window.STEPS=Object.assign(window.STEPS||{},{"ns-16e15965cf78":{"길":"두 삼각형이 닮음임을 보이고 비례식을 세워 이차방정식으로 BE를 구한다","단계":[{"제목":"닮음 관계 찾기","힌트":"∠A=∠D=∠CPE이고 이등변삼각형이라면?","식":[],"설명":"삼각형 ABE와 PBA는 이등변삼각형이며 ∠PAB=∠AEB이므로 두 삼각형은 닮음이다.","확인":null,"스킬":"S1"},{"제목":"비례식 세우기","고비":true,"힌트":"BE=x, PA=x-2라 하면 비례식은?","식":["$x:2=2:(x-2)$"],"설명":"닮음비로 비례식을 세운다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀기","힌트":"x²-2x-4=0을 근의 공식으로 풀면?","식":["$x^2-2x-4=0$","$x=1\\pm\\sqrt5$"],"설명":"근의 공식으로 풀면 x=1±√5이다.","확인":null,"스킬":"A6"},{"제목":"조건에 맞는 값 택하기","힌트":"x>0이므로 BE는?","식":["$x=1+\\sqrt5$"],"설명":"x>0이므로 BE=1+√5이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-1f3ccc0140fc":{"길":"a1을 구하고 역수의 소수부분으로 a2를 구해 주기 2를 찾아 100개의 합을 계산한다","단계":[{"제목":"a1 구하기","힌트":"2<√6<3이므로 소수부분은?","식":["$a_{1}=\\sqrt{6}-2$"],"설명":"√6의 정수부분 2를 빼 소수부분을 구한다.","확인":null,"스킬":"N7"},{"제목":"a2 구하기","힌트":"1/a1을 유리화하면?","식":["$\\frac{1}{\\sqrt{6}-2}=\\frac{\\sqrt{6}+2}{2}$"],"설명":"유리화한 값의 소수부분 a2=(√6-2)/2를 얻는다.","확인":null,"스킬":"N6"},{"제목":"a3에서 주기 확인하기","고비":true,"힌트":"1/a2를 유리화하면 다시 a1이 나올까?","식":["$\\frac{2}{\\sqrt{6}-2}=\\sqrt{6}+2\\Rightarrow a_{3}=\\sqrt{6}-2$"],"설명":"a3=a1이 되어 항이 두 개씩 반복되는 주기가 확인된다.","확인":null,"스킬":"P7"},{"제목":"100개 항의 합 세우기","힌트":"a1과 a2가 각각 몇 번씩 나올까?","식":["$50(\\sqrt{6}-2)+50\\left(\\frac{\\sqrt{6}-2}{2}\\right)=-150+75\\sqrt{6}$"],"설명":"a1, a2가 각 50번씩 더해져 -150+75√6이 된다.","확인":null,"스킬":"P6"},{"제목":"q-p 계산하기","힌트":"p=-150, q=75라면?","식":["$q-p=75-(-150)=225$"],"설명":"q-p=225이다.","확인":"225","스킬":"A3"}],"fb":"fig/ns/"},"ns-85b61aa86371":{"길":"√6의 범위로 [x]를 구하고 분모를 유리화한 뒤 범위를 좁혀 가우스값을 구한다","단계":[{"제목":"[x] 구하기","힌트":"√6은 몇과 몇 사이일까?","식":["$2<\\sqrt6<3$","$1<x<2$"],"설명":"2²<6<3²이므로 2<√6<3이고 x=√6-1은 1과 2 사이이므로 [x]=1이다.","확인":"1","스킬":"N7"},{"제목":"분모 유리화하기","힌트":"1/(√6-2)의 분모를 유리화하면?","식":["$\\frac1{\\sqrt6-2}=\\frac{\\sqrt6+2}2$"],"설명":"분모, 분자에 √6+2를 곱해 유리화한다.","확인":null,"스킬":"N6"},{"제목":"범위를 좁혀 가우스값 구하기","고비":true,"힌트":"√6+2는 몇과 몇 사이일까?","식":["$4<\\sqrt6+2<5$","$2<\\frac{\\sqrt6+2}2<3$"],"설명":"2<√6<3이므로 4<√6+2<5이고 2로 나누면 2와 3 사이이므로 가우스값은 2이다.","확인":"2","스킬":"N7"}],"fb":"fig/ns/"},"ns-441425e4be31":{"길":"넓이가 최대가 되는 점 P의 위치를 기하학적으로 찾아 피타고라스로 BP를 구한다","단계":[{"제목":"넓이 최대 조건 찾기","고비":true,"힌트":"밑변 AB가 고정일 때 높이가 최대가 되려면 점 P는 어디에 있어야 할까?","식":[],"설명":"삼각형 ABP의 넓이가 최대가 되려면 점 P에서 직선 OA까지의 거리(높이)가 최대여야 하므로, 반지름 OP가 OA와 수직일 때이다.","확인":null,"스킬":"S2"},{"제목":"OP=4, ∠BOP=90° 확인하기","힌트":"원의 반지름은 모두 같으므로 OP는?","식":["$\\overline{OP}=4,\\ \\angle BOP=90^{\\circ}$"],"설명":"P는 원 위의 점이므로 OP=4이고, 이때 ∠BOP=90°이다.","확인":null,"스킬":"S13"},{"제목":"BP 구하기","힌트":"직각삼각형 OBP에서 피타고라스 정리를 쓰면?","식":["$\\overline{BP}^2=3^2+4^2=25$","$\\overline{BP}=5$"],"설명":"직각삼각형 OBP에서 BP²=OB²+OP²=25이므로 BP=5이다.","확인":"5","스킬":"S3"},{"제목":"cosθ 구하기","힌트":"cosθ=OB/BP는?","식":["$\\cos\\theta=\\frac{3}{5}$"],"설명":"직각삼각형 OBP에서 cosθ=OB/BP=3/5이다.","확인":"3/5","스킬":"S6"}],"fb":"fig/ns/"},"ns-462222fb033e":{"길":"반지름을 1로 두고 부채꼴 내접원의 반지름과 호·현의 중점을 잇는 원의 반지름을 각각 구해 비를 낸다","단계":[{"제목":"직각삼각형에서 삼각비 구하기","힌트":"AB가 지름이므로 ∠APB는?","식":["$\\overline{AP}=8,\\ \\overline{BP}=6$","$\\cos\\theta=\\frac{4}{5},\\ \\sin\\theta=\\frac{3}{5}$"],"설명":"AB가 지름이므로 ∠APB=90°이고, ∠BAP=θ라 하면 직각삼각형에서 cosθ, sinθ를 구한다.","확인":null,"스킬":"S6"},{"제목":"중심각을 원주각의 2배로 놓기","힌트":"∠BOP은 ∠BAP의 몇 배일까?","식":["$\\angle BOP=2\\theta$"],"설명":"호 BP에 대한 중심각은 원주각의 2배이므로 ∠BOP=2θ이다.","확인":null,"스킬":"S5"},{"제목":"부채꼴 내접원의 반지름 r1 구하기","고비":true,"힌트":"반지름을 1로 두면 내접원 중심까지 거리는 r1/sinθ, 이를 반지름 관계식에 넣으면?","식":["$r_{1}+\\frac{r_{1}}{\\sin\\theta}=1$","$r_{1}=\\frac{3}{8}$"],"설명":"반지름 1인 부채꼴 OBP에 내접하는 원의 중심까지 거리가 r1/sinθ이므로 r1+r1/sinθ=1에서 r1=3/8을 얻는다.","확인":null,"스킬":"S13"},{"제목":"현 AP까지의 거리 구하기","힌트":"중심 O에서 현 AP까지의 거리는 sinθ와 어떤 관계일까?","식":["$\\overline{OD}=\\sin\\theta=\\frac{3}{5}$"],"설명":"중심에서 현 AP에 내린 수선의 발을 D라 하면 OD=sinθ이다.","확인":null,"스킬":"S13"},{"제목":"r2 구하기","힌트":"호 AP의 중점과 현의 중점을 잇는 지름의 길이는?","식":["$2r_{2}=1-\\overline{OD}$","$r_{2}=\\frac{1}{5}$"],"설명":"호의 중점(중심에서 거리 1인 점)에서 현의 중점(중심에서 거리 sinθ인 점)까지가 지름이므로 2r2=1-sinθ에서 r2=1/5이다.","확인":null,"스킬":"S13"},{"제목":"비율 계산하기","힌트":"r1/r2를 계산하면?","식":["$\\frac{r_{1}}{r_{2}}=\\frac{3/8}{1/5}=\\frac{15}{8}$"],"설명":"두 값을 나누면 r1/r2=15/8이다.","확인":"15/8","스킬":"S13"}],"fb":"fig/ns/"},"ns-225671cb6141":{"길":"부피 차이를 식으로 세우고 두 할인 조건을 순서대로 적용해 최종 금액을 구한다","단계":[{"제목":"부피 차이를 식으로 나타내기","힌트":"주문한 부피와 배달된 부피의 차는 어떻게 계산할까?","식":["$10a^{2}-10(a+3)(a-3)=10a^{2}-10(a^{2}-9)=90$"],"설명":"곱셈공식으로 전개하면 부피가 90cm³만큼 줄어든 것을 알 수 있다.","확인":"90","스킬":"C7"},{"제목":"할인 조건을 모두 적용하기","고비":true,"힌트":"1cm³당 200원 할인에 더해 70cm³ 이상 차이 나는 추가 할인까지 넣으면?","식":["$90\\times200+5000=23000$"],"설명":"부피 차이가 70cm³ 이상이므로 추가 할인 5000원까지 더해 총 할인은 23000원이다.","확인":"23000","스킬":"A2"},{"제목":"실제 지불 금액 구하기","힌트":"주문 가격에서 할인 금액을 빼면?","식":["$40000-23000=17000$"],"설명":"따라서 실제로 지불할 금액은 17000원이다.","확인":"17000","스킬":"A2"}],"fb":"fig/ns/"},"ns-b3267ae65c01":{"길":"변경 전후 면적을 각각 식으로 세운 뒤 전개해서 차를 구한다","단계":[{"제목":"처음 면적 A 세우기","힌트":"스탠딩석과 지정석의 넓이를 더하면?","식":["$A=x(2y+3z)=2xy+3xz$"],"설명":"두 구역의 넓이를 더해 A를 세운다.","확인":null,"스킬":"C7"},{"제목":"변경된 면적 B 세우기","고비":true,"힌트":"가로 10 늘리고 세로 7 줄인 것과 세로만 15 늘린 것을 식으로 쓰면?","식":["$B=(x+10)(2y-7)+x(3z+15)$","$=2xy-7x+20y-70+3xz+15x$","$=2xy+8x+20y+3xz-70$"],"설명":"바뀐 가로·세로를 대입해 전개하고 동류항을 정리한다.","확인":null,"스킬":"C7"},{"제목":"A-B 계산하기","힌트":"두 식을 빼면 어떤 항이 남을까?","식":["$A-B=(2xy+3xz)-(2xy+8x+20y+3xz-70)$","$=-8x-20y+70$"],"설명":"공통항이 사라지고 -8x-20y+70이 남는다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-159a935b2614":{"길":"다섯 보기를 곱셈공식·절댓값·텔레스코핑으로 하나씩 판별해 개수를 센다","단계":[{"제목":"ㄱ, ㄹ 판별하기","힌트":"곱셈공식과 제곱차 공식을 그대로 적용하면?","식":["$(2x-\\frac13)^2=4x^2-\\frac43x+\\frac19$","$1001^2-999^2=4\\times1000=4000$"],"설명":"곱셈공식을 그대로 적용하면 ㄱ, ㄹ은 옳다.","확인":null,"스킬":"A3"},{"제목":"ㄴ 판별하기","고비":true,"힌트":"-(x+1)²과 (-x-1)²은 같을까?","식":["$-(x+1)^2=-(-x-1)^2$"],"설명":"좌변은 항상 0 이하, 우변은 항상 0 이상이므로 등호가 성립하지 않아 ㄴ은 옳지 않다.","확인":null,"스킬":"A3"},{"제목":"ㄷ 판별하기","힌트":"(1-1/3)을 곱해 텔레스코핑으로 정리하면?","식":["$\\frac32(1-\\frac13)(1+\\frac13)(1+\\frac1{3^2})(1+\\frac1{3^4})(1+\\frac1{3^8})=\\frac32(1-\\frac1{3^{16}})$"],"설명":"1-1/3을 곱해 차례로 소거하면 값이 2/3이 아닌 3/2이므로 ㄷ은 옳지 않다.","확인":null,"스킬":"A1"},{"제목":"옳은 것 개수 세기","힌트":"ㄱ, ㄴ, ㄷ, ㄹ, ㅁ 중 옳지 않은 것을 제외하면?","식":[],"설명":"ㄴ과 ㄷ만 옳지 않으므로 옳은 것은 ㄱ, ㄹ, ㅁ로 모두 3개다.","확인":"3","스킬":"C3"}],"fb":"fig/ns/"},"ns-26dbeffde1e1":{"길":"숫자를 기준값 근처의 합과 차로 바꿔 합차 공식으로 상쇄시킨다","단계":[{"제목":"숫자를 기준값 근처로 바꿔보기","힌트":"1670과 1684를 1677을 기준으로 나타내면?","식":["$1670=1677-7,\\ 1684=1677+7$"],"설명":"두 수를 1677을 중심으로 한 차와 합의 꼴로 바꿔 쓴다.","확인":null,"스킬":"N6"},{"제목":"합차 공식으로 분자 정리하기","고비":true,"힌트":"$(1677-7)(1677+7)+7^2$을 계산하면?","식":["$(1677-7)(1677+7)+7^{2}=1677^{2}-7^{2}+7^{2}=1677^{2}$"],"설명":"합차 공식을 적용하면 -7²과 +7²이 상쇄되어 1677²만 남는다.","확인":null,"스킬":"A2"},{"제목":"분모로 나눠 정리하기","힌트":"1677²을 1677로 나누면?","식":["$\\frac{1677^{2}}{1677}=1677$"],"설명":"약분하면 값은 1677이다.","확인":"1677","스킬":"N6"}],"fb":"fig/ns/"},"ns-00d4163e4f8a":{"길":"호의 중점으로 같은 각을 표시하고, 두 삼각형의 외각 성질로 이등변삼각형을 확인한다","단계":[{"제목":"호의 중점으로 같은 각 표시하기","힌트":"D, E가 호의 중점이면 어떤 각들이 같아질까?","식":["$\\angle ACD=\\angle CED=a$","$\\angle BCE=\\angle CDE=b$"],"설명":"호 AD=DC, BE=EC이므로 원주각이 같음을 이용해 같은 크기의 각을 a, b로 놓는다.","확인":null,"스킬":"S5"},{"제목":"△CDM의 외각으로 ∠CMN 구하기","힌트":"삼각형의 외각은 두 내각의 합과 같다는 성질을 쓰면?","식":["$\\angle CMN=a+b$"],"설명":"△CDM에서 ∠MCD=a, ∠CDM=b이므로 외각 ∠CMN=a+b이다.","확인":null,"스킬":"S10"},{"제목":"△CEN의 외각으로 ∠CNM 구하기","고비":true,"힌트":"같은 방법으로 △CEN에서는?","식":["$\\angle CNM=a+b$"],"설명":"△CEN에서도 외각의 성질로 ∠CNM=a+b이므로 ∠CMN=∠CNM이다.","확인":null,"스킬":"S10"},{"제목":"이등변삼각형으로 각 구하기","힌트":"△MNC가 이등변삼각형이므로 ∠CNM은?","식":["$\\angle CNM=\\frac12\\times(180^{\\circ}-41^{\\circ})=69.5^{\\circ}$"],"설명":"∠MCN=41°이고 ∠CMN=∠CNM이므로 나머지 두 각을 반씩 나눠 ∠CNM을 구한다.","확인":"69.5","스킬":"S10"}],"fb":"fig/ns/"},"ns-01ba5c0b12d7":{"길":"세 직각삼각형에서 같은 방법(빗변×cos30°)을 차례로 반복해 OD를 구한다","단계":[{"제목":"OB의 길이 구하기","힌트":"직각삼각형 OAB에서 코사인을 쓰면?","식":["$\\overline{OB}=24\\cos30^\\circ=12\\sqrt3$"],"설명":"직각삼각형 OAB에서 OB=OA·cos30°이다.","확인":null,"스킬":"S6"},{"제목":"OC의 길이 구하기","힌트":"같은 방법으로 OC는?","식":["$\\overline{OC}=12\\sqrt3\\cos30^\\circ=18$"],"설명":"직각삼각형 OBC에서 OC=OB·cos30°=18이다.","확인":"18","스킬":"S6"},{"제목":"OD의 길이 구하기","고비":true,"힌트":"같은 방법을 한 번 더 반복하면?","식":["$\\overline{OD}=18\\cos30^\\circ=9\\sqrt3$"],"설명":"직각삼각형 OCD에서 OD=OC·cos30°=9√3이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-0285578506f8":{"길":"안쪽 정사각형 EFGH의 넓이로 변의 길이를 구하고, 도형 ②가 정사각형 그대로임을 알아본다","단계":[{"제목":"EFGH 넓이 구하기","힌트":"정사각형 ABCD의 넓이가 8이면 안쪽 정사각형 EFGH의 넓이는?","식":["$\\square ABCD=8\\Rightarrow \\square EFGH=4$"],"설명":"각 변의 중점을 이은 정사각형 EFGH의 넓이는 원래 넓이의 절반이다.","확인":null,"스킬":"S1"},{"제목":"EFGH 한 변의 길이 구하기","힌트":"넓이가 4인 정사각형의 한 변은?","식":["$\\overline{EH}=\\overline{EF}=2$"],"설명":"넓이 4인 정사각형의 한 변의 길이는 2이다.","확인":"2","스킬":"N8"},{"제목":"도형 ②와 EFGH를 맞춰 보기","고비":true,"힌트":"<보기>의 그림 ②는 어떤 정사각형과 같은 모양일까?","식":[],"설명":"그림 ②는 정사각형 EFGH를 그대로 오려낸 모양이므로 네 변이 모두 2로 같다.","확인":null,"스킬":"C3"},{"제목":"둘레의 길이 확인하기","힌트":"한 변이 2인 정사각형의 둘레는?","식":["$2\\times4=8$"],"설명":"둘레의 길이가 8인 유리수이므로 ②가 답이다.","확인":"8","스킬":"C3"}],"fb":"fig/ns/"},"ns-03f7a875318c":{"길":"나머지 두 변을 구한 뒤 넓이를 세 삼각형의 합으로 나타내 반지름 r을 구한다","단계":[{"제목":"AC, AB의 길이 구하기","힌트":"직각삼각형에서 tan, cos을 쓰면?","식":["$\\overline{AC}=3\\tan60^\\circ=3\\sqrt3,\\ \\overline{AB}=\\frac{3}{\\cos60^\\circ}=6$"],"설명":"직각삼각형 ABC의 나머지 두 변을 구한다.","확인":null,"스킬":"S6"},{"제목":"넓이를 세 삼각형의 합으로 나타내기","고비":true,"힌트":"내접원의 반지름을 r이라 하면 △ABC는 어떤 세 삼각형의 합일까?","식":["$\\triangle ABC=\\triangle IAB+\\triangle IBC+\\triangle IAC$"],"설명":"내심 I에서 세 변에 내린 수선의 길이가 모두 r이므로 이렇게 나눌 수 있다.","확인":null,"스킬":"S8"},{"제목":"넓이 방정식 세우기","힌트":"양변의 넓이를 식으로 쓰면?","식":["$\\frac{1}{2}\\times3\\times3\\sqrt3=\\frac{1}{2}r(6+3+3\\sqrt3)$"],"설명":"왼쪽은 직각삼각형의 넓이, 오른쪽은 세 삼각형 넓이의 합이다.","확인":null,"스킬":"S8"},{"제목":"r에 대해 풀어 유리화하기","힌트":"방정식을 정리하고 분모를 유리화하면?","식":["$(9+3\\sqrt3)r=9\\sqrt3$","$r=\\frac{3\\sqrt3}{3+\\sqrt3}=\\frac{3\\sqrt3-3}{2}$"],"설명":"r을 구하고 분모를 유리화해 정리한다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-061a926d20e9":{"길":"닮음비 1:3에서 부피비 1:27을 구해 남은 부피를 전체 부피의 분수로 계산한다","단계":[{"제목":"닮음비와 부피비 구하기","힌트":"높이가 1/3인 닮은 사각뿔의 부피비는?","식":["$1^{3}:3^{3}=1:27$"],"설명":"닮음비가 1:3이므로 부피비는 1:27이다.","확인":null,"스킬":"S1"},{"제목":"원래 사각뿔의 부피 구하기","힌트":"밑넓이×높이×1/3을 계산하면?","식":["$\\frac{1}{3}\\times\\sqrt{18}\\times\\sqrt{20}\\times\\sqrt{45}=\\frac{1}{3}\\times3\\sqrt{2}\\times2\\sqrt{5}\\times3\\sqrt{5}=30\\sqrt{2}$"],"설명":"근호를 정리해 원래 사각뿔의 부피를 구한다.","확인":null,"스킬":"N1"},{"제목":"남은 부피 계산하기","고비":true,"힌트":"전체에서 27분의 1을 잘라냈으므로 남은 비율은?","식":["$\\frac{26}{27}\\times30\\sqrt{2}=\\frac{260\\sqrt{2}}{9}$"],"설명":"26/27을 곱해 남은 입체도형의 부피를 구한다.","확인":null,"스킬":"A9"}],"fb":"fig/ns/"},"ns-06b1e9ec39d3":{"길":"수선의 발을 잡아 합동으로 ∠AOB를 구하고 부채꼴에서 삼각형을 빼 넓이를 구한다","단계":[{"제목":"수선의 발 H를 잡아 OH 구하기","고비":true,"힌트":"접었을 때 호 AB가 중심 O를 지나므로 OH는 OA의 절반일까?","식":["$\\overline{OH}=\\frac12\\times6=3$"],"설명":"접힌 호가 중심을 지나므로 O에서 AB까지 거리 OH는 반지름의 절반이 된다.","확인":"3","스킬":"S2"},{"제목":"∠AOH 구하기","힌트":"OA:OH=2:1인 직각삼각형에서 각은?","식":["$\\overline{OA}:\\overline{OH}=2:1\\Rightarrow\\angle OAH=30^{\\circ},\\ \\angle AOH=60^{\\circ}$"],"설명":"직각삼각형 OAH에서 변의 비로 각을 구한다.","확인":null,"스킬":"S6"},{"제목":"∠AOB 구하기","힌트":"△AOH≡△BOH(RHS 합동)이므로 ∠AOB는?","식":["$\\angle AOB=2\\times60^{\\circ}=120^{\\circ}$"],"설명":"두 삼각형이 합동이므로 ∠BOH=∠AOH=60°이고, 이를 더해 ∠AOB를 구한다.","확인":"120","스킬":"S2"},{"제목":"부채꼴과 삼각형의 넓이 구하기","힌트":"부채꼴 AOB와 △AOB의 넓이는 각각?","식":["$\\pi\\times6^2\\times\\frac{120}{360}=12\\pi$","$\\triangle AOB=\\frac12\\times6\\times6\\times\\sin60^{\\circ}=9\\sqrt3$"],"설명":"부채꼴의 넓이 공식과 두 변과 끼인각으로 삼각형의 넓이를 각각 구한다.","확인":null,"스킬":"S8"},{"제목":"색칠한 부분의 넓이 구하기","힌트":"부채꼴에서 삼각형을 빼면?","식":["$12\\pi-9\\sqrt3$"],"설명":"부채꼴의 넓이에서 삼각형의 넓이를 빼서 색칠한 부분의 넓이를 구한다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-07c3d56a99a0":{"길":"다섯 진술을 현·수선·합동에 관한 원의 성질로 하나씩 따진다","단계":[{"제목":"① 판별하기","힌트":"OA, OC는 어떤 선분일까?","식":[],"설명":"OA, OC는 모두 원의 반지름이므로 OA=OC이다. ①은 옳다.","확인":null,"스킬":"S5"},{"제목":"② 판별하기","힌트":"중심에서 현에 내린 수선은 현을 어떻게 나눌까?","식":[],"설명":"수선의 발은 현을 수직이등분하므로 AM=(1/2)AB이다. ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"③ 판별하기","힌트":"OM=ON이면 두 현의 길이는?","식":[],"설명":"중심에서 같은 거리에 있는 두 현은 길이가 같으므로 AB=CD이다. ③은 옳다.","확인":null,"스킬":"S5"},{"제목":"④ 판별하기","고비":true,"힌트":"OM과 DN이 항상 같은 길이라고 할 수 있을까?","식":[],"설명":"OM과 DN의 길이는 주어진 조건만으로는 같을 수도 다를 수도 있으므로 ④는 항상 옳지는 않다.","확인":null,"스킬":"C3"},{"제목":"⑤ 판별하고 정답 정하기","힌트":"△OAM과 △OCN이 RHS 조건으로 합동인지 확인하면?","식":[],"설명":"OA=OC, ∠OMA=∠ONC=90°, OM=ON이므로 RHS합동이다. ⑤도 옳으므로 옳지 않은 것은 ④이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-0b9d81f0ce1a":{"길":"그래프의 볼록 방향, 축의 위치, y절편의 위치를 차례로 읽는다","단계":[{"제목":"a의 부호 정하기","힌트":"그래프가 아래로 볼록할 때 a의 부호는?","식":[],"설명":"그래프가 아래로 볼록하므로 a>0이다.","확인":null,"스킬":"G7"},{"제목":"b의 부호 정하기","고비":true,"힌트":"축이 y축보다 오른쪽에 있으면 ab의 부호는?","식":["$ab<0$"],"설명":"축이 y축의 오른쪽에 있으므로 ab<0이고, a>0이므로 b<0이다.","확인":null,"스킬":"G7"},{"제목":"c의 부호 정해 답 확정하기","힌트":"그래프가 y축과 원점보다 위에서 만나면 c는?","식":[],"설명":"y축과 원점보다 위쪽에서 만나므로 c>0이다. 따라서 a>0, b<0, c>0이다.","확인":null,"스킬":"G7"}],"fb":"fig/ns/"},"ns-0d3c7f79913f":{"길":"책을 10권 이상 읽은 학생을 산점도에서 찾아 국어 성적의 평균을 계산한다","단계":[{"제목":"조건을 만족하는 학생 찾기","힌트":"책을 10권 이상 읽은 학생은 산점도에서 어디에 있을까?","식":[],"설명":"책 10권 이상인 점은 색칠한 부분에 있으며 4명이다.","확인":null,"스킬":"G6"},{"제목":"평균 계산하기","고비":true,"힌트":"네 학생의 국어 성적 70,80,80,90의 평균은?","식":["$\\frac{70+80+80+90}{4}=80$"],"설명":"네 학생의 국어 성적을 더해 평균을 구하면 80점이다.","확인":"80","스킬":"N6"}],"fb":"fig/ns/"},"ns-0e66b2a062a5":{"길":"내접사각형의 외각 성질과 접선과 현이 이루는 각을 각 보기에 적용해 참, 거짓을 가린다","단계":[{"제목":"ㄱ 판별하기","힌트":"사각형 ABCD가 원 O'에 내접하면 ∠BAP와 ∠BCD는 어떤 관계일까?","식":["$\\angle BAP=\\angle BCD=65^\\circ$"],"설명":"내접사각형에서 외각은 이웃한 내각의 대각과 같으므로 ∠BAP=∠BCD=65°이고, 접선과 현이 이루는 각의 성질에 의해 ∠BPS=∠BAP=65°이므로 ㄱ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ,ㄷ 판별하기","힌트":"∠ABP와 ∠ADC의 관계는 어떨까?","식":["$\\angle ABP=\\angle ADC=75^\\circ$"],"설명":"같은 방법으로 ∠APT=∠ABP=75°이므로 ㄴ이 주장한 65°는 옳지 않고, ∠BAP=65°이므로 ㄷ이 주장한 75°도 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 판별하고 결론 내리기","고비":true,"힌트":"∠BCD와 ∠BPS가 엇각으로 같으면 어떤 결론이 나올까?","식":["$\\angle BCD=\\angle BAP=\\angle BPS=65^\\circ$"],"설명":"세 각이 모두 65°로 같아 엇각 관계가 성립하므로 TS∥CD가 되어 ㄹ도 옳다. 따라서 옳은 것은 ㄱ, ㄹ이다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-0e96d833f29c":{"길":"삼각형 합동 증명의 빈칸을 반지름·수선·이등분 성질을 그대로 적용해 채운다","단계":[{"제목":"(가) 빈칸 채우기","힌트":"OA와 OC는 같은 원에서 무엇에 해당할까?","식":["$\\overline{OA}=\\overline{OC}$"],"설명":"OA, OC는 모두 원 O의 반지름이므로 같다.","확인":null,"스킬":"S5"},{"제목":"(나) 빈칸 채우기","힌트":"OM, ON이 현에 내린 수선이면 그 각은 몇 도일까?","식":["$\\angle OMA=\\angle ONC=90^\\circ$"],"설명":"원의 중심에서 현에 내린 수선이므로 두 각은 모두 직각이다.","확인":null,"스킬":"S5"},{"제목":"(다) 빈칸 채우기","고비":true,"힌트":"RHS 합동인 두 직각삼각형에서 AM=CN이면 AB, CD는 AM, CN의 몇 배일까?","식":["$\\overline{AB}=2\\overline{AM},\\ \\overline{CD}=2\\overline{CN}$"],"설명":"원의 중심에서 현에 내린 수선은 그 현을 이등분하므로 AB, CD는 각각 AM, CN의 2배이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-0ef8d88b1a95":{"길":"이동을 부호 있는 제곱의 합으로 쓰고 네 개씩 묶어 계산한다","단계":[{"제목":"이동을 부호 있는 수로 나타내기","힌트":"오른쪽은 +, 왼쪽은 -로 나타내면 n번째 날의 이동은?","식":["$n번째\\ 날의\\ 이동=\\pm n^2$"],"설명":"짝수 번째는 부호가 번갈아 바뀌므로 이동을 +, -로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"네 개씩 묶어 차로 정리하기","고비":true,"힌트":"1²+2²-3²-4²처럼 네 항씩 묶으면 어떤 규칙이 보일까?","식":["$(1^2-3^2)+(2^2-4^2)+(5^2-7^2)+(6^2-8^2)+\\cdots+(17^2-19^2)+18^2$"],"설명":"네 항씩 묶어 차의 꼴로 바꾸면 계산이 간단해진다.","확인":null,"스킬":"A2"},{"제목":"각 묶음 계산하기","힌트":"(a²-b²)=(a+b)(a-b)로 계산하면 각 묶음은?","식":["$-2(1+2+3+4+\\cdots+16+17+19)+18^2$"],"설명":"차의 공식으로 각 묶음을 정리해 하나의 식으로 합친다.","확인":null,"스킬":"A2"},{"제목":"총합 계산하기","힌트":"괄호 안의 합과 18²을 계산하면?","식":["$-2\\times172+324=-344+324=-20$"],"설명":"계산하면 -20이므로 처음 위치에서 왼쪽으로 20m 떨어져 있다.","확인":"20","스킬":"N6"}],"fb":"fig/ns/"},"ns-0f7c740dca32":{"길":"접어서 생기는 합동인 선분과 각 넓이 관계를 선지마다 확인한다","단계":[{"제목":"①, ③ 선지 판별하기","힌트":"접어서 겹친 부분은 서로 합동이므로 FH와 EC, 삼각형 ABH와 EBH는?","식":["$\\overline{FH}=\\overline{DH}=\\overline{EC}$"],"설명":"접었을 때 겹치는 선분과 삼각형은 서로 같으므로 ①, ③은 옳다.","확인":null,"스킬":"S10"},{"제목":"② CG의 길이 구하기","고비":true,"힌트":"AB=EB=b, EC=FG=DG=a-b를 이용하면 CG는?","식":["$\\overline{GC}=b-(a-b)=-a+2b=2b-a$"],"설명":"정사각형 변의 관계로 CG를 구하면 2b-a로 ②는 옳다.","확인":null,"스킬":"S10"},{"제목":"④ 사각형 FECG의 넓이 구하기","힌트":"(a-b)(-a+2b)를 전개하면?","식":["$(a-b)(-a+2b)=-a^2+3ab-2b^2$"],"설명":"두 변을 곱해 전개하면 ④도 옳다.","확인":null,"스킬":"A2"},{"제목":"⑤ 사각형 HBCG의 넓이 구해 비교하기","힌트":"HBCG의 넓이를 직접 계산하면 FECG의 몇 배일까?","식":["$ab-\\frac12b^2-\\frac12(a-b)^2=-\\frac12a^2+2ab-b^2$"],"설명":"실제로 계산하면 HBCG의 넓이는 FECG의 3.5배가 아니므로 ⑤가 옳지 않다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-175103613254":{"길":"잘라낸 도형의 넓이를 구하고 넓이 보존 조건으로 방정식을 세워 푼다","단계":[{"제목":"[그림1] 남은 부분의 넓이 구하기","힌트":"직사각형 넓이에서 두 도형을 빼면?","식":["$4x\\times3x-\\frac12\\times6\\times4-\\frac12(2x+3x)\\times4=12x^2-10x-12$"],"설명":"직사각형에서 잘라낸 두 도형의 넓이를 뺀다.","확인":null,"스킬":"S12"},{"제목":"넓이가 보존됨을 이용해 방정식 세우기","고비":true,"힌트":"[그림1]과 [그림2]의 넓이가 같다는 것을 식으로 쓰면?","식":["$12x^2-10x-12=\\frac12\\{(2x+1)+(x+1)\\}d$"],"설명":"잘라 붙여도 넓이는 변하지 않으므로 두 넓이를 같다고 놓는다.","확인":null,"스킬":"S12"},{"제목":"인수분해해 d로 정리하기","힌트":"양변을 인수분해해 정리하면?","식":["$2(2x-3)(3x+2)=\\frac12(3x+2)d$"],"설명":"양변을 인수분해하면 (3x+2)로 약분할 수 있다.","확인":null,"스킬":"A3"},{"제목":"d 구하기","힌트":"(3x+2)를 약분하면?","식":["$d=2\\times2(2x-3)=8x-12$"],"설명":"약분해 정리하면 평행한 두 변 사이의 거리는 8x-12다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-195cacd47730":{"길":"근의 공식 유도 과정을 순서대로 재현하며 각 빈칸과 대조한다","단계":[{"제목":"양변에 4a 곱하기","힌트":"ax²+bx+c=0의 양변에 4a를 곱하면?","식":["$4a^2x^2+4abx+4ac=0$"],"설명":"(가)는 4a로 맞다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식 만들기 위해 더할 값 확인하기","고비":true,"힌트":"4a²x²+4abx에 무엇을 더해야 완전제곱식이 될까?","식":["$4a^2x^2+4abx+b^2=-4ac+b^2$"],"설명":"더해야 할 값은 b²인데 (나)는 b라 되어 있으므로 옳지 않다.","확인":null,"스킬":"A6"},{"제목":"나머지 빈칸 확인하기","힌트":"(2ax+b)²=b²-4ac에서 (다),(라),(마)는?","식":["$2ax+b=\\pm\\sqrt{b^2-4ac}$","$x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}$"],"설명":"(다)=2ax+b, (라)=-b, (마)의 공식도 맞으므로 옳지 않은 것은 (나)뿐이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-1aa737cc9119":{"길":"직각삼각형 변으로 다섯 삼각비 정의를 하나씩 확인한다","단계":[{"제목":"①, ② 정의 확인하기","힌트":"직각삼각형에서 sin A, cos A의 정의는?","식":["$\\sin A=\\dfrac{a}{b},\\ \\cos A=\\dfrac{c}{b}$"],"설명":"빗변 b에 대해 각 A의 대변 a, 인접변 c로 sin A, cos A를 정의한다.","확인":null,"스킬":"S6"},{"제목":"③, ④ 여각 관계로 비교하기","힌트":"∠A와 ∠C는 서로 여각이므로 어떤 관계일까?","식":["$\\sin A=\\cos C=\\dfrac{a}{b},\\ \\cos A=\\sin C=\\dfrac{c}{b}$"],"설명":"직각삼각형에서 두 예각은 서로 여각이므로 sin A=cos C, cos A=sin C가 성립한다.","확인":null,"스킬":"S6"},{"제목":"⑤ tan A × tan C 계산하기","고비":true,"힌트":"tan A와 tan C를 곱하면 변이 어떻게 소거될까?","식":["$\\tan A\\times\\tan C=\\dfrac{a}{c}\\times\\dfrac{c}{a}=1$"],"설명":"tan A와 tan C를 곱하면 c와 a가 약분되어 1이 되므로, 2라고 한 ⑤가 옳지 않다.","확인":"1","스킬":"S6"}],"fb":"fig/ns/"},"ns-1ad83b49225d":{"길":"산점도에서 각 선지가 직접 읽을 수 있는 값인지 판단한다","단계":[{"제목":"선지별로 산점도에서 읽을 수 있는지 확인하기","힌트":"산점도로 평균·상관관계·특정 인원수는 읽을 수 있지만, 읽을 수 없는 것은?","식":[],"설명":"산점도에서는 개별 점의 위치는 읽을 수 있지만, 듣기와 말하기 점수의 차가 정확히 2점인 학생처럼 특정 변량을 짚어낼 근거가 없다.","확인":null,"스킬":"C3"},{"제목":"정답 선지 확정하기","고비":true,"힌트":"③이 다른 선지와 다른 이유는?","식":[],"설명":"산점도에서는 특정 변량(차가 2점인 경우)을 정확하게 짚어낼 수 없으므로 ③이 정답이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-1c4943453885":{"길":"접선의 길이·합동·사각형 각의 합·삼각비를 차례로 써서 다섯 선지를 확인한다","단계":[{"제목":"① 판별하기","힌트":"한 점에서 그은 두 접선의 길이는 어떤 관계일까?","식":["$\\overline{PT}=\\overline{PT'}=6$"],"설명":"원 밖의 한 점에서 그은 두 접선의 길이는 같으므로 PT=6이며 ①은 옳다.","확인":null,"스킬":"S5"},{"제목":"② 판별하기","힌트":"PT=PT', PO 공통, 두 각이 직각이면 어떤 합동일까?","식":["$\\triangle TPO\\equiv\\triangle T'PO\\ (RHS\\ 합동)$"],"설명":"접선과 반지름이 수직이므로 두 직각삼각형은 RHS합동이며 ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"③ 판별하기","힌트":"사각형 TPT'O의 내각의 합에서 ∠TPT'을 구하면?","식":["$\\angle TPT'=360^\\circ-(90^\\circ+120^\\circ+90^\\circ)=60^\\circ$"],"설명":"사각형의 내각의 합에서 ∠TPT'=60°이고, 합동이므로 이등분한 ∠TPO=30°이며 ③은 옳다.","확인":null,"스킬":"C7"},{"제목":"④ 판별하기","힌트":"직각삼각형 TPO에서 cos30°를 이용하면?","식":["$\\cos30^\\circ=\\frac{6}{\\overline{PO}}$"],"설명":"정리하면 PO=4√3이며 ④는 옳다.","확인":null,"스킬":"S6"},{"제목":"부채꼴 반지름 OT 구하기","고비":true,"힌트":"tan30°를 이용해 OT를 구하면?","식":["$\\tan30^\\circ=\\frac{\\overline{OT}}{6}$"],"설명":"정리하면 OT=2√3이다.","확인":null,"스킬":"S6"},{"제목":"⑤ 부채꼴 넓이 계산해 확인하기","힌트":"반지름 2√3, 중심각 120°인 부채꼴의 넓이는?","식":["$\\pi\\times(2\\sqrt{3})^2\\times\\frac{120^\\circ}{360^\\circ}=4\\pi$"],"설명":"실제 넓이는 4π인데 ⑤는 3π라 했으므로 ⑤가 옳지 않다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-1f3664d95190":{"길":"원래 그래프에서 a,b,c의 부호를 읽어 계수 자리가 바뀐 새 그래프의 개형을 정한다","단계":[{"제목":"a의 부호 정하기","힌트":"y=ax²-bx-c 그래프가 아래로 볼록하면 a는?","식":[],"설명":"그래프가 아래로 볼록하므로 a>0이다.","확인":null,"스킬":"G7"},{"제목":"b, c의 부호 정하기","고비":true,"힌트":"축이 y축의 왼쪽에 있고, 원점을 지나면 b, c는?","식":["$-ab>0\\ \\Rightarrow\\ b<0$","$-c=0\\ \\Rightarrow\\ c=0$"],"설명":"축이 y축 왼쪽에 있으므로 -ab>0에서 b<0이고, 그래프가 원점을 지나므로 c=0이다.","확인":null,"스킬":"G7"},{"제목":"새 함수의 개형 정하기","힌트":"y=bx²+cx+a에서 b<0, c=0, a>0이면 그래프는 어떤 모양일까?","식":[],"설명":"b<0이므로 위로 볼록하고, bc=0이므로 축은 y축(x=0)이며, a>0이므로 y축과 원점보다 위쪽에서 만난다.","확인":null,"스킬":"G4"},{"제목":"답 확정하기","힌트":"위 조건을 모두 만족하는 그래프는?","식":[],"설명":"위로 볼록하고 축이 y축이며 원점보다 위에서 y축과 만나는 그래프는 ②이다.","확인":null,"스킬":"G7"}],"fb":"fig/ns/"},"ns-1f94f7b7591e":{"길":"네 진술을 삼각비 정의와 동위각 관계로 하나씩 따져 개수를 센다","단계":[{"제목":"ㄱ, ㄴ 판별하기","힌트":"OA=OC=1이면 sin a°, tan a°는 어떤 값일까?","식":["$\\sin a^{\\circ}=\\dfrac{\\overline{AB}}{\\overline{OA}}=\\overline{AB}$","$\\tan a^{\\circ}=\\dfrac{\\overline{CD}}{\\overline{OC}}=\\overline{CD}$"],"설명":"반지름이 1이므로 OA=OC=1이 되어 ㄱ, ㄴ은 정의 그대로 성립한다.","확인":null,"스킬":"S6"},{"제목":"ㄷ 판별하기","힌트":"cos b°를 실제로 계산하면 AB일까, OB일까?","식":["$\\cos b^{\\circ}=\\dfrac{\\overline{AB}}{\\overline{OA}}=\\overline{AB}$"],"설명":"실제 cos b°의 값은 AB이므로, OB라고 한 ㄷ은 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"ㄹ 판별하기","고비":true,"힌트":"각 c°와 각 b°가 동위각으로 같다면 sin c°는?","식":["$c^{\\circ}=b^{\\circ}\\ (동위각)$","$\\sin c^{\\circ}=\\sin b^{\\circ}=\\dfrac{\\overline{OB}}{\\overline{OA}}=\\overline{OB}$"],"설명":"c°와 b°가 동위각으로 크기가 같으므로 sin c°=OB가 되어 ㄹ은 옳다.","확인":null,"스킬":"S10"},{"제목":"옳은 것의 개수 세기","힌트":"ㄱ, ㄴ, ㄹ이 옳으므로 개수는?","식":["$3$개"],"설명":"옳은 것은 ㄱ, ㄴ, ㄹ로 모두 3개다.","확인":"3","스킬":"P4"}],"fb":"fig/ns/"},"ns-203faa3059a0":{"길":"공통각과 접선-현 각으로 닮음을 찾고 비례식을 정리해 옳은 보기를 고른다","단계":[{"제목":"닮음인 두 삼각형 찾기","고비":true,"힌트":"△PTA와 △PBT에서 공통인 각과 같은 각을 찾으면?","식":["$\\angle P는\\ 공통,\\ \\angle PTA=\\angle PBT$"],"설명":"∠P가 공통이고 접선과 현이 이루는 각의 성질에 의해 ∠PTA=∠PBT이므로 두 삼각형은 AA닮음이다.","확인":null,"스킬":"S1"},{"제목":"비례식으로 정리하기","힌트":"닮음에서 나온 대응변의 비를 쓰면?","식":["$\\overline{PA}:\\overline{PT}=\\overline{PT}:\\overline{PB}$"],"설명":"닮음비를 그대로 쓰면 PA:PT=PT:PB가 성립하므로 옳은 것은 ①, ④이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-216e818ef756":{"길":"세 모둠의 평균, 편차의 합, 분산을 차례로 비교해 ㄱ~ㄹ 을 판정","단계":[{"제목":"세 모둠의 평균 구하기 (ㄱ)","힌트":"A, B, C 모둠의 평균은 각각 얼마인가","식":["A: $\\dfrac{3\\times2+4\\times2+5\\times2+6\\times2+7\\times2}{10}=5$","B: $\\dfrac{3\\times3+4\\times1+5\\times2+6\\times1+7\\times3}{10}=5$","C: $\\dfrac{3\\times1+4\\times2+5\\times4+6\\times2+7\\times1}{10}=5$"],"설명":"세 모둠 모두 학생이 10명이고 시청 시간의 평균이 5시간으로 같다. 따라서 ㄱ 은 옳다.","확인":"5","스킬":"P4"},{"제목":"편차의 합 구하기 (ㄴ)","힌트":"각 모둠에서 편차에 도수를 곱해 모두 더하면 얼마인가","식":["A: $(-2)\\times2+(-1)\\times2+0\\times2+1\\times2+2\\times2=0$","B: $(-2)\\times3+(-1)\\times1+0\\times2+1\\times1+2\\times3=0$","C: $(-2)\\times1+(-1)\\times2+0\\times4+1\\times2+2\\times1=0$"],"설명":"평균이 5 이므로 시청 시간 3, 4, 5, 6, 7 의 편차는 -2, -1, 0, 1, 2 이고, 편차에 도수를 곱해 더하면 세 모둠 모두 0 이다. 편차의 합은 어떤 자료에서도 항상 0 이므로 ㄴ 은 옳다.","확인":"0","스킬":"P4"},{"제목":"분산 비교로 ㄷ, ㄹ 판별","고비":true,"힌트":"평균 5 주위에 가장 몰린 모둠은 어디이고, B 와 C 중 분산이 큰 쪽은 어디인가","식":["A 분산: $\\dfrac{(-2)^2\\times2+(-1)^2\\times2+0^2\\times2+1^2\\times2+2^2\\times2}{10}=2$","B 분산: $\\dfrac{(-2)^2\\times3+(-1)^2\\times1+0^2\\times2+1^2\\times1+2^2\\times3}{10}=2.6$","C 분산: $\\dfrac{(-2)^2\\times1+(-1)^2\\times2+0^2\\times4+1^2\\times2+2^2\\times1}{10}=1.2$"],"설명":"자료가 평균 5 주위에 몰릴수록 분산과 표준편차가 작다. 분산은 A 가 2, B 가 2.6, C 가 1.2 이므로 표준편차가 가장 작은 모둠은 A 가 아니라 C 이고, B 의 분산은 C 의 분산보다 크다. 따라서 ㄷ 은 옳지 않고 ㄹ 은 옳으며, 옳은 것은 ㄱ, ㄴ, ㄹ 이다.","확인":null,"스킬":"C3"}]},"ns-2426f61620f0":{"길":"피타고라스 정리로 P, Q의 좌표를 구한 뒤 다섯 선지를 하나씩 확인한다","단계":[{"제목":"P, Q의 좌표 구하기","힌트":"AB=AQ=√2, AC=AP=√5이므로?","식":["$P(1-\\sqrt{5}),\\ Q(1+\\sqrt{2})$"],"설명":"피타고라스 정리로 구한 길이를 좌표로 옮긴다.","확인":null,"스킬":"S3"},{"제목":"①②④⑤ 선지 확인하기","힌트":"좌표, 거리를 각각 계산해 보면?","식":[],"설명":"①,②,④,⑤는 구한 좌표·거리와 그대로 일치해 옳다.","확인":null,"스킬":"N7"},{"제목":"③ 선지 확인하기","고비":true,"힌트":"P와 Q 사이에 유리수는 몇 개나 있을까?","식":[],"설명":"P와 Q 사이에는 유리수가 무수히 많으므로 '4개'라는 ③은 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-261dfe858b98":{"길":"그림에서 새 직사각형의 가로세로를 읽어 곱셈공식으로 넓이를 정리한다","단계":[{"제목":"새 직사각형의 가로세로 길이 읽기","힌트":"잘라 붙인 직사각형의 가로와 세로는 각각 얼마일까?","식":["가로$=a+b$, 세로$=a-b$"],"설명":"그림에서 새로 만든 직사각형의 가로는 a+b, 세로는 a-b임을 읽을 수 있다.","확인":null,"스킬":"C7"},{"제목":"넓이를 곱셈공식으로 정리하기","고비":true,"힌트":"$(a+b)(a-b)$를 전개하면?","식":["$(a-b)(a+b)=a^{2}-b^{2}$"],"설명":"합차 공식을 적용하면 넓이는 a²-b²이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-27b9b7778679":{"길":"세 모둠의 평균·중앙값·최빈값·분산·표준편차를 모두 구해 다섯 선지를 하나씩 확인한다","단계":[{"제목":"세 모둠의 평균 구하기","힌트":"A,B,C 모둠의 평균은 각각?","식":["$(A평균)=(B평균)=(C평균)=\\frac{90}{15}=6$"],"설명":"세 모둠 모두 평균이 6개로 같으므로 ①은 옳지 않다.","확인":"6","스킬":"P4"},{"제목":"중앙값과 최빈값 판별하기","힌트":"학생 수가 15명일 때 중앙값은 몇 번째 값이고, 세 모둠의 최빈값은?","식":[],"설명":"학생 수가 모두 15명이므로 중앙값은 8번째 값이며, 세 모둠 모두 6개로 같아 ②는 옳다. 최빈값은 A가 4개·8개, B는 없음, C는 6개로 모두 달라 ③은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"세 모둠의 분산 구하기","고비":true,"힌트":"A,B,C의 분산을 각각 구해 크기를 비교하면?","식":["$(A분산)=\\frac{36}{15}=2.4$","$(B분산)=\\frac{30}{15}=2$","$(C분산)=\\frac{22}{15}$"],"설명":"분산이 가장 큰 모둠은 A이므로 ④는 옳지 않다.","확인":null,"스킬":"A2"},{"제목":"표준편차로 ⑤ 확인하기","힌트":"각 분산에 제곱근을 씌우면?","식":["$\\sqrt{2.4},\\ \\sqrt{2},\\ \\sqrt{\\frac{22}{15}}$"],"설명":"분산 2.4, 2, 22/15에 각각 제곱근을 씌우면 ⑤의 표준편차 값과 일치하므로 ⑤는 옳다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-2a3abd4c45c1":{"길":"그래프에서 a, b를 읽어 이차식에 대입한 뒤 인수분해한다","단계":[{"제목":"그래프에서 a, b 값 읽기","힌트":"일차함수가 x축, y축과 만나는 점에서 a와 b를 구하면?","식":["$x절편=-2,\\ y절편=-4\\ \\Rightarrow\\ a=-2,\\ b=4$"],"설명":"그래프가 지나는 절편을 이용해 a=-2, b=4를 구한다.","확인":null,"스킬":"G9"},{"제목":"이차식에 대입해 인수분해하기","고비":true,"힌트":"ax²-7x+b에 a=-2, b=4를 넣고 인수분해하면?","식":["$-2x^{2}-7x+4=-(2x-1)(x+4)$"],"설명":"값을 대입한 뒤 인수분해하면 -(2x-1)(x+4)가 된다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-2b633fdaf4a3":{"길":"각 선지를 원주각·중심각·외각 성질로 하나씩 확인해 거짓인 것을 찾는다","단계":[{"제목":"① 진위 확인하기","힌트":"호 CB에 대한 원주각은 어디서 같을까?","식":["$\\angle CDB=\\angle CAB=30^\\circ$"],"설명":"호 CB에 대한 원주각 ∠CDB와 ∠CAB는 크기가 같으므로 ①은 옳다.","확인":null,"스킬":"S5"},{"제목":"② 진위 확인하기","고비":true,"힌트":"∠ACD는 중심각의 절반일까, ∠APD와 관계있을까?","식":["$\\angle ACD=\\frac{1}{2}\\angle AOD$"],"설명":"∠ACD는 중심각 ∠AOD의 절반이지 ∠APD와는 관계가 없으므로 ②는 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"③ 진위 확인하기","힌트":"∠ADB=90°임을 이용해 △ABD의 각의 합을 세우면?","식":["$\\angle ADB=90^\\circ\\Rightarrow\\angle BAD+\\angle DBA=90^\\circ$","$\\angle DBA=\\angle DCA$"],"설명":"지름에 대한 원주각이므로 ∠ADB=90°이고 ∠DBA=∠DCA(같은 호의 원주각)이므로 ∠BAD+∠DCA=90°가 성립해 ③은 옳다.","확인":null,"스킬":"S5"},{"제목":"④ 진위 확인하기","힌트":"△ADP의 내각의 합과 ∠DAB=∠DCB를 이용하면?","식":["$\\angle ABC=\\angle ADC=60^\\circ$","$\\angle APD+\\angle DAB=120^\\circ$"],"설명":"△ADP에서 내각의 합으로 ∠APD+∠DAB=120°이고 ∠DAB=∠DCB이므로 ∠APD+∠DCB=120°가 성립해 ④는 옳다.","확인":null,"스킬":"S10"},{"제목":"⑤ 진위 확인하고 정답 확정하기","힌트":"△ACP의 외각 정리를 쓰면 ∠APD는?","식":["$\\angle APD=30^\\circ+\\angle ACP$","$\\angle ACP=\\angle ABD\\Rightarrow\\angle APD=\\angle ABD+30^\\circ$"],"설명":"△ACP의 외각 정리로 ⑤도 옳음을 확인한다. 따라서 옳지 않은 것은 ②이다.","확인":"2","스킬":"S10"}],"fb":"fig/ns/"},"ns-2c0be01661df":{"길":"피타고라스 정리로 AD, EF를 구해 점 P, Q의 좌표를 정하고 PQ를 계산한다","단계":[{"제목":"AD, EF의 길이 구하기","힌트":"그림의 직각삼각형에서 AD, EF는?","식":["$\\overline{AD}=\\sqrt{2^{2}+3^{2}}=\\sqrt{13},\\ \\overline{EF}=\\sqrt{2^{2}+2^{2}}=2\\sqrt{2}$"],"설명":"피타고라스 정리로 두 길이를 구한다.","확인":null,"스킬":"S3"},{"제목":"P, Q의 좌표 구하기","고비":true,"힌트":"AD=AP, EF=EQ이므로?","식":["$P:2-\\sqrt{13},\\ Q:4+2\\sqrt{2}$"],"설명":"각 중심 좌표에서 구한 길이만큼 옮긴 점이 P, Q이다.","확인":null,"스킬":"N7"},{"제목":"PQ 계산하기","힌트":"두 좌표를 빼면?","식":["$(4+2\\sqrt{2})-(2-\\sqrt{13})=2+2\\sqrt{2}+\\sqrt{13}$"],"설명":"PQ=2+2√2+√13이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-2c0d5940ae69":{"길":"모눈에서 네 귀퉁이 삼각형을 빼 기울어진 정사각형의 넓이를 구하고 한 변을 찾아 좌표로 옮긴다","단계":[{"제목":"작은 정사각형 넓이 구하기","힌트":"3×3 정사각형에서 네 모서리 삼각형을 빼면?","식":["$3\\times3-4\\times\\left(\\frac{1}{2}\\times2\\times1\\right)=5$"],"설명":"기울어진 작은 정사각형의 넓이는 5이다.","확인":null,"스킬":"S12"},{"제목":"점 A의 좌표 구하기","힌트":"넓이 5인 정사각형의 한 변은 √5이므로 a는?","식":["$a=-4-\\sqrt{5}$"],"설명":"한 변의 길이 √5만큼 옮긴 좌표가 a이다.","확인":null,"스킬":"N7"},{"제목":"큰 정사각형 넓이 구하기","고비":true,"힌트":"4×4 정사각형에서 네 모서리 삼각형을 빼면?","식":["$4\\times4-4\\times\\left(\\frac{1}{2}\\times3\\times1\\right)=10$"],"설명":"기울어진 큰 정사각형의 넓이는 10이다.","확인":null,"스킬":"S12"},{"제목":"점 D의 좌표 구하기","힌트":"넓이 10인 정사각형의 한 변은 √10이므로 b는?","식":["$b=1+\\sqrt{10}$"],"설명":"한 변의 길이 √10만큼 옮긴 좌표가 b이다.","확인":null,"스킬":"N7"},{"제목":"a+2b 계산하기","힌트":"a와 2b를 더하면?","식":["$(-4-\\sqrt{5})+2(1+\\sqrt{10})=-2-\\sqrt{5}+2\\sqrt{10}$"],"설명":"정리하면 -2-√5+2√10이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-2eb555586bbc":{"길":"정사각형을 둘러싼 3×3 정사각형에서 귀퉁이를 빼 넓이를 구하고, 반지름과 부채꼴 넓이를 계산해 선지를 확인한다","단계":[{"제목":"정사각형 ABCD의 넓이 구하기","힌트":"3×3 정사각형에서 네 귀퉁이 삼각형을 빼면?","식":["$\\square ABCD=3\\times3-4\\times\\left(\\frac12\\times2\\times1\\right)=5$"],"설명":"정사각형 ABCD를 둘러싼 3×3 정사각형에서 네 귀퉁이의 작은 직각삼각형 넓이를 빼면 ABCD의 넓이는 5이다.","확인":"5","스킬":"S12"},{"제목":"반지름(=AB) 구하기","힌트":"정사각형의 넓이가 한 변의 제곱이라면 한 변은?","식":["$\\overline{AB}=\\sqrt5$"],"설명":"정사각형의 넓이가 5이므로 한 변, 즉 원의 반지름 AB는 √5이다.","확인":null,"스킬":"N8"},{"제목":"부채꼴 ABC의 넓이 구해 ②와 비교하기","고비":true,"힌트":"∠ABC=90°인 부채꼴의 넓이는?","식":["$\\frac14\\pi\\times(\\sqrt5)^2=\\frac54\\pi$"],"설명":"∠ABC=90°이므로 부채꼴 ABC의 넓이는 원 넓이의 ¼인 (5/4)π이다. ②는 5π라 했으므로 옳지 않다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-2fbca7786674":{"길":"밑면과 옆면에서 띠로 가려지지 않은 넓이를 각각 식으로 세워 더한다","단계":[{"제목":"밑면에서 가려지지 않은 부분 구하기","힌트":"밑면의 가로세로에서 띠의 폭 2씩을 빼면?","식":["$2(3x-2)(2x+3)=12x^{2}+10x-12$"],"설명":"밑면 두 곳에서 띠 폭만큼 줄인 직사각형의 넓이를 구해 더한다.","확인":null,"스킬":"C7"},{"제목":"옆면에서 가려지지 않은 부분 구하기","고비":true,"힌트":"옆면 둘레에서 띠가 겹치는 부분을 빼면?","식":["$10\\{2(3x+2x+5)-8\\}=100x+20$"],"설명":"옆면의 둘레 길이에서 띠가 겹치는 폭을 빼고 높이를 곱한다.","확인":null,"스킬":"C7"},{"제목":"두 부분을 더해 정리하기","힌트":"밑면과 옆면의 넓이를 더하면?","식":["$(12x^{2}+10x-12)+(100x+20)=12x^{2}+110x+8$"],"설명":"두 식을 더하면 최종 넓이는 12x²+110x+8이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-30be0b598413":{"길":"대수 막대의 넓이를 인수분해해 짧은 변을 찾고, 전체 넓이 조건으로 이차방정식을 풀어 길이를 구한다","단계":[{"제목":"전체 넓이를 인수분해하기","힌트":"2x²+3x+1을 두 일차식의 곱으로 나타내면?","식":["$2x^2+3x+1=(2x+1)(x+1)$"],"설명":"여섯 개 대수 막대의 넓이 합을 인수분해해 직사각형의 두 변을 확인한다.","확인":null,"스킬":"C7"},{"제목":"짧은 변 확인하기","힌트":"2x+1과 x+1 중 더 짧은 변은?","식":["$짧은\\ 변=x+1$"],"설명":"x>0이므로 x+1이 2x+1보다 짧은 변이다.","확인":null,"스킬":"C7"},{"제목":"넓이 조건으로 이차방정식 풀기","고비":true,"힌트":"넓이가 2일 때 근의 공식으로 x를 구하면?","식":["$2x^2+3x-1=0$","$x=\\frac{-3+\\sqrt{17}}{4}\\ (\\because x>0)$"],"설명":"넓이가 2라는 조건을 대입하고 근의 공식으로 양수인 x를 구한다.","확인":null,"스킬":"C2"},{"제목":"짧은 변의 길이 계산하기","힌트":"구한 x에 1을 더하면?","식":["$x+1=\\frac{1+\\sqrt{17}}{4}$"],"설명":"짧은 변의 길이는 x+1이므로 값을 계산한다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-311b05e71927":{"길":"AH, HC를 차례로 구해 다섯 선지를 하나씩 계산으로 검증한다","단계":[{"제목":"△ABH에서 AH 구하기","힌트":"∠BAH=30°인 직각삼각형에서 AH=6cos30°는?","식":["$\\overline{AH}=6\\cos30^{\\circ}=3\\sqrt3$"],"설명":"직각삼각형 ABH에서 AB와 각 30°로 AH를 구한다.","확인":null,"스킬":"S6"},{"제목":"△AHC에서 HC 구하기","힌트":"피타고라스 정리로 HC=√(9²-(3√3)²)는?","식":["$\\overline{HC}=\\sqrt{9^2-(3\\sqrt3)^2}=3\\sqrt6$"],"설명":"직각삼각형 AHC에서 피타고라스 정리로 HC를 구한다.","확인":null,"스킬":"S3"},{"제목":"sin x, △AHC의 넓이 구하기","힌트":"sin x=HC/AC, 넓이=1/2×HC×AH는?","식":["$\\sin x=\\dfrac{3\\sqrt6}{9}=\\dfrac{\\sqrt6}{3}$","$\\triangle AHC=\\dfrac12\\times3\\sqrt6\\times3\\sqrt3=\\dfrac{27\\sqrt2}{2}$"],"설명":"구한 AH, HC로 sin x와 삼각형의 넓이를 계산하면 ①~④는 모두 옳다.","확인":null,"스킬":"S8"},{"제목":"tan x 값을 구해 옳지 않은 것 찾기","고비":true,"힌트":"tan x=HC/AH를 계산하면 ⑤와 같을까?","식":["$\\tan x=\\dfrac{3\\sqrt6}{3\\sqrt3}=\\sqrt2$"],"설명":"실제 tan x의 값은 √2인데 ⑤는 √3이라 했으므로 ⑤가 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-337d89cee58c":{"길":"황금비 정의를 비례식으로 세우고 이차방정식으로 풀어 각 빈칸을 채운다","단계":[{"제목":"비례식 세우기(㉠)","힌트":"(x+1):x는 어떤 비와 같을까?","식":["$(x+1):x=x:1$"],"설명":"황금비의 정의에 따라 (x+1):x는 x:1과 같다.","확인":null,"스킬":"A8"},{"제목":"비례식을 방정식으로(㉡)","힌트":"외항의 곱과 내항의 곱이 같다는 성질을 쓰면?","식":["$x^2=x+1\\Rightarrow x^2-x-1=0$"],"설명":"비례식의 성질로 이차방정식을 세운다.","확인":null,"스킬":"A8"},{"제목":"근의 공식으로 풀기(㉢)","힌트":"근의 공식을 적용하면?","식":["$x=\\frac{1\\pm\\sqrt5}{2}$"],"설명":"근의 공식으로 두 값을 구한다.","확인":null,"스킬":"C7"},{"제목":"조건에 맞는 값과 오류 찾기(㉣)","고비":true,"힌트":"x>0 조건에 맞는 값은 무엇이어야 할까?","식":["$x>0\\Rightarrow x=\\frac{1+\\sqrt5}{2}$"],"설명":"x>0이므로 옳은 값은 (1+√5)/2인데 ㉣은 (1-√5)/2로 되어 있어 틀렸다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-34b65cdabe80":{"길":"직사각형의 두 꼭짓점을 지날 때의 a를 각각 구해 범위의 경계를 정한다","단계":[{"제목":"조건 이해하기","힌트":"y=ax²이 직사각형 둘레의 서로 다른 두 점을 지나려면 그래프의 폭은 어느 범위여야 할까?","식":[],"설명":"점 A를 지날 때보다 폭이 넓고, 점 C를 지날 때보다 폭이 좁아야 두 점에서 만난다.","확인":null,"스킬":"G1"},{"제목":"점 A를 지날 때의 a 구하기","힌트":"A(1,4)를 지나면 a는?","식":["$a=4$"],"설명":"A를 지날 때 a=4이다.","확인":null,"스킬":"A6"},{"제목":"점 C를 지날 때의 a 구하기","고비":true,"힌트":"C(4,2)를 지나면 a는?","식":["$16a=2\\ \\Rightarrow\\ a=\\frac{1}{8}$"],"설명":"C를 지날 때 a=1/8이다.","확인":null,"스킬":"A6"},{"제목":"범위 확정해 답 정하기","힌트":"1/8은 두 값 사이의 열린구간에 포함될까?","식":["$\\frac{1}{8}<a<4$"],"설명":"a는 1/8과 4 사이(양 끝 제외)의 값이어야 하므로, a=1/8은 조건을 만족하지 않는 값이다.","확인":"1/8","스킬":"G1"}],"fb":"fig/ns/"},"ns-379e4920298a":{"길":"다섯 선지를 넓이식·호의 비·보조선·현의 비로 하나씩 확인한다","단계":[{"제목":"① 판별하기","힌트":"부채꼴의 넓이는 (1/2)r²sinθ, sin80°와 sin40°의 관계는?","식":["$\\triangle AOB=\\frac12r^2\\sin80^\\circ,\\ \\triangle COD=\\frac12r^2\\sin40^\\circ$"],"설명":"sin80°≠2sin40°이므로 △AOB≠2△COD, ①은 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"② 판별하기","힌트":"OA는 반지름, CD는 현인데 둘이 같을까?","식":[],"설명":"OA=OB=OC=OD(반지름)이고 CD는 현이므로 일반적으로 OA=CD가 아니다. ②는 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"③ 판별하기","힌트":"호의 길이는 중심각의 크기에 정비례하므로?","식":["$\\overset{\\frown}{AB}:\\overset{\\frown}{CD}=80^\\circ:40^\\circ=2:1$"],"설명":"호의 길이와 중심각의 크기는 정비례하므로 AB(호)=2CD(호)가 성립해 ③은 옳다.","확인":null,"스킬":"S5"},{"제목":"④ 판별하기","고비":true,"힌트":"호 AB의 중점 M을 잡으면 AM, BM은 CD와 어떤 관계일까?","식":["$\\angle AOM=\\angle BOM=\\angle COD=40^\\circ\\Rightarrow\\overline{AM}=\\overline{BM}=\\overline{CD}$"],"설명":"호 AB의 중점 M을 잡으면 AM=BM=CD가 되고, 삼각부등식에서 AB<AM+BM=2CD이므로 ④는 옳지 않다.","확인":null,"스킬":"S14"},{"제목":"⑤ 판별하고 정답 확정하기","힌트":"현의 길이는 중심각에 정비례할까?","식":[],"설명":"현의 길이는 중심각의 크기와 정비례하지 않으므로 AB=2CD는 성립하지 않는다. 따라서 옳은 것은 ③이다.","확인":"3","스킬":"S5"}],"fb":"fig/ns/"},"ns-388dc6bdc7c4":{"길":"둘러싼 정사각형에서 귀퉁이를 빼 ABCD의 넓이와 한 변을 구한 뒤, P·Q의 좌표를 구해 선지를 확인한다","단계":[{"제목":"정사각형 ABCD의 넓이 구하기","힌트":"3×3 정사각형에서 네 귀퉁이 삼각형을 빼면?","식":["$\\square ABCD=3^2-4\\times\\left(\\frac12\\times1\\times2\\right)=5$"],"설명":"ABCD를 둘러싼 3×3 정사각형에서 네 귀퉁이 직각삼각형 넓이를 빼면 ABCD의 넓이는 5이다. ②는 옳다.","확인":"5","스킬":"S12"},{"제목":"한 변의 길이와 둘레 구하기","힌트":"넓이가 5인 정사각형의 한 변은?","식":["$\\overline{AD}=\\sqrt5$","$4\\times\\sqrt5=4\\sqrt5$"],"설명":"정사각형의 한 변은 √5이므로 둘레는 4√5이다. ③은 옳다.","확인":null,"스킬":"N8"},{"제목":"P, Q의 좌표 구해 PQ 계산하기","고비":true,"힌트":"P는 2에서 왼쪽, Q는 2에서 오른쪽으로 √5만큼 떨어진 점","식":["$P=2-\\sqrt5,\\ Q=2+\\sqrt5$","$\\overline{PQ}=(2+\\sqrt5)-(2-\\sqrt5)=2\\sqrt5$"],"설명":"P=2-√5, Q=2+√5이므로 PQ=2√5이다. ④는 4+2√5라 했으므로 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"나머지 선지 확인하고 답 정하기","힌트":"①, ⑤도 앞서 구한 값과 같은가?","식":[],"설명":"①의 P=2-√5는 위와 같아 옳고, ⑤의 AB=AP=√5도 정의상 같으므로 옳다. 따라서 옳지 않은 것은 ④이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-3a2bbe159bcc":{"길":"피타고라스로 BH를 구하고, 원주각이 같음을 이용한 닮음의 비례식으로 지름을 구해 반지름을 낸다","단계":[{"제목":"직각삼각형 ABH에서 BH 구하기","힌트":"피타고라스 정리로 BH를 구하면?","식":["$\\overline{BH}=\\sqrt{10^2-5^2}=5\\sqrt3$"],"설명":"직각삼각형 ABH에서 BH를 구한다.","확인":null,"스킬":"S3"},{"제목":"닮음인 두 삼각형 찾기","고비":true,"힌트":"BQ가 지름이면 ∠QCB는 몇 도이고, ∠BAH와 ∠BQC는 어떤 호의 원주각일까?","식":["$\\angle BAH=\\angle BQC(호\\ BC의\\ 원주각),\\ \\angle AHB=\\angle QCB=90^\\circ$"],"설명":"BQ가 지름이므로 ∠QCB=90°이고, 호 BC에 대한 원주각이 같으므로 ∠BAH=∠BQC이다. 두 각이 각각 같으므로 △ABH∽△QBC(AA닮음)이다.","확인":null,"스킬":"S5"},{"제목":"비례식 세우기","힌트":"닮음비로 AB:QB=BH:BC를 세우면?","식":["$10:\\overline{QB}=5\\sqrt3:16$"],"설명":"닮음인 두 삼각형의 대응변 비를 비례식으로 세운다.","확인":null,"스킬":"S1"},{"제목":"QB 구하기","힌트":"비례식을 풀면 QB는?","식":["$\\overline{QB}=\\frac{160}{5\\sqrt3}=\\frac{32\\sqrt3}{3}$"],"설명":"비례식을 풀어 지름 QB를 구한다.","확인":null,"스킬":"S1"},{"제목":"반지름 구하기","힌트":"지름의 절반이 반지름이므로?","식":["$\\frac12\\times\\frac{32\\sqrt3}{3}=\\frac{16\\sqrt3}{3}$"],"설명":"지름 QB의 절반이 원 O의 반지름이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-3c89fe8d8888":{"길":"세 삼각형에 각각 수선(또는 이등변 성질)을 적용해 세 변의 길이(범위)를 구해 비교한다","단계":[{"제목":"△ABC에서 BC 구하기","힌트":"A에서 BC에 내린 수선의 발 P로 BP, PC를 구하면?","식":["$\\overline{BP}=3\\sqrt6\\cos45^{\\circ}=3\\sqrt3$","$\\overline{PC}=6\\cos60^{\\circ}=3$","$\\overline{BC}=3\\sqrt3+3$"],"설명":"A에서 BC에 수선을 내려 두 직각삼각형으로 나눈 뒤 BP, PC를 더해 BC를 구한다.","확인":null,"스킬":"S2"},{"제목":"△DEF에서 EF 구하기","힌트":"E에서 DF에 내린 수선의 발 Q로 EQ, DQ, QF를 구하면?","식":["$\\overline{EQ}=6\\sin60^{\\circ}=3\\sqrt3,\\ \\overline{DQ}=6\\cos60^{\\circ}=3$","$\\overline{QF}=7-3=4$","$\\overline{EF}=\\sqrt{4^2+(3\\sqrt3)^2}=\\sqrt{43}$"],"설명":"같은 방법으로 E에서 DF에 수선을 내려 직각삼각형에서 EF를 구한다.","확인":null,"스킬":"S2"},{"제목":"△GHI에서 HI 구하기","고비":true,"힌트":"∠HGI를 구하면 △GHI는 어떤 삼각형일까?","식":["$\\angle HGI=180^{\\circ}-(30^{\\circ}+120^{\\circ})=30^{\\circ}$","$\\overline{HI}=\\overline{GI}=6$"],"설명":"∠HGI=∠GIH=30°로 이등변삼각형이 되어 HI=GI=6이다.","확인":"6","스킬":"S10"},{"제목":"BC의 범위 좁히기","힌트":"5<3√3<6임을 이용해 BC의 범위를 구하면?","식":["$5<3\\sqrt3<6\\Rightarrow8<3\\sqrt3+3<9$"],"설명":"3√3의 범위를 이용해 BC가 8과 9 사이임을 구한다.","확인":null,"스킬":"N6"},{"제목":"EF의 범위 좁히기","힌트":"6<√43<7임을 확인하면?","식":["$6<\\sqrt{43}<7$"],"설명":"√43이 6과 7 사이의 값임을 확인해 EF의 범위를 구한다.","확인":null,"스킬":"N6"},{"제목":"세 길이의 대소 비교하기","힌트":"HI=6, 6<EF<7, 8<BC<9를 비교하면?","식":["$\\overline{HI}<\\overline{EF}<\\overline{BC}$"],"설명":"세 범위를 비교하면 HI가 가장 작고 BC가 가장 크다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-3cb2f007cb1c":{"길":"네 보기를 하나씩 인수분해해 확인하고 남은 하나를 소거법으로 정한다","단계":[{"제목":"ㄴ, ㄷ 인수분해해 확인하기","힌트":"x²+14x+48과 x²+16x+48을 인수분해하면?","식":["$x^{2}+14x+48=(x+6)(x+8)$","$x^{2}+16x+48=(x+4)(x+12)$"],"설명":"두 식 모두 정수 인수로 깔끔히 나뉘어 직사각형을 만들 수 있으므로 ㄴ, ㄷ은 옳다.","확인":null,"스킬":"N4"},{"제목":"ㄹ, ㅁ 인수분해해 확인하기","힌트":"x²+26x+48과 x²+49x+48도 같은 방법으로 확인하면?","식":["$x^{2}+26x+48=(x+2)(x+24)$","$x^{2}+49x+48=(x+1)(x+48)$"],"설명":"역시 정수 인수로 나뉘므로 ㄹ, ㅁ도 옳다.","확인":null,"스킬":"N4"},{"제목":"남은 ㄱ을 따져 답 정하기","고비":true,"힌트":"x²+12x+48을 정수 인수로 나눌 수 있을까?","식":["$x^{2}+12x+48$"],"설명":"48을 곱해 합이 12가 되는 정수 짝이 없어 정수 인수로 나뉘지 않으므로, 나머지 넷이 모두 옳은 이상 소거법으로 옳지 않은 것은 ㄱ이다.","확인":null,"스킬":"C5"}],"fb":"fig/ns/"},"ns-3f513d9824bb":{"길":"이등변삼각형의 성질과 외각 정리를 순서대로 적용해 빈칸을 채운다","단계":[{"제목":"이등변삼각형 조건 채우기(가)","힌트":"△OAP가 이등변삼각형이려면 어느 두 변이 같아야 할까?","식":["$\\overline{OP}=\\overline{OA}$"],"설명":"P가 원 위의 점이므로 OP, OA는 모두 반지름이어서 OP=OA인 이등변삼각형이 된다.","확인":null,"스킬":"S7"},{"제목":"외각 정리로 (나) 채우기","고비":true,"힌트":"△OAP의 외각 ∠AOB는 두 밑각의 합으로 어떻게 쓸 수 있을까?","식":["$\\angle AOB=\\angle OPA+\\angle OAP=2\\angle APB$"],"설명":"이등변삼각형의 두 밑각이 같으므로 외각 ∠AOB는 ∠OPA의 2배, 즉 2∠APB이다.","확인":null,"스킬":"S7"}],"fb":"fig/ns/"},"ns-46b7b24aa9f3":{"길":"넓이비로 닮음비를 구해 두 변을 한 문자로 두고, 둘레 조건으로 방정식을 세워 풀어 GF를 구한다","단계":[{"제목":"닮음비로 두 변을 한 문자로 나타내기","힌트":"넓이비가 4:3이면 닮음비는?","식":["$4:3=2^2:(\\sqrt3)^2\\ \\Rightarrow\\ 2:\\sqrt3$","$\\overline{AB}=2a,\\ \\overline{ED}=\\sqrt3a$"],"설명":"두 정사각형의 넓이비 4:3의 제곱근을 취하면 닮음비는 2:√3이므로 AB=2a, ED=√3a로 둔다.","확인":null,"스킬":"A8"},{"제목":"둘레 조건으로 방정식 세워 a 구하기","고비":true,"힌트":"직사각형 ABCD의 둘레를 a로 나타내면?","식":["$2\\{2a+(2+\\sqrt3)a\\}=52\\ \\Rightarrow\\ (4+\\sqrt3)a=26$"],"설명":"직사각형의 가로는 2a, 세로는 (2+√3)a이므로 둘레 조건을 식으로 세워 정리한다.","확인":null,"스킬":"C7"},{"제목":"a의 값을 유리화해 구하기","힌트":"26/(4+√3)의 분모를 유리화하면?","식":["$a=\\frac{26}{4+\\sqrt3}=\\frac{26(4-\\sqrt3)}{13}=2(4-\\sqrt3)$"],"설명":"분모를 유리화하면 a=2(4-√3)이다.","확인":null,"스킬":"N6"},{"제목":"GF의 길이 구하기","힌트":"GF=2a-√3a를 a에 대입하면?","식":["$\\overline{GF}=(2-\\sqrt3)a=2(2-\\sqrt3)(4-\\sqrt3)=22-12\\sqrt3$"],"설명":"GF=(2-√3)a에 a를 대입해 전개하면 22-12√3이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-46cba171047d":{"길":"반지름·접선의 길이 성질과 SSS합동을 차례로 확인해 근거 없는 선지를 찾는다","단계":[{"제목":"반지름 성질 확인하기","힌트":"OA, OC는 원의 무엇일까?","식":[],"설명":"OA, OC는 모두 원 O의 반지름이므로 OA=OC이다.","확인":null,"스킬":"S5"},{"제목":"접선의 길이 성질 적용하기","힌트":"원 밖의 한 점 E에서 그은 두 접선의 길이는?","식":[],"설명":"원 밖의 한 점에서 그은 두 접선의 길이는 같으므로 EB=EC이고, 같은 이유로 PA=PB이다.","확인":null,"스킬":"S5"},{"제목":"SSS합동으로 각 비교하기","힌트":"OE는 공통, OC=OB, EB=EC이면 두 삼각형은?","식":["$\\triangle OCE \\equiv \\triangle OBE$"],"설명":"OE가 공통이고 OC=OB(반지름), EB=EC(접선의 길이)이므로 SSS합동이다. 따라서 ∠OEC=∠OEB이다.","확인":null,"스킬":"S5"},{"제목":"옳지 않은 것 찾기","고비":true,"힌트":"D, E가 대칭이라는 조건이 없다면 △ODC와 △OEC는?","식":[],"설명":"D와 E가 대칭이라는 조건이 없으므로 △ODC와 △OEC가 항상 합동이라고 할 수 없다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-473d0821017a":{"길":"세 학생의 평균이 같음을 확인한 뒤, 점수가 평균에 몰린 정도로 표준편차의 크기를 비교한다","단계":[{"제목":"세 학생의 평균 구하기","힌트":"A,B,C가 맞힌 숫자의 평균은 각각?","식":["$(A평균)=(B평균)=(C평균)=\\frac{30}{6}=5$"],"설명":"세 학생이 맞힌 숫자의 평균은 모두 5로 같다.","확인":"5","스킬":"P4"},{"제목":"평균 주위로 몰린 정도 비교하기","고비":true,"힌트":"점수가 평균 5 가까이에 가장 많이 몰려 있는 학생은 누구일까?","식":[],"설명":"점수가 평균 가까이 몰려 있을수록 표준편차가 작으므로, 흩어진 정도를 비교하면 b<c<a이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-4906458cba4c":{"길":"삼각형 넓이로 꼭짓점의 y좌표를 구하고, 그래프가 지나는 점으로 a를 구해 전개한다","단계":[{"제목":"밑변과 축의 위치로 넓이식 세우기","힌트":"그래프에서 O, B 사이 거리와 축의 위치는?","식":["$\\overline{OB}=4,\\ A(2,q)$","$\\frac12\\times4\\times q=8$"],"설명":"그래프에서 축이 x=2이고 O, B 사이 거리가 4임을 읽어 넓이식을 세운다.","확인":null,"스킬":"G10"},{"제목":"q 구하기","힌트":"넓이식을 풀면 q는?","식":["$q=4$"],"설명":"넓이식을 풀면 꼭짓점의 y좌표 q=4를 얻는다.","확인":"4","스킬":"G10"},{"제목":"점 B를 대입해 a 구하기","고비":true,"힌트":"y=a(x-2)²+4가 점 (4,0)을 지나면?","식":["$4a+4=0$","$a=-1$"],"설명":"그래프가 점 B(4,0)을 지나므로 대입해 a=-1을 얻는다.","확인":null,"스킬":"A6"},{"제목":"전개해 b, c 구하고 합하기","힌트":"y=-(x-2)²+4를 전개하면?","식":["$y=-x^2+4x$","$a=-1,\\ b=4,\\ c=0$","$a+b+c=3$"],"설명":"전개하면 b=4, c=0이므로 a+b+c=3이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-49d88b4e4bb4":{"길":"일곱 조건을 내접사각형의 세 정리(대각의 합·방멱정리의 역·원주각의 역)와 대조해 고른다","단계":[{"제목":"대각의 합 조건 판별하기","힌트":"한 쌍의 대각의 합이 180°이면 사각형은?","식":["$\\angle BAD+\\angle BCD=180^{\\circ}$"],"설명":"한 쌍의 대각의 크기의 합이 180°이므로 ㄱ은 원에 내접하는 조건이다.","확인":null,"스킬":"C3"},{"제목":"교점을 이용한 곱 조건 판별하기","힌트":"PA·PC=PB·PD는 방멱정리의 역이다","식":["$\\overline{PA}\\cdot\\overline{PC}=\\overline{PB}\\cdot\\overline{PD}$"],"설명":"두 선분의 곱이 같은 것은 방멱정리의 역으로 내접 조건이 된다.","확인":null,"스킬":"C3"},{"제목":"원주각 조건 판별하기","힌트":"한 호에 대한 두 원주각이 같으면?","식":["$\\angle BAC=\\angle BDC$"],"설명":"한 호에 대한 두 원주각의 크기가 같으므로 ㅁ은 원주각의 역으로 내접 조건이다.","확인":null,"스킬":"C3"},{"제목":"나머지 선지 걸러내기","고비":true,"힌트":"ㄴ, ㄷ, ㅂ, ㅅ은 내접을 보장하는 정확한 정리와 같은가?","식":[],"설명":"ㄴ, ㄷ, ㅂ, ㅅ은 겉보기에는 비슷하지만 내접을 보장하는 정확한 정리(대각의 합·원주각의 역 등)와 맞지 않아 제외된다. 옳은 것은 ㄱ,ㄹ,ㅁ 3개다.","확인":"3","스킬":"C3"}],"fb":"fig/ns/"},"ns-4a5c8994373d":{"길":"다섯 선지를 중심각·호·이등변삼각형·원주각 성질로 각각 확인해 함정을 찾는다","단계":[{"제목":"①호 비교하기","힌트":"중심각이 같으면 호는?","식":["$\\overset{\\frown}{AB}=\\overset{\\frown}{CD}$"],"설명":"∠AOB=∠COD이므로 두 중심각에 대한 호의 길이는 같다.","확인":null,"스킬":"S5"},{"제목":"②현의 비례 함정 확인하기","고비":true,"힌트":"중심각이 2배이면 현의 길이도 2배일까?","식":["$\\angle COE=2\\angle AOB$"],"설명":"중심각은 2배이지만 현의 길이는 중심각에 정비례하지 않으므로 2AB=CE는 성립하지 않는다.","확인":null,"스킬":"S5"},{"제목":"③이등변삼각형 밑각 비교하기","힌트":"∠AOB=∠DOE=a라 하면 두 이등변삼각형의 밑각은?","식":["$\\angle OAB=\\angle OED=\\frac{180^{\\circ}-a}{2}$"],"설명":"OA=OB, OD=OE인 이등변삼각형의 밑각을 비교하면 ∠OAB=∠OED이다.","확인":null,"스킬":"S7"},{"제목":"④원주각으로 비교하기","힌트":"∠ADB, ∠DBC는 각각 중심각의 몇 배일까?","식":["$\\angle ADB=\\frac{1}{2}\\angle AOB,\\ \\angle DBC=\\frac{1}{2}\\angle COD$"],"설명":"두 원주각은 각각 중심각의 절반이고 중심각이 같으므로 ∠ADB=∠DBC이다.","확인":null,"스킬":"S5"},{"제목":"⑤중심각-원주각 관계로 옳지 않은 것 확정하기","힌트":"한 호에 대한 중심각은 원주각의 몇 배일까?","식":["$\\angle AOB=2\\angle ACB$"],"설명":"①③④⑤는 모두 성립하므로 옳지 않은 것은 현의 비례를 잘못 적용한 ②이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-4cc5066cf26d":{"길":"마주보는 면 조건으로 ⓐ, ⓑ, ⓒ의 가능한 값을 구해 네 부호 조합의 합을 모두 확인한다","단계":[{"제목":"마주보는 면 관계로 ⓐ, ⓒ의 값 구하기","힌트":"ⓐ, ⓒ와 마주보는 면의 수는 16, 4이다. 각각의 제곱근은?","식":["$\\text{ⓐ}=\\pm\\sqrt{16}=\\pm4$","$\\text{ⓒ}=\\pm\\sqrt4=\\pm2$"],"설명":"ⓐ와 마주보는 면은 16이므로 ⓐ=±4이고, ⓒ와 마주보는 면은 4이므로 ⓒ=±2이다.","확인":null,"스킬":"S11"},{"제목":"ⓑ의 값 구하기","힌트":"ⓑ와 마주보는 면은 -√5이다. 마주보는 두 수는 서로 제곱근 관계이므로 ⓑ는?","식":["$\\text{ⓑ}=(-\\sqrt5)^2=5$"],"설명":"ⓑ와 마주보는 면이 -√5이므로 ⓑ는 그 제곱인 5이다.","확인":"5","스킬":"N8"},{"제목":"네 가지 부호 조합의 합 구하기","고비":true,"힌트":"ⓐ, ⓒ의 부호를 각각 바꿔가며 ⓐ+ⓑ+ⓒ 를 모두 구하면?","식":["$4+5+2=11,\\ 4+5-2=7,\\ -4+5+2=3,\\ -4+5-2=-1$"],"설명":"ⓐ, ⓒ의 부호를 네 가지로 조합하면 가능한 합은 11, 7, 3, -1이다.","확인":null,"스킬":"P4"},{"제목":"될 수 없는 값 찾기","힌트":"선지 중 위 네 값에 없는 것은?","식":[],"설명":"가능한 합은 -1, 3, 7, 11뿐이므로 선지 중 5는 될 수 없는 값이다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-4e5382cd3156":{"길":"네 개의 직각삼각형에서 피타고라스 정리를 차례로 적용해 BJ까지 구한다","단계":[{"제목":"BD, BF 구하기","힌트":"한 변을 a라 하면 BD, BF는?","식":["$\\overline{BD}=\\sqrt{a^2+a^2}=\\sqrt2a=\\overline{BE}$","$\\overline{BF}=\\sqrt{a^2+(\\sqrt2a)^2}=\\sqrt3a=\\overline{BG}$"],"설명":"정사각형의 한 변을 a라 하면 삼각형 BCD, BEF에서 피타고라스 정리로 BD, BF를 구한다.","확인":null,"스킬":"S3"},{"제목":"BH, BJ 구하기","고비":true,"힌트":"같은 방법을 두 번 더 반복하면?","식":["$\\overline{BH}=\\sqrt{a^2+(\\sqrt3a)^2}=2a=\\overline{BI}$","$\\overline{BJ}=\\sqrt{a^2+(2a)^2}=\\sqrt5a$"],"설명":"같은 방법으로 두 번 더 반복하면 BH=2a, BJ=√5a이다.","확인":null,"스킬":"S3"},{"제목":"sinB+cosB 구하기","힌트":"삼각형 JBI에서 sinB, cosB는?","식":["$\\sin B=\\frac{a}{\\sqrt5a}=\\frac{\\sqrt5}{5},\\ \\cos B=\\frac{2a}{\\sqrt5a}=\\frac{2\\sqrt5}{5}$","$\\sin B+\\cos B=\\frac{3\\sqrt5}{5}$"],"설명":"삼각형 JBI에서 sinB=JI/BJ, cosB=BI/BJ를 계산해 더하면 3√5/5이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-5263a2c82bbb":{"길":"다섯 선지를 각각 정의대로 계산해 BC와 같은지 확인한다","단계":[{"제목":"①③④⑤ 확인하기","고비":true,"힌트":"cosB, sinA, tanA, 1/tanB에 정의를 넣으면 모두 무엇이 될까?","식":["$c\\cos B=c\\sin A=b\\tan A=\\frac{b}{\\tan B}=\\overline{BC}$"],"설명":"cosB=BC/c, sinA=BC/c, tanA=BC/b, 1/tanB=BC/b이므로 ①③④⑤는 모두 BC와 같다.","확인":null,"스킬":"S6"},{"제목":"② 확인하기","힌트":"b/sinB에 sinB=b/c를 넣으면?","식":["$\\frac{b}{\\sin B}=b\\times\\frac{c}{b}=c=\\overline{AB}$"],"설명":"②는 계산하면 c, 즉 AB가 되어 BC와 다르다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-5298d683dbc4":{"길":"각의 이등분선과 원주각 성질로 AA닮음을 찾아 비례식으로 길이를 구한다","단계":[{"제목":"닮음 조건 찾기","고비":true,"힌트":"∠EBD와 ∠EAC는 어떤 호에 대한 원주각일까? AE는 각을 이등분한다.","식":["$\\angle EBD=\\angle EAC=\\angle EAB$"],"설명":"∠EBD와 ∠EAC는 같은 호 EC에 대한 원주각으로 같고, AE가 ∠A를 이등분하므로 ∠EAC=∠EAB이다. ∠E는 공통이므로 △EBD∽△EAB(AA닮음)이다.","확인":null,"스킬":"S5"},{"제목":"비례식 세우기","힌트":"닮음에서 대응변의 비를 쓰면?","식":["$\\overline{EB}:\\overline{EA}=\\overline{ED}:\\overline{EB}$"],"설명":"닮은 두 삼각형의 대응변 비로 EB²=EA×ED가 성립한다.","확인":null,"스킬":"S1"},{"제목":"EB 계산하기","힌트":"EA=AD+DE=16이므로 EB²은?","식":["$\\overline{EB}^{2}=16\\times4=64$","$\\overline{EB}=8$"],"설명":"EA=16, ED=4를 대입하면 EB²=64이므로 EB=8(EB>0)이다.","확인":"8","스킬":"S1"}],"fb":"fig/ns/"},"ns-52d009cbee01":{"길":"세 현이 중심에서 같은 거리에 있음을 보이고 같은 거리의 현은 길이가 같다는 정리를 적용한다","단계":[{"제목":"세 현까지의 거리 구하기","힌트":"반지름 r인 원에서 접어 만든 세 현은 중심에서 각각 얼마나 떨어져 있을까?","식":["$\\frac{1}{2}r$"],"설명":"원의 반지름을 r라 하면 접어서 생긴 세 현은 모두 중심으로부터 1/2r만큼 떨어져 있다.","확인":null,"스킬":"S13"},{"제목":"같은 거리의 현은 길이가 같음을 적용하기","고비":true,"힌트":"중심으로부터 같은 거리에 있는 현들은 길이가 어떨까?","식":[],"설명":"원의 중심으로부터 같은 거리에 있는 두 현의 길이는 같으므로 세 현의 길이가 모두 같다.","확인":null,"스킬":"S13"},{"제목":"정삼각형임을 확인하기","힌트":"세 변의 길이가 모두 같으면?","식":[],"설명":"세 변의 길이가 같으므로 접어서 만든 삼각형은 정삼각형이며, 이를 설명하는 성질은 ③이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-5528f68f07c2":{"길":"그림 속 길이를 x, y로 차례로 나타내 넓이식을 전개한다","단계":[{"제목":"각 변의 길이를 x, y로 나타내기","힌트":"정사각형 ABEH, HGFD의 변의 길이를 이용해 HD, DF는?","식":["$\\overline{AB}=\\overline{AH}=y,\\quad \\overline{HD}=\\overline{DF}=x-y$"],"설명":"정사각형의 변 길이를 이용해 HD, DF를 x, y로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"FC의 길이 구하기","고비":true,"힌트":"FC = DC - DF에서 DC=y이므로?","식":["$\\overline{FC}=y-(x-y)=-x+2y$"],"설명":"DC에서 DF를 빼면 FC의 길이를 얻는다.","확인":null,"스킬":"C7"},{"제목":"넓이를 전개해 a, b, c 구하기","힌트":"$(x-y)(-x+2y)$를 전개하면?","식":["$\\square GECF=(x-y)(-x+2y)=-x^{2}+3xy-2y^{2}$"],"설명":"전개하면 a=-1, b=3, c=-2를 얻는다.","확인":null,"스킬":"A3"},{"제목":"a+b+c 계산하기","힌트":"-1+3-2를 더하면?","식":["$a+b+c=-1+3-2=0$"],"설명":"따라서 a+b+c=0이다.","확인":"0","스킬":"A3"}],"fb":"fig/ns/"},"ns-56ff2f12b906":{"길":"네 점이 한 원 위에 있음을 확인한 뒤 원주각·닮음·방멱정리로 다섯 선지를 판별한다","단계":[{"제목":"네 점이 한 원 위에 있음 알아내기","고비":true,"힌트":"∠ACB=∠ADB이면 A,B,C,D는 어떤 위치 관계일까?","식":[],"설명":"한 선분 AB를 같은 각으로 보는 두 점이므로 네 점 A,B,C,D는 한 원 위에 있다.","확인":null,"스킬":"S15"},{"제목":"①호 AD의 원주각 비교하기","힌트":"호 AD에 대한 원주각은?","식":["$\\angle ABD=\\angle ACD$"],"설명":"한 호 AD에 대한 원주각의 크기는 같으므로 ∠ABD=∠ACD이다.","확인":null,"스킬":"S5"},{"제목":"②⑤닮음과 곱 관계 확인하기","힌트":"∠ABP=∠DCP, ∠BAP=∠CDP이면 어떤 닮음일까?","식":["$\\triangle ABP\\sim\\triangle DCP$","$\\overline{PA}\\cdot\\overline{PC}=\\overline{PB}\\cdot\\overline{PD}$"],"설명":"호 AD, 호 BC에 대한 원주각이 각각 같아 △ABP∽△DCP(AA닮음)이고, 대응변 비에서 PA·PC=PB·PD가 성립한다.","확인":null,"스킬":"S1"},{"제목":"③호 BC의 원주각 비교하기","힌트":"호 BC에 대한 원주각은?","식":["$\\angle BAC=\\angle BDC$"],"설명":"한 호 BC에 대한 원주각의 크기는 같으므로 ∠BAC=∠BDC이다.","확인":null,"스킬":"S5"},{"제목":"④호 DC의 원주각으로 옳지 않은 것 찾기","힌트":"호 DC에 대한 원주각은 ∠DBC와 어느 각이 같을까?","식":["$\\angle DBC=\\angle DAC$"],"설명":"한 호 DC에 대한 원주각의 크기는 같으므로 ∠DBC=∠DAC이며, ∠ADB와는 같다고 할 수 없어 ④가 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-5822f65e8880":{"길":"움직인 거리로 삼각형의 넓이식을 세워 이차방정식을 푼다","단계":[{"제목":"변의 길이를 x로 나타내기","힌트":"x초 후 AP, DQ, PD의 길이는?","식":["$\\overline{AP}=2x,\\ \\overline{DQ}=x,\\ \\overline{PD}=15-2x$"],"설명":"x초 후 점 P, Q가 움직인 거리로 세 변의 길이를 나타낸다.","확인":null,"스킬":"C7"},{"제목":"넓이식 세워 이차방정식 만들기","고비":true,"힌트":"직각삼각형 PDQ의 넓이를 x로 쓰면?","식":["$\\frac{1}{2}x(15-2x)=9$","$2x^2-15x+18=0$"],"설명":"삼각형 PDQ의 넓이가 9라는 조건으로 이차방정식을 세운다.","확인":null,"스킬":"C7"},{"제목":"인수분해해 시간 구하기","힌트":"좌변을 인수분해하면?","식":["$(2x-3)(x-6)=0$","$x=\\frac{3}{2}$ 또는 $x=6$"],"설명":"인수분해하면 두 값 모두 조건을 만족하는 시간이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-58d21918ce7d":{"길":"반지름이 1이므로 각 삼각비가 그대로 선분의 길이가 됨을 이용해 식을 정리한다","단계":[{"제목":"각 삼각비를 선분으로 바꾸기","고비":true,"힌트":"반지름이 1이면 sin, cos는 각각 어떤 선분과 같을까?","식":["$\\sin x=\\overline{AB},\\ \\sin y=\\overline{OB},\\ \\cos x=\\overline{OB},\\ \\cos y=\\overline{AB}$"],"설명":"OA=1이므로 sinx=AB, siny=OB, cosx=OB, cosy=AB이다.","확인":null,"스킬":"S6"},{"제목":"tan 값도 선분으로 바꾸기","힌트":"OC=1이므로 tanx, tanz는?","식":["$\\tan x=\\overline{CD},\\ \\tan z=\\frac{1}{\\overline{CD}}$"],"설명":"OC=1이므로 tanx=CD, tanz=1/CD이다.","확인":null,"스킬":"S6"},{"제목":"식 계산하기","힌트":"약분되는 것끼리 묶으면?","식":["$\\frac{\\overline{OB}}{\\overline{AB}}\\times\\frac{\\overline{AB}}{\\overline{OB}}+\\overline{CD}\\times\\frac1{\\overline{CD}}=1+1$"],"설명":"두 항이 각각 1이 되므로 전체 값은 1+1=2이다.","확인":"2","스킬":"A1"}],"fb":"fig/ns/"},"ns-5b2d201b72b3":{"길":"직각삼각형에서 수선을 내려 생기는 세 닮음 삼각형의 관계로 각 보기를 판별한다","단계":[{"제목":"닮음 관계 확인하기","고비":true,"힌트":"△ABC, △CBD, △ACD는 AA닮음으로 어떻게 짝지어질까?","식":[],"설명":"△ABC∽△CBD∽△ACD(AA닮음)이므로 대응각이 서로 같다.","확인":null,"스킬":"S1"},{"제목":"ㄱ 판별하기","힌트":"∠CAB와 ∠DCB는 대응각일까?","식":["$\\angle CAB=\\angle DCB=y$"],"설명":"닮음에서 ∠CAB=∠DCB=y이므로 sinA=siny이다. ㄱ은 옳다.","확인":null,"스킬":"S1"},{"제목":"ㄴ, ㄷ 판별하기","힌트":"∠ACD와 ∠CBD, ∠ABC는 서로 같을까?","식":["$\\angle ACD=\\angle CBD=\\angle ABC=x$"],"설명":"닮음에서 이 세 각이 모두 x로 같으므로 cosx=DB/BC이지 CD/BC가 아니어서 ㄴ은 틀리고, tanB=tanx=AD/CD가 성립해 ㄷ은 옳다.","확인":null,"스킬":"S1"},{"제목":"ㄹ 판별하기","힌트":"x+y=90°이면 sin(x+y)cos(x+y)는?","식":["$\\sin90^{\\circ}\\times\\cos90^{\\circ}=1\\times0=0$"],"설명":"x+y=90°이므로 sin(x+y)cos(x+y)=0이 되어 ㄹ은 틀리다. 옳은 것은 ㄱ, ㄷ이다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-5cbf0db78cfc":{"길":"두 직각삼각형에서 h에 대한 식을 각각 세워 5개의 선지를 확인한다","단계":[{"제목":"∠BOH, ∠AOH 구하기","고비":true,"힌트":"올려다본 각이 65°, 72°이면 O에서 내려다본 각은?","식":["$\\angle BOH=90^{\\circ}-72^{\\circ}=18^{\\circ}$","$\\angle AOH=90^{\\circ}-65^{\\circ}=25^{\\circ}$"],"설명":"직각삼각형 BOH, AOH에서 여각 관계로 ∠BOH=18°, ∠AOH=25°이다.","확인":null,"스킬":"S6"},{"제목":"①②④ 확인하기","힌트":"tan18°=200/h, tan25°=300/h, tan72°=h/200에서 h는?","식":["$h=\\frac{200}{\\tan18^{\\circ}},\\ h=\\frac{300}{\\tan25^{\\circ}},\\ h=200\\tan72^{\\circ}$"],"설명":"각각의 직각삼각형에서 tan 정의로 h를 나타내면 ①②④는 모두 옳다.","확인":null,"스킬":"S6"},{"제목":"③ 확인하기","힌트":"△AOH에서 tan65°=h/300이 맞을까?","식":["$\\tan65^{\\circ}=\\frac{h}{300}$"],"설명":"③은 h=300tan65°가 되어야 하는데 100tan65°로 되어 있으므로 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-61621ade91fe":{"길":"두 직각삼각형으로 AB, BD, DE를 구해 ∠BAC=15°를 얻고 다섯 식을 확인한다","단계":[{"제목":"AB, BE 구하기","힌트":"△ABE에서 ∠ABE=45°이면 AB, BE는?","식":["$\\overline{AB}=\\frac{4}{\\sqrt2}=2\\sqrt2,\\ \\overline{BE}=2$"],"설명":"직각삼각형 ABE는 45-45-90 삼각형이므로 AB=2√2, BE=2이다.","확인":null,"스킬":"S6"},{"제목":"BD, DE 구하기","힌트":"△BDE에서 ∠BED=60°이면 BD, DE는?","식":["$\\overline{BD}=2\\sin60^{\\circ}=\\sqrt3,\\ \\overline{DE}=2\\cos60^{\\circ}=1$"],"설명":"직각삼각형 BDE에서 BD=√3, DE=1이다.","확인":null,"스킬":"S6"},{"제목":"∠BAC=15° 구하기","고비":true,"힌트":"∠B=∠ABE+∠EBD이면 ∠BAC는?","식":["$\\angle EBD=90^{\\circ}-60^{\\circ}=30^{\\circ}$","$\\angle B=45^{\\circ}+30^{\\circ}=75^{\\circ}$","$\\angle BAC=90^{\\circ}-75^{\\circ}=15^{\\circ}$"],"설명":"직각삼각형 BDE에서 ∠BED=60°이므로 ∠EBD=30°이고, ∠B=∠ABE+∠EBD=75°이다. 직각삼각형 ABC에서 ∠BAC=90°-75°=15°이다.","확인":"15","스킬":"S10"},{"제목":"AC, BC 구하기","힌트":"∠AEF는 몇 도이고, △AEF에서 AF, FE는?","식":["$\\angle AEF=\\angle AEB-\\angle BEF=90^{\\circ}-30^{\\circ}=60^{\\circ}$","$\\overline{AF}=2\\sin60^{\\circ}=\\sqrt3,\\ \\overline{FE}=2\\cos60^{\\circ}=1$","$\\overline{AC}=\\sqrt3+1,\\ \\overline{BC}=\\sqrt3-1$"],"설명":"∠DEF=90°, ∠BED=60°이므로 ∠BEF=30°이고 ∠AEF=∠AEB-∠BEF=60°이다. 직각삼각형 AEF에서 AF=√3, FE=1이고 CF=DE=1, CD=FE=1이므로 AC=AF+CF=√3+1, BC=BD-CD=√3-1이다.","확인":null,"스킬":"S6"},{"제목":"①②③ 확인하기","힌트":"BC, AC, AB로 tan15°, cos15°, sin75°를 계산하면?","식":["$\\tan15^{\\circ}=\\frac{\\sqrt3-1}{\\sqrt3+1}=2-\\sqrt3$","$\\cos15^{\\circ}=\\sin75^{\\circ}=\\frac{\\sqrt6+\\sqrt2}{4}$"],"설명":"①②는 옳고, ③은 sin75°=cos15°와 같은 값이어야 하는데 (√6-√2)/4로 되어 있어 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"④⑤ 확인하기","힌트":"④, ⑤도 같은 값으로 계산하면?","식":["$\\sin45^{\\circ}\\times\\cos75^{\\circ}=\\frac{\\sqrt3-1}{4}$","$\\tan45^{\\circ}\\times\\tan75^{\\circ}=2+\\sqrt3$"],"설명":"④, ⑤는 계산 결과가 선지와 일치하므로 옳다. 따라서 옳지 않은 것은 ③이다.","확인":null,"스킬":"S6"}]},"ns-62e1acb677a6":{"길":"원래 그래프에서 부호와 꼭짓점 위치를 읽어 새 그래프의 개형을 판정한다","단계":[{"제목":"원래 그래프의 부호 읽기","힌트":"아래로 볼록하고 꼭짓점이 제3사분면에 있으면?","식":["$a>0,\\ p<0,\\ q<0$"],"설명":"그래프가 아래로 볼록하고 꼭짓점이 제3사분면에 있으므로 a>0, p<0, q<0이다.","확인":null,"스킬":"G4"},{"제목":"원점을 지나는 조건 확인하기","힌트":"그래프가 원점을 지나므로?","식":["$ap^2+q=0$"],"설명":"원점을 지나므로 이 관계식이 성립한다.","확인":null,"스킬":"G4"},{"제목":"새 그래프의 볼록성과 꼭짓점 위치 판정하기","고비":true,"힌트":"y=-a(x-p)²-q에서 계수와 꼭짓점 (p,-q)는?","식":["$-a<0\\Rightarrow\\text{위로 볼록}$","$p<0,\\ -q>0\\Rightarrow\\text{제2사분면}$"],"설명":"부호가 반대이므로 위로 볼록하고 꼭짓점은 제2사분면에 있다.","확인":null,"스킬":"G4"},{"제목":"원점을 지나는지 확인해 정답 고르기","힌트":"x=0일 때 y값은?","식":["$y=-ap^2-q=0$"],"설명":"새 그래프도 원점을 지나므로 조건을 모두 만족하는 ①이 답이다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-64399e9f4edd":{"길":"제곱근 성질로 a,b,c의 부호를 정하고 그래프의 개형 조건과 비교한다","단계":[{"제목":"a,b,c의 부호 판정하기","힌트":"√a²=a이면 a는?","식":["$\\sqrt{a^2}=a\\Rightarrow a>0$","$\\sqrt{b^2}=-b\\Rightarrow b<0$","$\\sqrt{c^2}=-c\\Rightarrow c<0$"],"설명":"제곱근의 성질로 a>0, b<0, c<0임을 얻는다.","확인":null,"스킬":"N8"},{"제목":"그래프의 개형 조건 확인하기","고비":true,"힌트":"a>0이면 볼록 방향은? ab의 부호로 축의 위치는? c의 부호로 y절편 위치는?","식":["$a>0\\Rightarrow\\text{아래로 볼록}$","$ab<0\\Rightarrow\\text{축은 }y\\text{축 오른쪽}$","$c<0\\Rightarrow y\\text{축과 원점보다 아래에서 만남}$"],"설명":"세 조건을 모두 만족하는 그래프는 ③이다.","확인":null,"스킬":"G7"}],"fb":"fig/ns/"},"ns-655205942276":{"길":"수선을 내려 접은 각을 구하고 엇각으로 ∠ACB를 얻어 넓이 공식을 적용한다","단계":[{"제목":"∠ACH 구하기","고비":true,"힌트":"점 A에서 BC(연장선)에 내린 수선의 발 H에서 AH:AC는?","식":["$\\overline{AH}:\\overline{AC}=5:10=1:2$","$\\angle ACH=30^{\\circ}$"],"설명":"직각삼각형 AHC에서 AH:AC=1:2이므로 ∠ACH=30°이다.","확인":"30","스킬":"S2"},{"제목":"∠ABH 구하기","힌트":"접은 각과 엇각의 성질로 ∠ACB=∠CAB는?","식":["$\\angle ACB=\\angle CAB=30^{\\circ}$","$\\angle ABH=60^{\\circ}$"],"설명":"접은 각과 엇각의 성질에 의해 ∠ACB=∠CAB=30°이고, ∠ABH=60°이다.","확인":"60","스킬":"S10"},{"제목":"AB 구하기","힌트":"직각삼각형 ABH에서 AB=5/sin60°는?","식":["$\\overline{AB}=\\frac{5}{\\sin60^{\\circ}}=\\frac{10\\sqrt3}{3}$"],"설명":"직각삼각형 ABH에서 AB=10√3/3이다.","확인":null,"스킬":"S6"},{"제목":"넓이 구하기","힌트":"△ABC=½×AB×AC×sin30°는?","식":["$\\triangle ABC=\\frac12\\times\\frac{10\\sqrt3}{3}\\times10\\times\\frac12=\\frac{25\\sqrt3}{3}$"],"설명":"두 변 AB, AC와 끼인각 30°로 넓이를 구하면 25√3/3이다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-66b26511eba7":{"길":"세 삼각형의 넓이를 각각 식으로 세워 같다는 조건으로 비를 구한다","단계":[{"제목":"세 삼각형의 넓이 식 세우기","고비":true,"힌트":"두 변과 끼인각으로 넓이를 쓰면?","식":["$S_1=\\frac12ab\\sin30^{\\circ}=\\frac14ab$","$S_2=\\frac12ac\\sin60^{\\circ}=\\frac{\\sqrt3}{4}ac$","$S_3=\\frac12bc\\sin45^{\\circ}=\\frac{\\sqrt2}{4}bc$"],"설명":"세 삼각형의 넓이를 각각 두 변과 끼인각으로 나타낸다.","확인":null,"스킬":"S6"},{"제목":"b를 c로 나타내기","힌트":"S1=S2에서 b는?","식":["$\\frac14ab=\\frac{\\sqrt3}{4}ac$","$b=\\sqrt3c$"],"설명":"S1=S2에서 a가 약분되어 b=√3c이다.","확인":null,"스킬":"A3"},{"제목":"a를 c로 나타내고 비 구하기","힌트":"S1=S3에서 a는?","식":["$\\frac14ab=\\frac{\\sqrt2}{4}bc$","$a=\\sqrt2c$","$a:b:c=\\sqrt2:\\sqrt3:1$"],"설명":"S1=S3에서 b가 약분되어 a=√2c이고, 세 값을 c로 나타내면 a:b:c=√2:√3:1이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-6a0ab831a6ff":{"길":"그래프에서 계수의 부호를 정하고, 각 선지를 특정 x값에서의 함숫값으로 바꿔 확인한다","단계":[{"제목":"부호 판정하기","힌트":"위로 볼록하고 축이 y축 오른쪽, y절편이 양수이면?","식":["$a<0$","$ab<0\\Rightarrow b>0$","$c>0$"],"설명":"그래프의 모양으로 a<0, b>0, c>0임을 얻는다.","확인":null,"스킬":"G7"},{"제목":"①~③ 선지 확인하기","힌트":"b, ab, bc의 부호를 각각 확인하면?","식":["$b>0,\\ ab<0,\\ bc>0$"],"설명":"①, ②, ③은 모두 옳다.","확인":null,"스킬":"G7"},{"제목":"④, ⑤ 선지를 함숫값으로 바꿔 확인하기","고비":true,"힌트":"x=2와 x=-1/2에서의 함숫값 부호는?","식":["$x=2:\\ y=4a+2b+c>0$","$x=-\\frac12:\\ y=\\frac14a-\\frac12b+c<0$"],"설명":"그래프가 x=2에서 x축 위, x=-1/2에서 x축 아래에 있으므로 각 부호를 얻는다.","확인":null,"스킬":"G11"},{"제목":"부등식 정리해 옳지 않은 것 찾기","힌트":"두 번째 부등식의 양변에 4를 곱하면?","식":["$a-2b+4c<0$"],"설명":"양변에 4를 곱하면 a-2b+4c<0이므로 ⑤ 'a-2b+4c>0'는 옳지 않다.","확인":null,"스킬":"G11"}],"fb":"fig/ns/"},"ns-6e64d7ebf0a6":{"길":"수선을 내려 접은 각을 구하고 엇각으로 ∠ACB를 얻어 넓이 공식을 적용한다","단계":[{"제목":"∠ACH 구하기","고비":true,"힌트":"직각삼각형 AHC에서 AH:AC는?","식":["$\\overline{AH}:\\overline{AC}=1:2$","$\\angle ACH=30^{\\circ}$"],"설명":"직각삼각형 AHC에서 AH:AC=1:2이므로 ∠ACH=30°이다.","확인":"30","스킬":"S2"},{"제목":"∠ABH 구하기","힌트":"접은 각, 엇각의 성질로 ∠ACB=∠CAB는?","식":["$\\angle ACB=\\angle CAB=30^{\\circ}$","$\\angle ABH=60^{\\circ}$"],"설명":"접은 각과 엇각의 성질에 의해 ∠ACB=∠CAB=30°이고 ∠ABH=60°이다.","확인":"60","스킬":"S10"},{"제목":"AB 구하기","힌트":"직각삼각형 AHB에서 AB=6/sin60°는?","식":["$\\overline{AB}=\\frac{6}{\\sin60^{\\circ}}=4\\sqrt3$"],"설명":"직각삼각형 AHB에서 AB=4√3(cm)이다.","확인":null,"스킬":"S6"},{"제목":"넓이 구하기","힌트":"△ABC=½×AB×BC×sin30°는?","식":["$\\triangle ABC=\\frac12\\times4\\sqrt3\\times12\\times\\frac12=12\\sqrt3$"],"설명":"두 변 AB, BC와 끼인각 30°로 넓이를 구하면 12√3(cm²)이다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-6f86150c6ee6":{"길":"그래프가 오른쪽으로 치우친 정도와 뾰족한 정도로 평균·중앙값·산포를 비교한다","단계":[{"제목":"ㄱ 평균 비교하기","힌트":"그래프가 더 오른쪽에 있는 반은 어느 쪽일까?","식":[],"설명":"2반의 그래프가 1반보다 오른쪽으로 치우쳐 있으므로 2반의 평균이 더 크다. ㄱ은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 중앙값 비교하기","힌트":"중앙값도 그래프의 치우친 방향을 따라갈까?","식":[],"설명":"같은 이유로 2반의 중앙값이 1반보다 크므로 ㄴ도 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 고르기(산포) 비교하기","고비":true,"힌트":"평균에 더 가깝게 몰려 있는 쪽이 더 고르다","식":[],"설명":"1반의 점수가 2반보다 평균에 더 가까이 몰려 있으므로 1반이 더 고르다. ㄷ은 옳다.","확인":null,"스킬":"C3"},{"제목":"옳은 것 확정하기","힌트":"옳은 것만 고른 선지는?","식":[],"설명":"옳은 것은 ㄷ뿐이므로 답은 ②이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-70a8ff236b0b":{"길":"접은 선분이 OP를 수직이등분함을 이용해 직각삼각형의 각을 구하고 정삼각형임을 증명한다","단계":[{"제목":"접은 선분 위 중점 찾기","힌트":"AB와 OP의 교점 M에서 OM과 MP는 어떤 관계일까?","식":["$\\overline{OM}=\\overline{MP}=\\frac{1}{2}\\overline{OP}=\\frac{1}{2}\\overline{OA}$"],"설명":"접은 선분 AB는 OP를 수직이등분하므로 M은 OP의 중점이고 OM=OA/2이다.","확인":null,"스킬":"S2"},{"제목":"직각삼각형에서 각 구하기","고비":true,"힌트":"직각삼각형 OAM에서 OA:OM=2:1이면 ∠AOM은?","식":["$\\angle AOM=60^{\\circ},\\ \\angle OAM=30^{\\circ}$"],"설명":"빗변과 한 변의 비가 2:1인 직각삼각형이므로 ∠AOM=60°, ∠OAM=30°이다.","확인":null,"스킬":"S6"},{"제목":"정삼각형임을 확인하기","힌트":"△OAP에서 OA=OP이고 끼인각 ∠AOP=60°이면?","식":[],"설명":"OA=OP이고 ∠AOP=60°이므로 △OAP는 항상 정삼각형이며, 정삼각형이 아닐 수 있다는 ④는 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"AB의 길이 구하기","힌트":"OA=6일 때 AM=6sin60°는?","식":["$\\overline{AM}=6\\sin60^{\\circ}=3\\sqrt{3}$","$\\overline{AB}=2\\overline{AM}=6\\sqrt{3}$"],"설명":"OA=6이면 AM=3√3이므로 AB=2AM=6√3이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-7387714c13af":{"길":"일차함수 그래프에서 부호를 읽고 이차함수의 꼭짓점 위치를 판별한다","단계":[{"제목":"일차함수의 부호 읽기","힌트":"오른쪽 위로 향하고 y절편이 원점보다 위쪽이면 a, b의 부호는?","식":[],"설명":"그래프가 오른쪽 위로 향하므로 a>0이고, y절편 -b가 원점보다 위쪽이므로 b<0이다.","확인":null,"스킬":"G9"},{"제목":"완전제곱으로 꼭짓점 좌표 구하기","고비":true,"힌트":"y=bx²-ax를 완전제곱 꼴로 바꾸면?","식":["$y=b\\left(x-\\frac{a}{2b}\\right)^{2}-\\frac{a^{2}}{4b}$"],"설명":"완전제곱으로 바꾸면 꼭짓점의 좌표는 (a/2b, -a²/4b)이다.","확인":null,"스킬":"A6"},{"제목":"꼭짓점이 속한 사분면 정하기","힌트":"a>0, b<0이면 a/2b와 -a²/4b의 부호는?","식":["$\\frac{a}{2b}<0,\\ \\ -\\frac{a^{2}}{4b}>0$"],"설명":"x좌표는 음수, y좌표는 양수이므로 꼭짓점은 제2사분면 위에 있다.","확인":null,"스킬":"G9"}],"fb":"fig/ns/"},"ns-73c1968c6ab4":{"길":"대화의 흐름을 완전제곱식 풀이 순서와 맞춰 보며 틀린 표현을 찾는다","단계":[{"제목":"빈칸 채우기","힌트":"이차방정식을 도형으로 풀 때 각 단계에서 필요한 것은?","식":["$㉡:\\text{완전제곱식},\\ ㉢:25,\\ ㉣:(x+5)^2=64,\\ ㉤:x+5=\\pm8$"],"설명":"대화의 흐름을 따라 각 빈칸에 알맞은 말과 식을 채운다.","확인":null,"스킬":"A6"},{"제목":"틀린 선지 고르기","고비":true,"힌트":"㉡ 자리에 들어갈 말은 \"근의 공식\"이 맞을까?","식":[],"설명":"㉡ 자리에는 \"완전제곱식\"이 들어가야 하므로 \"근의 공식\"이라 쓴 선지가 틀렸다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-752fffea7d94":{"길":"여각 관계로 ∠OBA를 구하고 다섯 선지를 직접 계산해 확인한다","단계":[{"제목":"∠OBA 구하기","고비":true,"힌트":"직각삼각형 OAB에서 나머지 각은?","식":["$\\angle OBA=90^{\\circ}-39^{\\circ}=51^{\\circ}$"],"설명":"삼각형 OAB는 직각삼각형이므로 ∠OBA=51°이다.","확인":"51","스킬":"S6"},{"제목":"①②⑤ 확인하기","힌트":"OB=1이므로 sin39°, cos39°, cos51°는 어떤 선분일까?","식":["$\\sin39^{\\circ}=\\overline{AB}=0.6293$","$\\cos39^{\\circ}=\\overline{OA}=0.7771$","$\\cos51^{\\circ}=\\overline{AB}=0.6293$"],"설명":"①은 0.6293, ②는 0.7771, ⑤는 0.6293이 되어 선지의 값과 다르므로 모두 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"③④ 확인하기","힌트":"tan39°, sin51°는 어떤 선분일까?","식":["$\\tan39^{\\circ}=\\overline{CD}=0.8098$","$\\sin51^{\\circ}=\\overline{OA}=0.7771$"],"설명":"③은 0.8098이 되어 옳지 않고, ④는 0.7771이 되어 선지와 일치하므로 옳다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-762e8d795d86":{"길":"1차 7회인 학생 중 2차 성공 횟수가 늘어난 학생만 골라 평균을 구한다","단계":[{"제목":"조건에 맞는 학생 찾기","힌트":"1차 7회이면서 2차가 늘어난 학생의 2차 성공 횟수는?","식":["$8회,\\ 9회$"],"설명":"산점도에서 조건에 맞는 학생은 2차에 8회, 9회 성공한 두 명이다.","확인":null,"스킬":"P4"},{"제목":"평균 구하기","고비":true,"힌트":"두 값을 더해 2로 나누면?","식":["$\\frac{8+9}{2}=8.5$"],"설명":"두 학생의 2차 성공 횟수의 평균은 8.5회이다.","확인":"8.5","스킬":"P4"}],"fb":"fig/ns/"},"ns-766a961f13a5":{"길":"좌표로 사다리꼴 넓이식을 세워 이차방정식을 풀고 사분면 조건으로 값을 고른다","단계":[{"제목":"점 A, B, C의 좌표 정하기","힌트":"y=1/2x+5에서 x=0이면 y는? 점 B, C의 좌표는?","식":["$A(0,5)$","$B\\left(a,\\frac{1}{2}a+5\\right)$","$C(a,0)$"],"설명":"y절편으로 A의 좌표를, 직선 위의 점으로 B와 C의 좌표를 구한다.","확인":null,"스킬":"G1"},{"제목":"사각형 넓이식 세우기","고비":true,"힌트":"사각형 ABCO를 사다리꼴로 보면 평행한 두 변과 높이는?","식":["$\\frac{1}{2}\\times\\left\\{\\left(\\frac{1}{2}a+5\\right)+5\\right\\}\\times(-a)=16$"],"설명":"사각형 ABCO를 사다리꼴로 보고 넓이 16이라는 조건으로 식을 세운다.","확인":null,"스킬":"G10"},{"제목":"이차방정식 풀기","힌트":"정리해 전개하면?","식":["$a^2+20a+64=0$","$(a+16)(a+4)=0$","$a=-16$ 또는 $a=-4$"],"설명":"넓이식을 정리해 인수분해하면 두 값의 a를 얻는다.","확인":null,"스킬":"A6"},{"제목":"사분면 조건으로 값 고르기","힌트":"점 B가 제2사분면 위에 있으려면 b는 양수여야 하지 않을까?","식":["$a=-16\\Rightarrow b=-3$","$a=-4\\Rightarrow b=3$","$a+b=-4+3=-1$"],"설명":"점 B가 제2사분면 위의 점이므로 b>0인 a=-4, b=3을 택하면 a+b=-1이다.","확인":"-1","스킬":"C2"}],"fb":"fig/ns/"},"ns-774970434267":{"길":"원래 그래프의 부호를 읽어 새 이차함수의 개형을 판별한다","단계":[{"제목":"원래 그래프의 부호 읽기","힌트":"아래로 볼록하고 축이 y축 오른쪽, y절편이 위쪽이면 a,b,c의 부호는?","식":[],"설명":"아래로 볼록하므로 a>0이고, 축이 y축 오른쪽에 있으므로 ab<0에서 b<0이며, y절편이 위쪽이므로 c>0이다.","확인":null,"스킬":"G7"},{"제목":"새 이차함수의 개형 정하기","힌트":"y=bx²-ax+c에서 b<0이면 볼록한 방향은?","식":[],"설명":"b<0이므로 위로 볼록하고, -ba>0이므로 축은 y축 왼쪽에 있으며, c>0이므로 y절편은 원점보다 위쪽이다.","확인":null,"스킬":"G7"},{"제목":"조건에 맞는 그래프 고르기","고비":true,"힌트":"위로 볼록·축이 y축 왼쪽·y절편이 양수인 그래프는?","식":[],"설명":"세 조건을 모두 만족하는 그래프는 ④이다.","확인":null,"스킬":"G7"}],"fb":"fig/ns/"},"ns-77c3e93624ab":{"길":"두 직각삼각형에서 tan x와 sin x를 각각 선분으로 나타내 차를 구한다","단계":[{"제목":"△OEF에서 tan x 구하기","힌트":"EF=1일 때 tan x°는 어떤 선분의 길이와 같을까?","식":["$\\tan x^\\circ=\\frac{\\overline{OF}}{\\overline{EF}}=\\overline{OF}$"],"설명":"반지름이 1인 사분원에서 EF=1이므로 tan x는 선분 OF의 길이와 같다.","확인":null,"스킬":"S6"},{"제목":"△OAB에서 sin x 구하기","힌트":"∠OAB=∠OEF=x°이고 OA=1일 때 sin x는 어떤 선분일까?","식":["$\\sin x^\\circ=\\frac{\\overline{OB}}{\\overline{OA}}=\\overline{OB}$"],"설명":"같은 각 x를 갖는 삼각형 OAB에서 빗변 OA가 1이므로 sin x는 선분 OB의 길이와 같다.","확인":null,"스킬":"S6"},{"제목":"두 선분의 차 구하기","고비":true,"힌트":"OF에서 OB를 빼면 남는 선분은 무엇일까?","식":["$\\tan x^\\circ-\\sin x^\\circ=\\overline{OF}-\\overline{OB}=\\overline{BF}$"],"설명":"같은 직선 위의 두 선분의 차이므로 tan x-sin x는 선분 BF의 길이와 같다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-78354c590568":{"길":"호의 비를 원주각의 비로 바꿔 각을 구하고, 내접사각형의 대각의 합으로 나머지 보기를 판별한다","단계":[{"제목":"호의 비를 원주각으로 바꿔 각 구하기","힌트":"호 AB:BC:CD=1:2:3이고 ∠AEB=20°이면 나머지 원주각은?","식":["$\\angle AEB:\\angle BEC:\\angle CED=1:2:3$","$\\angle BEC=40^{\\circ},\\ \\angle CED=60^{\\circ}$"],"설명":"호의 길이와 원주각은 비례하므로 세 원주각의 비도 1:2:3이며, ∠AEB=20°이므로 나머지 두 각을 구한다.","확인":null,"스킬":"S5"},{"제목":"ㄱ 판별하기","힌트":"호의 비가 현의 비와 같을까?","식":[],"설명":"호의 길이와 현의 길이는 정비례하지 않으므로 BC=2AB라 할 수 없어 ㄱ은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 판별하기","힌트":"∠ADC=∠ADB+∠BDC이고 각각 어떤 원주각과 같을까?","식":["$\\angle BDC=40^{\\circ},\\ \\angle ADB=20^{\\circ}$","$\\angle ADC=60^{\\circ}$"],"설명":"∠AEB:∠BDC=1:2이므로 ∠BDC=40°, ∠ADB=∠AEB=20°이므로 ∠ADC=60°이다.","확인":null,"스킬":"S5"},{"제목":"ㄷ, ㄹ 계산 위해 ∠BED 구하기","고비":true,"힌트":"∠BED=∠BEC+∠CED는?","식":["$\\angle BED=40^{\\circ}+60^{\\circ}=100^{\\circ}$"],"설명":"∠BED=100°이며, 내접사각형의 대각의 합이 180°임을 이용해 ㄷ, ㄹ을 각각 구한다.","확인":null,"스킬":"S5"},{"제목":"ㄷ 확정하기","힌트":"내접사각형 ACDE에서 ∠ACD는?","식":["$\\angle ACD=180^{\\circ}-120^{\\circ}=60^{\\circ}$","$\\overset{\\frown}{DCB}:\\overset{\\frown}{ADC}=100^{\\circ}:120^{\\circ}=5:6$"],"설명":"사각형 ACDE가 내접하므로 ∠ACD=60°이고 이를 이용해 호의 비를 구하면 5:6이므로 ㄷ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 확정하기","힌트":"내접사각형 BCDE에서 ∠BCD는?","식":["$\\angle BCD=180^{\\circ}-100^{\\circ}=80^{\\circ}$"],"설명":"사각형 BCDE가 내접하므로 ∠BCD=80°이므로 ㄹ도 옳다. 따라서 옳은 것은 ㄴ,ㄷ,ㄹ이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-78987289fa7e":{"길":"밀어서 겹친 반원의 넓이가 상쇄됨을 알아채 직사각형 부분의 넓이식으로 이차방정식을 세운다","단계":[{"제목":"겹치는 부분 상쇄 확인하기","힌트":"원을 밀었을 때 반원 두 개는 서로 어떻게 겹칠까?","식":["$\\frac{1}{2}\\pi x^2+2x(x+3)-\\frac{1}{2}\\pi x^2=36$"],"설명":"밀기 전후 겹치는 두 반원의 넓이는 서로 상쇄되고, 가운데 직사각형 모양의 넓이만 남는다.","확인":null,"스킬":"S12"},{"제목":"정리해 이차방정식 세우기","고비":true,"힌트":"반원 항을 지우고 정리하면?","식":["$2x(x+3)=36$","$x^2+3x-18=0$"],"설명":"반원 넓이가 상쇄되므로 직사각형 부분의 넓이 식만 남아 이차방정식을 얻는다.","확인":null,"스킬":"A6"},{"제목":"인수분해해 x 구하기","힌트":"인수분해하면?","식":["$(x+6)(x-3)=0$","$x=3\\ (\\because x>0)$"],"설명":"인수분해한 뒤 x가 자연수(양수)라는 조건으로 x=3을 고른다.","확인":"3","스킬":"C2"}],"fb":"fig/ns/"},"ns-78e92fef61ab":{"길":"정오각형의 각도로 닮은 삼각형을 찾아 이차방정식을 세우고 양수인 근을 고른다","단계":[{"제목":"정오각형 내각과 이등변삼각형 각 구하기","힌트":"정오각형의 한 내각과 이등변삼각형 ABC의 밑각은?","식":["$108^\\circ,\\ \\angle BAC=\\angle BCA=36^\\circ$"],"설명":"정오각형의 한 내각은 108°이고, AB=BC인 이등변삼각형 ABC의 두 밑각은 각각 36°이다.","확인":null,"스킬":"S10"},{"제목":"닮은 삼각형 찾기","고비":true,"힌트":"삼각형 ABC와 AFB는 어떤 관계일까?","식":["$\\triangle ABC\\sim\\triangle AFB$","$\\overline{CB}=\\overline{CF}=4$"],"설명":"두 삼각형이 서로 닮음임을 찾아내면 CF=CB=4임을 알 수 있다.","확인":null,"스킬":"S1"},{"제목":"비례식으로 이차방정식 세우기","힌트":"AB:AF=AC:AB 비례식을 쓰면?","식":["$4:(x-4)=x:4$","$x^2-4x-16=0$"],"설명":"닮음비로 비례식을 세워 정리하면 이차방정식을 얻는다.","확인":null,"스킬":"S1"},{"제목":"근의 공식으로 근 고르기","힌트":"근의 공식으로 풀어 양수인 근을 고르면?","식":["$x=2\\pm2\\sqrt{5}$","$x=2+2\\sqrt{5}\\ (\\because x>0)$"],"설명":"근의 공식으로 두 근을 구해 양수 조건을 만족하는 값을 고른다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-79fa6f475611":{"길":"두 번의 RHS합동으로 각을 문자로 놓아 합을 구하고, 닮음의 비 순서와 접선의 길이 합을 확인한다","단계":[{"제목":"①CD쪽 RHS합동 확인하기","힌트":"OD 공통, ∠OCD=∠OED=90°, OC=OE이면?","식":["$\\triangle COD\\equiv\\triangle EOD$"],"설명":"OD가 공통이고 두 직각이 같으며 OC=OE(반지름)이므로 RHS합동이다.","확인":null,"스킬":"S5"},{"제목":"②AB쪽 RHS합동 확인하기","힌트":"BO 공통, ∠OAB=∠OEB=90°, AO=EO이면?","식":["$\\triangle AOB\\equiv\\triangle EOB$"],"설명":"BO가 공통이고 두 직각이 같으며 AO=EO(반지름)이므로 RHS합동이다. 따라서 ∠ABO=∠EBO이다.","확인":null,"스킬":"S5"},{"제목":"③각을 문자로 놓고 합 구하기","고비":true,"힌트":"∠COD=∠EOD=a, ∠AOB=∠EOB=b라 하면 2a+2b는?","식":["$2a+2b=180^{\\circ}$","$a+b=90^{\\circ}$"],"설명":"AC가 지름이므로 두 합동에서 나온 각을 a, b라 하면 2a+2b=180°에서 a+b=90°이고, ∠BOD=a+b=90°이다.","확인":null,"스킬":"S2"},{"제목":"④닮음의 비 순서 확인하기","힌트":"△BOE∽△ODE에서 대응변의 비는 OB:DO=BE:OE일까, OB:OD=BE:ED일까?","식":["$\\overline{OB}:\\overline{DO}=\\overline{BE}:\\overline{OE}$"],"설명":"AA닮음에서 나오는 옳은 비는 OB:DO=BE:OE이므로, OB:OD=BE:ED라고 한 ④는 옳지 않다.","확인":null,"스킬":"S1"},{"제목":"⑤접선의 길이로 BD 표현하기","힌트":"AB=BE, CD=DE이면 AB+CD는?","식":["$\\overline{AB}+\\overline{CD}=\\overline{BE}+\\overline{DE}=\\overline{BD}$"],"설명":"접선의 길이가 같으므로 AB=BE, CD=DE이고 AB+CD=BD가 성립한다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-79fd1ed93706":{"길":"같은 원주각에 대한 현·삼각부등식·호의 비를 차례로 확인하고 합동은 근거 부족임을 가려낸다","단계":[{"제목":"ㄱ 판별하기","힌트":"원주각의 크기가 같으면 현의 길이는?","식":["$\\overline{AB}=\\overline{CD}=\\overline{DE}$"],"설명":"∠ACB=∠CBD=∠DBE이므로 원주각이 같은 호에 대한 현의 길이도 같아 AB=CD=DE이다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 판별하기","힌트":"2AB와 CD+DE를 비교하면 삼각부등식으로?","식":["$2\\overline{AB}=\\overline{CD}+\\overline{DE}>\\overline{CE}$"],"설명":"AB=CD=DE이므로 2AB=CD+DE이고, 삼각부등식에 의해 CD+DE>CE이므로 ㄴ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄷ 판별하기","고비":true,"힌트":"원주각의 비와 호의 비는 같으므로 AB:CE는?","식":["$\\overset{\\frown}{AB}:\\overset{\\frown}{CE}=\\angle ACB:\\angle CBE=1:2$"],"설명":"원주각과 호는 비례하므로 AB:CE=1:2이며 CE=2AB이므로 ㄷ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄹ 판별하기","힌트":"△CBA와 △BCD가 합동이려면 어떤 조건이 더 필요할까?","식":[],"설명":"두 삼각형이 합동임을 보일 조건이 부족하므로 ㄹ은 항상 성립한다고 할 수 없다. 따라서 옳은 것은 ㄱ,ㄴ,ㄷ이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-7c5c4d6c66b1":{"길":"높이의 발이 무게중심임을 찾아 삼각비를 구하고 다섯 문장을 하나씩 확인한다","단계":[{"제목":"DE의 길이 구하기","힌트":"△DCE에서 tan60°=DE/3을 풀면?","식":["$\\tan60^\\circ=\\frac{\\overline{DE}}{3}=\\sqrt3\\Rightarrow\\overline{DE}=3\\sqrt3$"],"설명":"정삼각형 DBC에서 tan60°를 이용해 DE를 구한다.","확인":null,"스킬":"S6"},{"제목":"AE 구하고 수선의 발 H 찾기","힌트":"정사면체의 대칭으로 AE와 DE, 무게중심 H의 위치는?","식":["$\\overline{AE}=\\overline{DE}=3\\sqrt3$","$\\overline{EH}=\\frac13\\overline{DE}=\\sqrt3$"],"설명":"정사면체의 대칭성으로 AE=DE이고, A에서 DE에 내린 수선의 발 H는 △BCD의 무게중심이므로 EH는 DE의 1/3이다.","확인":null,"스킬":"S7"},{"제목":"AH 구하기","힌트":"직각삼각형 AEH에서 피타고라스 정리를 쓰면?","식":["$\\overline{AH}=\\sqrt{(3\\sqrt3)^2-(\\sqrt3)^2}=2\\sqrt6$"],"설명":"피타고라스 정리로 높이 AH를 구한다.","확인":null,"스킬":"S3"},{"제목":"sin x, cos x, tan x 구하기","힌트":"AH/AE, EH/AE, AH/EH는 각각 얼마일까?","식":["$\\sin x=\\frac{2\\sqrt6}{3\\sqrt3}=\\frac{2\\sqrt2}{3}$","$\\cos x=\\frac13$","$\\tan x=2\\sqrt2$"],"설명":"직각삼각형 AEH에서 세 삼각비를 구한다.","확인":null,"스킬":"S6"},{"제목":"ㄷ,ㄹ,ㅁ 계산해 판별하기","고비":true,"힌트":"tan x-sin x, △ABC, △AED의 값을 각각 계산하면?","식":["$\\tan x-\\sin x=\\frac{4\\sqrt2}{3}$","$\\triangle ABC=9\\sqrt3$","$\\triangle AED=9\\sqrt2$"],"설명":"앞서 구한 삼각비로 세 값을 계산하면 ㄷ, ㄹ은 참이다. ㅁ은 실제 값이 9√2인데 진술은 18√2이므로 거짓이다.","확인":null,"스킬":"C3"},{"제목":"참인 보기 개수 세기","힌트":"ㄱ~ㅁ 중 참인 것은 모두 몇 개일까?","식":["참인 것: ㄱ, ㄴ, ㄷ, ㄹ"],"설명":"다섯 문장 중 네 개(ㄱ,ㄴ,ㄷ,ㄹ)가 참이므로 답은 4개다.","확인":"4","스킬":"C3"}],"fb":"fig/ns/"},"ns-7cd78040a58c":{"길":"정사각형의 넓이로 한 변을 구하고 수직선에서 a, b를 읽어 뺀다","단계":[{"제목":"정사각형의 한 변 구하기","힌트":"넓이가 3인 정사각형의 한 변은?","식":["$\\text{한 변}=\\sqrt3$"],"설명":"정사각형의 넓이가 3이므로 한 변의 길이는 √3이다.","확인":null,"스킬":"N8"},{"제목":"a 구하기","고비":true,"힌트":"3에서 √3만큼씩 두 번 왼쪽으로 가면 a는?","식":["$a=3-\\sqrt3-\\sqrt3=3-2\\sqrt3$"],"설명":"그림에 표시된 두 구간이 모두 √3이므로 3에서 √3을 두 번 빼면 a이다.","확인":null,"스킬":"S4"},{"제목":"b 구하고 a-b 계산하기","힌트":"3에서 √3만큼 오른쪽으로 가면 b는?","식":["$b=3+\\sqrt3$","$a-b=(3-2\\sqrt3)-(3+\\sqrt3)=-3\\sqrt3$"],"설명":"b=3+√3이므로 a에서 b를 빼면 -3√3이다.","확인":null,"스킬":"S4"}],"fb":"fig/ns/"},"ns-7e1fc6a97552":{"길":"각 삼각형의 접선 길이가 같음을 이용해 PF를 x로 놓고 사슬을 따라 각 변의 길이를 구한다","단계":[{"제목":"PF를 x로 놓기","힌트":"네 원의 접선 길이는 모두 같으므로 PF, PK, PL, PM, PN을 어떻게 나타낼까?","식":["$\\overline{PF}=\\overline{PK}=\\overline{PL}=\\overline{PM}=\\overline{PN}=x$"],"설명":"각 내접원에서 접선의 길이가 같으므로 다섯 접선 길이를 모두 x로 놓는다.","확인":null,"스킬":"S5"},{"제목":"AF, AG 구하기","힌트":"PA=25에서 PF=x를 빼면?","식":["$\\overline{AF}=\\overline{AG}=25-x$"],"설명":"삼각형 PAB의 내접원에서 접선 길이가 같으므로 AF=AG이고, PA=25이므로 25-x이다.","확인":null,"스킬":"S5"},{"제목":"BG, BK, BH 구하기","힌트":"AB=20에서 AG를 빼면?","식":["$\\overline{BG}=\\overline{BK}=\\overline{BH}=20-(25-x)=x-5$"],"설명":"AB=20이므로 AG를 뺀 나머지가 BG, BK, BH이다.","확인":null,"스킬":"S5"},{"제목":"CH, CL, CI 구하기","힌트":"BC=15에서 BH를 빼면?","식":["$\\overline{CH}=\\overline{CL}=\\overline{CI}=15-(x-5)=20-x$"],"설명":"BC=15이므로 BH를 뺀 나머지가 CH, CL, CI이다.","확인":null,"스킬":"S5"},{"제목":"DI, DM, DJ 구하기","고비":true,"힌트":"CD=10에서 CI를 빼면?","식":["$\\overline{DI}=\\overline{DM}=\\overline{DJ}=10-(20-x)=x-10$"],"설명":"부호가 계속 바뀌는 사슬이 여기서 가장 헷갈리므로 CD=10에서 CI를 뺀다.","확인":null,"스킬":"S5"},{"제목":"PE 구하기","힌트":"DE=5에서 DJ를 빼고 PN+EN을 더하면?","식":["$\\overline{EJ}=\\overline{EN}=5-(x-10)=15-x$","$\\overline{PE}=\\overline{PN}+\\overline{EN}=x+(15-x)=15$"],"설명":"DE=5에서 DJ를 뺀 EN을 구하고, PN과 더하면 x가 사라져 PE=15가 된다.","확인":"15","스킬":"S5"}],"fb":"fig/ns/"},"ns-7e2c28f62b45":{"길":"OD=OE=OF에서 세 현이 같음을 이끌어 정삼각형의 성질로 각 보기를 확인한다","단계":[{"제목":"정삼각형 확인하기","힌트":"원의 중심에서 세 변까지의 거리가 같으면 세 변의 길이는?","식":["$\\overline{OD}=\\overline{OE}=\\overline{OF}\\Rightarrow \\overline{AB}=\\overline{BC}=\\overline{CA}$"],"설명":"중심에서 같은 거리에 있는 현은 길이가 같으므로 삼각형 ABC는 정삼각형이다.","확인":null,"스킬":"S5"},{"제목":"① ~ ③ 확인하기","힌트":"정삼각형의 한 내각과 중점까지의 거리는?","식":["$\\angle A=60^{\\circ}$","$\\overline{AD}=\\frac{1}{2}\\overline{AB}=6\\sqrt{3}$"],"설명":"정삼각형이므로 내각은 60°이고, D는 AB의 중점이므로 AD는 AB의 절반이다.","확인":null,"스킬":"S2"},{"제목":"④ 확인하기","힌트":"BE, AF도 각각 절반일까?","식":["$\\overline{BE}=\\frac{1}{2}\\overline{BC}=6\\sqrt{3}=\\overline{AF}$"],"설명":"같은 방법으로 BE와 AF도 6√3이므로 서로 같다.","확인":null,"스킬":"S2"},{"제목":"⑤ 각 EOF 계산하기","고비":true,"힌트":"사각형 OECF의 나머지 각을 360°에서 빼면?","식":["$\\angle EOF=360^{\\circ}-(90^{\\circ}+60^{\\circ}+90^{\\circ})=120^{\\circ}$"],"설명":"사각형 OECF의 네 내각의 합이 360°임을 이용하면 ∠EOF는 120°이므로 150°라는 ⑤는 옳지 않다.","확인":"120","스킬":"S10"}],"fb":"fig/ns/"},"ns-8592bbb8fbbf":{"길":"점들이 흩어진 방향을 보고 상관관계의 종류를 판별한다","단계":[{"제목":"점들의 전체적인 추세 보기","힌트":"x가 커질수록 y도 대체로 커지는가?","식":[],"설명":"돼지고기 소비량이 늘수록 물가지수도 대체로 높아지는 추세가 보인다.","확인":null,"스킬":"C3"},{"제목":"양의 상관관계로 판정하기","고비":true,"힌트":"이런 추세를 무엇이라 부를까?","식":[],"설명":"한 변량이 커질 때 다른 변량도 커지는 경향이므로 양의 상관관계이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-859957e2f9fe":{"길":"접선 길이가 같음을 이용해 x에 대한 방정식을 세우고, 삼각형 PDC의 둘레가 2PA로 정리됨을 확인한다","단계":[{"제목":"CA, DB를 x로 놓기","힌트":"CA=CE=x라 하면 DE=DB는?","식":["$\\overline{CA}=\\overline{CE}=x,\\ \\overline{DE}=\\overline{DB}=6-x$"],"설명":"C, D에서 그은 접선의 길이가 같음을 이용해 CE, DE를 x로 나타낸다.","확인":null,"스킬":"S5"},{"제목":"PA=PB로 방정식 세우기","고비":true,"힌트":"PA=PB를 CA, DB로 나타내면?","식":["$7+x=9+(6-x)$","$2x=8,\\ x=4$"],"설명":"PA=PB이므로 두 식을 세워 x=4를 구한다.","확인":null,"스킬":"C7"},{"제목":"① ~ ④ 확인하기","힌트":"DB, PE와 PD, CE와 AO를 비교하면?","식":["$\\overline{DB}=6-4=2$"],"설명":"①은 AC=x=4로 3이 아니고, ②는 DB=2로 1이 아니며, ③은 PE≠PD, ④는 CE=CA로 AO와 다르므로 모두 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"⑤ 둘레 확인하기","힌트":"PC+CD+PD를 CA, DB로 바꿔 더하면?","식":["$\\overline{PC}+\\overline{CD}+\\overline{PD}=\\overline{PC}+\\overline{CA}+\\overline{DB}+\\overline{PD}=\\overline{PA}+\\overline{PB}=2\\overline{PA}$"],"설명":"둘레를 접선 길이로 바꿔 더하면 PA와 PB의 합, 즉 2PA와 같아진다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-893ea4477f00":{"길":"삼각비를 사분원의 선분으로 나타내고 반례로 옳지 않은 것을 찾는다","단계":[{"제목":"삼각비를 선분으로 나타내기","힌트":"sinx, cosx, tanx를 사분원의 선분으로 쓰면?","식":["$\\sin x^\\circ=\\overline{DA},\\ \\cos x^\\circ=\\overline{OA},\\ \\tan x^\\circ=\\overline{BC}$"],"설명":"반지름 1인 사분원에서 세 삼각비를 각각 선분의 길이로 나타낸다.","확인":null,"스킬":"T5"},{"제목":"② 반례로 판별하기","고비":true,"힌트":"x=45°일 때 cosx와 tanx의 크기를 비교하면?","식":["$x=45일\\ 때\\ \\overline{DA}=\\overline{OA},\\ \\overline{DA}<\\overline{BC}$"],"설명":"이 경우 sinx=cosx이고 sinx<tanx이므로 cosx<tanx가 되어 ②(tanx<cosx)는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"①,③,④,⑤ 확인하기","힌트":"각 진술을 선분의 변화로 확인하면?","식":[],"설명":"나머지 네 진술은 x가 0 또는 90에 가까워질 때 선분들이 어떻게 변하는지 보면 모두 옳다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-8a51850b9480":{"길":"OB를 구해 표에서 각을 찾고 그 각의 sin값으로 AB를 구한다","단계":[{"제목":"OB 구하기","힌트":"OD=1, BD=0.43이면 OB는?","식":["$\\overline{OB}=1-0.43=0.57$"],"설명":"반지름에서 BD를 빼서 OB를 구한다.","확인":"0.57","스킬":"S6"},{"제목":"각 x 찾기","고비":true,"힌트":"cos x = OB = 0.57이 되는 각은 표에서 몇 도일까?","식":["$\\cos x^\\circ=\\overline{OB}=0.57\\Rightarrow x=55$"],"설명":"삼각비 표에서 cos55°=0.57이므로 x=55°이다.","확인":"55","스킬":"S6"},{"제목":"AB 값 구하기","힌트":"AB=sin x이므로 표에서 sin55°는?","식":["$\\overline{AB}=\\sin55^\\circ=0.82$"],"설명":"표에서 sin55°를 찾으면 AB=0.82이다.","확인":"0.82","스킬":"S6"}],"fb":"fig/ns/"},"ns-8b3c30738511":{"길":"중심각이 같은 두 성질(현의 길이, 호의 비례)을 보기에 하나씩 적용해 판별한다","단계":[{"제목":"ㄱ 판별하기","힌트":"중심각이 같으면 현의 길이는?","식":["$\\angle AOB=\\angle DOE \\Rightarrow \\overline{AB}=\\overline{DE}$"],"설명":"중심각의 크기가 같으면 현의 길이도 같으므로 ㄱ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 판별하기","고비":true,"힌트":"∠AOC와 ∠BOE의 크기가 같다고 알 수 있을까?","식":[],"설명":"∠AOC와 ∠BOE가 같은지는 주어진 조건만으로 알 수 없으므로 호 AC=호 BE인지 알 수 없어 ㄴ은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"ㄷ 판별하기","힌트":"중심각과 호의 길이는 어떤 관계일까?","식":["$\\angle AOB=\\frac{1}{2}\\angle COE$"],"설명":"중심각의 크기와 호의 길이는 비례하므로 호 AB는 호 CE의 절반이다. ㄷ은 옳다.","확인":null,"스킬":"S5"},{"제목":"옳은 것 고르기","힌트":"ㄱ과 ㄷ만 옳다면?","식":[],"설명":"옳은 것은 ㄱ, ㄷ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-8ba060befa8d":{"길":"원의 둘레 a를 구한 뒤 다섯 선지가 유리수인지 무리수인지 확인한다","단계":[{"제목":"원의 둘레 a 구하기","힌트":"반지름이 2인 원의 둘레는?","식":["$a=2\\pi\\times2=4\\pi$"],"설명":"원이 한 바퀴 굴렀으므로 a는 원의 둘레와 같아 a=4π이다.","확인":null,"스킬":"N6"},{"제목":"①~④ 확인하기","힌트":"2a, a, 4π-a, a+√2는 각각 유리수일까 무리수일까?","식":["$4\\pi-a=0$"],"설명":"①,②,④는 무리수이고 ③ 4π-a=0은 유리수이므로 모두 옳다.","확인":null,"스킬":"N6"},{"제목":"⑤ 확인하기","고비":true,"힌트":"a-3=4π-3을 m/n 꼴로 나타낼 수 있을까?","식":["$a-3=4\\pi-3$"],"설명":"4π-3은 무리수이므로 정수 m, n으로 만든 분수 꼴로 나타낼 수 없어 ⑤가 옳지 않다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-8d234abf05e6":{"길":"꼭짓점 좌표로 넓이를 세워 p를 구한 뒤 평행이동한 식을 쓴다","단계":[{"제목":"완전제곱으로 꼭짓점 P 구하기","힌트":"y=x²-2x-3을 완전제곱 꼴로 바꾸면?","식":["$y=(x-1)^{2}-4$"],"설명":"완전제곱으로 바꾸면 꼭짓점 P의 좌표는 (1,-4)이다.","확인":null,"스킬":"A6"},{"제목":"넓이 조건으로 p 구하기","고비":true,"힌트":"색칠한 부분의 넓이가 폭 p, 높이 4인 직사각형과 같다면?","식":["$4p=20\\ \\Rightarrow\\ p=5$"],"설명":"두 꼭짓점의 y좌표가 같아 색칠한 부분은 폭 p, 높이 4인 직사각형이 되므로 4p=20에서 p=5이다.","확인":"5","스킬":"G4"},{"제목":"평행이동한 식 구하기","힌트":"y=(x-1)²-4를 x축의 방향으로 5만큼 평행이동하면?","식":["$y=(x-6)^{2}-4=x^{2}-12x+32$"],"설명":"x축의 방향으로 5만큼 평행이동하면 y=x²-12x+32이다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-8e8e127ff2a6":{"길":"평행선의 엇각과 원주각으로 두 삼각형이 합동임을 보이고, 나머지 보기는 판단할 수 없음을 확인한다","단계":[{"제목":"각 관계 세우기","힌트":"AD∥BC에서 엇각과 원주각을 연결하면?","식":["$\\angle ACB=\\angle CAD,\\ \\angle ACB=\\angle ADB,\\ \\angle ADB=\\angle DBC$"],"설명":"평행선의 엇각과 같은 호에 대한 원주각을 이어 ∠ACB=∠DBC를 얻는다.","확인":null,"스킬":"S10"},{"제목":"△ABC≡△DCB 보이기","고비":true,"힌트":"BC가 공통이고 두 쌍의 각이 같다면?","식":["$\\triangle ABC\\equiv \\triangle DCB\\ (ASA\\ 합동)$"],"설명":"BC 공통, ∠BAC=∠CDB, ∠ACB=∠DBC이므로 ASA 합동이다.","확인":null,"스킬":"S5"},{"제목":"㈀ 확인하기","힌트":"합동이면 대응변 AB, CD는?","식":["$\\overline{AB}=\\overline{CD}$"],"설명":"합동인 두 삼각형의 대응변이므로 AB=CD이다. ㈀은 옳다.","확인":null,"스킬":"S5"},{"제목":"㈁, ㈃ 판별하기","힌트":"AB∥CD, 호AD=호BC인지 알 수 있을까?","식":[],"설명":"주어진 조건만으로는 AB∥CD인지, 호AD=호BC인지 알 수 없으므로 ㈁, ㈃은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"㈂ 확인하기","힌트":"엇각으로 이미 확인한 각은?","식":["$\\angle ACB=\\angle CAD$"],"설명":"1단계에서 이미 확인했으므로 ㈂은 옳다. 따라서 옳은 것은 ㈀, ㈂이다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-8f638bfb67c8":{"길":"접선과 반지름이 이루는 직각삼각형에서 특수각 비율로 각을 구하고, 나머지 성질을 확인한다","단계":[{"제목":"PO 구하기","힌트":"직각삼각형 PAO에서 피타고라스 정리를 쓰면?","식":["$\\overline{PO}=\\sqrt{(2\\sqrt3)^2+2^2}=4$"],"설명":"∠PAO=90°인 직각삼각형에서 PO를 구한다.","확인":null,"스킬":"S3"},{"제목":"∠APB 구하기","고비":true,"힌트":"PO:AO=2:1이면 각도는?","식":["$\\angle APO=30^{\\circ}$","$\\angle APB=2\\times30^{\\circ}=60^{\\circ}$"],"설명":"변의 비가 2:1인 직각삼각형이므로 ∠APO=30°이고, ∠APB는 그 두 배인 60°이다. 따라서 30°라는 ③은 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"①, ④, ⑤ 확인하기","힌트":"합동인 두 삼각형과 접선의 성질을 확인하면?","식":[],"설명":"①의 PO=4는 맞고, ④의 ∠PAO=∠PBO=90°도 맞으며, ⑤의 △PAO≡△PBO(RHS 합동)도 맞다.","확인":null,"스킬":"S5"},{"제목":"② 확인하기","힌트":"△PAB는 어떤 삼각형일까?","식":[],"설명":"PA=PB이고 ∠APB=60°이므로 △PAB는 정삼각형이라 PA=AB도 맞다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-8f9b4145522b":{"길":"원주각의 성질과 각 이등분 조건으로 두 쌍의 각을 잡아 닮음을 만들고, 대응변의 곱 관계를 확인한다","단계":[{"제목":"(ㄱ) 판별하기","힌트":"호 AC에 대한 원주각은?","식":["$\\angle ABC=\\angle AEC$"],"설명":"같은 호 AC에 대한 원주각이므로 ∠ABC=∠AEC이다. (ㄱ)은 옳다.","확인":null,"스킬":"S5"},{"제목":"(ㄴ) 판별하기","힌트":"∠CBE, ∠BCE를 각 이등분 조건으로 바꾸면?","식":["$\\angle CBE=\\angle CAE,\\ \\angle BCE=\\angle BAE$"],"설명":"∠BAE=∠CAE(각 이등분)이므로 ∠CBE=∠BCE이다. (ㄴ)은 옳다.","확인":null,"스킬":"S5"},{"제목":"닮음 만들기","고비":true,"힌트":"△ABD와 △AEC에서 같은 각 두 쌍은?","식":["$\\angle ABD=\\angle AEC,\\ \\angle BAD=\\angle EAC$"],"설명":"두 각이 같으므로 △ABD∽△AEC(AA닮음)이다.","확인":null,"스킬":"S5"},{"제목":"(ㄷ) 판별하기","힌트":"닮음에서 대응변의 곱은 AB×AC=AD×?","식":["$\\overline{AB}:\\overline{AE}=\\overline{AD}:\\overline{AC}\\Rightarrow \\overline{AB}\\times\\overline{AC}=\\overline{AD}\\times\\overline{AE}$"],"설명":"닮음비에서 AB×AC=AD×AE가 되어야 하므로 AD×DE라 한 (ㄷ)은 옳지 않다. 옳은 것은 (ㄱ),(ㄴ)이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-90c7f4425734":{"길":"보조선으로 닮은 두 삼각형을 찾아 닮음비로 값을 구한다","단계":[{"제목":"보조선 긋기","힌트":"점 P에서 RC(또는 그 연장선)에 내린 수선의 발 H를 잡으면?","식":[],"설명":"점 P에서 선분 RC에 내린 수선의 발을 H라 한다.","확인":null,"스킬":"S2"},{"제목":"닮음인 두 삼각형 찾기","고비":true,"힌트":"△RPH와 △PBQ는 어떤 관계일까?","식":["$\\triangle RPH\\backsim\\triangle PBQ\\ (AA\\ 닮음)$"],"설명":"두 삼각형의 대응각이 같아 AA 닮음이 성립한다.","확인":null,"스킬":"S1"},{"제목":"닮음비로 값 구하기","힌트":"닮음비를 이용해 QC/PR을 구하면?","식":["$\\frac{\\overline{QC}}{\\overline{PR}}=\\frac{\\overline{PH}}{\\overline{PR}}=\\frac{\\overline{BQ}}{\\overline{BP}}=\\cos50^\\circ$"],"설명":"닮음비를 정리하면 QC/PR은 cos50°와 같다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-9484a662a60c":{"길":"세 반의 평균과 분산을 각각 계산해 다섯 보기를 판별한다","단계":[{"제목":"A반 평균·분산 구하기","힌트":"A반 도수분포를 평균·분산식에 넣으면?","식":["$평균=\\frac{3\\times2+4\\times2+5\\times2+6\\times2+7\\times2}{10}=5$","$분산=\\frac{(-2)^2\\times2+(-1)^2\\times2+0^2\\times2+1^2\\times2+2^2\\times2}{10}=2$"],"설명":"A반의 평균은 5권, 분산은 2이다.","확인":null,"스킬":"C3"},{"제목":"B반 평균·분산 구하기","힌트":"B반도 같은 방법으로 계산하면?","식":["$평균=\\frac{3\\times3+4\\times1+5\\times2+6\\times1+7\\times3}{10}=5$","$분산=\\frac{(-2)^2\\times3+(-1)^2\\times1+0^2\\times2+1^2\\times1+2^2\\times3}{10}=2.6$"],"설명":"B반의 평균은 5권, 분산은 2.6이다.","확인":null,"스킬":"C3"},{"제목":"C반 평균·분산 구하기","고비":true,"힌트":"C반도 같은 방법으로 계산하면?","식":["$평균=\\frac{3\\times1+4\\times2+5\\times4+6\\times2+7\\times1}{10}=5$","$분산=\\frac{(-2)^2\\times1+(-1)^2\\times2+0^2\\times4+1^2\\times2+2^2\\times1}{10}=1.2$"],"설명":"C반의 평균은 5권, 분산은 1.2이다.","확인":null,"스킬":"C3"},{"제목":"보기 판별하기","힌트":"분산이 가장 작은 반, 가장 큰 반, 평균이 모두 같은지 확인하면?","식":[],"설명":"C반의 분산이 가장 작아 ㄷ이 옳고, 세 반의 평균이 모두 5로 같아 ㄹ도 옳다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-94cc24e63ec7":{"길":"접선 길이로 CD를 구하고, C에서 BD에 내린 수선으로 피타고라스 정리를 써 AB를 구한 뒤 각 보기를 확인한다","단계":[{"제목":"CA, DB 구하기","힌트":"접선의 길이가 같으므로 CE, DE는?","식":["$\\overline{CA}=\\overline{CE}=4,\\ \\overline{DB}=\\overline{DE}=6$"],"설명":"접선의 성질에 의해 CA=CE=4, DB=DE=6이다.","확인":null,"스킬":"S5"},{"제목":"CD 구하기","힌트":"CE+ED를 더하면?","식":["$\\overline{CD}=4+6=10$"],"설명":"CD는 CE와 ED의 합이므로 10이다.","확인":null,"스킬":"S5"},{"제목":"보조선으로 AB 구하기","고비":true,"힌트":"C에서 BD에 내린 수선의 발을 H라 하면?","식":["$\\overline{HD}=6-4=2,\\ \\overline{CH}=\\sqrt{10^2-2^2}=4\\sqrt6$"],"설명":"직각삼각형 CDH에서 피타고라스 정리를 쓰면 CH=AB=4√6이다. ①은 옳다.","확인":null,"스킬":"S2"},{"제목":"② 확인하기","힌트":"두 쌍의 합동삼각형에서 각을 더하면 180°는?","식":["$\\angle COE+\\angle DOE=\\angle COD=90^{\\circ}$"],"설명":"합동인 삼각형들의 각을 더하면 ∠COD=90°이다. ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"③, ④ 확인하기","힌트":"△DOB≡△DOE, △AOC≡△EOC이면?","식":[],"설명":"RHS 합동으로 ∠EOD=∠BOD(③), △AOC≡△EOC(④) 모두 옳다.","확인":null,"스킬":"S5"},{"제목":"⑤ 넓이 확인하기","힌트":"△BOD의 넓이는 밑변 DB, 높이 AB/2로 구하면?","식":["$\\triangle BOD=\\frac12\\times2\\sqrt6\\times6=6\\sqrt6$"],"설명":"실제 넓이는 6√6이므로 12√6이라 한 ⑤는 옳지 않다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-9cad7e5ee980":{"길":"두 절편으로 큰 삼각형 넓이를 구하고, 작은 삼각형 넓이 조건을 좌표식으로 세워 완전제곱 이차방정식을 푼다","단계":[{"제목":"두 절편 A, B의 좌표 구하기","힌트":"y=0, x=0을 각각 대입하면?","식":["$\\mathrm{A}(6,\\,0),\\ \\mathrm{B}(0,\\,12)$"],"설명":"직선 y=-2x+12에 y=0을 대입하면 x=6, x=0을 대입하면 y=12이므로 두 절편을 구한다.","확인":null,"스킬":"G1"},{"제목":"△AOB의 넓이로 △MOP의 넓이 구하기","힌트":"큰 삼각형 넓이의 1/4은?","식":["$\\triangle\\mathrm{AOB}=\\frac12\\times6\\times12=36$","$\\triangle\\mathrm{MOP}=\\frac14\\times36=9$"],"설명":"조건에서 △MOP의 넓이는 △AOB 넓이의 1/4이므로 9이다.","확인":"9","스킬":"G10"},{"제목":"점 P의 좌표로 넓이식 세우기","고비":true,"힌트":"M(0,-2a+12), P(a,-2a+12)이면 직각삼각형 MOP의 두 변은?","식":["$\\frac12\\times a\\times(-2a+12)=9$"],"설명":"P의 좌표를 (a,-2a+12)라 하면 M은 (0,-2a+12)이고, OM과 MP를 두 변으로 하는 직각삼각형의 넓이를 세운다.","확인":null,"스킬":"G10"},{"제목":"완전제곱식으로 정리해 a 구하기","힌트":"정리하면 어떤 완전제곱식이 될까?","식":["$a^2-6a+9=0$","$(a-3)^2=0$","$a=3$"],"설명":"정리하면 완전제곱식이 되어 a=3인 중근 하나만 나오므로 점 P의 좌표는 (3,6)이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-9f28ffd3865e":{"길":"x좌표는 홀수항끼리, y좌표는 짝수항끼리 두 개씩 묶어 합차공식으로 계산한다","단계":[{"제목":"이동을 좌표로 나타내기","힌트":"동서 이동은 x좌표, 남북 이동은 y좌표에 부호를 붙이면?","식":["$x:1^2-3^2+5^2-7^2+9^2-11^2+13^2$","$y:2^2-4^2+6^2-8^2+10^2-12^2$"],"설명":"동쪽·서쪽은 x좌표에, 북쪽·남쪽은 y좌표에 부호를 번갈아 붙여 나타낸다.","확인":null,"스킬":"P1"},{"제목":"x좌표를 두 개씩 묶어 계산하기","고비":true,"힌트":"인접한 두 제곱을 합차공식으로 묶으면?","식":["$(1+3)(1-3)+(5+7)(5-7)+(9+11)(9-11)+13^2$","$=-2(1+3+5+7+9+11)+169=-72+169=97$"],"설명":"앞의 여섯 항을 두 개씩 묶어 합차공식으로 계산하고 마지막 13²을 더한다.","확인":"97","스킬":"A6"},{"제목":"y좌표를 두 개씩 묶어 계산하기","힌트":"y좌표도 같은 방법으로 묶으면?","식":["$(2+4)(2-4)+(6+8)(6-8)+(10+12)(10-12)$","$=-2(2+4+6+8+10+12)=-2\\times3\\times14=-84$"],"설명":"y좌표의 여섯 항을 모두 두 개씩 묶어 합차공식으로 계산한다.","확인":"-84","스킬":"A6"},{"제목":"좌표 정리하기","힌트":"구한 x, y값을 순서쌍으로 쓰면?","식":["$(97,\\,-84)$"],"설명":"13일 후 거북이의 위치는 (97, -84)이다.","확인":null,"스킬":"P1"}],"fb":"fig/ns/"},"ns-9fd115c48628":{"길":"배수 관계를 거꾸로 적용해 넓이를 구한 뒤 제곱근으로 변의 길이를 얻는다","단계":[{"제목":"B, C의 넓이 구하기","힌트":"A가 B의 √3배이면 B, C의 넓이는?","식":["$B=2\\sqrt{3}\\times\\frac{1}{\\sqrt{3}}=2$","$C=2\\times\\frac{1}{\\sqrt{3}}=\\frac{2}{\\sqrt{3}}$"],"설명":"주어진 배수 관계를 거꾸로 적용해 B, C의 넓이를 차례로 구한다.","확인":null,"스킬":"A8"},{"제목":"D의 넓이 구하기","고비":true,"힌트":"C를 √3으로 한 번 더 나누면?","식":["$D=\\frac{2}{\\sqrt{3}}\\times\\frac{1}{\\sqrt{3}}=\\frac{2}{3}$"],"설명":"같은 비율을 한 번 더 적용해 D의 넓이 2/3을 얻는다.","확인":"2/3","스킬":"A8"},{"제목":"한 변의 길이 구하기","힌트":"넓이가 2/3인 정사각형의 한 변은?","식":["$x^2=\\frac{2}{3}$","$x=\\sqrt{\\frac{2}{3}}=\\frac{\\sqrt{6}}{3}$"],"설명":"넓이의 양의 제곱근을 구하고 분모를 유리화해 한 변의 길이를 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-a26bf0665326":{"길":"B, C 각각 폭 조건을 부등식으로 세워 보기에서 해당하는 개수를 센다","단계":[{"제목":"B의 폭 조건 정하기","힌트":"아래로 볼록하고 y=3x²보다 폭이 넓으려면?","식":["$0<b<3$"],"설명":"부호가 같고 절댓값이 작을수록 폭이 넓다.","확인":null,"스킬":"C2"},{"제목":"B에 해당하는 보기 세기","힌트":"보기 중 0<b<3인 것은?","식":["$y=\\frac{1}{5}x^{2},\\ y=2x^{2}$"],"설명":"조건을 만족하는 보기는 2개다.","확인":null,"스킬":"P4"},{"제목":"C의 폭 조건 정하기","고비":true,"힌트":"위로 볼록하고 y=-1/2x²보다 폭이 넓으려면?","식":["$-\\frac{1}{2}<c<0$"],"설명":"부호가 같고 절댓값이 1/2보다 작아야 한다.","확인":null,"스킬":"C2"},{"제목":"C에 해당하는 보기 세기","힌트":"보기 중 -1/2<c<0인 것은?","식":["$y=-\\frac{1}{5}x^{2}$"],"설명":"조건을 만족하는 보기는 1개다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-a339b8888219":{"길":"세 개의 직각삼각형에서 각 변의 길이와 넓이를 구해 세 진술을 판별한다","단계":[{"제목":"ㄱ 판별하기: BE 구하기","힌트":"△BEF에서 ∠EBF=30°이면 sin30°=2/BE는?","식":["$\\sin30^\\circ=\\frac{2}{\\overline{BE}}=\\frac12\\Rightarrow\\overline{BE}=4$"],"설명":"직각삼각형 BEF에서 BE를 구하면 ㄱ은 참이다.","확인":null,"스킬":"S6"},{"제목":"ㄴ 판별하기: CE 구하기","고비":true,"힌트":"△CEF에서 ∠ECF=45°이면 sin45°=2/CE는?","식":["$\\sin45^\\circ=\\frac{2}{\\overline{CE}}=\\frac{\\sqrt2}{2}\\Rightarrow\\overline{CE}=2\\sqrt2$"],"설명":"실제 CE는 2√2인데 ㄴ은 2√3이라 했으므로 ㄴ은 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"BF, FC 구하기","힌트":"△BEF에서 ∠BEF=60°, △CEF에서 ∠CEF=45°일 때 BF, FC는?","식":["$\\overline{BF}=2\\tan60^\\circ=2\\sqrt3,\\quad\\overline{FC}=2\\tan45^\\circ=2$"],"설명":"두 직각삼각형에서 각각 BF와 FC를 구한다.","확인":null,"스킬":"S6"},{"제목":"ㄷ 판별하기: △ABE 넓이 구하기","힌트":"BC=AB=BF+FC를 이용해 △ABE 넓이는?","식":["$\\overline{BC}=\\overline{AB}=2\\sqrt3+2$","$\\triangle ABE=\\frac12\\times(2\\sqrt3+2)\\times2\\sqrt3=6+2\\sqrt3$"],"설명":"넓이를 계산하면 ㄷ도 참이다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-a41be39422f1":{"길":"각을 구해 PQRS가 직사각형임을 확인하고 네 변을 구해 넓이를 계산한다","단계":[{"제목":"내각 구하기","힌트":"이웃하는 두 내각의 비가 2:1이고 합이 180°이면 각B, 각C는?","식":["$\\angle B=180^\\circ\\times\\frac13=60^\\circ,\\quad\\angle C=180^\\circ\\times\\frac23=120^\\circ$"],"설명":"평행사변형의 이웃한 내각의 합은 180°이므로 두 각을 구한다.","확인":null,"스킬":"C7"},{"제목":"PQRS가 직사각형임을 확인하기","고비":true,"힌트":"각의 이등분선이 만드는 사각형 PQRS의 네 각은?","식":[],"설명":"이등분된 각들이 서로 엇각·동위각 관계를 이뤄 PQRS의 네 내각이 모두 90°인 직사각형이 된다.","확인":null,"스킬":"S10"},{"제목":"AP, AQ 구해 PQ 계산하기","힌트":"직각삼각형 ABP, ADQ에서 AP=6sin30°, AQ=10sin30°는?","식":["$\\overline{AP}=6\\sin30^\\circ=3,\\quad\\overline{AQ}=10\\sin30^\\circ=5,\\quad\\overline{PQ}=5-3=2$"],"설명":"두 직각삼각형에서 AP, AQ를 구해 PQ를 계산한다.","확인":"2","스킬":"S6"},{"제목":"BP, BS 구해 PS 계산하기","힌트":"직각삼각형 ABP, CBS에서 BP=6cos30°, BS=10cos30°는?","식":["$\\overline{BP}=6\\cos30^\\circ=3\\sqrt3,\\quad\\overline{BS}=10\\cos30^\\circ=5\\sqrt3,\\quad\\overline{PS}=5\\sqrt3-3\\sqrt3=2\\sqrt3$"],"설명":"같은 방법으로 PS를 구한다.","확인":null,"스킬":"S6"},{"제목":"직사각형 PQRS 넓이 구하기","힌트":"PQ×PS는?","식":["$2\\times2\\sqrt3=4\\sqrt3$"],"설명":"가로와 세로를 곱해 넓이를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-a547345a014f":{"길":"중간고사보다 기말고사 성적이 오른 학생만 골라 평균을 구한다","단계":[{"제목":"조건에 맞는 학생 찾기","힌트":"산점도에서 대각선 위쪽(기말이 중간보다 높은) 점은 몇 명일까?","식":["$7명$"],"설명":"중간보다 기말 성적이 오른 학생은 7명이다.","확인":null,"스킬":"P4"},{"제목":"평균 구하기","고비":true,"힌트":"7명의 기말 성적을 모두 더해 나누면?","식":["$\\frac{60+70\\times2+80+90\\times2+100}{7}=80$"],"설명":"7명의 기말 성적 평균은 80점이다.","확인":"80","스킬":"P4"}],"fb":"fig/ns/"},"ns-a6e47fe0af1a":{"길":"직각삼각형에서 BC를 구하고 닮음인 두 삼각형의 대응변 비로 sin A를 구한다","단계":[{"제목":"BC 길이 구하기","힌트":"직각삼각형 ABC에서 피타고라스 정리로 BC를 구하면?","식":["$\\overline{BC}=\\sqrt{5^2-4^2}=3$"],"설명":"직각삼각형 ABC에서 피타고라스 정리로 BC의 길이를 구한다.","확인":null,"스킬":"S3"},{"제목":"△ADE와 △ABC의 닮음 확인하기","힌트":"BC∥DE이면 두 삼각형은 어떤 관계일까?","식":[],"설명":"BC와 DE가 평행하므로 △ADE와 △ABC는 AA닮음이다.","확인":null,"스킬":"S1"},{"제목":"sin A 값 구하기","고비":true,"힌트":"닮음인 두 삼각형에서 대응변의 비는 서로 같을까?","식":["$\\sin A=\\dfrac{\\overline{DE}}{\\overline{AD}}=\\dfrac{\\overline{BC}}{\\overline{AB}}=\\dfrac{3}{5}$"],"설명":"닮음비를 이용하면 sin A는 △ABC에서의 대응변 비인 3/5와 같다.","확인":"3/5","스킬":"S6"}],"fb":"fig/ns/"},"ns-a7c5d2f49f77":{"길":"구간별 무리수 개수를 차례로 세어 7과 9 사이 값을 더한다","단계":[{"제목":"구간별 규칙 찾기","힌트":"1과 2사이, 2와 3사이 무리수 카드는 몇 개씩 늘어날까?","식":["$1\\sim2:2개,\\ 2\\sim3:4개,\\ \\ldots$"],"설명":"n과 n+1 사이에는 제곱수를 뺀 2n개의 무리수 카드가 있다.","확인":null,"스킬":"P4"},{"제목":"7과 8 사이 개수 구하기","고비":true,"힌트":"49와 64 사이 정수 중 제곱수를 빼면?","식":["$7\\sim8:\\ 14개$"],"설명":"49(=7²)와 64(=8²) 사이의 정수 14개가 모두 무리수 카드다.","확인":"14","스킬":"N8"},{"제목":"8과 9 사이 개수 구하고 합하기","힌트":"64와 81 사이는 몇 개이고, 둘을 더하면?","식":["$8\\sim9:\\ 16개$","$14+16=30$"],"설명":"같은 방법으로 8과 9 사이 16개를 구해 더하면 30개다.","확인":"30","스킬":"P4"}],"fb":"fig/ns/"},"ns-a7d06fbca5e5":{"길":"피타고라스로 대각선 길이를 구해 대응하는 수를 찾고 선지를 확인한다","단계":[{"제목":"대각선 길이 구하기","힌트":"한 변이 1인 정사각형의 대각선은?","식":["$\\overline{BD}=\\overline{AC}=\\sqrt{1^2+1^2}=\\sqrt{2}$"],"설명":"피타고라스 정리로 대각선의 길이가 √2임을 구한다.","확인":null,"스킬":"S3"},{"제목":"a, b 값 구하기","고비":true,"힌트":"BP=√2를 5에서 왼쪽으로, AQ=√2를 4에서 오른쪽으로 재면?","식":["$a=5-\\sqrt{2}$","$b=4+\\sqrt{2}$"],"설명":"BD, AC를 각각 B, A에서 옮겨 점 P, Q에 대응하는 수 a, b를 구한다.","확인":null,"스킬":"S3"},{"제목":"선지와 대조하기","힌트":"②의 b=5+√2와 구한 b=4+√2를 비교하면?","식":[],"설명":"②는 b가 4+√2가 되어야 하는데 5+√2로 잘못 적혀 있어 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-af3e2c8f09d0":{"길":"세 쌍의 직각이 만드는 숨은 원을 각각 찾아, 원주각의 성질을 이어 붙여 옳은 것을 확인한다","단계":[{"제목":"첫 번째 숨은 원 찾기","힌트":"∠AFC와 ∠ADC가 모두 직각이면 네 점은?","식":["$\\angle AFC=\\angle ADC=90^{\\circ}\\Rightarrow □AFDC는\\ 원에\\ 내접$"],"설명":"한 선분을 같은 직각으로 보는 네 점 A,F,D,C는 한 원 위에 있다.","확인":null,"스킬":"S15"},{"제목":"첫 번째 원에서 원주각 읽기","힌트":"□AFDC에서 호 FD에 대한 원주각은?","식":["$\\angle BAD=\\angle FCB$"],"설명":"원주각의 성질로 ∠BAD=∠FCB를 얻는다.","확인":null,"스킬":"S5"},{"제목":"두 번째 숨은 원 찾기","힌트":"∠BFC와 ∠BEC가 모두 직각이면?","식":["$\\angle BFC=\\angle BEC=90^{\\circ}\\Rightarrow □BCEF는\\ 원에\\ 내접$"],"설명":"같은 방법으로 B,C,E,F 네 점도 한 원 위에 있어 ∠ABE=∠ACF를 얻는다.","확인":null,"스킬":"S15"},{"제목":"세 번째 숨은 원으로 목표 각 잇기","고비":true,"힌트":"∠AEB와 ∠ADB가 모두 직각이면 A,B,D,E는?","식":["$\\angle AEB=\\angle ADB=90^{\\circ}\\Rightarrow □ABDE는\\ 원에\\ 내접$"],"설명":"세 번째 숨은 원 ABDE를 찾아 그 안의 원주각으로 ∠CAD=∠CBE를 얻는 것이 이 문제에서 가장 어렵다.","확인":null,"스킬":"S15"},{"제목":"옳은 것 확정하기","힌트":"세 번째 원에서 얻은 결론은?","식":["$\\angle CAD=\\angle CBE$"],"설명":"세 번째 숨은 원의 원주각 성질로 ∠CAD=∠CBE가 성립하므로 ④가 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-af918c182595":{"길":"수선의 발이 만드는 직각으로 다섯 사각형이 원에 내접하는지 하나씩 확인한다","단계":[{"제목":"①, ⑤ 확인하기","힌트":"∠BFC=∠BEC, ∠ADB=∠AEB이면?","식":["$\\angle BFC=\\angle BEC\\Rightarrow □BCEF\\ 내접$","$\\angle ADB=\\angle AEB\\Rightarrow □ABDE\\ 내접$"],"설명":"같은 선분을 같은 직각으로 보는 네 점이므로 ①, ⑤ 모두 원에 내접한다.","확인":null,"스킬":"S15"},{"제목":"②, ④ 확인하기","힌트":"∠HDC+∠HEC, ∠AFH+∠AEH의 합은?","식":["$\\angle HDC+\\angle HEC=180^{\\circ}$","$\\angle AFH+\\angle AEH=180^{\\circ}$"],"설명":"마주보는 각의 합이 180°이므로 ②, ④도 원에 내접한다.","확인":null,"스킬":"S5"},{"제목":"③ 확인하기","고비":true,"힌트":"□DEAF에서 마주보는 각을 살펴보면?","식":[],"설명":"□DEAF는 마주보는 각의 합이 180°가 됨을 보장하는 직각 쌍이 없어 원에 내접한다고 할 수 없다.","확인":null,"스킬":"S15"},{"제목":"답 확정하기","힌트":"내접하지 않는 것은?","식":[],"설명":"①,②,④,⑤는 내접하지만 ③ □DEAF는 내접하지 않는다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-b26ff8eb9062":{"길":"세 정사각형의 한 변을 구한 뒤 둘레를 가로 방향과 세로 방향으로 나눠 더한다","단계":[{"제목":"세 정사각형의 한 변 구하기","힌트":"54, 24, 6의 제곱근을 간단히 하면?","식":["$\\sqrt{54}=3\\sqrt{6},\\ \\sqrt{24}=2\\sqrt{6},\\ \\sqrt{6}$"],"설명":"각 넓이의 제곱근을 구해 한 변의 길이를 얻는다.","확인":null,"스킬":"N8"},{"제목":"둘레를 변의 개수로 나타내기","힌트":"계단 모양을 직사각형으로 밀어 보면 가로 방향과 세로 방향의 길이 합은?","식":["$2(3\\sqrt{6}+2\\sqrt{6}+\\sqrt{6})+2\\times3\\sqrt{6}$","$4\\times3\\sqrt{6}+2\\times2\\sqrt{6}+2\\times\\sqrt{6}$"],"설명":"계단 모양의 둘레는 가로 방향이 세 변의 합의 2배이고, 세로 방향이 가장 큰 정사각형 한 변의 2배이다. 이를 변의 개수로 모으면 A 의 변 4번, B 의 변 2번, C 의 변 2번이다.","확인":null,"스킬":"S12","고비":true},{"제목":"둘레 계산하기","힌트":"동류항끼리 더하면?","식":["$12\\sqrt{6}+4\\sqrt{6}+2\\sqrt{6}=18\\sqrt{6}$"],"설명":"같은 근호끼리 더해 둘레의 길이 18√6을 얻는다.","확인":null,"스킬":"N6"}]},"ns-b48d58d603c4":{"길":"세 정사각형의 변을 구한 뒤 겹치는 부분을 빼며 둘레를 계산한다","단계":[{"제목":"세 정사각형의 한 변 구하기","힌트":"2, 5, 8의 제곱근을 간단히 하면?","식":["$\\sqrt{2},\\ \\sqrt{5},\\ \\sqrt{8}=2\\sqrt{2}$"],"설명":"각 넓이의 제곱근으로 한 변의 길이를 구한다.","확인":null,"스킬":"N8"},{"제목":"겹치는 변 파악하기","고비":true,"힌트":"뒤 정사각형이 앞 정사각형의 대각선 교점에 꼭짓점을 맞추면 둘레에서 빠지는 길이는?","식":[],"설명":"이어 붙이며 겹치는 부분만큼 둘레에서 앞 정사각형의 변 일부가 가려진다.","확인":null,"스킬":"S12"},{"제목":"구간별로 둘레 식 세우기","힌트":"각 정사각형이 둘레에 남기는 길이를 더하고 빼면?","식":["$3\\sqrt{2}+(3\\sqrt{5}-\\sqrt{2})+(8\\sqrt{2}-\\sqrt{5})$"],"설명":"각 정사각형이 실제로 둘레에 드러내는 길이를 더하고 겹친 부분을 뺀다.","확인":null,"스킬":"S12"},{"제목":"정리해 둘레 구하기","힌트":"같은 근호끼리 모으면?","식":["$=10\\sqrt{2}+2\\sqrt{5}$"],"설명":"√2 항과 √5 항을 각각 모아 최종 둘레를 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-b96547613acd":{"길":"두 꼭짓점을 구해 평행이동 관계를 알아채고 색칠한 넓이를 직사각형으로 바꾼다","단계":[{"제목":"두 꼭짓점 구하기","힌트":"완전제곱으로 바꾸면 꼭짓점은?","식":["$A(1,3),\\ B(4,3)$"],"설명":"두 이차함수를 완전제곱 꼴로 바꿔 꼭짓점을 구한다.","확인":null,"스킬":"A6"},{"제목":"평행이동 관계 알아채기","고비":true,"힌트":"두 그래프의 꼭짓점 높이가 같다면?","식":[],"설명":"두 그래프는 모양이 같고 꼭짓점 높이도 같으므로, 두 번째 그래프는 첫 번째를 x축 방향으로 3만큼 평행이동한 것이다.","확인":null,"스킬":"G4"},{"제목":"색칠한 넓이를 직사각형으로 바꾸기","힌트":"평행이동으로 생기는 두 곡선 사이 넓이는 어떤 도형의 넓이와 같을까?","식":[],"설명":"평행이동한 도형이므로 겹치고 남는 부분의 넓이는 A, B와 그 수선의 발로 만든 직사각형의 넓이와 같다.","확인":null,"스킬":"S12"},{"제목":"직사각형 넓이 계산하기","힌트":"가로 3, 세로 3인 직사각형의 넓이는?","식":["$(4-1)\\times3=9$"],"설명":"가로와 세로가 모두 3인 직사각형의 넓이를 계산한다.","확인":"9","스킬":"N6"}],"fb":"fig/ns/"},"ns-b9c25be4e095":{"길":"피타고라스로 a=√10을 구한 뒤 여섯 보기를 각각 a와 4 사이인지 확인한다","단계":[{"제목":"a의 값 구하기","힌트":"모눈에서 AB의 길이를 피타고라스로 구하면?","식":["$\\overline{AB}=\\sqrt{3^2+1^2}=\\sqrt{10}$"],"설명":"직각삼각형에서 피타고라스 정리로 AB=√10, 즉 a=√10임을 구한다.","확인":null,"스킬":"S3"},{"제목":"ㄷ, ㄴ, ㅂ 제외하기","고비":true,"힌트":"3.5는 유리수, a/3+1과 a-0.1은 a와 4 사이에 있을까?","식":["$\\frac{\\sqrt{10}}{3}+1<\\sqrt{10}$","$\\sqrt{10}-0.1<\\sqrt{10}$"],"설명":"ㄷ은 유리수라 제외되고, ㄴ과 ㅂ은 값이 a보다 작아 a와 4 사이에 들지 못한다.","확인":null,"스킬":"N7"},{"제목":"ㄱ, ㄹ, ㅁ이 범위 안에 있는지 확인하기","힌트":"√13, a+0.01, (a+4)/2가 a와 4 사이인지 부등식으로 확인하면?","식":["$\\sqrt{10}<\\sqrt{13}<4$","$\\sqrt{10}<\\sqrt{10}+0.01<4$","$\\frac{7}{2}<\\frac{\\sqrt{10}+4}{2}<4$"],"설명":"세 값 모두 a보다 크고 4보다 작아 조건을 만족하는 무리수다.","확인":null,"스킬":"N7"}],"fb":"fig/ns/"},"ns-bca452959c6f":{"길":"막대그래프의 퍼짐 정도만 비교해 표준편차의 대소를 정한다","단계":[{"제목":"표준편차와 퍼짐 정도의 관계 떠올리기","힌트":"자료가 평균에 몰려있을수록 표준편차는 어떻게 될까?","식":[],"설명":"자료가 평균을 중심으로 더 많이 모여 있을수록 표준편차는 작아진다.","확인":null,"스킬":"P4"},{"제목":"세 그래프의 퍼짐 정도 비교하기","힌트":"막대그래프에서 어느 자료가 가장 좁게 모여 있을까?","식":["$a<c<b$"],"설명":"세 막대그래프를 비교하면 A가 가장 좁게 모여 있고 B가 가장 넓게 퍼져 있어 표준편차는 a<c<b 순서이다.","확인":null,"스킬":"P4","고비":true},{"제목":"선지와 대조해 답 정하기","힌트":"a<c<b에 해당하는 선지는?","식":[],"설명":"a<c<b 순서와 일치하는 선지는 ②이다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-c8e241a1fb14":{"길":"남은 사각형의 두 변을 x,y로 나타내 넓이를 전개하고 계수를 계산한다","단계":[{"제목":"남은 사각형의 두 변 구하기","힌트":"GD=DC=2y라면 AG, AE는 각각?","식":["$\\overline{AG}=3x-2y$","$\\overline{AE}=2y-(3x-2y)=-3x+4y$"],"설명":"정사각형의 한 변 길이로 AG, AE를 구한다.","확인":null,"스킬":"C7"},{"제목":"넓이 전개해 계수 구하기","고비":true,"힌트":"(3x-2y)(-3x+4y)를 전개하면?","식":["$(3x-2y)(-3x+4y)=-9x^2+18xy-8y^2$"],"설명":"전개하면 p=-9, q=18, r=-8이다.","확인":null,"스킬":"A3"},{"제목":"p÷q×r 계산하기","힌트":"세 값을 대입해 계산하면?","식":["$(-9)\\div18\\times(-8)=4$"],"설명":"계산 결과는 4이다.","확인":"4","스킬":"A3"}],"fb":"fig/ns/"},"ns-ca4f4703f791":{"길":"산점도에서 점의 위치로 저축액이 가장 큰 사람과 수입 대비 소비가 심한 사람을 찾는다","단계":[{"제목":"저축을 가장 많이 하는 사람 찾기","힌트":"산점도에서 저축액이 가장 큰 점은 어디에 있을까?","식":[],"설명":"가로축이 월 저축액이므로 가장 오른쪽에 있는 점 E가 저축을 가장 많이 하는 사람이다.","확인":null,"스킬":"P4"},{"제목":"수입 대비 소비가 심한 사람 찾기","힌트":"수입은 크지만 저축은 적은 점은 어디에 있을까?","식":[],"설명":"수입이 가장 크면서 저축액은 가장 적은 점 A가 수입에 비해 소비가 심한 사람이다.","확인":null,"스킬":"P4","고비":true},{"제목":"답 정하기","힌트":"두 사람을 차례로 묶으면?","식":["E, A"],"설명":"저축을 가장 많이 하는 E와 소비가 심한 A를 순서대로 묶은 ④가 답이다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-cc3138a12252":{"길":"두 정사각형이 자연수 변을 갖는 조건을 각각 구해 공통되는 n을 찾는다","단계":[{"제목":"A가 자연수 변을 갖는 조건 찾기","힌트":"24n=2³×3×n이 완전제곱수이려면 n은?","식":["$n=6k^2\\ (k는\\ 자연수)$"],"설명":"24n의 소인수 지수를 모두 짝수로 만들려면 n이 6×(제곱수) 꼴이어야 한다.","확인":null,"스킬":"N8"},{"제목":"B가 자연수 변을 갖는 조건 찾기","고비":true,"힌트":"28-2n이 1, 4, 9, 16, 25 중 하나가 되는 n은?","식":["$28-2n=4\\Rightarrow n=12$","$28-2n=16\\Rightarrow n=6$"],"설명":"28-2n이 완전제곱수가 되는 자연수 n 중 정수해는 n=12, 6뿐이다.","확인":null,"스킬":"N8"},{"제목":"두 조건을 모두 만족하는 n 정하기","힌트":"n=6과 n=12 중 6k² 꼴에 맞는 것은?","식":["$n=6=6\\times1^2$"],"설명":"n=6만 A의 조건도 함께 만족하므로 n=6으로 정한다.","확인":null,"스킬":"C2"},{"제목":"A, B의 변의 길이와 C의 넓이 구하기","힌트":"n=6일 때 A, B의 한 변과 C의 가로, 세로는?","식":["$\\overline{A}=\\sqrt{144}=12,\\ \\overline{B}=\\sqrt{16}=4$","$4\\times(12-4)=32$"],"설명":"A, B의 한 변을 구하고 직사각형 C의 가로 4, 세로 8을 곱해 넓이 32㎡를 얻는다.","확인":"32","스킬":"C7"}],"fb":"fig/ns/"},"ns-cc5dc7347d22":{"길":"그래프의 볼록 방향과 꼭짓점 위치로 a,p,q의 부호를 정해 선지를 하나씩 확인한다","단계":[{"제목":"a의 부호 정하기","힌트":"아래로 볼록한 그래프는 a의 부호가?","식":[],"설명":"그래프가 아래로 볼록하므로 a>0이다.","확인":null,"스킬":"A6"},{"제목":"p,q의 부호 정하기","고비":true,"힌트":"꼭짓점 (-p,q)가 제4사분면에 있다면 -p, q의 부호는?","식":["$-p>0,\\ q<0$","$\\therefore p<0,\\ q<0$"],"설명":"꼭짓점 좌표 (-p,q)가 제4사분면 위에 있으므로 -p>0, q<0이고 정리하면 p<0, q<0이다.","확인":null,"스킬":"A6"},{"제목":"선지 대입해 옳지 않은 것 찾기","힌트":"a>0, p<0, q<0을 각 선지에 넣으면?","식":["$ap<0,\\ aq<0,\\ pq>0,\\ a-p>0$","$ap+q<0$"],"설명":"부호를 대입하면 ①~④는 모두 옳고, ⑤는 ap<0, q<0이므로 ap+q<0이 되어 'ap+q>0'이라는 진술은 옳지 않다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-cc7b0661f6e3":{"길":"넓이비로 닮음비를 구한 뒤 긴 변과 짧은 변의 관계를 세운다","단계":[{"제목":"닮음비 구하기","힌트":"넓이비가 2:1이면 닮음비는?","식":["$닮음비=\\sqrt{2}:1$"],"설명":"A4와 A5의 넓이비 2:1에서 닮음비는 √2:1이다.","확인":null,"스킬":"S1"},{"제목":"A4의 변의 길이 나타내기","고비":true,"힌트":"A5의 짧은 변을 a라 하면 A4의 짧은 변과 긴 변은?","식":["$A4의\\ 짧은\\ 변=\\sqrt{2}a,\\quad A4의\\ 긴\\ 변=2a$"],"설명":"닮음비로 A4의 짧은 변을 구하고, A5를 반으로 접은 관계로 A4의 긴 변이 2a임을 구한다.","확인":null,"스킬":"S1"},{"제목":"몇 배인지 구하기","힌트":"긴 변을 짧은 변으로 나누면?","식":["$\\frac{2a}{\\sqrt{2}a}=\\sqrt{2}$"],"설명":"A4의 긴 변을 짧은 변으로 나눠 √2배임을 구한다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-cceda9ed8652":{"길":"점 B를 문자로 두고 EB=BC 조건으로 C,D를 나타낸 뒤 정사각형 변의 길이가 같다는 식을 세운다","단계":[{"제목":"B의 좌표를 문자로 두기","힌트":"점 B의 x좌표를 t라 하면 y좌표는?","식":["$B\\left(t,\\ \\frac{1}{2}t^2\\right)$"],"설명":"점 B는 포물선 위의 점이므로 x좌표를 t라 하면 y좌표는 t²/2이다.","확인":null,"스킬":"A6"},{"제목":"EB=BC 조건으로 C의 좌표 구하기","힌트":"EB=BC=t이면 점 C의 x좌표는?","식":["$C\\left(2t,\\ \\frac{1}{2}t^2\\right)$"],"설명":"EB=BC=t이므로 점 C는 B보다 x좌표가 t만큼 더 크다.","확인":null,"스킬":"C7"},{"제목":"D의 좌표 구하고 방정식 세우기","고비":true,"힌트":"D는 C와 x좌표가 같은 포물선 위의 점이면?","식":["$D\\left(2t,\\ 2t^2\\right)$","$\\overline{BC}=\\overline{DC}$","$t=2t^2-\\frac{1}{2}t^2$"],"설명":"D(2t,2t²)이고 정사각형이므로 BC=DC이다. 이를 식으로 세우면 t=2t²-t²/2이다.","확인":null,"스킬":"A6"},{"제목":"t를 구해 넓이 계산하기","힌트":"정리한 이차방정식을 풀면?","식":["$\\frac{3}{2}t^2-t=0$","$t=\\frac{2}{3}$","$\\left(\\frac{2}{3}\\right)^2=\\frac{4}{9}$"],"설명":"방정식을 풀면 t=2/3(t≠0)이고, 정사각형의 한 변이 2/3이므로 넓이는 4/9이다.","확인":"4/9","스킬":"A6"}],"fb":"fig/ns/"},"ns-cf4d3189157a":{"길":"직선 y=ax+b가 지나는 두 점으로 a,b를 구하고 이차함수의 꼭짓점과 폭을 확인한다","단계":[{"제목":"a,b 구하기","힌트":"직선이 점 (3,0), (0,3)을 지나면 a,b는?","식":["$3a+b=0,\\ b=3$","$a=-1$"],"설명":"직선이 (3,0),(0,3)을 지나므로 y절편 b=3이고, 3a+3=0에서 a=-1이다.","확인":null,"스킬":"G9"},{"제목":"이차함수 식 완성하기","힌트":"a=-1, b=3을 y=a(x+b)²+b/a에 대입하면?","식":["$y=-(x+3)^2-3$"],"설명":"대입하면 이차함수는 y=-(x+3)²-3이다.","확인":null,"스킬":"A3"},{"제목":"y절편·볼록방향 판별하기","고비":true,"힌트":"x=0일 때 y값과 볼록 방향은?","식":["$x=0\\Rightarrow y=-12$"],"설명":"x=0을 대입하면 y=-12이므로 점 (0,-12)를 지나고, 이차항 계수가 음수이므로 위로 볼록한 포물선이다.","확인":null,"스킬":"A3"},{"제목":"꼭짓점과 폭으로 답 정하기","힌트":"꼭짓점 좌표와 축, 폭 비교는?","식":["$\\left|-1\\right|>\\left|\\frac{1}{2}\\right|$"],"설명":"꼭짓점 좌표는 (-3,-3)이고 축은 x=-3이며, 이차항 계수의 절댓값이 더 크므로 y=1/2x²보다 폭이 좁다. 따라서 옳은 것은 꼭짓점 좌표이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-cfd7359eccc0":{"길":"사각형이 원에 내접하는 조건과 원주각 성질로 보기를 하나씩 확인한다","단계":[{"제목":"① 판별하기","힌트":"∠BFC=∠BEC=90°이면 BFEC는 어떤 사각형일까?","식":[],"설명":"∠BFC=∠BEC=90°이므로 사각형 BFEC는 원에 내접하고, 호 EF의 원주각이 같으므로 ∠ABE=∠ACF가 성립해 ①은 옳다.","확인":null,"스킬":"S15"},{"제목":"③ 판별하기","힌트":"∠BFH+∠BDH=180°이면 사각형 FBDH는?","식":["$\\overline{AF}\\times\\overline{AB}=\\overline{AH}\\times\\overline{AD}$"],"설명":"사각형 FBDH가 원에 내접하므로 닮음 관계에서 이 등식이 성립해 ③은 옳다.","확인":null,"스킬":"S15"},{"제목":"④ 판별하기","고비":true,"힌트":"∠DCH는 호DE와 호DH 중 어느 호의 원주각일까?","식":[],"설명":"사각형 DCEH가 원에 내접할 때 ∠DCH는 호DH의 원주각이지 호DE의 원주각이 아니므로 ④는 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"⑤ 판별하기","힌트":"한 원 위의 네 점이 되는 사각형은 모두 몇 가지일까?","식":[],"설명":"대각의 합이 180°인 경우 3가지, 한 변에 대해 같은 쪽의 두 각이 90°로 같은 경우 3가지로 모두 6가지이므로 ⑤는 옳다.","확인":null,"스킬":"S15"},{"제목":"② 결정하기","힌트":"옳지 않은 것이 2개인데 ④ 하나를 찾았다면 남은 하나는?","식":[],"설명":"①③⑤가 옳고 ④가 옳지 않음을 확인했으므로, 옳지 않은 것이 2개라는 조건에서 남은 ②도 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-d028edae9baa":{"길":"x축 대칭 관계에서 |a|=|d|, |b|=|c|를 얻어 다섯 진술을 하나씩 따진다","단계":[{"제목":"대칭 관계로 절댓값 관계 얻기","힌트":"y=ax², y=dx²가 x축에 대칭이면 a,d의 관계는?","식":["$|a|=|d|,\\ d=-a$","$|b|=|c|,\\ c=-b$"],"설명":"x축에 대칭이므로 절댓값이 같고 부호가 반대이다.","확인":null,"스킬":"A6"},{"제목":"ㄱ 판별하기","힌트":"그래프의 폭으로 d와 c의 크기를 비교하면?","식":[],"설명":"y=dx²의 폭이 y=cx²보다 좁으므로 |d|>|c|이고, c,d가 모두 음수이므로 d<c이다. ㄱ은 옳다.","확인":null,"스킬":"A6"},{"제목":"ㄴ 판별하기","힌트":"a,b,c,d의 부호를 정하면 곱은?","식":["$a>0,b>0,c<0,d<0$"],"설명":"a,b는 양수, c,d는 음수이므로 abcd>0이다. ㄴ은 옳다.","확인":null,"스킬":"N5"},{"제목":"ㄷ,ㄹ 판별하기","고비":true,"힌트":"a와 c의 폭 비교, a+b+c+d는?","식":["$|a|>|c|$","$a+b+c+d=a+b+(-b)+(-a)=0$"],"설명":"ㄷ은 |a|>|c|이므로 옳지 않고, ㄹ은 c=-b, d=-a를 대입하면 0이 되어 옳다.","확인":null,"스킬":"A2"},{"제목":"ㅁ 판별하고 답 정하기","힌트":"d-b의 부호로 근호를 풀면?","식":["$d<0,\\ b>0\\Rightarrow d-b<0$","$\\sqrt{(d-b)^2}=-(d-b)$"],"설명":"d-b가 음수이므로 √((d-b)²)=-(d-b)이다. ㅁ은 옳지 않다. 따라서 옳은 것은 ㄱ,ㄴ,ㄹ이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-d09b77a84b13":{"길":"닮음, 외각을 이용한 이등변삼각형 증명, 접선과 할선의 관계, 각이등분선 성질을 차례로 연결한다","단계":[{"제목":"① 판별 - 닮음 찾기","힌트":"△PCB와 △PDT에서 공통으로 같은 각을 찾으면?","식":["$\\angle BPC=\\angle TPD,\\ \\angle PBC=\\angle PTD$"],"설명":"두 쌍의 각이 같으므로 △PCB∽△PDT(AA닮음)이다. ①은 참이다.","확인":null,"스킬":"S1"},{"제목":"④ 판별 - 이등변삼각형 증명","고비":true,"힌트":"두 삼각형의 외각을 이용하면 ∠PCT와 ∠CDT는 같을까?","식":["$\\angle BPC=\\angle TPD=a,\\ \\angle PBC=\\angle PTD=b$","$\\angle PCT=a+b=\\angle CDT$"],"설명":"외각의 성질로 두 각이 같음을 보이면 △TDC는 CT=DT인 이등변삼각형이다. ④는 참이다.","확인":null,"스킬":"S10"},{"제목":"② 판별 - 닮음이 아님을 확인","힌트":"△TAB도 이등변삼각형일까?","식":["$\\angle BAT=2a+b\\ne\\angle ABT$"],"설명":"△TAB는 이등변삼각형이 아니므로 △TCD와 서로 닮음이 아니다. ②는 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"③ 판별 - PT, PA 구하기","힌트":"닮음비 PB:PT=PC:PD를 이용하면 PT는?","식":["$24:\\overline{PT}=18:12\\ \\Rightarrow\\ \\overline{PT}=16$","$\\overline{PT}^2=\\overline{PA}\\times\\overline{PB}\\ \\Rightarrow\\ \\overline{PA}=\\frac{32}{3}$"],"설명":"닮음비로 PT를 구하고, 접선과 할선의 관계로 PA를 구한다.","확인":null,"스킬":"S5"},{"제목":"③ 판별 - 각이등분선으로 비 구하기","힌트":"PD가 ∠P를 이등분하면 AD:DT는?","식":["$\\overline{AD}:\\overline{DT}=\\overline{PA}:\\overline{PT}=\\frac{32}{3}:16=2:3$"],"설명":"각이등분선의 성질로 AD:DT=2:3을 확인해 ③이 참임을 보인다.","확인":null,"스킬":"S1"},{"제목":"⑤ 판별하기","힌트":"∠TPB=∠TBP인지 알 수 있을까?","식":[],"설명":"주어진 조건만으로 ∠TPB=∠TBP인지 알 수 없으므로 PT=BT임을 알 수 없다. ⑤는 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-d0a210bcc0da":{"길":"직육면체의 면대각선과 공간대각선을 차례로 구해 삼각비 선지를 확인한다","단계":[{"제목":"면대각선 FH 구하기","힌트":"직사각형 EFGH에서 피타고라스 정리로 FH는?","식":["$\\overline{FH}=\\sqrt{(\\sqrt5)^2+(2\\sqrt5)^2}=5$"],"설명":"두 모서리로 이루어진 직사각형에서 대각선 FH를 구한다.","확인":"5","스킬":"S3"},{"제목":"공간대각선 DF 구하기","힌트":"직각삼각형 DFH에서 DF는?","식":["$\\overline{DF}=\\sqrt{5^2+(\\sqrt{11})^2}=6$"],"설명":"직각삼각형 DFH에서 피타고라스 정리로 DF를 구한다.","확인":"6","스킬":"S3"},{"제목":"①~⑤ 선지 확인하기","고비":true,"힌트":"sinx, cosx, tanx를 DH, FH, DF로 나타내면?","식":["$\\sin x=\\dfrac{\\sqrt{11}}{6},\\ \\cos x=\\dfrac56,\\ \\tan x=\\dfrac{\\sqrt{11}}{5}$"],"설명":"각 선지를 계산해 비교하면 ④ cosx=5/6만 제시된 값과 일치한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-d0ef39af0ec2":{"길":"현·호·합동에 관한 원의 기본 성질을 하나씩 선지에 적용해 확인한다","단계":[{"제목":"①~③ 판별하기","힌트":"OM=ON이면 현의 길이와 호의 길이는 어떻게 될까?","식":[],"설명":"OM=ON이면 AB=CD이고(①), OA=OC는 반지름으로 항상 같으며(②), AB=CD이면 호AB=호CD이다(③). 모두 옳다.","확인":null,"스킬":"S5"},{"제목":"⑤ 판별하기","힌트":"△OAM과 △OCN은 RHS 합동일까?","식":["$\\overline{OA}=\\overline{OC},\\ \\angle OMA=\\angle ONC=90^\\circ,\\ \\overline{OM}=\\overline{ON}$"],"설명":"빗변과 한 변이 각각 같으므로 △OAM≡△OCN(RHS 합동)이다. ⑤도 옳다.","확인":null,"스킬":"S5"},{"제목":"④ 결정하기","고비":true,"힌트":"옳지 않은 것이 하나뿐이라면 남은 것은?","식":[],"설명":"①②③⑤가 모두 옳음을 확인했으므로 남은 ④(BM=ON)가 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-d16dea4fa063":{"길":"그래프의 볼록 방향과 폭 비교만으로 a의 값을 큰 순서로 나열한다","단계":[{"제목":"볼록 방향으로 부호 나누기","힌트":"아래로 볼록/위로 볼록이면 a의 부호는?","식":[],"설명":"아래로 볼록하면 a>0, 위로 볼록하면 a<0이다.","확인":null,"스킬":"A6"},{"제목":"폭으로 순서 정하기","고비":true,"힌트":"폭이 좁을수록 |a|는 어떻게 될까?","식":["㉠-㉡-㉣-㉢"],"설명":"절댓값이 클수록 폭이 좁으므로, 폭을 비교해 순서를 정하면 ㉠-㉡-㉣-㉢이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-d75c3a5193c8":{"길":"두 그래프의 퍼짐 정도를 비교해 성적이 고른 반을 판단한다","단계":[{"제목":"그래프에서 퍼짐 정도 비교하기","힌트":"A반과 B반 중 어느 그래프가 평균을 중심으로 더 모여 있을까?","식":[],"설명":"A반의 그래프가 B반의 그래프보다 평균을 중심으로 더 모여 있다.","확인":null,"스킬":"C3"},{"제목":"성적이 고른 학급 판단하기","힌트":"자료가 평균에 더 모여 있으면 성적이 고른 것일까?","식":[],"설명":"평균 중심으로 더 모여 있는 A반의 성적이 더 고르므로, 이를 설명한 ④가 옳다.","확인":null,"스킬":"C3","고비":true}],"fb":"fig/ns/"},"ns-d91fc18c32c2":{"길":"원의 중심에서 현에 내린 수선의 성질과 합동으로 선지를 하나씩 확인한다","단계":[{"제목":"①②③ 판별하기","힌트":"AB=CD이면 OM,ON과 AM, CD의 절반은 어떤 관계일까?","식":["$\\overline{OM}=\\overline{ON}$","$\\overline{AM}=\\overline{BM}$","$\\overline{AM}=\\frac{1}{2}\\overline{CD}$"],"설명":"AB=CD이므로 중심에서 거리가 같아 OM=ON이고, 수선의 발이 현을 이등분하므로 AM=BM, AM=(1/2)AB=(1/2)CD이다. ①②③은 모두 참이다.","확인":null,"스킬":"S5"},{"제목":"④ 판별하기","힌트":"△AOM≡△CON임을 보이면 ∠OAM과 ∠OCN은?","식":["$\\triangle AOM\\equiv\\triangle CON\\ (RHS)$"],"설명":"RHS 합동으로 ∠OAM=∠OCN이 성립하므로 ④는 참이다.","확인":null,"스킬":"S5"},{"제목":"⑤ 대응 확인하기","고비":true,"힌트":"AO=DO, ∠AMO=∠DNO=90°, AM=DN이면 어느 두 삼각형이 합동일까?","식":["$\\overline{AO}=\\overline{DO},\\ \\angle AMO=\\angle DNO=90^\\circ,\\ \\overline{AM}=\\overline{DN}$"],"설명":"세 조건으로 △AOM과 △DON이 합동임을 확인했지만, ①~④가 모두 참이므로 남은 ⑤가 옳지 않은 것이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-dc7837662649":{"길":"네 내접원의 접선 길이를 한 미지수로 연결해 사슬을 따라간다","단계":[{"제목":"공통 접선 길이를 미지수로 놓기","힌트":"네 내접원 모두 점 A에서 접하므로 다섯 접선의 길이는?","식":["$\\overline{AG}=\\overline{AI}=\\overline{AK}=\\overline{AM}=\\overline{AO}=x$"],"설명":"네 내접원 모두 점 A에서 접하므로 이 다섯 접선의 길이를 x로 놓는다.","확인":null,"스킬":"S5"},{"제목":"차례로 이웃한 접선 길이 구하기","고비":true,"힌트":"BC=12, CD=9, DE=6, EF=3을 이용해 CH,DJ,EL,FN을 차례로 구하면?","식":["$\\overline{CH}=12-(16-x)=x-4$","$\\overline{DJ}=9-(x-4)=13-x$","$\\overline{EL}=6-(13-x)=x-7$","$\\overline{FN}=3-(x-7)=10-x$"],"설명":"각 삼각형의 변 길이 조건을 차례로 이용해 다음 접선 길이를 x에 대한 식으로 구해 나간다.","확인":null,"스킬":"S5"},{"제목":"AF 길이 구하기","힌트":"AO와 FN(=FO)을 더하면 x가 사라질까?","식":["$\\overline{AF}=\\overline{AO}+\\overline{FO}=x+(10-x)=10$"],"설명":"AO와 FO를 더하면 x가 소거되어 AF=10이 바로 구해진다.","확인":"10","스킬":"S5"}],"fb":"fig/ns/"},"ns-e12d26c4b82e":{"길":"외접사각형에서 알 수 있는 것과 알 수 없는 것을 구분해 확인한다","단계":[{"제목":"①~④ 판별하기","힌트":"외접사각형이라는 조건만으로 점 P가 원의 중심이거나 대각의 합이 180°임을 알 수 있을까?","식":[],"설명":"원에 내접하지 않고 외접할 뿐이므로 ①~④는 주어진 조건만으로 알 수 없다.","확인":null,"스킬":"C3"},{"제목":"⑤ 판별하기","고비":true,"힌트":"원에 외접하는 사각형은 두 쌍의 대변의 합에 대해 어떤 성질이 있을까?","식":["$\\overline{AB}+\\overline{CD}=\\overline{BC}+\\overline{AD}$"],"설명":"외접사각형은 마주보는 두 변의 길이의 합이 서로 같으므로, AB+CD는 둘레의 절반이다. ⑤가 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-e18edbfe9354":{"길":"정사각형의 변의 길이로 나머지 변을 구해 직사각형의 넓이를 계산한다","단계":[{"제목":"정사각형 IFGD의 한 변 구하기","힌트":"넓이가 2인 정사각형의 한 변은?","식":["$\\overline{ID}=\\overline{IF}=\\overline{FG}=\\overline{GD}=\\sqrt2$"],"설명":"정사각형 IFGD의 넓이가 2이므로 한 변의 길이는 √2이다.","확인":null,"스킬":"N8"},{"제목":"EF, FH의 길이 구하기","고비":true,"힌트":"직사각형의 변에서 정사각형의 변을 빼면?","식":["$\\overline{EF}=\\sqrt7-\\sqrt2$","$\\overline{FH}=3\\sqrt2-\\sqrt2=2\\sqrt2$"],"설명":"가로, 세로에서 정사각형의 변의 길이를 빼서 EF와 FH를 구한다.","확인":null,"스킬":"N6"},{"제목":"직사각형 EBHF의 넓이 계산하기","힌트":"EF와 FH를 곱하면?","식":["$\\square EBHF=2\\sqrt2(\\sqrt7-\\sqrt2)=2\\sqrt{14}-4$"],"설명":"두 변의 길이를 곱해 넓이를 구하면 2√14-4다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-e2695c673d51":{"길":"세 현이 같음을 보여 정삼각형을 확인한 뒤 삼각비로 반지름과 넓이를 구한다","단계":[{"제목":"세 현이 같음을 확인하기","힌트":"중심에서 거리가 같은 현은 길이도 같을까?","식":["$\\overline{OD}=\\overline{OE}=\\overline{OF}\\ \\Rightarrow\\ \\overline{AB}=\\overline{BC}=\\overline{CA}$"],"설명":"중심에서 세 현까지의 거리가 같으므로 세 현의 길이도 같아 삼각형 ABC는 정삼각형이다.","확인":null,"스킬":"S5"},{"제목":"직각삼각형 OBE 만들기","고비":true,"힌트":"OE⊥BC이므로 ∠OBE와 BE는 얼마일까?","식":["$\\angle OBE=\\frac{1}{2}\\times60^\\circ=30^\\circ,\\ \\overline{BE}=\\frac{1}{2}\\times6=3$"],"설명":"정삼각형의 한 내각의 절반과 반변의 길이로 직각삼각형 OBE를 만든다.","확인":null,"스킬":"S6"},{"제목":"반지름 구하기","힌트":"cos30°를 이용해 OB를 구하면?","식":["$\\overline{OB}=\\frac{3}{\\cos30^\\circ}=2\\sqrt3$"],"설명":"직각삼각형에서 코사인 비로 반지름 OB를 구한다.","확인":null,"스킬":"S6"},{"제목":"원의 넓이 구하기","힌트":"반지름의 제곱에 π를 곱하면?","식":["$\\pi\\times(2\\sqrt3)^2=12\\pi$"],"설명":"반지름을 이용해 원의 넓이를 구하면 12π이다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-e413ad1e5dfe":{"길":"총 인원 조건과 총합 조건으로 연립방정식을 세워 a, b를 구하고 중앙값·최빈값을 확인한다","단계":[{"제목":"총 인원 식 세우기","힌트":"찢어진 두 막대를 a, b명이라 하면 전체 32명 식은?","식":["$2+7+4+a+3+b+3+1=32$","$a+b=12$"],"설명":"충치 3개, 5개인 학생 수를 각각 a, b라 하면 전체 인원 32명에서 a+b=12이다.","확인":null,"스킬":"C7"},{"제목":"총합 식 세우기","힌트":"평균 3.25에 32를 곱하면 충치 개수의 총합은?","식":["$3.25\\times32=104$","$3a+5b=52$"],"설명":"평균 3.25에서 총합이 104개임을 구하고, 이를 도수분포로 다시 풀어 3a+5b=52를 얻는다.","확인":null,"스킬":"C7"},{"제목":"연립방정식 풀어 a, b 구하기","고비":true,"힌트":"a+b=12와 3a+5b=52를 연립하면?","식":["$a=4,\\ b=8$"],"설명":"두 식을 연립하면 a=4, b=8이다.","확인":null,"스킬":"A10"},{"제목":"최빈값 확인하기","힌트":"가장 도수가 큰 값은 몇 개일까?","식":["$b=8$"],"설명":"충치 5개인 학생이 8명으로 가장 많아 최빈값은 5개다. 따라서 최빈값이 1개라는 ⑤는 옳지 않다.","확인":"5","스킬":"C3"}],"fb":"fig/ns/"},"ns-e55efbe91ac7":{"길":"n, n+1로 넓이를 식으로 나타내고 네 보기를 하나씩 계산해 확인한다","단계":[{"제목":"AD, BD 길이 구하기","힌트":"AC=2n+1이므로 AD, BD는?","식":["$\\overline{AD}=\\overline{CD}=\\frac{2n+1}{2}$","$\\overline{BD}=(n+1)-\\frac{2n+1}{2}=\\frac{1}{2}$"],"설명":"AC=2n+1에서 AD와 BD를 구하면 ㄱ은 옳다.","확인":null,"스킬":"A2"},{"제목":"S2-S1 계산하기","힌트":"(n+1)²-n²을 전개하면?","식":["$S_2-S_1=(n+1)^2-n^2=2n+1$"],"설명":"차는 2n+1로 홀수이므로 ㄴ은 옳지 않고, (n+1)+n과 같으므로 ㄷ은 옳다.","확인":null,"스킬":"A2"},{"제목":"S3-S4 계산하기","고비":true,"힌트":"AD², BD²를 빼면?","식":["$S_3-S_4=\\left(\\frac{2n+1}{2}\\right)^2-\\left(\\frac{1}{2}\\right)^2=n(n+1)$"],"설명":"차가 n(n+1)로 두 수의 곱과 같으므로 ㄹ도 옳다.","확인":null,"스킬":"A2"},{"제목":"옳은 보기 정리하기","힌트":"ㄱ~ㄹ 중 옳은 것은?","식":[],"설명":"ㄱ, ㄷ, ㄹ이 옳으므로 답은 ④이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-e579d96c4e20":{"길":"작은 원 반지름을 r 로 놓고 둘레 조건과 색칠한 넓이 조건을 식으로 세워 연립한다","단계":[{"제목":"AD 를 지름으로 하는 원의 둘레 식 세우기","힌트":"AC=2r, CD=a 일 때 AD 를 지름으로 하는 원의 둘레는?","식":["$\\overline{\\mathrm{AC}}=2r,\\ \\overline{\\mathrm{AD}}=2r+a$","$(2r+a)\\pi=8\\pi$","$2r+a=8$"],"설명":"AC 를 지름으로 하는 작은 원의 반지름을 $r$ 라 하면 $\\overline{\\mathrm{AC}}=2r$ 이고, D 는 C 에서 $a$ 만큼 더 간 점이므로 $\\overline{\\mathrm{AD}}=2r+a$ 이다. 원의 둘레는 지름에 $\\pi$ 를 곱한 값이므로 첫 식이 나온다.","확인":null,"스킬":"C7"},{"제목":"색칠한 부분의 넓이 식 세우기","고비":true,"힌트":"D 가 BC 의 중점일 때 AB 를 지름으로 하는 큰 원의 반지름은?","식":["$\\overline{\\mathrm{AB}}=2r+2a$","$(r+a)^2\\pi-r^2\\pi=28\\pi$","$\\pi(2r+a)a=28\\pi$"],"설명":"D 가 BC 의 중점이라 $\\overline{\\mathrm{BC}}=2a$ 이므로 $\\overline{\\mathrm{AB}}=2r+2a$ 이고 큰 원의 반지름은 $r+a$ 이다. 색칠한 부분은 큰 원에서 작은 원을 뺀 것이므로 넓이 차를 합차 공식으로 인수분해하면 $(2r+a)a=28$ 꼴이 된다.","확인":null,"스킬":"A6"},{"제목":"앞 식을 대입해 a 구하기","힌트":"2r+a=8 을 (2r+a)a=28 에 대입하면?","식":["$8a=28$","$a=3.5$"],"설명":"$(2r+a)a=28$ 의 $2r+a$ 자리에 $8$ 을 넣으면 $8a=28$ 이므로 $a=3.5$ 이다.","확인":"3.5","스킬":"A10"}]},"ns-e72c134d5d0c":{"길":"그래프의 볼록 방향과 꼭짓점 위치로 a,p,q의 부호를 정해 선지를 하나씩 확인한다","단계":[{"제목":"a의 부호 정하기","힌트":"위로 볼록한 그래프는 a의 부호가?","식":[],"설명":"그래프가 위로 볼록하므로 a<0이다.","확인":null,"스킬":"A6"},{"제목":"p,q의 부호 정하기","고비":true,"힌트":"꼭짓점 (-p,q)가 제1사분면에 있다면?","식":["$-p>0,\\ q>0$","$\\therefore p<0,\\ q>0$"],"설명":"꼭짓점이 제1사분면 위에 있으므로 -p>0, q>0이고 정리하면 p<0, q>0이다.","확인":null,"스킬":"A6"},{"제목":"선지에 대입해 옳은 것 찾기","힌트":"x=0일 때 y값의 부호는?","식":["$aq<0,\\ pq<0,\\ a+p<0,\\ p-q<0$","$ap^2+q>0$"],"설명":"부호를 대입하면 ①~④는 모두 옳지 않고, y축과의 교점이 원점보다 위이므로 x=0일 때 y=ap²+q>0이 되어 ⑤가 옳다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-e7525fabf949":{"길":"넓이 공식 (1/2)ab sinC를 여러 변·각 조합으로 써서 선지를 하나씩 확인한다","단계":[{"제목":"① 판별하기","힌트":"∠C=90°인 특수한 경우로 확인하면?","식":["$\\cos A=\\frac{b}{c},\\ \\sin A=\\frac{a}{c}$"],"설명":"∠C=90°일 때만 성립하는 특수한 관계이므로 일반적인 예각삼각형에서는 ①이 항상 옳지는 않다.","확인":null,"스킬":"S6"},{"제목":"② 넓이 공식으로 판별하기","힌트":"△ABC의 넓이를 두 가지 변·각 조합으로 쓰면?","식":["$\\frac12bc\\sin A=\\frac12ab\\sin C$"],"설명":"sinA>sinC이면 (1/2)bc<(1/2)ab, 즉 c<a이므로 ②는 옳다.","확인":null,"스킬":"S8"},{"제목":"③ 넓이 공식 확장해 판별하기","고비":true,"힌트":"넓이를 세 가지 변·각 조합으로 모두 쓰면?","식":["$\\frac12bc\\sin A=\\frac12ac\\sin B=\\frac12ab\\sin C$"],"설명":"세 식이 모두 같으므로 bc·sinA=ac·sinB=ab·sinC이지, ac·sinB=ab·sinC가 아니므로 ③은 옳지 않다.","확인":null,"스킬":"S8"},{"제목":"④, ⑤ 판별하고 정답 정하기","힌트":"sinA=1/2일 때 넓이는? 45°≤A<90°에서 tanA는?","식":["$\\triangle ABC=\\frac12bc\\sin A=\\frac14bc$","$45^{\\circ}\\le A<90^{\\circ}\\Rightarrow\\tan A\\ge1$"],"설명":"④는 (1/4)bc가 되어 옳지 않고, ⑤도 tanA≥1이 되어 옳지 않다. 따라서 옳은 것은 ②이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-edfebcdf35aa":{"길":"각의 크기 비교로 근호 안 부호를 정한 뒤 절댓값을 풀어 변으로 정리한다","단계":[{"제목":"각 크기 비교로 a, b 관계 정하기","힌트":"∠A>∠B이면 대응하는 변의 크기는?","식":["$\\angle A>\\angle B\\Rightarrow a>b$"],"설명":"큰 각에 대응하는 변이 더 크므로 a>b이다.","확인":null,"스킬":"S6"},{"제목":"근호 안 부호 판정하기","고비":true,"힌트":"sinB와 cosB, sinC와 cosC의 크기를 비교하면?","식":["$\\sin B<\\cos B$","$\\sin C-\\cos C=\\sin90^{\\circ}-\\cos90^{\\circ}=1$"],"설명":"∠B<45°이므로 sinB-cosB<0이고, ∠C=90°이므로 sinC-cosC=1임을 확인한다.","확인":null,"스킬":"N5"},{"제목":"근호를 절댓값으로 풀기","힌트":"√(x²)=|x|이므로 각 항의 부호에 맞게 풀면?","식":["$\\sqrt{(\\sin A+\\cos A)^2}+\\sqrt{(\\sin B-\\cos B)^2}+\\sqrt{(\\sin C-\\cos C)^2}=(\\sin A+\\cos A)+(-\\sin B+\\cos B)+1$"],"설명":"sinA+cosA>0, sinB-cosB<0이므로 부호에 맞게 절댓값을 푼다.","확인":null,"스킬":"N5"},{"제목":"변으로 바꿔 정리하기","힌트":"sinA=a/c, cosA=b/c 등으로 바꾸면?","식":["$\\left(\\frac{a}{c}+\\frac{b}{c}\\right)+\\left(-\\frac{b}{c}+\\frac{a}{c}\\right)+1=\\frac{2a+c}{c}$"],"설명":"삼각비를 변의 비로 바꿔 정리하면 (2a+c)/c를 얻는다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-efc7361fea67":{"길":"각의 이등분선의 성질로 BD:CD를 구해 CD를 얻고 cos a°를 계산한다","단계":[{"제목":"BC 구하기","힌트":"직각삼각형 ABC에서 BC는?","식":["$\\overline{BC}=\\sqrt{10^2-6^2}=8$"],"설명":"피타고라스 정리로 BC를 구한다.","확인":"8","스킬":"S3"},{"제목":"각의 이등분선 성질로 BD:CD 구하기","고비":true,"힌트":"∠A=2a°가 이등분되어 ∠DAC=a°라면 BD:CD는?","식":["$\\overline{BD}:\\overline{CD}=\\overline{AB}:\\overline{AC}=10:6=5:3$"],"설명":"AD가 ∠A를 이등분하므로 각의 이등분선의 성질로 BD:CD를 구한다.","확인":null,"스킬":"A8"},{"제목":"CD 구하기","힌트":"BC=8을 5:3으로 나누면?","식":["$\\overline{CD}=8\\times\\frac{3}{8}=3$"],"설명":"비례식으로 CD의 길이를 구한다.","확인":"3","스킬":"A8"},{"제목":"cos a° 계산하기","힌트":"직각삼각형 ACD에서 AD를 구해 cos a°=AC/AD를 계산하면?","식":["$\\overline{AD}=\\sqrt{6^2+3^2}=3\\sqrt5$","$\\cos a^{\\circ}=\\frac{6}{3\\sqrt5}=\\frac{2\\sqrt5}{5}$"],"설명":"직각삼각형 ACD에서 피타고라스 정리와 삼각비로 cos a°를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-f030676470e5":{"길":"반지름·중심각·호의 표준 성질을 확인하고 현의 길이는 비례하지 않음을 가려낸다","단계":[{"제목":"①②③④ 판별하기","힌트":"반지름은 모두 같고, 호의 길이는 중심각에 비례할까?","식":["$\\angle AOC=180^\\circ-150^\\circ=30^\\circ$"],"설명":"OA=OB=OC는 반지름으로 같아 ①이 참이고, ∠AOC=30°로 ②가 참이다. 중심각의 비로 호의 비도 정해지므로 ③,④도 모두 참이다.","확인":null,"스킬":"S5"},{"제목":"⑤ 판별하기","고비":true,"힌트":"현의 길이와 중심각의 크기는 정비례할까?","식":[],"설명":"현의 길이는 중심각에 비례하지 않으므로 BC=5AC는 성립하지 않는다. ⑤가 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-f10cb39c342e":{"길":"일차함수 그래프에서 a, b의 부호를 읽고 이를 이차함수의 오목한 방향과 꼭짓점 위치로 옮긴다","단계":[{"제목":"일차함수 그래프에서 a, b의 부호 정하기","힌트":"그래프가 오른쪽 위로 향하고 y절편이 양수라면?","식":["$a>0,\\ b>0$"],"설명":"그래프가 왼쪽 아래에서 오른쪽 위로 향하므로 a>0, y축과 원점보다 위쪽에서 만나므로 b>0이다.","확인":null,"스킬":"G9"},{"제목":"이차함수의 오목한 방향 정하기","힌트":"a>0이면 이차함수의 그래프는?","식":[],"설명":"a>0이므로 y=a(x+b)²의 그래프는 아래로 볼록하다.","확인":null,"스킬":"G4"},{"제목":"꼭짓점의 위치 정하기","고비":true,"힌트":"꼭짓점 (-b,0)에서 b>0이면 -b는?","식":["$(-b,\\,0)$"],"설명":"꼭짓점의 좌표는 (-b,0)인데 b>0이므로 꼭짓점은 x축의 음의 부분 위에 있다. 이 조건을 만족하는 그래프는 그림 ①이다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-f25f3e763aec":{"길":"산책로 폭이 4 인 두 원의 반지름으로 가운데 원의 둘레와 산책로 넓이를 각각 세워 비교한다","단계":[{"제목":"산책로 가운데 원의 둘레 식 세우기","힌트":"잔디밭 반지름이 r, 폭이 4 일 때 가운데 원의 반지름은?","식":["$l=2\\pi(r+2)$"],"설명":"잔디밭 반지름을 $r$ 라 하면 산책로 한가운데 원의 반지름은 폭 $4$ 의 절반인 $2$ 만큼 바깥인 $r+2$ 이다. 둘레는 반지름에 $2\\pi$ 를 곱한 값이므로 위 식이 나온다.","확인":null,"스킬":"C7"},{"제목":"산책로 넓이를 인수분해하기","고비":true,"힌트":"바깥 원 반지름이 r+4 일 때 산책로 넓이는?","식":["$\\pi(r+4)^2-\\pi r^2=\\pi\\{(r+4)^2-r^2\\}$","$=\\pi(r+4+r)(r+4-r)=4\\pi(2r+4)$"],"설명":"산책로는 바깥 원(반지름 $r+4$)에서 잔디밭(반지름 $r$)을 뺀 부분이다. 제곱의 차를 합차 공식으로 인수분해하면 $4\\pi(2r+4)$ 가 된다.","확인":null,"스킬":"A6"},{"제목":"l 로 바꿔 정리하기","힌트":"2π(r+2)=l 을 이용하면?","식":["$4\\pi(2r+4)=8\\pi(r+2)=4\\times2\\pi(r+2)=4l$"],"설명":"$2\\pi(r+2)$ 가 $l$ 이므로 산책로의 넓이는 $l$ 의 $4$ 배이다.","확인":null,"스킬":"A10"}]},"ns-f84e7134007b":{"길":"가장 짧은 쇠사슬로 포물선의 식을 세우고 점 C를 대입해 구한 뒤 x=10을 넣는다","단계":[{"제목":"포물선의 식 세우기","힌트":"꼭짓점이 (0,5)인 포물선은 어떤 꼴일까?","식":["$y=ax^2+5$"],"설명":"가장 짧은 쇠사슬이 5m이므로 꼭짓점이 (0,5)인 포물선으로 놓는다.","확인":null,"스킬":"A6"},{"제목":"점 C를 대입해 a 구하기","고비":true,"힌트":"점 C(50,10)을 대입하면?","식":["$10=a\\times50^2+5$","$a=\\frac{1}{500}$"],"설명":"두 기둥 사이 거리 100m의 절반인 점 C(50,10)을 대입해 a를 구한다.","확인":"1/500","스킬":"A3"},{"제목":"x=10을 대입해 길이 구하기","힌트":"두 번째 쇠사슬의 위치 x=10을 대입하면?","식":["$y=\\frac{1}{500}\\times10^2+5=5.2$"],"설명":"점 D의 x좌표 10을 식에 대입하면 두 번째로 짧은 쇠사슬의 길이는 5.2m이다.","확인":"5.2","스킬":"A3"}],"fb":"fig/ns/"},"ns-f94b5e7fa4e8":{"길":"같은 호의 원주각과 현이 같을 때의 원주각을 찾아 ∠ACB와 같은 각의 개수를 센다","단계":[{"제목":"같은 호에 대한 원주각 찾기","힌트":"∠ADB와 ∠ACB는 어떤 관계일까?","식":["$\\angle ADB=\\angle ACB$"],"설명":"호AB에 대한 원주각이므로 ∠ADB=∠ACB이다.","확인":null,"스킬":"S5"},{"제목":"현이 같음을 이용해 각 찾기","고비":true,"힌트":"OM=ON이면 AB와 CD, 호AB와 호CD는 어떻게 될까?","식":["$\\overline{AB}=\\overline{CD}\\ \\Rightarrow\\ \\overset{\\frown}{AB}=\\overset{\\frown}{CD}\\ \\Rightarrow\\ \\angle ACB=\\angle CAD$"],"설명":"OM=ON이므로 AB=CD, 즉 호AB=호CD여서 같은 크기의 원주각 ∠CAD도 ∠ACB와 같다.","확인":null,"스킬":"S5"},{"제목":"개수 세기","힌트":"∠CAD=∠CBD=∠ACB이면 같은 각은 모두 몇 개일까?","식":[],"설명":"∠CAD=∠CBD=∠ACB이므로 ∠ACB와 크기가 같은 각은 ∠ADB, ∠CAD, ∠CBD의 3개이다.","확인":"3","스킬":"P4"}],"fb":"fig/ns/"},"ns-ff7ae3c41a57":{"길":"피타고라스, 원주각, 각이등분선 성질, 닮음을 차례로 적용해 보기 다섯 개를 판별한다","단계":[{"제목":"ㄱ 판별하기 - OB 구하기","힌트":"AB가 지름이므로 ∠ADB는?","식":["$\\angle ADB=90^\\circ,\\ \\overline{AB}=\\sqrt{6^2+2^2}=2\\sqrt{10}$"],"설명":"지름에 대한 원주각이 90°이므로 직각삼각형 ADB에서 피타고라스 정리로 AB를 구하면 OB=√10이다. ㄱ은 참이다.","확인":null,"스킬":"S3"},{"제목":"ㄴ 판별하기 - ∠ADC 구하기","힌트":"CA=CB이고 ∠ACB=90°이면 ∠CAB는?","식":["$\\angle CAB=\\angle CBA=45^\\circ,\\ \\angle ADC=\\angle ABC=45^\\circ$"],"설명":"직각이등변삼각형에서 밑각이 45°이고, 호AC에 대한 원주각이 같으므로 ∠ADC=45°이다. ㄴ은 참이다.","확인":null,"스킬":"S5"},{"제목":"ㄷ 판별하기 - PB 구하기","고비":true,"힌트":"∠ADP=∠BDP이면 DP는 무엇의 이등분선이고, AP:PB는?","식":["$\\overline{AP}:\\overline{PB}=\\overline{AD}:\\overline{DB}=6:2=3:1$","$\\overline{PB}=2\\sqrt{10}\\times\\frac{1}{4}=\\frac{\\sqrt{10}}{2}$"],"설명":"각의 이등분선의 성질로 AP:PB=3:1임을 구해 PB=√10/2를 얻는데, 이는 보기의 √10/3과 다르므로 ㄷ은 옳지 않다.","확인":null,"스킬":"S1"},{"제목":"ㅁ 판별하기 - CD 구하기","힌트":"△CBP∽△CDB(AA닮음)를 이용하면 CD는?","식":["$\\overline{CB}=2\\sqrt5,\\quad \\overline{CD}=4\\sqrt2$"],"설명":"닮음비로 CD=4√2를 구하는데, 이는 보기의 2√2와 다르므로 ㅁ은 옳지 않다.","확인":null,"스킬":"S1"},{"제목":"ㄹ 판별하기 - PD 구하기","힌트":"CP를 구해 CD에서 빼면 PD는?","식":["$\\overline{CP}=\\frac{5\\sqrt2}{2},\\quad \\overline{PD}=4\\sqrt2-\\frac{5\\sqrt2}{2}=\\frac{3\\sqrt2}{2}$"],"설명":"닮음으로 구한 CP를 CD에서 빼면 PD=3√2/2로 보기와 일치해 ㄹ은 참이다.","확인":null,"스킬":"S1"},{"제목":"개수 세기","힌트":"참인 것은 ㄱ,ㄴ,ㄹ이면 모두 몇 개일까?","식":[],"설명":"옳은 것은 ㄱ,ㄴ,ㄹ로 모두 3개이다.","확인":"3","스킬":"P4"}],"fb":"fig/ns/"},"ns-05908c79b5e0":{"길":"누락된 두 값과 기존 평균·중앙값을 비교해 변화 방향을 판단한다","단계":[{"제목":"평균 변화 판단하기","힌트":"누락된 두 선수 키의 평균은 179보다 클까 작을까?","식":["$\\frac{178+181}{2}=179.5$"],"설명":"누락된 두 선수 키의 평균 179.5cm가 기존 평균 179cm보다 크므로 전체 평균은 179cm보다 높아진다.","확인":null,"스킬":"C2"},{"제목":"중앙값 변화 판단하기","고비":true,"힌트":"홀수 명일 때 178cm, 181cm를 추가해도 중앙값의 위치가 바뀔까?","식":[],"설명":"인원이 홀수이고 추가된 값이 기존 중앙값 178cm와 그보다 큰 값이므로 중앙값은 178cm로 변하지 않는다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-0abbd14ac7b1":{"길":"부호 조건으로 a<0, b>0을 정한 뒤 다섯 선지를 절댓값 성질로 계산해 확인한다","단계":[{"제목":"a, b의 부호 정하기","힌트":"a-b<0, ab<0을 동시에 만족하려면?","식":["$a<0,\\ b>0$"],"설명":"두 조건을 동시에 만족하려면 a는 음수, b는 양수여야 한다.","확인":null,"스킬":"C2"},{"제목":"①~④ 선지 계산하기","힌트":"√(a²)=-a, √(b²)=b임을 이용해 계산하면?","식":["$①\\,-a-b\\quad②\\,2b\\quad③\\,-1\\quad④\\,-2a+2b$"],"설명":"①은 a-b가 아니라 -a-b, ③은 1이 아니라 -1, ④는 0이 아니라 -2a+2b가 되어 모두 옳지 않다.","확인":null,"스킬":"N7"},{"제목":"⑤ 선지 계산해 확인하기","고비":true,"힌트":"√(9b²)+√(b²)-√((-2b)²)은?","식":["$3b+b-2b=2b$"],"설명":"⑤는 3b+b-2b=2b로 식과 일치하므로 옳다.","확인":null,"스킬":"N7"}],"fb":"fig/ns/"},"ns-0f3ee31b0dcb":{"길":"a 를 뺀 다섯 수를 정렬하고 a 의 자리별 중앙값을 따져 ㄱ, ㄴ, ㄷ 을 판정","단계":[{"제목":"다섯 수 정렬과 ㄱ 판별","힌트":"a 를 뺀 다섯 수를 작은 값부터 늘어놓으면 a 는 몇째 자리까지 들어갈 수 있는가","식":["$7,\\ 10,\\ 14,\\ 16,\\ 19$","$a<14$"],"설명":"a 를 뺀 다섯 수는 7, 10, 14, 16, 19 이다. 여섯 개 자료의 중앙값은 셋째와 넷째의 평균인데, a 가 넷째 이후에 들어가면 중앙값이 a 이하가 된다. 중앙값이 a 보다 크려면 a 는 작은 값부터 첫째, 둘째, 셋째 자리에 와야 하므로 ㄱ 은 옳다.","확인":null,"스킬":"C2"},{"제목":"경우를 나눠 중앙값 범위 구하기","고비":true,"힌트":"a 가 10 이하일 때와 10 보다 클 때 셋째·넷째 값은 각각 무엇인가","식":["$a\\le10:\\ \\dfrac{10+14}{2}=12$","$10<a<14:\\ \\dfrac{a+14}{2}$","$12<\\dfrac{a+14}{2}<14$"],"설명":"a 가 10 이하이면 셋째가 10, 넷째가 14 이므로 중앙값은 늘 12 이다. 10 < a < 14 이면 셋째가 a 이므로 중앙값 (a+14)/2 는 12 보다 크고 14 보다 작다. 따라서 가능한 중앙값은 12 이상 14 미만이고 그중 자연수는 12, 13 뿐이므로 ㄴ 은 옳다.","확인":null,"스킬":"C2"},{"제목":"16 이 160 이 될 때 ㄷ 판별","힌트":"16 이 160 이 되면 정렬한 순서에서 셋째·넷째 값이 달라지는가","식":["a=8 일 때 $7,\\ 8,\\ 10,\\ 14,\\ 16,\\ 19$ → 중앙값 $\\dfrac{10+14}{2}=12$","16 이 160 이면 $7,\\ 8,\\ 10,\\ 14,\\ 19,\\ 160$ → 중앙값 $\\dfrac{10+14}{2}=12$"],"설명":"중앙값은 정렬한 여섯 수의 셋째와 넷째로 정해진다. 16 은 a 가 어디에 있어도 다섯째 자리이므로 160 이 되어도 여섯째 자리로 옮겨 갈 뿐 셋째·넷째 값은 그대로다. 따라서 중앙값은 바뀌지 않아 ㄷ 은 옳지 않고, 옳은 것은 ㄱ, ㄴ 이다.","확인":null,"스킬":"C3"}]},"ns-14b72d7035ab":{"길":"근호 안이 제곱수가 되는 a-b 를 찾아 순서쌍을 세고 전체 경우로 나눈다","단계":[{"제목":"근의 공식 세우기","힌트":"$x^2-3x+a-b-1=0$ 에 근의 공식을 쓰면 근호 안은?","식":["$x=\\frac{3\\pm\\sqrt{13-4(a-b)}}{2}$"],"설명":"근호 안은 $(-3)^2-4(a-b-1)=13-4(a-b)$ 이다.","확인":null,"스킬":"A6"},{"제목":"유리수 조건 정하기","힌트":"근호 안 $13-4(a-b)$ 가 $0$ 또는 제곱수이려면 $a-b$ 는?","식":["$13-4(a-b)=1,\\ 9,\\ 25$","$a-b=3,\\ 1,\\ -3$"],"설명":"$a-b$ 는 $-5$ 이상 $5$ 이하의 정수라 $13-4(a-b)$ 는 홀수이고 $-7$ 이상 $33$ 이하이다. 이 범위의 홀수인 제곱수는 $1$, $9$, $25$ 뿐이므로 $a-b=3$, $1$, $-3$ 이다.","확인":null,"스킬":"N8","고비":true},{"제목":"각 경우의 순서쌍 세기","힌트":"$a-b=3$, $1$, $-3$ 인 $(a,\\ b)$ 는 각각 몇 개?","식":["$a-b=3$ → $3$개","$a-b=1$ → $5$개","$a-b=-3$ → $3$개"],"설명":"$a-b=3$ 은 $(4,1),(5,2),(6,3)$, $a-b=1$ 은 $(2,1),(3,2),(4,3),(5,4),(6,5)$, $a-b=-3$ 은 $(1,4),(2,5),(3,6)$ 이다.","확인":null,"스킬":"P4"},{"제목":"확률 계산하기","힌트":"전체 $36$ 가지 중 조건을 만족하는 경우는?","식":["$\\frac{3+5+3}{36}=\\frac{11}{36}$"],"설명":"조건을 만족하는 순서쌍은 $3+5+3$ 개이고 전체는 $6\\times6=36$ 개이다.","확인":"11/36","스킬":"N6"}]},"ns-152c8e497f5b":{"길":"x를 a로 바꿔 두 근호를 완전제곱 꼴로 만들고 2<a<3 범위로 부호를 정한다","단계":[{"제목":"x를 a로 나타내기","힌트":"√x=a-2이면 x는?","식":["$x=(a-2)^{2}=a^{2}-4a+4$"],"설명":"양변을 제곱해 x를 a에 관한 식으로 바꾼다.","확인":null,"스킬":"A6"},{"제목":"두 근호를 완전제곱으로 만들기","힌트":"x+2a-3과 x-2a+5에 대입해 정리하면?","식":["$\\sqrt{(a-1)^{2}}-\\sqrt{(a-3)^{2}}$"],"설명":"각각 (a-1)², (a-3)² 꼴로 정리된다.","확인":null,"스킬":"A6"},{"제목":"범위로 부호 정하기","고비":true,"힌트":"2<a<3이면 a-1과 a-3의 부호는?","식":["$a-1>0,\\ a-3<0$"],"설명":"이 범위에서 a-1은 양수, a-3은 음수이다.","확인":null,"스킬":"C2"},{"제목":"절댓값 풀어 계산하기","힌트":"부호를 반영해 빼면?","식":["$(a-1)-\\{-(a-3)\\}=2a-4$"],"설명":"정리하면 2a-4이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-164e9c00de0e":{"길":"D의 실제 키를 방정식으로 구한 뒤, 나머지 학생의 범위 조건으로 중앙값의 범위를 좁힌다","단계":[{"제목":"D의 키 구하기","힌트":"F를 포함한 평균 160cm 식을 세우면?","식":["$\\frac{161.5\\times5-d+166}{5}=160$"],"설명":"D 대신 F(166cm)를 넣은 평균이 160cm라는 조건으로 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"방정식 풀어 d 구하기","고비":true,"힌트":"식을 정리하면 d는?","식":["$973.5-d=800$","$d=173.5$"],"설명":"D의 실제 키는 173.5cm이다.","확인":"173.5","스킬":"A10"},{"제목":"A,B,E의 범위 조건 세우기","힌트":"A,B,C,D,E의 중앙값이 161이려면 a,b,e는 161과 어떤 관계일까?","식":["$a\\le161,\\ b\\le161,\\ e\\ge161$"],"설명":"처음 다섯 명의 중앙값이 161이므로 a, b는 161 이하, e는 161 이상이어야 한다.","확인":null,"스킬":"C2"},{"제목":"여섯 명의 중앙값 범위 구하기","힌트":"166과 173.5 사이에서 중앙값이 놓일 수 있는 범위는?","식":["$161\\le(중앙값)\\le163.5$"],"설명":"a, b, 161, 166, e, 173.5의 배열을 살펴보면 중앙값은 161 이상 163.5 이하의 값만 가질 수 있으므로, 이 범위를 벗어나는 164.5cm는 중앙값이 될 수 없다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-1815c2e0e8a0":{"길":"이차식을 x에 관해 정리하고 상수항을 인수분해해 전체를 두 일차식으로 나눈다","단계":[{"제목":"x에 관해 내림차순 정리하기","힌트":"y에 관한 항을 상수처럼 묶어 x에 관해 정리하면?","식":["$2x^2-(7y+14)x+3y^2+2y-16$"],"설명":"x에 관한 이차식으로 정리한다.","확인":null,"스킬":"A3"},{"제목":"상수항을 인수분해하기","고비":true,"힌트":"3y²+2y-16을 인수분해하면?","식":["$3y^2+2y-16=(3y+8)(y-2)$"],"설명":"상수항을 y에 관해 인수분해해 두 인수를 찾는다.","확인":null,"스킬":"N4"},{"제목":"전체 인수분해하기","힌트":"2x²의 계수를 맞춰 두 일차식으로 묶으면?","식":["$2x^2-(7y+14)x+(3y+8)(y-2)=(x-3y-8)(2x-y+2)$"],"설명":"교차법으로 전체를 두 일차식의 곱으로 인수분해한다.","확인":null,"스킬":"A3"},{"제목":"a+b+c+d 계산하기","힌트":"a=-3, b=-8, c=-1, d=2를 더하면?","식":["$a+b+c+d=-3-8-1+2=-10$"],"설명":"계수를 비교해 얻은 값을 모두 더하면 -10이다.","확인":"-10","스킬":"A3"}],"fb":"fig/ns/"},"ns-19557671e607":{"길":"세 진술을 근의 공식과 반례로 하나씩 확인한다","단계":[{"제목":"가 진술 확인하기","힌트":"근의 공식을 그대로 적용하면?","식":["$x=-b\\pm\\sqrt{b^2-c}$"],"설명":"근의 공식에 의해 가는 옳다.","확인":null,"스킬":"A6"},{"제목":"나 진술 확인하기","힌트":"해가 유리수이면 항상 c=0일까?","식":[],"설명":"c=0이면 해가 유리수이지만 역은 성립하지 않으므로 나는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"다 진술 반례 찾기","고비":true,"힌트":"b=2, c=-4인 경우를 대입하면?","식":["$x=-2\\pm\\sqrt{2^2-(-4)}=-2\\pm2\\sqrt2$"],"설명":"중근이 아닌 반례가 있으므로 다는 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-1994926ac261":{"길":"양변을 x로 나눠 대칭식으로 바꾼 뒤 곱셈공식으로 필요한 값을 구한다","단계":[{"제목":"양변을 x로 나눠 대칭식 만들기","힌트":"x²-2x+1=0의 양변을 x로 나누면?","식":["$x-2+\\frac1x=0\\Rightarrow x+\\frac1x=2$"],"설명":"x≠0이므로 양변을 x로 나눠 x+1/x=2를 얻는다.","확인":null,"스킬":"A2"},{"제목":"x²+1/x² 구하기","고비":true,"힌트":"(x+1/x)²을 이용하면?","식":["$x^2+\\frac1{x^2}=\\left(x+\\frac1x\\right)^2-2=2^2-2=2$"],"설명":"곱셈공식을 이용해 x²+1/x²의 값을 구한다.","확인":null,"스킬":"A2"},{"제목":"구하는 식으로 정리하기","힌트":"x²-2x-2/x+1/x²을 (x²+1/x²)과 (x+1/x)로 묶으면?","식":["$\\left(x^2+\\frac1{x^2}\\right)-2\\left(x+\\frac1x\\right)=2-2\\times2=-2$"],"설명":"앞서 구한 값을 대입해 정리하면 -2다.","확인":"-2","스킬":"A2"}],"fb":"fig/ns/"},"ns-1b0808a462cd":{"길":"a의 범위로 부호를 정하고 근호 안을 완전제곱 꼴로 바꿔 절댓값을 정리한다","단계":[{"제목":"0<a<1에서 부호 정하기","힌트":"a-1/a와 a+1/a의 부호는?","식":["$0<a<1\\Rightarrow a-\\frac1a<0,\\ a+\\frac1a>0$"],"설명":"a가 0과 1 사이이므로 a-1/a는 음수, a+1/a는 양수다.","확인":null,"스킬":"C2"},{"제목":"근호 안을 완전제곱 꼴로 바꾸기","고비":true,"힌트":"각 식에 2, -2를 더하고 빼서 (a±1/a)² 꼴로 만들면?","식":["$\\sqrt{a^2+2+\\frac1{a^2}}+\\sqrt{a^2-2+\\frac1{a^2}}=\\sqrt{\\left(a+\\frac1a\\right)^2}+\\sqrt{\\left(a-\\frac1a\\right)^2}$"],"설명":"근호 안을 완전제곱식으로 바꿔 쓴다.","확인":null,"스킬":"A6"},{"제목":"부호에 맞게 근호 풀어 정리하기","힌트":"부호에 따라 절댓값을 풀면?","식":["$=\\left(a+\\frac1a\\right)+\\left(-a+\\frac1a\\right)=\\frac2a$"],"설명":"부호에 맞게 근호를 풀어 더하면 2/a가 남는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-1b3ba7a6444a":{"길":"지수 차를 반으로 줄이는 인수분해를 끝까지 반복해 소인수를 모두 꺼낸 뒤 조건에 맞는 두 인수를 고른다","단계":[{"제목":"거듭제곱 차 인수분해 시작하기","힌트":"$2^{64}-1$을 $(2^{32}+1)(2^{32}-1)$로 쪼개면?","식":["$2^{64}-1=(2^{32}+1)(2^{32}-1)$"],"설명":"$a^2-b^2=(a+b)(a-b)$ 공식을 적용해 지수를 절반으로 줄인다.","확인":null,"스킬":"N1"},{"제목":"같은 과정 끝까지 반복하기","고비":true,"힌트":"$2^{32}-1$도 같은 방법으로 계속 쪼개면 끝에 무엇이 남을까?","식":["$2^{64}-1=(2^{32}+1)(2^{16}+1)(2^{8}+1)(2^{4}+1)(2^{2}+1)\\times(2+1)\\times(2-1)$","$=(2^{32}+1)(2^{16}+1)(2^{8}+1)\\times17\\times5\\times3$"],"설명":"지수를 절반씩 줄이는 인수분해를 끝까지 반복하면 마지막에 17, 5, 3이 인수로 남는다.","확인":null,"스킬":"N1"},{"제목":"10과 20 사이 두 인수 찾기","힌트":"17, 5, 3 가운데 10보다 크고 20보다 작은 수와 그 곱은?","식":["$15=3\\times5,\\ 17$","$A+B=15+17=32$"],"설명":"15와 17이 모두 10과 20 사이의 자연수이면서 원래 식의 인수이므로 A+B=32이다.","확인":"32","스킬":"A2"}],"fb":"fig/ns/"},"ns-1c52ee3098ac":{"길":"a의 자릿수 m을 부등식으로 구하고, x²+y² 범위를 만족하는 순서쌍 개수 n을 세어 곱한다","단계":[{"제목":"a의 범위 정하기","힌트":"일곱 자리 자연수 a의 범위는?","식":["$10^{6}\\le a<10^{7}$"],"설명":"일곱 자리 자연수의 범위를 부등식으로 쓴다.","확인":null,"스킬":"N1"},{"제목":"√a의 자릿수 m 구하기","힌트":"√a의 범위를 구하면 몇 자리 수일까?","식":["$1000\\le\\sqrt{a}<1000\\sqrt{10}$"],"설명":"√a는 4자리 자연수이므로 m=4이다.","확인":"4","스킬":"N7"},{"제목":"x²+y²의 범위 구하기","힌트":"√(x²+y²)의 정수부분이 8이 되려면?","식":["$64\\le x^{2}+y^{2}<81$"],"설명":"정수부분이 8이 되는 x²+y²의 범위를 부등식으로 쓴다.","확인":null,"스킬":"N7"},{"제목":"조건을 만족하는 순서쌍 세기","고비":true,"힌트":"x≥y인 자연수 중 이 범위를 만족하는 (x,y)는?","식":["$(8,1),(8,2),(8,3),(8,4),(7,4),(7,5),(6,6)$"],"설명":"빠짐없이 세면 7개이므로 n=7이다.","확인":"7","스킬":"P4"},{"제목":"mn 계산하기","힌트":"m과 n을 곱하면?","식":["$4\\times7=28$"],"설명":"mn=28이다.","확인":"28","스킬":"A3"}],"fb":"fig/ns/"},"ns-1d5025dc26be":{"길":"쉬운 다항식을 먼저 인수분해해 두 경우로 나눠 공통인수 조건을 맞춘다","단계":[{"제목":"쉬운 다항식 먼저 인수분해하기","힌트":"$x^2-(a+1)x+a$는 $x=1$을 넣으면 0이 되지 않을까?","식":["$x^{2}-(a+1)x+a=(x-1)(x-a)$"],"설명":"이 다항식은 항상 x-1과 x-a를 인수로 갖는다.","확인":null,"스킬":"A4"},{"제목":"공통인수가 x-1인 경우 살펴보기","힌트":"$x^2-(a+5)x+a+8$이 $(x-1)(x+m)$ 꼴이라면?","식":["$x^{2}-(a+5)x+a+8=(x-1)(x+m)$","$a+5=1-m,\\ a+8=-m$"],"설명":"두 식을 연립하면 모순이 생겨 이 경우에는 a가 존재하지 않는다.","확인":null,"스킬":"C2"},{"제목":"공통인수가 x-a인 경우 풀기","고비":true,"힌트":"이번엔 $(x-a)(x+n)$ 꼴로 놓으면 a는?","식":["$x^{2}-(a+5)x+a+8=(x-a)(x+n)$","$n=-5,\\ a=2$"],"설명":"계수를 비교해 연립하면 n=-5, a=2가 나오며 이 경우만 성립한다.","확인":"2","스킬":"C2"}],"fb":"fig/ns/"},"ns-1ed8da3e32d7":{"길":"계수를 비교해 c를 구한 뒤 조건을 만족하는 정수쌍을 모두 찾아 개수를 센다","단계":[{"제목":"식을 정리해 완전제곱 형태와 비교하기","힌트":"두 다항식을 빼서 $a(x-c)^2$ 꼴과 비교하면?","식":["$ax^{2}-4ax+b^{2}+4=ax^{2}-2acx+ac^{2}$"],"설명":"주어진 식을 빼고 우변 a(x-c)^2을 전개해 계수를 맞춘다.","확인":null,"스킬":"A3"},{"제목":"x 계수를 비교해 c 구하기","힌트":"$-4a=-2ac$에서 c는?","식":["$-4a=-2ac\\ \\Rightarrow\\ c=2$"],"설명":"x의 계수를 비교하면 c=2로 정해진다.","확인":"2","스킬":"A3"},{"제목":"상수항을 비교해 a, b 관계식 세우기","힌트":"$b^2+4=ac^2$에 c=2를 넣으면?","식":["$b^{2}+4=4a\\ \\Rightarrow\\ b^{2}=4(a-1)$"],"설명":"상수항을 비교해 a와 b 사이의 관계식을 얻는다.","확인":null,"스킬":"A3"},{"제목":"조건을 만족하는 정수쌍 모두 찾기","고비":true,"힌트":"$|b|\\le10$인 짝수 b를 하나씩 넣어 확인하면? b=0인 경우도 빠뜨리지 않았는가?","식":["$(a,b)=(26,\\pm10),(17,\\pm8),(10,\\pm6),(5,\\pm4),(2,\\pm2),(1,0)$"],"설명":"b가 짝수일 때만 a가 정수가 되며, b=0, a=1인 경우까지 포함하면 모두 11개다.","확인":"11","스킬":"N4"},{"제목":"cd 값 구하기","힌트":"c=2, d=11을 곱하면?","식":["$cd=2\\times11=22$"],"설명":"c=2와 d=11을 곱하면 22이다.","확인":"22","스킬":"A3"}],"fb":"fig/ns/"},"ns-202a9a73791b":{"길":"두 번 치환해 완전제곱 구조를 드러낸 뒤 분모까지 정리해 계산한다","단계":[{"제목":"공통부분을 A로 치환하기","힌트":"21을 A로 놓으면 22, 25, 26은 어떻게 표현될까?","식":["$A=21,\\ 22=A+1,\\ 25=A+4,\\ 26=A+5$"],"설명":"연속한 수들을 A=21 기준으로 바꿔 쓴다.","확인":null,"스킬":"A1"},{"제목":"분자를 B로 다시 치환해 완전제곱 만들기","힌트":"$(A+1)(A+4)A(A+5)$를 두 쌍으로 묶어 $B=A^2+5A$로 놓으면?","식":["$(A^{2}+5A+4)(A^{2}+5A)+4=(B+4)B+4=(B+2)^{2}$"],"설명":"두 항을 곱으로 묶으면 B=A^2+5A에 대한 완전제곱식이 된다.","확인":null,"스킬":"A1"},{"제목":"분모도 완전제곱으로 바꾸기","고비":true,"힌트":"분모 $142^2-1420+25$도 완전제곱으로 고치면?","식":["$142^{2}-2\\times142\\times5+5^{2}=137^{2}$"],"설명":"분모는 (142-5)^2=137^2이 되어 분자의 제곱과 짝이 맞는다.","확인":null,"스킬":"A1"},{"제목":"값을 계산해 최종 답 구하기","힌트":"548을 137로 나누면 얼마가 남을까?","식":["$\\frac{548^{2}}{137^{2}}+9=4^{2}+9=25$","$\\sqrt{25}=5$"],"설명":"548=137×4이므로 값을 계산하면 답은 5가 된다.","확인":"5","스킬":"N6"}],"fb":"fig/ns/"},"ns-20b2f77cef27":{"길":"부등식을 풀어 x의 범위를 구하고 무리수 값을 정수 사이로 좁혀 최소 정수를 찾는다","단계":[{"제목":"부등식 정리하기","힌트":"2x+8<√5(3+x)를 x항끼리 모으면?","식":["$(2-\\sqrt{5})x<3\\sqrt{5}-8$"],"설명":"양변을 정리해 x에 관한 부등식으로 만든다.","확인":null,"스킬":"A10"},{"제목":"부호를 살펴 부등호 방향 정하기","고비":true,"힌트":"2-√5는 음수일까 양수일까?","식":["$x>\\frac{3\\sqrt{5}-8}{2-\\sqrt{5}}=1+2\\sqrt{5}$"],"설명":"2-√5<0이므로 양변을 나눌 때 부등호 방향이 바뀐다.","확인":null,"스킬":"C2"},{"제목":"1+2√5의 범위 좁히기","힌트":"4<2√5<5이면 1+2√5는?","식":["$5<1+2\\sqrt{5}<6$"],"설명":"1+2√5는 5와 6 사이의 값이다.","확인":null,"스킬":"N7"},{"제목":"가장 작은 정수 찾기","힌트":"x가 이 값보다 커야 하므로 가장 작은 정수는?","식":["$6$"],"설명":"x>1+2√5(≈5.47)를 만족하는 가장 작은 정수는 6이다.","확인":"6","스킬":"N7"}],"fb":"fig/ns/"},"ns-25c35f164e9b":{"길":"합차 공식으로 묶은 뒤 두 수의 곱을 구해 대입한다","단계":[{"제목":"합차 공식으로 인수분해하기","힌트":"$(x^n-y^n)^2-(x^n+y^n)^2$을 합차 공식으로 묶으면?","식":["$(x^{n}-y^{n})^{2}-(x^{n}+y^{n})^{2}=(2x^{n})(-2y^{n})=-4(xy)^{n}$"],"설명":"합차 공식 $A^2-B^2=(A+B)(A-B)$를 적용하면 $-4(xy)^n$ 꼴로 정리된다.","확인":null,"스킬":"A2"},{"제목":"xy 값 구하기","고비":true,"힌트":"$x=9-4\\sqrt5$, $y=9+4\\sqrt5$의 곱은?","식":["$xy=(9-4\\sqrt5)(9+4\\sqrt5)=81-80=1$"],"설명":"합차 공식으로 곱을 계산하면 xy=1이다.","확인":"1","스킬":"A2"},{"제목":"최종 값 계산하기","힌트":"xy=1을 대입하면?","식":["$-4\\times1^{n}=-4$"],"설명":"xy=1이므로 n에 관계없이 값은 -4이다.","확인":"-4","스킬":"A2"}],"fb":"fig/ns/"},"ns-288e6687c625":{"길":"근과 계수의 관계로 합을 구하고 최대공약수 구조로 두 수를 정한다","단계":[{"제목":"근과 계수의 관계로 합 구하기","힌트":"이차방정식 x²-24x+k=0에서 두 근의 합은?","식":["$a+b=24$"],"설명":"근과 계수의 관계에 의해 두 근의 합은 24이다.","확인":null,"스킬":"A2"},{"제목":"최대공약수 구조로 a, b 정하기","고비":true,"힌트":"최대공약수가 3이고 a>b>3인 조건을 만족하는 a, b는?","식":["$a=15,\\ b=9$"],"설명":"합이 24이면서 최대공약수가 3인 조건을 만족하는 값은 15와 9뿐이다.","확인":null,"스킬":"N2"},{"제목":"k 값 구하기","힌트":"근과 계수의 관계에서 두 근의 곱은 k와 같다","식":["$k=ab=15\\times9=135$"],"설명":"두 근의 곱이 k이므로 값을 계산한다.","확인":"135","스킬":"A2"}],"fb":"fig/ns/"},"ns-292828986a86":{"길":"완전제곱 형태로 정리해 근호를 풀고 기약분수를 구한다","단계":[{"제목":"완전제곱 형태 만들기","힌트":"291을 289+2로 바꾸면 어떤 완전제곱식이 보일까?","식":["$291+\\frac{1}{289}=17^{2}+2+\\frac{1}{17^{2}}=\\left(17+\\frac{1}{17}\\right)^{2}$"],"설명":"289=17²임을 이용해 완전제곱 꼴로 정리한다.","확인":null,"스킬":"A6"},{"제목":"제곱근을 풀어 분수로 바꾸기","고비":true,"힌트":"근호를 벗기면 얼마가 남을까?","식":["$\\sqrt{\\left(17+\\frac{1}{17}\\right)^{2}}=17+\\frac{1}{17}=\\frac{290}{17}$"],"설명":"근호가 풀리면 기약분수 290/17이 남는다.","확인":"290/17","스킬":"N6"},{"제목":"A+B 계산하기","힌트":"A=17, B=290을 더하면?","식":["$A+B=17+290=307$"],"설명":"따라서 A+B=307이다.","확인":"307","스킬":"A2"}],"fb":"fig/ns/"},"ns-2ae62cb81ba9":{"길":"근의 공식으로 해를 나타내고 판별식이 완전제곱수가 되는 조건으로 k를 센다","단계":[{"제목":"근의 공식으로 해 나타내기","힌트":"근의 공식을 적용하면 해는 어떤 꼴일까?","식":["$x=4\\pm\\sqrt{16+k}$"],"설명":"근의 공식을 적용해 해를 16+k의 제곱근을 포함한 식으로 나타낸다.","확인":null,"스킬":"N8"},{"제목":"완전제곱수 조건 세우기","고비":true,"힌트":"해가 정수이려면 16+k는 어떤 수여야 할까?","식":["$16+k=36,49,64,81,100$"],"설명":"해가 정수이려면 16+k가 제곱수여야 하므로 가능한 값을 나열한다.","확인":null,"스킬":"N8"},{"제목":"두 자리 자연수 k 개수 세기","힌트":"이 중 두 자리 자연수 k는 몇 개일까?","식":["$k=20,33,48,65,84$"],"설명":"16+k값에서 16을 빼 k를 구하면 두 자리 자연수 k는 5개이다.","확인":"5","스킬":"P4"}],"fb":"fig/ns/"},"ns-2b86c307ba21":{"길":"다섯 선지를 삼각비 정의대로 하나씩 따져 옳은 것을 고른다","단계":[{"제목":"①, ② 판별하기","힌트":"특수각 삼각비는 정삼각형·정사각형의 절반인 직각삼각형에서 나올까?","식":[],"설명":"정사각형의 반쪽 직각삼각형이어야 하는데 직사각형이라 한 ①은 옳지 않고, sin0°=0, cos0°=1로 구할 수 있으므로 ②도 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"③ tan90° 판별하기","고비":true,"힌트":"tan90°=(대변)/(밑변)에서 밑변의 길이가 0이 되면?","식":["$\\tan90^{\\circ}=\\dfrac{대변}{0}$"],"설명":"밑변의 길이가 0이 되어 나눌 수 없으므로 tan90°는 정의할 수 없다는 ③이 옳다.","확인":null,"스킬":"S6"},{"제목":"④, ⑤ 판별하기","힌트":"sin30°와 cos30°는 같을까? 직각이등변삼각형은 크기에 따라 비가 달라질까?","식":["$\\sin30^{\\circ}=\\dfrac12,\\ \\cos30^{\\circ}=\\dfrac{\\sqrt3}{2}$"],"설명":"sin30°≠cos30°이므로 ④는 옳지 않고, 직각이등변삼각형은 모두 닮음이라 삼각비가 항상 같으므로 ⑤도 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-2bc80b285c7f":{"길":"분모를 유리화해 항을 반으로 쪼갠 뒤 이웃한 항끼리 지워 합을 구한다","단계":[{"제목":"분모 유리화하기","힌트":"1/(√(x+2)+√x)의 분모를 유리화하면?","식":["$f(x)=\\frac{\\sqrt{x+2}-\\sqrt{x}}{2}$"],"설명":"분모, 분자에 √(x+2)-√x를 곱해 유리화한다.","확인":null,"스킬":"P6"},{"제목":"항을 나열해 지우기","고비":true,"힌트":"f(1)부터 f(48)까지 더하면 가운데 항들이 어떻게 될까?","식":["$\\frac{1}{2}(-1-\\sqrt{2}+\\sqrt{49}+\\sqrt{50})$"],"설명":"이웃한 항끼리 상쇄되고 양 끝 항만 남는다.","확인":null,"스킬":"P6"},{"제목":"남은 값 계산하기","힌트":"√49, √50을 정리하면?","식":["$\\frac{1}{2}(6+4\\sqrt{2})=3+2\\sqrt{2}$"],"설명":"정리하면 3+2√2이다.","확인":null,"스킬":"N1"}],"fb":"fig/ns/"},"ns-2c88df58c0ce":{"길":"7을 7000000으로 늘려 표의 제곱값 사이에 넣고 자리를 다시 맞춘다","단계":[{"제목":"700만과 표의 제곱값 비교 준비하기","힌트":"7을 표의 수와 비교하려면 얼마를 곱해야 할까?","식":["$7\\times10^6=7000000$"],"설명":"7의 소수 자리를 표의 큰 수와 비교하려면 7에 10⁶을 곱해 7000000으로 만든다.","확인":null,"스킬":"N6"},{"제목":"부등식으로 좁히기","고비":true,"힌트":"2645², 2646² 사이 어디에 7000000이 있을까?","식":["$2645^2=6996025<7000000<7001316=2646^2$"],"설명":"표에서 7000000을 사이에 두는 두 제곱을 찾으면 2645²과 2646² 사이이다.","확인":null,"스킬":"N8"},{"제목":"최종 자리 읽기","힌트":"1000√7의 범위를 1000으로 나누면?","식":["$2645<1000\\sqrt7<2646$","$2.645<\\sqrt7<2.646$"],"설명":"부등식을 1000으로 나누면 √7은 2.645와 2.646 사이이므로 소수 셋째 자리 숫자는 5이다.","확인":"5","스킬":"N6"}],"fb":"fig/ns/"},"ns-2cae99619838":{"길":"고정된 다항식을 인수분해한 뒤 두 경우로 나눠 각 k값을 구해 곱한다","단계":[{"제목":"고정된 다항식 인수분해하기","힌트":"x²-2x-8을 인수분해하면?","식":["$x^{2}-2x-8=(x-4)(x+2)$"],"설명":"이 다항식은 항상 x-4와 x+2를 인수로 갖는다.","확인":null,"스킬":"A4"},{"제목":"공통인수가 x-4인 경우 풀기","힌트":"$x^2-(k+1)x+k+6=(x-4)(x+m)$이라 하면?","식":["$k+1=4-m,\\ -4m=k+6\\ \\Rightarrow\\ k=6$"],"설명":"계수를 비교해 연립하면 k=6이 나온다.","확인":"6","스킬":"C2"},{"제목":"공통인수가 x+2인 경우 풀고 곱 구하기","고비":true,"힌트":"$(x+2)(x+n)$으로 놓고 풀면 다른 k는?","식":["$k+1=-2-n,\\ 2n=k+6\\ \\Rightarrow\\ k=-4$","$6\\times(-4)=-24$"],"설명":"같은 방법으로 풀면 k=-4가 나오고, 두 값을 곱하면 -24이다.","확인":"-24","스킬":"C2"}],"fb":"fig/ns/"},"ns-2e55ccc61c1d":{"길":"두 근을 연속하는 정수로 놓고 제곱의 차 조건으로 근을 구한 뒤 근과 계수의 관계로 p+q를 구한다","단계":[{"제목":"두 근을 연속 정수로 놓기","힌트":"연속하는 두 양의 정수를 n, n+1로 놓으면?","식":["$두\\ 근:\\ n,\\ n+1$"],"설명":"두 근이 연속하는 양의 정수이므로 n, n+1로 놓는다.","확인":null,"스킬":"A2"},{"제목":"제곱의 차 조건으로 n 구하기","고비":true,"힌트":"(n+1)²-n²=13을 풀면?","식":["$(n+1)^2-n^2=13\\Rightarrow 2n+1=13\\Rightarrow n=6$"],"설명":"제곱의 차가 13이라는 조건으로 n=6을 구한다.","확인":null,"스킬":"A3"},{"제목":"근과 계수의 관계로 p+q 구하기","힌트":"두 근이 6, 7일 때 p, q는?","식":["$(x-6)(x-7)=0\\Rightarrow x^2-13x+42=0$","$p=-13,\\ q=42,\\ p+q=29$"],"설명":"두 근이 6과 7이므로 전개해 p, q를 구하고 더한다.","확인":"29","스킬":"A2"}],"fb":"fig/ns/"},"ns-2f61cfac5d43":{"길":"0°~90°에서 세 삼각비의 증가·감소와 정의를 다섯 선지에 적용해 옳지 않은 것을 고른다","단계":[{"제목":"①~③, ⑤ 판별하기","힌트":"A가 커질수록 sinA, tanA는 커지고, A=90°일 때 cosA는?","식":[],"설명":"0°부터 90°까지 A가 커질수록 sin A와 tan A는 커지고 cos A는 작아지므로 ①②③은 옳고, A=90°에서 cos A=0이므로 ⑤도 옳다.","확인":null,"스킬":"T5"},{"제목":"④ 판별하기","고비":true,"힌트":"A=90°일 때 tan A를 정의할 수 있을까?","식":[],"설명":"A=90°에서는 밑변의 길이가 0이 되어 tan A가 정의되지 않으므로, 값이 1이라고 한 ④는 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-30402c88756a":{"길":"두 선수의 2라운드 평균과 두 라운드의 분산을 각각 구해 다섯 선지를 확인한다","단계":[{"제목":"①,② 2라운드 평균 구하기","힌트":"A, B선수의 2라운드 평균은?","식":["$(A)=\\frac{10+8+8+10+9}{5}=9$","$(B)=\\frac{8+8+6+6+7}{5}=7$"],"설명":"A선수의 2라운드 평균은 9, B선수는 7이므로 ①, ②는 모두 옳지 않다.","확인":null,"스킬":"P4"},{"제목":"③ A선수의 두 라운드 분산 비교하기","고비":true,"힌트":"A선수의 1, 2라운드 분산을 각각 구하면?","식":["$\\frac{1^2+(-1)^2+(-1)^2+1^2+0^2}{5}=0.8$"],"설명":"A선수의 1, 2라운드 분산이 모두 0.8로 같으므로 표준편차도 같아 ③은 옳다.","확인":"0.8","스킬":"A2"},{"제목":"④,⑤ 확인하기","힌트":"B선수의 두 라운드 분산과 평균의 합을 비교하면?","식":["$(B분산,\\ 1,2라운드\\ 모두)=0.8$","$(A평균합)=8+9=17,\\ (B평균합)=9+7=16$"],"설명":"B선수도 두 라운드의 분산이 같으므로 ④는 옳지 않고, 평균의 합은 B가 A보다 작으므로 ⑤도 옳지 않다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-306b6ff046f4":{"길":"세 점의 부호와 범위를 정해 대소를 비교한 뒤, 부호를 살펴 곱셈에서 부등호가 그대로인지 확인한다","단계":[{"제목":"부호 정하기","힌트":"㉠에 따라 A, B, C의 부호는?","식":[],"설명":"㉠에 따라 점 A, B는 음수이고 점 C는 양수이다.","확인":null,"스킬":"C2"},{"제목":"B, A의 범위 구하기","힌트":"㉡, ㉢으로 B와 A의 정확한 범위는?","식":["$b=-\\sqrt5$","$-1.5<a<-0.5$"],"설명":"㉡에서 |b|=√5이고 b<0이므로 b=-√5이다. ㉢에서 A에 가장 가까운 정수가 -1이므로 -1.5<a<-0.5이다.","확인":null,"스킬":"C2"},{"제목":"세 수의 대소 관계 정하기","고비":true,"힌트":"-√5는 -1.5보다 작을까 클까?","식":["$b=-\\sqrt5<-1.5<a<-0.5<0<c$"],"설명":"√5≈2.24이므로 b=-√5는 -1.5보다 작다. 따라서 b<a<c이다.","확인":null,"스킬":"N5"},{"제목":"선지 확인해 옳지 않은 것 찾기","힌트":"a>b인데 양변에 양수 c를 곱하면 부등호는 그대로일까?","식":["$a>b,\\ c>0\\ \\Rightarrow\\ ac>bc$"],"설명":"a>b이고 c는 양수이므로 양변에 c를 곱해도 부등호 방향은 그대로다. 따라서 ac>bc이며, ④에서 ac<bc라 했으므로 ④는 옳지 않다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-32eaa20f0a31":{"길":"x=3, x=-3을 경계로 세 구간에서 A를 정리한 뒤 네 보기를 하나씩 확인한다","단계":[{"제목":"세 구간으로 나누기","힌트":"√((x-3)²)와 √((x+3)²)의 부호가 바뀌는 경계는?","식":["$x=3,\\ x=-3$"],"설명":"근호 안이 완전제곱이므로 x-3, x+3의 부호가 바뀌는 x=3, x=-3을 경계로 세 구간으로 나눈다.","확인":null,"스킬":"C2"},{"제목":"각 구간에서 A 정리하기","고비":true,"힌트":"각 구간에서 x-3, x+3의 부호를 따라 절댓값을 풀면?","식":["$x>3:\\ A=(x-3)-(x+3)=-6$","$-3<x<3:\\ A=-x+3-(x+3)=-2x$","$x<-3:\\ A=-x+3-(-x-3)=6$"],"설명":"세 구간마다 x-3, x+3의 부호대로 절댓값을 풀어 정리하면 각각 -6, -2x, 6이다.","확인":null,"스킬":"C2"},{"제목":"ㄱ, ㄹ 판별하기","힌트":"A=0이 되는 구간과 x값은?","식":["$-2x=0\\ \\Rightarrow\\ x=0$"],"설명":"A=0은 -3<x<3 구간에서만 가능하고 x=0이므로 ㄱ은 옳다. 이 구간의 식이 -2x이므로 ㄹ도 옳다.","확인":null,"스킬":"C2"},{"제목":"ㄴ, ㄷ 판별하고 답 정하기","힌트":"x≥3, x<-3 구간의 실제 값은 보기와 같은가?","식":["$x>3:\\ A=-6\\ (\\ne6)$","$x<-3:\\ A=6\\ (\\ne-6)$"],"설명":"x≥3이면 실제 A=-6이므로 ㄴ은 옳지 않고, x<-3이면 실제 A=6이므로 ㄷ도 옳지 않다. 따라서 옳은 것은 ㄱ, ㄹ이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-331408024b14":{"길":"a는 완전제곱식으로, b는 연속으로 약분되는 곱으로 각각 정리해 나눈다","단계":[{"제목":"a를 완전제곱식으로 정리하기","힌트":"396²+8×396+16을 완전제곱 꼴로 보면?","식":["$396^{2}+8\\times396+16=(396+4)^{2}=400^{2}$"],"설명":"16=4², 8×396=2×4×396이므로 완전제곱식이다.","확인":null,"스킬":"A6"},{"제목":"a 값 구하기","힌트":"근호를 풀면?","식":["$a=\\sqrt{400^{2}}=400$"],"설명":"근호를 풀면 a=400이다.","확인":"400","스킬":"N6"},{"제목":"b를 약분되는 곱으로 정리하기","고비":true,"힌트":"$1-\\frac{1}{n^2}$을 $\\frac{(n-1)(n+1)}{n^2}$ 형태로 바꿔 연속으로 약분하면?","식":["$15\\times\\frac{1\\times3}{2\\times2}\\times\\frac{2\\times4}{3\\times3}\\times\\cdots\\times\\frac{14\\times16}{15\\times15}=15\\times\\frac{1}{2}\\times\\frac{16}{15}=8$"],"설명":"각 항을 인수분해해 늘어놓으면 대부분 약분되어 사라지고 b=8이 남는다.","확인":"8","스킬":"P1"},{"제목":"a/b 계산하기","힌트":"400을 8로 나누면?","식":["$\\frac{a}{b}=\\frac{400}{8}=50$"],"설명":"따라서 a/b=50이다.","확인":"50","스킬":"N6"}],"fb":"fig/ns/"},"ns-36f1a95649ca":{"길":"완전제곱식 만드는 과정을 그대로 따라가며 각 빈칸의 값을 계산해 확인한다","단계":[{"제목":"이차항 계수로 나누기(㉮)","힌트":"양변을 2로 나누면 상수항은?","식":["$x^2+4x+\\frac12=0$"],"설명":"x²의 계수 2로 양변을 나누어 상수항 ㉮=1/2을 얻는다.","확인":null,"스킬":"A6"},{"제목":"완전제곱 만들 값 더하기(㉯,㉰)","힌트":"x²+4x를 완전제곱식으로 만들려면 몇을 더해야 할까?","식":["$x^2+4x+4=-\\frac12+4$","$(x+2)^2=\\frac72$"],"설명":"양변에 4(=㉯)를 더해 완전제곱식으로 만들면 ㉰=7/2이다.","확인":null,"스킬":"A6"},{"제목":"제곱근 취하기(㉱)","힌트":"양변에 제곱근을 취하면?","식":["$x+2=\\pm\\sqrt{\\frac72}$"],"설명":"양변에 제곱근을 취해 ㉱를 구한다.","확인":null,"스킬":"A6"},{"제목":"최종 해 계산해 오류 찾기(㉲)","고비":true,"힌트":"√(7/2)를 유리화하면 실제 해는?","식":["$x=-2\\pm\\frac{\\sqrt{14}}{2}$"],"설명":"√(7/2)=√14/2이므로 실제 해는 ±√14/2인데 ㉲는 ±√7/2로 틀렸다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-371a733c1fd7":{"길":"x-y를 곱해 합차 공식을 반복 적용한 뒤 a, b를 찾아 곱한다","단계":[{"제목":"x-y 값 구하기","힌트":"y=x-16에서 x-y는?","식":["$x-y=16$"],"설명":"주어진 관계식에서 x-y=16임을 얻는다.","확인":"16","스킬":"A2"},{"제목":"x-y를 곱해 식을 묶어나가기","고비":true,"힌트":"$(x+y)(x^2+y^2)(x^4+y^4)$에 $\\frac{x-y}{16}$을 곱하면 합차 공식이 반복되어 어떻게 될까?","식":["$\\frac{1}{16}(x-y)(x+y)(x^{2}+y^{2})(x^{4}+y^{4})=\\frac{1}{16}(x^{8}-y^{8})$"],"설명":"x-y를 곱해 합차 공식을 세 번 반복 적용하면 x⁸-y⁸ 꼴로 정리된다.","확인":null,"스킬":"A2"},{"제목":"a, b 값을 찾아 곱 구하기","힌트":"a=1/16, b=8을 곱하면?","식":["$a=\\frac{1}{16},\\ b=8,\\ ab=\\frac{1}{2}$"],"설명":"따라서 a=1/16, b=8이므로 ab=1/2이다.","확인":"1/2","스킬":"A2"}],"fb":"fig/ns/"},"ns-38205cdd366e":{"길":"접선-현 각을 원주각으로 옮기고 지름 보조선을 그어 직각삼각형의 삼각비로 AB를 구한다","단계":[{"제목":"접선과 현이 이루는 각 옮기기","힌트":"접선과 현이 이루는 각은 그 호에 대한 원주각과 같다는 성질을 쓰면 ∠BCA는?","식":["$\\angle BCA=42^\\circ$"],"설명":"접선과 현이 이루는 각의 성질에 의해 ∠BCA=42°이다.","확인":null,"스킬":"S5"},{"제목":"지름이 되도록 보조선 긋기","고비":true,"힌트":"AO를 연장해 원과 만나는 점 C'을 잡으면 AC'은 무엇이 될까?","식":["$\\overline{AC'}=10,\\ \\angle ABC'=90^\\circ,\\ \\angle BC'A=42^\\circ$"],"설명":"AO의 연장선이 원과 만나는 점 C'을 잡으면 AC'은 지름(=10)이 되어 ∠ABC'=90°이고, 같은 호의 원주각이므로 ∠BC'A=42°이다.","확인":null,"스킬":"S2"},{"제목":"직각삼각형에서 AB 구하기","힌트":"직각삼각형 ABC'에서 sin을 쓰면 AB는?","식":["$\\overline{AB}=10\\sin42^\\circ$"],"설명":"직각삼각형 ABC'에서 삼각비를 이용하면 AB=10sin42°(cm)이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-39566b7b4c87":{"길":"다섯 선지를 특수각과 극단값 대입으로 하나씩 검증한다","단계":[{"제목":"①, ② 판별하기","힌트":"sinA-cosA은 항상 같을까, sinA의 최솟·최댓값은?","식":["$A=30^{\\circ}:\\sin A-\\cos A=\\dfrac{1-\\sqrt3}{2}$","$A=45^{\\circ}:\\sin A-\\cos A=0$"],"설명":"A값에 따라 sinA-cosA 값이 달라지므로 ①은 옳지 않고, sinA의 최솟값은 0, 최댓값은 1이므로 ②도 옳지 않다.","확인":null,"스킬":"T5"},{"제목":"③ 판별하기","힌트":"A=0°일 때 sinA와 tanA를 비교하면?","식":["$A=0^{\\circ}:\\sin A=\\tan A=0$"],"설명":"A=0°에서 sinA=tanA이므로 tanA가 항상 더 크다는 ③은 옳지 않다.","확인":null,"스킬":"T5"},{"제목":"④ 판별하기","힌트":"tanA도 항상 0~1 사이의 값일까?","식":["$\\tan45^{\\circ}=1$"],"설명":"45°보다 큰 A에서는 tanA가 1보다 커지므로 모든 삼각비가 0~1이라는 ④는 옳지 않다.","확인":null,"스킬":"T5"},{"제목":"⑤ 판별하기","고비":true,"힌트":"A가 커질수록 sinA는 항상 커질까?","식":[],"설명":"0°부터 90°까지 A가 커지면 sinA도 함께 커지므로 ⑤가 옳다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-3ae7d83ab238":{"길":"전체 학생 수를 문자로 두고 평균과 중앙값이 어떻게 바뀌는지 식으로 따진다","단계":[{"제목":"두 점수를 포함한 평균 식 세우기","힌트":"전체 학생 수를 x라 하면 평균은 어떻게 쓸 수 있을까?","식":["$(평균)=\\frac{60(x-2)+40+90}{x}=60+\\frac{10}{x}$"],"설명":"두 점수를 포함한 평균을 식으로 쓰면 60보다 10/x만큼 크므로 평균은 60점보다 크다.","확인":null,"스킬":"C7"},{"제목":"두 점수가 중앙값 양옆에 하나씩 늘어남을 보기","힌트":"40점은 기존 중앙값보다 작고 90점은 크다면 중앙값의 위치는 어떻게 움직일까?","식":[],"설명":"40점은 기존 중앙값 50보다 작은 쪽에, 90점은 큰 쪽에 하나씩 추가되므로 중앙값보다 작은 값과 큰 값이 각각 하나씩 늘어난다.","확인":null,"스킬":"C2"},{"제목":"중앙값이 그대로임을 확정하기","고비":true,"힌트":"작은 값과 큰 값이 대칭적으로 하나씩 늘면 중앙값의 위치는 변할까?","식":[],"설명":"전체 학생 수가 홀수로 유지되면서 중앙값보다 작은 값과 큰 값이 대칭적으로 하나씩 늘어나므로 중앙값의 위치는 그대로이고 값도 50으로 변함없다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-3b6a93e0db73":{"길":"x=-4, x=4를 경계로 세 구간에서 A를 정리한 뒤 세 보기를 하나씩 확인한다","단계":[{"제목":"절댓값 기준 경계 나누기","힌트":"x-4, x+4의 부호가 바뀌는 경계는?","식":["$x=4,\\ x=-4$"],"설명":"근호 안이 완전제곱이므로 x=-4, x=4를 경계로 세 구간을 나눈다.","확인":null,"스킬":"C2"},{"제목":"각 구간에서 식 정리하기","고비":true,"힌트":"각 구간에서 x-4, x+4의 부호대로 절댓값을 풀면?","식":["$x<-4:\\ A=8$","$-4<x<4:\\ A=-2x$","$x>4:\\ A=-8$"],"설명":"세 구간마다 부호대로 절댓값을 풀어 정리하면 각각 8, -2x, -8이다.","확인":null,"스킬":"C2"},{"제목":"ㄱ, ㄴ 판별하기","힌트":"ㄱ과 ㄴ의 구간은 위 결과와 일치하는가?","식":[],"설명":"x<-4이면 A=8이므로 ㄱ은 옳고, -4<x<1은 -4<x<4에 포함되어 A=-2x이므로 ㄴ도 옳다.","확인":null,"스킬":"C2"},{"제목":"ㄷ 판별하고 답 정하기","힌트":"x>4일 때 실제 값은 0인가?","식":["$x>4:\\ A=-8\\ (\\ne0)$"],"설명":"x>4이면 실제 A=-8이므로 ㄷ은 옳지 않다. 따라서 옳은 것은 ㄱ, ㄴ이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-3bfe43776b4e":{"길":"다섯 선택지를 판별식과 대입으로 하나씩 확인해 옳은 것을 고른다","단계":[{"제목":"①, ② 판별하기","힌트":"a=-2일 때 판별식은? x=1 대입하면 a는?","식":["$a=-2:\\ D=(-4)^2-4\\times6=-8<0$","$x=1\\ 대입:\\ a=1$"],"설명":"①은 판별식이 음수라 해가 없고, ②는 a=1일 때 다른 근이 -3이므로 둘 다 틀리다.","확인":null,"스킬":"C3"},{"제목":"③ 판별하기","고비":true,"힌트":"a=-3이면 방정식은 어떤 완전제곱식이 될까?","식":["$x^2-6x+9=0\\Rightarrow(x-3)^2=0$"],"설명":"a=-3이면 (x-3)²=0으로 중근 x=3을 가지므로 ③이 옳다.","확인":null,"스킬":"A6"},{"제목":"④, ⑤ 판별하기","힌트":"x=2 대입 시 a는? a=1일 때 판별식은?","식":["$x=2\\ 대입:\\ a=-4$","$a=1:\\ D=4+12=16>0$"],"설명":"④는 a=-4가 되어 틀리고, ⑤는 서로 다른 두 근을 가지므로 '근이 없다'는 설명이 틀리다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-3effbae66b80":{"길":"곱셈식을 합차 공식으로 정리한 뒤 범위 조건에 맞는 a, b를 구한다","단계":[{"제목":"곱셈식을 합차 공식으로 정리하기","힌트":"996×1004를 1000을 기준으로 나타내면?","식":["$996\\times1004=(1000-4)(1000+4)=1000^{2}-16$"],"설명":"합차 공식을 이용해 1000을 기준으로 정리한다.","확인":null,"스킬":"N6"},{"제목":"완전제곱 조건으로 a 값 정하기","고비":true,"힌트":"근호 안이 100의 배수인 제곱수가 되려면 -16+a는 어떤 값이어야 할까?","식":["$1000^{2}-16+a=1000^{2}\\ (a=16)$"],"설명":"범위 안에서 근호 값이 깔끔한 제곱수가 되려면 -16을 상쇄하는 a=16이어야 한다.","확인":"16","스킬":"N8"},{"제목":"b 값을 구해 최솟값 계산하기","힌트":"1000=10b²에서 b는?","식":["$b^{2}=100\\ \\Rightarrow\\ b=\\pm10$"],"설명":"b=±10 중 a+b가 최소가 되는 것은 b=-10이므로 a+b=16-10=6이다.","확인":"6","스킬":"A2"}],"fb":"fig/ns/"},"ns-415a161ae438":{"길":"완전제곱 형태로 정리해 근호를 풀고 기약분수를 구한다","단계":[{"제목":"완전제곱 형태로 정리하기","힌트":"258을 256+2로 바꾸면 어떤 완전제곱식이 보일까?","식":["$258+\\frac{1}{256}=16^{2}+2\\times16\\times\\frac{1}{16}+\\left(\\frac{1}{16}\\right)^{2}=\\left(16+\\frac{1}{16}\\right)^{2}$"],"설명":"256=16²임을 이용해 완전제곱 꼴로 만든다.","확인":null,"스킬":"A6"},{"제목":"근호를 풀어 기약분수로 바꾸기","고비":true,"힌트":"근호를 벗기면?","식":["$\\sqrt{\\left(\\frac{257}{16}\\right)^{2}}=\\frac{257}{16}$"],"설명":"근호가 풀리면 a=16, b=257인 기약분수 257/16이 된다.","확인":"257/16","스킬":"N6"},{"제목":"b-a 계산하기","힌트":"257에서 16을 빼면?","식":["$b-a=257-16=241$"],"설명":"따라서 b-a=241이다.","확인":"241","스킬":"A2"}],"fb":"fig/ns/"},"ns-42d078a998e8":{"길":"표의 각 줄을 근호와 비율의 정의대로 계산해 다섯 선지를 하나씩 확인한다","단계":[{"제목":"첫째 줄(①)과 둘째 줄(②) 계산하기","힌트":"√a=3, √(a/b)를 각각 정의대로 계산하면?","식":["$\\sqrt a=3\\Rightarrow a=9\\ (\\therefore\\text{㉠}=9)$","$\\sqrt{\\frac{a}{b}}=\\sqrt{\\frac{4}{16}}=\\frac12\\ (\\therefore\\text{㉡}=\\frac12)$"],"설명":"①은 ㉠=9인데 √3이라 했으므로 틀렸고, ②는 ㉡=1/2인데 1/4이라 했으므로 틀렸다.","확인":null,"스킬":"N8"},{"제목":"셋째 줄(③)과 넷째 줄(④) 계산하기","힌트":"√a=6, √36/√b=6/7을 각각 계산하면?","식":["$\\sqrt a=6\\Rightarrow a=36\\ (\\therefore\\text{㉢}=36)$","$\\frac{6}{\\sqrt b}=\\frac67\\Rightarrow b=49,\\ \\sqrt b=7\\ (\\therefore\\text{㉣}=7)$"],"설명":"③은 ㉢=36인데 √6이라 했으므로 틀렸고, ④는 ㉣=7인데 49라 했으므로 틀렸다.","확인":null,"스킬":"N8"},{"제목":"다섯째 줄(⑤) 계산해 답 정하기","고비":true,"힌트":"a=1/9, √b=1/4일 때 √a/√b는?","식":["$\\frac{\\sqrt a}{\\sqrt b}=\\frac{\\sqrt{1/9}}{1/4}=\\frac{1/3}{1/4}=\\frac43$"],"설명":"㉤=4/3이고 이는 ⑤의 주장과 같으므로 ⑤가 옳다.","확인":"4/3","스킬":"N8"}],"fb":"fig/ns/"},"ns-42fa48bdae50":{"길":"√3a, √2b를 자연수 u, v로 치환해 a, b가 자연수가 되는 조건을 찾아 순서쌍을 센다","단계":[{"제목":"u=√3a, v=√2b로 치환해 조건 세우기","힌트":"√3a, √2b를 자연수 u, v로 두면 u+v는?","식":["$u=\\sqrt{3a},\\ v=\\sqrt{2b}\\ (u,v는\\ 자연수),\\quad u+v=12$"],"설명":"두 근호를 자연수 u, v로 치환하면 조건은 u+v=12이다.","확인":null,"스킬":"A1"},{"제목":"a, b가 자연수가 되는 u, v 조건 찾기","고비":true,"힌트":"3a=u²이 자연수가 되려면 u는 어떤 수의 배수여야 할까?","식":["$a=\\frac{u^2}{3}\\text{가 자연수}\\Rightarrow u는\\ 3의\\ 배수$","$b=\\frac{v^2}{2}\\text{가 자연수}\\Rightarrow v는\\ 짝수$"],"설명":"a=u²/3이 자연수이려면 u²이 3의 배수여야 하므로 u가 3의 배수여야 하고, 같은 이유로 v는 짝수여야 한다.","확인":null,"스킬":"N1"},{"제목":"u+v=12를 만족하는 순서쌍 찾기","힌트":"u가 3의 배수이면서 12-u가 짝수인 경우는?","식":["$u=3\\Rightarrow v=9\\ (홀수,\\ 제외)$","$u=6\\Rightarrow v=6\\ (짝수,\\ 성립)$","$u=9\\Rightarrow v=3\\ (홀수,\\ 제외)$"],"설명":"u가 3, 6, 9일 때를 확인하면 v가 짝수인 경우는 u=6, v=6뿐이다.","확인":null,"스킬":"P4"},{"제목":"개수 세어 답 정하기","힌트":"성립하는 순서쌍은 몇 개일까?","식":["$(a,\\,b)=(12,\\,18)$의 $1$개"],"설명":"조건을 만족하는 순서쌍은 (12, 18) 하나뿐이므로 1개이다.","확인":"1","스킬":"P4"}],"fb":"fig/ns/"},"ns-42ff315c1e3d":{"길":"여덟 수를 유리수·무리수로 분류한 뒤 다섯 선지를 하나씩 확인한다","단계":[{"제목":"여덟 수를 유리수·무리수로 분류하기","힌트":"순환소수 표기와 근호 안의 완전제곱 여부를 하나씩 확인하면?","식":["$3.\\dot1\\dot4=\\frac{311}{99}(유),\\ \\sqrt{\\frac1{10}}(무),\\ \\sqrt{\\left(-\\frac32\\right)^2}=\\frac32(유),\\ \\sqrt9-\\sqrt4=1(유)$","$-\\sqrt7(무),\\ -\\sqrt{2.5}(무),\\ -\\sqrt6+1(무),\\ \\sqrt{12}(무)$"],"설명":"여덟 수를 하나씩 확인하면 유리수는 4개, 무리수는 5개(√(1/10), -√7, -√2.5, -√6+1, √12)이다.","확인":null,"스킬":"N6"},{"제목":"① 판별하기","힌트":"무리수의 개수는 몇 개인가?","식":[],"설명":"무리수는 5개이므로 ①(6개)은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"② 판별하기","힌트":"3보다 큰 무리수는?","식":["$3=\\sqrt9<\\sqrt{12}$"],"설명":"3보다 큰 무리수는 √12 하나뿐이므로 ②(2개)는 옳지 않다.","확인":null,"스킬":"N5"},{"제목":"③ 판별하기","힌트":"정수가 아닌 유리수는 무엇인가?","식":[],"설명":"정수가 아닌 유리수는 3.14̇, √((-3/2)²)의 2개이므로 ③(3개)은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"④ 판별하기","고비":true,"힌트":"-2와 0 사이에 있는 무리수는?","식":["$-2=-\\sqrt4$"],"설명":"-2와 0 사이의 무리수는 -√2.5, -√6+1의 2개이므로 ④는 옳다.","확인":null,"스킬":"N5"},{"제목":"⑤ 판별하고 답 정하기","힌트":"-√6+1과 √20을 정수로 좁히면?","식":["$-2<-\\sqrt6+1<-1,\\quad 4<\\sqrt{20}<5$"],"설명":"이 범위 사이의 자연수는 1, 2, 3, 4의 4개이므로 ⑤(5개)는 옳지 않다. 따라서 옳은 것은 ④이다.","확인":null,"스킬":"N3"}],"fb":"fig/ns/"},"ns-4664ac0c432e":{"길":"학생 수와 점수를 문자로 두고 평균과 분산이 일괄적으로 몇 점씩 더해질 때 어떻게 바뀌는지 식으로 확인한다","단계":[{"제목":"변화 후 평균 구하기","힌트":"모든 점수에 5점씩 더하면 평균은 어떻게 바뀔까?","식":["$\\frac{(x_1+5)+\\cdots+(x_{30}+5)}{30}=\\frac{30m+150}{30}=m+5$"],"설명":"평균은 원래 평균 m보다 5점 올라간다.","확인":null,"스킬":"A2"},{"제목":"변화 후 분산·표준편차 구하기","고비":true,"힌트":"각 편차 (x_i+5)-(m+5)는 원래 편차와 같을까?","식":["$(x_i+5)-(m+5)=x_i-m$"],"설명":"편차가 원래와 같으므로 분산과 표준편차는 변함없다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-48845f951ad1":{"길":"중근 조건으로 m을 구해 a를 찾고, 이를 대입해 k와 b를 구한 뒤 모두 더한다","단계":[{"제목":"중근 조건으로 m 구하기","힌트":"2x²-12x+m=0이 중근을 가지려면 판별식은?","식":["$2x^2-12x+m=0$","$(-12)^2-8m=0\\Rightarrow m=18$"],"설명":"식을 정리한 뒤 중근 조건(판별식=0)으로 m을 구한다.","확인":null,"스킬":"A6"},{"제목":"중근 a 구하기","고비":true,"힌트":"m=18을 대입하면 어떤 완전제곱식이 될까?","식":["$x^2-6x+9=0\\Rightarrow(x-3)^2=0$","$a=3$"],"설명":"m=18을 대입해 완전제곱식으로 정리하면 중근 a=3을 얻는다.","확인":null,"스킬":"A6"},{"제목":"k 구하기","힌트":"x²-x-k=0의 해가 x=3이므로 k는?","식":["$9-3-k=0\\Rightarrow k=6$"],"설명":"x=3을 대입해 k를 구한다.","확인":null,"스킬":"A3"},{"제목":"다른 근 b 구하기","힌트":"x²-x-6=0을 인수분해하면?","식":["$(x-3)(x+2)=0\\Rightarrow b=-2$"],"설명":"인수분해해 x=3 또는 x=-2를 얻고, b=-2이다.","확인":null,"스킬":"A2"},{"제목":"a-b+m+k 계산하기","힌트":"구한 값을 모두 대입하면?","식":["$a-b+m+k=3-(-2)+18+6=29$"],"설명":"구한 값을 모두 더해 최종 답을 구한다.","확인":"29","스킬":"A6"}],"fb":"fig/ns/"},"ns-4d71067ba71e":{"길":"우변을 옮겨 표준형으로 만든 뒤 판별식으로 k를, 대입으로 중근 m을 차례로 구한다","단계":[{"제목":"식 정리하기","힌트":"우변을 좌변으로 옮기면 이차방정식은 어떤 꼴이 될까?","식":["$2x^2-15x=-3x+k\\ \\Rightarrow\\ 2x^2-12x-k=0$"],"설명":"우변의 항을 모두 좌변으로 옮겨 표준형으로 정리한다.","확인":null,"스킬":"A6"},{"제목":"판별식으로 k 구하기","고비":true,"힌트":"중근을 가지려면 판별식(간이식)은 얼마가 되어야 할까?","식":["$(-6)^2-2\\times(-k)=0$","$k=-18$"],"설명":"중근을 가지므로 판별식이 0이 되도록 하는 k를 구한다.","확인":"-18","스킬":"A6"},{"제목":"중근 m 구하기","힌트":"k=-18을 대입한 방정식을 인수분해하면?","식":["$2x^2-12x+18=0$","$2(x-3)^2=0$","$x=3$"],"설명":"k를 대입해 완전제곱식으로 인수분해하면 중근 m=3을 얻는다.","확인":"3","스킬":"A6"},{"제목":"2m+k 계산하기","힌트":"앞서 구한 값을 대입하면?","식":["$2m+k=2\\times3+(-18)=-12$"],"설명":"m과 k를 대입해 최종 값을 구한다.","확인":"-12","스킬":"N5"}],"fb":"fig/ns/"},"ns-4fc35c4b9c58":{"길":"근호 조건으로 a, b의 부호를 정한 뒤 각 항의 부호에 맞춰 절댓값을 풀어 정리한다","단계":[{"제목":"조건에서 a, b의 부호 정하기","힌트":"√((-a)²)=a라면 -a는 양수일까 음수일까?","식":["$\\sqrt{(-a)^2}=|{-a}|=a\\Rightarrow a\\ge0$","$\\sqrt{b^2}=|b|=-b\\Rightarrow b\\le0$"],"설명":"근호 조건에서 a≥0, b≤0임을 알 수 있다.","확인":null,"스킬":"C2"},{"제목":"각 항의 부호 확인해 절댓값 풀기","고비":true,"힌트":"3a, -4b, -a+b는 각각 양수일까 음수일까?","식":["$3a\\ge0,\\ -4b\\ge0,\\ -a+b\\le0$"],"설명":"a≥0, b≤0이므로 3a≥0, -4b≥0이고 -a+b≤0이다. 이를 이용해 절댓값을 정리하면 √(9a²)=3a, √((-4b)²)=-4b, √((-a+b)²)=-(-a+b)=a-b이다.","확인":null,"스킬":"C2"},{"제목":"식 정리하기","힌트":"3a+(-4b)-(a-b)를 정리하면?","식":["$3a+(-4b)-(a-b)=2a-3b$"],"설명":"동류항을 정리하면 2a-3b이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-5155534255bf":{"길":"x=2를 대입해 a를 구하고 다른 근 b를 찾은 뒤, 거듭제곱의 일의 자리 주기로 답을 구한다","단계":[{"제목":"x=2 대입해 a 구하기","힌트":"한 근이 2이므로 방정식에 대입하면?","식":["$4(a-1)-2(a^2+1)+2(a+1)=0$","$a^2-3a+2=0$","$(a-1)(a-2)=0$"],"설명":"x=2를 대입해 정리하면 a에 대한 이차방정식을 얻는다.","확인":null,"스킬":"A4"},{"제목":"a 값 정하고 다른 근 구하기","고비":true,"힌트":"a=1이면 이차방정식이 되지 않는다는 조건을 쓰면?","식":["$a=2\\ (\\because a\\ne1)$","$x^2-5x+6=0$","$(x-2)(x-3)=0$"],"설명":"a=1이면 이차항이 사라지므로 a=2이고, 이를 대입한 방정식을 풀면 x=2 또는 3이므로 b=3이다.","확인":"3","스킬":"N4"},{"제목":"b의 거듭제곱 주기 찾기","힌트":"3의 거듭제곱의 일의 자리는 몇 개의 주기로 반복될까?","식":["$3^1,3^2,3^3,3^4\\to3,9,7,1$ (주기 4)"],"설명":"3의 거듭제곱의 일의 자리 숫자는 3, 9, 7, 1이 반복되는 주기 4를 가진다.","확인":null,"스킬":"N3"},{"제목":"나머지로 자리 확정하기","힌트":"2018을 4로 나눈 나머지는?","식":["$2018=4\\times504+2$"],"설명":"나머지가 2이므로 주기의 두 번째 숫자인 9가 일의 자리 숫자이다.","확인":"9","스킬":"N3"}],"fb":"fig/ns/"},"ns-6117ab7ed7d7":{"길":"A[n]을 부등식으로 정의한 뒤 대입해 항을 상쇄시키고 마지막 자리를 구한다","단계":[{"제목":"A[n]을 식으로 나타내기","힌트":"n² < n²+1 < (n+1)²이면 √(n²+1)은 어디에 있을까?","식":["$n^2<n^2+1<(n+1)^2\\Rightarrow n<\\sqrt{n^2+1}<n+1$"],"설명":"√(n²+1)은 n과 n+1 사이에 있으므로 소수부분은 A[n]=√(n²+1)-n이다.","확인":null,"스킬":"N7"},{"제목":"식을 대입해 간단히 하기","고비":true,"힌트":"A[2019]+2019를 대입하면 무엇이 상쇄될까?","식":["$(A[2019]+2019)^2=\\left\\{(\\sqrt{2019^2+1}-2019)+2019\\right\\}^2=\\left(\\sqrt{2019^2+1}\\right)^2$"],"설명":"A[2019]에 있는 -2019와 더해진 2019가 상쇄되어 식은 (√(2019²+1))²로 간단해진다.","확인":null,"스킬":"N7"},{"제목":"값을 계산해 일의 자리 구하기","힌트":"2019²+1의 일의 자리는 2019²의 일의 자리로 정해진다","식":["$(\\sqrt{2019^2+1})^2=2019^2+1$","$9^2=81\\Rightarrow$일의 자리 1, $1+1=2$"],"설명":"2019²의 일의 자리는 9²=81에서 1이므로 2019²+1의 일의 자리는 2이다.","확인":"2","스킬":"N3"}],"fb":"fig/ns/"},"ns-61c1e00b55fe":{"길":"식을 통분해 합과 곱 꼴로 바꾸고, (x+y)² 공식으로 xy를 구해 대입한다","단계":[{"제목":"식을 합·곱으로 정리하기","힌트":"√(y/x)+√(x/y)를 통분하면?","식":["$\\sqrt{\\frac yx}+\\sqrt{\\frac xy}=\\frac{\\sqrt{xy}}{x}+\\frac{\\sqrt{xy}}{y}=\\frac{(x+y)\\sqrt{xy}}{xy}$"],"설명":"두 항을 통분하면 (x+y)√(xy)/xy 꼴이 된다.","확인":null,"스킬":"A2"},{"제목":"xy의 값 구하기","고비":true,"힌트":"(x+y)²=x²+2xy+y²을 이용하면 xy는?","식":["$3^2=7+2xy\\Rightarrow xy=1$"],"설명":"(x+y)²=9이고 x²+y²=7이므로 2xy=2, xy=1이다.","확인":"1","스킬":"A2"},{"제목":"값을 대입해 계산하기","힌트":"x+y=3, xy=1을 식에 넣으면?","식":["$\\frac{3\\times\\sqrt1}{1}=3$"],"설명":"앞서 구한 값을 대입하면 답은 3이다.","확인":"3","스킬":"N5"}],"fb":"fig/ns/"},"ns-651a70b8dc05":{"길":"판별식이 완전제곱수인 순서쌍만 골라 실제로 인수분해해 확인한다","단계":[{"제목":"인수분해 조건 세우기","힌트":"ax²+x+b가 인수분해되려면 판별식은 어떤 수여야 할까?","식":["$D=1-4ab$"],"설명":"정수 계수의 두 일차식으로 인수분해되려면 판별식이 완전제곱수여야 한다.","확인":null,"스킬":"A4"},{"제목":"네 순서쌍의 판별식 확인하기","고비":true,"힌트":"보기의 수로 만든 순서쌍 중 판별식이 완전제곱수인 것은?","식":["$(-3,4):D=49,\\ (-1,6):D=25$","$(4,-3):D=49,\\ (6,-1):D=25$"],"설명":"이 네 순서쌍만 판별식이 7², 5²처럼 완전제곱수가 되어 인수분해가 가능하다.","확인":null,"스킬":"N8"},{"제목":"실제로 인수분해해 확인하기","힌트":"네 경우를 각각 인수분해하면?","식":["$-3x^2+x+4=(x+1)(-3x+4)$","$-x^2+x+6=(x+2)(-x+3)$","$4x^2+x-3=(4x-3)(x+1)$","$6x^2+x-1=(2x+1)(3x-1)$"],"설명":"네 경우 모두 실제로 두 일차식의 곱으로 인수분해된다.","확인":null,"스킬":"A4"},{"제목":"개수 세기","힌트":"조건을 만족하는 순서쌍은 모두 몇 개?","식":["$4$개"],"설명":"인수분해되는 순서쌍은 4개이다.","확인":"4","스킬":"P4"}],"fb":"fig/ns/"},"ns-65bb5bc19308":{"길":"계수를 바꾼 방정식에 주어진 해를 대입해 a를 구하고 남은 해를 찾는다","단계":[{"제목":"바뀐 방정식 세우기","힌트":"일차항의 계수와 상수항을 서로 바꾸면 방정식은?","식":["$x^2+3ax-2a=0$"],"설명":"원래 방정식의 일차항 계수 -2a와 상수항 3a를 서로 바꿔 새 방정식을 만든다.","확인":null,"스킬":"C7"},{"제목":"x=-1 대입해 a 구하기","고비":true,"힌트":"바뀐 방정식에 x=-1을 대입하면?","식":["$1-3a-2a=0$","$a=\\frac{1}{5}$"],"설명":"바뀐 방정식에서 한 해가 x=-1이므로 대입해 a를 구한다.","확인":"1/5","스킬":"A4"},{"제목":"다른 해 구하기","힌트":"a를 대입한 방정식을 인수분해하면?","식":["$5x^2+3x-2=0$","$(x+1)(5x-2)=0$","$x=\\frac{2}{5}$"],"설명":"a를 대입해 정리한 이차방정식을 인수분해하면 다른 해는 2/5이다.","확인":"2/5","스킬":"A6"}],"fb":"fig/ns/"},"ns-65d28584fbf7":{"길":"A와 B를 각각 곱셈공식으로 인수분해한 뒤 비를 계산한다","단계":[{"제목":"A를 인수분해하기","힌트":"2019×2020을 2019×(2019+1)로 바꾸면?","식":["$A=2019\\times2020-2=2019^2+2019-2$","$=(2019+2)(2019-1)=2021\\times2018$"],"설명":"2019×2020을 전개한 뒤 인수분해하면 A=2021×2018이다.","확인":null,"스킬":"A1"},{"제목":"B를 인수분해하기","고비":true,"힌트":"2018²-9를 합차공식으로 바꾸면?","식":["$B=2018^2-9=(2018+3)(2018-3)=2021\\times2015$"],"설명":"합차공식으로 B를 인수분해하면 2021×2015이다.","확인":null,"스킬":"A6"},{"제목":"비 계산하기","힌트":"A를 B로 나누면 공통인수가 어떻게 될까?","식":["$\\frac{A}{B}=\\frac{2021\\times2018}{2021\\times2015}=\\frac{2018}{2015}$"],"설명":"공통인수 2021이 약분되어 A는 B의 2018/2015배이다.","확인":"2018/2015","스킬":"A6"}],"fb":"fig/ns/"},"ns-67ce5b1c91cf":{"길":"0<a<1일 때 네 수의 크기를 비교해 가장 큰 수와 작은 수를 곱한다","단계":[{"제목":"a, a², 1/a, 1/a²의 크기 비교하기","힌트":"0<a<1일 때 a, a², 1/a의 크기 순서는?","식":["$a^2<a<1<\\frac1a<\\frac1{a^2}$"],"설명":"0<a<1이므로 거듭제곱할수록 값이 작아지고 역수를 취하면 커진다.","확인":null,"스킬":"C3"},{"제목":"보기의 네 수를 순서대로 나열하기","고비":true,"힌트":"이 순서에서 a², a, √a, √(1/a)는 어떻게 놓일까?","식":["$a^2<a<\\sqrt a<\\sqrt{\\frac1a}$"],"설명":"지수가 작아질수록 1에 가까워지므로 a²<a<√a<√(1/a)이다.","확인":null,"스킬":"C3"},{"제목":"가장 큰 수와 작은 수 곱하기","힌트":"√(1/a)와 a²을 곱하면?","식":["$\\sqrt{\\frac1a}\\times a^2=\\frac{\\sqrt a}a\\times a^2=a\\sqrt a$"],"설명":"가장 큰 수 √(1/a)와 가장 작은 수 a²의 곱을 정리하면 a√a이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-706d40f3345a":{"길":"잘못 쓴 값으로 세운 평균·분산 식에서 나머지 변량의 합과 제곱합을 구한 뒤 고친 값으로 바꿔 다시 계산한다","단계":[{"제목":"나머지 세 변량의 합 구하기","힌트":"잘못 쓴 값 4,7과 나머지 a,b,c의 평균이 5라는 식을 세우면?","식":["$\\frac{4+7+a+b+c}{5}=5$","$a+b+c=14$"],"설명":"평균 방정식을 정리하면 나머지 세 변량의 합은 14이다.","확인":null,"스킬":"C7"},{"제목":"나머지 세 변량의 제곱합 구하기","고비":true,"힌트":"잘못 구한 분산 30을 식으로 쓰면?","식":["$\\frac{(-1)^2+2^2+(a-5)^2+(b-5)^2+(c-5)^2}{5}=30$","$(a-5)^2+(b-5)^2+(c-5)^2=145$"],"설명":"잘못된 분산식을 정리해 나머지 세 변량의 편차 제곱합을 구한다.","확인":null,"스킬":"A2"},{"제목":"고친 값으로 실제 평균·분산 구하기","힌트":"4,7 대신 5,6을 넣으면 평균과 분산은?","식":["$\\frac{5+6+14}{5}=5$","$\\frac{0^2+1^2+145}{5}=\\frac{146}{5}=29.2$"],"설명":"합이 14로 같아 평균은 그대로 5이고, 고친 분산은 29.2이다.","확인":null,"스킬":"A2"},{"제목":"분산의 차 구하기","힌트":"실제 분산 29.2에서 잘못 구한 분산 30을 빼면?","식":["$|29.2-30|=0.8$"],"설명":"두 분산의 차는 0.8이다.","확인":"0.8","스킬":"A2"}],"fb":"fig/ns/"},"ns-70a3e39deb3c":{"길":"cos을 여각의 sin으로 바꿔 다섯 값을 sin끼리 비교한다","단계":[{"제목":"cos을 sin으로 바꾸기","고비":true,"힌트":"cos40°, cos20°를 여각의 sin으로 바꾸면?","식":["$\\cos40^{\\circ}=\\sin50^{\\circ}$","$\\cos20^{\\circ}=\\sin70^{\\circ}$"],"설명":"여각 관계 cos(90°-θ)=sinθ를 이용해 ㄷ, ㅁ을 sin으로 바꾼다.","확인":null,"스킬":"T5"},{"제목":"tan45°를 sin과 비교 준비하기","힌트":"tan45°=1이고 sin45°와 비교하면?","식":["$\\tan45^{\\circ}=1>\\sin45^{\\circ}$"],"설명":"tan45°=1은 sin의 최댓값인 1이므로 어떤 sinθ(θ<90°)보다도 크다.","확인":null,"스킬":"T5"},{"제목":"크기 순서 정하기","힌트":"각이 클수록 sin 값도 커지므로 70°,50°,40°,20°는?","식":["$\\sin70^{\\circ}>\\sin50^{\\circ}>\\sin40^{\\circ}>\\sin20^{\\circ}$"],"설명":"0°~90°에서 각이 클수록 sin값이 커지므로 ㄱ>ㅁ>ㄷ>ㄴ>ㄹ 순이다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-721d0c41b045":{"길":"여섯 진술을 하나씩 반례나 정의로 따져 옳은 것만 남긴다","단계":[{"제목":"ㄱ, ㄷ 판별하기","힌트":"수직선을 유리수만으로 채울 수 있을까, π는 점에 대응할 수 있을까?","식":[],"설명":"수직선은 무리수까지 있어야 완전히 메워지므로 ㄱ은 옳지 않고, π는 무리수이므로 점에 대응시킬 수 있어 ㄷ도 옳지 않다.","확인":null,"스킬":"N6"},{"제목":"ㄹ 판별하기","힌트":"두 무리수 사이에는 유리수가 하나도 없을까?","식":[],"설명":"두 무리수 사이에는 무수히 많은 유리수가 있으므로 ㄹ은 옳지 않다.","확인":null,"스킬":"N6"},{"제목":"ㅁ 반례 찾기","고비":true,"힌트":"두 무리수의 합이 유리수가 되는 경우가 있을까?","식":["$\\sqrt2+(-\\sqrt2)=0$"],"설명":"√2와 -√2의 합은 0으로 유리수이므로 ㅁ은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄴ, ㅂ 확인하고 답 정하기","힌트":"남은 두 진술은 정의에 맞을까?","식":[],"설명":"수직선의 한 점에는 반드시 대응하는 실수가 있고, 무리수는 모두 순환하지 않는 무한소수이므로 ㄴ, ㅂ이 옳다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-72e11561bda0":{"길":"평행사변형을 대각선으로 나눈 넓이 공식을 사각형 EFGH에 적용해 빈칸을 채운다","단계":[{"제목":"(ㄱ),(ㄴ) 채우기","힌트":"평행사변형 ABCD=2×△ABC이고 △ABC의 넓이 공식은?","식":["$\\square ABCD=2\\times\\triangle ABC=2\\times\\frac12ab\\sin B=ab\\sin B$"],"설명":"(ㄱ)은 ½ab sinB, (ㄴ)은 ab sinB이다.","확인":null,"스킬":"S8"},{"제목":"(ㄷ),(ㄹ) 채우기","고비":true,"힌트":"□EFGH의 넓이가 □ABCD의 2배이면 □ABCD는 □EFGH의 몇 배일까?","식":["$\\square ABCD=\\frac12\\square EFGH=\\frac12ab\\sin x$"],"설명":"□EFGH=2×□ABCD이므로 □ABCD=(1/2)×□EFGH=(1/2)ab sinx이다. (ㄷ)은 1/2, (ㄹ)은 (1/2)ab sinx이다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-72e70e403248":{"길":"양변에 (9-3)을 곱해 반복해서 합차공식을 적용해 좌변을 정리한다","단계":[{"제목":"9-3을 곱해 식 변형하기","힌트":"양변에 (9-3)을 곱하면 앞의 세 괄호는 어떻게 묶일까?","식":["$(9-3)(9+3)(9^2+3^2)(9^4+3^4)+6\\times\\frac{3^7}{2}=6\\times x\\times3^y$"],"설명":"양변에 6=9-3을 곱해 좌변의 곱을 합차공식으로 정리할 준비를 한다.","확인":null,"스킬":"A1"},{"제목":"합차공식 반복 적용하기","고비":true,"힌트":"(9-3)(9+3)을 시작으로 계속 곱하면 지수가 어떻게 늘어날까?","식":["$(9^2-3^2)(9^2+3^2)(9^4+3^4)+3^8=(9^4-3^4)(9^4+3^4)+3^8$","$=(9^8-3^8)+3^8=9^8$"],"설명":"합차공식을 세 번 연달아 적용하면 앞부분이 9^8-3^8이 되고, 3^8을 더하면 3^8이 사라져 9^8만 남는다.","확인":null,"스킬":"A1"},{"제목":"밑을 3으로 통일하기","힌트":"9^8을 3의 거듭제곱으로 바꾸면?","식":["$9^8=(3^2)^8=3^{16}$"],"설명":"9=3^2이므로 9^8=3^16이다.","확인":null,"스킬":"A9"},{"제목":"x, y 값 정하기","힌트":"3^16=6×x×3^y에서 1/2≤x≤1을 쓰면?","식":["$3\\le6x\\le6$","$6x=3\\Rightarrow x=\\frac12,\\ y=15$"],"설명":"x의 범위 조건에서 6x가 3이 되어야 하므로 x=1/2, y=15이다.","확인":null,"스킬":"C2"},{"제목":"y/x 계산하기","힌트":"y=15, x=1/2를 나누면?","식":["$\\frac{y}{x}=15\\div\\frac12=30$"],"설명":"y를 x로 나누면 30이다.","확인":"30","스킬":"N5"}],"fb":"fig/ns/"},"ns-75b4d5d9e0f7":{"길":"눈의 수가 모두 소수임을 이용해 두 인수분해 꼴을 찾고, 가능한 모든 조합에서 k의 최댓값·최솟값을 구한다","단계":[{"제목":"인수분해 꼴 두 가지 찾기","힌트":"a, b가 모두 소수이면 ax²+kx+b는 어떤 두 꼴로만 인수분해될까?","식":["$(ax+1)(x+b)$ 또는 $(ax+b)(x+1)$"],"설명":"a, b의 소인수가 자기 자신뿐이므로 인수분해는 이 두 꼴 중 하나이다.","확인":null,"스킬":"N1"},{"제목":"k를 a, b로 나타내기","힌트":"두 꼴을 전개하면 k는 각각 무엇과 같을까?","식":["$k=ab+1$ 또는 $k=a+b$"],"설명":"두 꼴을 전개해 x의 계수를 비교하면 k의 두 후보식을 얻는다.","확인":null,"스킬":"A3"},{"제목":"모든 조합 나열하기","고비":true,"힌트":"a≤b로 두고 {2,3,5,7}에서 고를 수 있는 조합을 모두 나열하면?","식":["$(2,2):5,4\\quad(2,3):7,5\\quad(2,5):11,7\\quad(2,7):15,9$","$(3,3):10,6\\quad(3,5):16,8\\quad(3,7):22,10$","$(5,5):26,10\\quad(5,7):36,12\\quad(7,7):50,14$"],"설명":"a≤b인 열 가지 조합에서 두 후보 k값을 모두 구한다.","확인":null,"스킬":"P4"},{"제목":"최댓값 찾기","힌트":"나열한 값 중 가장 큰 것은?","식":["$50$"],"설명":"a=7, b=7일 때 ab+1=50으로 가장 크다.","확인":null,"스킬":"P4"},{"제목":"최솟값 찾기","힌트":"나열한 값 중 가장 작은 것은?","식":["$4$"],"설명":"a=2, b=2일 때 a+b=4로 가장 작다.","확인":null,"스킬":"P4"},{"제목":"차 계산하기","힌트":"최댓값에서 최솟값을 빼면?","식":["$50-4=46$"],"설명":"자연수 k의 최댓값과 최솟값의 차는 46이다.","확인":"46","스킬":"N5"}],"fb":"fig/ns/"},"ns-7849e889c42a":{"길":"근의 공식과 근과 계수의 관계를 다섯 진술에 하나씩 대입해 옳고 그름을 가린다","단계":[{"제목":"근의 공식으로 두 근 표현하기","힌트":"근의 공식을 쓰면 두 근은?","식":["$x=4\\pm\\sqrt{16-k}$"],"설명":"근의 공식으로 두 근을 나타내면 한 근이 4+√7일 때 다른 근은 4-√7임을 알 수 있다.","확인":null,"스킬":"A6"},{"제목":"근과 계수의 관계로 합 확인하기","힌트":"두 근의 합은 k의 값과 관계없이 얼마일까?","식":["$\\alpha+\\beta=8$"],"설명":"근과 계수의 관계에 따라 k의 값에 상관없이 두 근의 합은 항상 8이다.","확인":null,"스킬":"A2"},{"제목":"k=16, 곱 조건 판별하기","고비":true,"힌트":"k=16이면 중근인지, 두 근의 곱이 -9이면 어떤 인수를 가질지 확인하면?","식":["$k=16:\\ (x-4)^2=0\\ (중근)$","$k=-9:\\ (x-9)(x+1)=0$"],"설명":"k=16이면 중근을 갖고, 두 근의 곱이 -9이면 x+1을 인수로 가지므로 이 두 진술이 옳다.","확인":null,"스킬":"A4"}],"fb":"fig/ns/"},"ns-7869dfd0370e":{"길":"순서를 유지한 채 두 평균식을 세워 c를 구하고, 새 학생 점수를 넣어 중앙값 변화를 판정한다","단계":[{"제목":"다섯 학생 점수 순서 놓기","힌트":"중앙값이 77이므로 다섯 점수를 작은 순서로 나열하면?","식":["$a\\le b\\le77\\le c\\le d$"],"설명":"중앙값이 77이므로 나머지 네 점수를 이 순서로 둔다.","확인":null,"스킬":"C2"},{"제목":"처음 평균식 세우기","힌트":"다섯 점수의 평균이 75라는 식은?","식":["$\\frac{a+b+77+c+d}{5}=75$","$a+b+c+d=298$"],"설명":"평균 방정식을 정리해 네 점수의 합을 구한다.","확인":null,"스킬":"A2"},{"제목":"전학 후 평균식 세우기","고비":true,"힌트":"한 명이 나가고 90점인 학생이 들어와 평균이 77로 올랐다면?","식":["$\\frac{a+b+77+d+90}{5}=77$","$a+b+d=218$"],"설명":"새 평균 방정식을 정리해 남은 세 점수의 합을 구한다.","확인":null,"스킬":"A2"},{"제목":"c 구하기","힌트":"두 식을 빼면 c는?","식":["$298-218=80$","$c=80$"],"설명":"두 합의 차로 c=80임을 구한다.","확인":null,"스킬":"A10"},{"제목":"중앙값 변화 판정하기","힌트":"점수를 다시 순서대로 나열하면 가운데 값은?","식":["$a,\\,b,\\,77,\\,d,\\,90\\ 또는\\ a,\\,b,\\,77,\\,90,\\,d$"],"설명":"어느 순서든 가운데 값은 77이므로 중앙값은 변하지 않는다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-7af3295a1fc4":{"길":"a+1/a를 먼저 구하고, 주어진 식이 (a-1/a)²임을 알아채 값을 구한다","단계":[{"제목":"a+1/a 값 구하기","힌트":"방정식을 a로 나누면?","식":["$a-5+\\frac{1}{a}=0$","$a+\\frac{1}{a}=5$"],"설명":"방정식의 양변을 a로 나누면 a+1/a의 값을 얻는다.","확인":"5","스킬":"A2"},{"제목":"식을 완전제곱 꼴로 알아채기","고비":true,"힌트":"주어진 식을 (a-1/a)로 묶으면?","식":["$a\\left(a-\\frac{1}{a}\\right)+\\frac{1}{a}\\left(\\frac{1}{a}-a\\right)=\\left(a-\\frac{1}{a}\\right)^2$"],"설명":"두 번째 항의 부호를 바꿔 보면 전체 식이 (a-1/a)의 완전제곱임을 알 수 있다.","확인":null,"스킬":"A2"},{"제목":"(a-1/a)² 값 구하기","힌트":"(a-1/a)²을 (a+1/a)²으로 바꾸면?","식":["$\\left(a-\\frac{1}{a}\\right)^2=\\left(a+\\frac{1}{a}\\right)^2-4=25-4=21$"],"설명":"합의 제곱에서 4를 빼면 차의 제곱을 구할 수 있으므로 값은 21이다.","확인":"21","스킬":"A2"}],"fb":"fig/ns/"},"ns-7bb2d1d48fe0":{"길":"x²+cx+24를 (x+a)(x+b)로 놓고 곱이 24인 쌍 중 두 주머니 조건에 맞는 것만 찾는다","단계":[{"제목":"a, b의 관계식 세우기","힌트":"(x+a)(x+b)를 전개하면 c, 24는 무엇과 같을까?","식":["$x^2+cx+24=(x+a)(x+b)$","$a+b=c,\\ ab=24$"],"설명":"전개해 계수를 비교하면 c는 a+b, 24는 ab와 같다.","확인":null,"스킬":"A3"},{"제목":"조건에 맞는 a,b 찾기","고비":true,"힌트":"곱이 24이면서 a는 짝수, b는 홀수인 쌍은?","식":["$(a,b)=(8,3)$"],"설명":"24의 약수 쌍 중 a가 짝수(A 주머니), b가 홀수(B 주머니)인 것은 (8,3) 뿐이다.","확인":null,"스킬":"N4"},{"제목":"c 값 구하기","힌트":"a+b를 계산하면?","식":["$c=a+b=8+3=11$"],"설명":"c=a+b=11이다.","확인":"11","스킬":"A3"}],"fb":"fig/ns/"},"ns-7d3456230f40":{"길":"두 방정식을 빼 공통근을 찾고, 관계식으로 각각을 인수분해해 나머지 근을 더한다","단계":[{"제목":"두 방정식을 빼 공통근 찾기","힌트":"두 방정식이 같은 공통근을 가지므로 등호로 놓고 빼면?","식":["$2x^2-ax+b=2x^2-bx+a$","$(b-a)x=a-b$","$x=-1$"],"설명":"두 방정식이 공통으로 갖는 근에서는 두 식의 값이 같으므로, 이를 정리하면 공통근이 항상 -1임을 알 수 있다.","확인":"-1","스킬":"A10"},{"제목":"공통근을 대입해 관계식 구하기","고비":true,"힌트":"첫째 방정식에 x=-1을 대입하면?","식":["$2+a+b=0$","$b=-2-a$"],"설명":"공통근 x=-1을 한 방정식에 대입해 a와 b 사이의 관계식을 얻는다.","확인":null,"스킬":"A3"},{"제목":"첫째 방정식을 인수분해해 다른 근 구하기","힌트":"b를 대입해 정리하고 인수분해하면?","식":["$2x^2-ax-2-a=0$","$(2x-2-a)(x+1)=0$","$x=\\frac{2+a}{2}$ 또는 $x=-1$"],"설명":"관계식을 대입해 정리한 뒤 인수분해하면 첫째 방정식의 다른 근을 얻는다.","확인":null,"스킬":"A4"},{"제목":"둘째 방정식을 인수분해해 다른 근 구하기","힌트":"같은 방법으로 둘째 방정식도 정리하면?","식":["$2x^2+(2+a)x+a=0$","$(2x+a)(x+1)=0$","$x=-\\frac{a}{2}$ 또는 $x=-1$"],"설명":"같은 관계식을 둘째 방정식에 대입해 정리하면 다른 근을 얻는다.","확인":null,"스킬":"A4"},{"제목":"나머지 두 근의 합 구하기","힌트":"공통근 -1을 제외한 두 근을 더하면?","식":["$\\frac{2+a}{2}+\\left(-\\frac{a}{2}\\right)=1$"],"설명":"공통근을 제외한 두 방정식의 나머지 근을 더하면 a에 관계없이 항상 1이다.","확인":"1","스킬":"N5"}],"fb":"fig/ns/"},"ns-7f1b2b8a5e82":{"길":"다섯 선지를 정의와 비교해 근호를 쓰고도 유리수인 반례를 찾는다","단계":[{"제목":"①,②,③,⑤ 확인하기","힌트":"유한소수, 무한소수, 실수의 정의와 비교하면 나머지 선지는 맞을까?","식":[],"설명":"①,②,③,⑤는 유리수·무리수의 정의와 일치하므로 옳다.","확인":null,"스킬":"N6"},{"제목":"④ 반례 찾기","고비":true,"힌트":"근호를 쓴 수가 항상 무리수일까?","식":["$\\sqrt4=2$"],"설명":"√4=2는 근호를 사용했지만 유리수이므로 ④가 옳지 않다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-8371c79aa343":{"길":"a>0, b<0 조건으로 각 선지의 부호를 따져 근호를 벗긴다","단계":[{"제목":"①,②,④,⑤ 확인하기","힌트":"a>0, b<0일 때 각 근호 안의 부호를 맞게 처리했을까?","식":[],"설명":"①,②,④,⑤는 부호를 맞게 처리해 각각 옳다.","확인":null,"스킬":"C2"},{"제목":"③ 부호 확인해 반례 찾기","고비":true,"힌트":"a-2b의 부호는 양수일까 음수일까?","식":["$a-2b>0$"],"설명":"a>0이고 -2b>0이므로 a-2b>0이다. 따라서 √((a-2b)²)=a-2b이므로 ③이 옳지 않다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-8b6486b6f548":{"길":"네 진술에 특수각 값을 대입해 계산하고 참인 것을 고른다","단계":[{"제목":"ㄱ,ㄴ 계산하기","힌트":"sin30÷sin60과 tan30×tan60을 각각 계산하면?","식":["$\\sin30^\\circ\\div\\sin60^\\circ=\\frac{\\sqrt3}{3}\\ne\\tan60^\\circ$","$\\tan30^\\circ\\times\\tan60^\\circ=1=\\tan45^\\circ$"],"설명":"특수각 값을 대입해 계산하면 ㄱ은 거짓, ㄴ은 참이다.","확인":null,"스킬":"S6"},{"제목":"ㄷ,ㄹ 계산하기","고비":true,"힌트":"sin45×cos45와 cos30+cos60을 각각 계산하면?","식":["$\\sin45^\\circ\\times\\cos45^\\circ=\\frac12=\\sin30^\\circ$","$\\cos30^\\circ+\\cos60^\\circ=\\frac{\\sqrt3+1}{2}\\ne\\cos90^\\circ$"],"설명":"특수각 값을 대입하면 ㄷ은 참, ㄹ은 거짓이다.","확인":null,"스킬":"S6"},{"제목":"옳은 것 고르기","힌트":"참인 진술만 골라내면?","식":[],"설명":"ㄴ, ㄷ만 참이므로 답은 ㄴ, ㄷ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-8c86493638d6":{"길":"호가 같음을 원주각으로 옮겨 각 이등분을 보이고, 두 쌍의 AA 닮음을 찾아 옳은 보기를 가린다","단계":[{"제목":"㉠ 판별하기","힌트":"호 BC=호 CD이면 원주각은?","식":["$\\angle BAC=\\angle BDC,\\ \\angle CAD=\\angle CBD$"],"설명":"같은 호에 대한 원주각은 같고, 호 BC=호 CD이므로 ∠BAC=∠CAD이다. ㉠은 옳다.","확인":null,"스킬":"S5"},{"제목":"㉡ 판별하기","고비":true,"힌트":"△BCA와 △EDA에서 공통인 각과 같은 각을 찾으면?","식":["$\\angle ACB=\\angle ADE,\\ \\angle BAC=\\angle EAD$"],"설명":"두 쌍의 각이 같으므로 △BCA∽△EDA(AA닮음)이다. ㉡은 옳다.","확인":null,"스킬":"S5"},{"제목":"㉢ 판별하기","힌트":"△ABE와 △DCE에서도 같은 방법을 쓰면?","식":["$\\angle ABE=\\angle DCE,\\ \\angle BAE=\\angle CDE$"],"설명":"같은 원리로 △ABE∽△DCE(AA닮음)이다. ㉢도 옳다.","확인":null,"스킬":"S5"},{"제목":"옳은 것 고르기","힌트":"㉠,㉡,㉢이 모두 옳다면?","식":[],"설명":"옳은 것은 ㉠, ㉡, ㉢이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-8d82ad0efec4":{"길":"ㄱ은 합차공식으로 바로 확인하고, ㄴ·ㄷ은 실제로 계산해 주어진 값과 비교한다","단계":[{"제목":"ㄱ 판별하기","힌트":"16a²-9b²을 합차공식으로 인수분해하면?","식":["$16a^2-9b^2=(4a-3b)(4a+3b)$"],"설명":"합차공식 그대로이므로 ㄱ은 옳다.","확인":null,"스킬":"A6"},{"제목":"ㄴ 판별하기","고비":true,"힌트":"a-b=4일 때 a²-b²-(a-b)(a+b-3)을 정리하면?","식":["$a^2-b^2-(a-b)(a+b-3)=(a-b)(a+b)-(a-b)(a+b-3)$","$=(a-b)\\times3=3\\times4=12$"],"설명":"공통인수 (a-b)로 묶어 정리하면 값은 -12가 아니라 12이므로 ㄴ은 옳지 않다.","확인":null,"스킬":"A1"},{"제목":"ㄷ 판별하기","힌트":"홀수 제곱을 두 개씩 묶어 합차공식을 쓰면?","식":["$-1^2+3^2-5^2+7^2-9^2+11^2-13^2+15^2$","$=(3+1)(3-1)+(7+5)(7-5)+(11+9)(11-9)+(15+13)(15-13)$","$=2(4+12+20+28)=128$"],"설명":"두 개씩 묶어 합차공식으로 계산하면 64가 아니라 128이므로 ㄷ은 옳지 않다.","확인":null,"스킬":"A6"},{"제목":"옳은 것 정리하기","힌트":"세 보기 중 옳은 것만 고르면?","식":[],"설명":"ㄱ만 옳으므로 답은 ㄱ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-8e4fdefc2009":{"길":"1보다 작은 무리와 큰 무리로 나눠 각각 제곱해 크기를 비교한다","단계":[{"제목":"1보다 작은 세 수 정하기","힌트":"1/3, (1/3)², √(1/3)은 모두 1보다 작을까?","식":[],"설명":"1/3, (1/3)², √(1/3)은 모두 1보다 작은 수이다.","확인":null,"스킬":"N6"},{"제목":"세 수를 제곱해 비교하기","고비":true,"힌트":"세 수를 각각 제곱하면 크기 비교가 쉬워질까?","식":["$\\left(\\frac13\\right)^2=\\frac19,\\ \\left(\\frac19\\right)^2=\\frac1{81},\\ \\left(\\sqrt{\\frac13}\\right)^2=\\frac13$"],"설명":"제곱한 값을 비교하면 (1/3)²<1/3<√(1/3)이다.","확인":null,"스킬":"N6"},{"제목":"1보다 큰 두 수 비교하기","힌트":"√3과 (√3)² 중 어느 것이 클까?","식":["$1<\\sqrt3<2,\\ (\\sqrt3)^2=3$"],"설명":"√3<2<3=(√3)²이므로 √3<(√3)²이다.","확인":null,"스킬":"N6"},{"제목":"a, b 정해 ab 계산하기","힌트":"두 번째, 세 번째로 큰 수는 무엇일까?","식":["$a=\\sqrt3,\\ b=\\sqrt{\\frac13}$","$ab=\\sqrt3\\times\\sqrt{\\frac13}=1$"],"설명":"전체 순서는 (1/3)²<1/3<√(1/3)<√3<(√3)²이므로 a=√3, b=√(1/3)이고 ab=1이다.","확인":"1","스킬":"N6"}],"fb":"fig/ns/"},"ns-9083734c7744":{"길":"a+b를 한 문자로 치환해 식을 정리한 뒤 인수분해한다","단계":[{"제목":"동류항 모아 정리하기","힌트":"항들을 a+b가 보이도록 다시 묶으면?","식":["$2ab+b^2-7b+a^2-7a-8=a^2+2ab+b^2-7a-7b-8$"],"설명":"항의 순서를 바꿔 a²+2ab+b²이 보이도록 정리한다.","확인":null,"스킬":"A1"},{"제목":"a+b로 치환하기","고비":true,"힌트":"a²+2ab+b²과 -7a-7b를 A=a+b로 바꾸면?","식":["$=(a+b)^2-7(a+b)-8=A^2-7A-8\\ (A=a+b)$"],"설명":"a+b를 A로 치환하면 A에 대한 이차식이 된다.","확인":null,"스킬":"A1"},{"제목":"인수분해하기","힌트":"A²-7A-8을 인수분해하면?","식":["$A^2-7A-8=(A+1)(A-8)$","$=(a+b+1)(a+b-8)$"],"설명":"인수분해한 뒤 A를 다시 a+b로 되돌린다.","확인":null,"스킬":"A1"}],"fb":"fig/ns/"},"ns-9098026f0d08":{"길":"여섯 수를 간단히 정리한 뒤 정수와 유리수의 개수를 세어 선지를 확인한다","단계":[{"제목":"여섯 수 정리하기","힌트":"√9-2, √1.69, 0.888…을 간단히 하면?","식":["$\\sqrt9-2=1,\\ \\sqrt{1.69}=1.3,\\ 0.888\\cdots=\\frac89,\\ -\\sqrt{\\frac{48}3}=-4$"],"설명":"근호와 순환소수를 정리하면 값이 각각 1, 5/6, 1.3, 8/9, 3π, -4이다.","확인":null,"스킬":"N6"},{"제목":"①,②,③ 확인하기","힌트":"정수와 자연수는 각각 몇 개일까?","식":[],"설명":"정수는 1, -4의 2개이고 자연수는 1의 1개이므로 ①, ②는 옳지 않다.","확인":null,"스킬":"N6"},{"제목":"④ 정수가 아닌 유리수 개수 세기","고비":true,"힌트":"유리수 5개 중 정수 2개를 빼면?","식":["$5-2=3$"],"설명":"유리수는 1, 5/6, 1.3, 8/9, -4의 5개이고 이 중 정수 2개를 빼면 정수가 아닌 유리수는 3개이므로 ④가 옳다.","확인":"3","스킬":"N6"}],"fb":"fig/ns/"},"ns-93c319632b63":{"길":"√3의 범위를 구한 뒤 다섯 선지가 √3과 2 사이인지 확인한다","단계":[{"제목":"√3의 범위 구하기","힌트":"1.7²과 1.8²은 3과 어떤 관계일까?","식":["$1.7^2<3<1.8^2$"],"설명":"1.7²=2.89, 1.8²=3.24이므로 1.7<√3<1.8이다.","확인":null,"스킬":"N6"},{"제목":"선지를 하나씩 비교하기","고비":true,"힌트":"각 선지가 √3보다 크고 2보다 작은지 확인하면?","식":["$\\sqrt3-\\frac1{10}<\\sqrt3$"],"설명":"①~④는 모두 √3과 2 사이지만 ⑤ √3-1/10은 √3보다 작으므로 두 수 사이에 있지 않다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-950ad1b134bf":{"길":"f(x)가 일정한 구간을 나눠 누적합 식을 세우고 방정식을 풀어 n을 구한다","단계":[{"제목":"f(x) 값의 구간 나누기","힌트":"√x가 자연수 k와 k+1 사이일 때 f(x)는 얼마일까?","식":["$f(1)=0,\\ f(2)=f(3)=f(4)=1,\\ f(5)=\\cdots=f(9)=2,\\ f(10)=\\cdots=f(16)=3,\\ f(17)=\\cdots=f(25)=4$"],"설명":"√x가 k와 k+1 사이일 때 f(x)=k이므로 x의 구간마다 f값이 정해진다.","확인":null,"스킬":"N7"},{"제목":"n=16까지 누적합 구하기","고비":true,"힌트":"0+1×3+2×5+3×7을 더하면?","식":["$0+1\\times3+2\\times5+3\\times7=34$"],"설명":"n=16까지의 누적합은 34이다.","확인":"34","스킬":"P1"},{"제목":"방정식 풀어 n 구하기","힌트":"34+4x=42를 풀면?","식":["$4x=8,\\ x=2$","$n=16+2=18$"],"설명":"f=4인 항이 2개 더 필요하므로 n=18이다.","확인":"18","스킬":"N7"}],"fb":"fig/ns/"},"ns-9630732a9d2c":{"길":"√7의 소수부분을 구해 x²+4x 값을 얻고 주어진 식에 대입한다","단계":[{"제목":"소수부분 구하기","힌트":"2<√7<3이므로 소수부분은?","식":["$x=\\sqrt{7}-2$"],"설명":"√7의 정수부분이 2이므로 소수부분은 √7-2이다.","확인":null,"스킬":"N7"},{"제목":"x²+4x 값 구하기","고비":true,"힌트":"x+2=√7의 양변을 제곱하면?","식":["$(x+2)^2=7$","$x^2+4x+4=7\\Rightarrow x^2+4x=3$"],"설명":"양변을 제곱해 정리하면 x²+4x=3이다.","확인":"3","스킬":"A3"},{"제목":"식에 대입해 계산하기","힌트":"(x+1)²+2x+4를 x²+4x를 이용해 정리하면?","식":["$(x+1)^2+2x+4=x^2+4x+5=3+5=8$"],"설명":"전개해 x²+4x 자리에 3을 대입하면 값은 8이다.","확인":"8","스킬":"A1"}],"fb":"fig/ns/"},"ns-97446420d5fd":{"길":"A는 완전제곱 꼴로, B는 합차공식으로, C는 완전제곱 꼴로 각각 구해 크기를 비교한다","단계":[{"제목":"A 구하기","힌트":"24.5²-9×7×3.5+4.5²을 완전제곱 꼴로 보면?","식":["$A^2=24.5^2-2\\times4.5\\times24.5+4.5^2=(24.5-4.5)^2=20^2$"],"설명":"가운데 항이 2×4.5×24.5임을 보면 완전제곱식이 되어 A=20이다.","확인":"20","스킬":"A6"},{"제목":"B 구하기","힌트":"53²-45²을 합차공식으로 바꾸면?","식":["$B=\\sqrt{53^2-45^2}=\\sqrt{(53-45)(53+45)}=\\sqrt{8\\times98}$","$=\\sqrt{2^4\\times7^2}=2^2\\times7=28$"],"설명":"합차공식으로 인수분해한 뒤 소인수분해해 근호를 없애면 B=28이다.","확인":"28","스킬":"A6"},{"제목":"C 구하기","고비":true,"힌트":"24×28+4를 20을 이용한 완전제곱 꼴로 보면?","식":["$C^2=24\\times28+4=(20+4)(20+8)+4$","$=20^2+12\\times20+36=(20+6)^2=26^2$"],"설명":"24=20+4, 28=20+8로 보고 전개해 완전제곱식으로 정리하면 C=26이다.","확인":"26","스킬":"A6"},{"제목":"크기 비교하기","힌트":"A=20, B=28, C=26의 대소는?","식":["$A<C<B$"],"설명":"세 값을 비교하면 A<C<B이다.","확인":null,"스킬":"N5"}],"fb":"fig/ns/"},"ns-9cbc6cbd8d7f":{"길":"a>0 조건으로 여섯 식을 정리해 값이 -a인 것의 개수를 센다","단계":[{"제목":"여섯 식 정리하기","힌트":"a>0일 때 √(a²), -√((-a)²)은 각각 얼마일까?","식":["$\\sqrt{a^2}=a,\\ -\\sqrt{a^2}=-a,\\ (\\sqrt a)^2=a,\\ -\\sqrt{(-a)^2}=-a,\\ \\sqrt{(-a)^2}=a,\\ (-\\sqrt a)^2=a$"],"설명":"a>0이므로 근호 안이 양수가 되도록 정리하면 여섯 값이 정해진다.","확인":null,"스킬":"C2"},{"제목":"-a인 것 개수 세기","고비":true,"힌트":"여섯 값 중 -a인 것은 몇 개일까?","식":[],"설명":"값이 -a인 것은 -√(a²)과 -√((-a)²)의 2개이다.","확인":"2","스킬":"C2"}],"fb":"fig/ns/"},"ns-9db32025f0e0":{"길":"x의 구간을 나눠 각 자료의 중앙값을 구하고 세 값이 같아지는 x를 모두 찾아 더한다","단계":[{"제목":"중앙값 자리 확인하기","힌트":"다섯 개씩인 자료에서 중앙값은 몇 번째 값일까?","식":[],"설명":"각 자료가 5개씩이므로 작은 값부터 세 번째 값이 중앙값이다.","확인":null,"스킬":"C2"},{"제목":"x<5인 경우 확인하기","힌트":"x가 5보다 작으면 세 중앙값은?","식":["$A=5,\\ B=5,\\ C=3\\ 또는\\ x$"],"설명":"이 경우 C가 A, B와 같을 수 없어 A=B=C가 성립하지 않는다.","확인":null,"스킬":"C2"},{"제목":"5≤x≤7인 경우 확인하기","고비":true,"힌트":"이 구간에서 세 중앙값은 모두 x가 될까?","식":["$A=x,\\ B=x,\\ C=x$"],"설명":"이 구간에서는 항상 A=B=C=x가 성립하므로 x=5,6,7이 모두 조건을 만족한다.","확인":null,"스킬":"C2"},{"제목":"x>7인 경우 확인하기","힌트":"x가 7보다 크면 세 중앙값은?","식":["$A=8,\\ B=7,\\ C=8$"],"설명":"이 경우 세 값이 같지 않으므로 조건을 만족하지 않는다.","확인":null,"스킬":"C2"},{"제목":"만족하는 x를 모두 더하기","힌트":"조건을 만족하는 x는 5,6,7뿐이므로 합은?","식":["$5+6+7=18$"],"설명":"만족하는 모든 자연수 x의 합은 18이다.","확인":"18","스킬":"A2"}],"fb":"fig/ns/"},"ns-9ddaf5e275b2":{"길":"두 순환소수를 분수로 바꿔 식을 세우고 b/a를 기약분수로 정리한다","단계":[{"제목":"순환소수를 분수로 바꾸기","힌트":"1.0(2 반복)과 0.(2 반복)을 분수로 나타내면?","식":["$1.0\\dot2=\\frac{92}{90},\\ 0.\\dot2=\\frac29$"],"설명":"두 순환소수를 분수로 고친다.","확인":null,"스킬":"N6"},{"제목":"식을 세워 정리하기","고비":true,"힌트":"양변을 제곱하면 근호가 사라질까?","식":["$\\frac{92}{90}\\times\\frac ba=\\left(\\frac29\\right)^2=\\frac4{81}$"],"설명":"양변을 제곱한 뒤 b/a에 대한 식으로 정리한다.","확인":null,"스킬":"N6"},{"제목":"b/a를 기약분수로 정리하기","힌트":"4/81 × 90/92를 약분하면?","식":["$\\frac ba=\\frac4{81}\\times\\frac{90}{92}=\\frac{10}{207}$"],"설명":"계산하면 b/a=10/207이고 10과 207은 서로소이므로 a=207, b=10이다.","확인":null,"스킬":"N6"},{"제목":"a-b 계산하기","힌트":"207에서 10을 빼면?","식":["$a-b=207-10=197$"],"설명":"a-b=197이다.","확인":"197","스킬":"N6"}],"fb":"fig/ns/"},"ns-9ea742e6d0b6":{"길":"완전제곱으로 바꾼 뒤 다섯 선지를 하나씩 대입·계산해 옳은 것을 고른다","단계":[{"제목":"완전제곱으로 바꾸기","힌트":"y=-10x²+200x+3000을 완전제곱으로 바꾸면?","식":["$y=-10(x-10)^{2}+4000$"],"설명":"완전제곱 꼴로 바꾸면 최댓값의 위치와 크기가 보인다.","확인":null,"스킬":"A6"},{"제목":"①②판별하기","힌트":"x=10일 때 높이는 얼마일까?","식":[],"설명":"최댓값은 x=10에서 4000이므로 ①(20초), ②(2000m)는 모두 옳지 않다.","확인":null,"스킬":"A6"},{"제목":"③판별하기","힌트":"y=0이 되는 x를 구하면?","식":["$-10x^{2}+200x+3000=0\\Rightarrow x=30$"],"설명":"지면에 떨어지는 시간은 30초이므로 ③은 옳지 않다.","확인":null,"스킬":"A6"},{"제목":"④판별하기","힌트":"x=1을 대입하면?","식":["$y=-10+200+3000=3190$"],"설명":"1초 후 높이는 3190m이므로 ④는 옳지 않다.","확인":null,"스킬":"A9"},{"제목":"⑤판별하기","고비":true,"힌트":"높이가 4000m가 되는 x는?","식":["$-10(x-10)^{2}+4000=4000\\Rightarrow x=10$"],"설명":"최댓값 4000m가 되는 때는 x=10초이므로 ⑤가 옳다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-9fbc69755ac8":{"길":"상수항 부호를 바꾼 방정식에 근 2를 대입해 a를 구하고, 원래 방정식을 근의 공식으로 풀어 2A-B를 계산한다","단계":[{"제목":"부호를 바꾼 방정식에 근을 대입해 a 구하기","고비":true,"힌트":"상수항의 부호를 바꾼 식 x²-ax-(1-a)=0에 x=2를 넣으면?","식":["$4-2a-(1-a)=0$","$-a+3=0,\\ a=3$"],"설명":"상수항의 부호를 바꾼 방정식에 근 x=2를 대입해 a를 구한다.","확인":"3","스킬":"A4"},{"제목":"원래 방정식을 근의 공식으로 풀기","힌트":"a=3을 원래 식 x²-ax+(1-a)=0에 넣으면?","식":["$x^2-3x-2=0$","$x=\\frac{3\\pm\\sqrt{17}}{2}$"],"설명":"원래 방정식은 x²-3x-2=0이 되고, 근의 공식으로 풀면 두 근을 얻는다.","확인":null,"스킬":"A6"},{"제목":"2A-B 계산하기","힌트":"큰 근 A와 작은 근 B를 식에 넣으면?","식":["$A=\\frac{3+\\sqrt{17}}{2},\\ B=\\frac{3-\\sqrt{17}}{2}$","$2A-B=\\frac{3(1+\\sqrt{17})}{2}$"],"설명":"2A-B를 계산해 통분하면 답을 얻는다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-a2116308e54a":{"길":"다섯 진술에 특수각 값을 대입해 계산하고 참인 것을 모두 고른다","단계":[{"제목":"ㄱ,ㄴ 계산하기","힌트":"sin90+cos0과 (1+tan30)(1-tan30)을 계산하면?","식":["$\\sin90^\\circ+\\cos0^\\circ=1+1=2$","$(1+\\tan30^\\circ)(1-\\tan30^\\circ)=1-\\frac13=\\frac23$"],"설명":"계산하면 ㄱ은 값이 1이 아니라 거짓, ㄴ은 참이다.","확인":null,"스킬":"S6"},{"제목":"ㄷ,ㄹ 계산하기","힌트":"(cos30)²+(sin60)²과 sin60×cos45×tan60을 계산하면?","식":["$(\\cos30^\\circ)^2+(\\sin60^\\circ)^2=\\frac34+\\frac34=\\frac32$","$\\sin60^\\circ\\times\\cos45^\\circ\\times\\tan60^\\circ=\\frac{3\\sqrt2}{4}$"],"설명":"계산하면 ㄷ은 값이 1이 아니라 거짓, ㄹ은 참이다.","확인":null,"스킬":"S6"},{"제목":"ㅁ 계산하기","고비":true,"힌트":"½tan45+√3cos30-3√2cos45를 차례로 계산하면?","식":["$\\frac12\\times1+\\sqrt3\\times\\frac{\\sqrt3}{2}-3\\sqrt2\\times\\frac{\\sqrt2}{2}=\\frac12+\\frac32-3=-1$"],"설명":"세 항을 각각 계산해 더하면 -1이 되어 ㅁ은 참이다.","확인":"-1","스킬":"S6"},{"제목":"옳은 것 고르기","힌트":"참인 진술만 모으면?","식":[],"설명":"ㄴ, ㄹ, ㅁ이 참이므로 답은 ㄴ, ㄹ, ㅁ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-a53543e15ff6":{"길":"세 진술을 정의대로 따져보고, p=0 조건이 빠진 ㄴ의 함정을 가려낸다","단계":[{"제목":"ㄱ 판별하기","힌트":"q=0이면 (x-p)²=0의 해는?","식":["$x=p$ (중근)"],"설명":"q=0이면 완전제곱식이 0이 되어 중근 x=p를 가지므로 ㄱ은 옳다.","확인":null,"스킬":"A6"},{"제목":"ㄴ 판별하기","고비":true,"힌트":"q>0이면 두 근은 p±√q인데, 항상 부호가 반대일까?","식":["$x=p\\pm\\sqrt{q}$"],"설명":"두 근은 p+√q, p-√q이며 p≠0이면 절댓값이 같지 않고 부호도 반대가 아닐 수 있으므로 ㄴ은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판별하기","힌트":"p=0, q>0이면 방정식은 어떤 꼴이 될까?","식":["$x^2=q\\ \\Rightarrow\\ x=\\pm\\sqrt{q}$"],"설명":"p=0이면 x=±√q이므로 두 근의 합은 0이 되어 ㄷ은 옳다. 옳은 것은 ㄱ, ㄷ이다.","확인":"0","스킬":"A6"}],"fb":"fig/ns/"},"ns-a7ac0237ff56":{"길":"다섯 보기에 반례를 대입해 무리수인지 하나씩 확인한다","단계":[{"제목":"ㄱ, ㄷ에 반례 대입하기","힌트":"a=-√3이면 a+√3은?","식":["$a=-\\sqrt{3}\\Rightarrow a+\\sqrt{3}=0$","$a=\\sqrt{5}\\Rightarrow\\sqrt{5}a=5$"],"설명":"ㄱ은 a=-√3일 때, ㄷ은 a=√5일 때 결과가 유리수가 되므로 항상 무리수가 아니다.","확인":null,"스킬":"C3"},{"제목":"ㅁ에 반례 대입하기","고비":true,"힌트":"a=4+2√3이면 (1-√3)²a는?","식":["$(1-\\sqrt{3})^2a=(4-2\\sqrt{3})(4+2\\sqrt{3})=16-12=4$"],"설명":"ㅁ도 특정 a에서 유리수가 되는 반례가 있어 항상 무리수는 아니다.","확인":null,"스킬":"C3"},{"제목":"ㄴ, ㄹ 판별하기","힌트":"a+2, 3a는 무리수에 유리수를 더하거나 곱한 것일까?","식":[],"설명":"무리수에 0이 아닌 유리수를 더하거나 곱한 결과는 항상 무리수이므로 ㄴ, ㄹ은 항상 무리수다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-a8a320bde85e":{"길":"다섯 선지를 폭, 대칭, 사분면, 증감 기준으로 하나씩 따져 옳은 것을 고른다","단계":[{"제목":"①판별하기","힌트":"위로 볼록한 그래프는 이차항 계수가?","식":[],"설명":"이차항 계수가 음수인 ㄴ, ㄷ, ㅂ이 위로 볼록하므로 ①은 옳지 않다.","확인":null,"스킬":"G4"},{"제목":"②판별하기","힌트":"ㄴ, ㄹ, ㅁ의 폭을 비교하면?","식":[],"설명":"ㄴ의 폭은 ㄹ보다 좁고 ㅁ과 같으므로 ②는 옳지 않다.","확인":null,"스킬":"G4"},{"제목":"③판별하기","힌트":"y축에 대칭인 그래프는 어떤 조건일까?","식":[],"설명":"평행이동하지 않은 ㄱ, ㄴ, ㄷ, ㅁ이 y축 대칭이므로 ③은 옳지 않다.","확인":null,"스킬":"G4"},{"제목":"④판별하기","고비":true,"힌트":"제3사분면을 지나려면 그래프가 어디에 있어야 할까?","식":[],"설명":"위로 볼록하며 y절편이 음수인 ㄴ, ㄷ, ㅂ이 제3사분면을 지나므로 ④가 옳다.","확인":null,"스킬":"G4"},{"제목":"⑤ 확인하고 답 정하기","힌트":"x>0에서 증가하는 것은 몇 개일까?","식":[],"설명":"x>0에서 증가하는 것은 ㄱ, ㄹ, ㅁ이므로 ⑤는 옳지 않다. 따라서 옳은 것은 ④이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-a98f5ecbfc5f":{"길":"네 보기에 반례를 확인해 옳은 것만 고른다","단계":[{"제목":"ㄱ 반례 확인하기","힌트":"√2+1의 제곱은?","식":["$(\\sqrt{2}+1)^2=3+2\\sqrt{2}$"],"설명":"무리수의 제곱이 무리수가 되는 반례가 있어 ㄱ은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판별하기","힌트":"무리수도 수직선 위의 점에 대응시킬 수 있을까?","식":[],"설명":"무리수도 수직선 위 한 점과 대응되므로 ㄷ은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄴ, ㄹ 판별하기","고비":true,"힌트":"두 실수 사이에는 유리수가 있을까, 제곱수가 아닌 수의 제곱근은?","식":[],"설명":"두 실수 사이에는 항상 무수히 많은 유리수가 있으므로 ㄴ은 옳고, 제곱수가 아닌 자연수의 제곱근은 무리수이므로 ㄹ도 옳다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-a9b514ed409c":{"길":"겉넓이 식을 세워 세로 길이를 구한 뒤 분모를 유리화해 부피를 계산한다","단계":[{"제목":"겉넓이 식 세우기","힌트":"세로를 x라 하면 겉넓이는 어떤 식일까?","식":["$2(5\\sqrt{3}x+3\\sqrt{2}x+5\\sqrt{3}\\times3\\sqrt{2})=48+70\\sqrt{6}$"],"설명":"세로의 길이를 x로 놓고 직육면체의 겉넓이 공식을 세운다.","확인":null,"스킬":"C7"},{"제목":"식 정리해 x의 계수 모으기","힌트":"괄호를 풀어 x에 대해 정리하면?","식":["$(5\\sqrt{3}+3\\sqrt{2})x+15\\sqrt{6}=24+35\\sqrt{6}$","$(5\\sqrt{3}+3\\sqrt{2})x=24+20\\sqrt{6}$"],"설명":"양변을 전개하고 상수항 15√6을 이항해 x의 계수식을 만든다.","확인":null,"스킬":"A3"},{"제목":"분모를 유리화해 x 구하기","고비":true,"힌트":"분모 5√3+3√2를 없애려면 무엇을 곱할까?","식":["$x=\\frac{24+20\\sqrt{6}}{5\\sqrt{3}+3\\sqrt{2}}=\\frac{4(6+5\\sqrt{6})(5\\sqrt{3}-3\\sqrt{2})}{57}=4\\sqrt{2}$"],"설명":"켤레 5√3-3√2를 분모, 분자에 곱해 유리화하면 x=4√2를 얻는다.","확인":null,"스킬":"N6"},{"제목":"부피 계산하기","힌트":"가로, 세로, 높이를 모두 곱하면?","식":["$5\\sqrt{3}\\times4\\sqrt{2}\\times3\\sqrt{2}=120\\sqrt{3}$"],"설명":"세 변의 길이를 곱해 부피 120√3 cm³를 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-ae02a3e5f2e1":{"길":"네 개의 오답 선지에 반례를 대입해 지우고 남는 것을 고른다","단계":[{"제목":"①, ②에 반례 대입하기","힌트":"a=√2, b=0이면 ab는? a=√2, b=2이면 √b/a는?","식":["$ab=\\sqrt{2}\\times0=0$","$\\frac{\\sqrt{b}}{a}=\\frac{\\sqrt{2}}{\\sqrt{2}}=1$"],"설명":"두 반례에서 모두 유리수가 나와 ①, ②는 항상 무리수가 아니다.","확인":null,"스킬":"C3"},{"제목":"④, ⑤에 반례 대입하기","고비":true,"힌트":"a=√2, b=2이면 a²-b²은, a=-√2, b=2이면 a+√b는?","식":["$a^2-b^2=2-4=-2$","$a+\\sqrt{b}=-\\sqrt{2}+\\sqrt{2}=0$"],"설명":"④, ⑤도 특정 값에서 유리수가 되는 반례가 있어 제외된다.","확인":null,"스킬":"C3"},{"제목":"③이 항상 무리수임을 확인하기","힌트":"무리수에 유리수를 더하면 항상 무리수일까?","식":[],"설명":"무리수와 유리수의 합은 어떤 경우에도 유리수가 될 수 없으므로 ③ a+b가 항상 무리수다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-aecaf291adb4":{"길":"RHS 합동 증명의 빈칸을 순서대로 채워 어긋난 결론을 찾는다","단계":[{"제목":"㉠, ㉡, ㉢ 채우기","힌트":"수선이 만드는 각과 반지름, 공통변은?","식":["$\\angle OMA=\\angle OMB=90^{\\circ},\\ \\overline{OA}=\\overline{OB}(반지름),\\ \\overline{OM}은\\ 공통$"],"설명":"직각, 반지름이 같음, 공통변을 채운다.","확인":null,"스킬":"S5"},{"제목":"㉣ 채우기","힌트":"직각삼각형의 합동 조건은?","식":["$\\triangle OAM\\equiv\\triangle OBM\\ (RHS\\ 합동)$"],"설명":"빗변과 다른 한 변이 각각 같으므로 RHS 합동이다.","확인":null,"스킬":"S5"},{"제목":"㉤ 확인하기","고비":true,"힌트":"합동에서 나오는 결론은 AM=?","식":["$\\overline{AM}=\\overline{BM}$"],"설명":"합동이므로 AM=BM이 되어야 하는데 AM=OM이라 한 ㉤은 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-af0b3dcb94f6":{"길":"분모를 유리화해 telescoping(소거) 형태로 만들어 더한다","단계":[{"제목":"1/f(a) 유리화하기","힌트":"분모 √(a+1)+√a에 켤레를 곱하면?","식":["$\\frac{1}{f(a)}=\\frac{\\sqrt{a+1}-\\sqrt{a}}{(\\sqrt{a+1}+\\sqrt{a})(\\sqrt{a+1}-\\sqrt{a})}=\\sqrt{a+1}-\\sqrt{a}$"],"설명":"분모, 분자에 켤레 √(a+1)-√a를 곱해 분모를 유리수 1로 만든다.","확인":null,"스킬":"N6"},{"제목":"합을 소거되는 형태로 나열하기","고비":true,"힌트":"각 항을 (√(a+1)-√a) 꼴로 나열하면 무엇이 남을까?","식":["$(-\\sqrt{1}+\\sqrt{2})+(-\\sqrt{2}+\\sqrt{3})+\\cdots+(-\\sqrt{1001}+\\sqrt{1002})$"],"설명":"이웃한 항끼리 부호가 반대라 중간 항들이 모두 사라지고 처음과 끝 항만 남는다.","확인":null,"스킬":"P6"},{"제목":"남은 값 정리하기","힌트":"남은 -√1과 √1002를 정리하면?","식":["$=-1+\\sqrt{1002}$"],"설명":"소거되고 남은 -√1=-1과 √1002를 더해 최종값을 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-b19f0875aac9":{"길":"네 진술을 정의와 반례로 하나씩 따져 옳은 것만 고른다","단계":[{"제목":"㉮ 판별하기","힌트":"b=0,c=0이면 ax²=0인데 이것도 이차방정식일까?","식":["$ax^2=0\\ (a\\ne0)$"],"설명":"a≠0이므로 ax²=0도 이차방정식이다. 따라서 ㉮는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"㉯, ㉰ 판별하기","힌트":"판별식의 부호에 따라 근의 개수가 어떻게 달라질까?","식":["$b^2-4ac>0\\to$서로 다른 두 근","$b^2-4ac=0\\to$중근"],"설명":"판별식이 양수이면 서로 다른 두 근, 0이면 중근을 가지므로 ㉯, ㉰는 모두 옳다.","확인":null,"스킬":"C3"},{"제목":"㉱ 판별하기","고비":true,"힌트":"b=0이면 x²=-c/a인데, -c/a가 음수이면 근이 있을까?","식":["$x^2=-\\frac{c}{a}$"],"설명":"-c/a가 음수이면 실근이 없으므로 '항상 절댓값이 같고 부호가 다른 두 근을 가진다'는 ㉱는 옳지 않다. 옳은 것은 ㉯, ㉰이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-b2e06b4ac7b2":{"길":"0<a<1일 때 다섯 식의 크기를 부등식으로 정리해 순서를 매긴다","단계":[{"제목":"각 식의 범위 정하기","힌트":"0<a<1일 때 √a, 1/√a, 1/a, a²의 범위는?","식":["$0<\\sqrt{a}<1,\\quad \\frac{1}{\\sqrt{a}}>1,\\quad \\frac{1}{a}>1,\\quad 0<a^2<1$"],"설명":"0과 1 사이의 수는 거듭제곱하면 작아지고 역수를 취하면 1보다 커진다는 성질로 각 식의 범위를 정한다.","확인":null,"스킬":"C3"},{"제목":"전체 순서 정하기","고비":true,"힌트":"1/a와 1/√a 중 어느 것이 더 크고, a와 a² 중 어느 것이 더 클까?","식":["$\\frac{1}{a}>\\frac{1}{\\sqrt{a}}>\\sqrt{a}>a>a^2$"],"설명":"1보다 큰 것끼리, 1보다 작은 것끼리 다시 비교해 다섯 식을 크기 순으로 나열한다.","확인":null,"스킬":"C3"},{"제목":"세 번째로 큰 수 찾기","힌트":"큰 수부터 나열하면 세 번째는?","식":[],"설명":"1/a, 1/√a, √a, a, a² 순이므로 세 번째로 큰 수는 ㉠(√a)이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-b39b4a549b7f":{"길":"판별식 13-4k가 완전제곱수(0 포함)가 되는 자연수 k를 모두 찾아 합을 구한다","단계":[{"제목":"근의 공식으로 판별식 확인하기","힌트":"x²+5x+(k+3)=0을 근의 공식으로 풀면?","식":["$x=\\frac{-5\\pm\\sqrt{13-4k}}{2}$"],"설명":"근의 공식을 적용하면 13-4k가 근호 안에 남는다.","확인":null,"스킬":"A6"},{"제목":"완전제곱수 조건으로 경우 나누기","고비":true,"힌트":"√(13-4k)가 유리수가 되려면 13-4k는 어떤 수여야 할까?","식":["$\\sqrt{13-4k}=0,1,2,3$"],"설명":"해가 모두 유리수이려면 13-4k가 0이거나 제곱수여야 하므로 그 값을 0부터 차례로 넣어 본다.","확인":null,"스킬":"N8"},{"제목":"자연수 k만 골라내기","힌트":"각 경우의 k값 중 자연수인 것은?","식":["$k=\\frac{13}{4},3,\\frac94,1$"],"설명":"네 경우의 k값 중 자연수는 k=3과 k=1뿐이다.","확인":null,"스킬":"C2"},{"제목":"합 구하기","힌트":"자연수 k들을 더하면?","식":["$1+3=4$"],"설명":"자연수 k의 값 1과 3을 더하면 답은 4이다.","확인":"4","스킬":"N8"}],"fb":"fig/ns/"},"ns-b3c18953f5db":{"길":"이차방정식을 완전제곱식으로 바꾸는 과정을 직접 전개해 각 선지의 빈칸이 맞는지 확인한다","단계":[{"제목":"양변을 a로 나눈 식 확인하기","힌트":"ax²+2bx+c=0을 a로 나누면 x의 계수는?","식":["$x^2+\\frac{2b}{a}x=-\\frac{c}{a}$"],"설명":"양변을 a로 나누고 상수항을 이항하면 x의 계수는 2b/a이므로 ㉠은 b/a가 아니라 2b/a여야 해 옳지 않다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식 만들기","고비":true,"힌트":"양변에 (b/a)²을 더하면 좌변은 어떤 완전제곱식이 될까?","식":["$\\left(x+\\frac{b}{a}\\right)^2=\\frac{b^2-ac}{a^2}$"],"설명":"양변에 (b/a)²을 더하면 좌변은 (x+b/a)², 우변은 (b²-ac)/a²이 된다. ㉢은 b/a(제곱 없이)여야 하고, ㉣은 (b²-ac)/a²으로 옳다.","확인":null,"스킬":"A6"},{"제목":"제곱근을 풀어 x 확인하기","힌트":"양변에 제곱근을 취해 정리하면 분모는?","식":["$x=\\frac{-b\\pm\\sqrt{b^2-ac}}{a}$"],"설명":"분모는 a가 되어야 하므로 분모가 2a인 ㉤도 옳지 않다. 옳은 것은 ㉣ 하나뿐이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-b56e4d3253bc":{"길":"앞의 두 다항식을 인수분해해 공통인수를 찾고, 그 인수로 세 번째 식의 A를 구한다","단계":[{"제목":"첫 다항식 인수분해하기","힌트":"4x²+10x-24에서 공통인수 2를 묶으면?","식":["$4x^2+10x-24=2(2x^2+5x-12)=2(2x-3)(x+4)$"],"설명":"2를 묶어낸 뒤 인수분해하면 (2x-3)(x+4)를 얻는다.","확인":null,"스킬":"A4"},{"제목":"둘째 다항식 인수분해하기","힌트":"8x²y-14xy+3y에서 공통인수 y를 묶으면?","식":["$8x^2y-14xy+3y=y(8x^2-14x+3)=y(2x-3)(4x-1)$"],"설명":"y를 묶어낸 뒤 인수분해하면 (2x-3)(4x-1)을 얻는다.","확인":null,"스킬":"A4"},{"제목":"공통인수로 셋째 식 인수분해하기","고비":true,"힌트":"공통인수 2x-3을 이용해 4x²+Ax-3을 인수분해하면?","식":["$4x^2+Ax-3=(2x-3)(2x+1)$"],"설명":"두 다항식의 공통인수가 2x-3이므로 셋째 식도 이 인수를 가진다.","확인":null,"스킬":"A4"},{"제목":"A 값 구하기","힌트":"전개했을 때 x의 계수는?","식":["$A=2-6=-4$"],"설명":"(2x-3)(2x+1)을 전개한 x의 계수가 A이므로 A=-4이다.","확인":"-4","스킬":"A3"}],"fb":"fig/ns/"},"ns-b6794254888b":{"길":"다섯 식을 각각 계산해 선지와 다른 값이 나오는 것을 찾는다","단계":[{"제목":"①, ②식 계산해 확인하기","힌트":"분모를 유리화하고 근호를 정리하면?","식":["$\\frac{2}{\\sqrt{5}-2}+\\frac{3-\\sqrt{5}}{3+\\sqrt{5}}=\\frac{15+\\sqrt{5}}{2}$","$\\sqrt{\\frac{6}{49}}-\\sqrt{24}+\\frac{5\\sqrt{2}}{\\sqrt{3}}=-\\frac{4\\sqrt{6}}{21}$"],"설명":"①, ②는 분모를 유리화하고 동류항을 정리하면 선지와 값이 같다.","확인":null,"스킬":"N6"},{"제목":"③식 직접 계산하기","고비":true,"힌트":"3√24, 3√28, √54를 간단히 하면?","식":["$3\\sqrt{24}-3\\sqrt{28}-\\sqrt{54}+\\sqrt{7}=6\\sqrt{6}-6\\sqrt{7}-3\\sqrt{6}+\\sqrt{7}$"],"설명":"근호를 간단히 하고 동류항을 정리한다.","확인":null,"스킬":"N6"},{"제목":"③을 정리하고 선지와 비교하기","힌트":"동류항을 모으면 실제 값은?","식":["$=3\\sqrt{6}-5\\sqrt{7}$"],"설명":"실제 계산값은 3√6-5√7인데 선지는 9√6-5√7로 적혀 있어 옳지 않다.","확인":null,"스킬":"N6"},{"제목":"④, ⑤도 값이 맞는지 확인하기","힌트":"나머지 두 식도 계산하면 선지와 같을까?","식":["$\\frac{3}{4\\sqrt{3}}+\\sqrt{6}\\div\\frac{4\\sqrt{2}}{3}-\\frac{\\sqrt{12}}{4}\\div3=\\frac{5\\sqrt{3}}{6}$"],"설명":"④, ⑤를 계산해도 선지와 값이 같으므로 옳지 않은 것은 ③뿐이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-b8634c018821":{"길":"네 이차방정식의 근을 각각 구한 뒤 중근·근의 합·곱·부호를 선지별로 확인한다","단계":[{"제목":"(ⅰ),(ⅱ) 방정식 풀기","힌트":"인수분해와 제곱근으로 풀면?","식":["$x^2-2x-24=0\\Rightarrow x=-4,6$","$5x^2-25=0\\Rightarrow x=\\pm\\sqrt5$"],"설명":"첫째 식은 인수분해로, 둘째 식은 제곱근으로 푼다.","확인":null,"스킬":"A6"},{"제목":"(ⅲ),(ⅳ) 방정식 풀기","힌트":"전개해서 정리하거나 완전제곱식 그대로 풀면?","식":["$(x-4)^2=3x-8\\Rightarrow x=3,8$","$(x+2)^2=6\\Rightarrow x=-2\\pm\\sqrt6$"],"설명":"셋째 식은 전개해 인수분해하고, 넷째 식은 그대로 제곱근을 취해 푼다.","확인":null,"스킬":"A6"},{"제목":"중근을 갖는지 확인하기","고비":true,"힌트":"네 방정식 중 두 근이 같은 것이 있을까?","식":[],"설명":"네 방정식의 근이 각각 -4·6, ±√5, 3·8, -2±√6로 모두 서로 다른 두 근이므로 중근을 가지는 방정식은 없다.","확인":null,"스킬":"C3"},{"제목":"두 근의 합·곱 확인하기","힌트":"두 근의 합이 0인 방정식, 곱이 음수인 방정식은 몇 개일까?","식":["(ii)에서 합=0","곱: (i)-24, (ii)-5, (iv)-2로 음수 3개"],"설명":"②는 (ii)가 있어 틀리고, 두 근의 곱이 음수인 방정식은 (i),(ii),(iv) 3개이므로 ③(1개)도 틀리다.","확인":null,"스킬":"C3"},{"제목":"무리수 근·모두 음수인 근 확인해 정답 확정하기","힌트":"무리수인 근을 가지는 방정식과 두 근 모두 음수인 방정식은 각각 몇 개일까?","식":["무리수: (ii),(iv) 2개","모두 음수인 것: 없음"],"설명":"④는 무리수 근을 가지는 방정식이 2개이므로 틀리고, ⑤는 두 근이 모두 음수인 방정식이 없어 틀리다. 따라서 옳은 것은 ①이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-b934a4f0d857":{"길":"형과 동생의 평균·중앙값·최빈값을 각각 구해 선지를 하나씩 확인한다","단계":[{"제목":"형의 평균 구하기","힌트":"형의 점수 8,9,10,6,7의 평균은?","식":["$\\frac{8+9+10+6+7}{5}=8$"],"설명":"형의 평균 점수는 8점이다.","확인":null,"스킬":"P4"},{"제목":"동생의 평균 구하고 비교하기","힌트":"동생의 점수 5,3,7,8,7의 평균은?","식":["$\\frac{5+3+7+8+7}{5}=6$"],"설명":"동생의 평균은 6점으로 형의 평균보다 낮으므로 형의 평균이 더 높다는 ①은 옳다.","확인":null,"스킬":"P4"},{"제목":"두 사람의 중앙값 비교하기","힌트":"점수를 작은 값부터 나열하면 중앙값은?","식":["형: $6,7,8,9,10\\to8$","동생: $3,5,7,7,8\\to7$"],"설명":"형의 중앙값은 8, 동생의 중앙값은 7로 서로 달라 ②도 옳다.","확인":null,"스킬":"P4"},{"제목":"형의 최빈값 존재 여부 확인하기","힌트":"형의 점수에 같은 값이 있을까?","식":[],"설명":"형의 점수는 모두 달라 최빈값이 존재하지 않으므로 중앙값과 최빈값이 같다는 ④는 옳지 않다.","확인":null,"스킬":"P4","고비":true},{"제목":"나머지 선지 확인해 답 정하기","힌트":"동생의 중앙값과 최빈값은 같을까?","식":["동생 최빈값 $=7$"],"설명":"동생의 중앙값과 최빈값이 모두 7로 같아 ⑤도 옳으므로, 옳지 않은 것은 ④이다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-b9928e9443d3":{"길":"3^12-1을 합차공식으로 반복해서 인수분해한 뒤 각 인수를 소인수분해해 약수 개수를 구한다","단계":[{"제목":"합차공식 반복 적용하기","힌트":"3^12-1을 (3^6+1)(3^6-1)로 나누고 다시 나누면?","식":["$3^{12}-1=(3^6+1)(3^6-1)=(3^6+1)(3^3+1)(3^3-1)$"],"설명":"합차공식을 두 번 적용해 세 인수로 나눈다.","확인":null,"스킬":"A6"},{"제목":"각 인수 값 구하기","힌트":"3^6+1, 3^3+1, 3^3-1의 값은?","식":["$3^6+1=730,\\ 3^3+1=28,\\ 3^3-1=26$"],"설명":"세 인수를 직접 계산하면 730, 28, 26이다.","확인":null,"스킬":"A6"},{"제목":"각 인수 소인수분해하기","고비":true,"힌트":"730, 28, 26을 각각 소인수분해하면?","식":["$730=2\\times5\\times73$","$28=2^2\\times7$","$26=2\\times13$"],"설명":"세 수를 소인수분해해 곱하면 2^4×5×7×13×73이다.","확인":null,"스킬":"N1"},{"제목":"약수 개수 세기","힌트":"지수에 1을 더해 곱하면?","식":["$(4+1)\\times(1+1)\\times(1+1)\\times(1+1)\\times(1+1)$","$=5\\times2\\times2\\times2\\times2=80$"],"설명":"각 소인수 지수에 1을 더해 곱하면 약수의 개수는 80개이다.","확인":"80","스킬":"N1"}],"fb":"fig/ns/"},"ns-ba415a582f6d":{"길":"공통인수로 p(x)를 구한 뒤 다섯 선지를 각각 인수분해·완전제곱·반례로 따진다","단계":[{"제목":"p(x) 구하기","힌트":"공통인수 x로 묶으면 p(x)는?","식":["$4x^3+(m+5)x^2+9x=x\\{4x^2+(m+5)x+9\\}$"],"설명":"x로 묶으면 p(x)=4x²+(m+5)x+9이다.","확인":null,"스킬":"A4"},{"제목":"①, ② 판별하기","힌트":"p(x)의 차수와, x가 인수인지는?","식":[],"설명":"p(x)는 이차식이고, x{...} 꼴로 묶었으므로 x는 인수이다. 두 선지 모두 옳다.","확인":null,"스킬":"A4"},{"제목":"③ 판별하기","힌트":"m=-17일 때 p(x)는?","식":["$p(x)=4x^2-12x+9=(2x-3)^2$"],"설명":"m=-17을 대입하면 완전제곱식이 되므로 ③은 옳다.","확인":null,"스킬":"A6"},{"제목":"④ 판별하기","힌트":"우변을 만들 때 쓰인 것은 분배법칙일까, 인수분해일까?","식":[],"설명":"공통인수로 묶는 것은 인수분해이지 분배법칙이 아니므로 ④는 옳지 않다.","확인":null,"스킬":"A4"},{"제목":"⑤ 반례 찾기","고비":true,"힌트":"m이 정수이면서 p(x)가 두 일차식으로 인수분해되는 경우가 있을까?","식":["$m=15$일 때 $p(x)=4x^2+20x+9=(2x+9)(2x+1)$"],"설명":"m=15일 때 p(x)가 두 일차식의 곱으로 인수분해되는 반례가 있으므로 ⑤도 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"옳지 않은 것 정리하기","힌트":"옳지 않은 선지를 모두 고르면?","식":[],"설명":"④, ⑤가 옳지 않으므로 답은 ④, ⑤이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-badb1ba0d30d":{"길":"xy를 구한 뒤 (a+b)²-(a-b)²=4ab 항등식으로 값을 계산한다","단계":[{"제목":"xy 값 구하기","힌트":"x=2+√5, y=2-√5의 곱은?","식":["$xy=(2+\\sqrt5)(2-\\sqrt5)=4-5=-1$"],"설명":"합차공식으로 곱하면 xy=-1이다.","확인":"-1","스킬":"A6"},{"제목":"식을 항등식으로 바꾸기","고비":true,"힌트":"(a+b)²-(a-b)²을 전개하면 무엇이 남을까?","식":["$(x^{10}+y^{10})^2-(x^{10}-y^{10})^2=4x^{10}y^{10}$"],"설명":"(a+b)²-(a-b)²=4ab 항등식을 a=x^10, b=y^10에 적용한다.","확인":null,"스킬":"A2"},{"제목":"값 계산하기","힌트":"4(xy)^10을 계산하면?","식":["$4(xy)^{10}=4\\times(-1)^{10}=4$"],"설명":"xy=-1을 대입하면 (-1)^10=1이므로 값은 4이다.","확인":"4","스킬":"N5"}],"fb":"fig/ns/"},"ns-bfaa9ca7b9d1":{"길":"sinA로 A를 특정한 뒤 부호를 판단해 절댓값을 풀어 더한다","단계":[{"제목":"A의 값 구하기","힌트":"sinA=1/2를 만족하는 0°~90° 사이의 각은?","식":["$\\sin A=\\dfrac12\\Rightarrow A=30^\\circ$"],"설명":"특수각의 삼각비를 이용해 A=30°임을 구한다.","확인":null,"스킬":"C2"},{"제목":"cosA의 부호 판단하기","고비":true,"힌트":"cos30°는 1보다 작을까? cosA-1과 1+cosA의 부호는?","식":["$\\cos A=\\cos30^\\circ=\\dfrac{\\sqrt3}{2}<1$"],"설명":"cosA-1<0, 1+cosA>0이므로 절댓값 기호를 벗길 때 부호를 반대로 해야 한다.","확인":null,"스킬":"C2"},{"제목":"절댓값을 풀어 값 구하기","힌트":"부호에 맞게 근호 안 제곱을 절댓값으로 풀면?","식":["$(1-\\cos A)+(1+\\cos A)=2$"],"설명":"부호에 맞게 절댓값을 풀어 더하면 cosA가 상쇄되어 2가 된다.","확인":"2","스킬":"C2"}],"fb":"fig/ns/"},"ns-c35219bce74d":{"길":"다섯 성질에 간단한 반례를 넣어 어긋나는 것을 찾는다","단계":[{"제목":"성질들 훑어보기","힌트":"②~⑤는 제곱근의 기본 성질과 같은 식일까?","식":[],"설명":"②~⑤는 제곱근의 곱셈·나눗셈·거듭제곱 성질 그대로이므로 항상 성립한다.","확인":null,"스킬":"C3"},{"제목":"①에 반례 대입하기","고비":true,"힌트":"a=b=1을 넣으면 양변이 같을까?","식":["$\\sqrt{1}+\\sqrt{1}=2,\\quad \\sqrt{1+1}=\\sqrt{2}$"],"설명":"간단한 반례로 √a+√b=√(a+b)가 항상 성립하지 않음을 확인한다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-c3f3cda123bf":{"길":"√166을 표의 값으로 바꿔 계산한 뒤 남은 값을 다시 표에서 찾는다","단계":[{"제목":"√166을 표로 읽을 수 있게 바꾸기","힌트":"166=10²×1.66이므로 √166은?","식":["$\\sqrt{166}=\\sqrt{10^2\\times1.66}=10\\sqrt{1.66}$"],"설명":"166을 100×1.66으로 바꿔 표에 있는 √1.66 꼴을 만든다.","확인":null,"스킬":"N6"},{"제목":"표에서 값을 읽어 √166 구하기","힌트":"표에서 1.66에 해당하는 값은?","식":["$\\sqrt{166}=10\\times1.288=12.88$"],"설명":"제곱근표에서 1.66에 해당하는 값을 읽어 10을 곱한다.","확인":null,"스킬":"N6"},{"제목":"x² 구하고 표에서 x 찾기","고비":true,"힌트":"12.88-11.14를 구한 뒤 다시 표에서 찾으면?","식":["$x^2=12.88-11.14=1.74$","$x=\\sqrt{1.74}=1.319$"],"설명":"x²의 값을 구한 뒤 표에서 그 값에 해당하는 제곱근을 찾는다.","확인":"1.319","스킬":"N6"}],"fb":"fig/ns/"},"ns-c49be5571999":{"길":"선지마다 삼각형 넓이 공식에 대입해 계산하고 제시된 값과 비교한다","단계":[{"제목":"①, ② 선지 계산하기","힌트":"S=1/2ab sinC에 45°, 60°를 대입하면?","식":["$C=45^\\circ:\\ S=\\dfrac12ab\\sin45^\\circ=\\dfrac{\\sqrt2}{4}ab$","$C=60^\\circ:\\ S=\\dfrac12ab\\sin60^\\circ=\\dfrac{\\sqrt3}{4}ab$"],"설명":"①은 √2/4 ab, ②는 √3/4 ab가 되어 제시된 값과 달라 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"③ 선지 확인하기","힌트":"a=b이고 B=60°이면 어떤 삼각형일까?","식":["$S=\\dfrac{\\sqrt3}{4}a^2$"],"설명":"a=b, B=60°이면 정삼각형이 되어 넓이는 (√3/4)a²이므로 ③도 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"④ 선지 확인하기","고비":true,"힌트":"C=150°일 때 sin150°의 값은?","식":["$S=\\dfrac12a^2\\sin150^\\circ=\\dfrac12a^2\\times\\dfrac12=\\dfrac14a^2$"],"설명":"a=b, C=150°이면 넓이가 1/4a²이 되어 ④가 옳다.","확인":null,"스킬":"S6"},{"제목":"⑤ 선지 확인하기","힌트":"C가 90°를 넘어서도 sinC가 계속 커질까?","식":[],"설명":"sinC는 0°~90°에서는 커지지만 90°~180°에서는 작아지므로 ⑤는 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-c4d26c9e54da":{"길":"0~90° 구간에서 sin, cos, tan의 증가·감소와 극값을 각각 판단해 선지를 고른다","단계":[{"제목":"② 선지 판단하기","힌트":"cos0°와 tan90°의 값은 각각 무엇일까?","식":["$\\cos0^\\circ=1,\\ \\tan90^\\circ는\\ 정할\\ 수\\ 없음$"],"설명":"분모가 1이어도 tan90° 자체가 정의되지 않으므로 전체 값도 정할 수 없어 ②는 옳다.","확인":null,"스킬":"T5"},{"제목":"③ 선지 판단하기","고비":true,"힌트":"45°보다 큰 각에서 sinA, cosA, tanA의 크기 순서는?","식":["$45^\\circ<A<90^\\circ:\\ \\cos A<\\sin A<\\tan A$"],"설명":"45°를 기준으로 sin은 커지고 cos은 작아지며 tan은 1보다 커지므로 실제 순서는 cos47°<sin47°<tan47°이다. 제시된 순서와 달라 ③은 옳지 않다.","확인":null,"스킬":"T5"},{"제목":"④, ⑤ 선지 판단하기","힌트":"sinA와 tanA는 0°, 90°에서 각각 어떤 값을 가질까?","식":["$\\sin A:\\ 0\\sim1,\\ \\tan A:\\ 0\\sim(정할\\ 수\\ 없음)$"],"설명":"sinA는 최솟값 0, 최댓값 1로 ④는 옳지만, tanA는 최댓값을 정할 수 없어 ⑤는 옳지 않다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-c503f25cc904":{"길":"일곱 진술을 정의대로 하나씩 따져 옳은 것의 개수를 센다","단계":[{"제목":"㉠ 판별하기","힌트":"극단값이 있을 때 평균과 중앙값 중 어느 것이 더 안정적일까?","식":[],"설명":"극단적인 값이 있으면 평균보다 중앙값이 자료의 중심을 더 잘 나타내므로 ㉠은 옳다.","확인":null,"스킬":"C3"},{"제목":"㉡, ㉢ 판별하기","힌트":"도수가 모두 같으면 최빈값이 있을까? 중앙값은 항상 자료 안의 값일까?","식":[],"설명":"도수가 모두 같으면 최빈값은 존재하지 않으므로 ㉡은 옳지 않고, 자료 개수가 짝수이면 중앙값이 자료에 없는 값일 수도 있으므로 ㉢도 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"㉣ 판별하기","힌트":"평균이 크면 산포도도 항상 클까?","식":[],"설명":"평균의 크기와 산포도 사이에는 관계가 없으므로 ㉣은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"㉤, ㉥ 판별하기","힌트":"분산과 표준편차의 정의를 떠올리면?","식":[],"설명":"편차 제곱의 평균은 분산의 정의 그대로이므로 ㉤은 옳고, 표준편차는 분산의 음이 아닌 제곱근이므로 '제곱근'이라고만 한 ㉥은 옳지 않다.","확인":null,"스킬":"C3","고비":true},{"제목":"㉦ 판별하고 개수 세기","힌트":"표준편차가 클수록 자료는 평균에서 얼마나 떨어져 있을까?","식":["옳은 것: ㉠, ㉤, ㉦"],"설명":"표준편차가 클수록 흩어진 정도가 크다는 ㉦도 옳으므로, 옳은 것은 ㉠, ㉤, ㉦의 3개이다.","확인":"3","스킬":"C3"}],"fb":"fig/ns/"},"ns-c680955d20a0":{"길":"표에서 66000을 사이에 두는 두 제곱수를 찾아 √6.6의 범위를 좁힌다","단계":[{"제목":"표에서 66000을 사이에 두는 값 찾기","힌트":"256²과 257² 중 어느 사이에 66000이 있을까?","식":["$256^2<66000<257^2$"],"설명":"표에서 66000을 사이에 두는 두 제곱수를 찾는다.","확인":null,"스킬":"N6"},{"제목":"√6.6의 범위로 바꾸기","고비":true,"힌트":"√66000=100√6.6임을 이용하면?","식":["$256<100\\sqrt{6.6}<257$","$2.56<\\sqrt{6.6}<2.57$"],"설명":"양변을 100으로 나눠 √6.6이 있는 소수 범위를 구한다.","확인":null,"스킬":"N6"},{"제목":"소수점 아래 둘째 자리 읽기","힌트":"2.56과 2.57 사이 값의 둘째 자리 숫자는?","식":[],"설명":"√6.6은 2.56과 2.57 사이이므로 소수점 아래 둘째 자리 숫자는 6이다.","확인":"6","스킬":"N6"}],"fb":"fig/ns/"},"ns-cc001779af09":{"길":"다섯 식을 계산해 부호를 나눈 뒤 음수끼리, 양수끼리 대소를 비교한다","단계":[{"제목":"각 식을 계산해 부호 정하기","힌트":"다섯 식을 정리하면 부호가 어떻게 나뉠까?","식":["$①=3-\\sqrt{3}(+),\\ ②=2\\sqrt{2}(+)$","$③=-4\\sqrt{2}(-),\\ ④=-2(-),\\ ⑤=1-2\\sqrt{3}(-)$"],"설명":"다섯 식을 각각 계산해 정리하면 음수 셋(③④⑤), 양수 둘(①②)로 나뉜다.","확인":null,"스킬":"N6"},{"제목":"음수 세 값의 대소 비교하기","고비":true,"힌트":"-4√2, -2, 1-2√3을 범위로 좁히면?","식":["$-4\\sqrt{2}=-\\sqrt{32}\\Rightarrow-6<-4\\sqrt{2}<-5$","$3<2\\sqrt{3}<4\\Rightarrow-3<1-2\\sqrt{3}<-2$"],"설명":"각 값을 부등식으로 범위를 좁혀 -4√2<1-2√3<-2 순서를 확인한다.","확인":null,"스킬":"N6"},{"제목":"양수 두 값도 비교해 전체 순서 정하기","힌트":"3-√3과 2√2 중 어느 것이 더 클까?","식":["$1<\\sqrt{3}<2\\Rightarrow1<3-\\sqrt{3}<2$","$2<2\\sqrt{2}<3\\Rightarrow3-\\sqrt{3}<2\\sqrt{2}$"],"설명":"양수 두 값도 범위를 좁혀 비교하면 전체 순서는 -4√2<1-2√3<-2<3-√3<2√2이다.","확인":null,"스킬":"N6"},{"제목":"왼쪽에서 세 번째 값 찾기","힌트":"가장 작은 값부터 세 번째는?","식":[],"설명":"왼쪽에서 세 번째 값은 -2이며, 이는 ④의 계산 결과이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-cdf8a323c7b2":{"길":"식을 근호 하나로 정리한 뒤 ab=4를 대입해 양의 제곱근을 구한다","단계":[{"제목":"식을 하나의 근호로 정리하기","힌트":"a√(b/a)와 √b/(b√a)를 근호 하나로 합치면?","식":["$a\\sqrt{\\frac{b}{a}}-\\frac{\\sqrt{b}}{b\\sqrt{a}}=\\sqrt{ab}-\\sqrt{\\frac{1}{ab}}$"],"설명":"각 항을 근호 하나의 형태로 정리한다.","확인":null,"스킬":"N6"},{"제목":"ab=4 대입하기","고비":true,"힌트":"ab=4를 대입하면?","식":["$\\sqrt{4}-\\sqrt{\\frac{1}{4}}=2-\\frac{1}{2}=\\frac{3}{2}$"],"설명":"ab=4를 대입해 식의 값 3/2를 구한다.","확인":"3/2","스킬":"N6"},{"제목":"양의 제곱근 구하기","힌트":"3/2의 양의 제곱근은?","식":["$\\sqrt{\\frac{3}{2}}=\\frac{\\sqrt{6}}{2}$"],"설명":"3/2의 양의 제곱근을 구해 분모를 유리화한다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-cf5928e93b41":{"길":"비례식을 이차방정식으로 바꿔 근의 공식으로 (다)를 구한다","단계":[{"제목":"비례식을 이차방정식으로 바꾸기","힌트":"AB:AP=AP:BP에서 (x+1):x=x:1이면?","식":["$x^2=x+1$"],"설명":"비례식의 외항과 내항의 곱이 같다는 성질로 x²=x+1을 얻는다.","확인":null,"스킬":"A8"},{"제목":"이차방정식 정리하기","힌트":"우변을 좌변으로 이항하면?","식":["$x^2-x-1=0$"],"설명":"정리하면 이차방정식 x²-x-1=0이 세워진다.","확인":null,"스킬":"A6"},{"제목":"근의 공식으로 x 구하기","고비":true,"힌트":"근의 공식에 a=1, b=-1, c=-1을 대입하면?","식":["$x=\\frac{1\\pm\\sqrt{5}}{2}$"],"설명":"근의 공식을 이용하면 x=(1±√5)/2이다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-d316c7aaa08b":{"길":"두 해를 a, 3a로 놓고 계수 비교로 a를 구해 k값들의 합을 계산한다","단계":[{"제목":"두 해를 비례식으로 표현하기","힌트":"두 해의 비가 1:3이면 어떻게 놓을 수 있을까?","식":["$x=a,\\ 3a\\ (a\\ne0)$"],"설명":"두 해의 비가 1:3이므로 한 해를 a, 다른 해를 3a로 둔다.","확인":null,"스킬":"A8"},{"제목":"인수분해 형태로 방정식 쓰기","힌트":"두 해가 a, 3a인 이차방정식은?","식":["$(x-a)(x-3a)=0$","$x^2-4ax+3a^2=0$"],"설명":"두 해를 이용해 방정식을 전개하면 x²-4ax+3a²=0이다.","확인":null,"스킬":"A2"},{"제목":"계수 비교로 식 세우기","고비":true,"힌트":"원래 방정식과 계수를 비교하면?","식":["$k+3=4a,\\ 3k=3a^2$"],"설명":"원래 방정식과 계수를 비교하면 두 식을 얻는다.","확인":null,"스킬":"A3"},{"제목":"연립해 a 구하기","힌트":"4a-3=a²을 정리해 풀면?","식":["$a^2-4a+3=0$","$(a-1)(a-3)=0$"],"설명":"두 식을 연립해 정리하면 a=1 또는 a=3이다.","확인":null,"스킬":"N4"},{"제목":"k값들의 합 구하기","힌트":"a=1, a=3일 때 k는 각각?","식":["$a=1:\\ k=1,\\ a=3:\\ k=9$","$1+9=10$"],"설명":"각 a에 대응하는 k를 구해 더하면 10이다.","확인":"10","스킬":"A3"}],"fb":"fig/ns/"},"ns-d3f1216e7fbd":{"길":"부등식으로 x의 범위를 구한 뒤 무리수가 아닌 값만 제외해 개수를 센다","단계":[{"제목":"정수부분 조건을 부등식으로 세우기","힌트":"정수부분이 4이상 12이하라는 것을 부등식으로 쓰면?","식":["$4\\le\\sqrt{3x}<13$"],"설명":"정수부분 조건을 부등식으로 옮긴다.","확인":null,"스킬":"N7"},{"제목":"양변을 제곱해 x의 범위 구하기","힌트":"부등식의 각 변을 제곱하면?","식":["$16\\le3x<169$","$\\frac{16}{3}\\le x<\\frac{169}{3}$"],"설명":"양변을 제곱해 정리하면 x는 6부터 56까지의 자연수다.","확인":null,"스킬":"N7"},{"제목":"무리수가 아닌 x 제외하기","고비":true,"힌트":"√3x가 유리수가 되려면 3x는 어떤 수여야 할까?","식":["$x=3k^2\\ (k=1,2,3,4,\\ldots)$","$x=12,\\ 27,\\ 48$"],"설명":"3x가 완전제곱수가 되는 x=12, 27, 48은 √3x가 무리수가 아니므로 제외한다.","확인":null,"스킬":"N8"},{"제목":"개수 세기","힌트":"전체 51개에서 제외한 3개를 빼면?","식":["$56-6+1=51$","$51-3=48$"],"설명":"6부터 56까지 51개 중 무리수가 아닌 3개를 빼면 48개다.","확인":"48","스킬":"P4"}],"fb":"fig/ns/"},"ns-d49a6e229790":{"길":"두 다항식을 빼서 완전제곱식 조건을 세우고 두 자리 자연수 조건을 만족하는 순서쌍을 센다","단계":[{"제목":"두 다항식 빼서 정리하기","힌트":"x²+7ax-3b에서 ax-6b를 빼면?","식":["$x^2+7ax-3b-(ax-6b)=x^2+6ax+3b$"],"설명":"두 식을 빼면 x²+6ax+3b가 된다.","확인":null,"스킬":"A3"},{"제목":"완전제곱식 조건 세우기","고비":true,"힌트":"완전제곱식이 되려면 상수항은?","식":["$3b=\\left(\\frac{6a}{2}\\right)^2=9a^2$","$b=3a^2$"],"설명":"완전제곱식 조건에서 b=3a²을 얻는다.","확인":null,"스킬":"A6"},{"제목":"두 자리 자연수 조건으로 순서쌍 세기","힌트":"b=3a²가 두 자리 자연수가 되는 a는?","식":["$(2,12),(3,27),(4,48),(5,75)$"],"설명":"조건을 만족하는 a는 2,3,4,5이므로 순서쌍은 4개이다.","확인":"4","스킬":"P4"}],"fb":"fig/ns/"},"ns-d59866ef0d1f":{"길":"상수를 더해 좌변을 인수분해가 되는 꼴로 만든 뒤 곱셈 공식으로 두 수를 찾는다","단계":[{"제목":"양변에 상수 더해 인수분해 준비하기","힌트":"ab+3a+5b에 15를 더하면 인수분해가 될까?","식":["$ab+3a+5b+15=76+15=91$"],"설명":"양변에 15를 더하면 좌변이 두 일차식의 곱으로 묶인다.","확인":null,"스킬":"A1"},{"제목":"인수분해하기","고비":true,"힌트":"a(b+3)+5(b+3)을 묶으면?","식":["$(a+5)(b+3)=91$"],"설명":"공통인수로 묶으면 (a+5)(b+3)=91이다.","확인":null,"스킬":"A1"},{"제목":"91을 곱으로 나눠 a,b 구하기","힌트":"91=7×13이고 a>b이면 a+5, b+3은 각각?","식":["$a+5=13,\\ b+3=7$","$a=8,\\ b=4$"],"설명":"a>b 조건에 맞게 배정하면 a=8, b=4이다.","확인":null,"스킬":"N4"},{"제목":"2a-3b 계산하기","힌트":"a=8,b=4를 대입하면?","식":["$2a-3b=16-12=4$"],"설명":"값을 대입하면 4이다.","확인":"4","스킬":"A2"}],"fb":"fig/ns/"},"ns-da70fe1f4af1":{"길":"a를 계수로 둔 채 완전제곱으로 정리해 최솟값 조건과 a의 범위를 함께 살펴 a를 구한다","단계":[{"제목":"완전제곱으로 정리하기","힌트":"(a-1)을 묶어 완전제곱 꼴로 만들면?","식":["$y=(a-1)x^2-2(1-a)x+a^2-3a$","$=(a-1)(x+1)^2+a^2-4a+1$"],"설명":"이차항 계수 (a-1)을 묶어 완전제곱 꼴로 정리하면 최솟값은 a²-4a+1이다.","확인":null,"스킬":"A6"},{"제목":"최솟값을 갖는 조건과 방정식 세우기","고비":true,"힌트":"최솟값이 존재하려면 a-1의 부호는? 최솟값이 -2라면?","식":["$a-1>0\\Rightarrow a>1$","$a^2-4a+1=-2$"],"설명":"최솟값을 가지려면 아래로 볼록해야 하므로 a>1이고, 최솟값이 -2라는 조건을 식으로 세운다.","확인":null,"스킬":"C1"},{"제목":"방정식을 풀어 a 정하기","힌트":"a²-4a+3=0을 인수분해하면?","식":["$(a-1)(a-3)=0$","$a=3\\ (\\because a>1)$"],"설명":"인수분해하면 a=1 또는 a=3인데 a>1이므로 a=3이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-db7e986643c7":{"길":"도수분포표에서 평균·최빈값·중앙값을 차례로 계산해 선지를 확인한다","단계":[{"제목":"12반의 평균 구하기","힌트":"도수분포표에서 (변량×도수)의 합을 학생 수로 나누면?","식":["$\\frac{0\\times2+1\\times4+2\\times3+3\\times3+4\\times0+5\\times1+6\\times2}{15}=2.4$"],"설명":"12반 학생들이 구입한 아이스크림 개수의 평균은 2.4개이다.","확인":null,"스킬":"P4"},{"제목":"13반의 평균 구해 비교하기","힌트":"같은 방법으로 13반의 평균을 구하면?","식":["$\\frac{0\\times2+1\\times4+2\\times6+3\\times4+4\\times2+5\\times1+6\\times1}{20}=2.35$"],"설명":"13반의 평균은 2.35개로 12반보다 작으므로, 12반이 13반보다 적다는 ①은 옳지 않다.","확인":null,"스킬":"P4"},{"제목":"12반의 최빈값 확인하기","힌트":"12반에서 도수가 가장 큰 개수는?","식":["최빈값 $=1$"],"설명":"12반의 최빈값은 도수가 가장 큰 1개이므로, 최빈값이 2라는 ②는 옳지 않다.","확인":null,"스킬":"P4","고비":true},{"제목":"12반의 중앙값 구해 답 정하기","힌트":"15명 중 8번째 값은 몇 개일까?","식":["중앙값 $=2$"],"설명":"작은 값부터 나열했을 때 8번째에 오는 값이 2개이므로 12반의 중앙값은 2개이고, 이를 설명한 ③이 옳다.","확인":"2","스킬":"P4"}],"fb":"fig/ns/"},"ns-ddd56b9d16d3":{"길":"다섯 선지를 평균·중앙값·산포도 성질로 하나씩 따져 옳고 그름을 가린다","단계":[{"제목":"A, B의 평균 구하기","힌트":"A와 B의 6회 점수를 각각 더해 6으로 나누면?","식":["$\\frac{80+75+70+75+80+70}{6}=75$","$\\frac{60+59+61+60+63+57}{6}=60$"],"설명":"A의 평균은 75점, B의 평균은 60점이므로 ①, ②는 옳다.","확인":null,"스킬":"C3"},{"제목":"C의 평균과 중앙값 비교하기","힌트":"C의 점수를 크기순으로 늘어놓고 평균, 중앙값을 각각 구하면?","식":["$\\frac{55+60+65+70+75+80}{6}=67.5$","$\\frac{65+70}{2}=67.5$"],"설명":"C의 평균과 중앙값이 모두 67.5점으로 같아 ③은 옳다.","확인":null,"스킬":"C3"},{"제목":"B의 산포도 판단하기","힌트":"B의 점수가 평균 주위에 가장 모여 있는가?","식":[],"설명":"B의 점수가 평균을 중심으로 가장 좁게 모여 있으므로 표준편차가 가장 작아 ④는 옳다.","확인":null,"스킬":"C3"},{"제목":"최빈값 있는지 확인하기","고비":true,"힌트":"B의 점수 중 두 번 나온 값이 있는가?","식":["$60$"],"설명":"B에서 60점이 두 번 나타나 최빈값 60점을 가지므로 '모두 최빈값을 갖지 않는다'는 ⑤는 옳지 않다.","확인":"60","스킬":"C3"}],"fb":"fig/ns/"},"ns-dff0206524fc":{"길":"네 각의 크기를 비교해 cos 값이 작은 순서로 나열한다","단계":[{"제목":"cos의 증감 성질 확인하기","힌트":"0°~90° 범위에서 각이 커지면 cos는 어떻게 변할까?","식":[],"설명":"각의 크기가 커질수록 cos 값은 작아진다.","확인":null,"스킬":"T5"},{"제목":"네 각의 크기 비교로 순서 정하기","고비":true,"힌트":"5°, 30°, 43°, 77°를 큰 순서로 늘어놓으면?","식":["$77^{\\circ}>43^{\\circ}>30^{\\circ}>5^{\\circ}$"],"설명":"각이 클수록 cos는 작으므로 값이 작은 것부터 (ㄷ)-(ㄹ)-(ㄱ)-(ㄴ) 순이다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-e07a8a34375b":{"길":"19명 중앙값의 위치를 찾고, 최빈값 조건으로 y의 범위를 좁혀 x, y를 정한다","단계":[{"제목":"중앙값 위치 정하기","힌트":"19명이면 중앙값은 몇 번째 값일까?","식":["$10+y$"],"설명":"자료를 작은 값부터 나열했을 때 10번째 오는 값이 중앙값이므로 10+y이다.","확인":null,"스킬":"P4"},{"제목":"y의 범위 정하기","고비":true,"힌트":"중앙값 10+y가 줄기 1의 잎 범위 안에 있으려면 y는?","식":["$12\\le10+y\\le16$","$2\\le y\\le6$"],"설명":"줄기 1의 잎 범위 안에 있어야 하므로 y는 2 이상 6 이하다.","확인":null,"스킬":"C2"},{"제목":"최빈값·중앙값 조건으로 x, y 정하기","힌트":"중앙값이 최빈값보다 4 크다는 조건을 만족하는 값은?","식":["$최빈값=12,\\ 중앙값=16$"],"설명":"최빈값이 12, 중앙값이 16일 때 조건이 맞으므로 x=2, y=6이다.","확인":null,"스킬":"C2"},{"제목":"x+y 계산하기","힌트":"x와 y를 더하면?","식":["$x+y=2+6=8$"],"설명":"x+y=8이다.","확인":"8","스킬":"C2"}],"fb":"fig/ns/"},"ns-e1dca5228c8e":{"길":"주어진 세 조건으로 a, b, c의 부호를 정한 뒤 절댓값을 풀어 정리한다","단계":[{"제목":"㉠, ㉡에서 a, c의 부호 정하기","힌트":"b<c<a와 c(b-a)<0을 같이 보면 c의 부호는?","식":["$c(b-a)<0,\\ b-a<0\\Rightarrow c>0$"],"설명":"b<c<a에서 b-a<0이므로 c(b-a)<0이 성립하려면 c>0이고, c<a이므로 a>0이다.","확인":null,"스킬":"C2"},{"제목":"㉢에서 b의 부호 정하기","고비":true,"힌트":"ac+b=0이고 a,c가 양수라면 b는?","식":["$ac=-b,\\ ac>0\\Rightarrow b<0$"],"설명":"a, c가 모두 양수이므로 ac>0이고, ac=-b이므로 b<0이다.","확인":null,"스킬":"C2"},{"제목":"절댓값 기호 벗기기","힌트":"c-a, b, c-b의 부호를 각각 정하면?","식":["$c-a<0,\\ b<0,\\ c-b>0$"],"설명":"b<c<a이므로 c-a<0, c-b>0이고, ㉢에서 b<0이다.","확인":null,"스킬":"C2"},{"제목":"식 정리하기","힌트":"√((c-a)²)=-(c-a), √(b²)=-b, √((c-b)²)=c-b를 대입하면?","식":["$(-c+a)+(-b)-(c-b)=a-2c$"],"설명":"각 절댓값을 부호에 맞게 풀어 정리하면 a-2c다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-e3b68c4f308e":{"길":"분모를 유리화해 유리수 조건으로 식을 세우고 연립방정식을 푼다","단계":[{"제목":"분모를 유리화해 식 정리하기","힌트":"두 분수를 통분해 유리화하면?","식":["$\\frac{(x-\\sqrt5)(\\sqrt5-1)+(y-\\sqrt5)(\\sqrt5+1)}{4}$"],"설명":"분모를 유리화하며 통분한다.","확인":null,"스킬":"A10"},{"제목":"유리수 조건으로 x+y=0 찾기","고비":true,"힌트":"√5가 포함된 항이 없어지려면 x+y는?","식":["$\\frac{-x+y-10+\\sqrt5(x+y)}{4},\\ x+y=0$"],"설명":"값이 유리수가 되려면 √5의 계수가 0이어야 하므로 x+y=0이다.","확인":null,"스킬":"A3"},{"제목":"연립방정식 풀기","힌트":"x+y=0과 x+2y=6을 연립하면?","식":["$x=-6,\\ y=6$"],"설명":"두 식을 연립해서 풀면 x=-6, y=6이다.","확인":null,"스킬":"A10"},{"제목":"y-x 계산하기","힌트":"y에서 x를 빼면?","식":["$y-x=6-(-6)=12$"],"설명":"y-x를 계산하면 12다.","확인":"12","스킬":"N6"}],"fb":"fig/ns/"},"ns-e81670529c66":{"길":"다섯 식을 각각 전개한 뒤 전개 결과가 같은 두 식을 짝짓는다","단계":[{"제목":"(ㄱ), (ㄴ), (ㄷ) 전개하기","고비":true,"힌트":"(ㄴ) 은 −1 을 묶어 (a−b)² 꼴로 보면?","식":["(ㄱ) $(a+b)(a-b)=a^2-b^2$","(ㄴ) $(-a+b)(a-b)=-(a-b)^2=-a^2+2ab-b^2$","(ㄷ) $(-a+b)(-a-b)=a^2-b^2$"],"설명":"(ㄱ) 은 합차 공식이다. (ㄴ) 은 앞 괄호에서 $-1$ 을 묶으면 $-(a-b)^2$ 이 된다. (ㄷ) 은 $-a$ 와 $b$ 를 합차 꼴로 보면 $(-a)^2-b^2=a^2-b^2$ 이다.","확인":null,"스킬":"A3"},{"제목":"(ㄹ), (ㅁ) 전개하기","힌트":"(ㅁ) 은 (a+b)² 을 먼저 전개한 뒤 부호를 붙이면?","식":["(ㄹ) $(a-b)(-a-b)=-(a-b)(a+b)=-a^2+b^2$","(ㅁ) $-(a+b)^2=-a^2-2ab-b^2$"],"설명":"(ㄹ) 은 뒤 괄호에서 $-1$ 을 묶어 합차 공식으로 전개한다. (ㅁ) 은 $(a+b)^2$ 을 전개한 식 전체에 마이너스를 붙인다.","확인":null,"스킬":"A3"},{"제목":"전개식이 같은 짝 찾기","힌트":"다섯 전개 결과 중 같은 꼴 두 개는?","식":["(ㄱ), (ㄷ) 의 전개식 $=a^2-b^2$"],"설명":"(ㄴ), (ㄹ), (ㅁ) 의 전개식은 서로 다르고, (ㄱ) 과 (ㄷ) 만 $a^2-b^2$ 으로 같다. 따라서 답은 ②이다.","확인":null,"스킬":"A3"}]},"ns-efab77072c5a":{"길":"연속한 홀수의 합 공식으로 근호 안을 제곱수로 바꿔 계산한다","단계":[{"제목":"규칙을 합의 공식으로 보기","힌트":"1+3+5+...+(2n-1)의 합은?","식":["$1+3+5+\\cdots+(2n-1)=n^2$"],"설명":"연속한 홀수의 합은 제곱수가 되는 규칙이다.","확인":null,"스킬":"P1"},{"제목":"마지막 항으로 n 구하기","고비":true,"힌트":"마지막 항이 49라면 n은?","식":["$2n-1=49\\Rightarrow n=25$"],"설명":"1부터 49까지의 홀수는 25개이므로 합은 25²이다.","확인":null,"스킬":"P1"},{"제목":"제곱근 계산하기","힌트":"√(25²)의 값은?","식":["$\\sqrt{25^2}=25$"],"설명":"25²의 제곱근은 25다.","확인":"25","스킬":"N8"}],"fb":"fig/ns/"},"ns-f2842b973556":{"길":"4-√3의 정수부분과 소수부분을 구해 식에 대입하고 유리화한다","단계":[{"제목":"4-√3의 정수부분, 소수부분 구하기","힌트":"1<√3<2이면 4-√3의 범위는?","식":["$1<\\sqrt3<2\\Rightarrow2<4-\\sqrt3<3$"],"설명":"√3의 범위로 4-√3의 범위를 구하면 정수부분은 2다.","확인":null,"스킬":"N7"},{"제목":"소수부분 b 구하기","고비":true,"힌트":"4-√3에서 정수부분 2를 빼면?","식":["$a=2,\\ b=(4-\\sqrt3)-2=2-\\sqrt3$"],"설명":"소수부분은 (4-√3)에서 정수부분을 뺀 2-√3이다.","확인":null,"스킬":"N7"},{"제목":"식에 대입해 유리화하기","힌트":"b/(√3a)에 대입하고 분모를 유리화하면?","식":["$\\frac{2-\\sqrt3}{2\\sqrt3}=\\frac{(2-\\sqrt3)\\sqrt3}{2\\sqrt3\\times\\sqrt3}=\\frac{2\\sqrt3-3}{6}$"],"설명":"분모를 유리화해서 정리하면 (2√3-3)/6이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-f421854f7184":{"길":"이차방정식의 근의 공식을 유도하는 과정을 따라가며 빈칸을 채운다","단계":[{"제목":"㉮, ㉯ 빈칸 채우기","힌트":"양변을 a로 나누고 완전제곱을 만들려면 더할 수는?","식":["$㉮=\\frac{c}{a}$","$㉯=\\left(\\frac{b}{2a}\\right)^2$"],"설명":"상수항을 이항하고 완전제곱식을 만들기 위해 더하는 항은 (b/2a)²이다.","확인":null,"스킬":"A6"},{"제목":"㉰, ㉱ 빈칸 채우기","고비":true,"힌트":"좌변을 완전제곱으로 정리하면 우변의 분모, 분자는?","식":["$㉰=4a^2$","$㉱=\\pm\\sqrt{b^2-4ac}$"],"설명":"좌변을 정리하면 우변의 분모는 4a², 분자는 ±√(b²-4ac)이다.","확인":null,"스킬":"A6"},{"제목":"옳지 않은 것 찾기","힌트":"㉯의 실제 값과 선지에 적힌 값을 비교하면?","식":["$㉯의\\ 실제값=\\left(\\frac{b}{2a}\\right)^2\\ne\\frac{b}{2a}$"],"설명":"㉯는 (b/2a)²인데 선지는 b/2a로 되어 있어 옳지 않다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-f4bc9a4dcfd6":{"길":"텔레스코핑으로 t를 구한 뒤 완전제곱 꼴로 정리해 값을 계산한다","단계":[{"제목":"분모 유리화해 한 항씩 정리하기","힌트":"1/(1+√2)를 유리화하면?","식":["$\\frac{1}{1+\\sqrt2}=\\frac{\\sqrt2-1}{(\\sqrt2+1)(\\sqrt2-1)}=\\sqrt2-1$"],"설명":"각 항의 분모를 유리화하면 인접한 두 제곱근의 차가 된다.","확인":null,"스킬":"N6"},{"제목":"소거해서 t 구하기","고비":true,"힌트":"유리화한 항을 모두 더하면 중간 항들이 어떻게 될까?","식":["$t=(\\sqrt2-1)+(\\sqrt3-\\sqrt2)+\\cdots+(\\sqrt{80}-\\sqrt{79})=\\sqrt{80}-1$"],"설명":"이웃한 항끼리 소거되어 t=√80-1만 남는다.","확인":null,"스킬":"P6"},{"제목":"식을 완전제곱 꼴로 보기","힌트":"(t-2)²+6(t-2)+9는 어떤 식의 완전제곱일까?","식":["$(t-2)^2+6(t-2)+9=\\{(t-2)+3\\}^2=(t+1)^2$"],"설명":"A=t-2로 보면 A²+6A+9=(A+3)²이므로 (t+1)²이 된다.","확인":null,"스킬":"A6"},{"제목":"값 대입해 계산하기","힌트":"t+1=√80이므로 √((t+1)²)은?","식":["$\\sqrt{(t+1)^2}=\\sqrt{(\\sqrt{80})^2}=\\sqrt{80}=4\\sqrt5$"],"설명":"t+1=√80을 대입하면 값은 4√5다.","확인":null,"스킬":"N8"}],"fb":"fig/ns/"},"ns-f6200a94610b":{"길":"구간에 따른 부호를 정해 절댓값을 풀고 두 식의 크기를 비교한다","단계":[{"제목":"①~③ 선지 부호 판별하기","힌트":"-1<x<y<0에서 x-2, -y, y-2의 부호는?","식":["$x-2<0,\\ -y>0,\\ y-2<0$"],"설명":"각 식의 부호를 확인해 절댓값을 풀면 ①은 x-2, ②는 y, ③은 y-2로 모두 음수다.","확인":null,"스킬":"C2"},{"제목":"④, ⑤ 선지 부호 판별하고 크기 비교하기","고비":true,"힌트":"2-x와 2+y는 각각 양수일까?","식":["$2-x>0\\Rightarrow\\sqrt{(2-x)^2}=2-x$","$1<2+y<2\\Rightarrow\\sqrt{(2+y)^2}=2+y$"],"설명":"④는 2-x, ⑤는 2+y로 둘 다 양수이며 비교 대상이 된다.","확인":null,"스킬":"C2"},{"제목":"가장 큰 값 고르기","힌트":"2-x와 2+y 중 어느 것이 더 클까?","식":["$x<y\\Rightarrow-x>-y\\Rightarrow2-x>2+y$"],"설명":"x<y이므로 -x>-y이고, 따라서 2-x가 2+y보다 커서 가장 큰 값은 2-x다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-fcadf21cc04b":{"길":"이미 두 번씩 나온 4와 9를 최빈값 후보로 경우를 나눠 중앙값과 비교한다","단계":[{"제목":"최빈값 후보 찾기","힌트":"4와 9는 이미 몇 번씩 나오는가?","식":["$4,\\ 9$"],"설명":"자료에 4와 9가 이미 두 번씩 나오므로 최빈값은 a에 따라 4 또는 9가 된다.","확인":null,"스킬":"C2"},{"제목":"a=4인 경우 확인하기","고비":true,"힌트":"a=4이면 최빈값은 4, 중앙값은?","식":["$2,3,4,4,4,7,9,9$","$\\frac{4+4}{2}=4$"],"설명":"a=4이면 최빈값과 중앙값이 모두 4로 같다.","확인":null,"스킬":"C2"},{"제목":"a=9인 경우 확인하기","힌트":"a=9이면 최빈값은 9, 중앙값은?","식":["$2,3,4,4,7,9,9,9$","$\\frac{4+7}{2}=5.5$"],"설명":"a=9이면 최빈값은 9이지만 중앙값은 5.5로 서로 다르다.","확인":null,"스킬":"C2"},{"제목":"조건에 맞는 a 정하기","힌트":"두 경우 중 중앙값과 최빈값이 같은 것은?","식":["$a=4$"],"설명":"중앙값과 최빈값이 같은 경우는 a=4뿐이다.","확인":"4","스킬":"C2"}],"fb":"fig/ns/"},"ns-fcbfc2301c22":{"길":"두 근호식을 A,B로 놓고 곱셈공식으로 값을 구한다","단계":[{"제목":"A,B로 치환해 곱셈공식 적용하기","힌트":"A+B와 A-B의 곱은 A²-B²와 같다","식":["$(\\sqrt{a+2}+\\sqrt{a-2})(\\sqrt{a+2}-\\sqrt{a-2})=(a+2)-(a-2)=4$"],"설명":"두 식의 곱은 4이다.","확인":null,"스킬":"A1"},{"제목":"값 나누어 구하기","고비":true,"힌트":"곱이 4이고 한 인수가 1/2이면 다른 인수는?","식":["$(\\sqrt{a+2}+\\sqrt{a-2})\\times\\frac{1}{2}=4$","$\\sqrt{a+2}+\\sqrt{a-2}=8$"],"설명":"주어진 값 1/2로 나누면 구하는 값은 8이다.","확인":"8","스킬":"A1"}],"fb":"fig/ns/"},"ns-fdba6db1c695":{"길":"인수분해 꼴 (x+a)(x-b) 의 두 수 관계식을 세우고 k 가 30 이하인 경우를 나열해 센다","단계":[{"제목":"인수분해 조건 세우기","힌트":"x²+x−k=(x+a)(x−b) 로 놓으면 a, b 의 관계는?","식":["$a-b=1,\\ ab=k$"],"설명":"$(x+a)(x-b)$ 를 전개해 $x^2+x-k$ 와 계수를 비교하면 $a-b=1$, $ab=k$ 이다.","확인":null,"스킬":"A3"},{"제목":"a, b 값 늘려가며 k 나열하기","고비":true,"힌트":"a=2, 3, 4, 5, 6 일 때 k=ab 는?","식":["$a=2,b=1:k=2$","$a=3,b=2:k=6$","$a=4,b=3:k=12$","$a=5,b=4:k=20$","$a=6,b=5:k=30$"],"설명":"$a-b=1$ 을 유지하며 $k\\le30$ 인 경우를 모두 나열한다. $a=7$ 이면 $k=42$ 로 30 을 넘는다.","확인":null,"스킬":"P4"},{"제목":"개수 세기","힌트":"나열한 k 의 개수는?","식":["$k=2,6,12,20,30$ 의 개수 $=5$"],"설명":"나열한 $k$ 는 모두 5개이므로 인수분해되는 이차식은 5개이다.","확인":"5","스킬":"P4"}]},"ns-fdd7b6481398":{"길":"네 보기를 (x+a)²=b의 성질로 하나씩 판별한다","단계":[{"제목":"㉠, ㉡ 판별하기","힌트":"b<0이면 (x+a)²=b를 만족하는 실수 x가 있을까? b=0이면?","식":["$b<0\\ \\Rightarrow\\ 근\\ 없음$","$b=0\\ \\Rightarrow\\ x=-a\\ (중근)$"],"설명":"b<0이면 (x+a)²≥0이므로 근이 없어 ㉠은 옳고, b=0이면 중근을 가지므로 ㉡도 옳다.","확인":null,"스킬":"C3"},{"제목":"㉢ 판별하기","고비":true,"힌트":"b>0이면 두 근은 -a±√b인데 절댓값이 항상 같을까?","식":["$x=-a\\pm\\sqrt{b}$"],"설명":"a≠0이면 두 근 -a+√b, -a-√b의 절댓값이 다를 수 있으므로 ㉢은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"㉣ 판별하기","힌트":"ab>0이면 a와 b가 모두 음수인 경우도 있을까?","식":[],"설명":"ab>0이려면 a<0, b<0일 수도 있는데 이때는 근 자체가 없으므로 ㉣은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"옳은 보기 확정하기","힌트":"지금까지 확인한 결과 옳은 것은?","식":[],"설명":"옳은 것은 ㉠, ㉡이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-fdf692236514":{"길":"식을 인수분해한 뒤, 소수가 되려면 한 인수가 ±1이어야 함을 이용해 경우를 나눠 확인한다","단계":[{"제목":"식 인수분해하기","힌트":"n²+8n-48을 인수분해하면?","식":["$n^2+8n-48=(n+12)(n-4)$"],"설명":"두 일차식의 곱으로 인수분해한다.","확인":null,"스킬":"A6"},{"제목":"소수가 되는 조건 세우기","고비":true,"힌트":"두 정수의 곱이 소수이려면 한 인수는 ±1이어야 하지 않을까?","식":[],"설명":"곱이 소수가 되려면 두 인수 중 하나가 ±1이어야 한다.","확인":null,"스킬":"C2"},{"제목":"네 경우 확인하기","힌트":"n+12=±1, n-4=±1일 때 각각 값은?","식":["$n=-11:(1)(-15)=-15$","$n=-13:(-1)(-17)=17$","$n=5:(17)(1)=17$","$n=3:(15)(-1)=-15$"],"설명":"네 경우를 확인하면 n=-13, 5일 때만 소수 17이 된다.","확인":null,"스킬":"C2"},{"제목":"개수 세기","힌트":"조건을 만족하는 n의 개수는?","식":["$2개$"],"설명":"조건을 만족하는 정수 n은 -13, 5의 2개이다.","확인":"2","스킬":"C2"}],"fb":"fig/ns/"},"ns-fe00d717f305":{"길":"모든 항을 2의 거듭제곱으로 통일한 뒤, 공통인수를 묶어 인수분해로 약분한다","단계":[{"제목":"밑을 2로 통일하기","힌트":"8,4,16을 2의 거듭제곱으로 바꾸면?","식":["$\\sqrt{\\frac{(2^3)^8\\times2^2-(2^2)^{10}}{(2^2)^{12}\\times2^3-(2^4)^6}}$"],"설명":"모든 항을 2의 거듭제곱으로 바꾼다.","확인":null,"스킬":"A9"},{"제목":"지수 정리하기","힌트":"각 항의 지수를 계산하면?","식":["$\\sqrt{\\frac{2^{26}-2^{20}}{2^{27}-2^{24}}}$"],"설명":"지수를 계산해 정리한다.","확인":null,"스킬":"A9"},{"제목":"공통인수 묶어 인수분해하기","고비":true,"힌트":"분자, 분모에서 공통으로 묶이는 것은?","식":["$\\sqrt{\\frac{2^{20}(2^3+1)(2^3-1)}{2^{24}(2^3-1)}}$"],"설명":"2⁶-1을 합차공식으로 인수분해하면 (2³-1)이 약분된다.","확인":null,"스킬":"A1"},{"제목":"약분해 값 구하기","힌트":"남은 식을 정리하면?","식":["$\\sqrt{\\frac{2^3+1}{2^4}}=\\sqrt{\\frac{9}{16}}=\\frac{3}{4}$"],"설명":"약분하면 값은 3/4이다.","확인":"3/4","스킬":"N6"}],"fb":"fig/ns/"},"ns-fe2939530db0":{"길":"a, p, q의 부호로 오목한 방향과 꼭짓점의 사분면을 정해 지나는 사분면을 판단한다","단계":[{"제목":"그래프의 오목한 방향 정하기","힌트":"a<0이면 그래프는?","식":[],"설명":"a<0이므로 y=a(x-p)²+q의 그래프는 위로 볼록하다.","확인":null,"스킬":"G4"},{"제목":"꼭짓점의 사분면 정하기","힌트":"p>0, q<0이면 꼭짓점 (p,q)는?","식":["$(p,\\,q)$"],"설명":"p>0, q<0이므로 꼭짓점 (p,q)는 제4사분면 위에 있다.","확인":null,"스킬":"G4"},{"제목":"지나는 사분면 정하기","고비":true,"힌트":"위로 볼록하고 꼭짓점이 제4사분면이면 그래프는 어느 사분면들을 지날까?","식":[],"설명":"위로 볼록하고 꼭짓점이 제4사분면에 있으므로 그래프는 제3, 4사분면만을 지난다.","확인":null,"스킬":"G4"}],"fb":"fig/ns/"},"ns-ff317992364f":{"길":"식을 곱의 꼴로 인수분해해 51의 약수 쌍으로 경우를 나눠 x,y를 구한다","단계":[{"제목":"식 정리해 인수분해하기","힌트":"4x²-y²=51을 인수분해하면?","식":["$(2x+y)(2x-y)=51$"],"설명":"좌변을 합차공식으로 인수분해한다.","확인":null,"스킬":"N4"},{"제목":"51의 약수 쌍으로 경우 나누기","고비":true,"힌트":"51=51×1=17×3 중 2x+y>2x-y>0을 만족하는 것은?","식":["$2x+y=51,2x-y=1:x=13,y=25$","$2x+y=17,2x-y=3:x=5,y=7$"],"설명":"두 경우 모두 x,y가 자연수로 나온다.","확인":null,"스킬":"N4"},{"제목":"y값의 합 구하기","힌트":"25와 7을 더하면?","식":["$25+7=32$"],"설명":"y값의 합은 32이다.","확인":"32","스킬":"P4"}],"fb":"fig/ns/"},"ns-ffcd29112479":{"길":"근을 m에 관한 식으로 구한 뒤 다섯 선지를 하나씩 대입해 확인한다","단계":[{"제목":"근을 m에 관한 식으로 구하기","힌트":"(x+3)²=1+m에서 x를 m으로 나타내면?","식":["$x=-3\\pm\\sqrt{1+m}$"],"설명":"양변에 제곱근을 취해 두 근을 m에 관한 식으로 나타낸다.","확인":null,"스킬":"A6"},{"제목":"①, ② 선지 확인하기","힌트":"두 근의 합과 m=-1일 때의 근은?","식":["$(-3+\\sqrt{1+m})+(-3-\\sqrt{1+m})=-6$"],"설명":"두 근의 합은 항상 -6이므로 ①은 옳지 않고, m=-1이면 x=-3인 중근이므로 ②는 옳다.","확인":null,"스킬":"A2"},{"제목":"③, ④ 선지 확인하기","힌트":"m=3, m=1일 때 근을 각각 구하면?","식":["$m=3:\\ x=-1,-5$","$m=1:\\ x=-3\\pm\\sqrt2$"],"설명":"m=3이면 두 근이 모두 음수이므로 ③은 옳고, m=1이면 서로 다른 두 근이 나오므로 ④도 옳다.","확인":null,"스킬":"N6"},{"제목":"⑤ 선지 확인해 답 정하기","고비":true,"힌트":"m=-3/4일 때 근호 안의 값은 유리수의 제곱일까?","식":["$x=-3\\pm\\sqrt{\\frac{1}{4}}=-\\frac{5}{2},-\\frac{7}{2}$"],"설명":"근호 안이 완전제곱이 되어 유리수인 근을 가지므로 ⑤도 옳다. 따라서 옳지 않은 것은 ①이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-016311d2bbaf":{"길":"길이가 같은 두 현은 중심에서 같은 거리에 있다는 원의 성질을 적용한다","단계":[{"제목":"현의 길이와 중심거리 관계 떠올리기","힌트":"길이가 같은 두 현은 중심에서 같은 거리에 있을까?","식":[],"설명":"원에서 길이가 같은 두 현은 중심으로부터 같은 거리에 있다.","확인":null,"스킬":"S5"},{"제목":"OM=ON 결론짓기","고비":true,"힌트":"AB=CD이므로 OM, ON은?","식":["$\\overline{AB}=\\overline{CD}\\Rightarrow\\overline{OM}=\\overline{ON}$"],"설명":"AB=CD이므로 두 현에서 중심까지의 거리 OM과 ON은 같다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-01fe417684a4":{"길":"직각삼각형 세 개에서 길이를 차례로 구한 뒤 삼각형 ABD의 넓이를 두 가지로 나타내 siny°를 구한다","단계":[{"제목":"AD, DC 구하기","힌트":"직각삼각형 ACD에서 AD=4, sinx=1/4이면 DC는?","식":["$\\overline{AD}=4,\\ \\overline{DC}=\\overline{BD}=1$"],"설명":"sinx°=DC/AD=1/4이므로 AD=4일 때 DC=1이고, BD=CD이므로 BD=1이다.","확인":null,"스킬":"S3"},{"제목":"AC의 길이 구하기","힌트":"직각삼각형 ACD에서 피타고라스 정리를 쓰면?","식":["$\\overline{AC}=\\sqrt{4^2-1^2}=\\sqrt{15}$"],"설명":"직각삼각형 ACD에서 AC를 구한다.","확인":null,"스킬":"S3"},{"제목":"AB의 길이 구하기","힌트":"BC=BD+DC이고 직각삼각형 ABC에서 AB는?","식":["$\\overline{BC}=2,\\ \\overline{AB}=\\sqrt{2^2+(\\sqrt{15})^2}=\\sqrt{19}$"],"설명":"BC=BD+DC=2이고 직각삼각형 ABC에서 피타고라스 정리로 AB를 구한다.","확인":null,"스킬":"S3"},{"제목":"삼각형 ABD의 넓이 구하기","힌트":"BD가 BC의 절반이므로 △ABD의 넓이는 △ABC의 몇 배일까?","식":["$\\triangle ABD=\\frac{1}{2}\\triangle ABC=\\frac{1}{2}\\times\\frac{1}{2}\\times2\\times\\sqrt{15}=\\frac{\\sqrt{15}}{2}$"],"설명":"BD=DC이므로 △ABD의 넓이는 △ABC 넓이의 절반이다.","확인":null,"스킬":"S12"},{"제목":"넓이를 AB, AD와 siny°로 나타내 비교하기","고비":true,"힌트":"두 변 AB, AD와 그 끼인각 y°로 넓이를 쓰면?","식":["$\\frac{\\sqrt{15}}{2}=\\frac{1}{2}\\times\\sqrt{19}\\times4\\times\\sin y^\\circ$","$\\sin y^\\circ=\\frac{\\sqrt{15}}{4\\sqrt{19}}=\\sqrt{\\frac{15}{304}}$"],"설명":"두 표현을 같게 놓고 siny°를 구하면 a=304, b=15이므로 a+b=319이다.","확인":"319","스킬":"S8"}],"fb":"fig/ns/"},"ns-03451ce2ec7c":{"길":"대각선 AC의 길이로 점 P의 좌표를 구하고 정수·소수부분으로 나눠 식에 대입한다","단계":[{"제목":"대각선 AC의 길이 구하기","힌트":"한 변이 1인 정사각형의 대각선은?","식":["$\\overline{AC}=\\sqrt{2}$"],"설명":"정사각형 ABCD의 대각선 길이는 √2이다.","확인":null,"스킬":"S3"},{"제목":"점 P의 좌표 구하기","힌트":"AP=AC이므로 점 P의 좌표 a는?","식":["$a=3-\\sqrt{2}$"],"설명":"점 A(3)에서 왼쪽으로 √2만큼 떨어진 점이 P이다.","확인":null,"스킬":"N7"},{"제목":"정수부분과 소수부분 나누기","고비":true,"힌트":"1<√2<2이므로 3-√2는 몇과 몇 사이일까?","식":["$1<3-\\sqrt{2}<2$"],"설명":"정수부분 x=1, 소수부분 y=3-√2-1=2-√2이다.","확인":null,"스킬":"N7"},{"제목":"식에 대입해 계산하기","힌트":"(y-1)/(x-2y)에 값을 넣으면?","식":["$\\frac{y-1}{x-2y}=\\frac{2-\\sqrt{2}-1}{1-2(2-\\sqrt{2})}=1+\\sqrt{2}$"],"설명":"대입해 정리하면 1+√2이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-03707f0e1f22":{"길":"둘레 조건으로 반지름을 구한 뒤 두 원의 넓이 차를 합차공식으로 계산한다","단계":[{"제목":"반지름을 a로 나타내기","힌트":"CD=a라 하면 큰 원의 반지름은?","식":["$\\overline{CD}=a,\\ 큰\\ 원의\\ 반지름=\\frac{a+1.2}{2}$"],"설명":"AC+BD=1.2를 이용해 큰 원의 반지름을 a로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"둘레 조건으로 a 구하기","고비":true,"힌트":"두 원의 둘레의 합이 10π라는 조건을 식으로 쓰면?","식":["$2\\pi\\times\\frac{a}{2}+2\\pi\\times\\frac{a+1.2}{2}=10\\pi$","$2a=8.8\\Rightarrow a=4.4$"],"설명":"둘레의 합 조건으로 방정식을 세워 a=4.4를 구한다.","확인":"4.4","스킬":"C7"},{"제목":"넓이 차 계산하기","힌트":"큰 원과 작은 원의 넓이 차를 인수분해로 계산하면?","식":["$\\pi\\times2.8^2-\\pi\\times2.2^2=\\pi(2.8+2.2)(2.8-2.2)=3\\pi$"],"설명":"합차공식으로 넓이 차를 계산하면 3π다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-08bfef992668":{"길":"원주각·접선과 현의 각·닮음 성질을 차례로 확인해 옳지 않은 것을 찾는다","단계":[{"제목":"① 판별하기","힌트":"반원에 대한 원주각은?","식":[],"설명":"BT가 지름이므로 반원에 대한 원주각 ∠PAT=90°이다. ①은 옳다.","확인":null,"스킬":"S5"},{"제목":"② 판별하기","힌트":"접선과 현이 이루는 각은 어떤 원주각과 같을까?","식":[],"설명":"접선과 그 접점을 지나는 현이 이루는 각은 그 각 내부의 호에 대한 원주각과 같으므로 ∠PTA=∠PBT이다. ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"③ 판별하기","힌트":"∠PAT=∠PTB=90°이고 공통인 각이 있다면?","식":[],"설명":"∠PAT=∠PTB=90°이고 ∠PTA=∠PBT이므로 AA닮음으로 △PAT∽△PTB이다. ③은 옳다.","확인":null,"스킬":"S1"},{"제목":"④ 판별하기","힌트":"접선과 할선의 관계(방멱)를 쓰면?","식":["$\\overline{PT}^2=\\overline{PA}\\times\\overline{PB}$"],"설명":"접선과 할선의 관계에 의해 PT²=PA×PB가 성립하므로 ④는 옳다.","확인":null,"스킬":"S5"},{"제목":"⑤ 판별하고 정답 정하기","고비":true,"힌트":"△PAT∽△PTB에서 대응변의 비를 올바르게 쓰면?","식":["$\\overline{BT}:\\overline{BP}=\\overline{TA}:\\overline{PT}$"],"설명":"닮음에서 대응변의 비는 BT:BP=TA:PT인데 선지는 순서가 바뀌어 있으므로 ⑤가 옳지 않다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-0aa2bc3cace9":{"길":"직각삼각형의 외접원 반지름을 구하고, 대변이 같은 사각형의 평행사변형·내접 조건을 확인한다","단계":[{"제목":"△OAH의 외접원 반지름 구하기","힌트":"직각삼각형 OAH에서 빗변 OA의 길이는?","식":["$\\overline{OA}=\\sqrt{2^2+6^2}=2\\sqrt{10}$"],"설명":"직각삼각형의 외접원은 빗변을 지름으로 하므로 외접원의 반지름은 OA의 절반인 √10이다. ①은 옳다.","확인":null,"스킬":"S7"},{"제목":"THOR의 대변으로 평행사변형 확인하기","힌트":"표시된 두 쌍의 변 길이가 같다면 □THOR은 어떤 사각형일까?","식":[],"설명":"두 쌍의 대변의 길이가 같으므로 □THOR은 평행사변형이다. ④는 옳다.","확인":null,"스킬":"C3"},{"제목":"각의 합으로 내접 여부 확인하기","고비":true,"힌트":"∠ORT+∠OHT가 180°인지 확인하면?","식":["$\\angle ORT+\\angle OHT=85^{\\circ}+85^{\\circ}=170^{\\circ}$"],"설명":"두 각의 합이 180°가 아니므로 네 점은 한 원 위에 있지 않고 대각의 합도 180°가 아니어서 ③, ⑤는 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-0b64233ee30f":{"길":"n²과 (n+1)² 사이의 무리수 개수 규칙으로 가~다를 확인하고, 라는 반례로 걸러낸다","단계":[{"제목":"가 판별하기","힌트":"n과 n+1 사이의 무리수 점의 개수는 2n개, 항상 짝수일까?","식":["$2n$"],"설명":"n과 n+1 사이의 무리수에 대응하는 점은 항상 2n개(짝수)이므로 가는 옳다.","확인":null,"스킬":"P1"},{"제목":"나 판별하기","힌트":"이 수직선 위의 점들은 모두 무엇의 제곱근일까?","식":[],"설명":"n과 n+1 사이의 점은 모두 제곱수가 아닌 자연수의 제곱근이므로 유리수인 점은 없다. 나는 옳다.","확인":null,"스킬":"N8"},{"제목":"다 판별하기","힌트":"2013과 2014 사이의 무리수 개수는 2×2013일까?","식":["$2\\times2013=4026$"],"설명":"가의 규칙을 그대로 적용하면 4026개이므로 다는 옳다.","확인":null,"스킬":"P1"},{"제목":"라 반례 찾기","고비":true,"힌트":"n=3이면 √(n²+1)의 정수부분과 1~n 사이 정수점의 개수가 같을까?","식":["$\\sqrt{3^{2}+1}=\\sqrt{10}$"],"설명":"n=3이면 정수부분은 3인데 1과 3 사이의 정수점은 1개뿐이라 같지 않으므로 라는 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"옳은 개수 세기","힌트":"가, 나, 다만 옳으므로 개수는?","식":["$3$개"],"설명":"옳은 것은 가, 나, 다 3개이다.","확인":"3","스킬":"P4"}],"fb":"fig/ns/"},"ns-0fe992946ad1":{"길":"기울기로 BD, CD를 b에 관한 식으로 나타내고 곱 조건으로 b를 구해 BC를 계산한다","단계":[{"제목":"a, b의 관계 정리하기","힌트":"9a²-4b²=0을 인수분해하면?","식":["$(3a+2b)(3a-2b)=0$","$a,\\ b>0\\Rightarrow a=\\frac23b$"],"설명":"인수분해하고 양수 조건을 적용하면 a=(2/3)b다.","확인":null,"스킬":"A6"},{"제목":"기울기로 BD, CD를 b로 나타내기","고비":true,"힌트":"직선 l의 기울기 a, 직선 m의 기울기 -b를 AD, BD, CD로 표현하면?","식":["$\\frac{3\\sqrt2}{q}=\\frac23b\\Rightarrow q=\\frac{9\\sqrt2}{2b}$","$\\frac{3\\sqrt2}{p}=b\\Rightarrow p=\\frac{3\\sqrt2}{b}$"],"설명":"기울기는 높이와 밑변의 비이므로 BD=p, CD=q를 b에 관한 식으로 나타낸다.","확인":null,"스킬":"G9"},{"제목":"BD×CD=1/2로 b 구하기","힌트":"pq=1/2를 대입해 정리하면?","식":["$\\frac{9\\sqrt2}{2b}\\times\\frac{3\\sqrt2}{b}=\\frac12\\Rightarrow b^2=54\\Rightarrow b=3\\sqrt6$"],"설명":"pq=1/2 조건을 대입해 b를 구한다.","확인":null,"스킬":"A10"},{"제목":"BC 길이 구하기","힌트":"구한 b로 p, q를 계산해 더하면?","식":["$p=\\frac{\\sqrt3}{3},\\ q=\\frac{\\sqrt3}{2}$","$\\overline{BC}=\\frac{\\sqrt3}{3}+\\frac{\\sqrt3}{2}=\\frac{5\\sqrt3}{6}$"],"설명":"p, q를 더해 BC의 길이를 구하면 5√3/6이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-10711049498e":{"길":"세 직각삼각형에서 길이를 구해 이등변삼각형 BDG를 만들고 수선을 내려 siny를 구한다","단계":[{"제목":"△DGH에서 GD, DH 구하기","힌트":"CD=GH=2이고 ∠DGH=60°이면 GD는?","식":["$\\overline{GD}=4,\\ \\overline{DH}=2\\sqrt3$"],"설명":"직각삼각형 DGH에서 대변과 각으로 GD, DH를 구한다.","확인":null,"스킬":"S3"},{"제목":"△BFG에서 FG, BG 구하기","힌트":"BF=2√3이고 ∠BGF=45°이면 FG, BG는?","식":["$\\overline{FG}=2\\sqrt3,\\ \\overline{BG}=2\\sqrt6$"],"설명":"직각삼각형 BFG에서 FG, BG를 구한다.","확인":null,"스킬":"S3"},{"제목":"△BCD에서 BD 구하기","힌트":"BC=2√3이면 피타고라스 정리로 BD는?","식":["$\\overline{BD}=\\sqrt{2^2+(2\\sqrt3)^2}=\\sqrt{16}=4$"],"설명":"직각삼각형 BCD에서 BD를 구한다.","확인":"4","스킬":"S3"},{"제목":"△BDG가 이등변삼각형임을 확인하기","힌트":"BD, DG, BG의 길이를 비교하면?","식":["$\\overline{BD}=\\overline{DG}=4,\\ \\overline{BG}=2\\sqrt6$"],"설명":"BD=DG=4이므로 삼각형 BDG는 이등변삼각형이다.","확인":null,"스킬":"S2"},{"제목":"수선을 내려 DI 구하기","고비":true,"힌트":"D에서 BG에 내린 수선의 발을 I라 하면 BI는?","식":["$\\overline{BI}=\\overline{GI}=\\sqrt6$","$\\overline{DI}=\\sqrt{4^2-(\\sqrt6)^2}=\\sqrt{10}$"],"설명":"이등변삼각형에서 꼭짓점에서 내린 수선은 밑변을 이등분하므로 BI=GI=√6이고, 피타고라스 정리로 DI를 구한다.","확인":null,"스킬":"S2"},{"제목":"sinx 구하기","힌트":"sinx는 DI/DG일까?","식":["$\\sin x=\\frac{\\overline{DI}}{\\overline{DG}}=\\frac{\\sqrt{10}}{4}$"],"설명":"직각삼각형에서 sinx=DI/DG이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-123ca9cc94ee":{"길":"접선과 현의 각, 지름의 원주각, 호의 비, 닮음을 차례로 이용해 네 보기를 판별한다","단계":[{"제목":"접선과 현이 이루는 각 찾기","힌트":"∠ATC는 접선 PT와 현 AT가 이루는 각이다. 이는 어떤 원주각과 같을까?","식":["$\\angle ABT=\\angle ATC=75^\\circ$"],"설명":"접선과 현이 이루는 각은 그 호에 대한 원주각과 같으므로 ∠ABT=75°이다.","확인":null,"스킬":"S5"},{"제목":"직각삼각형에서 ∠BAT 구하기","힌트":"AB가 지름이면 ∠ATB는 몇 도일까?","식":["$\\angle ATB=90^\\circ,\\ \\angle BAT=90^\\circ-75^\\circ=15^\\circ$"],"설명":"지름에 대한 원주각은 90°이므로 삼각형 ABT에서 ∠BAT=15°가 나온다. 따라서 ㉠은 옳다.","확인":null,"스킬":"S5"},{"제목":"호의 길이 비 구하기","힌트":"원주각의 크기와 호의 길이는 어떤 관계일까?","식":["$\\overset{\\frown}{BT}:\\overset{\\frown}{AT}=15^\\circ:75^\\circ=1:5$"],"설명":"원주각의 크기는 호의 길이에 비례하므로 두 호의 비는 1:5이다. 따라서 ㉣도 옳다.","확인":null,"스킬":"S5"},{"제목":"삼각형 APT에서 ∠APT 구하기","힌트":"삼각형 APT의 세 각의 합을 이용하면 ∠APT는?","식":["$\\angle APT+15^\\circ=75^\\circ$"],"설명":"정리하면 ∠APT=60°이므로, ㉡이 주장하는 65°는 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"닮음 삼각형 찾기","고비":true,"힌트":"△APT와 △TPB에서 공통인 각과 같은 각을 찾으면?","식":["$\\triangle APT\\sim\\triangle TPB\\ (AA\\ 닮음)$"],"설명":"∠P가 공통이고 ∠PAT=∠PTB이므로 두 삼각형은 닮음이다.","확인":null,"스킬":"S1"},{"제목":"비례식으로 결론 내리기","힌트":"닮음비에서 PT는 PA, PB와 어떤 관계일까?","식":["$\\overline{PA}:\\overline{PT}=\\overline{PT}:\\overline{PB}\\ \\Rightarrow\\ \\overline{PT}^2=\\overline{PA}\\cdot\\overline{PB}$"],"설명":"비례식을 정리하면 PT²=PA·PB이므로 ㉢도 옳다. 따라서 옳은 것은 ㉠, ㉢, ㉣이다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-157481866571":{"길":"중심에서 현에 내린 수선의 발을 잡아 피타고라스 정리를 두 번 적용한다","단계":[{"제목":"수선의 발 H 잡고 AH 구하기","힌트":"원의 중심에서 현에 내린 수선은 현을 어떻게 나눌까?","식":["$\\overline{AH}=\\frac{1}{2}\\overline{AB}=9$"],"설명":"O에서 AB에 내린 수선의 발을 H라 하면 수선은 현을 이등분하므로 AH=9이다.","확인":null,"스킬":"S2"},{"제목":"OH 구하기","힌트":"직각삼각형 OAH에서 피타고라스 정리를 쓰면?","식":["$\\overline{OH}=\\sqrt{11^2-9^2}=2\\sqrt{10}$"],"설명":"OA는 반지름 11이므로 피타고라스 정리로 OH를 구한다.","확인":null,"스킬":"S3"},{"제목":"CH 구하기","힌트":"AC=CD=DB이면 AC의 길이는 얼마일까?","식":["$\\overline{AC}=6,\\ \\overline{CH}=\\overline{AH}-\\overline{AC}=3$"],"설명":"AB를 세 등분한 AC=6이고, H가 AB의 중점이므로 CH=AH-AC=3이다.","확인":null,"스킬":"C7"},{"제목":"OC 구하기","고비":true,"힌트":"직각삼각형 OCH에서 다시 피타고라스 정리를 쓰면?","식":["$\\overline{OC}=\\sqrt{(2\\sqrt{10})^2+3^2}=\\sqrt{49}$"],"설명":"OH와 CH를 변으로 하는 직각삼각형에서 OC를 구하면 7이다.","확인":"7","스킬":"S3"}],"fb":"fig/ns/"},"ns-157eae40879e":{"길":"세 반의 평균, 분산, 표준편차를 각각 계산해 다섯 선지와 비교한다","단계":[{"제목":"A반 평균·분산 구하기","힌트":"도수를 이용해 A반의 평균과 분산을 구하면?","식":["$(A평균)=\\frac{3\\times2+4\\times2+5\\times2+6\\times2+7\\times2}{10}=5$","$(A분산)=\\frac{(-2)^2\\times2+(-1)^2\\times2+0^2\\times2+1^2\\times2+2^2\\times2}{10}=2$"],"설명":"A반의 평균은 5권, 분산은 2이다.","확인":null,"스킬":"P4"},{"제목":"B반 평균·분산 구하기","힌트":"B반도 같은 방법으로 구하면?","식":["$(B평균)=5$","$(B분산)=\\frac{(-2)^2\\times3+(-1)^2\\times1+0^2\\times2+1^2\\times1+2^2\\times3}{10}=2.6$"],"설명":"B반의 평균은 5권, 분산은 2.6이다.","확인":null,"스킬":"P4"},{"제목":"C반 평균·분산 구하고 비교하기","고비":true,"힌트":"C반의 분산까지 구해 세 반을 비교하면?","식":["$(C평균)=5$","$(C분산)=\\frac{(-2)^2\\times1+(-1)^2\\times2+0^2\\times4+1^2\\times2+2^2\\times1}{10}=1.2$"],"설명":"C반의 평균은 5권, 분산은 1.2로 세 반 중 가장 작다. 세 반의 평균은 모두 같고, 분산은 B가 가장 크므로 표준편차도 B가 가장 크다.","확인":"1.2","스킬":"A2"}],"fb":"fig/ns/"},"ns-174dcf6bfe94":{"길":"각 x를 공유하는 두 직각삼각형에서 변을 구해 삼각형 ABE의 넓이를 계산한다","단계":[{"제목":"△AOD에서 AD 구하기","힌트":"△AOD에서 tan x=AD/15이면 AD는?","식":["$\\tan x=\\dfrac{\\overline{AD}}{15}=\\dfrac{4}{3}$","$\\overline{AD}=20$"],"설명":"△AOD에서 tan x의 정의로부터 AD의 길이를 구한다.","확인":"20","스킬":"S6"},{"제목":"AO와 sin x, cos x 구하기","힌트":"직각삼각형 AOD에서 피타고라스 정리로 AO를 구하면?","식":["$\\overline{AO}=\\sqrt{20^2+15^2}=25$","$\\cos x=\\dfrac{15}{25}=\\dfrac{3}{5},\\ \\sin x=\\dfrac{20}{25}=\\dfrac{4}{5}$"],"설명":"피타고라스 정리로 빗변 AO를 구하고, 이를 이용해 cos x와 sin x 값을 얻는다.","확인":null,"스킬":"S3"},{"제목":"같은 각 x로 △BOC에서 OC, BC 구하기","고비":true,"힌트":"△BOC에도 같은 각 x가 나타난다면 OC와 BC는?","식":["$\\cos x=\\dfrac{\\overline{OC}}{15}=\\dfrac{3}{5}\\Rightarrow\\overline{OC}=9$","$\\sin x=\\dfrac{\\overline{BC}}{15}=\\dfrac{4}{5}\\Rightarrow\\overline{BC}=12$"],"설명":"△AOD에서 구한 x의 삼각비 값을 그대로 △BOC에 적용해 OC와 BC를 구한다.","확인":null,"스킬":"S6"},{"제목":"AE, BE의 길이 구하기","힌트":"AD와 BC, 반지름과 OC의 차로 AE, BE를 구하면?","식":["$\\overline{AE}=20-12=8,\\ \\overline{BE}=15-9=6$"],"설명":"AD에서 BC를 빼고 반지름에서 OC를 빼서 AE, BE를 구한다.","확인":null,"스킬":"S3"},{"제목":"△ABE의 넓이 구하기","힌트":"직각삼각형 ABE의 넓이는?","식":["$\\triangle ABE=\\dfrac12\\times6\\times8=24$"],"설명":"AE와 BE를 두 변으로 하는 직각삼각형의 넓이를 구한다.","확인":"24","스킬":"S8"}],"fb":"fig/ns/"},"ns-1f7049cd1f60":{"길":"30-60-90 삼각형과 사각형 안의 두 직각삼각형을 차례로 풀어 cos x를 구한다","단계":[{"제목":"△ABC의 세 변을 비로 나타내기","힌트":"∠B=60°인 직각삼각형에서 BC=a라 하면 AC, AB는?","식":["$\\overline{BC}=a,\\ \\overline{AC}=\\sqrt3\\,a,\\ \\overline{AB}=2a$"],"설명":"직각삼각형 ABC는 30°-60°-90° 삼각형이므로 세 변의 비 1:√3:2를 이용해 나타낸다.","확인":null,"스킬":"S6"},{"제목":"△ACF에서 FC 구하기","힌트":"△ACF에서 ∠FAC=45°일 때 FC는?","식":["$\\overline{FC}=\\sqrt3\\,a\\sin45^{\\circ}=\\dfrac{\\sqrt6}{2}a$"],"설명":"직각삼각형 ACF에서 빗변 AC와 각 45°의 삼각비로 FC를 구한다.","확인":null,"스킬":"S6"},{"제목":"△BEC에서 CE 구하기","고비":true,"힌트":"∠BCE=45°임을 이용하면 CE는?","식":["$\\overline{CE}=a\\cos45^{\\circ}=\\dfrac{\\sqrt2}{2}a$"],"설명":"직각삼각형 BEC에서 ∠BCE=45°임을 찾아내 CE를 구한다.","확인":null,"스킬":"S6"},{"제목":"AD=FE의 길이 구하기","힌트":"직사각형의 성질로 AD=FE=FC+CE인가?","식":["$\\overline{AD}=\\overline{FE}=\\dfrac{\\sqrt6}{2}a+\\dfrac{\\sqrt2}{2}a=\\dfrac{\\sqrt6+\\sqrt2}{2}a$"],"설명":"직사각형 ADEF에서 AD=FE이고, FE는 FC와 CE를 더한 값과 같다.","확인":null,"스킬":"S12"},{"제목":"cos x 값 구하기","힌트":"△ABD에서 cos x=AD/AB는?","식":["$\\cos x=\\dfrac{\\frac{\\sqrt6+\\sqrt2}{2}a}{2a}=\\dfrac{\\sqrt6+\\sqrt2}{4}$"],"설명":"직각삼각형 ABD에서 인접변 AD를 빗변 AB로 나누어 cos x를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-20bb294fa36b":{"길":"접선 성질로 직각삼각형을 만들고 닮음으로 보조점 위치를 구해 피타고라스로 EF를 구한다","단계":[{"제목":"AP, PT 길이 구하기","힌트":"AD=30이고 P가 CD를 지름으로 하는 원의 중심이면 AP는?","식":["$\\overline{AP}=25,\\ \\overline{PT}=5$"],"설명":"원 P의 지름 CD=10이므로 반지름 5이고, T가 접점이라 ∠ATP=90°인 직각삼각형에서 AP=25, PT=5이다.","확인":null,"스킬":"S13"},{"제목":"닮음 삼각형 찾기","고비":true,"힌트":"N에서 EF에 내린 수선의 발 H를 잡으면 △AHN과 △ATP는 어떤 관계일까?","식":["$\\triangle AHN\\sim\\triangle ATP$"],"설명":"두 삼각형은 공통각을 가지며 닮음이다.","확인":null,"스킬":"S1"},{"제목":"HN 구하기","힌트":"AN:AP=HN:TP 비례식을 쓰면?","식":["$15:25=\\overline{HN}:5$"],"설명":"AN=15(원N의 반지름의 3배)임을 이용해 비례식을 풀면 HN=3이다.","확인":"3","스킬":"S1"},{"제목":"EH 구하기","힌트":"직각삼각형 EHN에서 피타고라스 정리를 쓰면?","식":["$\\overline{EH}=\\sqrt{5^2-3^2}=4$"],"설명":"EN은 원 N의 반지름 5이므로 피타고라스 정리로 EH=4를 얻는다.","확인":null,"스킬":"S3"},{"제목":"EF 길이 구하기","힌트":"H가 EF의 중점이면 EF는?","식":["$\\overline{EF}=2\\overline{EH}=8$"],"설명":"수선의 발 H는 EF를 이등분하므로 EF=8이다.","확인":"8","스킬":"S2"}],"fb":"fig/ns/"},"ns-2174fccf434d":{"길":"표에서 각을 먼저 찾고, 같은 각의 다른 삼각비 값으로 BC를 구한다","단계":[{"제목":"표에서 각의 크기 찾기","힌트":"sin x=4.8629/7의 값을 표에서 찾으면 x는?","식":["$\\sin x=\\dfrac{4.8629}{7}=0.6947$","$x=44^{\\circ}$"],"설명":"표에서 sin 값이 0.6947인 각을 찾으면 x=44°이다.","확인":null,"스킬":"S6"},{"제목":"cos44°로 BC 구하기","고비":true,"힌트":"cos44°=BC/7에서 BC는?","식":["$\\cos44^{\\circ}=\\dfrac{\\overline{BC}}{7}=0.7193$","$\\overline{BC}=5.0351$"],"설명":"표에서 cos44°=0.7193을 읽어 BC를 구한다.","확인":"5.0351","스킬":"S6"}],"fb":"fig/ns/"},"ns-238173f14be6":{"길":"y절편과 축의 위치로 a, b의 부호를 정해 직선의 성질을 판단한다","단계":[{"제목":"b의 부호 정하기","힌트":"y축과의 교점이 x축 아래에 있으면 b는?","식":[],"설명":"y축과의 교점이 x축 아래에 있으므로 b<0이다.","확인":null,"스킬":"G7"},{"제목":"a의 부호 정하기","고비":true,"힌트":"축이 y축보다 오른쪽에 있으면 a는?","식":[],"설명":"축이 y축 오른쪽에 있으므로 a>0이다.","확인":null,"스킬":"G7"},{"제목":"직선의 성질 판단해 답 정하기","힌트":"a>0, b<0인 직선 y=ax+b의 x절편, 방향, y절편은?","식":["$x절편=-\\frac{b}{a}>0$"],"설명":"기울기가 양수이므로 오른쪽 위로 향하고, y절편은 음수이며, x절편은 -b/a로 0보다 크다. 따라서 옳은 것은 ②이다.","확인":null,"스킬":"G9"}],"fb":"fig/ns/"},"ns-2520a3d6b101":{"길":"원주각과 내접사각형 성질로 같은 각을 찾아 엇각으로 평행 여부를 판정한다","단계":[{"제목":"∠BAD과 ∠BCD의 관계 찾기","힌트":"같은 호에 대한 원주각은 어떤 관계일까?","식":["$\\angle BAD=\\angle BCD$"],"설명":"원주각의 성질에 의해 두 각은 같다.","확인":null,"스킬":"S5"},{"제목":"내접사각형 성질로 ∠DQP 연결하기","힌트":"사각형 CDQP가 원에 내접하면 ∠BCD와 ∠DQP는 어떤 관계일까?","식":["$\\angle BCD=\\angle DQP$"],"설명":"CDQP가 원에 내접하므로 외각은 그 내대각과 같아 ∠BCD=∠DQP이다.","확인":null,"스킬":"S5"},{"제목":"엇각으로 평행선 판정하기","고비":true,"힌트":"∠BAD=∠DQP가 엇각이면 어떤 두 직선이 평행할까?","식":["$\\angle BAD=\\angle DQP$"],"설명":"엇각의 크기가 같으므로 AB∥PQ임이 확인되는데, 이는 CD와는 다른 직선이라 ①에서는 AB와 CD가 평행하지 않다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-25dbcde6a4a9":{"길":"넓이·현의 길이는 중심각에 비례하지 않음을 걸러내고 호의 길이만 비례식으로 확인한다","단계":[{"제목":"넓이·현의 길이 선지들 판별하기","힌트":"삼각형의 넓이나 현의 길이는 중심각에 정비례할까?","식":[],"설명":"삼각형의 넓이(①)와 반지름(②), 현의 길이(④,⑤)는 중심각에 비례하지 않으므로 모두 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"호의 길이로 판별하기","고비":true,"힌트":"호의 길이는 중심각에 어떻게 비례할까?","식":["$\\overset{\\frown}{AB}=2\\overset{\\frown}{CD}$"],"설명":"호의 길이는 중심각의 크기에 정비례하므로 80°:40°=2:1인 ③만 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-2a3044eb4421":{"길":"다섯 빈칸을 하나씩 확인해 거꾸로 서술된 (라)를 찾아낸다","단계":[{"제목":"(가)(나) 확인하기","힌트":"OA, OC는 반지름이고 ∠OMA, ∠ONC는 어떤 각일까?","식":["$\\overline{OA}=\\overline{OC},\\ \\angle OMA=\\angle ONC=90^\\circ$"],"설명":"둘 다 참인 진술이므로 (가), (나)는 옳다.","확인":null,"스킬":"S5"},{"제목":"(다) 확인하기","힌트":"문제에서 이미 조건으로 주어진 것은 무엇일까?","식":["$\\overline{AB}=\\overline{CD}$"],"설명":"조건으로 주어진 등식이므로 (다)도 옳다.","확인":null,"스킬":"S5"},{"제목":"(라) 판별하기","고비":true,"힌트":"AM=CN을 이끌어내는 성질은 '수선은 현을 이등분한다'일까, '이등분선은 수선이 된다'일까?","식":[],"설명":"AM=CN을 얻으려면 '원의 중심에서 현에 내린 수선은 그 현을 이등분한다'는 성질이 필요한데, (라)는 이를 거꾸로 서술하고 있어 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"(마) 확인하기","힌트":"RHS 합동에서 얻어지는 대응변 결론은?","식":["$\\overline{OM}=\\overline{ON}$"],"설명":"합동인 두 삼각형의 대응변이므로 (마)는 옳다. 따라서 옳지 않은 것은 (라)이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-2ad31db8a3b2":{"길":"네 동심원의 넓이를 가장 작은 반지름 x로 나타내 조건식을 세운다","단계":[{"제목":"가장 작은 반지름으로 놓기","힌트":"네 원의 반지름 비가 1:2:3:4이므로 가장 작은 반지름을 x라 하면?","식":["$r=x,\\ 2x,\\ 3x,\\ 4x$"],"설명":"네 원의 반지름을 가장 작은 원의 반지름 x의 배수로 나타낸다.","확인":null,"스킬":"A8"},{"제목":"회색 부분 넓이 구하기","힌트":"네 번째-세 번째, 두 번째-첫 번째 고리의 넓이를 더하면?","식":["$\\pi(4x)^2-\\pi(3x)^2+\\pi(2x)^2-\\pi x^2=10\\pi x^2$"],"설명":"회색으로 칠해진 두 고리의 넓이를 더해 정리한다.","확인":null,"스킬":"A8"},{"제목":"빗금 부분 넓이 구하기","힌트":"세 번째-두 번째 고리와 가장 안쪽 원의 넓이를 더하면?","식":["$\\pi(3x)^2-\\pi(2x)^2+\\pi x^2=6\\pi x^2$"],"설명":"빗금 쳐진 두 부분의 넓이를 더해 정리한다.","확인":null,"스킬":"A8"},{"제목":"조건식을 세워 x와 지름 구하기","고비":true,"힌트":"두 넓이의 차가 16π라는 조건으로 x를 구하면?","식":["$10\\pi x^2-6\\pi x^2=16\\pi\\Rightarrow x=2$","$2\\times(2\\times4)=16$"],"설명":"넓이 차 조건으로 x=2를 구하고, 가장 큰 원의 지름을 계산한다.","확인":"16","스킬":"C7"}],"fb":"fig/ns/"},"ns-2b8ef819d9f6":{"길":"AC의 길이와 회전각을 구해 호의 길이와 점 T의 좌표를 각각 구한 뒤 더한다","단계":[{"제목":"AC의 길이와 회전각 구하기","힌트":"직각이등변삼각형의 빗변 AC와 회전각은?","식":["$\\overline{AC}=5\\sqrt{2},\\ \\angle TAC=135^{\\circ}$"],"설명":"피타고라스 정리로 AC를 구하고, 회전한 각을 구한다.","확인":null,"스킬":"S3"},{"제목":"호 TC의 길이 구하기","힌트":"반지름 5√2, 중심각 135°인 호의 길이는?","식":["$2\\pi\\times5\\sqrt{2}\\times\\frac{135^{\\circ}}{360^{\\circ}}=\\frac{15\\sqrt{2}}{4}\\pi$"],"설명":"호의 길이 공식으로 15√2/4 π를 얻는다.","확인":null,"스킬":"S3"},{"제목":"주어진 형태와 맞춰 a 구하기","고비":true,"힌트":"15√2를 3√a 꼴로 바꾸면?","식":["$15\\sqrt{2}=3\\sqrt{50}\\Rightarrow a=50$"],"설명":"15√2=3√50이므로 a=50이다.","확인":"50","스킬":"N8"},{"제목":"점 T의 좌표 구하기","힌트":"B(10)에서 AC만큼 이동한 T의 좌표는?","식":["$5-5\\sqrt{2}=5-\\sqrt{50}$"],"설명":"T의 좌표를 b+c√a 꼴로 맞추면 b=5, c=-1이다.","확인":null,"스킬":"N8"},{"제목":"a+b-c 계산하기","힌트":"세 값을 더하고 빼면?","식":["$50+5-(-1)=56$"],"설명":"a+b-c=56이다.","확인":"56","스킬":"A3"}],"fb":"fig/ns/"},"ns-2bed9f8ea505":{"길":"직각삼각형에서 DB를 구해 참·거짓을 가리고 소거법으로 옳은 것을 찾는다","단계":[{"제목":"① 판별하기","힌트":"OA, OB, OC는 모두 원의 반지름일까?","식":[],"설명":"OA=OB=OC(반지름)이므로 △OAB, △OCB는 모두 이등변삼각형이다. ①은 옳다.","확인":null,"스킬":"S7"},{"제목":"② DB, AB 구하기","고비":true,"힌트":"△BCD에서 피타고라스 정리를 쓰면 DB는?","식":["$\\overline{DB}=\\sqrt{(3\\sqrt2)^2-2^2}=\\sqrt{14}$","$\\overline{AB}=2\\overline{DB}=2\\sqrt{14}$"],"설명":"직각삼각형 BCD에서 DB를 구하면 실제 AB는 2√14cm이다. ②가 주장하는 √14cm와 다르므로 ②는 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"④ 판별하기","힌트":"△BCD에서 DC:DB의 비가 1:√3이 되는지 확인하면?","식":["$\\overline{DC}:\\overline{DB}\\ne1:\\sqrt3$"],"설명":"DC와 DB의 비가 1:√3이 아니므로 ∠DBC=30°가 아니다. ④는 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"⑤ 판별하기","힌트":"△OAB의 넓이를 △ODA, △ODB로 나누면?","식":["$\\triangle OAB=2\\triangle ODA=2\\triangle ODB$"],"설명":"△OAB의 넓이는 △CAB의 넓이의 2배라는 관계가 아니므로 ⑤는 옳지 않다.","확인":null,"스킬":"S12"},{"제목":"옳은 것 확정하기","힌트":"②④⑤가 모두 옳지 않으므로 남는 것은?","식":[],"설명":"②, ④, ⑤가 거짓임을 확인했으므로 옳은 것은 ①, ③ 두 개다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-2d190623a43a":{"길":"접선-현 각을 원주각으로 옮기고 지름·닮음·호의 비까지 순서대로 확인한다","단계":[{"제목":"ㄱ 판별 준비하기","힌트":"접선과 현이 이루는 각을 원주각으로 옮기면 ∠ABT는?","식":["$\\angle ABT=35^\\circ$"],"설명":"접선과 현이 이루는 각은 그 호에 대한 원주각과 같으므로 ∠ABT=35°이다.","확인":null,"스킬":"S5"},{"제목":"ㄱ 계산 마무리하기","힌트":"AB가 지름이므로 ∠ATB는 몇 도이고, 삼각형의 내각의 합으로 ∠BAT는?","식":["$\\angle ATB=90^\\circ\\Rightarrow\\angle BAT=55^\\circ$"],"설명":"지름에 대한 원주각이므로 ∠ATB=90°이고, 삼각형의 내각의 합에서 ∠BAT=55°이므로 ㄱ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ 판별하기","고비":true,"힌트":"△APT의 외각 ∠BAT를 이용하면 ∠APT는?","식":["$\\angle APT=55^\\circ-35^\\circ=20^\\circ$"],"설명":"△APT의 한 외각이 ∠BAT=55°이므로 ∠APT=20°이고, 이는 ㄴ이 주장하는 15°와 다르므로 ㄴ은 옳지 않다.","확인":null,"스킬":"S10"},{"제목":"ㄷ, ㄹ 판별하기","힌트":"PT²=PA×PB를 만드는 두 삼각형의 닮음과, 원주각으로 구한 호의 비는?","식":["$\\overset{\\frown}{BT}:\\overset{\\frown}{AT}=110^\\circ:70^\\circ=11:7$"],"설명":"△PAT∽△PTB(공통각+접선-현 각)로 ㄷ이 성립하고, 호의 길이는 원주각에 비례하므로 ㄹ도 11:7로 성립한다.","확인":null,"스킬":"S5"},{"제목":"정답 확정하기","힌트":"옳은 것을 모두 고르면?","식":[],"설명":"옳은 것은 ㄱ, ㄷ, ㄹ이다.","확인":"4","스킬":"C3"}],"fb":"fig/ns/"},"ns-2edb372559cc":{"길":"한 변이 1인 정사각형의 대각선 길이로 P, Q의 좌표를 구하고 네 보기를 차례로 확인한다","단계":[{"제목":"대각선 길이 구해 P, Q의 좌표 구하기","힌트":"한 변이 1인 정사각형의 대각선 길이는?","식":["$\\overline{AC}=\\overline{BD}=\\sqrt2$","$P=2-\\sqrt2,\\ Q=1+\\sqrt2$"],"설명":"정사각형의 대각선 길이는 √2이므로 BD=BP에서 P=2-√2이고, AC=AQ에서 Q=1+√2이다.","확인":null,"스킬":"S3"},{"제목":"가, 나 판별하기","힌트":"P의 좌표와 PA를 정의대로 계산하면?","식":["$\\overline{PA}=1-(2-\\sqrt2)=\\sqrt2-1$"],"설명":"P의 좌표가 2-√2이므로 가는 옳고, PA=√2-1=-1+√2이므로 나도 옳다.","확인":null,"스킬":"S3"},{"제목":"다 판별해 옳지 않음 확인하기","고비":true,"힌트":"PQ를 Q, P의 좌표 차로 계산하면?","식":["$\\overline{PQ}=(1+\\sqrt2)-(2-\\sqrt2)=2\\sqrt2-1$"],"설명":"PQ=2√2-1인데 다는 2√2+1이라 했으므로 다는 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"라 판별하고 답 정하기","힌트":"BD의 길이는 앞에서 이미 구했다","식":["$\\overline{BD}=\\sqrt2$"],"설명":"BD=√2이므로 라도 옳다. 따라서 옳은 것은 가, 나, 라이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-39bb6484b76c":{"길":"대각의 합 180°가 되는 경계를 잡고 점 D의 위치로 부등식의 방향을 정한다","단계":[{"제목":"경계 조건 확인하기","힌트":"∠ADC+∠B=180°이면 어떤 상태가 될까?","식":["$\\angle ADC+\\angle B=180^\\circ\\Rightarrow□ABCD는\\ 원에\\ 내접$"],"설명":"두 각의 합이 180°이면 사각형은 원에 내접하는데, 그러면 D가 원 위에 있어야 한다.","확인":null,"스킬":"S5"},{"제목":"점 D의 위치로 부등식 방향 정하기","고비":true,"힌트":"D가 활꼴 안(원 내부)에 있으면 ∠ADC는 원 위에 있을 때보다 커질까 작아질까?","식":[],"설명":"점 D는 호의 안쪽(원 내부)에 있으므로 원 위에 있을 때보다 ∠ADC가 더 커야 한다. 즉 ∠ADC>100°이어야 한다.","확인":null,"스킬":"S15"},{"제목":"될 수 없는 각 찾기","힌트":"100°는 이 부등식을 만족할까?","식":[],"설명":"∠ADC>100°이어야 하므로 100°는 될 수 없는 각이다.","확인":"100","스킬":"C1"}],"fb":"fig/ns/"},"ns-3a319242eb5e":{"길":"점 P의 좌표를 문자로 놓고 색칠한 영역 넓이 조건으로 이차방정식을 세운 뒤 넓이비를 구한다","단계":[{"제목":"점 P의 좌표 설정","힌트":"직선 y=2x 위의 점 P를 한 문자로 나타내면?","식":["$P(a,\\ 2a)$"],"설명":"점 P가 직선 y=2x 위에 있으므로 좌표를 a로 나타낸다.","확인":null,"스킬":"G10"},{"제목":"색칠한 영역 넓이식 세우기","고비":true,"힌트":"삼각형 AOC의 넓이에서 어떤 부분을 빼면 색칠한 영역이 될까?","식":["$52=\\frac12\\times10\\times20-2a(10-a)$"],"설명":"삼각형 AOC의 넓이에서 겹치는 직사각형 부분을 뺀 것이 색칠한 영역의 넓이다.","확인":null,"스킬":"G10"},{"제목":"이차방정식 풀어 a 구하기","힌트":"정리한 방정식을 인수분해하면?","식":["$a^2-10a+24=0$","$(a-6)(a-4)=0$"],"설명":"정리한 식을 인수분해해 a=4 또는 a=6을 얻고, OQ<QC 조건으로 a=4를 고른다.","확인":null,"스킬":"C2"},{"제목":"넓이의 비 구하기","힌트":"△POQ와 △APR은 닮음이다. 닮음비로 넓이비를 구하면?","식":["$\\triangle POQ:\\triangle APR=a^2:(10-a)^2=16:36=4:9$"],"설명":"두 삼각형은 닮음이므로 닮음비의 제곱으로 넓이의 비를 구한다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-3a9ccc4ab707":{"길":"여덟 조건을 내접사각형의 성질과 원주각 정리의 역으로 하나씩 확인해 개수를 센다","단계":[{"제목":"ㄱ 판별하기","힌트":"대각의 합이 180°이면 원에 내접할까?","식":[],"설명":"대각의 합이 180°이면 원에 내접하는 사각형의 조건(원주각 정리의 역)이 성립하므로 ㄱ은 옳다.","확인":null,"스킬":"S5"},{"제목":"ㄴ, ㄷ 판별하기","힌트":"대각의 크기가 같다고, 또는 대각선 일부 길이가 같다고 내접이 보장될까?","식":[],"설명":"직사각형이 아닌 평행사변형은 대각의 크기가 같고(ㄴ) 두 대각선이 서로를 이등분하지만(ㄷ) 원에 내접하지 않는다. 따라서 ㄴ, ㄷ은 내접을 보장하지 않아 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"ㄹ, ㅁ 판별하기","고비":true,"힌트":"PA×PC=PB×PD는 내접 조건일까, AB+CD=AD+BC는 어떤 사각형의 조건일까?","식":["$\\overline{PA}\\times\\overline{PC}=\\overline{PB}\\times\\overline{PD}$"],"설명":"PA×PC=PB×PD이면 PA:PD=PB:PC이고 ∠APB=∠DPC(맞꼭지각)이므로 △PAB∽△PDC이다. 그러면 ∠BAC=∠BDC이므로 A, D가 BC를 같은 쪽에서 같은 각으로 보아 네 점이 한 원 위에 있고, ㄹ은 옳다. 반면 AB+CD=AD+BC는 원에 외접하는 사각형의 조건이므로 ㅁ은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"ㅂ, ㅅ 판별하기","힌트":"한 선분을 같은 쪽에서 같은 각으로 보는 두 점은 어떤 성질을 가질까?","식":["$\\angle BAC=\\angle BDC\\Rightarrow A,D는\\ 한\\ 원\\ 위$"],"설명":"BC를 같은 쪽에서 같은 크기로 보는 두 점 A, D는 원주각 정리의 역에 의해 한 원 위에 있으므로 ㅂ은 옳고, 같은 이유로 ㅅ도 옳다.","확인":null,"스킬":"S15"},{"제목":"ㅇ 판별하고 개수 세기","힌트":"∠CBD=∠CDB는 같은 호에 대한 원주각일까?","식":[],"설명":"∠CBD와 ∠CDB는 같은 원주에 대한 원주각이 아니므로 크기가 같다고 내접을 보장할 수 없다. 따라서 옳은 조건은 ㄱ,ㄹ,ㅂ,ㅅ으로 4개이다.","확인":"4","스킬":"C3"}]},"ns-3ee32ca2e42b":{"길":"그래프가 대칭인 점선의 위치로 평균을, 퍼진 정도로 표준편차를 비교한다","단계":[{"제목":"평균 비교하기","힌트":"B의 그래프가 A보다 오른쪽에 있다면 평균은?","식":[],"설명":"B 학급의 그래프가 A 학급의 그래프보다 오른쪽에 있으므로 B의 평균이 더 높다.","확인":null,"스킬":"C3"},{"제목":"퍼짐 정도 비교하기","고비":true,"힌트":"평균을 중심으로 더 몰려 있는 쪽은 어디일까?","식":[],"설명":"A 학급의 그래프가 평균을 중심으로 더 몰려 있으므로 A의 성적이 더 고르다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-3f8e04417a26":{"길":"비율대로 S2, S3을 구해 세 정사각형의 변의 길이를 모두 더한다","단계":[{"제목":"S2, S3 값 구하기","힌트":"S2=(1/3)S1, S3=(1/3)S2를 계산하면?","식":["$S_2=\\frac13\\times3=1,\\ S_3=\\frac13\\times1=\\frac13$"],"설명":"비율대로 계산하면 S2=1, S3=1/3이다.","확인":null,"스킬":"N6"},{"제목":"각 정사각형의 변의 길이 구하기","고비":true,"힌트":"정사각형의 넓이가 S이면 한 변은?","식":["$\\overline{OB}=\\sqrt3,\\ \\overline{BB_1}=1,\\ \\overline{B_1B_2}=\\sqrt{\\frac13}=\\frac{\\sqrt3}{3}$"],"설명":"각 정사각형의 한 변은 넓이의 제곱근이므로 세 변의 길이를 구한다.","확인":null,"스킬":"N8"},{"제목":"세 길이를 더해 OB2 구하기","힌트":"OB2는 세 구간의 길이를 이은 값이다","식":["$\\overline{OB_2}=\\sqrt3+1+\\frac{\\sqrt3}{3}=\\frac{3+4\\sqrt3}{3}$"],"설명":"x축 위의 세 구간의 길이를 모두 더하면 OB2=(3+4√3)/3이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-431d82366499":{"길":"같은 쪽에서 본 직각과 대각의 합 조건으로 한 원 위의 네 점을 찾는다","단계":[{"제목":"㉠, ㉥ 판별하기","힌트":"한 선분을 같은 쪽에서 보는 두 각이 모두 90°라면?","식":["$\\angle AP_1B=\\angle AP_2B=90^\\circ$"],"설명":"선분을 같은 쪽에서 보는 두 각의 크기가 90°로 같으므로 그 네 점은 한 원 위에 있다. 이 조건으로 ㉠, ㉥이 성립한다.","확인":null,"스킬":"S15"},{"제목":"㉢ 판별하기","고비":true,"힌트":"사각형에서 마주보는 두 각의 합이 180°가 되는지 확인하면?","식":["$\\angle A+\\angle P_4=180^\\circ$"],"설명":"한 쌍의 대각의 합이 180°이므로 ㉢도 한 원 위에 있는 조건을 만족한다.","확인":null,"스킬":"S15"},{"제목":"나머지 판별하고 정답 확정하기","힌트":"㉡, ㉣, ㉤은 같은 방식으로 확인했을 때 조건을 만족할까?","식":[],"설명":"㉡, ㉣, ㉤은 같은 쪽 직각이나 대각의 합 조건을 만족하지 않으므로 한 원 위에 있지 않다. 따라서 답은 ㉠, ㉢, ㉥이다.","확인":"3","스킬":"C3"}],"fb":"fig/ns/"},"ns-450bd32fa556":{"길":"가로 길이는 묶어서, 세로 길이는 바로 인수분해한 뒤 타일 한 변으로 나눠 곱한다","단계":[{"제목":"가로 길이를 그룹핑해 인수분해하기","힌트":"$2n^3-n^2-2n+1$을 두 항씩 묶어 인수분해하면?","식":["$2n^{3}-n^{2}-2n+1=n^{2}(2n-1)-(2n-1)=(n^{2}-1)(2n-1)=(n+1)(n-1)(2n-1)$"],"설명":"네 항을 두 개씩 묶어 공통인수 (2n-1)을 꺼낸 뒤 n²-1도 인수분해한다.","확인":null,"스킬":"A1"},{"제목":"세로 길이 인수분해하기","힌트":"n²+4n+3을 인수분해하면?","식":["$n^{2}+4n+3=(n+1)(n+3)$"],"설명":"세로 길이도 두 일차식의 곱으로 나뉜다.","확인":null,"스킬":"N4"},{"제목":"타일 한 변 n+1로 각 방향 개수 나누기","고비":true,"힌트":"가로, 세로를 각각 (n+1)로 나누면 몇 개씩 배열될까?","식":["가로 $(n-1)(2n-1)$개, 세로 $(n+3)$개"],"설명":"가로, 세로 길이를 각각 타일 한 변 n+1로 나누면 배열되는 개수를 얻는다.","확인":null,"스킬":"N4"},{"제목":"전체 타일 개수 구하기","힌트":"가로 개수와 세로 개수를 곱하면?","식":["$(n-1)(2n-1)\\times(n+3)=(n-1)(2n-1)(n+3)$"],"설명":"가로 방향과 세로 방향 타일 개수를 곱하면 전체 타일 개수가 된다.","확인":null,"스킬":"A1"}],"fb":"fig/ns/"},"ns-47366108a11b":{"길":"세 반원의 넓이를 각각 구해 색칠한 부분 넓이 조건으로 이차방정식을 세운다","단계":[{"제목":"AB를 지름으로 하는 반원 넓이","힌트":"AB=20일 때 큰 반원의 넓이는?","식":["$\\pi\\times10^2\\times\\frac12=50\\pi$"],"설명":"지름이 AB인 반원의 넓이를 계산한다.","확인":null,"스킬":"C7"},{"제목":"AC, BC를 지름으로 하는 반원 넓이","힌트":"AC=x라 하면 두 작은 반원의 넓이는?","식":["$\\frac{x^2}{8}\\pi,\\ \\frac{(20-x)^2}{8}\\pi$"],"설명":"AC를 x로 놓고 두 작은 반원의 넓이를 x에 대한 식으로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"색칠한 부분 조건으로 방정식 세우기","고비":true,"힌트":"큰 반원에서 두 작은 반원을 뺀 넓이가 24π라는 조건은?","식":["$50\\pi-\\frac{x^2}{8}\\pi-\\frac{(20-x)^2}{8}\\pi=24\\pi$","$x^2-20x+96=0$"],"설명":"색칠한 부분의 넓이 조건을 정리해 이차방정식을 만든다.","확인":null,"스킬":"C2"},{"제목":"조건에 맞는 AC 구하기","힌트":"인수분해한 두 값 중 AC>CB 조건에 맞는 것은?","식":["$(x-12)(x-8)=0$","$\\overline{AC}>\\overline{CB}\\Rightarrow x=12$"],"설명":"x=8 또는 x=12 중 AC>CB를 만족하는 x=12만 남는다.","확인":"12","스킬":"C2"}],"fb":"fig/ns/"},"ns-48d7dea2cf8b":{"길":"정사각형 한 변을 2a로 두고 넓이를 두 가지로 나타내 sin x를 구한다","단계":[{"제목":"BE, BF의 길이 구하기","힌트":"한 변을 2a라 하면 직각삼각형 ABE, BCF에서 빗변은?","식":["$\\overline{BE}=\\sqrt{a^2+(2a)^2}=\\sqrt5a$","$\\overline{BF}=\\sqrt{(2a)^2+a^2}=\\sqrt5a$"],"설명":"정사각형의 한 변을 2a라 하면 E, F가 각각 AD, CD의 중점이므로 직각삼각형 ABE, BCF에서 BE=BF=√5a이다.","확인":null,"스킬":"S3"},{"제목":"삼각형 BEF의 넓이 구하기","고비":true,"힌트":"정사각형에서 세 귀퉁이 삼각형을 빼면?","식":["$\\triangle BEF=(2a)^2-2\\times\\frac12\\times2a\\times a-\\frac12\\times a\\times a=\\frac32a^2$"],"설명":"정사각형 넓이에서 세 귀퉁이 삼각형의 넓이를 빼면 삼각형 BEF의 넓이는 (3/2)a²이다.","확인":null,"스킬":"S8"},{"제목":"sin x 구하기","힌트":"넓이를 ½×BE×BF×sinx로도 쓰면?","식":["$\\frac12\\times\\sqrt5a\\times\\sqrt5a\\times\\sin x=\\frac32a^2$","$\\sin x=\\frac35$"],"설명":"두 변 BE, BF와 끼인각 x로 넓이를 나타낸 식과 앞서 구한 넓이를 같게 놓으면 sin x=3/5이다.","확인":"3/5","스킬":"S6"}],"fb":"fig/ns/"},"ns-54c2eef8328e":{"길":"내접한 정삼각형의 변의 길이·넓이·중심각·중심에서 변까지 거리를 각각 삼각비와 넓이 공식으로 구한다","단계":[{"제목":"①AC의 길이 구하기","힌트":"O에서 AC에 내린 수선의 발 M에서 ∠OCM은?","식":["$\\overline{CM}=6\\cos30^{\\circ}=3\\sqrt{3}$","$\\overline{AC}=6\\sqrt{3}$"],"설명":"O에서 AC에 내린 수선의 발을 M이라 하면 직각삼각형 OCM에서 ∠OCM=30°이므로 CM=3√3, AC=2CM=6√3이다.","확인":null,"스킬":"S6"},{"제목":"②정삼각형의 넓이 구하기","힌트":"한 변이 6√3인 정삼각형의 넓이는?","식":["$\\triangle ABC=\\frac{\\sqrt{3}}{4}\\times(6\\sqrt{3})^{2}=27\\sqrt{3}$"],"설명":"정삼각형 넓이 공식으로 △ABC=27√3이다.","확인":null,"스킬":"S8"},{"제목":"③△OCA의 넓이 구하기","고비":true,"힌트":"△OCA는 △ABC를 몇 등분한 넓이일까?","식":["$\\triangle OCA=\\frac{1}{3}\\triangle ABC=9\\sqrt{3}$"],"설명":"정삼각형의 외심은 무게중심과 같아 세 삼각형 OAB, OBC, OCA의 넓이가 같으므로 △OCA=(1/3)×27√3=9√3이다. 선지의 18√3과 달라 옳지 않다.","확인":null,"스킬":"S7"},{"제목":"④중심각 구하기","힌트":"∠AOB는 원주각 ∠ACB의 몇 배일까?","식":["$\\angle AOB=2\\angle ACB=120^{\\circ}$"],"설명":"중심각은 원주각의 2배이므로 ∠AOB=2×60°=120°이다.","확인":null,"스킬":"S5"},{"제목":"⑤중심에서 변까지 거리 구하기","힌트":"직각삼각형 ONC에서 ∠OCN=30°이면 ON은?","식":["$\\overline{ON}=6\\sin30^{\\circ}=3$"],"설명":"중심 O에서 BC에 내린 수선의 발 N에서 ∠OCN=30°이므로 ON=3이다.","확인":"3","스킬":"S6"}],"fb":"fig/ns/"},"ns-58a4fda9b2ad":{"길":"정사면체를 평면 삼각형으로 옮겨 AH, EH를 구해 tanx를 계산한다","단계":[{"제목":"AE, ED 길이 구하기","힌트":"정삼각형의 높이 공식으로 AE, ED는?","식":["$\\overline{AE}=\\overline{ED}=\\frac{\\sqrt3}{2}\\times2=\\sqrt3$"],"설명":"E는 BC의 중점이므로 AE, DE는 각각 정삼각형 ABC, BCD의 높이이고 모두 √3이다.","확인":null,"스킬":"S11"},{"제목":"EH 구하기","고비":true,"힌트":"점 A에서 ED에 내린 수선의 발 H는 ED를 어떻게 나눌까?","식":["$\\overline{EH}=\\frac13\\overline{DE}=\\frac{\\sqrt3}{3}$"],"설명":"정사면체이므로 A에서 밑면 BCD에 내린 수선의 발 G는 △BCD의 무게중심이고, G는 중선 ED 위에서 EG=(1/3)ED이다. AG⊥ED이므로 G가 곧 수선의 발 H이다.","확인":null,"스킬":"S7"},{"제목":"AH 구하기","힌트":"직각삼각형 AEH에서 AH는?","식":["$\\overline{AH}=\\sqrt{(\\sqrt3)^2-\\left(\\frac{\\sqrt3}{3}\\right)^2}=\\frac{2\\sqrt6}{3}$"],"설명":"직각삼각형 AEH에서 피타고라스 정리로 AH=2√6/3이다.","확인":null,"스킬":"S3"},{"제목":"tan x 구하기","힌트":"tanx=AH/EH는?","식":["$\\tan x=\\frac{2\\sqrt6}{3}\\times\\sqrt3=2\\sqrt2$"],"설명":"직각삼각형 AEH에서 tanx=AH/EH=2√2이다.","확인":null,"스킬":"S6"}]},"ns-5b32517af903":{"길":"두 점으로 판매량 함수를 구하고 매출 함수를 완전제곱으로 정리한다","단계":[{"제목":"두 점으로 직선식 세우기","힌트":"두 점 (300,500), (350,400)을 이용하면?","식":["$300a+b=500$","$350a+b=400$"],"설명":"판매량을 단가의 일차식으로 놓고 두 점을 대입한다.","확인":null,"스킬":"C7"},{"제목":"연립방정식 풀기","힌트":"두 식을 빼서 a, b를 구하면?","식":["$a=-2,\\ b=1100$","$y=-2x+1100$"],"설명":"연립방정식을 풀어 판매량 함수를 얻는다.","확인":null,"스킬":"A10"},{"제목":"매출 함수를 완전제곱으로 정리하기","고비":true,"힌트":"매출=단가×판매량을 완전제곱으로 바꾸면?","식":["$(\\text{매출})=x(-2x+1100)=-2x^2+1100x$","$=-2(x-275)^2+2\\times275^2$"],"설명":"매출 함수를 완전제곱으로 정리하면 x=275일 때 최대가 된다.","확인":"275","스킬":"A6"}],"fb":"fig/ns/"},"ns-5dbdbb3a1862":{"길":"중심에서 현에 내린 수선이 현을 이등분함과 중점연결정리를 이어 옳지 않은 것을 찾는다","단계":[{"제목":"수선의 발이 중점임을 적용하기","힌트":"중심에서 현에 내린 수선은 현을 어떻게 나눌까?","식":["$\\overline{AM}=\\overline{BM},\\ \\overline{AN}=\\overline{CN}$"],"설명":"원의 중심에서 현에 내린 수선은 현을 이등분하므로 AM=BM, AN=CN이다.","확인":null,"스킬":"S13"},{"제목":"중점연결정리 적용하기","힌트":"M, N이 각각 AB, AC의 중점이면 MN과 BC의 관계는?","식":["$\\overline{MN}\\parallel\\overline{BC},\\ \\overline{BC}=2\\overline{MN}$"],"설명":"M, N이 AB, AC의 중점이므로 중점연결정리에 의해 MN∥BC, BC=2MN이다.","확인":null,"스킬":"S1"},{"제목":"옳지 않은 것 찾기","고비":true,"힌트":"OM=ON이라는 조건이 주어졌을까?","식":[],"설명":"OM=ON일 때에만 AB=AC가 성립하는데 그 조건이 주어지지 않았으므로 ④가 옳지 않다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-62e4775f8d0e":{"길":"직각삼각형의 비를 k로 두고, 수선을 내려 닮음으로 BH, DH를 구해 AD를 얻는다","단계":[{"제목":"AC 구하기","힌트":"sinx=1/3이면 AB, BC, AC의 비는?","식":["$\\overline{AB}=3k,\\ \\overline{BC}=k$","$\\overline{AC}=\\sqrt{(3k)^2-k^2}=2\\sqrt2k$"],"설명":"sinx=BC/AB=1/3이므로 AB=3k, BC=k로 두면 AC=2√2k이다.","확인":null,"스킬":"S6"},{"제목":"수선 내려 닮음 만들기","고비":true,"힌트":"점 D에서 AB의 연장선에 내린 수선의 발을 H라 하면 △ABC∽△DBH일까?","식":[],"설명":"점 D에서 AB의 연장선에 내린 수선의 발을 H라 하면 BD=BC=k인 이등변삼각형이고, △ABC∽△DBH(AA닮음)이다.","확인":null,"스킬":"S2"},{"제목":"BH, DH 구하기","힌트":"k:BH=3:1, 2√2k:DH=3:1이면?","식":["$\\overline{BH}=\\frac13k,\\ \\overline{DH}=\\frac{2\\sqrt2}{3}k$"],"설명":"닮음비로 BH=k/3, DH=2√2k/3이다.","확인":null,"스킬":"S1"},{"제목":"AD 구하기","힌트":"AH=AB+BH이면 직각삼각형 ADH에서 AD는?","식":["$\\overline{AH}=3k+\\frac13k=\\frac{10}{3}k$","$\\overline{AD}=\\sqrt{\\left(\\frac{2\\sqrt2}{3}k\\right)^2+\\left(\\frac{10}{3}k\\right)^2}=2\\sqrt3k$"],"설명":"AH=AB+BH=(10/3)k이므로 직각삼각형 ADH에서 AD=2√3k이다.","확인":null,"스킬":"S3"},{"제목":"cos y 구하기","힌트":"cosy=AH/AD는?","식":["$\\cos y=\\frac{\\frac{10}{3}k}{2\\sqrt3k}=\\frac{5\\sqrt3}{9}$"],"설명":"직각삼각형 ADH에서 cosy=AH/AD=5√3/9이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-6427c1902718":{"길":"RHS합동으로 성립하는 것들을 확인한 뒤 반지름을 구할 근거가 없음을 찾는다","단계":[{"제목":"RHS합동 확인하기","힌트":"PO가 공통, ∠PAO=∠PBO=90°, OA=OB이면?","식":["$\\triangle PAO\\equiv\\triangle PBO$"],"설명":"PO가 공통, 두 직각이 같고, OA=OB(반지름)이므로 RHS합동이다.","확인":null,"스킬":"S5"},{"제목":"합동으로 성립하는 것 확인하기","힌트":"합동이면 대응변·대응각·나머지 각의 합은?","식":["$\\overline{PA}=\\overline{PB}=10,\\ \\angle PAO=\\angle PBO,\\ \\angle APO+\\angle POA=90^{\\circ}$"],"설명":"합동에서 대응변·대응각이 같으므로 ①③④⑤는 모두 성립한다.","확인":null,"스킬":"S5"},{"제목":"옳지 않은 것 찾기","고비":true,"힌트":"AO(반지름)의 길이를 구할 수 있는 조건이 주어졌을까?","식":[],"설명":"PA=10cm이라는 조건만으로는 반지름 AO의 길이를 알 수 없으므로 ②가 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-650c063f2abd":{"길":"반지름이 1인 사분원에서 각 보기의 삼각비를 선분으로 바꿔 확인한다","단계":[{"제목":"ㄱ, ㄴ 확인하기","고비":true,"힌트":"OA=OC=1이면 sina, tana는?","식":["$\\sin a^{\\circ}=\\frac{\\overline{AB}}{1}=\\overline{AB}$","$\\tan a^{\\circ}=\\frac{\\overline{CD}}{1}=\\overline{CD}$"],"설명":"OA=OC=1이므로 sina=AB, tana=CD이다. ㄱ, ㄴ 모두 옳다.","확인":null,"스킬":"S6"},{"제목":"ㄷ 확인하기","힌트":"cosb=AB/OA인데 cosb는 어떤 값과 같을까?","식":["$\\cos b^{\\circ}=\\frac{\\overline{AB}}{1}=\\overline{AB}$"],"설명":"cosb=AB이지 OB가 아니므로 ㄷ은 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"ㄹ 확인하기","힌트":"c와 b가 같은 각이면 sinc는?","식":["$\\sin c^{\\circ}=\\sin b^{\\circ}=\\frac{\\overline{OB}}{1}=\\overline{OB}$"],"설명":"∠c=∠b이므로 sinc=OB이다. ㄹ도 옳다. 따라서 옳은 것은 ㄱ, ㄴ, ㄹ이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-65126883563c":{"길":"각의 이등분선 성질로 두 변의 비를 얻고 변수를 두어 피타고라스로 sinx를 구한다","단계":[{"제목":"각의 이등분선 성질 적용하기","고비":true,"힌트":"각의 이등분선은 대변을 어떤 비로 나눌까?","식":["$\\overline{AB}:\\overline{AC}=\\overline{BD}:\\overline{DC}=2:1$"],"설명":"각의 이등분선의 성질에 의해 AB:AC=BD:DC=2:1이다.","확인":null,"스킬":"C7"},{"제목":"변수로 두고 식 세우기","힌트":"AB=2a,AC=a,BD=2b,DC=b라 하면 직각삼각형 ABC에서?","식":["$(2a)^2=a^2+(3b)^2$","$a^2=3b^2\\Rightarrow a=\\sqrt3b$"],"설명":"AB=2a, AC=a, BD=2b, DC=b로 두고 피타고라스 정리를 적용하면 a=√3b이다.","확인":null,"스킬":"S3"},{"제목":"AD 구하기","힌트":"직각삼각형 ACD에서 AD는?","식":["$\\overline{AD}=\\sqrt{a^2+b^2}=\\sqrt{3b^2+b^2}=2b$"],"설명":"직각삼각형 ACD에서 피타고라스 정리로 AD=2b이다.","확인":null,"스킬":"S3"},{"제목":"sin x 구하기","힌트":"△ACD에서 sinx=DC/AD는?","식":["$\\sin x=\\frac{b}{2b}=\\frac12$"],"설명":"직각삼각형 ACD에서 sinx=DC/AD=1/2이다.","확인":"1/2","스킬":"S6"}],"fb":"fig/ns/"},"ns-668df0521415":{"길":"표에서 각 사람의 분산을 직접 계산해 표준편차를 비교한다","단계":[{"제목":"갑의 분산 구하기","힌트":"갑의 편차 제곱과 도수를 곱해 더하면?","식":["$\\frac{(-3)^2\\times1+(-1)^2\\times1+1^2\\times4}{10}=1.4$"],"설명":"갑의 편차 제곱과 도수를 곱해 더한 뒤 10으로 나누면 분산은 1.4이다.","확인":null,"스킬":"P4"},{"제목":"을의 분산 구하기","고비":true,"힌트":"을의 편차 제곱과 도수를 곱해 더하면?","식":["$\\frac{(-3)^2\\times1+(-2)^2\\times1+(-1)^2\\times2+1^2\\times3+2^2\\times2}{10}=2.6$"],"설명":"같은 방식으로 을의 분산을 구하면 2.6이다.","확인":null,"스킬":"P4"},{"제목":"표준편차 비교하기","힌트":"분산이 작을수록 표준편차도 작다 - 실력은 어느 쪽이 더 안정적일까?","식":["$\\sqrt{1.4}<\\sqrt{2.6}$"],"설명":"갑의 분산이 더 작으므로 표준편차도 작고, 갑의 실력이 더 안정적이다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-67f04da381e9":{"길":"한 변의 길이를 정사각형 조건으로 이차방정식을 세워 a를 구한 뒤 넓이를 계산한다","단계":[{"제목":"점 C,D를 문자로 나타내고 한 변의 길이 세우기","힌트":"C(a,0)이라 하면 D는? 정사각형이므로 CD의 길이는?","식":["$C(a,0),\\ D(a,6-a^2)$","$\\overline{CD}=2a$"],"설명":"정사각형이므로 세로 길이 6-a²이 가로 길이 2a와 같다.","확인":null,"스킬":"S4"},{"제목":"이차방정식 풀어 a 구하기","고비":true,"힌트":"6-a²=2a를 정리하면?","식":["$a^2+2a-6=0$","$a=-1+\\sqrt7\\ (a>0)$"],"설명":"근의 공식으로 풀면 a>0인 근은 -1+√7이다.","확인":null,"스킬":"S4"},{"제목":"넓이 계산하기","힌트":"정사각형의 넓이는 한 변 길이의 제곱, 즉 (2a)²는?","식":["$4a^2=4(-1+\\sqrt7)^2=32-8\\sqrt7$"],"설명":"한 변의 길이의 제곱을 계산하면 넓이는 32-8√7이다.","확인":null,"스킬":"S4"}],"fb":"fig/ns/"},"ns-68186759e6f3":{"길":"포물선의 폭 비교로 부등식을 세워 k의 범위를 구한다","단계":[{"제목":"계수 크기로 부등식 세우기","힌트":"㉮와 ㉯ 사이에 있으려면 1-k는 두 계수 사이일까?","식":["$\\frac14<1-k<\\sqrt2$"],"설명":"포물선의 폭은 이차항 계수의 절댓값이 클수록 좁으므로 1-k가 두 계수 사이에 있어야 한다.","확인":null,"스킬":"C7"},{"제목":"부등식을 풀어 k의 범위 구하기","고비":true,"힌트":"1-k에 대한 부등식을 k에 대해 정리하면?","식":["$-\\sqrt2+1<k<\\frac34$"],"설명":"부등식을 정리하면 k의 범위를 얻는다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-6d4432367fb7":{"길":"완전제곱으로 꼭짓점을 구하고 삼각형 넓이 조건으로 k를 구한다","단계":[{"제목":"y절편 B의 좌표 구하기","힌트":"y축과의 교점의 좌표는?","식":["$B(0,\\ k)$"],"설명":"x=0을 대입하면 y절편은 k이므로 B의 좌표는 (0, k)이다.","확인":null,"스킬":"G1"},{"제목":"완전제곱으로 꼭짓점 A 구하기","힌트":"y=-x²-8x+k를 완전제곱 꼴로 바꾸면?","식":["$y=-(x+4)^{2}+16+k$"],"설명":"완전제곱으로 바꾸면 꼭짓점 A의 좌표는 (-4, 16+k)이다.","확인":null,"스킬":"A6"},{"제목":"삼각형 OAB의 넓이로 k 구하기","고비":true,"힌트":"밑변 OB=k, 높이는 A의 x좌표의 절댓값 4를 쓰면?","식":["$\\triangle OAB=\\frac{1}{2}\\times k\\times4=2$"],"설명":"넓이 공식에 대입해 풀면 2k=2이므로 k=1이다.","확인":"1","스킬":"G10"}],"fb":"fig/ns/"},"ns-6d44498cb0e2":{"길":"직각삼각형과 접선의 길이가 같다는 성질로 미지수 x에 대한 방정식을 세워 풀고 넓이를 구한다","단계":[{"제목":"BE의 길이 구하기","힌트":"직각삼각형 BCE에서 CE=4, BC=5이면 BE는?","식":["$\\overline{BE}=\\sqrt{5^{2}-4^{2}}=3$"],"설명":"△BCE에서 ∠BEC=90°, CE=4(반지름), BC=5이므로 피타고라스 정리로 BE=3이다.","확인":null,"스킬":"S3"},{"제목":"접선의 길이가 같음을 이용해 미지수 놓기","힌트":"F에서 그은 두 접선 FD, FE의 길이는 같을까?","식":["$\\overline{FD}=\\overline{EF}=x$"],"설명":"F에서 원에 그은 두 접선 FD, FE의 길이는 같으므로 FD=EF=x로 놓는다.","확인":null,"스킬":"S5"},{"제목":"직각삼각형 BFP에서 식 세우기","고비":true,"힌트":"F에서 BC에 내린 수선의 발을 P라 하면 BF, BP는 x로 어떻게 표현될까?","식":["$\\overline{BF}=3+x,\\ \\overline{BP}=5-x$","$4^{2}+(5-x)^{2}=(3+x)^{2}$"],"설명":"FP=CD=4이고, BF=BE+EF=3+x, BP=BC-PC=5-x이므로 피타고라스 정리로 식을 세운다.","확인":null,"스킬":"S3"},{"제목":"x를 풀어 AF 구하기","힌트":"식을 정리해 x를 풀면?","식":["$x=2$","$\\overline{AF}=\\overline{AD}-\\overline{FD}=5-2=3$"],"설명":"식을 정리하면 x=2이고, AF=AD-FD=3이다.","확인":null,"스킬":"S3"},{"제목":"△ABF의 넓이 구하기","힌트":"AB=4, AF=3인 직각삼각형의 넓이는?","식":["$\\triangle ABF=\\frac{1}{2}\\times4\\times3=6$"],"설명":"AB와 AF를 밑변, 높이로 하여 넓이를 구하면 6이다.","확인":"6","스킬":"S8"}],"fb":"fig/ns/"},"ns-6f37dcccb60d":{"길":"내접사각형·이등변삼각형으로 직사각형과 접선을 증명하고, 넓이·둘레를 각각 계산해 비교한다","단계":[{"제목":"①직사각형 확인하기","힌트":"지름 AB에 대한 원주각과 PH에 대한 내접사각형의 대각의 합은?","식":["$\\angle APB=90^{\\circ}$","$\\angle CHD=180^{\\circ}-\\angle APB=90^{\\circ}$"],"설명":"AB가 지름이므로 ∠APB=90°이고, □PCHD는 PH를 지름으로 하는 원에 내접하므로 대각의 합이 180°에서 ∠CHD=90°이다. 네 각이 모두 직각이므로 PCHD는 직사각형이다.","확인":null,"스킬":"S5"},{"제목":"②접선 조건 위한 보조각 잡기","힌트":"직사각형의 두 각 a, b를 ∠CHP, ∠PHD로 놓으면?","식":["$\\angle CHP=a,\\ \\angle PHD=b,\\ a+b=90^{\\circ}$"],"설명":"직사각형 PCHD의 성질로 ∠CHP=a, ∠PHD=b라 하면 a+b=90°이다.","확인":null,"스킬":"S2"},{"제목":"이등변삼각형으로 수직 증명하기","고비":true,"힌트":"△CQH, △OCH가 이등변삼각형임을 이용하면 ∠OCQ는?","식":["$\\angle QCH=\\angle CHQ=b,\\ \\angle OCH=\\angle OHC=a$","$\\angle OCQ=a+b=90^{\\circ}$"],"설명":"반지름이 같아 이등변삼각형이 되는 두 삼각형에서 밑각을 비교하면 ∠OCQ=90°이고 같은 방법으로 ∠ODR=90°이다. 따라서 직선 CD는 두 작은 반원에 모두 접한다.","확인":null,"스킬":"S7"},{"제목":"④색칠된 넓이 계산하기","힌트":"큰 반원에서 두 작은 반원을 빼면?","식":["$\\pi(r_{1}+r_{2})^{2}\\times\\frac{1}{2}-\\pi r_{1}^{2}\\times\\frac{1}{2}-\\pi r_{2}^{2}\\times\\frac{1}{2}=r_{1}r_{2}\\pi$"],"설명":"색칠된 부분의 넓이는 세 반원의 넓이 차로 r1r2π이다.","확인":null,"스킬":"S12"},{"제목":"PH를 지름으로 한 원의 넓이와 비교하기","힌트":"PH²=AH×BH임을 이용하면 원 O의 넓이는?","식":["$\\overline{PH}^{2}=2r_{1}\\times2r_{2}=4r_{1}r_{2}$","$\\pi\\left(\\frac{\\overline{PH}}{2}\\right)^{2}=r_{1}r_{2}\\pi$"],"설명":"PH²=AH×BH(수선의 길이 관계)이므로 PH를 지름으로 하는 원의 넓이도 r1r2π로 같다. 따라서 색칠된 부분의 넓이는 원 O의 넓이와 같고, √2배라는 ④는 옳지 않다.","확인":null,"스킬":"S13"},{"제목":"⑤둘레의 길이 비교하기","힌트":"가장 큰 반원의 둘레와 두 작은 반원의 둘레의 합을 각각 정리하면?","식":["$2r_{1}+2r_{2}+(r_{1}+r_{2})\\pi$"],"설명":"양쪽 모두 2r1+2r2+(r1+r2)π로 같은 식이 나오므로 ⑤는 성립한다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-72875eaa34d4":{"길":"모눈에서 두 대각선의 길이를 읽어 P, Q의 좌표를 구하고 더한다","단계":[{"제목":"BC 길이로 a 구하기","힌트":"모눈에서 BC는 한 변이 1인 정사각형의 대각선일까?","식":["$\\overline{BC}=\\overline{BP}=\\sqrt2$"],"설명":"BC는 대각선이므로 √2이고 BP=BC이므로 점 P에 대응하는 수는 a=2-√2이다.","확인":null,"스킬":"S3"},{"제목":"AD 길이로 b 구하기","힌트":"AD도 같은 크기의 대각선일까?","식":["$\\overline{AD}=\\overline{AQ}=\\sqrt2$"],"설명":"AD도 대각선이므로 √2이고 AQ=AD이므로 점 Q에 대응하는 수는 b=1+√2이다.","확인":null,"스킬":"S3"},{"제목":"a+b 계산하기","고비":true,"힌트":"두 값을 더하면 √2가 사라질까?","식":["$a+b=(2-\\sqrt2)+(1+\\sqrt2)=3$"],"설명":"√2가 서로 상쇄되어 a+b=3이다.","확인":"3","스킬":"N6"}],"fb":"fig/ns/"},"ns-7352d835db66":{"길":"RHS합동과 SAS합동을 차례로 확인하고 피타고라스 정리까지 적용해 옳지 않은 것을 찾는다","단계":[{"제목":"RHS합동으로 첫 성질 찾기","힌트":"OT=OQ, ∠OTP=∠OQP=90°, OP 공통이면?","식":["$\\triangle TPO\\equiv\\triangle QPO$"],"설명":"OT=OQ(반지름), 두 직각이 같고 OP가 공통이므로 RHS합동이다. 따라서 PT=PQ, ∠TOC=∠QOC이다.","확인":null,"스킬":"S5"},{"제목":"SAS합동으로 두 번째 성질 찾기","고비":true,"힌트":"PT=PQ, ∠TPC=∠QPC, PC 공통이면 △TPC와 △QPC는?","식":["$\\triangle TPC\\equiv\\triangle QPC$"],"설명":"PT=PQ, ∠TPC=∠QPC, PC가 공통이므로 SAS합동이다. 따라서 ∠TCP=∠QCP=90°이고 PO⊥TQ이다.","확인":null,"스킬":"S5"},{"제목":"피타고라스 정리 적용하기","힌트":"직각삼각형 OTP에서 PO²은?","식":["$\\overline{PO}^{2}=\\overline{PT}^{2}+\\overline{OT}^{2}$"],"설명":"직각삼각형 OTP에서 피타고라스 정리가 성립한다.","확인":null,"스킬":"S3"},{"제목":"옳지 않은 것 찾기","힌트":"PT와 PO는 같은 길이일까?","식":[],"설명":"PT=PQ가 성립할 뿐 PT=PO라는 근거는 없으므로 ③이 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-74f6de60e6e6":{"길":"다섯 쌍의 삼각형을 각각 원주각·내접사각형 성질로 AA닮음인지 확인한다","단계":[{"제목":"①APD와 BPC의 닮음 확인하기","힌트":"∠PAD와 ∠PBC, ∠PDA와 ∠PCB는 각각 같은 호의 원주각일까?","식":["$\\triangle APD\\sim\\triangle BPC$"],"설명":"∠PAD=∠PBC, ∠PDA=∠PCB(원주각)이므로 AA닮음이다.","확인":null,"스킬":"S5"},{"제목":"③ACS와 BDS의 닮음 확인하기","힌트":"∠S는 공통이고 ∠SAC와 ∠SBD는?","식":["$\\triangle ACS\\sim\\triangle BDS$"],"설명":"∠S가 공통이고 ∠SAC=∠SBD(원주각)이므로 AA닮음이다.","확인":null,"스킬":"S5"},{"제목":"④ABP와 DCP의 닮음 확인하기","힌트":"∠PAB와 ∠PDC, ∠PBA와 ∠PCD는?","식":["$\\triangle ABP\\sim\\triangle DCP$"],"설명":"∠PAB=∠PDC, ∠PBA=∠PCD(원주각)이므로 AA닮음이다.","확인":null,"스킬":"S5"},{"제목":"⑤ABS와 CDS의 닮음 확인하기","힌트":"내접사각형의 성질로 ∠SAB와 ∠SCD는?","식":["$\\triangle ABS\\sim\\triangle CDS$"],"설명":"∠S가 공통이고 내접사각형의 성질로 ∠SAB=∠SCD이므로 AA닮음이다.","확인":null,"스킬":"S5"},{"제목":"틀리게 말한 것 찾기","고비":true,"힌트":"△ABC와 △BDA는 대응각이 같다는 근거가 있을까?","식":[],"설명":"①③④⑤는 모두 근거가 있지만 ②는 대응각이 같다는 근거가 없으므로 틀리게 말한 것이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-77543a237570":{"길":"AB:AC 비를 x좌표 차이로 옮겨 C의 좌표를 구하고 차례로 b, a를 정한다","단계":[{"제목":"점 A의 좌표 확인하기","힌트":"A의 x좌표가 2이고 y=ax² 위의 점이므로 A의 좌표는?","식":["$A(2,\\ 4a)$"],"설명":"A의 x좌표가 2이므로 y=ax² 위의 점 A의 좌표는 (2, 4a)이다.","확인":null,"스킬":"A8"},{"제목":"AB:AC 비로 점 C의 x좌표 구하기","고비":true,"힌트":"AB:AC=2:3이면 A에서 C까지 x좌표 차이는 A에서 B까지의 몇 배일까?","식":["$C_x-2=\\frac{3}{2}\\times(2-0)=3\\ \\Rightarrow\\ C_x=5$"],"설명":"AB:AC=2:3이므로 x좌표 차이도 같은 비로 늘어나 C의 x좌표는 5이다.","확인":null,"스킬":"A8"},{"제목":"b 값 구하기","힌트":"C(5, 25/6)이 직선 위의 점이므로?","식":["$\\frac{25}{6}=-\\frac{5}{2}+b\\ \\Rightarrow\\ b=\\frac{20}{3}$"],"설명":"C의 좌표를 직선의 식에 대입하면 b=20/3이다.","확인":null,"스킬":"C7"},{"제목":"a 값 구하기","힌트":"4a-b=-1에 b=20/3을 대입하면?","식":["$4a-\\frac{20}{3}=-1\\ \\Rightarrow\\ a=\\frac{17}{12}$"],"설명":"앞서 세운 식에 b값을 대입해 정리하면 a=17/12이다.","확인":"17/12","스킬":"A3"}],"fb":"fig/ns/"},"ns-7a91b5d6039c":{"길":"점선의 좌우 위치로 평균을, 그래프의 퍼진 정도로 고르기를 비교한다","단계":[{"제목":"시청시간(평균) 비교하기","힌트":"점선이 더 오른쪽에 있는 반은?","식":[],"설명":"A의 점선이 B의 점선보다 오른쪽에 있으므로 A반의 시청 시간이 더 길다.","확인":null,"스킬":"C3"},{"제목":"분포의 고르기 비교하기","고비":true,"힌트":"더 평평하게 퍼진 그래프는 어느 쪽일까?","식":[],"설명":"A반의 그래프가 B반보다 평평하므로 B반의 분포가 더 고르다.","확인":null,"스킬":"C3"},{"제목":"답 확정하기","힌트":"시청시간은 짧고 고른 쪽을 고르면?","식":[],"설명":"B반이 시청시간은 짧지만 분포는 고르므로 답은 ④이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-8302f3f24f7a":{"길":"삼각비를 변으로 바꾸고 부호를 판정해 절댓값을 없앤다","단계":[{"제목":"삼각비를 변으로 나타내기","힌트":"직각삼각형에서 sinA, sinB, cosA, cosB를 변으로 쓰면?","식":["$\\sin A=\\frac ac,\\ \\sin B=\\frac bc,\\ \\cos A=\\frac bc,\\ \\cos B=\\frac ac$"],"설명":"직각삼각형의 정의로 네 삼각비를 세 변으로 나타낸다.","확인":null,"스킬":"S6"},{"제목":"부호 판정하기","고비":true,"힌트":"0<A<45<B<90일 때 sinA와 sinB, cosA와 cosB의 크기는?","식":["$\\sin A<\\sin B,\\ \\cos A>\\cos B$"],"설명":"각의 범위에서 삼각비의 대소를 판정해 절댓값 기호를 없앤다.","확인":null,"스킬":"C2"},{"제목":"절댓값을 풀어 정리하기","힌트":"부호에 맞춰 절댓값을 풀면?","식":["$-(\\sin A-\\sin B)+(\\cos A-\\cos B)=\\frac{2(b-a)}{c}$"],"설명":"부호를 반영해 절댓값을 풀고 정리하면 2(b-a)/c가 된다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-85ece874f24e":{"길":"특수각 삼각형으로 변을 구하고 넓이를 두 가지로 표현해 반지름을 구한다","단계":[{"제목":"꼭짓점에서 수선 내려 밑변 이등분하기","힌트":"이등변삼각형이므로 BH=CH는 얼마일까?","식":["$\\overline{BH}=\\overline{CH}=4\\sqrt3$"],"설명":"A에서 BC에 내린 수선의 발 H는 BC를 이등분한다.","확인":null,"스킬":"S2"},{"제목":"AB 길이 구하기","힌트":"30-60-90 삼각형 ABH에서 변의 비는?","식":["$4\\sqrt3:\\overline{AB}=\\sqrt3:2\\Rightarrow\\overline{AB}=8$"],"설명":"특수각 삼각형의 변의 비로 AB를 구한다.","확인":"8","스킬":"S6"},{"제목":"넓이를 두 가지로 표현해 식 세우기","고비":true,"힌트":"△ABC의 넓이를 ½ab sinθ와 내접원 반지름 공식으로 각각 쓰면?","식":["$\\frac12\\times8\\times8\\sqrt3\\times\\sin30^\\circ=\\frac r2(16+8\\sqrt3)$"],"설명":"넓이를 두 가지 방법으로 나타낸 식을 세운다.","확인":null,"스킬":"S8"},{"제목":"r에 대해 정리하기","힌트":"양변을 정리해 r을 구하면?","식":["$16\\sqrt3=(8+4\\sqrt3)r\\Rightarrow r=\\frac{4\\sqrt3}{2+\\sqrt3}=4(2\\sqrt3-3)$"],"설명":"식을 정리하고 유리화해 r을 구한다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-85ed5772b465":{"길":"공통각을 갖는 여러 직각삼각형에서 cos A 를 나타내는 비를 하나씩 확인한다","단계":[{"제목":"①~③ 선지에서 cos A 확인하기","힌트":"직각삼각형 ABC, ADE, EDF에서 cos A는 각각 어떻게 쓸까?","식":["$\\angle\\mathrm{DEF}=\\angle\\mathrm{A}$","$\\cos A=\\frac{\\overline{\\mathrm{AB}}}{\\overline{\\mathrm{AC}}}=\\frac{\\overline{\\mathrm{AD}}}{\\overline{\\mathrm{AE}}}=\\frac{\\overline{\\mathrm{DE}}}{\\overline{\\mathrm{EF}}}$"],"설명":"$\\triangle\\mathrm{ABC}$, $\\triangle\\mathrm{ADE}$ 는 $\\angle\\mathrm{A}$ 를 공유하고, $\\triangle\\mathrm{EDF}$ 는 $\\angle\\mathrm{DEF}$ 가 $\\angle\\mathrm{A}$ 와 같다(둘 다 $\\angle\\mathrm{AED}$ 의 여각). 세 삼각형 모두 직각삼각형이라 이웃한 변 ÷ 빗변이 모두 $\\cos A$ 이다.","확인":null,"스킬":"S1"},{"제목":"④ 선지 판별하기","고비":true,"힌트":"직각삼각형 EDF에서 DF/EF는 cos A일까 sin A일까?","식":["$\\sin A=\\frac{\\overline{\\mathrm{DF}}}{\\overline{\\mathrm{EF}}}$"],"설명":"DF/EF는 각 A에 대한 sin이지 cos이 아니므로 ④가 cos A의 값이 아니다.","확인":null,"스킬":"S6"},{"제목":"⑤ 선지 확인하기","힌트":"직각삼각형 AEF에서 cos A는?","식":["$\\cos A=\\frac{\\overline{\\mathrm{AE}}}{\\overline{\\mathrm{AF}}}$"],"설명":"⑤도 cos A와 같은 값이다.","확인":null,"스킬":"S1"}]},"ns-86e6a8646092":{"길":"접은 각 관계로 이등변삼각형을 찾고 보조선을 그어 tan x를 구한다","단계":[{"제목":"엇각·접은 각으로 각 관계 찾기","힌트":"엇각과 접은 각의 성질로 ∠GFE와 ∠GEF는 어떤 관계일까?","식":["$\\angle\\mathrm{GFE}=\\angle\\mathrm{DEF}\\ (\\text{엇각})$","$\\angle\\mathrm{GEF}=\\angle\\mathrm{DEF}\\ (\\text{접은 각})$"],"설명":"$\\overline{\\mathrm{AD}}\\parallel\\overline{\\mathrm{BC}}$ 라 $\\angle\\mathrm{GFE}$ 는 $\\angle\\mathrm{DEF}$ 와 엇각이고, 접은 각이라 $\\angle\\mathrm{GEF}=\\angle\\mathrm{DEF}$ 이다. 두 각이 모두 $\\angle\\mathrm{DEF}$ 와 같으므로 $\\angle\\mathrm{GFE}=\\angle\\mathrm{GEF}$ 이다.","확인":null,"스킬":"S10"},{"제목":"이등변삼각형 GEF 찾기","고비":true,"힌트":"두 밑각이 같은 삼각형 GEF에서 GF의 길이는?","식":["$\\overline{\\mathrm{GF}}=\\overline{\\mathrm{GE}}=\\overline{\\mathrm{ED}}=4$"],"설명":"$\\angle\\mathrm{GFE}=\\angle\\mathrm{GEF}$ 이므로 $\\triangle\\mathrm{GEF}$ 는 $\\overline{\\mathrm{GE}}=\\overline{\\mathrm{GF}}$ 인 이등변삼각형이고, 접은 선분이므로 $\\overline{\\mathrm{GE}}$ 는 $\\overline{\\mathrm{ED}}$ 와 같은 4이다.","확인":"4","스킬":"S10"},{"제목":"접힌 삼각형 GHF 에서 HF 구하기","힌트":"접으면 C 가 H 로 옮겨진다. 직각삼각형 GHF 에서 GH=3, GF=4 일 때 HF 는?","식":["$\\overline{\\mathrm{GH}}=\\overline{\\mathrm{DC}}=3$","$\\overline{\\mathrm{HF}}=\\sqrt{4^2-3^2}=\\sqrt7$"],"설명":"접으면 $\\angle\\mathrm{C}$ 가 $\\angle\\mathrm{H}$ 로, $\\overline{\\mathrm{DC}}$ 가 $\\overline{\\mathrm{GH}}$ 로 옮겨져 $\\angle\\mathrm{H}=90^\\circ$, $\\overline{\\mathrm{GH}}=3$ 이다. 직각삼각형 GHF 에서 피타고라스 정리로 $\\overline{\\mathrm{HF}}$ 를 구한다.","확인":null,"스킬":"S3"},{"제목":"수선의 발 P 로 EP 구하기","힌트":"F 에서 AD 에 내린 수선의 발 P 에 대해 PD 는 어느 변과 같고, EP 는?","식":["$\\overline{\\mathrm{PD}}=\\overline{\\mathrm{FC}}=\\overline{\\mathrm{HF}}=\\sqrt7$","$\\overline{\\mathrm{EP}}=4-\\sqrt7$"],"설명":"$\\mathrm{PFCD}$ 는 직사각형이라 $\\overline{\\mathrm{PD}}=\\overline{\\mathrm{FC}}$ 이고, 접었으므로 $\\overline{\\mathrm{FC}}=\\overline{\\mathrm{FH}}$ 이다. $\\overline{\\mathrm{EP}}=\\overline{\\mathrm{ED}}-\\overline{\\mathrm{PD}}$ 로 구한다.","확인":null,"스킬":"S3"},{"제목":"tan x 계산하기","힌트":"직각삼각형 EPF에서 tan x는?","식":["$\\tan x=\\frac{\\overline{\\mathrm{PF}}}{\\overline{\\mathrm{EP}}}=\\frac{3}{4-\\sqrt7}=\\frac{4+\\sqrt7}{3}$"],"설명":"$\\overline{\\mathrm{PF}}=\\overline{\\mathrm{DC}}=3$ 이고 $\\angle\\mathrm{PEF}=x$ 이므로 직각삼각형 EPF 에서 $\\tan x=\\dfrac{\\overline{\\mathrm{PF}}}{\\overline{\\mathrm{EP}}}$ 이다. 분모를 유리화해 값을 구한다.","확인":null,"스킬":"S6"}]},"ns-880730b6a481":{"길":"세 자료의 평균과 분산을 각각 계산해 네 보기를 판별한다","단계":[{"제목":"A의 평균·분산 구하기","힌트":"A 자료의 평균과 분산을 구하면?","식":["$평균=\\frac{11+12+78+14+15}{10}=13$","$분산=\\frac{4+1+1+4}{10}=1$"],"설명":"자료 A의 평균은 13, 분산은 1이다.","확인":null,"스킬":"C3"},{"제목":"B의 평균·분산 구하기","힌트":"같은 방법으로 B 자료를 계산하면?","식":["$평균=\\frac{22+24+26+28+30}{10}=13$","$분산=\\frac{8+2+2+8}{10}=2$"],"설명":"자료 B의 평균은 13, 분산은 2이다.","확인":null,"스킬":"C3"},{"제목":"C의 평균·분산 구하기","고비":true,"힌트":"C 자료도 같은 방법으로 계산하면?","식":["$평균=\\frac{11+36+26+42+15}{10}=13$","$분산=\\frac{4+3+3+4}{10}=1.4$"],"설명":"자료 C의 평균은 13, 분산은 1.4이다.","확인":null,"스킬":"C3"},{"제목":"ㄱ~ㄹ 보기 판별하기","힌트":"표준편차가 가장 작은 자료, 평균 비교, 평균=중앙값=최빈값인 자료 개수, 최빈값 개수가 가장 많은 자료를 각각 확인하면?","식":[],"설명":"표준편차가 가장 작은 것은 분산이 가장 작은 A이므로 ㄱ만 옳고, 나머지는 옳지 않다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-883f71749c3b":{"길":"다섯 진술을 삼각비의 성질대로 하나씩 따져 옳은 것을 고른다","단계":[{"제목":"①,② 판별하기","힌트":"예각에서 x가 커질 때와 작아질 때 sinx, cosx는 어떻게 변할까?","식":[],"설명":"sinx는 x가 커질수록 커지고, cosx는 x가 작아질수록 커지므로 ①,②는 모두 옳지 않다.","확인":null,"스킬":"T5"},{"제목":"③ 판별하기","고비":true,"힌트":"tanx는 x에 대해 항상 커지는 함수일까?","식":[],"설명":"tanx는 예각 범위에서 x가 커질수록 커지므로, x가 작아지면 tanx도 작아진다. 따라서 ③은 옳다.","확인":null,"스킬":"T5"},{"제목":"④,⑤ 판별하기","힌트":"45°를 기준으로 tanx의 크기, tan90°의 값은?","식":[],"설명":"45°<x<90°에서 tanx>1이므로 ④는 옳지 않고, tan90°는 정할 수 없으므로 ⑤도 옳지 않다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-8b5d201eca67":{"길":"최대 넓이는 P, Q가 꼭짓점일 때임을 이용해 PQ 거리로 a를 구한다","단계":[{"제목":"P, Q가 각 꼭짓점일 때 넓이가 최대임을 확인하기","힌트":"□PAQB의 넓이가 최대이려면 P, Q는 각 포물선의 어떤 점이어야 할까?","식":[],"설명":"사각형 PAQB가 최대 넓이를 가지려면 P, Q가 각각 포물선의 꼭짓점이어야 한다.","확인":null,"스킬":"G7"},{"제목":"두 꼭짓점의 좌표 구하기","힌트":"두 이차함수를 완전제곱 꼴로 바꾸면 꼭짓점은?","식":["$y=-\\frac{1}{2}(x-1)^{2}+\\frac{1}{2}-\\frac{1}{4}a$","$y=2(x-1)^{2}-2+a$"],"설명":"두 이차함수를 완전제곱으로 바꾸면 꼭짓점 P, Q의 x좌표가 모두 1로 같다.","확인":null,"스킬":"A6"},{"제목":"PQ의 길이로 방정식 세우기","고비":true,"힌트":"두 y좌표의 차가 10이라는 조건을 식으로 쓰면?","식":["$\\overline{PQ}=\\frac{1}{2}-\\frac{1}{4}a-(-2+a)=10$"],"설명":"P, Q의 y좌표 차가 10이라는 조건을 식으로 세운다.","확인":null,"스킬":"A3"},{"제목":"a 값 구하기","힌트":"방정식을 정리하면?","식":["$\\frac{5}{2}-\\frac{5}{4}a=10\\ \\Rightarrow\\ a=-6$"],"설명":"식을 정리하면 a=-6이다.","확인":"-6","스킬":"A3"}],"fb":"fig/ns/"},"ns-8b88a29b35c5":{"길":"큰 원과 작은 원의 넓이 차를 합차공식으로 바로 계산한다","단계":[{"제목":"두 원의 반지름 정하기","힌트":"호수 지름 95, 폭 5이면 산책로 바깥·안쪽 반지름은?","식":["$\\frac{105}{2},\\ \\frac{95}{2}$"],"설명":"바깥 지름은 95+2×5=105, 안쪽 지름은 95이므로 반지름은 각각 105/2, 95/2이다.","확인":null,"스킬":"S13"},{"제목":"합차공식으로 넓이 차 구하기","고비":true,"힌트":"두 원의 넓이 차를 합차공식으로 바꾸면?","식":["$\\left(\\frac{105}{2}\\right)^2\\pi-\\left(\\frac{95}{2}\\right)^2\\pi=\\left(\\frac{105}{2}+\\frac{95}{2}\\right)\\left(\\frac{105}{2}-\\frac{95}{2}\\right)\\pi$"],"설명":"두 원의 넓이 차를 합차공식으로 바꾼다.","확인":null,"스킬":"A6"},{"제목":"계산 정리하기","힌트":"100×5×π를 계산하면?","식":["$=100\\times5\\times\\pi=500\\pi$"],"설명":"정리하면 산책로의 넓이는 500π m²이다.","확인":null,"스킬":"N5"}],"fb":"fig/ns/"},"ns-8bca4c79221c":{"길":"작은 원에 접하는 두 현은 중심에서 거리가 반지름 3이므로, 피타고라스 정리로 반현의 길이를 구해 모두 더한다","단계":[{"제목":"접선 거리로 OR=OS=3 놓기","힌트":"AB, CD가 작은 원에 접하므로 중심에서 거리는?","식":["$\\overline{OR}=\\overline{OS}=\\overline{RP}=\\overline{SP}=3$"],"설명":"AB, CD가 작은 원(반지름 3)에 접하므로 중심에서 두 현까지 거리는 모두 3이다.","확인":null,"스킬":"S13"},{"제목":"피타고라스로 CR 구하기","고비":true,"힌트":"큰 원의 반지름 5와 OR=3으로 직각삼각형 COR에서 CR은?","식":["$\\overline{CR}=\\sqrt{5^2-3^2}=4$"],"설명":"삼각형 COR에서 피타고라스 정리를 적용해 CR을 구한다.","확인":null,"스킬":"S3"},{"제목":"수직이등분 성질로 나머지 반현 구하기","힌트":"중심에서 현에 내린 수선은 현을 어떻게 나눌까?","식":["$\\overline{CR}=\\overline{DR},\\ \\overline{AS}=\\overline{BS}=4$"],"설명":"중심에서 현에 내린 수선은 현을 이등분하므로 AS, BS도 각각 4이다.","확인":null,"스킬":"S2"},{"제목":"AB 구하기","힌트":"AS+SB를 더하면?","식":["$\\overline{AB}=\\overline{AS}+\\overline{SB}=4+4=8$"],"설명":"AB는 AS와 SB의 합이므로 8이다.","확인":null,"스킬":"S2"},{"제목":"AB+CP 구하기","힌트":"CP는 CR+RP와 같으므로 모두 더하면?","식":["$\\overline{AB}+\\overline{CP}=8+(4+3)=15$"],"설명":"CP=CR+RP=4+3=7이므로 AB+CP=8+7=15이다.","확인":"15","스킬":"S2"}],"fb":"fig/ns/"},"ns-8dd3d3394514":{"길":"그래프 부호를 읽어 다섯 선지를 함숫값으로 하나씩 확인한다","단계":[{"제목":"그래프에서 a, b, c의 부호 읽기","힌트":"위로 볼록하고 축이 x=-1, y절편이 양수이면?","식":[],"설명":"위로 볼록하므로 a<0이고, 축의 방정식 x=b/2a=-1에서 b>0이며, y절편 c는 양수이다.","확인":null,"스킬":"G6"},{"제목":"① abc<0 확인하기","힌트":"a<0, b>0, c>0이면 abc의 부호는?","식":[],"설명":"abc<0이 성립하므로 ①은 옳다.","확인":null,"스킬":"G6"},{"제목":"② 판별식, ③④ 함숫값 확인하기","힌트":"x축과 두 점에서 만나면 판별식은? x=-1, x=1을 대입한 값은?","식":["$x=-1:\\ y=a+b+c>0$","$x=1:\\ y=a-b+c<0$"],"설명":"그래프가 x축과 두 점에서 만나므로 b²-4ac>0이고, x=-1에서 y=a+b+c>0, x=1에서 y=a-b+c<0이므로 ②③④는 모두 옳다.","확인":null,"스킬":"G6"},{"제목":"⑤ a+2b+4c를 함숫값으로 옮기기","고비":true,"힌트":"x=-1/2를 대입한 값의 4배가 a+2b+4c와 같을까?","식":["$x=-\\frac{1}{2}:\\ y=\\frac{1}{4}a+\\frac{1}{2}b+c>0$"],"설명":"x=-1/2에서의 함숫값이 양수이므로 그 4배인 a+2b+4c도 양수이다.","확인":null,"스킬":"G6"},{"제목":"옳지 않은 것 고르기","힌트":"a+2b+4c<0이라는 ⑤는 실제 부호와 맞을까?","식":[],"설명":"a+2b+4c>0이므로 ⑤ a+2b+4c<0은 옳지 않다.","확인":null,"스킬":"G6"}],"fb":"fig/ns/"},"ns-9032f663b6a3":{"길":"직각삼각형의 변의 비로 각을 구하고, RHS 합동과 사인법칙 넓이 공식으로 각 보기를 확인한다","단계":[{"제목":"∠APB 구하기","힌트":"PA:AO=√3:1이면 각도는?","식":["$\\angle APO=30^{\\circ},\\ \\angle APB=60^{\\circ}$"],"설명":"직각삼각형 PAO에서 변의 비로 각을 구하면 ∠APB=60°이다. ①은 옳다.","확인":null,"스킬":"S6"},{"제목":"AB 구하기","힌트":"△PAB가 정삼각형이라면?","식":["$\\overline{AB}=8\\sqrt3$"],"설명":"PA=PB이고 ∠APB=60°이므로 정삼각형이 되어 AB=8√3이다. ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"□APBO 넓이 구하기","고비":true,"힌트":"삼각형 PAO 넓이의 두 배는?","식":["$□APBO=2\\times\\left(\\frac12\\times8\\sqrt3\\times8\\right)=64\\sqrt3$"],"설명":"사각형 넓이는 삼각형 PAO 넓이의 2배이므로 64√3이다. 부채꼴을 뺀 값이라 한 ③은 옳지 않다.","확인":null,"스킬":"S8"},{"제목":"△AOB 넓이 구하기","힌트":"∠AOB=120°일 때 사인법칙 넓이 공식은?","식":["$\\triangle AOB=\\frac12\\times8\\times8\\times\\sin120^{\\circ}=16\\sqrt3$"],"설명":"두 변과 끼인각으로 넓이를 구하면 16√3이다. ④는 옳다.","확인":null,"스킬":"S6"},{"제목":"∠BAO 구하기","힌트":"이등변삼각형 AOB의 밑각은?","식":["$\\angle BAO=\\frac12\\times(180^{\\circ}-120^{\\circ})=30^{\\circ}$"],"설명":"이등변삼각형의 밑각을 구하면 30°이다. ⑤도 옳다.","확인":null,"스킬":"S10"}],"fb":"fig/ns/"},"ns-9185537d17fb":{"길":"두 정사각형의 넓이 차 x-a를 합차공식으로 바꿔 직사각형의 변의 길이를 읽는다","단계":[{"제목":"넓이 차를 합차공식으로 쓰기","고비":true,"힌트":"x-a를 합차공식으로 인수분해하면?","식":["$x-a=(\\sqrt{x}+\\sqrt{a})(\\sqrt{x}-\\sqrt{a})$"],"설명":"도형 ㉮를 잘라낸 넓이 x-a를 합차공식으로 인수분해한다.","확인":null,"스킬":"A6"},{"제목":"직사각형의 변 읽기","힌트":"두 인수 중 긴 변에 해당하는 것은?","식":["$\\sqrt{x}+\\sqrt{a}$"],"설명":"두 인수 중 더 큰 값인 √x+√a가 직사각형의 긴 변의 길이이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-92d8602f7bb4":{"길":"세 원의 중심을 이은 삼각형에서 30°를 이용해 접점까지 거리를 구하고, 정삼각형의 둘레를 완성한다","단계":[{"제목":"각 OBP 구하기","힌트":"정삼각형의 한 내각을 이등분하면?","식":["$\\angle OBP=30^{\\circ}$"],"설명":"정삼각형 ABC의 한 내각(60°)을 중심 O가 이등분하므로 ∠OBP=30°이다.","확인":null,"스킬":"S6"},{"제목":"BP 구하기","고비":true,"힌트":"OP=3이고 tan30°를 이용하면?","식":["$\\overline{BP}=\\frac{\\overline{OP}}{\\tan30^{\\circ}}=3\\sqrt3$"],"설명":"직각삼각형에서 tan30°의 비를 이용해 BP를 구한다.","확인":null,"스킬":"S6"},{"제목":"BC 구하기","힌트":"BP+2원의 지름+PC를 모두 더하면?","식":["$\\overline{BC}=6+6\\sqrt3$"],"설명":"가운데 두 원의 지름(6)과 양쪽 BP, PC(각 3√3)를 더한다.","확인":null,"스킬":"S2"},{"제목":"둘레 구하기","힌트":"BC를 세 번 더하면?","식":["$3\\times(6+6\\sqrt3)=18+18\\sqrt3$"],"설명":"정삼각형이므로 BC를 세 배 하면 둘레는 18+18√3이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-955eef90e51a":{"길":"네 점을 0,2,4,6으로 놓고 평균과 분산을 구해 표준편차를 계산한다","단계":[{"제목":"네 점을 수로 놓기","힌트":"간격이 2인 4개 점을 0부터 놓으면?","식":["$0,\\,2,\\,4,\\,6$"],"설명":"가장 왼쪽 점부터 0, 2, 4, 6으로 놓는다.","확인":null,"스킬":"C7"},{"제목":"평균과 분산 구하기","고비":true,"힌트":"네 수의 평균과 분산을 구하면?","식":["$평균=\\frac{0+2+4+6}{4}=3$","$분산=\\frac{9+1+1+9}{4}=5$"],"설명":"평균은 3, 분산은 5이다.","확인":null,"스킬":"N6"},{"제목":"표준편차 구하기","힌트":"분산에 제곱근을 씌우면?","식":["$\\sqrt{5}$"],"설명":"표준편차는 √5이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-9620490165a0":{"길":"보기를 그래프에서 읽은 값으로 하나씩 가리고, 남은 보기는 대회별 중앙값과의 거리로 비교한다","단계":[{"제목":"① 최빈값 비교하기","힌트":"A와 B 대회의 최빈값은 각각?","식":["$A:85점,\\ B:55점$"],"설명":"두 대회의 최빈값이 다르므로 ①은 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"② 인원수, ③ 편차합 판별하기","힌트":"두 대회 인원수는 같은가? 편차의 합은 항상 얼마일까?","식":["$A,B\\ 각각\\ 50명$"],"설명":"인원수는 각각 50명으로 같고, 편차의 합은 항상 0이므로 ②, ③도 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"④ 중앙값 비교하기","힌트":"A와 B 대회의 중앙값은 각각?","식":["$A:75점,\\ B:55점$"],"설명":"B 대회의 중앙값이 A 대회보다 낮으므로 B 대회에 출전한 선수들의 성적이 높다고 할 수 없다. 따라서 ④도 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"상대적 성적 비교하기","고비":true,"힌트":"우준이의 점수가 각 대회 중앙값에서 얼마나 떨어져 있는지 비교하면?","식":["$A:75-50=25,\\ B:55-40=15$"],"설명":"두 점수 모두 자기 대회의 중앙값보다 낮고, B 대회 점수가 중앙값에 더 가깝다. 중앙값에서 덜 떨어진 B 대회 점수가 상대적으로 더 좋은 성적이므로 남은 보기가 옳다.","확인":null,"스킬":"C3"}]},"ns-967d7abaf6ae":{"길":"완전제곱으로 꼭짓점을 구해 넓이식을 세우고 사분면 조건으로 답을 고른다","단계":[{"제목":"이차함수를 완전제곱으로 바꾸기","힌트":"y=2x²-4x+2를 완전제곱으로 바꾸면?","식":["$y=2x^{2}-4x+2=2(x-1)^{2}$"],"설명":"완전제곱 꼴로 바꾸면 꼭짓점이 보인다.","확인":null,"스킬":"A6"},{"제목":"넓이 식 세우기","힌트":"밑변 OB=6, 높이는 점 A의 y좌표","식":["$\\triangle AOB=\\frac{1}{2}\\times6\\times2(k-1)^{2}=24$"],"설명":"점 A(k,2(k-1)²)로 놓고 삼각형 AOB의 넓이 식을 세운다.","확인":null,"스킬":"G10"},{"제목":"방정식 풀어 후보 구하기","힌트":"(k-1)²=4를 풀면?","식":["$(k-1)^{2}=4\\Rightarrow k=-1\\ 또는\\ k=3$"],"설명":"이차방정식을 풀면 두 후보가 나온다.","확인":null,"스킬":"A6"},{"제목":"제1사분면 조건으로 답 정하기","고비":true,"힌트":"점 A가 제1사분면에 있으려면 x좌표는?","식":["$k=3$"],"설명":"k>0이어야 하므로 A의 x좌표는 3이다.","확인":"3","스킬":"C2"}],"fb":"fig/ns/"},"ns-9749ec4e0c1d":{"길":"두 정사각형의 넓이로 변의 길이를 구해 B, E의 좌표를 잡고 Q의 좌표를 구한다","단계":[{"제목":"정사각형 ABCD로 B의 좌표 구하기","힌트":"넓이가 10인 정사각형의 한 변은?","식":["$\\overline{AB}=\\overline{BC}=\\sqrt{10}$"],"설명":"정사각형 ABCD의 넓이가 10이므로 한 변은 √10이고, 점 P의 좌표가 -2-√10이므로 점 B의 좌표는 -2이다.","확인":"-2","스킬":"S4"},{"제목":"정사각형 DEFG로 E의 좌표 구하기","고비":true,"힌트":"넓이가 17인 정사각형의 한 변은?","식":["$\\overline{DE}=\\overline{EF}=\\sqrt{17}$"],"설명":"정사각형 DEFG의 넓이가 17이므로 한 변은 √17이고, 모눈에서 점 E의 좌표는 1이다.","확인":"1","스킬":"S4"},{"제목":"Q의 좌표 구하기","힌트":"E에서 오른쪽으로 √17만큼 가면?","식":["$Q=1+\\sqrt{17}$"],"설명":"점 Q의 좌표는 1+√17이다.","확인":null,"스킬":"S4"}],"fb":"fig/ns/"},"ns-98f6de305563":{"길":"네 진술에 특수각 값을 대입해 계산하고 참인 것을 고른다","단계":[{"제목":"ㄱ,ㄴ 계산해 판별하기","힌트":"sin²30+cos²60과 cos30×tan30을 계산하면?","식":["$\\sin^230^\\circ+\\cos^260^\\circ=\\frac14+\\frac14=\\frac12$","$\\cos30^\\circ\\times\\tan30^\\circ=\\frac{\\sqrt3}{2}\\times\\frac{\\sqrt3}{3}=\\frac12$"],"설명":"계산하면 ㄱ은 값이 1이 아니라 거짓이고, ㄴ은 sin30°=1/2과 같으므로 참이다.","확인":null,"스킬":"S6"},{"제목":"ㄷ,ㄹ 계산해 판별하기","고비":true,"힌트":"sin30+sin60과 1/tan60을 각각 계산하면?","식":["$\\sin30^\\circ+\\sin60^\\circ=\\frac{1+\\sqrt3}{2}\\ne1$","$\\frac{1}{\\tan60^\\circ}=\\frac{\\sqrt3}{3}=\\tan30^\\circ$"],"설명":"계산하면 ㄷ은 거짓, ㄹ은 참이다.","확인":null,"스킬":"S6"},{"제목":"옳은 것 고르기","힌트":"참인 진술만 고르면?","식":[],"설명":"ㄴ, ㄹ이 참이므로 답은 ㄴ, ㄹ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-9e5a3892e942":{"길":"지름과 같은 호의 원주각을 확인하고, 닮음으로 길이를 구해 나머지 보기를 가린다","단계":[{"제목":"지름의 원주각","힌트":"지름 $\\overline{\\mathrm{AD}}$ 를 보는 $\\angle\\mathrm{ACD}$ 의 크기는?","식":["$\\angle\\mathrm{ACD}=90^{\\circ}$"],"설명":"$\\overline{\\mathrm{AD}}$ 는 원 $\\mathrm{O}$ 의 지름이므로 지름에 대한 원주각 $\\angle\\mathrm{ACD}$ 는 $90^{\\circ}$ 이다. ①은 옳다.","확인":null,"스킬":"S5"},{"제목":"같은 호의 원주각","힌트":"호 $\\mathrm{AC}$ 를 보는 $\\angle\\mathrm{ABC}$ 와 같은 크기의 각은?","식":["$\\angle\\mathrm{ABC}=\\angle\\mathrm{ADC}$"],"설명":"$\\angle\\mathrm{ABC}$ 와 $\\angle\\mathrm{ADC}$ 는 같은 호 $\\mathrm{AC}$ 를 보는 원주각이므로 크기가 같다. ③은 옳다.","확인":null,"스킬":"S5"},{"제목":"직각삼각형으로 BP 구하기","힌트":"$\\triangle\\mathrm{ABP}$ 에서 $\\overline{\\mathrm{AB}}$, $\\overline{\\mathrm{AP}}$ 로 $\\overline{\\mathrm{BP}}$ 를 구하면?","식":["$\\overline{\\mathrm{BP}}=\\sqrt{4^2-3^2}=\\sqrt{7}$"],"설명":"$\\triangle\\mathrm{ABP}$ 는 $\\angle\\mathrm{APB}=90^{\\circ}$ 인 직각삼각형이므로 피타고라스 정리로 $\\overline{\\mathrm{BP}}=\\sqrt{7}$ 이다. $2\\sqrt{2}$ 가 아니므로 ④는 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"닮음으로 AC 구하기","고비":true,"힌트":"$\\triangle\\mathrm{ABP}$ 와 닮은 삼각형을 찾아 대응변의 비를 세우면?","식":["$\\triangle\\mathrm{ABP}\\sim\\triangle\\mathrm{ADC}$","$4:8=3:\\overline{\\mathrm{AC}}$","$\\overline{\\mathrm{AC}}=6$"],"설명":"$\\angle\\mathrm{ABP}=\\angle\\mathrm{ADC}$ 이고 $\\angle\\mathrm{APB}=\\angle\\mathrm{ACD}=90^{\\circ}$ 이므로 두 삼각형은 닮음이다. $\\overline{\\mathrm{AB}}:\\overline{\\mathrm{AD}}=\\overline{\\mathrm{AP}}:\\overline{\\mathrm{AC}}$ 에서 $\\overline{\\mathrm{AC}}=6$ 이다. $4\\sqrt{2}$ 가 아니므로 ⑤는 옳지 않다.","확인":"6","스킬":"S1"},{"제목":"BC 가 지름인지 따지기","힌트":"$\\angle\\mathrm{BAC}=90^{\\circ}$ 라면 $\\overline{\\mathrm{BC}}$ 의 길이와 세 변 사이의 관계는?","식":["$\\overline{\\mathrm{AB}}^2+\\overline{\\mathrm{AC}}^2=16+36=52$","$\\overline{\\mathrm{BC}}^2=8^2=64$"],"설명":"$\\angle\\mathrm{BAC}=90^{\\circ}$ 이면 $\\overline{\\mathrm{BC}}$ 가 지름이라 $\\overline{\\mathrm{BC}}^2=64$ 여야 한다. 그런데 $\\overline{\\mathrm{AB}}^2+\\overline{\\mathrm{AC}}^2=52$ 이므로 성립하지 않아 ②는 옳지 않다. 따라서 옳은 것은 ①, ③이다.","확인":null,"스킬":"S3"}]},"ns-9f16784d267e":{"길":"각의 이등분선 성질로 비를 세우고 피타고라스로 AD를 구해 cos x를 계산한다","단계":[{"제목":"각의 이등분선 성질로 비 세우기","힌트":"AD가 ∠A의 이등분선이면 AB:AC는?","식":["$\\overline{AB}:\\overline{AC}=\\overline{BD}:\\overline{DC}=2:1$"],"설명":"각의 이등분선의 성질로 AB:AC=2:1을 얻는다.","확인":null,"스킬":"S6"},{"제목":"변수로 놓고 피타고라스 식 세우기","고비":true,"힌트":"AB=2a,AC=a,BD=2b,DC=b로 놓으면 직각삼각형 ABC에서 식은?","식":["$(2a)^2=(3b)^2+a^2\\Rightarrow a=\\sqrt3\\,b$"],"설명":"직각삼각형 ABC에서 피타고라스 정리로 a와 b의 관계를 구한다.","확인":null,"스킬":"S3"},{"제목":"AD 구하기","힌트":"직각삼각형 ACD에서 AD는?","식":["$\\overline{AD}=\\sqrt{a^2+b^2}$"],"설명":"직각삼각형 ACD에서 피타고라스 정리로 AD를 구한다.","확인":null,"스킬":"S3"},{"제목":"cos x 계산하기","힌트":"AC/AD에 a=√3b를 대입하면?","식":["$\\cos x=\\frac{a}{\\sqrt{a^2+b^2}}=\\frac{\\sqrt3b}{2b}=\\frac{\\sqrt3}{2}$"],"설명":"대입해 정리하면 cos x=√3/2이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-9f8ba76a6a1b":{"길":"세 넓이가 같다는 조건을 식으로 세워 a,b,c의 비를 구한다","단계":[{"제목":"세 넓이를 같다고 식 세우기","힌트":"½ab sin30, ½ac sin60, ½bc sin45가 모두 같다는 식은?","식":["$\\frac12ab\\sin30^\\circ=\\frac12ac\\sin60^\\circ=\\frac12bc\\sin45^\\circ$"],"설명":"세 삼각형의 넓이가 같다는 조건을 식으로 세운다.","확인":null,"스킬":"S8"},{"제목":"공통 변수로 정리하기","고비":true,"힌트":"양변에 2를 곱해 특수각 값을 대입하면?","식":["$ab=\\sqrt3\\,ac=\\sqrt2\\,bc$"],"설명":"sin값을 대입해 세 식을 정리한다.","확인":null,"스킬":"A3"},{"제목":"b, a를 c로 나타내기","힌트":"ab=√3ac에서 b는, ab=√2bc에서 a는?","식":["$b=\\sqrt3c,\\quad a=\\sqrt2c$"],"설명":"두 식을 각각 c에 대한 식으로 정리한다.","확인":null,"스킬":"A3"},{"제목":"비 정리하기","힌트":"a,b,c를 c로 통일하면 비는?","식":["$a:b:c=\\sqrt2:\\sqrt3:1$"],"설명":"최종 비를 정리한다.","확인":null,"스킬":"A8"}],"fb":"fig/ns/"},"ns-a149243b1330":{"길":"길이가 같은 현의 중점을 모으면 작은 원이 되는 구조를 보고, 두 반지름의 제곱 차를 피타고라스로 구한다","단계":[{"제목":"중점이 그리는 도형 보기","힌트":"길이가 같은 현의 중점에서 중심까지 거리는?","식":[],"설명":"현의 길이가 모두 같으므로 중점에서 중심까지 거리도 모두 같아, 중점들은 작은 원을 이룬다.","확인":null,"스킬":"S13"},{"제목":"직각삼각형 세우기","고비":true,"힌트":"큰 원의 반지름 b, 작은 원의 반지름 a, 반현 4로 피타고라스를 세우면?","식":["$b^2=a^2+4^2$"],"설명":"중심에서 현에 내린 수선이 만든 직각삼각형에서 관계식을 세운다.","확인":null,"스킬":"S3"},{"제목":"넓이차 식 세우기","힌트":"현이 지나간 부분의 넓이는 두 원의 넓이 차와 같다면?","식":["$\\pi b^2-\\pi a^2=\\pi(b^2-a^2)$"],"설명":"구하는 넓이는 큰 원에서 작은 원을 뺀 것과 같다.","확인":null,"스킬":"S13"},{"제목":"값 계산하기","힌트":"b²-a²=16을 대입하면?","식":["$\\pi\\times16=16\\pi$"],"설명":"앞서 구한 b²-a²=16을 대입하면 넓이는 16π이다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-a2fbf3d881d3":{"길":"비 조건을 k로 매개화하고 같은 직선 위의 점이라 y좌표가 같다는 것을 이용한다","단계":[{"제목":"비 조건을 정리하기","힌트":"3PA=4PD이면 PA:PD는?","식":["$\\overline{PA}:\\overline{PD}=4:3$"],"설명":"주어진 식을 비로 바꾼다.","확인":null,"스킬":"A8"},{"제목":"D, A 좌표를 k로 나타내기","힌트":"비례식대로 x좌표를 4k, 3k로 놓으면?","식":["$D(3k,9ak^{2}),\\ A(-4k,16k^{2})$"],"설명":"비례식대로 x좌표를 놓고 각 그래프 식에 대입한다.","확인":null,"스킬":"A8"},{"제목":"같은 y좌표 조건 찾기","고비":true,"힌트":"A와 D는 같은 직선 l 위에 있으므로 y좌표는?","식":[],"설명":"A와 D는 모두 직선 l 위의 점이므로 y좌표가 같다는 것이 핵심이다.","확인":null,"스킬":"G1"},{"제목":"a값 구하기","힌트":"두 y좌표를 같다고 놓으면?","식":["$9ak^{2}=16k^{2}\\Rightarrow a=\\frac{16}{9}$"],"설명":"두 식을 같다고 놓고 a를 구한다.","확인":"16/9","스킬":"A6"}],"fb":"fig/ns/"},"ns-a48bb86d57ee":{"길":"점 P, Q의 위치에 맞는 접선·할선의 길이 공식을 각각 적용해 내접하지 않는 것을 가린다","단계":[{"제목":"① 판별하기","고비":true,"힌트":"P가 원 안에서 만나면 올바른 곱 관계는?","식":["$\\overline{PA}\\times\\overline{PC}=\\overline{PB}\\times\\overline{PD}$"],"설명":"두 현이 원 안에서 만나므로 PA×PC=PB×PD가 맞는 식인데, PA×PB=PC×PD라 한 ①은 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"② 확인하기","힌트":"Q가 원 밖에서 만나면 올바른 곱 관계는?","식":["$\\overline{QA}\\times\\overline{QD}=\\overline{QB}\\times\\overline{QC}$"],"설명":"두 할선이 원 밖에서 만나므로 이 관계가 성립한다. ②는 옳다.","확인":null,"스킬":"S5"},{"제목":"③ 확인하기","힌트":"같은 호에 대한 원주각은?","식":["$\\angle BAC=\\angle BDC$"],"설명":"호 BC에 대한 원주각이므로 성립한다. ③은 옳다.","확인":null,"스킬":"S5"},{"제목":"④, ⑤ 확인하기","힌트":"내접사각형의 외각과 대각의 합은?","식":["$\\angle ABC+\\angle ADC=180^{\\circ}$"],"설명":"내접사각형의 대각의 합이 180°이므로 외각 ∠ABQ=∠ADC(④)와 ⑤ 모두 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-a944aa2f0592":{"길":"반지름이 1인 사분원에서 각 점의 좌표를 삼각비로 나타내 선지를 확인한다","단계":[{"제목":"A, B 점을 삼각비로 나타내기","힌트":"반지름 OB=1이고 각이 40°이면 OA, AB는?","식":["$\\overline{OA}=\\cos40^\\circ,\\ \\overline{AB}=\\sin40^\\circ$"],"설명":"OB가 반지름 1이고 x축과 40°를 이루므로 OA=cos40°, AB=sin40°이다.","확인":null,"스킬":"T5"},{"제목":"D 점으로 tan40° 나타내기","힌트":"직선 OB를 연장해 x=1에서 만나는 점 D의 y좌표는?","식":["$\\overline{DC}=\\tan40^\\circ$"],"설명":"OC=1이므로 직각삼각형 OCD에서 tan40°=DC/OC=DC이다.","확인":null,"스킬":"T5"},{"제목":"①~⑤ 선지 확인하기","고비":true,"힌트":"AB, OA, DC 중 어느 것이 tan40°일까?","식":[],"설명":"①sin40°=AB, ②cos40°=OA, ④sin50°=cos40°=OA, ⑤tan50°>OA는 모두 옳지만 ③은 tan40°=DC인데 AB라 했으므로 옳지 않다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-aac83831fa8d":{"길":"다섯 수를 계산해 유리수인 것을 고른다","단계":[{"제목":"각 수의 성질 살펴보기","힌트":"근호나 원주율이 남으면 무리수, 사라지면 유리수다","식":[],"설명":"빗금친 부분은 유리수이므로 계산 결과에서 근호가 사라지는 것을 찾는다.","확인":null,"스킬":"C3"},{"제목":"①을 계산해 확인하기","고비":true,"힌트":"0.4의 순환소수를 분수로 바꾸면?","식":["$-\\sqrt{0.\\dot{4}}=-\\sqrt{\\frac{4}{9}}=-\\frac{2}{3}$"],"설명":"순환소수를 분수로 바꿔 근호 안이 완전제곱꼴이 되면 근호가 사라져 유리수 -2/3이 된다.","확인":"-2/3","스킬":"N6"}],"fb":"fig/ns/"},"ns-b6c53481ea50":{"길":"연속한 접선의 길이가 모두 같음을 이용해 x에 대한 식을 세워 반지름을 구한다","단계":[{"제목":"접선 길이를 x로 놓기","힌트":"PA부터 PE까지 접선의 길이는 모두 같은 x일까?","식":["$\\overline{PA}=\\overline{PB}=\\overline{PC}=\\overline{PD}=\\overline{PE}=x$"],"설명":"점 P에서 그은 접선의 길이는 원이 바뀌어도 모두 같은 x이다.","확인":null,"스킬":"S5"},{"제목":"x 구하기","고비":true,"힌트":"x+1=11에서 x는?","식":["$x+1=11,\\ x=10$"],"설명":"그림에서 주어진 관계식을 풀면 x=10이므로 구하는 반지름은 10이다.","확인":"10","스킬":"S5"}],"fb":"fig/ns/"},"ns-b74769e3d16b":{"길":"BD, DC의 길이를 구해 넓이 차를 합차공식으로 ab로 바꾸고, 식을 인수분해해 대입한다","단계":[{"제목":"BD, DC의 길이 구하기","힌트":"D는 AC의 중점이므로 CD, BD는 a,b로 어떻게 나타날까?","식":["$\\overline{CD}=\\frac{a+b}{2},\\ \\overline{BD}=\\frac{b-a}{2}$"],"설명":"D가 AC의 중점이므로 CD=(a+b)/2이고, BD는 그 나머지인 (b-a)/2이다.","확인":null,"스킬":"C7"},{"제목":"넓이 차로 ab 구하기","고비":true,"힌트":"S2-S1을 합차공식으로 바꾸면?","식":["$S_2-S_1=\\left(\\frac{b+a}{2}\\right)^2-\\left(\\frac{b-a}{2}\\right)^2=ab=11$"],"설명":"두 정사각형의 넓이 차를 합차공식으로 바꾸면 ab=11이다.","확인":"11","스킬":"A6"},{"제목":"식을 인수분해해 대입하기","힌트":"분자를 (a+b)로 묶으면 약분할 수 있을까?","식":["$\\frac{2ab^2+a+2a^2b+b}{a+b}=\\frac{2ab(a+b)+(a+b)}{a+b}=2ab+1$"],"설명":"분자를 (a+b)로 묶어 약분하면 2ab+1이 남는다.","확인":null,"스킬":"A1"},{"제목":"값 계산하기","힌트":"ab=11을 대입하면?","식":["$2\\times11+1=23$"],"설명":"ab=11을 대입하면 값은 23이다.","확인":"23","스킬":"N5"}],"fb":"fig/ns/"},"ns-bb37e0b4ca52":{"길":"정사각형의 넓이로 한 변을 구한 뒤 여덟 보기를 하나씩 대조해 옳은 것의 개수를 센다","단계":[{"제목":"정사각형의 한 변 구하기","힌트":"그림에서 정사각형의 넓이를 계산하면?","식":["$3\\times3-4\\times\\frac12\\times1\\times2=5$"],"설명":"전체 정사각형에서 삼각형 넷을 빼 넓이 5를 구하고, 한 변은 √5임을 얻는다.","확인":null,"스킬":"S3"},{"제목":"P, Q의 좌표 구하기","힌트":"BP=AB, BQ=BC를 이용해 P, Q의 좌표를 구하면?","식":["$P:-1-\\sqrt{5},\\quad Q:-1+\\sqrt{5}$"],"설명":"B를 기준으로 √5만큼 옮긴 점이 P, Q이므로 좌표를 구한다.","확인":null,"스킬":"S3"},{"제목":"ㄱ~ㅁ 대조하기","고비":true,"힌트":"보기의 값과 실제로 구한 값을 하나씩 비교하면?","식":["$\\overline{PB}=\\overline{QB}=\\sqrt{5},\\quad \\overline{PQ}=2\\sqrt{5}$"],"설명":"ㄱ, ㄴ, ㄷ, ㅁ은 실제 값과 달라 옳지 않고, ㄹ은 QB=√5로 일치해 옳다.","확인":null,"스킬":"C3"},{"제목":"ㅂ, ㅅ, ㅇ 대조하기","힌트":"b=-1+√5의 정수 부분과 소수 부분을 구해 x, y를 정하면?","식":["$b=-1+\\sqrt{5},\\quad x=1,\\quad y=-2+\\sqrt{5}$"],"설명":"1<-1+√5<2이므로 정수 부분 x=1, 소수 부분 y=-2+√5이다. 보기 ㅅ은 일치하지만 ㅂ은 x=3으로 틀렸다.","확인":null,"스킬":"N7"},{"제목":"ㅇ 계산하고 옳은 것의 개수 세기","힌트":"a+xy를 계산하면 보기 ㅇ의 값과 같을까?","식":["$a+xy=-1-\\sqrt{5}+1\\times(-2+\\sqrt{5})=-3$"],"설명":"실제 값은 -3인데 보기는 -3+2√5로 달라 ㅇ은 옳지 않다. 따라서 옳은 것은 ㄹ, ㅅ 2개다.","확인":"2","스킬":"N7"}],"fb":"fig/ns/"},"ns-bd6c2eeaba94":{"길":"두 점에서 AD에 내린 수선의 길이를 구해 닮은 삼각형의 비로 BD:DC를 구한다","단계":[{"제목":"점 B에서 내린 수선의 발 잡기","힌트":"점 B에서 AD의 연장선에 내린 수선의 발을 P라 하면 BP의 길이는?","식":["$\\overline{BP}=4\\sin60^\\circ=2\\sqrt3$"],"설명":"직각삼각형 ABP에서 각 BAD=60°이므로 BP를 구한다.","확인":null,"스킬":"S2"},{"제목":"점 C에서 내린 수선의 발 잡기","힌트":"점 C에서 AD의 연장선에 내린 수선의 발을 Q라 하면 CQ의 길이는?","식":["$\\overline{CQ}=\\sqrt6\\cos45^\\circ=\\sqrt3$"],"설명":"직각삼각형 ACQ에서 각 CAD=45°이므로 CQ를 구한다.","확인":null,"스킬":"S2"},{"제목":"닮은 삼각형으로 비 구하기","고비":true,"힌트":"△BDP와 △CDQ는 어떤 관계일까?","식":["$\\overline{BD}:\\overline{DC}=\\overline{BP}:\\overline{CQ}=2\\sqrt3:\\sqrt3=2:1$"],"설명":"맞꼭지각과 직각으로 △BDP∽△CDQ(AA닮음)이므로 BD:DC는 BP:CQ와 같다.","확인":null,"스킬":"S1"}],"fb":"fig/ns/"},"ns-be4b27727686":{"길":"각 점에서 그은 접선의 길이가 같다는 성질을 하나씩 대응시켜 옳지 않은 것을 찾는다","단계":[{"제목":"①, ②, ③ 확인하기","힌트":"A, B, C 각각에서 그은 접선의 길이는?","식":["$\\overline{AD}=\\overline{AF},\\ \\overline{BE}=\\overline{BF},\\ \\overline{CD}=\\overline{CE}$"],"설명":"한 점에서 그은 두 접선의 길이는 같으므로 ①,②,③은 모두 옳다.","확인":null,"스킬":"S5"},{"제목":"④ 확인하기","고비":true,"힌트":"BF와 CD는 서로 다른 점에서 나온 접선인데 같을까?","식":[],"설명":"BF는 점 B, CD는 점 C에서 나온 접선으로 서로 다른 점의 접선이라 같을 이유가 없으므로 ④는 옳지 않다.","확인":null,"스킬":"S5"},{"제목":"⑤ 확인하기","힌트":"원의 반지름 OD, OE, OF는?","식":["$\\overline{OD}=\\overline{OE}=\\overline{OF}$"],"설명":"모두 원의 반지름이므로 같다. ⑤는 옳다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-c2202e7388cc":{"길":"P를 문자로 놓아 직사각형 넓이를 완전제곱으로 정리해 최댓값을 만드는 점을 구한다","단계":[{"제목":"점 P 좌표 놓기","힌트":"직선 위의 점이므로 P는 어떻게 쓸까?","식":["$P\\left(p,\\frac{4}{3}p+4\\right)$"],"설명":"직선의 식을 이용해 P의 y좌표를 p로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"넓이 식 세우기","힌트":"직사각형 PQOR의 넓이는 가로×세로","식":["$S=-p\\left(\\frac{4}{3}p+4\\right)$"],"설명":"P가 2사분면 점이므로 -p(가로)와 세로의 곱으로 넓이를 세운다.","확인":null,"스킬":"G10"},{"제목":"완전제곱으로 정리하기","고비":true,"힌트":"이차식을 완전제곱 꼴로 바꾸면?","식":["$S=-\\frac{4}{3}\\left(p+\\frac{3}{2}\\right)^{2}+3$"],"설명":"완전제곱 꼴로 정리하면 최댓값의 위치가 보인다.","확인":null,"스킬":"A6"},{"제목":"점 P의 좌표 구하기","힌트":"p=-3/2일 때 y좌표는?","식":["$P\\left(-\\frac{3}{2},2\\right)$"],"설명":"p=-3/2를 직선의 식에 대입해 y좌표를 구한다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-c2a889b585f7":{"길":"합동으로 각도를 구한 뒤 직각삼각형 비율을 반복 적용해 두 넓이를 구해 더한다","단계":[{"제목":"합동으로 각 구하기","힌트":"△ABE와 △CBF는 어떤 관계이고 각 ABE는?","식":["$\\angle ABE=\\angle CBF=30^\\circ$"],"설명":"△ABE≡△CBF(RHS합동)이므로 대응각이 같아 ∠ABE=∠CBF=30°이다.","확인":null,"스킬":"S1"},{"제목":"BF 길이 구하기","힌트":"직각삼각형 BCF에서 BF는?","식":["$\\overline{BF}=\\dfrac{3}{\\cos30^\\circ}=2\\sqrt3$"],"설명":"직각삼각형 BCF에서 BC=3, 각 30°를 이용해 빗변 BF를 구한다.","확인":null,"스킬":"S6"},{"제목":"BI 길이 구하기","고비":true,"힌트":"같은 방법으로 직각삼각형 BFI에서 BI는?","식":["$\\overline{BI}=\\dfrac{2\\sqrt3}{\\cos30^\\circ}=4$"],"설명":"정사각형 BGHF에서도 같은 비율이 적용되어 BI를 구한다.","확인":null,"스킬":"S6"},{"제목":"두 이등변삼각형의 넓이 합 구하기","힌트":"넓이 공식 (1/2)×변×변×sin30°을 두 번 쓰면?","식":["$\\triangle BEF+\\triangle BIJ=\\dfrac12(2\\sqrt3)^2\\sin30^\\circ+\\dfrac12(4)^2\\sin30^\\circ=7$"],"설명":"이등변삼각형의 넓이 공식으로 각각 구해 더하면 7이다.","확인":"7","스킬":"S8"}],"fb":"fig/ns/"},"ns-c3777b4a6c62":{"길":"각 변의 길이를 삼각비 정의로 확인해 선지를 하나씩 검증한다","단계":[{"제목":"x, y에 대한 삼각비를 변의 길이로 읽기","힌트":"반지름이 1인 부채꼴에서 x, y에 대응하는 변의 길이는 각각 무슨 삼각비일까?","식":[],"설명":"그림에 표시된 각 변의 길이가 sinx°, cosx°, siny°, cosy° 값이 된다.","확인":null,"스킬":"T5"},{"제목":"①~④ 선지 값 정정하기","고비":true,"힌트":"그림의 실제 값을 대입하면 ①~④는 어떻게 바뀔까?","식":["$\\sin x^\\circ=0.54,\\ \\cos x^\\circ=0.83,\\ \\cos y^\\circ=0.5,\\ \\sin y^\\circ=0.87$"],"설명":"그림에서 읽은 실제 값은 제시된 선지와 달라 ①~④는 모두 옳지 않다.","확인":null,"스킬":"T5"},{"제목":"정답 확정하기","힌트":"남은 선지 tanx°=0.65는 그림의 값과 같을까?","식":[],"설명":"그림에서 tanx°에 해당하는 값이 0.65와 일치하므로 ⑤가 옳다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-c39c2b777e89":{"길":"볼록한 방향, y절편, 대칭축의 위치를 차례로 읽어 a, b, c의 부호를 정한다","단계":[{"제목":"a의 부호 판별하기","힌트":"그래프가 아래로 볼록하면 a는?","식":[],"설명":"아래로 볼록한 그래프이므로 a>0이다.","확인":null,"스킬":"A6"},{"제목":"c의 부호 판별하기","힌트":"y절편은 -c인데, 그래프의 y절편 부호는?","식":["$-c>0\\Rightarrow c<0$"],"설명":"y절편이 양수이므로 -c>0에서 c<0이다.","확인":null,"스킬":"A6"},{"제목":"b의 부호 판별하기","고비":true,"힌트":"대칭축 b/2a의 부호로 b를 정하면?","식":["$\\frac{b}{2a}>0\\Rightarrow b>0$"],"설명":"대칭축이 y축의 오른쪽에 있으므로 b/2a>0이고, a>0이므로 b>0이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-c582cf7ef96b":{"길":"두 암호의 이차식을 각각 인수분해해 부호화하고 표에서 문자를 찾아 단어를 완성한다","단계":[{"제목":"첫 암호의 두 식 인수분해하기","힌트":"x²-2x-3과 x²+3x+2를 인수분해하면?","식":["$x^2-2x-3=(x-3)(x+1)$","$x^2+3x+2=(x+2)(x+1)$"],"설명":"암호 (-2,-3), (3,2)로 만든 두 이차식을 각각 인수분해한다.","확인":null,"스킬":"A4"},{"제목":"부호화해 표에서 문자 찾기","고비":true,"힌트":"인수분해된 두 수의 짝을 표에서 찾으면?","식":["$(x-3)(x+1)\\to(-3,1)\\to$ㅁ","$(x+2)(x+1)\\to(2,1)\\to$ㅣ"],"설명":"표에서 (-3,1)은 ㅁ, (2,1)은 ㅣ이므로 첫 암호는 '미'이다.","확인":null,"스킬":"C6"},{"제목":"둘째 암호도 같은 방법으로 풀기","힌트":"x²-5x+6과 x²+2x-3을 인수분해하면?","식":["$x^2-5x+6=(x-2)(x-3)\\to(-2,-3)\\to$ㄴ","$x^2+2x-3=(x+3)(x-1)\\to(3,-1)\\to$ㅕ"],"설명":"둘째 암호는 '녀'가 되어 두 글자를 합치면 '미녀'이다.","확인":null,"스킬":"C6"}],"fb":"fig/ns/"},"ns-c72f9d95b335":{"길":"10등분된 호에서 원주각이 호의 비율에 비례하는 공식을 그대로 적용한다","단계":[{"제목":"공식 적용하기","힌트":"원주각의 크기는 호의 길이에 비례한다면 칸 수를 그대로 넣으면?","식":["$x=180^{\\circ}\\times\\frac{2}{10}=36^{\\circ}$","$y=180^{\\circ}\\times\\frac{3}{10}=54^{\\circ}$"],"설명":"원주각의 크기와 호의 길이는 비례하므로 칸 수의 비율을 그대로 곱한다.","확인":null,"스킬":"S5"},{"제목":"x+y 구하기","고비":true,"힌트":"36°와 54°를 더하면?","식":["$x+y=36^{\\circ}+54^{\\circ}=90^{\\circ}$"],"설명":"두 값을 더하면 90°이다.","확인":"90","스킬":"S5"}],"fb":"fig/ns/"},"ns-c860de59185c":{"길":"정사각형 넓이로 한 변의 길이를 구해 수직선 좌표를 정하고 인수분해로 계산한다","단계":[{"제목":"정사각형 넓이로 한 변 구하기","힌트":"모눈에서 정사각형 ABCD의 넓이는?","식":["$\\square ABCD=5$","$\\overline{AB}=\\overline{AD}=\\sqrt5$"],"설명":"모눈에서 정사각형의 넓이를 세면 5이므로 한 변의 길이는 √5이다.","확인":null,"스킬":"S3"},{"제목":"수직선 위 좌표 구하기","힌트":"AQ=AB, AP=AD만큼 각각 오른쪽·왼쪽으로 옮기면?","식":["$a=2-\\sqrt5,\\ b=2+\\sqrt5$"],"설명":"기준점에서 √5만큼 좌우로 옮긴 점이 P, Q이다.","확인":null,"스킬":"N8"},{"제목":"식을 인수분해로 정리하기","고비":true,"힌트":"(a-b)a²+(b-a)b²를 묶으면?","식":["$(a-b)a^2+(b-a)b^2=(a-b)(a^2-b^2)=(a-b)^2(a+b)$"],"설명":"식을 인수분해하면 (a-b)²(a+b) 꼴이 되어 계산이 간단해진다.","확인":null,"스킬":"A2"},{"제목":"값을 대입해 계산하기","힌트":"a-b=-2√5, a+b=4를 대입하면?","식":["$(-2\\sqrt5)^2\\times4=20\\times4=80$"],"설명":"값을 대입하면 결과는 80이다.","확인":"80","스킬":"A2"}],"fb":"fig/ns/"},"ns-c916784edc3c":{"길":"피타고라스 정리로 두 빗변을 구하고 선지의 삼각비를 하나씩 계산해 비교한다","단계":[{"제목":"AB, AD 길이 구하기","힌트":"직각삼각형 ABC와 ADC에서 피타고라스 정리를 쓰면?","식":["$\\overline{AB}=\\sqrt{3^2+1^2}=\\sqrt{10}$","$\\overline{AD}=\\sqrt{2^2+1^2}=\\sqrt5$"],"설명":"두 직각삼각형에서 각각 빗변 AB, AD를 구한다.","확인":null,"스킬":"S3"},{"제목":"①~③ 선지 계산하기","힌트":"sinx, cosx, tanx를 각각 AC, BC, AB로 나타내면?","식":["$\\sin x=\\dfrac{\\sqrt{10}}{10},\\ \\cos x=\\dfrac{3\\sqrt{10}}{10},\\ \\tan x=\\dfrac13$"],"설명":"①②③을 계산한 값이 선지와 달라 모두 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"④, ⑤ 선지 계산하기","고비":true,"힌트":"siny, tany를 AD, DC로 나타내면?","식":["$\\sin y=\\dfrac{\\overline{AC}}{\\overline{AD}}=\\dfrac{\\sqrt5}{5},\\ \\tan y=\\dfrac{\\overline{AC}}{\\overline{DC}}=\\dfrac12$"],"설명":"④는 계산값과 선지가 일치해 옳고, ⑤는 값이 달라 옳지 않다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-c9489edb4faa":{"길":"꼭짓점을 이용해 식을 세우고 y절편 조건으로 a를 구한 뒤 방정식을 푼다","단계":[{"제목":"꼭짓점으로 식 세우기","힌트":"그래프의 꼭짓점이 (2,50)이면 이차함수는 어떤 꼴일까?","식":["$y=a(x-2)^2+50$"],"설명":"꼭짓점의 좌표가 (2,50)이므로 이차함수를 꼭짓점 형태로 세운다.","확인":null,"스킬":"A6"},{"제목":"y절편으로 a 구하기","고비":true,"힌트":"쏘아 올린 높이가 30m라는 조건, 즉 x=0일 때 y=30을 대입하면?","식":["$30=a(0-2)^2+50$","$a=-5$"],"설명":"지상 30m에서 쏘았으므로 y절편이 30이다. 대입해 정리하면 a=-5이다.","확인":"-5","스킬":"A3"},{"제목":"방정식을 세워 풀기","힌트":"땅에 떨어질 때 y=0이라는 조건을 대입하면?","식":["$-5(x-2)^2+50=0$","$x^2-4x-6=0$","$x=2+\\sqrt{10}$"],"설명":"y=0을 대입해 정리하면 x²-4x-6=0이 되고, 근의 공식으로 풀면 x>0인 근은 2+√10이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-cdb1dd3a855f":{"길":"접선의 길이가 같다는 성질로 각 구간을 미지수로 연결해 사슬을 따라간다","단계":[{"제목":"공통접선 길이를 미지수로 놓기","힌트":"AG,AH,AI,AJ,AK는 모두 같은 점에서 그은 접선일까?","식":["$\\overline{AG}=\\overline{AH}=\\overline{AI}=\\overline{AJ}=\\overline{AK}=x$"],"설명":"한 점 A에서 그은 접선의 길이는 모두 같으므로 다섯 선분을 x로 놓는다.","확인":null,"스킬":"S5"},{"제목":"이웃한 접선 길이를 x로 나타내기","고비":true,"힌트":"BG, CL, DM, EN, FO를 각각 x로 나타내면?","식":["$\\overline{BG}=17-x,\\ \\overline{CL}=x-3,\\ \\overline{DM}=14-x,\\ \\overline{EN}=x-6,\\ \\overline{FO}=11-x$"],"설명":"각 변의 길이 조건에서 나머지 접선 길이를 x에 대한 식으로 정리한다.","확인":null,"스킬":"S5"},{"제목":"AF 길이 구하기","힌트":"AK와 FO를 더하면 x가 사라질까?","식":["$\\overline{AF}=\\overline{AK}+\\overline{FO}=x+(11-x)=11$"],"설명":"AK와 FO를 더하면 x가 소거되어 AF=11이 바로 구해진다.","확인":"11","스킬":"S5"}],"fb":"fig/ns/"},"ns-cdde9b68e251":{"길":"직사각형의 두 극단 꼭짓점을 지날 때의 a를 구해 범위를 잡고, 범위 밖의 값을 고른다","단계":[{"제목":"좁을 때(4,1)를 지날 조건 구하기","힌트":"폭이 좁을 때, 즉 점 (4,1)을 지날 조건은?","식":["$1<16a$","$\\therefore \\frac{1}{16}<a$"],"설명":"그래프가 점 (4,1)보다 좁아야 하므로 16a>1, 즉 a>1/16이다.","확인":null,"스킬":"C2"},{"제목":"넓을 때(2,4)를 지날 조건 구하기","고비":true,"힌트":"폭이 넓을 때, 즉 점 (2,4)를 지날 조건은?","식":["$4>4a$","$\\therefore a<1$"],"설명":"그래프가 점 (2,4)보다 넓어야 하므로 4a<4, 즉 a<1이다.","확인":null,"스킬":"C2"},{"제목":"범위 정하고 아닌 값 고르기","힌트":"두 조건을 합치면 a의 범위는?","식":["$\\frac{1}{16}<a<1$"],"설명":"두 조건을 합치면 1/16<a<1이어야 하는데, 선지 중 a=1은 이 범위에 속하지 않으므로 옳지 않다.","확인":"1","스킬":"C2"}],"fb":"fig/ns/"},"ns-cf0bc439482b":{"길":"일차함수의 x절편, y절편으로 a,b를 구하고 이차함수의 꼭짓점과 폭을 확인한다","단계":[{"제목":"a,b 구하기","힌트":"x절편이 4, y절편이 3이면 a,b는?","식":["$b=3$","$a=-\\frac{3}{4}$"],"설명":"일차함수 y=ax+b의 x절편이 4, y절편이 3이므로 b=3이고, 0=4a+3에서 a=-3/4이다.","확인":null,"스킬":"G9"},{"제목":"이차함수 식 완성하기","힌트":"구한 a,b를 y=a(x+b)²+b/a에 대입하면?","식":["$y=-\\frac{3}{4}(x+3)^2-4$"],"설명":"a=-3/4, b=3을 대입하면 이차함수는 y=-3/4(x+3)²-4이다.","확인":null,"스킬":"A3"},{"제목":"x축과의 관계, 볼록 방향 판별하기","고비":true,"힌트":"이 그래프는 x축과 만날까, 어떤 방향으로 볼록할까?","식":[],"설명":"이차항 계수가 음수이므로 위로 볼록하고, 꼭짓점 y좌표가 음수이므로 x축과 만나지 않으며, 축은 x=-3이다.","확인":null,"스킬":"A6"},{"제목":"꼭짓점과 폭 비교로 답 정하기","힌트":"꼭짓점 좌표와 y=-1/2x²과의 폭 비교는?","식":["$\\left|-\\frac{3}{4}\\right|>\\left|-\\frac{1}{2}\\right|$"],"설명":"꼭짓점의 좌표는 (-3,-4)이고, 이차항 계수의 절댓값이 더 크므로 y=-1/2x²보다 폭이 좁다. 따라서 옳은 것은 꼭짓점 좌표뿐이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-d02ace9e3bd0":{"길":"빗변에 매번 2/√3을 곱하는 규칙을 찾아 반복 계산한다","단계":[{"제목":"비율 규칙 찾기","힌트":"직각삼각형마다 빗변이 이전 변의 몇 배가 될까?","식":["$\\overline{BO}=\\dfrac{3}{\\cos30^\\circ}=2\\sqrt3$"],"설명":"직각삼각형 OAB에서 cos30°로 나누면 다음 빗변이 되므로, 매번 2/√3배가 되는 규칙을 찾는다.","확인":null,"스킬":"P1"},{"제목":"CO, DO, EO 구하기","힌트":"같은 규칙을 세 번 더 적용하면?","식":["$\\overline{CO}=4,\\ \\overline{DO}=\\dfrac{8\\sqrt3}{3},\\ \\overline{EO}=\\dfrac{16}{3}$"],"설명":"같은 비율을 반복해 CO, DO, EO를 차례로 구한다.","확인":null,"스킬":"P1"},{"제목":"FO, GO 구하기","고비":true,"힌트":"같은 규칙을 두 번 더 적용하면?","식":["$\\overline{FO}=\\dfrac{32\\sqrt3}{9},\\ \\overline{GO}=\\dfrac{64}{9}$"],"설명":"규칙을 놓치지 않고 이어가야 FO, GO를 정확히 구할 수 있다.","확인":null,"스킬":"P1"},{"제목":"HO 계산하기","힌트":"마지막으로 한 번 더 규칙을 적용하면?","식":["$\\overline{HO}=\\dfrac{64}{9}\\times\\dfrac{2}{\\sqrt3}=\\dfrac{128\\sqrt3}{27}$"],"설명":"규칙을 마지막으로 적용해 HO를 구한다.","확인":null,"스킬":"P1"}],"fb":"fig/ns/"},"ns-d09e4fe3dbbd":{"길":"직각삼각형 두 개에서 각 x, y의 여각 관계를 찾고 네 식을 각각 삼각비 정의로 확인한다","단계":[{"제목":"x와 y의 관계 찾기","힌트":"∠CDH와 ∠DCH를 통해 x와 y를 연결하면?","식":["$\\angle x+\\angle CDH=90^\\circ,\\ \\angle CDH+\\angle DCH=90^\\circ\\Rightarrow\\angle DCH=\\angle x$"],"설명":"두 관계식을 연결하면 ∠DCH=∠x이고, 이는 곧 ∠x+∠y=90°임을 뜻한다.","확인":null,"스킬":"S10"},{"제목":"㈎ 확인하기","힌트":"직각삼각형 ABC에서 siny는?","식":["$\\sin y=\\dfrac{\\overline{AB}}{\\overline{AC}}=\\dfrac{1}{\\overline{AC}}$"],"설명":"직각삼각형 ABC에서 siny를 구하면 제시된 ㈎와 일치한다.","확인":null,"스킬":"S6"},{"제목":"㈏, ㈐ 확인하기","고비":true,"힌트":"직각삼각형 CDH에서 cosx와 tany는 실제로 무엇일까?","식":["$\\cos x=\\dfrac{\\overline{CH}}{\\overline{CD}},\\ \\tan y=\\dfrac{\\overline{CH}}{\\overline{DH}}$"],"설명":"실제 값은 ㈏, ㈐에 제시된 것과 분모·분자가 달라 둘 다 옳지 않다.","확인":null,"스킬":"S6"},{"제목":"㈑ 확인하기","힌트":"직각삼각형 CDH에서 tanx는?","식":["$\\tan x=\\dfrac{\\overline{HD}}{\\overline{CH}}$"],"설명":"직각삼각형 CDH에서 tanx를 구하면 ㈑와 일치하므로 옳은 것은 ㈎, ㈑이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-db986aa181d8":{"길":"평균과 분산 조건을 각각 식으로 세워 연립한 뒤 이차방정식을 푼다","단계":[{"제목":"평균 조건으로 a를 m으로 나타내기","힌트":"다섯 값의 합을 5로 나누면 m이라는 조건을 a에 대해 풀면?","식":["$\\frac{3+5+1+6+a}{5}=m$","$a=5m-15$"],"설명":"평균 조건을 정리해 a를 m에 대한 식으로 나타낸다.","확인":null,"스킬":"A10"},{"제목":"분산 공식으로 두 번째 식 세우기","힌트":"분산은 제곱의 평균에서 평균의 제곱을 뺀 값이다. 이를 식으로 쓰면?","식":["$\\frac{9+25+1+36+a^2}{5}-m^2=9.2$","$5m^2-a^2=25$"],"설명":"분산 공식을 이용해 a와 m의 관계식을 세운다.","확인":null,"스킬":"A10"},{"제목":"두 식을 연립해 이차방정식 만들기","힌트":"a=5m-15를 대입하면?","식":["$5m^2-(5m-15)^2=25$","$2m^2-15m+25=0$"],"설명":"a를 대입해 정리하면 m에 대한 이차방정식이 나온다.","확인":null,"스킬":"A2","고비":true},{"제목":"이차방정식을 풀어 m 정하기","힌트":"인수분해하면 m의 값은?","식":["$(2m-5)(m-5)=0$","$m=5\\ (\\because\\,a는\\ 자연수)$"],"설명":"인수분해하면 m은 5/2 또는 5인데, a가 자연수가 되려면 m=5여야 한다.","확인":null,"스킬":"A2"},{"제목":"a와 m을 더해 답 구하기","힌트":"m=5일 때 a는?","식":["$a=5\\times5-15=10$","$a+m=15$"],"설명":"m=5일 때 a=10이므로 a+m은 15이다.","확인":"15","스킬":"A10"}],"fb":"fig/ns/"},"ns-dd5b3401376b":{"길":"특수각의 삼각비 값을 대입해 세 식을 각각 계산하고 크기를 비교한다","단계":[{"제목":"(가) 계산하기","힌트":"tan45°, cos30°, tan60°의 값을 대입하면?","식":["$2\\tan45^\\circ-\\cos30^\\circ\\times\\tan60^\\circ=2-\\dfrac{\\sqrt3}2\\times\\sqrt3=\\dfrac12$"],"설명":"특수각의 값을 대입해 (가)를 계산한다.","확인":"1/2","스킬":"S6"},{"제목":"(나) 계산하기","힌트":"나눗셈과 곱셈의 순서를 지켜 계산하면?","식":["$2\\sin60^\\circ-3\\tan30^\\circ\\div\\sin45^\\circ\\times\\cos45^\\circ=0$"],"설명":"연산 순서를 지켜 계산하면 (나)는 0이다.","확인":"0","스킬":"S6"},{"제목":"(다) 계산하기","고비":true,"힌트":"tan0°는 0임에 주의하며 계산하면?","식":["$\\tan0^\\circ\\times\\sin90^\\circ-2(2-\\cos60^\\circ+\\cos0^\\circ)=-5$"],"설명":"tan0°=0이므로 첫 항은 0이 되고, 나머지를 계산하면 (다)는 -5이다.","확인":"-5","스킬":"S6"},{"제목":"크기 순서대로 나열하기","힌트":"1/2, 0, -5를 작은 순서로 나열하면?","식":["$-5<0<\\dfrac12\\Rightarrow(다)-(나)-(가)$"],"설명":"세 값을 비교하면 작은 순서는 (다)-(나)-(가)이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-dde698887002":{"길":"접선과 반지름이 수직임을 이용해 두 직각삼각형에서 각각 tan a를 표현한다","단계":[{"제목":"△DOA에서 tan a 표현하기","힌트":"직각삼각형 DOA에서 OA=1일 때 tan a는 어떤 변의 길이와 같을까?","식":["$\\tan a=\\frac{\\overline{DA}}{\\overline{OA}}=\\overline{DA}$"],"설명":"OA=1이므로 tan a는 DA의 길이와 같다.","확인":null,"스킬":"T5"},{"제목":"△BOG에서 tan a 표현하기","고비":true,"힌트":"점 B가 접점이므로 FG와 OB는 어떤 관계일까?","식":["$\\overline{FG}\\perp\\overline{OB}$","$\\tan a=\\frac{\\overline{BG}}{\\overline{OB}}=\\overline{BG}$"],"설명":"접선은 접점을 지나는 반지름과 수직이므로 △BOG도 직각삼각형이 되어 tan a는 BG의 길이와 같다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-dee7beb9b26f":{"길":"두 이차함수를 완전제곱으로 정리해 꼭짓점을 구하고, y좌표가 같다는 조건으로 k를 구한다","단계":[{"제목":"첫 함수의 꼭짓점 구하기","힌트":"y=2x²-12x+3k+1을 완전제곱으로 정리하면?","식":["$y=2(x-3)^2+3k-17$"],"설명":"완전제곱으로 정리하면 꼭짓점은 (3, 3k-17)이다.","확인":null,"스킬":"A6"},{"제목":"둘째 함수의 꼭짓점과 조건식 세우기","고비":true,"힌트":"y=-5(x+2)²+25-4k의 꼭짓점은? 두 꼭짓점의 y좌표가 같다면?","식":["$(-2,\\ 25-4k)$","$3k-17=25-4k$"],"설명":"둘째 함수의 꼭짓점은 (-2, 25-4k)이고, 두 꼭짓점을 이은 직선이 x축과 평행하려면 두 y좌표가 같아야 한다.","확인":null,"스킬":"A3"},{"제목":"방정식을 풀어 k 구하기","힌트":"7k=42를 풀면?","식":["$3k-17=25-4k$","$7k=42,\\ k=6$"],"설명":"방정식을 풀면 k=6이다.","확인":"6","스킬":"A3"}],"fb":"fig/ns/"},"ns-dfe74ad0936c":{"길":"x가 작아질 때 y=90°-x와 tan y가 어떻게 변하는지 살펴본다","단계":[{"제목":"x와 y의 관계 정리하기","힌트":"직각삼각형에서 x+y는 얼마일까?","식":["$x+y=90^{\\circ}$"],"설명":"y=90°-x이므로 x가 작아지면 y는 커진다.","확인":null,"스킬":"T5"},{"제목":"tan y의 증감 판단하기","고비":true,"힌트":"y가 커지면 tan y는 어떻게 변할까?","식":[],"설명":"0°~90° 사이에서 각이 커지면 tan 값도 커지므로 tan y도 커진다. 따라서 ⑤는 옳지 않다.","확인":null,"스킬":"T5"}],"fb":"fig/ns/"},"ns-e0069d94c33a":{"길":"두 수선의 발 M, N을 잡아 닮은 두 직각삼각형의 비례식으로 EF를 구한다","단계":[{"제목":"AM 구하기","힌트":"점 A에서 CD에 내린 수선의 발 M을 잡으면 △AMD는?","식":["$\\overline{AM}=1\\times\\sin60^{\\circ}=\\frac{\\sqrt3}{2}$"],"설명":"직각삼각형 AMD에서 ∠ADM=60°이므로 AM을 구한다.","확인":null,"스킬":"S3"},{"제목":"AE 구하기","힌트":"직각삼각형 ADE에서 AE는?","식":["$\\overline{AE}=\\sqrt{1^2+1^2}=\\sqrt2$"],"설명":"∠ADE=90°이므로 피타고라스 정리로 AE를 구한다.","확인":null,"스킬":"S3"},{"제목":"EN 구하기","힌트":"점 E에서 DF에 내린 수선의 발 N을 잡으면 △EDN은?","식":["$\\overline{EN}=1\\times\\sin30^{\\circ}=\\frac12$"],"설명":"직각삼각형 EDN에서 ∠EDN=30°이므로 EN을 구한다.","확인":null,"스킬":"S3"},{"제목":"닮음비로 비례식 세우기","고비":true,"힌트":"△AMF와 △ENF는 왜 닮음일까?","식":["$\\overline{AM}:\\overline{AF}=\\overline{EN}:\\overline{EF}$"],"설명":"두 직각삼각형이 서로 닮음이므로 EF=x로 놓고 비례식을 세운다.","확인":null,"스킬":"S1"},{"제목":"비례식 풀어 정리하기","힌트":"비례식을 정리하면 x에 대한 방정식은?","식":["$\\frac{\\sqrt3}{2}:(\\sqrt2+x)=\\frac12:x$","$\\frac{\\sqrt3-1}{2}x=\\frac{\\sqrt2}{2}$"],"설명":"비례식을 정리해 x에 대한 방정식을 세운다.","확인":null,"스킬":"A2"},{"제목":"EF 값 구하기","힌트":"방정식을 풀어 x를 구하면?","식":["$x=\\frac{\\sqrt2}{\\sqrt3-1}=\\frac{\\sqrt6+\\sqrt2}{2}$"],"설명":"분모를 유리화하면 EF의 값을 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-e41558363dea":{"길":"FG:GH:DH의 비를 문자로 놓고 피타고라스 정리를 두 번 적용해 cos x를 구한다","단계":[{"제목":"변의 길이를 비율로 놓기","힌트":"FG:GH:DH=3:2:1이므로 DH=a로 놓으면?","식":["$\\overline{FG}=3a,\\ \\overline{GH}=2a,\\ \\overline{DH}=a$"],"설명":"주어진 비를 문자 a로 나타낸다.","확인":null,"스킬":"A8"},{"제목":"FH 구하기","힌트":"직각삼각형 FGH에서 FH는?","식":["$\\overline{FH}=\\sqrt{(3a)^2+(2a)^2}=\\sqrt{13}a$"],"설명":"피타고라스 정리로 FH를 구한다.","확인":null,"스킬":"S3"},{"제목":"FD 구하기","고비":true,"힌트":"FH와 DH로 직각삼각형 FHD에서 FD를 구하면?","식":["$\\overline{FD}=\\sqrt{(\\sqrt{13}a)^2+a^2}=\\sqrt{14}a$"],"설명":"직각삼각형 FHD에서 피타고라스 정리로 FD를 구한다.","확인":null,"스킬":"S3"},{"제목":"cos x 값 구하기","힌트":"cos x=FH/FD는?","식":["$\\cos x=\\frac{\\sqrt{13}a}{\\sqrt{14}a}=\\frac{\\sqrt{182}}{14}$"],"설명":"삼각비 정의로 cos x를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-e5016777cc89":{"길":"호의 비로 두 원주각을 구한 뒤 삼각형의 내각의 합으로 x를 구한다","단계":[{"제목":"두 원주각 구하기","힌트":"호의 비는 원주각의 비와 같을까?","식":["$\\angle ADC=90^\\circ\\times\\frac{5}{9}=50^\\circ$","$\\angle BAD=90^\\circ\\times\\frac{2}{5}=36^\\circ$"],"설명":"지름에 대한 원주각 90°를 호의 비로 나누어 두 원주각을 구한다.","확인":null,"스킬":"S5"},{"제목":"삼각형에서 x 구하기","고비":true,"힌트":"AB와 CD의 교점을 P라 하면 △PAD의 내각의 합은?","식":["$\\angle x=180^\\circ-(36^\\circ+50^\\circ)=94^\\circ$"],"설명":"삼각형의 내각의 합이 180°임을 이용해 x를 구한다.","확인":"94","스킬":"S10"}],"fb":"fig/ns/"},"ns-e76f3771178a":{"길":"세 그래프의 값이 퍼진 정도를 비교해 표준편차의 크기 순서를 정한다","단계":[{"제목":"분포의 퍼짐 정도 살펴보기","힌트":"값이 가운데 몰려 있을수록, 고르게 퍼져 있을수록 표준편차는 어떻게 다를까?","식":[],"설명":"자료가 평균 주위에 고르게 모여 있을수록 표준편차는 작고, 넓게 퍼질수록 표준편차는 크다.","확인":null,"스킬":"P4"},{"제목":"세 그래프 비교하기","고비":true,"힌트":"A, B, C 중 가장 고르게 모인 것과 가장 퍼진 것은?","식":[],"설명":"A는 가운데 값에 가장 많이 모여 있어 표준편차가 가장 작고, B는 모든 값에 고르게 퍼져 있어 표준편차가 가장 크다.","확인":null,"스킬":"P4"},{"제목":"대소 관계 정리하기","힌트":"a, b, c를 작은 순서로 나열하면?","식":["$a<c<b$"],"설명":"표준편차는 a<c<b 순서다.","확인":null,"스킬":"P4"}],"fb":"fig/ns/"},"ns-ee8964b2e938":{"길":"중심각·호·원주각의 표준 성질을 확인하고 현의 길이는 비례하지 않음을 가려낸다","단계":[{"제목":"①③④ 판별하기","힌트":"호의 길이는 중심각에 비례하고, 지름에 대한 원주각은 90°, 중심각은 원주각의 2배일까?","식":[],"설명":"호AB의 중심각은 60°, 호AD의 중심각은 180°이므로 ①은 참이다. AD가 지름이므로 ∠ABD=90°로 ③도 참이고, 중심각은 원주각의 2배이므로 ④도 참이다.","확인":null,"스킬":"S5"},{"제목":"② 판별하기","고비":true,"힌트":"중심각의 크기와 현의 길이는 정비례할까?","식":[],"설명":"현의 길이는 중심각의 크기에 정비례하지 않으므로 AB=(1/2)BD는 성립하지 않는다. ②가 옳지 않다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-f1a3134c4a1d":{"길":"접선 길이로 R을 구하고 피타고라스로 두 내접원의 반지름을, 좌표 관계로 두 중심 사이 거리를 구한다","단계":[{"제목":"원 O'의 반지름을 R로 놓고 접선 길이 정리하기","힌트":"AB=CD=2R이고, AH, EH는 각각 어떻게 나타낼까?","식":["$\\overline{AB}=\\overline{CD}=2R$","$\\overline{AH}=12-R,\\ \\overline{EH}=4-R$"],"설명":"직사각형에서 AB=CD=2R이고, 접선의 길이가 같다는 성질로 AH, EH를 R에 대한 식으로 나타낸다.","확인":null,"스킬":"S5"},{"제목":"피타고라스 정리로 R 구하기","고비":true,"힌트":"△ABE에서 AB, BE, AE를 R로 나타내 피타고라스 정리를 세우면?","식":["$\\overline{AB}=2R,\\ \\overline{BE}=8,\\ \\overline{AE}=16-2R$","$4R^2+64=(16-2R)^2\\ \\Rightarrow\\ R=3$"],"설명":"직각삼각형 ABE에 피타고라스 정리를 적용해 R=3을 구한다.","확인":null,"스킬":"S3"},{"제목":"원 O의 반지름 구하기","힌트":"AB=6,BE=8,AE=10인 직각삼각형에서 내접원 반지름은?","식":["$3r+4r+5r=24\\ \\Rightarrow\\ r=2$"],"설명":"넓이를 두 가지로 표현해 내접원의 반지름 r=2를 구한다. ①은 3/2라 하여 옳지 않다.","확인":null,"스킬":"S8"},{"제목":"②③ 판별하기","힌트":"두 원의 넓이의 합과 삼각형의 둘레를 계산하면?","식":["$4\\pi+9\\pi=13\\pi$","$6+8+10=24$"],"설명":"두 원의 넓이의 합은 13π로 ②가 참이고, △ABE의 둘레는 24로 ③도 참이다.","확인":null,"스킬":"S8"},{"제목":"OO' 길이 구하기","힌트":"점 O에서 O'I에 내린 수선의 발 P를 이용하면?","식":["$\\overline{O'P}=1,\\ \\overline{OP}=7$","$\\overline{OO'}=\\sqrt{1^2+7^2}=5\\sqrt2$"],"설명":"직각삼각형을 만들어 OO'의 길이를 구하면 5√2이므로 ④는 참, ⑤(4√3)는 옳지 않다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-f4c50dac8cd4":{"길":"잘라낸 정사각형의 변의 길이를 이용해 직육면체의 가로·세로·높이를 식으로 세운다","단계":[{"제목":"처음 직사각형의 가로·세로 정하기","힌트":"가로가 세로보다 4cm 길다면 가로를 x라 할 때 세로는?","식":["$가로=x,\\ 세로=x-4$"],"설명":"처음 직사각형의 가로를 x라 하면 세로는 x-4이다.","확인":null,"스킬":"C7"},{"제목":"직육면체의 가로·세로·높이 구하기","고비":true,"힌트":"귀퉁이 정사각형의 넓이가 4cm²이면 그 한 변(높이)은? 잘려나간 만큼 가로·세로는 얼마나 줄어들까?","식":["$높이=2$","$가로=x-4,\\ 세로=x-8$"],"설명":"귀퉁이 정사각형의 한 변은 2cm(높이)이고, 양쪽에서 2cm씩 잘려나가 직육면체의 가로는 x-4, 세로는 x-8이 된다.","확인":null,"스킬":"C7"},{"제목":"부피 조건으로 이차방정식 세우기","힌트":"부피 384cm³를 가로×세로×높이로 나타내면?","식":["$384=2(x-4)(x-8)$","$x^2-12x-160=0$"],"설명":"부피 공식으로 식을 세우고 정리하면 이차방정식을 얻는다.","확인":null,"스킬":"A3"},{"제목":"인수분해해 x 구하기","힌트":"(x-20)(x+8)=0에서 x>0인 해는?","식":["$(x-20)(x+8)=0$"],"설명":"인수분해하면 x=20 또는 x=-8인데 x>0이므로 x=20이다.","확인":"20","스킬":"N4"}],"fb":"fig/ns/"},"ns-f4cfd5ec2e93":{"길":"미지수 k를 잡아 IP²를 두 식으로 세워 풀고, 두 직각삼각형에서 sin x, cos y를 구해 더한다","단계":[{"제목":"BD, FH 구하기","힌트":"정육면체의 면의 대각선 BD, FH는?","식":["$\\overline{BD}=\\overline{FH}=3\\sqrt2$"],"설명":"한 모서리가 3인 정육면체의 면의 대각선은 3√2이다.","확인":null,"스킬":"S3"},{"제목":"ID 구하기","힌트":"BI:IF=1:2이므로 BI=1, 직각삼각형 BID에서 ID는?","식":["$\\overline{ID}=\\sqrt{(3\\sqrt2)^2+1^2}=\\sqrt{19}$"],"설명":"BD⊥BF이므로 직각삼각형 BID에서 피타고라스 정리로 ID를 구한다.","확인":null,"스킬":"S3"},{"제목":"IH 구하기","힌트":"IF=2이고 직각삼각형 FIH에서 IH는?","식":["$\\overline{IH}=\\sqrt{(3\\sqrt2)^2+2^2}=\\sqrt{22}$"],"설명":"FH⊥BF이므로 직각삼각형 FIH에서 피타고라스 정리로 IH를 구한다.","확인":null,"스킬":"S3"},{"제목":"수선의 발 P를 잡아 방정식 세우기","고비":true,"힌트":"점 I에서 DH에 내린 수선의 발을 P, HP=k라 하면 IP²를 두 가지로 쓰면?","식":["$\\overline{IP}^2=(\\sqrt{22})^2-k^2=(\\sqrt{19})^2-(3-k)^2$"],"설명":"△DIH에서 수선의 발 P를 잡아 IP²를 두 직각삼각형에서 각각 표현해 k에 대한 방정식을 세운다.","확인":null,"스킬":"S3"},{"제목":"k 값 구하기","힌트":"방정식을 정리해 k를 구하면?","식":["$6k=12\\Rightarrow k=2$"],"설명":"식을 전개해 정리하면 k=2, 즉 HP=2, PD=1이다.","확인":"2","스킬":"A3"},{"제목":"IP 구하기","힌트":"IP=√(IH²-HP²)는?","식":["$\\overline{IP}=\\sqrt{(\\sqrt{22})^2-2^2}=3\\sqrt2$"],"설명":"직각삼각형 IPH에서 피타고라스 정리로 IP를 구한다.","확인":null,"스킬":"S3"},{"제목":"sin x, cos y로 바꿔 계산하기","힌트":"x=∠IHD, y=∠IDH이므로 sin x, cos y를 IP, PD, IH, ID로 나타내면?","식":["$\\sin x+\\cos y=\\frac{\\overline{IP}}{\\overline{IH}}+\\frac{\\overline{PD}}{\\overline{ID}}=\\frac{3\\sqrt2}{\\sqrt{22}}+\\frac{1}{\\sqrt{19}}=\\frac{3\\sqrt{11}}{11}+\\frac{\\sqrt{19}}{19}$"],"설명":"직각삼각형 IPH, IPD에서 각각 sin x와 cos y를 구해 더한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-f6a7fcff0195":{"길":"두 색종이의 넓이를 완전제곱식으로 바꿔 한 변의 길이를 구하고 차를 계산한다","단계":[{"제목":"색종이 A 한 변 구하기","힌트":"4x²+4x+1을 완전제곱식으로 바꾸면?","식":["$4x^2+4x+1=(2x+1)^2$"],"설명":"A의 한 변의 길이는 2x+1이다.","확인":null,"스킬":"A6"},{"제목":"색종이 B 넓이·한 변 구하기","고비":true,"힌트":"A의 넓이에 겹치지 않는 부분을 더하면?","식":["$4x^2+4x+1+8x(4x+1)=36x^2+12x+1=(6x+1)^2$"],"설명":"B의 넓이를 완전제곱식으로 바꾸면 한 변은 6x+1이다.","확인":null,"스킬":"A6"},{"제목":"두 변의 길이 차 구하기","힌트":"6x+1에서 2x+1을 빼면?","식":["$(6x+1)-(2x+1)=4x$"],"설명":"두 색종이의 한 변의 길이의 차는 4x이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-fa12f9895100":{"길":"AD, DB를 a,b로 나타내고 합차공식으로 S1-S2를 구한다","단계":[{"제목":"AD, DB 길이 구하기","힌트":"AC의 중점 D의 위치에서 AD, DB는?","식":["$\\overline{AD}=\\frac{a+b}{2},\\ \\overline{DB}=\\frac{a-b}{2}$"],"설명":"AC=a+b이므로 중점까지 거리와 DB를 구한다.","확인":null,"스킬":"A2"},{"제목":"S1-S2 계산하기","고비":true,"힌트":"합차공식을 적용하면?","식":["$S_1-S_2=\\left(\\frac{a+b}{2}\\right)^2-\\left(\\frac{a-b}{2}\\right)^2=ab$"],"설명":"합차 공식으로 계산하면 S1-S2=ab이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-fa1e75ddbcbd":{"길":"다섯 식을 특수각 삼각비로 각각 계산해 크기를 비교한다","단계":[{"제목":"①, ② 계산하기","힌트":"특수각 삼각비를 대입해 각각 계산하면?","식":["$\\sqrt2(\\sin45^{\\circ}-\\tan45^{\\circ})+\\cos45^{\\circ}=1-\\frac{\\sqrt2}{2}$","$1-\\sin90^{\\circ}\\times\\tan45^{\\circ}\\div\\cos60^{\\circ}=-1$"],"설명":"①은 약 0.29, ②는 -1이다.","확인":null,"스킬":"S6"},{"제목":"③ 계산하기","힌트":"특수각 값을 대입해 정리하면?","식":["$\\frac{1}{\\sqrt3}\\tan30^{\\circ}+(\\sin60^{\\circ}+\\cos90^{\\circ})\\cos30^{\\circ}=\\frac13+\\frac34=\\frac{13}{12}$"],"설명":"③은 13/12이다.","확인":"13/12","스킬":"S6"},{"제목":"④ 계산하기","힌트":"직선의 기울기가 곧 tanα이므로?","식":["$\\tan\\alpha=\\frac32$"],"설명":"일차함수 3x-2y+3=0의 기울기가 3/2이므로 tanα=3/2이다.","확인":"3/2","스킬":"G9"},{"제목":"⑤ 계산하고 비교하기","고비":true,"힌트":"sin60°를 이차방정식에 대입해 a를 구하면?","식":["$4\\times\\frac34-2\\times\\frac{\\sqrt3}{2}-a=0\\Rightarrow a=3-\\sqrt3$"],"설명":"⑤는 3-√3(약 1.27)이다. 다섯 값을 비교하면 3/2=1.5가 가장 커서 ④가 답이다.","확인":null,"스킬":"N5"}],"fb":"fig/ns/"},"ns-fd5890886853":{"길":"두 원이 만나 생기는 내접사각형의 대각 성질과 접선-현의 각으로 틀린 것을 찾는다","단계":[{"제목":"③ 판별하기","힌트":"원 O'에 내접하는 사각형 CDPQ에서 ∠C와 ∠APQ는 어떤 관계일까?","식":["$\\angle C=\\angle APQ$"],"설명":"사각형 CDPQ가 원에 내접하므로 ∠C=∠APQ이고, 이는 ∠A+∠C=180°가 아님을 보여준다. ③은 틀렸다.","확인":null,"스킬":"S15"},{"제목":"⑤ 판별하기","고비":true,"힌트":"∠A=∠PQC, ∠B=∠DPQ라면 AB와 PQ는 평행일까?","식":["$\\angle A=\\angle PQC,\\ \\angle B=\\angle DPQ$"],"설명":"엇각이 서로 다른 각과 같아져 AB와 PQ는 평행이 아니다. ⑤도 틀렸다.","확인":null,"스킬":"S15"},{"제목":"나머지 판별하기","힌트":"틀린 것이 두 개(③,⑤)임을 확인했다면 ①②④는?","식":[],"설명":"틀린 것이 ③,⑤ 두 개로 확정되므로 ①,②,④는 모두 옳다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-fd7321858297":{"길":"세 점의 좌표를 한 문자 a로 나타내고 AB:BC 비 조건으로 이차방정식을 세워 둘레를 구한다","단계":[{"제목":"점 A, D, C의 좌표를 a로 나타내기","힌트":"A(a, y)라 하면 D와 C의 좌표는?","식":["$A\\left(a,\\frac{1}{3}a^2\\right),\\ D\\left(a,3a^2\\right),\\ C\\left(3a,3a^2\\right)$"],"설명":"A는 y=x²/3 위, D는 A와 x좌표가 같고 y=3x² 위, C는 D와 y좌표가 같고 y=x²/3 위의 점이다.","확인":null,"스킬":"G1"},{"제목":"AB, BC의 길이를 a로 나타내기","힌트":"가로 AB와 세로 BC의 길이는?","식":["$\\overline{AB}=\\overline{DC}=2a,\\ \\overline{BC}=\\overline{AD}=\\frac{8}{3}a^2$"],"설명":"두 변의 길이를 각각 좌표 차로 구한다.","확인":null,"스킬":"S4"},{"제목":"비 조건으로 방정식 세우기","고비":true,"힌트":"AB:BC=1:2를 비례식으로 쓰면?","식":["$2a:\\frac{8}{3}a^2=1:2$","$\\frac{8}{3}a^2-4a=0$"],"설명":"비례식을 내항과 외항의 곱으로 바꾸어 이차방정식을 만든다.","확인":null,"스킬":"A8"},{"제목":"a 값 구하기","힌트":"방정식을 풀면?","식":["$a=\\frac{3}{2}$"],"설명":"방정식을 정리해 a를 구한다.","확인":"3/2","스킬":"C7"},{"제목":"둘레 구하기","힌트":"가로와 세로 길이를 더해 2배 하면?","식":["$2\\left(2a+\\frac{8}{3}a^2\\right)=2(3+6)=18$"],"설명":"둘레의 길이는 18이다.","확인":"18","스킬":"C7"}],"fb":"fig/ns/"},"ns-025e808cf6f0":{"길":"4√7과 8-2√7의 정수부분을 각각 구해 소수부분을 만들고, 차의 부호를 가려 절댓값을 없앤다","단계":[{"제목":"4√7의 정수부분 구하기","힌트":"4√7=√112는 몇과 몇 사이일까?","식":["$10<4\\sqrt{7}=\\sqrt{112}<11$"],"설명":"정수부분은 10이므로 소수부분 a=4√7-10이다.","확인":null,"스킬":"N7"},{"제목":"8-2√7의 정수부분 구하기","힌트":"8-2√7=8-√28은 몇과 몇 사이일까?","식":["$2<8-2\\sqrt{7}<3$"],"설명":"정수부분은 2이므로 소수부분 b=6-2√7이다.","확인":null,"스킬":"N7"},{"제목":"a-b 계산하기","힌트":"a에서 b를 빼면?","식":["$a-b=(4\\sqrt{7}-10)-(6-2\\sqrt{7})=6\\sqrt{7}-16$"],"설명":"두 소수부분의 차를 계산한다.","확인":null,"스킬":"A3"},{"제목":"부호를 가려 절댓값 풀기","고비":true,"힌트":"6√7과 16 중 어느 것이 더 클까?","식":["$6\\sqrt{7}=\\sqrt{252}<\\sqrt{256}=16$"],"설명":"6√7-16<0이므로 √((a-b)²)=-(6√7-16)=16-6√7이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-03c3fbd3acf9":{"길":"합격자와 불합격자의 총점을 더해 전체 평균 방정식을 세우고 합격률을 구한다","단계":[{"제목":"전체 평균식 세우기","힌트":"합격자 수 a, 전체 학생 수 n이라 하면 전체 평균식은?","식":["$\\frac{82a+66(n-a)}{n}=70$"],"설명":"합격자와 불합격자의 총점을 더해 전체 평균 70으로 놓고 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"n과 a의 관계 구하기","고비":true,"힌트":"식을 정리하면 n은 a의 몇 배일까?","식":["$n=4a$"],"설명":"방정식을 정리하면 전체 학생 수는 합격자 수의 4배이다.","확인":null,"스킬":"A2"},{"제목":"합격률 계산하기","힌트":"a/n을 백분율로 나타내면?","식":["$\\frac{a}{4a}\\times100=25\\%$"],"설명":"합격률을 계산하면 25%이다.","확인":"25","스킬":"N6"}],"fb":"fig/ns/"},"ns-056b784fa1ce":{"길":"양변을 b²으로 나눠 a/b에 대한 이차방정식을 만들고 근의 공식으로 푼다","단계":[{"제목":"식 전개해 정리하기","힌트":"(a+b)²=5ab를 전개하면?","식":["$a^2+2ab+b^2=5ab$","$a^2-3ab+b^2=0$"],"설명":"전개해 이항하면 a²-3ab+b²=0이다.","확인":null,"스킬":"A3"},{"제목":"b²으로 나눠 비율 방정식 만들기","고비":true,"힌트":"양변을 b²으로 나누면 a/b에 대한 식은?","식":["$\\left(\\frac{a}{b}\\right)^2-3\\frac{a}{b}+1=0$"],"설명":"a/b를 미지수로 하는 이차방정식이 된다.","확인":null,"스킬":"A1"},{"제목":"근의 공식으로 풀고 조건에 맞는 근 고르기","힌트":"근의 공식으로 구한 두 값 중 a>b>0에 맞는 것은?","식":["$\\frac{a}{b}=\\frac{3\\pm\\sqrt5}{2}$"],"설명":"a>b>0이므로 a/b>1인 값을 택하면 (3+√5)/2이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-05bf8c1db0b9":{"길":"가감법으로 x,y를 a로 나타낸 뒤, 완전제곱 형태로 바꿔 0<a<3 범위에서 부호를 정한다","단계":[{"제목":"㉠에서 y 꼴 만들기","힌트":"ax-y=a³+3a를 y=...로 정리하면?","식":["$y=ax-a^{3}-3a$"],"설명":"첫째 식을 y에 대해 정리한다.","확인":null,"스킬":"A10"},{"제목":"㉡에 대입해 x 구하기","힌트":"9x-ay=3a²+81에 대입하면?","식":["$(9-a^{2})x=81-a^{4}$","$x=9+a^{2}$"],"설명":"대입해 정리하면 x=9+a²이다.","확인":null,"스킬":"A10"},{"제목":"y 값 구하기","힌트":"x=9+a²를 다시 ㉠에 넣으면?","식":["$y=6a$"],"설명":"y=6a로 정리된다.","확인":null,"스킬":"A10"},{"제목":"x-y, x+y를 완전제곱으로 바꾸기","힌트":"x-y와 x+y를 (a∓3)² 꼴로 쓰면?","식":["$x-y=(a-3)^{2},\\ x+y=(a+3)^{2}$"],"설명":"각각 완전제곱식으로 바뀐다.","확인":null,"스킬":"A6"},{"제목":"0<a<3 범위로 부호 정하기","고비":true,"힌트":"a-3과 a+3의 부호는 이 범위에서 어떨까?","식":["$\\sqrt{(a-3)^{2}}=3-a,\\ \\sqrt{(a+3)^{2}}=a+3$"],"설명":"0<a<3이므로 a-3<0, a+3>0이다.","확인":null,"스킬":"C2"},{"제목":"최종 값 계산하기","힌트":"(3-a)-(a+3)은?","식":["$(3-a)-(a+3)=-2a$"],"설명":"√(x-y)-√(x+y)=-2a이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-0e99b5cb640e":{"길":"식을 인수분해한 뒤 주사위 눈의 범위에서 만족하는 순서쌍을 센다","단계":[{"제목":"식을 인수분해 꼴로 바꾸기","힌트":"xy-4y-2x+8을 묶어 인수분해하면?","식":["$xy-4y-2x+8=(x-4)(y-2)$"],"설명":"식을 두 인수의 곱으로 바꾼다.","확인":null,"스킬":"N4"},{"제목":"자연수가 되는 (x-4)(y-2) 값 찾기","고비":true,"힌트":"√((x-4)(y-2))가 자연수가 되려면 이 곱은 어떤 수여야 할까?","식":["$(x-4)(y-2)=1\\ 또는\\ 4$"],"설명":"제곱수가 되어야 하므로 곱의 값은 1 또는 4다.","확인":null,"스킬":"N8"},{"제목":"주사위 범위에서 경우 나누기","힌트":"x, y가 1~6인 범위에서 (x-4)(y-2)=1, 4가 되는 (x,y)는?","식":["$(3,1),\\ (5,3),\\ (5,6),\\ (6,4)$"],"설명":"x, y가 1~6인 조건에서 가능한 순서쌍을 모두 찾으면 4개다.","확인":"4","스킬":"P4"}],"fb":"fig/ns/"},"ns-0f457aa28a56":{"길":"근을 원래 식에 대입해 2a+1/a 값을 구하고, 제곱 항등식으로 2a-1/a를 구한다","단계":[{"제목":"근의 조건 이용해 식 변형하기","힌트":"2a²-5a+1=0의 양변을 a로 나누면?","식":["$2a-5+\\frac{1}{a}=0$","$2a+\\frac{1}{a}=5$"],"설명":"근 a가 방정식을 만족하므로 양변을 a로 나눠 정리한다.","확인":null,"스킬":"A12"},{"제목":"제곱 항등식 이용하기","고비":true,"힌트":"(2a-1/a)²과 (2a+1/a)²의 관계는?","식":["$\\left(2a-\\frac{1}{a}\\right)^2=\\left(2a+\\frac{1}{a}\\right)^2-8=17$"],"설명":"두 제곱의 차가 8임을 이용해 값을 구한다.","확인":null,"스킬":"A2"},{"제목":"값 구하기","힌트":"제곱이 17이면 원래 값은?","식":["$2a-\\frac{1}{a}=\\pm\\sqrt{17}$"],"설명":"제곱근을 취하면 ±√17이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-10148a9cf7aa":{"길":"x-y를 A로 치환해 이차방정식을 풀고, 연립방정식으로 x,y를 구한다","단계":[{"제목":"치환해 이차방정식 만들기","힌트":"x-y=A로 놓으면 조건 (3)은?","식":["$A(A-1)=12$","$A^2-A-12=0$"],"설명":"x-y를 A로 치환하면 이차방정식이 된다.","확인":null,"스킬":"A1"},{"제목":"A 값 정하기","고비":true,"힌트":"(A-4)(A+3)=0에서 x<y 조건에 맞는 A는?","식":["$(A-4)(A+3)=0$","$x-y=-3$"],"설명":"x<y이므로 x-y=-3을 택한다.","확인":null,"스킬":"C2"},{"제목":"연립방정식 풀기","힌트":"2x+y=5와 x-y=-3을 연립하면?","식":["$x=\\frac{2}{3},\\ y=\\frac{11}{3}$"],"설명":"두 식을 연립해 풀면 x=2/3, y=11/3이다.","확인":null,"스킬":"A10"}],"fb":"fig/ns/"},"ns-2c41d8cec8e6":{"길":"x=1을 대입해 t를 구한 뒤 방정식이 되는 조건으로 t를 확정하고, 다른 근의 거듭제곱 끝자리를 주기로 찾는다","단계":[{"제목":"x=1 대입해 t 구하기","힌트":"x=1을 대입하면 t에 대한 어떤 방정식이 나올까?","식":["$(t-1)-(t^2+4)+2t+3=0$","$t^2-3t+2=0$"],"설명":"x=1을 대입해 정리하면 t에 대한 이차방정식이 나온다.","확인":null,"스킬":"A3"},{"제목":"t값 구하고 조건으로 확정하기","고비":true,"힌트":"t=1이면 x²의 계수가 0이 되어 이차방정식이 아니게 된다","식":["$(t-1)(t-2)=0\\Rightarrow t=1\\ 또는\\ t=2$","$t-1\\ne0\\Rightarrow t=2$"],"설명":"t=1이면 이차방정식이 되지 않으므로 t=2로 확정한다.","확인":null,"스킬":"C2"},{"제목":"다른 근 a 구하기","힌트":"t=2를 대입한 이차방정식을 풀면?","식":["$x^2-8x+7=0$","$(x-1)(x-7)=0\\Rightarrow a=7$"],"설명":"t=2를 대입해 방정식을 풀면 다른 근 a=7을 얻는다.","확인":"7","스킬":"A2"},{"제목":"거듭제곱 끝자리 주기 찾기","힌트":"7의 거듭제곱의 일의 자리 숫자는 어떤 규칙으로 반복될까?","식":["$7^1=7,\\ 7^2=9,\\ 7^3=3,\\ 7^4=1,\\ \\cdots$"],"설명":"7의 거듭제곱의 일의 자리는 7,9,3,1이 4개씩 반복된다.","확인":null,"스킬":"N3"},{"제목":"2016번째 자리 값 구하기","힌트":"2016을 4로 나누면 나머지는?","식":["$2016=4\\times504$"],"설명":"2016이 4의 배수이므로 주기의 마지막인 1이 일의 자리 숫자가 된다.","확인":"1","스킬":"N3"}],"fb":"fig/ns/"},"ns-374f9bf28950":{"길":"이차항 계수로 나눈 뒤 완전제곱식으로 바꿔 p, q를 구한다","단계":[{"제목":"이차항 계수로 나누기","힌트":"양변을 3으로 나누면?","식":["$x^2+\\frac73x+\\frac13=0$"],"설명":"x²의 계수 3으로 양변을 나눈다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식 만들기","고비":true,"힌트":"x²+(7/3)x를 완전제곱식으로 만들려면 무엇을 더할까?","식":["$x^2+\\frac73x+\\frac{49}{36}=-\\frac13+\\frac{49}{36}$","$\\left(x+\\frac76\\right)^2=\\frac{37}{36}$"],"설명":"(7/6)²=49/36을 양변에 더해 완전제곱식으로 만든다.","확인":null,"스킬":"A6"},{"제목":"p, q 값 읽기","힌트":"(x+7/6)²=37/36에서 p, q는?","식":["$p=\\frac76,\\ q=\\frac{37}{36}$"],"설명":"완전제곱식의 꼴에서 p, q를 바로 읽는다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-4b5a3330f1a8":{"길":"13을 표의 제곱값과 비교해 범위를 좁혀 소수점 둘째 자리를 읽는다","단계":[{"제목":"표의 제곱값과 13 비교하기","힌트":"3.6², 3.61² 중 13은 어느 사이에 있을까?","식":["$3.6^2=12.96<13<13.0321=3.61^2$"],"설명":"13을 표의 제곱값과 비교하면 3.6²과 3.61² 사이에 있다.","확인":null,"스킬":"N8"},{"제목":"범위를 좁혀 자리 읽기","고비":true,"힌트":"3.6<√13<3.61이면 소수점 둘째 자리는?","식":["$3.6<\\sqrt{13}<3.61$"],"설명":"부등식에서 √13의 소수점 첫째 자리는 6, 둘째 자리는 0임을 알 수 있다.","확인":"0","스킬":"N8"}],"fb":"fig/ns/"},"ns-6dd18b656b3c":{"길":"이차항 계수를 1로 만들어 완전제곱식을 얻은 뒤 다시 계수를 맞춰 p, q를 구한다","단계":[{"제목":"이차항 계수를 1로 만들기","힌트":"양변을 2로 나누면?","식":["$x^2-2x-\\frac{5}{2}=0$"],"설명":"이차항 계수를 1로 만들기 위해 양변을 2로 나눈다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식으로 바꾸기","고비":true,"힌트":"상수항을 옮기고 제곱을 완성하려면 몇을 더해야 할까?","식":["$x^2-2x=\\frac{5}{2}$","$(x-1)^2=\\frac{7}{2}$"],"설명":"좌변에 1을 더해 완전제곱식을 만든다.","확인":null,"스킬":"A6"},{"제목":"계수 맞춰 p, q 구하기","힌트":"양변에 3을 곱하면?","식":["$3(x-1)^2=\\frac{21}{2}$","$p=-1,\\ q=\\frac{21}{2}$"],"설명":"양변에 3을 곱해 주어진 꼴에 맞추면 p, q가 정해진다.","확인":null,"스킬":"A6"},{"제목":"p+q 계산하기","힌트":"두 값을 더하면?","식":["$p+q=-1+\\frac{21}{2}=\\frac{19}{2}$"],"설명":"앞서 구한 p, q를 더한다.","확인":"19/2","스킬":"N5"}],"fb":"fig/ns/"},"ns-783f7809edcc":{"길":"모서리 평균에서 합을, 분산식을 전개해 제곱합을 구한다","단계":[{"제목":"세 모서리의 합 구하기","힌트":"12개 모서리 평균이 6이면 4(a+b+c)는?","식":["$\\frac{4(a+b+c)}{12}=6$","$a+b+c=18$"],"설명":"평균 방정식을 정리하면 a+b+c=18이다.","확인":null,"스킬":"A2"},{"제목":"분산식 세우기","고비":true,"힌트":"12개 모서리 분산이 9라는 식을 세우면?","식":["$\\frac{4\\{(a-6)^2+(b-6)^2+(c-6)^2\\}}{12}=9$","$(a-6)^2+(b-6)^2+(c-6)^2=27$"],"설명":"분산식을 정리해 편차 제곱합을 구한다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식 전개하기","힌트":"완전제곱식을 펼쳐 a²+b²+c²에 관해 정리하면?","식":["$a^2+b^2+c^2-12(a+b+c)+108=27$","$a^2+b^2+c^2-12\\times18+108=27$"],"설명":"완전제곱식을 펼쳐 12(a+b+c)=216을 대입할 준비를 한다.","확인":null,"스킬":"A6"},{"제목":"값 대입해 답 구하기","힌트":"216을 대입해 정리하면?","식":["$a^2+b^2+c^2=135$"],"설명":"정리하면 a²+b²+c²=135이다.","확인":"135","스킬":"A6"}],"fb":"fig/ns/"},"ns-8fe3432184f1":{"길":"두 방정식의 근을 구하고 무리수 크기를 좁혀 순서를 정한 뒤 분모를 유리화해 계산한다","단계":[{"제목":"두 방정식의 근을 근의 공식으로 구하기","힌트":"각 이차방정식을 근의 공식으로 풀면?","식":["$x^2-2x-4=0\\Rightarrow x=1\\pm\\sqrt5$","$x^2+4x+2=0\\Rightarrow x=-2\\pm\\sqrt2$"],"설명":"두 이차방정식을 각각 근의 공식으로 풀어 네 근을 구한다.","확인":null,"스킬":"A6"},{"제목":"무리수의 범위를 좁혀 네 근의 크기 비교하기","고비":true,"힌트":"2<√5<3, 1<√2<2를 이용하면 각 근은 어느 구간에 있을까?","식":["$-4<-2-\\sqrt2<-3,\\ -2<1-\\sqrt5<-1$","$-1<-2+\\sqrt2<0,\\ 3<1+\\sqrt5<4$"],"설명":"√5와 √2의 범위로 네 근을 정수 사이로 좁히면 -2-√2 < 1-√5 < -2+√2 < 1+√5 순서가 된다.","확인":null,"스킬":"N5"},{"제목":"a,b,c,d 정하기","힌트":"작은 것부터 a,b,c,d라 하면 b와 c는?","식":["$b=1-\\sqrt5,\\ c=-2+\\sqrt2$"],"설명":"크기 순서에 따라 b=1-√5, c=-2+√2로 정해진다.","확인":null,"스킬":"C2"},{"제목":"분모를 유리화해 계산하기","힌트":"각 분수의 분모를 유리화하면?","식":["$-\\frac1b=\\frac1{\\sqrt5-1}=\\frac{\\sqrt5+1}{4}$","$\\frac1c=\\frac1{\\sqrt2-2}=-\\frac{\\sqrt2+2}{2}$"],"설명":"두 분수를 각각 유리화한다.","확인":null,"스킬":"N6"},{"제목":"두 값을 더해 정리하기","힌트":"통분해서 더하면?","식":["$\\frac{\\sqrt5+1}{4}-\\frac{2\\sqrt2+4}{4}=\\frac{-2\\sqrt2+\\sqrt5-3}{4}$"],"설명":"분모 4로 통분해 더하면 답이 나온다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-a86f0ae4725d":{"길":"A의 중앙값으로 b를 정하고 전체를 정렬해 중앙값 식으로 a를 구한다","단계":[{"제목":"A의 중앙값으로 b 정하기","힌트":"a≥b이고 A의 중앙값이 15이면 b는?","식":["$b=15$"],"설명":"a≥b이므로 중앙값 15는 b의 자리이다.","확인":null,"스킬":"C2"},{"제목":"자료를 정리하기","힌트":"b=15를 넣으면 A, B는 각각?","식":["$A:10,14,15,a,22$","$B:11,14,a,21,22$"],"설명":"b=15를 대입해 두 자료를 정리한다.","확인":null,"스킬":"C7"},{"제목":"전체를 정렬해 중앙값 식 세우기","고비":true,"힌트":"열 개를 크기순으로 늘어놓으면 가운데 두 값은?","식":["$10,11,14,14,15,a,a,21,22,22$","$\\frac{15+a}{2}=16$"],"설명":"전체를 정렬하면 다섯·여섯 번째 값의 평균이 중앙값이므로 식을 세운다.","확인":null,"스킬":"C2"},{"제목":"a 구하고 답 계산하기","힌트":"식을 풀면 a는? a+b는?","식":["$a=17$","$a+b=17+15=32$"],"설명":"a=17이므로 a+b=32이다.","확인":"32","스킬":"A2"}],"fb":"fig/ns/"},"ns-a91841ad2693":{"길":"a값을 1부터 차례로 대입해 중앙값이 184개가 되는 때를 찾는다","단계":[{"제목":"a=1일 때 중앙값 확인하기","힌트":"편차를 크기순으로 나열하면?","식":["$-11,\\ 1,\\ 1,\\ 4,\\ 5$","$180+1=181$"],"설명":"a=1이면 편차의 가운데 값이 1이므로 중앙값은 181개이다.","확인":null,"스킬":"C2"},{"제목":"a=2일 때 중앙값 확인하기","힌트":"편차를 다시 나열하면?","식":["$-11,\\ 0,\\ 2,\\ 4,\\ 5$","$180+2=182$"],"설명":"a=2이면 중앙값은 182개로 아직 184개에 못 미친다.","확인":null,"스킬":"C2"},{"제목":"a=3일 때 중앙값 확인하기","힌트":"다시 나열하면?","식":["$-11,\\ -1,\\ 3,\\ 4,\\ 5$","$180+3=183$"],"설명":"a=3이면 중앙값은 183개로 여전히 부족하다.","확인":null,"스킬":"C2"},{"제목":"a=4일 때 중앙값 확인하고 정하기","힌트":"이번에는 편차가 어떻게 바뀔까?","식":["$-11,\\ -2,\\ 4,\\ 4,\\ 5$","$180+4=184$"],"설명":"a=4일 때 비로소 중앙값이 184개가 되므로 가장 작은 a의 값은 4이다.","확인":"4","스킬":"C2","고비":true}],"fb":"fig/ns/"},"ns-aed6b96691e5":{"길":"조건식을 x-a=b-1로 바꿔 주어진 식을 완전제곱 패턴으로 정리한 뒤 b의 이차방정식에서 근과 계수의 관계로 합을 구한다","단계":[{"제목":"조건식을 x-a=b-1로 바꾸기","힌트":"x+1=a+b를 x-a에 대해 정리하면?","식":["$x-a=b-1$"],"설명":"주어진 조건 x+1=a+b를 x-a에 대해 정리한다.","확인":null,"스킬":"A1"},{"제목":"주어진 식을 (x-a) 패턴으로 묶기","고비":true,"힌트":"x²-2ax+a²는 무엇의 제곱이고, 2x-2a는 무엇의 배수일까?","식":["$(x-a)^2+2(x-a)-3(b-1)=0$"],"설명":"x²-2ax+a²=(x-a)², 2x-2a=2(x-a)로 묶으면 식이 (x-a)에 관한 꼴로 정리된다.","확인":null,"스킬":"A1"},{"제목":"x-a=b-1을 대입해 b의 이차식으로 만들기","힌트":"(x-a) 자리에 b-1을 넣으면?","식":["$(b-1)^2+2(b-1)-3(b-1)=0$","$(b-1)(b-2)=0$"],"설명":"x-a=b-1을 대입하고 공통인수 (b-1)로 묶으면 b에 관한 방정식이 된다.","확인":null,"스킬":"A1"},{"제목":"근과 계수의 관계로 b의 합 구하기","힌트":"(b-1)(b-2)=0을 전개하면 b²-3b+2=0인데, 두 근의 합은?","식":["$b^2-3b+2=0$","$b의\\ 값의\\ 합=3$"],"설명":"이차방정식 b²-3b+2=0에서 두 근의 합은 근과 계수의 관계에 의해 3이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-b0e653f4d440":{"길":"이차방정식을 완전제곱식으로 바꾸는 과정을 단계별로 따라가며 부호가 틀린 빈칸을 찾는다","단계":[{"제목":"완전제곱식 만들기 위해 더할 항 확인하기","힌트":"x²+(2b/a)x를 완전제곱식으로 만들려면 무엇을 더해야 할까?","식":["$\\left(\\frac{b}{a}\\right)^2$"],"설명":"(가)는 x의 계수의 절반의 제곱이므로 옳다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식과 우변 정리 확인하기","힌트":"좌변이 (x+b/a)²이 되면 우변은?","식":["$\\left(x+\\frac{b}{a}\\right)^2=\\frac{b^2-ac}{a^2}$"],"설명":"(나)와 (다)는 각각 x+b/a, b²-ac로 옳게 채워져 있다.","확인":null,"스킬":"A6"},{"제목":"제곱근을 풀어 x 정리하기","고비":true,"힌트":"x+b/a=±√(b²-ac)/a에서 x를 정리하면 부호는?","식":["$x=-\\frac{b}{a}\\pm\\frac{\\sqrt{b^2-ac}}{a}$"],"설명":"이항하면 x의 앞에 -b/a가 와야 하는데 (라)는 b/a로 되어 있어 부호가 틀렸다.","확인":null,"스킬":"A6"},{"제목":"옳지 않은 것 확정하기","힌트":"부호가 빠진 (라)가 답이 되려면?","식":[],"설명":"(라)는 -b/a가 되어야 하므로 옳지 않은 것은 (라)이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-b38128db2322":{"길":"근의 공식에서 판별식이 홀수 제곱수가 되는 조건을 세우고 두 자리 범위에서 k를 모두 찾는다","단계":[{"제목":"근의 공식으로 조건 세우기","힌트":"x²-5x-k=0을 근의 공식으로 풀면?","식":["$x=\\frac{5\\pm\\sqrt{25+4k}}{2}$"],"설명":"근의 공식을 적용하면 25+4k가 근호 안에 남는다.","확인":null,"스킬":"A6"},{"제목":"제곱수 조건 정하기","고비":true,"힌트":"분모가 2이므로 근이 정수가 되려면 25+4k는 어떤 수의 제곱이어야 할까?","식":["$25+4k=(홀수)^2$ 꼴"],"설명":"5가 홀수이고 분모가 2이므로 해가 정수가 되려면 25+4k가 홀수인 자연수의 제곱이어야 한다.","확인":null,"스킬":"N8"},{"제목":"두 자리 k에 해당하는 제곱수 나열하기","힌트":"10≤k≤99에서 25+4k의 범위는?","식":["$25+4k=81,121,169,225,289,361$"],"설명":"k가 두 자리 자연수인 범위에서 조건을 만족하는 홀수 제곱수를 나열한다.","확인":null,"스킬":"P1"},{"제목":"k값을 구해 개수 세기","힌트":"각 제곱수에서 k를 구하면?","식":["$k=14,24,36,50,66,84$"],"설명":"여섯 개의 k값이 나오므로 답은 6개이다.","확인":"6","스킬":"N8"}],"fb":"fig/ns/"},"ns-c64589daa547":{"길":"첫 학생의 풀이는 완전제곱식으로, 둘째 학생의 풀이는 근의 공식으로 맞춰 네 상수를 구해 곱한다","단계":[{"제목":"첫 방정식을 완전제곱식으로 바꾸기","고비":true,"힌트":"4x²-12x+7=0을 4로 나누고 완전제곱식으로 만들면?","식":["$x^2-3x+\\frac74=0$","$\\left(x-\\frac32\\right)^2=\\frac12$"],"설명":"양변을 4로 나누고 완전제곱식으로 정리하면 a=-3/2, b=1/2이다.","확인":null,"스킬":"A6"},{"제목":"둘째 방정식을 정수 계수로 바꾸기","힌트":"0.2x²+2/5x-0.1=0의 양변에 10을 곱하면?","식":["$2x^2+4x-1=0$"],"설명":"양변에 10을 곱해 소수와 분수를 없앤다.","확인":null,"스킬":"A9"},{"제목":"근의 공식으로 c, d 구하기","힌트":"근의 공식을 적용하면 분모와 근호 안의 수는?","식":["$x=\\frac{-2\\pm\\sqrt6}{2}$"],"설명":"근의 공식으로 풀면 c=2, d=6이다.","확인":null,"스킬":"A6"},{"제목":"abcd 계산하기","힌트":"네 값을 모두 곱하면?","식":["$abcd=-\\frac32\\times\\frac12\\times2\\times6=-9$"],"설명":"네 상수를 곱하면 -9이다.","확인":"-9","스킬":"N6"}],"fb":"fig/ns/"},"ns-c6bdf255edb6":{"길":"a²-5a=-1이라는 관계로 오차식의 차수를 두 번 낮춰 계산한다","단계":[{"제목":"근의 관계식 세우기","힌트":"a가 근이므로 a²-5a+1=0에서 얻을 수 있는 식은?","식":["$a^2-5a=-1$"],"설명":"x=a를 대입하면 a²-5a+1=0이므로 a²-5a=-1이다.","확인":null,"스킬":"A12"},{"제목":"5차식에서 a²-5a 묶어 차수 낮추기","고비":true,"힌트":"a^5-7a^4를 a³(a²-5a) 형태로 묶으면?","식":["$a^5-7a^4=a^3(a^2-5a)-2a^4$","$=-a^3-2a^4$"],"설명":"a^5-7a^4를 a³(a²-5a)-2a⁴로 바꾸고 a²-5a=-1을 대입하면 -a³-2a⁴가 된다.","확인":null,"스킬":"A12"},{"제목":"4차식에서 다시 a²-5a 묶어 차수 낮추기","힌트":"-2a⁴+10a³을 -2a²(a²-5a) 형태로 묶으면?","식":["$-2a^4+10a^3=-2a^2(a^2-5a)$","$=2a^2$"],"설명":"같은 방법으로 -2a⁴+10a³을 -2a²(a²-5a)로 바꾸면 값은 2a²이다.","확인":null,"스킬":"A12"},{"제목":"남은 이차식 계산하기","힌트":"정리된 식 a²-5a-4에 a²-5a=-1을 대입하면?","식":["$a^2-5a-4=-1-4=-5$"],"설명":"모든 항을 정리하면 a²-5a-4가 남고, 여기에 a²-5a=-1을 대입하면 -5이다.","확인":"-5","스킬":"A12"}],"fb":"fig/ns/"},"ns-cc694bc34027":{"길":"근의 공식으로 두 근을 구하고 √19의 범위를 잡아 사이 정수를 센다","단계":[{"제목":"근의 공식 적용하기","힌트":"x²+8x-3=0의 두 근을 근의 공식으로 나타내면?","식":["$x=\\frac{-8\\pm\\sqrt{8^2-4\\times1\\times(-3)}}{2}=-4\\pm\\sqrt{19}$"],"설명":"근의 공식을 이용하면 두 근은 -4±√19이다.","확인":null,"스킬":"N8"},{"제목":"√19의 범위 잡기","고비":true,"힌트":"4², 5² 사이에 19가 있다면?","식":["$4<\\sqrt{19}<5$"],"설명":"16<19<25이므로 4<√19<5이다.","확인":null,"스킬":"N8"},{"제목":"두 근의 범위 구하기","힌트":"-4-√19와 -4+√19는 각각 어느 구간에 있을까?","식":["$-9<-4-\\sqrt{19}<-8$","$0<-4+\\sqrt{19}<1$"],"설명":"√19의 범위로 두 근이 있는 구간을 각각 구한다.","확인":null,"스킬":"N3"},{"제목":"두 근 사이 정수 개수 세기","힌트":"-8부터 0까지 정수는 몇 개일까?","식":["$-8,-7,\\ldots,0$"],"설명":"두 근 사이에 있는 정수는 -8부터 0까지 모두 9개이다.","확인":"9","스킬":"P4"}],"fb":"fig/ns/"},"ns-f05501e5fb9b":{"길":"세 보기를 (x+p)²=q의 근의 공식으로 하나씩 확인한다","단계":[{"제목":"ㄱ 판별하기","힌트":"q>0일 때 두 근의 합은 항상 0일까?","식":["$x=-p\\pm\\sqrt{q}$","$(두\\ 근의\\ 합)=-2p$"],"설명":"두 근의 합은 -2p이므로 p≠0이면 0이 아니다. ㄱ은 옳지 않다.","확인":null,"스킬":"A6"},{"제목":"ㄴ 판별하기","힌트":"q=0이면 근이 하나로 겹칠까?","식":["$q=0\\Rightarrow x=-p\\ (중근)$"],"설명":"q=0이면 (x+p)²=0에서 x=-p인 중근을 가지므로 ㄴ은 옳다.","확인":null,"스킬":"A6"},{"제목":"ㄷ 판별하기","고비":true,"힌트":"p=0이면 두 근은 ±√q인데 절댓값을 비교하면?","식":["$p=0\\Rightarrow x=\\pm\\sqrt{q}$"],"설명":"p=0이면 두 근이 √q, -√q로 절댓값이 같으므로 ㄷ은 옳다.","확인":null,"스킬":"A6"},{"제목":"옳은 보기 확정하기","힌트":"지금까지 확인한 결과 옳은 것은?","식":[],"설명":"옳은 것은 ㄴ, ㄷ이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-f51ca107837b":{"길":"주어진 차를 유리화해 구하고, ad+bc를 ac+bd와 (a-b)(c-d)로 바꿔 계산한다","단계":[{"제목":"a-b, c-d 값 유리화하기","힌트":"1/(2-√3)과 3/(2√3+3)을 유리화하면?","식":["$a-b=\\frac{1}{2-\\sqrt3}=2+\\sqrt3$","$c-d=\\frac{3}{2\\sqrt3+3}=2\\sqrt3-3$"],"설명":"분모를 유리화해 a-b와 c-d의 값을 구한다.","확인":null,"스킬":"N6"},{"제목":"ad+bc를 ac, bd, (a-b)(c-d)로 나타내기","고비":true,"힌트":"(a-b)(c-d)를 전개하면 ad+bc가 어떻게 나올까?","식":["$(a-b)(c-d)=ac-ad-bc+bd$","$ad+bc=ac+bd-(a-b)(c-d)$"],"설명":"(a-b)(c-d)를 전개해 ad+bc를 ac+bd에서 빼는 식으로 바꾼다.","확인":null,"스킬":"A2"},{"제목":"값 대입해 계산하기","힌트":"ac=bd=√3이고 (a-b)(c-d)의 값을 대입하면?","식":["$ad+bc=2\\sqrt3-(2+\\sqrt3)(2\\sqrt3-3)=2\\sqrt3-\\sqrt3=\\sqrt3$"],"설명":"ac+bd=2√3에서 (a-b)(c-d)를 빼면 ad+bc=√3이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-05cb19e42484":{"길":"두 삼각형이 닮음임을 보이고 비례식을 세워 이차방정식으로 AB를 구한다","단계":[{"제목":"각 구하기","힌트":"이등변삼각형의 밑각과 이등분선으로 생기는 각들은?","식":["$\\angle ABC=\\angle ACB=72^\\circ,\\ \\angle ACD=\\angle DCB=36^\\circ$"],"설명":"밑각과 이등분선으로 만들어진 각을 각각 구한다.","확인":null,"스킬":"S10"},{"제목":"닮음 찾기","고비":true,"힌트":"∠CDB=72°임을 이용하면 어떤 두 삼각형이 닮음일까?","식":["$\\angle CDB=36^\\circ+36^\\circ=72^\\circ$"],"설명":"△ABC와 △CDB는 AA닮음이다.","확인":null,"스킬":"S1"},{"제목":"비례식 세우기","힌트":"AB=x라 하면 AB:CD=BC:DB의 비례식은?","식":["$x:8=8:(x-8)$"],"설명":"닮음비로 비례식을 세운다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀어 AB 구하기","힌트":"x²-8x-64=0을 근의 공식으로 풀면?","식":["$x^2-8x-64=0$","$x=4+4\\sqrt5$"],"설명":"근의 공식으로 풀고 x>0 조건에 맞는 값을 택한다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-05e1ceee904a":{"길":"꼭짓점 대칭을 이용해 직사각형의 네 점을 한 변수로 잡고 둘레를 완전제곱으로 최적화한다","단계":[{"제목":"완전제곱 꼴로 표준화하기","힌트":"y=-2x²+16x-24를 완전제곱 꼴로 바꾸면?","식":["$y=-2(x-4)^2+8$"],"설명":"축의 방정식은 x=4이고 꼭짓점은 (4,8)이다.","확인":null,"스킬":"A6"},{"제목":"D를 변수로 잡아 A, C 좌표 나타내기","고비":true,"힌트":"D(a, -2a²+16a-24)라 하면 대칭인 A, x축 위의 C는?","식":["$A(8-a,\\ -2a^2+16a-24)$","$C(a,\\ 0)$"],"설명":"직사각형이 축 x=4에 대해 좌우대칭이므로 A의 x좌표는 8-a이고, C는 D 바로 아래 x축 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"변의 길이를 a로 나타내기","힌트":"AD와 CD의 길이는 각각 어떻게 쓸까?","식":["$\\overline{AD}=2a-8$","$\\overline{CD}=-2a^2+16a-24$"],"설명":"가로 AD는 두 x좌표의 차, 세로 CD는 D의 y좌표이다.","확인":null,"스킬":"A6"},{"제목":"둘레식 세워 완전제곱으로 최댓값 구하기","힌트":"둘레 l=2(AD+CD)를 완전제곱으로 정리하면?","식":["$l=-4a^2+36a-64=-4\\left(a-\\frac{9}{2}\\right)^2+17$"],"설명":"둘레를 a에 대한 이차식으로 세워 완전제곱으로 정리하면 최댓값은 17이다.","확인":"17","스킬":"A6"}],"fb":"fig/ns/"},"ns-118d97f1ef65":{"길":"한 변을 x로 잡아 넓이를 완전제곱으로 최적화한 뒤 둘레를 구한다","단계":[{"제목":"직사각형 변의 길이를 x로 나타내기","힌트":"EF=BF=x라 하면 HG, GC, FG는 각각 어떻게 쓸까?","식":["$\\overline{HG}=\\overline{GC}=x$","$\\overline{FG}=20-2x$"],"설명":"직각이등변삼각형의 대칭을 이용해 직사각형의 가로 FG를 x로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"넓이를 완전제곱으로 정리해 최댓값 조건 찾기","고비":true,"힌트":"넓이 x(20-2x)를 완전제곱으로 바꾸면?","식":["$x(20-2x)=-2(x-5)^2+50$"],"설명":"넓이가 최대가 되는 것은 x=5일 때이다.","확인":null,"스킬":"A6"},{"제목":"둘레 계산하기","힌트":"x=5일 때 직사각형의 가로, 세로는?","식":["$2\\times(5+10)=30$"],"설명":"x=5, FG=10이므로 둘레는 30이다.","확인":"30","스킬":"A6"}],"fb":"fig/ns/"},"ns-1bfc2d402296":{"길":"점 P를 (a, -a+6)으로 놓고 직사각형 넓이 조건으로 이차방정식을 세워 a를 구한다","단계":[{"제목":"점 P의 좌표 설정","힌트":"직선 위의 점 P를 한 문자로 나타내면?","식":["$P(a,\\ -a+6)$"],"설명":"점 P가 직선 y=-x+6 위에 있으므로 y좌표를 a로 나타낸다.","확인":null,"스킬":"G10"},{"제목":"넓이 조건으로 방정식 세우기","힌트":"직사각형 OQPR의 넓이는 a와 b의 곱이다","식":["$a(-a+6)=6$","$a^2-6a+6=0$"],"설명":"직사각형의 넓이가 6이라는 조건을 식으로 옮겨 이차방정식을 만든다.","확인":null,"스킬":"C7"},{"제목":"근의 공식으로 a 구하고 조건 적용","고비":true,"힌트":"근의 공식으로 두 값 중 어느 것이 0<a≤b 조건에 맞을까?","식":["$a=3\\pm\\sqrt3$","$a<3\\Rightarrow a=3-\\sqrt3$"],"설명":"근의 공식으로 두 값을 구한 뒤 0<a≤b 조건을 만족하는 값만 남긴다.","확인":null,"스킬":"C2"},{"제목":"점 P의 좌표 확정","힌트":"a=3-√3일 때 b=-a+6은?","식":["$P(3-\\sqrt3,\\ 3+\\sqrt3)$"],"설명":"구한 a값을 직선의 식에 대입해 점 P의 좌표를 완성한다.","확인":null,"스킬":"G10"}],"fb":"fig/ns/"},"ns-1e58d22870e9":{"길":"같은 x좌표를 갖는 두 점의 y좌표 차를 완전제곱으로 정리해 최솟값을 구한다","단계":[{"제목":"P, Q 좌표를 p로 나타내기","힌트":"y축에 평행한 직선 위의 점이므로 P, Q의 x좌표는 같다. 각각의 y좌표는?","식":["$P(p,\\ -(p-1)^2-2)$","$Q\\left(p,\\ \\frac{1}{2}p-1\\right)$"],"설명":"x좌표가 p로 같은 두 점의 y좌표를 각각 식으로 나타낸다.","확인":null,"스킬":"A6"},{"제목":"PQ를 p에 대한 식으로 세우기","고비":true,"힌트":"Q의 y좌표에서 P의 y좌표를 빼면?","식":["$\\overline{QP}=\\left(\\frac{1}{2}p-1\\right)-\\{-(p-1)^2-2\\}=p^2-\\frac{3}{2}p+2$"],"설명":"직선이 포물선보다 위에 있으므로 Q의 y좌표에서 P의 y좌표를 빼서 거리를 구한다.","확인":null,"스킬":"A2"},{"제목":"완전제곱으로 최솟값 구하기","힌트":"p²-3/2 p+2를 완전제곱 꼴로 바꾸면?","식":["$\\overline{QP}=\\left(p-\\frac{3}{4}\\right)^2+\\frac{23}{16}$"],"설명":"완전제곱으로 정리하면 최솟값은 23/16이다.","확인":"23/16","스킬":"A6"}],"fb":"fig/ns/"},"ns-229fe22fb5bc":{"길":"네 직각삼각형의 합동을 이용해 넓이 관계식을 세우고 이차방정식을 푼다","단계":[{"제목":"합동인 직각삼각형 찾기","힌트":"네 귀퉁이 직각삼각형은 서로 어떤 관계일까?","식":["$\\triangle AEH\\equiv\\triangle BFE\\equiv\\triangle CGF\\equiv\\triangle DHG$"],"설명":"RHA 합동으로 네 귀퉁이 삼각형이 모두 합동임을 확인한다.","확인":null,"스킬":"S8"},{"제목":"변의 길이를 한 문자로 놓기","힌트":"AH=x라 하면 AE는 어떻게 나타날까?","식":["$\\overline{AH}=x,\\ \\overline{AE}=7-x$"],"설명":"합동인 네 삼각형의 대응변이 같으므로 한 문자 x로 나머지 길이를 나타낸다.","확인":null,"스킬":"A8"},{"제목":"넓이 관계식 세우기","고비":true,"힌트":"큰 정사각형 넓이 = 네 삼각형 넓이 + 작은 정사각형 넓이","식":["$49=4\\times\\left(\\frac12x(7-x)\\right)+25$","$x^2-7x+12=0$"],"설명":"두 정사각형과 네 삼각형의 넓이 관계를 식으로 세워 정리한다.","확인":null,"스킬":"S8"},{"제목":"조건에 맞는 x 구하기","힌트":"인수분해한 두 값 중 AE>AH 조건에 맞는 것은?","식":["$(x-3)(x-4)=0$","$\\overline{AE}>\\overline{AH}\\Rightarrow x=3$"],"설명":"x=3 또는 x=4 중 AE>AH를 만족하는 x=3만 남는다.","확인":"3","스킬":"C2"}],"fb":"fig/ns/"},"ns-23a47617a134":{"길":"합동으로 AQ=AR=AP임을 보이고, AP가 최소가 되는 위치를 찾아 최소 넓이를 구한다","단계":[{"제목":"합동으로 AQ=AP, AR=AP 보이기","힌트":"△AQM과 △APM, △ARN과 △APN은 어떤 합동일까?","식":["$\\triangle AQM\\equiv\\triangle APM\\ (RHS\\ 합동)$","$\\triangle ARN\\equiv\\triangle APN\\ (RHS\\ 합동)$"],"설명":"두 쌍의 삼각형이 RHS 합동이므로 AQ=AR=AP이고, ∠QAM=∠PAM, ∠RAN=∠PAN이다.","확인":null,"스킬":"S2"},{"제목":"∠QAR의 크기 구하기","힌트":"∠PAM+∠PAN이 60°라면 ∠QAR은?","식":["$\\angle QAR=2(\\angle PAM+\\angle PAN)=2\\times60^{\\circ}=120^{\\circ}$"],"설명":"합동으로 생긴 두 각의 합이 배가 되어 ∠QAR=120°로 일정하다.","확인":"120","스킬":"S2"},{"제목":"AP가 최소일 조건 찾기","고비":true,"힌트":"∠QAR이 일정할 때 △AQR의 넓이를 최소로 만드는 AP는?","식":[],"설명":"∠QAR이 일정하므로 AP가 짧을수록 넓이가 작아지고, AP가 가장 짧을 때는 BC를 밑변으로 하는 높이일 때이다.","확인":null,"스킬":"S8"},{"제목":"BC의 길이 구하기","힌트":"B에서 AC에 내린 수선의 발 H로 직각삼각형을 만들면?","식":["$\\overline{AH}=4\\cos60^{\\circ}=2,\\ \\overline{BH}=4\\sin60^{\\circ}=2\\sqrt3$","$\\overline{CH}=5-2=3$","$\\overline{BC}=\\sqrt{(2\\sqrt3)^2+3^2}=\\sqrt{21}$"],"설명":"수선의 발 H를 이용해 직각삼각형 BHC에서 피타고라스 정리로 BC를 구한다.","확인":null,"스킬":"S3"},{"제목":"넓이를 두 가지로 나타내 AP 구하기","힌트":"△ABC의 넓이를 sin으로도, BC×AP로도 나타내면?","식":["$\\triangle ABC=\\dfrac12\\times4\\times5\\times\\sin60^{\\circ}=\\dfrac12\\times\\sqrt{21}\\times\\overline{AP}$","$\\overline{AP}=\\dfrac{10\\sqrt7}{7}$"],"설명":"같은 삼각형의 넓이를 두 가지 식으로 놓아 AP의 값을 구한다.","확인":null,"스킬":"S8"},{"제목":"△AQR의 최소 넓이 계산하기","힌트":"AQ=AR=AP이고 ∠QAR=120°일 때 넓이는?","식":["$\\dfrac12\\times\\left(\\dfrac{10\\sqrt7}{7}\\right)^2\\times\\sin120^{\\circ}=\\dfrac{25\\sqrt3}{7}$"],"설명":"AQ=AR=AP를 두 변, ∠QAR=120°를 끼인각으로 하는 넓이 공식에 대입한다.","확인":null,"스킬":"S8"}],"fb":"fig/ns/"},"ns-23b192dceb96":{"길":"찢어진 두 도수를 미지수로 두고 도수의 합과 평균 식을 연립해 구한 뒤 분산을 계산한다","단계":[{"제목":"도수의 합 식 세우기","힌트":"전체 학생 수 50명이라는 조건으로 식을 세우면?","식":["$8+12+x+y+4+2=50$","$\\therefore\\ x+y=24$"],"설명":"30 이상 40 미만의 도수를 x, 40 이상 50 미만의 도수를 y라 하면 도수의 합이 50이라는 식을 세울 수 있다.","확인":null,"스킬":"C7"},{"제목":"평균 식 세워 연립하기","고비":true,"힌트":"평균이 35권이라는 조건으로 두 번째 식을 세우면?","식":["$\\frac{15\\times8+25\\times12+35x+45y+55\\times4+65\\times2}{50}=35$","$7x+9y=196$"],"설명":"평균 조건으로 두 번째 식을 세워 앞의 식과 연립하면 x=10, y=14이다.","확인":null,"스킬":"A10"},{"제목":"분산 계산하기","힌트":"각 계급값과 평균의 편차 제곱에 도수를 곱해 더하면?","식":["$(분산)=\\frac{(-20)^2\\times8+(-10)^2\\times12+0^2\\times10+10^2\\times14+20^2\\times4+30^2\\times2}{50}$"],"설명":"구한 x, y 값을 대입해 분산을 계산하면 184이다.","확인":"184","스킬":"A2"}],"fb":"fig/ns/"},"ns-26ba14ece1a8":{"길":"포물선 위 점을 변수로 잡아 EB=BC, AB=2BC 조건을 차례로 적용해 넓이를 구한다","단계":[{"제목":"B의 좌표와 EB, BC를 a로 나타내기","힌트":"B(a,a²)이라 하면 2EB=BC 조건에서 EB, BC는?","식":["$\\overline{EB}=a,\\ \\overline{BC}=2a$"],"설명":"2EB=BC이므로 BC=2×EB=2a로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"C, D의 좌표 구하기","힌트":"C의 x좌표는 B의 x좌표에서 BC만큼 이동한 값이다. D는 포물선 위의 대응점이다.","식":["$D(3a,\\ 9a^2)$"],"설명":"C, D의 x좌표는 a+2a=3a이고, D는 포물선 위의 점이므로 y좌표는 (3a)²=9a²이다.","확인":null,"스킬":"S4"},{"제목":"AB=2BC 조건으로 a 구하기","고비":true,"힌트":"AB는 D와 B의 y좌표 차이다. AB=2BC를 식으로 세우면?","식":["$8a^2=4a\\ \\Rightarrow\\ a=\\frac{1}{2}$"],"설명":"AB=9a²-a²=8a²이고 BC=2a이므로 8a²=2×2a에서 a=1/2(a>0)을 얻는다.","확인":null,"스킬":"A6"},{"제목":"넓이 계산하기","힌트":"a=1/2일 때 AB, BC 값으로 넓이를 구하면?","식":["$\\overline{AB}=2,\\ \\overline{BC}=1$","$2\\times1=2$"],"설명":"AB=2, BC=1이므로 사각형의 넓이는 2이다.","확인":"2","스킬":"N6"}],"fb":"fig/ns/"},"ns-2d1f99c81dac":{"길":"A의 대칭점 D를 구하고 BC=2AD 조건으로 사다리꼴 넓이를 구한다","단계":[{"제목":"a 값 구하기","힌트":"포물선이 A(-3,-2)를 지나므로 a는?","식":["$-2=9a\\ \\Rightarrow\\ a=-\\frac{2}{9}$"],"설명":"A의 좌표를 대입해 a를 구한다.","확인":null,"스킬":"A6"},{"제목":"D의 좌표와 AD 구하기","힌트":"A, D는 y축에 대칭이므로 D는?","식":["$D(3,-2)$","$\\overline{AD}=6$"],"설명":"A와 D는 y축 대칭이므로 D(3,-2)이고 AD=6이다.","확인":null,"스킬":"S4"},{"제목":"BC의 길이와 B, C의 좌표 구하기","고비":true,"힌트":"BC=2AD이고 B,C의 y좌표가 같으므로 x좌표는?","식":["$\\overline{BC}=12\\ \\Rightarrow\\ B(-6,-8),\\ C(6,-8)$"],"설명":"BC=2×6=12이므로 x좌표는 ±6이고, 포물선에 대입하면 y=-8이다.","확인":null,"스킬":"S4"},{"제목":"사다리꼴 넓이 계산하기","힌트":"윗변 AD, 아랫변 BC, 높이로 사다리꼴 넓이를 구하면?","식":["$\\frac{1}{2}\\times(6+12)\\times6=54$"],"설명":"사다리꼴 넓이 공식으로 계산하면 54이다.","확인":"54","스킬":"N6"}],"fb":"fig/ns/"},"ns-31b868665b94":{"길":"교점을 구하고 P를 매개변수로 잡아 두 삼각형의 넓이를 같게 놓고 k를 구한다","단계":[{"제목":"A, B, C의 좌표 구하기","힌트":"직선과 포물선의 교점, 직선의 y절편은?","식":["$x^2+x-2=0\\ \\Rightarrow\\ x=-2,1$"],"설명":"교점은 A(-2,4), B(1,1)이고, 직선의 y절편 C(0,2)를 구한다.","확인":null,"스킬":"G1"},{"제목":"P를 매개변수로 두고 직선 AP의 식 세우기","힌트":"P(k,k²)(k>0)이라 하면 직선 AP의 방정식은?","식":["$y=(k-2)x+2k$"],"설명":"A와 P를 지나는 직선의 방정식을 세운다.","확인":null,"스킬":"G9"},{"제목":"D의 좌표 구하기","힌트":"직선 AP가 y축과 만나는 점 D는?","식":["$D(0,\\ 2k)$"],"설명":"x=0을 대입해 D의 y좌표를 구한다.","확인":null,"스킬":"G1"},{"제목":"두 삼각형의 넓이를 k로 나타내기","고비":true,"힌트":"△ACD와 △DPO의 넓이를 각각 k에 대한 식으로 쓰면?","식":["$\\triangle ACD=2-2k$","$\\triangle DPO=k^2$"],"설명":"밑변과 높이를 이용해 두 삼각형의 넓이를 각각 k의 식으로 나타낸다.","확인":null,"스킬":"G10"},{"제목":"두 넓이를 같게 놓고 정리하기","힌트":"2-2k=k²를 정리하면?","식":["$k^2+2k-2=0$"],"설명":"이차방정식으로 정리한다.","확인":null,"스킬":"A6"},{"제목":"근의 공식으로 k 확정하기","힌트":"근의 공식을 적용하고 k>0인 것을 고르면?","식":["$k=-1+\\sqrt{3}$"],"설명":"근의 공식으로 두 근을 구한 뒤 k>0인 것을 선택하면 점 P의 x좌표는 -1+√3이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-33cc155c899a":{"길":"두 포물선 사이 직사각형을 두 변수로 잡아 둘레를 완전제곱으로 최적화한다","단계":[{"제목":"두 포물선을 완전제곱 꼴로 바꾸기","힌트":"두 식을 완전제곱 꼴로 바꾸면 축은?","식":["$y=x^2-ax-3=\\left(x-\\frac{a}{2}\\right)^2-\\frac{a^2}{4}-3$","$y=-x^2+ax+3=-\\left(x-\\frac{a}{2}\\right)^2+\\frac{a^2}{4}+3$"],"설명":"두 그래프 모두 축의 방정식이 x=a/2로 같다.","확인":null,"스킬":"A6"},{"제목":"D를 변수로 잡아 A, C의 좌표 나타내기","고비":true,"힌트":"D를 축에서 k만큼 떨어진 점으로 두면 A, C는?","식":["$A\\left(\\frac{a}{2}-k,\\ -k^2+\\frac{a^2}{4}+3\\right)$","$C\\left(\\frac{a}{2}+k,\\ k^2-\\frac{a^2}{4}-3\\right)$"],"설명":"축에 대해 대칭인 A와, D 바로 아래 다른 포물선 위의 점 C를 k로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"변의 길이 AD, DC를 k, a로 나타내기","힌트":"AD와 DC의 길이는?","식":["$\\overline{AD}=2k$","$\\overline{DC}=-2k^2+\\frac{1}{2}a^2+6$"],"설명":"두 변의 길이를 k와 a에 대한 식으로 나타낸다.","확인":null,"스킬":"A6"},{"제목":"둘레식을 k에 대해 완전제곱으로 정리하기","힌트":"둘레 l=2(AD+DC)를 k에 대해 완전제곱으로 정리하면?","식":["$l=-4k^2+4k+a^2+12=-4\\left(k-\\frac{1}{2}\\right)^2+a^2+13$"],"설명":"k에 대해 완전제곱으로 정리하면 둘레의 최댓값은 a²+13이다.","확인":null,"스킬":"A6"},{"제목":"최댓값 조건으로 a 구하기","힌트":"최댓값이 49이므로 a²은?","식":["$a^2+13=49\\ \\Rightarrow\\ a^2=36\\ \\Rightarrow\\ a=6$"],"설명":"a²=36에서 a>0이므로 a=6이다.","확인":"6","스킬":"A6"}],"fb":"fig/ns/"},"ns-3570d873e91c":{"길":"EC를 미지수로 놓고 등변 조건으로 방정식을 세워 AD를 구한다","단계":[{"제목":"EC를 미지수로 놓고 AC 구하기","힌트":"EC=a라 하면 tan75°=AC/EC에서 AC는?","식":["$\\overline{EC}=a,\\ \\overline{AC}=(2+\\sqrt3)a$"],"설명":"△ACE에서 EC=a로 놓고 주어진 tan75°=2+√3을 이용해 AC를 a로 나타낸다.","확인":null,"스킬":"A1"},{"제목":"BC=AC로 방정식 세워 a 구하기","고비":true,"힌트":"∠ABC=45°이면 BC와 AC는 어떤 관계일까?","식":["$\\overline{BC}=2+a=(2+\\sqrt3)a$","$(\\sqrt3+1)a=2\\Rightarrow a=\\sqrt3-1$"],"설명":"∠C=90°, ∠ABC=45°이면 △ABC는 직각이등변삼각형이라 BC=AC이므로 방정식을 세워 a를 구한다.","확인":null,"스킬":"A1"},{"제목":"△BCD에서 CD 구하기","힌트":"BC:CD의 비가 √3:1이라면 CD는?","식":["$\\overline{BC}=2+(\\sqrt3-1)=1+\\sqrt3$","$(1+\\sqrt3):\\overline{CD}=\\sqrt3:1\\Rightarrow\\overline{CD}=\\dfrac{3+\\sqrt3}{3}$"],"설명":"구한 BC와 ∠DBC=30°의 비례식으로 CD를 구한다.","확인":null,"스킬":"S6"},{"제목":"AD의 길이 구하기","힌트":"AC에서 DC를 빼면 AD는?","식":["$\\overline{AD}=\\overline{AC}-\\overline{DC}=(\\sqrt3+1)-\\dfrac{3+\\sqrt3}{3}=\\dfrac{2\\sqrt3}{3}$"],"설명":"AC에서 DC를 빼서 AD의 길이를 구한다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-37f4e5ef93c1":{"길":"축의 방정식으로 b를 구해 꼭짓점 형태로 바꾸고, 점을 변수 k로 두어 둘레를 완전제곱으로 정리한다","단계":[{"제목":"축 이용해 b 구하고 꼭짓점 형태로 바꾸기","힌트":"축이 x=2이면 -b/(-2)=2에서 b는?","식":["$-\\frac{b}{-2}=2\\Rightarrow b=4$","$y=-x^2+4x=-(x-2)^2+4$"],"설명":"축의 방정식으로 b=4를 구하고 이차함수를 꼭짓점 형태로 정리한다.","확인":null,"스킬":"A6"},{"제목":"점 D, A, C를 k로 나타내기","힌트":"D(2+k, ...)라 하면 A, C의 좌표는?","식":["$D(2+k,\\,-k^2+4)$","$A(2-k,\\,-k^2+4)$","$C(2+k,\\,0)$"],"설명":"대칭을 이용해 D, A, C의 좌표를 k로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"둘레를 k의 식으로 세우기","고비":true,"힌트":"직사각형 ABCD의 둘레는 가로와 세로를 더해 2배 한 것","식":["$2(2k-k^2+4)=-2k^2+4k+8$"],"설명":"가로 2k와 세로 -k²+4를 더해 2배 하면 둘레식이 된다.","확인":null,"스킬":"A6"},{"제목":"완전제곱으로 최댓값 구하기","힌트":"-2k²+4k+8을 완전제곱으로 바꾸면?","식":["$-2(k-1)^2+10$"],"설명":"완전제곱으로 정리하면 k=1일 때 최댓값 10을 갖는다.","확인":"10","스킬":"A6"}],"fb":"fig/ns/"},"ns-39c62b008543":{"길":"두 곡선 위의 점을 한 문자로 나타내 정사각형 조건 AB=AD로 방정식을 세운다","단계":[{"제목":"점 A, B, D를 문자로 나타내기","힌트":"A(a,2a²)이면 B, D는?","식":["$A(a,2a^2),\\ B(-a,2a^2)$","$D\\left(a,-\\frac12a^2\\right)$"],"설명":"A를 (a,2a²)로 두면 대칭점 B와, x좌표가 같은 D의 좌표를 얻는다.","확인":null,"스킬":"S4"},{"제목":"정사각형 조건 AB=AD로 방정식 세우기","고비":true,"힌트":"AB의 길이와 AD의 길이를 각각 구하면?","식":["$\\overline{AB}=2a$","$\\overline{AD}=2a^2+\\frac12a^2=\\frac52a^2$","$2a=\\frac52a^2$"],"설명":"정사각형이므로 두 변의 길이가 같다는 식을 세운다.","확인":null,"스킬":"S4"},{"제목":"방정식 풀어 a 구하기","힌트":"양변을 정리해 a로 묶으면?","식":["$\\frac52a^2-2a=0$","$\\frac52a\\left(a-\\frac45\\right)=0$"],"설명":"a>0이므로 a=4/5를 얻는다.","확인":"4/5","스킬":"S4"}],"fb":"fig/ns/"},"ns-3b99b9aa1e48":{"길":"그래프의 두 점으로 직선의 식을 구한 뒤 수입 함수를 완전제곱으로 정리한다","단계":[{"제목":"두 점을 지나는 직선식 세우기","힌트":"그래프가 지나는 두 점 (5000,160), (5600,100)을 이용하면?","식":["$k=ax+b$","$5000a+b=160$","$5600a+b=100$"],"설명":"판매량 k와 가격 x 사이의 관계를 직선식으로 놓고 두 점을 대입한다.","확인":null,"스킬":"C7"},{"제목":"연립방정식 풀어 직선식 구하기","힌트":"두 식을 빼서 a, b를 구하면?","식":["$a=-\\frac{1}{10},\\ b=660$","$k=-\\frac{1}{10}x+660$"],"설명":"두 식을 연립해 풀면 직선의 식을 얻는다.","확인":null,"스킬":"A10"},{"제목":"수입을 x의 이차식으로 세우기","고비":true,"힌트":"수입 y=가격×판매량이므로?","식":["$y=x\\left(-\\frac{1}{10}x+660\\right)=-\\frac{1}{10}x^2+660x$"],"설명":"가격과 판매량의 곱으로 수입 함수를 세운다.","확인":null,"스킬":"C7"},{"제목":"완전제곱으로 최댓값 구하기","힌트":"이차식을 완전제곱으로 바꾸면?","식":["$-\\frac{1}{10}(x-3300)^2+1089000$"],"설명":"완전제곱으로 정리하면 x=3300일 때 최댓값 1089000원을 얻는다.","확인":"1089000","스킬":"A6"}],"fb":"fig/ns/"},"ns-3bc563ffcd48":{"길":"축의 대칭을 이용해 변수 k로 둘레를 나타내 완전제곱으로 최댓값을 구한다","단계":[{"제목":"꼭짓점 형태로 바꾸고 점들을 k로 나타내기","힌트":"y=-2x²+8x을 완전제곱으로 바꾸고 B(k,0)라 하면?","식":["$y=-2(x-2)^2+8$","$B(k,0),\\ A(k,-2k^2+8k),\\ C(4-k,0)$"],"설명":"축이 x=2이므로 대칭을 이용해 세 점을 k로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"둘레를 k의 식으로 세우기","고비":true,"힌트":"BC와 AB의 길이를 더해 2배 하면?","식":["$\\overline{BC}=4-2k,\\ \\overline{AB}=-2k^2+8k$","$2(4-2k-2k^2+8k)=-4k^2+12k+8$"],"설명":"가로와 세로 길이를 더해 둘레식을 세운다.","확인":null,"스킬":"A6"},{"제목":"완전제곱으로 최댓값 구하기","힌트":"-4k²+12k+8을 완전제곱으로 바꾸면?","식":["$-4\\left(k-\\frac32\\right)^2+17$"],"설명":"완전제곱으로 정리하면 최댓값 17을 얻는다.","확인":"17","스킬":"A6"}],"fb":"fig/ns/"},"ns-421bfdbe4d15":{"길":"가로세로를 한 문자로 나타내 넓이 함수를 완전제곱으로 정리한다","단계":[{"제목":"가로, 세로를 x로 나타내기","힌트":"세로를 x라 하면 가로는?","식":["$세로=x,\\ 가로=16-2x$"],"설명":"직각이등변삼각형의 성질로 가로를 16-2x로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"넓이 함수 세우고 완전제곱으로 정리","고비":true,"힌트":"y=x(16-2x)를 완전제곱으로 바꾸면?","식":["$y=-2x^2+16x=-2(x-4)^2+32$"],"설명":"넓이를 이차식으로 세워 완전제곱으로 정리하면 x=4일 때 최댓값 32를 갖는다.","확인":"32","스킬":"A6"}],"fb":"fig/ns/"},"ns-505a2f61cd0c":{"길":"큰 정사각형의 변을 x로 놓고 넓이합 식을 세워 이차방정식을 푼 뒤 큰 쪽 조건으로 고른다","단계":[{"제목":"변수 정해 넓이식 세우기","힌트":"큰 정사각형의 변을 x라 하면 작은 정사각형의 변은?","식":["$x^2+(12-x)^2=90$"],"설명":"큰 정사각형의 한 변을 x cm라 하면 작은 정사각형의 한 변은 (12-x) cm이고, 두 넓이의 합이 90이다.","확인":null,"스킬":"C7"},{"제목":"전개해 이차방정식 풀기","고비":true,"힌트":"전개해 정리한 뒤 인수분해하면?","식":["$x^2-12x+27=0$","$(x-9)(x-3)=0$"],"설명":"식을 전개하고 정리해 인수분해하면 x=9 또는 x=3이다.","확인":null,"스킬":"A6"},{"제목":"조건에 맞는 값 고르기","힌트":"큰 정사각형이므로 x는 6보다 커야 하지 않을까?","식":["$x=9\\ (\\because x>6)$"],"설명":"큰 정사각형의 변이므로 x>6인 값만 답이 된다.","확인":"9","스킬":"C2"}],"fb":"fig/ns/"},"ns-5170a696055b":{"길":"직사각형의 두 꼭짓점을 지나는 경계 조건으로 a의 범위를 구한다","단계":[{"제목":"점 A를 지날 때의 a 구하기","힌트":"그래프가 점 A를 지나려면?","식":["$4=2a$","$a=2$"],"설명":"그래프가 점 A를 지날 때 a=2이다.","확인":null,"스킬":"C2"},{"제목":"점 C를 지날 때의 a 구하기","고비":true,"힌트":"그래프가 점 C를 지나려면?","식":["$2=32a$","$a=\\frac{1}{16}$"],"설명":"그래프가 점 C를 지날 때 a=1/16이다.","확인":null,"스킬":"C2"},{"제목":"두 경계값으로 범위 정하기","힌트":"두 값 사이에서 둘레 위 두 점을 지나려면?","식":["$\\frac{1}{16}<a<2$"],"설명":"a가 두 경계값 사이에 있을 때 그래프가 직사각형 둘레 위 서로 다른 두 점을 지난다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-536a18144b58":{"길":"이등변삼각형에서 AB, AC를 구하고, 점 D에서 내린 수선으로 얻는 두 직각삼각형의 식을 연립해 x를 구한다","단계":[{"제목":"AB, BD 구하기","힌트":"직각이등변삼각형 ABD에서 AB는?","식":["$\\overline{AB}=\\sqrt{10}\\cos45^{\\circ}=\\sqrt5,\\ \\overline{BD}=\\sqrt5$"],"설명":"삼각형 ABD는 AB=BD인 직각이등변삼각형이므로 AB=BD=√5이다.","확인":null,"스킬":"S6"},{"제목":"AC 구하기","힌트":"직각삼각형 ABC에서 AC는?","식":["$\\overline{AC}=\\sqrt{(\\sqrt5)^2+(2\\sqrt5)^2}=5$"],"설명":"BC=BD+DC=2√5이므로 직각삼각형 ABC에서 피타고라스 정리로 AC=5이다.","확인":"5","스킬":"S3"},{"제목":"수선 내려 식 세우기","고비":true,"힌트":"점 D에서 AC에 내린 수선의 발을 H, CH=x라 하면 DH²을 두 가지로 쓰면?","식":["$\\overline{DH}^2=(\\sqrt5)^2-x^2=(\\sqrt{10})^2-(5-x)^2$"],"설명":"점 D에서 AC에 내린 수선의 발을 H, CH=x, AH=5-x라 하면 직각삼각형 DHC와 DHA에서 공통변 DH로 식을 세운다.","확인":null,"스킬":"S3"},{"제목":"x 값 구하기","힌트":"식을 정리해 x를 풀면?","식":["$10x=20$","$x=2$"],"설명":"식을 전개해 정리하면 10x=20이므로 x=2이다.","확인":"2","스킬":"A3"},{"제목":"DH 구하기","힌트":"직각삼각형 ADH에서 AH=3이므로 DH는?","식":["$\\overline{DH}=\\sqrt{(\\sqrt{10})^2-3^2}=1$"],"설명":"AH=5-2=3이므로 직각삼각형 ADH에서 DH=1이다.","확인":"1","스킬":"S3"},{"제목":"sin x 구하기","힌트":"직각삼각형 ADH에서 sinx=DH/AD는?","식":["$\\sin x=\\frac{1}{\\sqrt{10}}=\\frac{\\sqrt{10}}{10}$"],"설명":"직각삼각형 ADH에서 sinx=DH/AD=√10/10이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-5386405d69d8":{"길":"그래프 위 점을 대입해 a를 구하고 대칭을 이용해 사다리꼴의 넓이를 구한다","단계":[{"제목":"점 B를 대입해 a 구하기","힌트":"y=ax²이 점 B(2,1)을 지나면?","식":["$4a=1$","$a=\\frac14$"],"설명":"점 B를 대입하면 a=1/4이다.","확인":null,"스킬":"S4"},{"제목":"점 C의 좌표 구하기","힌트":"CD가 12이고 y축 대칭이면 C의 x좌표는?","식":["$2p=12\\Rightarrow p=6$","$q=\\frac14\\times6^2=9$"],"설명":"CD의 길이로 C의 x좌표를 구하고 그래프에 대입해 y좌표를 구한다.","확인":null,"스킬":"S4"},{"제목":"사다리꼴 넓이 구하기","고비":true,"힌트":"윗변, 아랫변, 높이를 넓이 공식에 대입하면?","식":["$\\frac12\\times(4+12)\\times8=64$"],"설명":"사다리꼴 넓이 공식에 대입하면 64이다.","확인":"64","스킬":"S4"}],"fb":"fig/ns/"},"ns-55b092103f60":{"길":"잘못 기록된 두 값의 합이 같아 평균은 그대로임을 확인하고, 분산 식에서 편차 제곱만 바꿔 계산한다","단계":[{"제목":"평균이 그대로임을 확인하기","힌트":"51+47과 46+52는 같을까?","식":["$51+47=46+52=98$"],"설명":"두 값의 합이 같으므로 전체 변량의 합도 같아 실제 평균과 잘못 구한 평균은 같다.","확인":null,"스킬":"C7"},{"제목":"편차 제곱을 바꿔 분산 다시 계산하기","고비":true,"힌트":"잘못된 편차 제곱을 실제 편차 제곱으로 바꿔 대입하면?","식":["$\\frac{10\\times5-(-4)^2-2^2+1^2+(-3)^2}{5}=\\frac{40}{5}=8$"],"설명":"잘못 기록된 두 값의 편차 제곱을 실제 값의 편차 제곱으로 바꿔 계산하면 분산은 8이다.","확인":"8","스킬":"A2"},{"제목":"표준편차 구하기","힌트":"분산 8에 제곱근을 씌우면?","식":["$\\sqrt{8}=2\\sqrt{2}$"],"설명":"표준편차는 2√2개이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-593d707b885e":{"길":"찢어진 두 도수를 미지수로 두고 도수의 합과 평균 식을 연립해 구한 뒤 중앙값과 최빈값의 차를 계산한다","단계":[{"제목":"도수의 합 식 세우기","힌트":"전체 학생 수 40명 조건으로 식을 세우면?","식":["$8+2+3+x+3+y+2+1=40$","$x+y=21$"],"설명":"3회 학생 수를 x, 5회 학생 수를 y라 하면 도수의 합이 40이라는 식을 세울 수 있다.","확인":null,"스킬":"C7"},{"제목":"평균 식 세워 연립하기","고비":true,"힌트":"평균이 3회라는 조건으로 두 번째 식을 세우면?","식":["$\\frac{0\\times8+1\\times2+2\\times3+3x+4\\times3+5y+6\\times2+7\\times1}{40}=3$","$3x+5y=81$"],"설명":"평균 조건으로 두 번째 식을 세워 연립하면 x=12, y=9이다.","확인":null,"스킬":"A10"},{"제목":"중앙값·최빈값 읽어 a-b 구하기","힌트":"x=12, y=9를 넣으면 중앙값과 최빈값은?","식":["$a=3,\\ b=3,\\ a-b=0$"],"설명":"중앙값과 최빈값이 모두 3회이므로 a-b=0이다.","확인":"0","스킬":"C7"}],"fb":"fig/ns/"},"ns-5b3d5b9f6dc9":{"길":"닮음으로 좌표 비를 구하고 직선 위의 두 점 조건으로 a를 구한다","단계":[{"제목":"닮음으로 x좌표의 비 구하기","힌트":"△APO∽△BQO이고 OA:OB=1:4이므로 OP:OQ는?","식":["$\\overline{OP}:\\overline{OQ}=1:4$"],"설명":"닮음비로 x좌표의 비가 1:4임을 얻는다.","확인":null,"스킬":"S1"},{"제목":"두 점을 문자로 나타내기","힌트":"A(t,t²)라 하면 B는?","식":["$A(t,t^2)$","$B(4t,16at^2)$"],"설명":"x좌표의 비를 이용해 B의 좌표를 t로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"직선 위의 점 조건으로 a 구하기","고비":true,"힌트":"두 점이 같은 직선 y=kx 위에 있으므로?","식":["$t^2=kt,\\ 16at^2=4kt$","$16a=4$","$a=\\frac14$"],"설명":"두 식에서 k를 소거하면 a=1/4을 얻는다.","확인":"1/4","스킬":"S1"}],"fb":"fig/ns/"},"ns-624816fb0a08":{"길":"직각삼각형에서 AM을 구하고 닮음으로 DM을 얻어 피타고라스로 AC까지 구한다","단계":[{"제목":"AM 구하기","힌트":"△ABM에서 sinx=3/AM이면 AM은?","식":["$\\sin x=\\frac{3}{\\overline{AM}}=\\frac13$","$\\overline{AM}=9$"],"설명":"직각삼각형 ABM에서 sinx=1/3이므로 AM=9이다.","확인":"9","스킬":"S6"},{"제목":"DM 구하기","고비":true,"힌트":"△ABM∽△CDM이면 9:3은 3:DM과 같을까?","식":["$9:3=3:\\overline{DM}$","$\\overline{DM}=1$"],"설명":"△ABM∽△CDM(AA닮음)이므로 비례식을 세우면 DM=1이다.","확인":"1","스킬":"S1"},{"제목":"CD 구하기","힌트":"△CDM에서 CD는?","식":["$\\overline{CD}=\\sqrt{3^2-1^2}=2\\sqrt2$"],"설명":"직각삼각형 CDM에서 피타고라스 정리로 CD=2√2이다.","확인":null,"스킬":"S3"},{"제목":"sin y 구하기","힌트":"△ADC에서 AC를 구해 sinY=CD/AC를 계산하면?","식":["$\\overline{AC}=\\sqrt{10^2+(2\\sqrt2)^2}=6\\sqrt3$","$\\sin y=\\frac{2\\sqrt2}{6\\sqrt3}=\\frac{\\sqrt6}{9}$"],"설명":"AD=AM+MD=10이므로 직각삼각형 ADC에서 AC=6√3, sinY=CD/AC=√6/9이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-63d5fc90666c":{"길":"점들을 문자로 나타내 비례식을 세워 a를 구한다","단계":[{"제목":"점 A,B,D를 문자로 나타내기","힌트":"A(a,2a²)라 하면 B, D는?","식":["$A(a,2a^2),\\ B(-a,2a^2)$","$D\\left(a,-\\frac13a^2\\right)$"],"설명":"A를 문자로 두고 대칭점 B와 D의 좌표를 나타낸다.","확인":null,"스킬":"S4"},{"제목":"AB, AD의 길이 구하기","힌트":"AB와 AD를 a로 나타내면?","식":["$\\overline{AB}=2a$","$\\overline{AD}=2a^2+\\frac13a^2=\\frac73a^2$"],"설명":"두 선분의 길이를 a에 관한 식으로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"비례식 세워 a 구하기","고비":true,"힌트":"AB:AD=3:4를 식으로 세우면?","식":["$2a:\\frac73a^2=3:4$","$7a^2-8a=0$","$7a\\left(a-\\frac87\\right)=0$"],"설명":"비례식을 정리하면 a>0이므로 a=8/7을 얻는다.","확인":"8/7","스킬":"C7"}],"fb":"fig/ns/"},"ns-69a84c02d2be":{"길":"터널을 좌표평면에 놓고 포물선의 식을 구해 특정 위치의 높이를 계산한다","단계":[{"제목":"포물선의 식 세우기","힌트":"꼭짓점 (0,6)이고 점 (2,0)을 지나는 포물선의 식은?","식":["$y=ax^2+6$","$0=4a+6\\Rightarrow a=-\\frac32$"],"설명":"꼭짓점과 지나는 점을 이용해 포물선의 식을 구한다.","확인":null,"스킬":"C7"},{"제목":"트럭 폭의 절반 위치의 높이 구하기","힌트":"x=1일 때 y값은?","식":["$y=-\\frac32(1)^2+6=\\frac92$"],"설명":"트럭 폭의 절반인 x=1에서의 높이를 구한다.","확인":null,"스킬":"C7"},{"제목":"트럭 바닥 높이를 빼서 답 구하기","고비":true,"힌트":"터널 높이에서 트럭 바닥 높이 1m를 빼면?","식":["$\\frac92-1=\\frac72$"],"설명":"지면에서 바닥까지의 1m를 빼면 실을 수 있는 높이는 7/2m이다.","확인":"7/2","스킬":"C7"}],"fb":"fig/ns/"},"ns-6d21dbbcb410":{"길":"포물선의 식을 세운 뒤 x=5를 대입해 높이를 구한다","단계":[{"제목":"포물선의 식 세우기","힌트":"꼭짓점이 (0,10)이고 점 (10,0)을 지나는 포물선의 식은?","식":["$y=ax^{2}+10$","$100a+10=0\\ \\Rightarrow\\ a=-\\frac{1}{10}$"],"설명":"꼭짓점의 좌표가 (0, 10)이므로 y=ax²+10으로 놓고, 그래프가 점 (10, 0)을 지남을 이용해 a를 구한다.","확인":null,"스킬":"C7"},{"제목":"x=5에서 높이 계산하기","고비":true,"힌트":"y=-1/10 x²+10에 x=5를 대입하면?","식":["$h=-\\frac{1}{10}\\times5^{2}+10$"],"설명":"x=5를 대입하면 터널의 높이 h는 7.5m이다.","확인":"7.5","스킬":"A6"}],"fb":"fig/ns/"},"ns-780fe51c960b":{"길":"점 P를 매개변수로 두고 PQ의 길이를 완전제곱으로 최소화한다","단계":[{"제목":"점 P, Q의 좌표를 매개변수로 나타내기","힌트":"P(a, -a²-4)라 하면 Q의 y좌표는 P와 같으므로 Q의 x좌표는?","식":["$P(a,\\ -a^{2}-4)$","$Q(-a^{2}-5,\\ -a^{2}-4)$"],"설명":"P의 y좌표 -a²-4를 y=x+1에 대입해 Q의 x좌표를 구한다.","확인":null,"스킬":"A6"},{"제목":"PQ의 길이를 완전제곱으로 정리하기","고비":true,"힌트":"PQ = a-(-a²-5)를 완전제곱 꼴로 바꾸면?","식":["$\\overline{PQ}=a^{2}+a+5=\\left(a+\\frac{1}{2}\\right)^{2}+\\frac{19}{4}$"],"설명":"PQ를 a에 관한 식으로 나타내고 완전제곱으로 정리한다.","확인":null,"스킬":"A6"},{"제목":"최솟값 구하기","힌트":"완전제곱식의 최솟값은?","식":[],"설명":"완전제곱한 값이 0일 때, 즉 a=-1/2일 때 PQ는 최솟값 19/4를 갖는다.","확인":"19/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-79192f7f20d2":{"길":"보조선을 그어 닮음비로 B의 좌표를 구한 뒤 기울기를 계산한다","단계":[{"제목":"보조선 긋고 닮은 삼각형 찾기","힌트":"점 A를 지나 x축에 평행한 직선을 그으면 어떤 삼각형이 닮을까?","식":[],"설명":"점 A에서 x축에 평행한 직선을 긋고 C, B에서 내린 수선의 발을 각각 P, Q라 하면 △ACP∽△ABQ이다.","확인":null,"스킬":"S1"},{"제목":"AC:CB 비로 Q의 좌표 구하기","힌트":"AP:PQ=1:4이면 PQ의 길이는?","식":["$A\\left(a,\\ \\frac{1}{4}a^{2}\\right)\\ (a<0)$","$\\overline{PQ}=-4a,\\ Q\\left(-4a,\\ \\frac{1}{4}a^{2}\\right)$"],"설명":"AC:CB=1:4이므로 AP:PQ도 같은 비이고, 이를 이용해 Q의 좌표를 a로 나타낸다.","확인":null,"스킬":"S1"},{"제목":"B의 좌표를 a로 나타내기","힌트":"CP:BQ=1:5이면 BQ의 길이는?","식":["$\\overline{BQ}=5-\\frac{5}{4}a^{2}$","$B(-4a,\\ 5-a^{2})$"],"설명":"같은 비를 CP:BQ에도 적용해 B의 좌표를 a로 나타낸다.","확인":null,"스킬":"S1"},{"제목":"B가 포물선 위의 점임을 이용해 a 구하기","고비":true,"힌트":"B(-4a, 5-a²)가 y=1/4x² 위의 점이므로?","식":["$5-a^{2}=\\frac{1}{4}(-4a)^{2}$","$5a^{2}=5\\ \\Rightarrow\\ a=-1\\ (\\because a<0)$"],"설명":"B의 좌표를 포물선의 식에 대입해 정리하면 a=-1이다.","확인":null,"스킬":"G2"},{"제목":"기울기 계산하기","힌트":"A(-1, 1/4), B(4, 4)의 기울기는?","식":["$\\frac{4-\\frac{1}{4}}{4-(-1)}=\\frac{3}{4}$"],"설명":"두 점 A, B의 좌표로 직선 l의 기울기를 계산하면 3/4이다.","확인":"3/4","스킬":"G9"}],"fb":"fig/ns/"},"ns-795f0b2b8f3f":{"길":"각을 따라가 닮은 이등변삼각형을 찾아 이차방정식을 세우고 범위 조건으로 근을 고른다","단계":[{"제목":"각을 따라가 닮음 조건 찾기","힌트":"이등변삼각형의 밑각과 이등분선으로 생기는 각들을 표시하면?","식":["$\\angle ABC=\\angle ACB=72^\\circ,\\ \\angle DBA=\\angle DBC=36^\\circ,\\ \\angle BDC=72^\\circ$"],"설명":"각을 표시해 보면 삼각형 ABC와 BCD가 닮음인 이등변삼각형임을 알 수 있다.","확인":null,"스킬":"S10"},{"제목":"변의 길이를 x로 나타내기","고비":true,"힌트":"CD=x라 하면 DA와 BD, BC의 길이는?","식":["$\\overline{CD}=x,\\ \\overline{DA}=\\overline{BD}=\\overline{BC}=10-x$"],"설명":"닮음인 이등변삼각형의 성질로 나머지 변의 길이를 x로 나타낸다.","확인":null,"스킬":"S1"},{"제목":"비례식으로 이차방정식 세우기","힌트":"AB:BC=BC:CD 비례식을 쓰면?","식":["$10:(10-x)=(10-x):x$","$x^2-30x+100=0$"],"설명":"닮음비로 비례식을 세워 정리하면 이차방정식을 얻는다.","확인":null,"스킬":"S1"},{"제목":"조건에 맞는 근 고르기","힌트":"x는 0과 10 사이여야 하지 않을까?","식":["$x=15-5\\sqrt{5}\\ (\\because 0<x<10)$"],"설명":"근의 공식으로 얻은 두 근 중 범위를 만족하는 값을 고른다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-7978e9f12d35":{"길":"A의 좌표와 중점을 구해 새 포물선의 식에 대입한다","단계":[{"제목":"점 A의 좌표와 중점 M 구하기","힌트":"y=10을 y=5/8x²에 대입하면 A의 x좌표는?","식":["$10=\\frac{5}{8}x^{2}\\ \\Rightarrow\\ x=\\pm4$","$A(4,\\ 10),\\ M(2,\\ 10)$"],"설명":"A의 y좌표가 10이므로 x좌표를 구하고, B(0,10)과의 중점 M을 구한다.","확인":null,"스킬":"G1"},{"제목":"M을 지나는 포물선의 식 구하기","고비":true,"힌트":"y=ax²가 M(2,10)을 지나므로?","식":["$10=4a\\ \\Rightarrow\\ a=\\frac{5}{2}$"],"설명":"M의 좌표를 y=ax²에 대입해 a를 구하면 5/2이다.","확인":"5/2","스킬":"A6"}],"fb":"fig/ns/"},"ns-7ad570262026":{"길":"그래프에서 직선의 식을 읽고 넓이식으로 이차방정식을 세운 뒤 조건으로 값을 고른다","단계":[{"제목":"그래프에서 직선의 식 읽기","힌트":"그림에서 기울기와 y절편을 읽으면?","식":["$y=-x-20$"],"설명":"그래프에서 기울기가 -1이고 y절편이 -20임을 읽어 직선의 식을 세운다.","확인":null,"스킬":"G1"},{"제목":"점 P의 좌표를 한 문자로 나타내기","힌트":"P의 x좌표를 -a(a>0)라 하면 y좌표는?","식":["$\\mathrm{P}(-a,\\ a-20)$"],"설명":"P의 x좌표를 -a라 하면 직선의 식으로 y좌표를 a에 관해 나타낼 수 있다.","확인":null,"스킬":"G1"},{"제목":"넓이식 세워 이차방정식 풀기","고비":true,"힌트":"직사각형 APBO의 두 변 BO, BP의 길이는?","식":["$\\overline{BO}=a,\\ \\overline{BP}=20-a$","$a(20-a)=36$","$(a-18)(a-2)=0$"],"설명":"사각형 APBO의 넓이가 36이라는 조건으로 이차방정식을 세워 a=2 또는 18을 얻는다.","확인":null,"스킬":"G10"},{"제목":"조건으로 a 고르고 y좌표 구하기","힌트":"PA>PB인 경우는 a가 클 때일까 작을 때일까?","식":["$a=18\\ (\\because \\overline{PA}>\\overline{PB})$","$y=18-20=-2$"],"설명":"PA>PB 조건을 만족하는 a=18을 택해 P의 y좌표를 구한다.","확인":"-2","스킬":"C2"}],"fb":"fig/ns/"},"ns-7b78d2883f89":{"길":"닮음으로 변의 길이를 x로 나타내 넓이를 최대화한 뒤 둘레를 구한다","단계":[{"제목":"닮음으로 DG를 x로 나타내기","힌트":"△ADG∽△ABC이고 DE=x이면 DG는?","식":["$(12-x):12=\\overline{DG}:18$","$\\overline{DG}=\\frac{3}{2}(12-x)$"],"설명":"닮음비를 이용해 DG의 길이를 x에 관한 식으로 나타낸다.","확인":null,"스킬":"S1"},{"제목":"직사각형의 넓이를 완전제곱으로 정리하기","고비":true,"힌트":"넓이 y=x×DG를 완전제곱 꼴로 바꾸면?","식":["$y=-\\frac{3}{2}(x-6)^{2}+54$"],"설명":"넓이를 x에 관한 이차식으로 세운 뒤 완전제곱으로 정리한다.","확인":null,"스킬":"A6"},{"제목":"넓이가 최대일 때 변의 길이 구하기","힌트":"x=6일 때 DE, DG의 길이는?","식":["$\\overline{DE}=6,\\ \\overline{DG}=\\frac{3}{2}\\times(12-6)=9$"],"설명":"x=6일 때 넓이가 최대이므로 이때 DE=6, DG=9이다.","확인":null,"스킬":"S1"},{"제목":"둘레의 길이 계산하기","힌트":"2×(6+9)는?","식":["$2\\times(6+9)=30$"],"설명":"직사각형의 둘레의 길이는 30이다.","확인":"30","스킬":"G10"}],"fb":"fig/ns/"},"ns-7ce4abf70947":{"길":"AD를 피타고라스로 구하고 △ADE에서 세 삼각비를 구해 대입한다","단계":[{"제목":"DE 길이 구하기","힌트":"직각삼각형 ADC에서 수선 DE가 만드는 성질은?","식":["$\\overline{DE}^2=\\overline{AE}\\times\\overline{CE}=4\\times9=36\\Rightarrow\\overline{DE}=6$"],"설명":"직각삼각형 ADC에서 수선의 성질로 DE를 구한다.","확인":"6","스킬":"S3"},{"제목":"AD 길이 구하기","힌트":"직각삼각형 ADE에서 피타고라스 정리는?","식":["$\\overline{AD}=\\sqrt{4^2+6^2}=2\\sqrt{13}$"],"설명":"직각삼각형 ADE에서 피타고라스 정리로 AD를 구한다.","확인":null,"스킬":"S3"},{"제목":"∠ADE=x°임을 확인하고 세 삼각비 구하기","고비":true,"힌트":"∠BAD+∠CAD=90°이므로 △ADE에서 ∠ADE는 무엇과 같을까?","식":["$\\sin x^\\circ=\\frac{2}{\\sqrt{13}}$","$\\cos y^\\circ=\\frac{2}{\\sqrt{13}}$","$\\tan y^\\circ=\\frac32$"],"설명":"x+y=90°이므로 △ADE에서 ∠ADE=x°가 되어 세 삼각비를 AD, DE, AE로 나타낼 수 있다.","확인":null,"스킬":"S6"},{"제목":"식을 계산해 a, b 구하기","힌트":"세 값을 대입해 정리하면?","식":["$\\sin x^\\circ+\\cos y^\\circ-2\\tan y^\\circ=\\frac{4}{\\sqrt{13}}-3=\\frac{4\\sqrt{13}}{13}-3$"],"설명":"대입해 정리하면 a=13, b=3이다.","확인":null,"스킬":"S6"},{"제목":"a+b 값 구하기","힌트":"a=13, b=3이면 a+b는?","식":["$a+b=13+3=16$"],"설명":"최종적으로 a+b=16이다.","확인":"16","스킬":"S6"}],"fb":"fig/ns/"},"ns-832eff30e5c9":{"길":"대칭인 두 점을 변수로 잡아 둘레를 완전제곱으로 최대화한다","단계":[{"제목":"대칭인 두 점 A, D를 변수로 나타내기","힌트":"D(a, -a²+6)(a>0)이라 하면 A는?","식":["$D(a,\\ -a^{2}+6),\\ A(-a,\\ -a^{2}+6)$"],"설명":"A와 D는 y축에 대하여 대칭이므로 D(a,-a²+6)이라 하면 A(-a,-a²+6)이다.","확인":null,"스킬":"G4"},{"제목":"둘레의 길이를 완전제곱으로 정리하기","고비":true,"힌트":"AD=2a, CD=-a²+6이므로 둘레는?","식":["$y=2(2a-a^{2}+6)=-2(a-1)^{2}+14$"],"설명":"둘레의 길이를 a에 관한 식으로 세운 뒤 완전제곱으로 정리한다.","확인":null,"스킬":"A6"},{"제목":"최댓값 구하기","힌트":"a=1일 때 둘레의 길이는?","식":[],"설명":"a=1일 때 직사각형 ABCD의 둘레의 길이는 최댓값 14를 갖는다.","확인":"14","스킬":"A6"}],"fb":"fig/ns/"},"ns-84746b634b33":{"길":"점 D를 변수로 두고 정사각형 조건 AD=DC로 방정식을 세운다","단계":[{"제목":"세 점 A, D, C를 변수로 나타내기","힌트":"D(a,-a²)(a>0)이라 하면 A, C의 좌표는?","식":["$D(a,\\ -a^{2}),\\ A(-a,\\ -a^{2}),\\ C(a,\\ -4)$"],"설명":"D를 포물선 위의 점 (a,-a²)으로 두면 A는 대칭점, C는 D 바로 아래 직선 y=-4 위의 점이다.","확인":null,"스킬":"S4"},{"제목":"정사각형 조건 AD=DC로 방정식 세우기","고비":true,"힌트":"AD의 길이와 DC의 길이가 같다는 조건을 식으로 쓰면?","식":["$a-(-a)=-a^{2}-(-4)$","$a^{2}+2a-4=0$"],"설명":"정사각형이므로 AD=DC를 식으로 세우면 이차방정식이 나온다.","확인":null,"스킬":"S4"},{"제목":"a의 값 구하기","힌트":"근의 공식으로 풀면 a>0인 근은?","식":["$a=-1+\\sqrt{5}\\ (\\because a>0)$"],"설명":"근의 공식으로 풀어 a>0인 값을 택하면 a=-1+√5이다.","확인":null,"스킬":"N8"},{"제목":"정사각형의 넓이 계산하기","힌트":"한 변의 길이 2a를 제곱하면?","식":["$(2a)^{2}=4(-1+\\sqrt5)^{2}=4(6-2\\sqrt5)=24-8\\sqrt5$"],"설명":"한 변의 길이 2a를 제곱해 정리하면 넓이는 24-8√5이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-85f2638f2da2":{"길":"CE를 k로 놓고 AC=BC 관계식을 세워 k를 구한 뒤 AD를 계산한다","단계":[{"제목":"CE=k로 놓고 AC 표현하기","힌트":"△AEC에서 tan75°=AC/CE이면?","식":["$\\overline{CE}=k,\\ \\overline{AC}=(2+\\sqrt3)k$"],"설명":"tan75°=2+√3을 이용해 AC를 k로 나타낸다.","확인":null,"스킬":"S6"},{"제목":"AC=BC 관계로 k 구하기","고비":true,"힌트":"△ABC에서 AC=BC이므로 세울 수 있는 식은?","식":["$(2+\\sqrt3)k=a+k\\Rightarrow k=\\frac{\\sqrt3-1}{2}a$"],"설명":"각B=45°인 이등변삼각형이므로 AC=BC를 이용해 방정식을 세워 k를 구한다.","확인":null,"스킬":"C7"},{"제목":"AC(=BC) 길이 구하기","힌트":"k값을 대입하면 AC는?","식":["$\\overline{AC}=\\overline{BC}=\\frac{\\sqrt3+1}{2}a$"],"설명":"k를 대입해 AC, BC 길이를 a로 나타낸다.","확인":null,"스킬":"S6"},{"제목":"DC 구하고 AD 계산하기","힌트":"△BCD에서 DC=BC tan30°, AD=AC-DC는?","식":["$\\overline{DC}=\\frac{\\sqrt3+1}{2}a\\times\\frac{\\sqrt3}{3}=\\frac{3+\\sqrt3}{6}a$","$\\overline{AD}=\\frac{\\sqrt3+1}{2}a-\\frac{3+\\sqrt3}{6}a=\\frac{\\sqrt3}{3}a$"],"설명":"DC를 구해 AC에서 빼면 AD를 얻는다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-889b13ab0012":{"길":"직사각형과 정사각형의 닮음비로 비례식을 세워 이차방정식을 풀고 a, b를 구해 곱한다","단계":[{"제목":"변의 길이를 x로 나타내기","힌트":"AD=x라 하면 DF의 길이는?","식":["$\\overline{AD}=x$","$\\overline{DF}=\\overline{AD}-\\overline{AF}=x-12$"],"설명":"정사각형 ABEF의 한 변이 12이므로 AF=12이고, DF=AD-AF=x-12이다.","확인":null,"스킬":"S1"},{"제목":"닮음비로 비례식 세우기","고비":true,"힌트":"□ABCD와 □DFEC가 닮음이므로 어떤 비례식이 성립할까?","식":["$\\overline{AB}:\\overline{DF}=\\overline{AD}:\\overline{DC}$","$12:(x-12)=x:12$"],"설명":"두 직사각형이 서로 닮음이므로 대응변의 비가 같다는 비례식을 세운다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀고 근 고르기","힌트":"비례식을 정리해 전개하면?","식":["$x^2-12x-144=0$","$x=6+6\\sqrt{5}\\ (\\because x>0)$"],"설명":"비례식을 정리한 이차방정식을 풀면 x>0 조건으로 근을 고를 수 있다.","확인":null,"스킬":"A6"},{"제목":"a, b 정하고 ab 계산하기","힌트":"x=a+b√5 꼴과 비교하면?","식":["$a=6,\\ b=6$","$ab=36$"],"설명":"구한 x의 값을 a+b√5 꼴과 비교하면 a=6, b=6이므로 ab=36이다.","확인":"36","스킬":"N5"}],"fb":"fig/ns/"},"ns-889f22dc5bc0":{"길":"점 P를 변수로 두고 PQ=2 조건으로 방정식을 세운다","단계":[{"제목":"점 P, Q를 변수로 나타내기","힌트":"P(a,4a²)(a>0)이고 PQ=2이면 Q의 좌표는?","식":["$P(a,\\ 4a^{2}),\\ Q(a+2,\\ (a+2)^{2})$"],"설명":"P를 (a,4a²)로 두고 PQ=2이므로 Q의 x좌표는 a+2이다.","확인":null,"스킬":"A6"},{"제목":"y좌표가 같다는 조건으로 방정식 세우기","고비":true,"힌트":"P, Q는 같은 직선 y=k 위의 점이므로 y좌표가 같다. 이를 식으로 쓰면?","식":["$4a^{2}=(a+2)^{2}$","$3a^{2}-4a-4=0$"],"설명":"두 점의 y좌표가 같다는 조건을 식으로 세워 정리한다.","확인":null,"스킬":"A6"},{"제목":"a를 구해 k 계산하기","힌트":"인수분해해서 a>0인 근을 구하면?","식":["$(3a+2)(a-2)=0\\ \\Rightarrow\\ a=2$","$k=4a^{2}=16$"],"설명":"인수분해해 a=2를 구하고 대입하면 k=16이다.","확인":"16","스킬":"A6"}],"fb":"fig/ns/"},"ns-8a469ebab53b":{"길":"두 x절편과 계수로 포물선의 식을 세워 최댓값을 구한다","단계":[{"제목":"포물선의 식 세우기","힌트":"(0,0), (12,0)을 지나고 x²의 계수가 -1/2인 포물선의 식은?","식":["$y=-\\frac{1}{2}x(x-12)=-\\frac{1}{2}x^{2}+6x$"],"설명":"두 점을 지나고 x²의 계수가 -1/2인 포물선의 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"완전제곱으로 최댓값 구하기","고비":true,"힌트":"y=-1/2x²+6x를 완전제곱 꼴로 바꾸면?","식":["$y=-\\frac{1}{2}(x-6)^{2}+18$"],"설명":"완전제곱으로 정리하면 최댓값은 18이다.","확인":"18","스킬":"A6"}],"fb":"fig/ns/"},"ns-8bc2251e0243":{"길":"직사각형의 두 꼭짓점을 지날 때의 a값으로 범위를 찾는다","단계":[{"제목":"점 A를 지날 때의 a 구하기","힌트":"y=ax²가 A(-4,-4)를 지나면 a는?","식":["$-4=a\\times(-4)^{2}\\ \\Rightarrow\\ a=-\\frac{1}{4}$"],"설명":"포물선이 점 A(-4,-4)를 지날 때 a=-1/4이다.","확인":null,"스킬":"G2"},{"제목":"점 C를 지날 때의 a 구하기","고비":true,"힌트":"y=ax²가 C(-2,-12)를 지나면 a는?","식":["$-12=a\\times(-2)^{2}\\ \\Rightarrow\\ a=-3$"],"설명":"포물선이 점 C(-2,-12)를 지날 때 a=-3이다.","확인":null,"스킬":"G2"},{"제목":"a의 범위 정하기","힌트":"두 값 사이에서 직사각형 둘레와 두 번 만나려면?","식":[],"설명":"포물선이 두 값 사이를 지날 때 직사각형의 둘레와 서로 다른 두 점에서 만나므로 -3<a<-1/4이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-8cb045e4caad":{"길":"접은 각 관계로 이등변삼각형 PQC를 찾아 보조선으로 tan x를 구한다","단계":[{"제목":"보조선 긋고 각 관계 찾기","힌트":"엇각과 접은 각의 성질로 ∠APQ와 ∠PQC의 관계는?","식":["$\\angle APQ=\\angle PQC(엇각),\\ \\angle CPQ=\\angle APQ(접은\\ 각)$"],"설명":"두 각 모두 ∠APQ와 같으므로 ∠PQC=∠CPQ이다.","확인":null,"스킬":"S10"},{"제목":"이등변삼각형 PQC 찾기","고비":true,"힌트":"두 밑각이 같은 △PQC에서 PC의 길이는?","식":["$\\overline{PC}=\\overline{QC}=5$"],"설명":"∠PQC=∠CPQ이므로 △PQC는 PC=QC인 이등변삼각형이고, 접은 선분이므로 QC는 원래 변 길이 5와 같다.","확인":"5","스킬":"S10"},{"제목":"PD 구하기","힌트":"직각삼각형 CDP에서 PC=AP=5, DC=3이면 PD는?","식":["$\\overline{PD}=\\sqrt{5^2-3^2}=4$"],"설명":"피타고라스 정리로 PD를 구한다.","확인":"4","스킬":"S3"},{"제목":"HP 구하기","힌트":"BQ=AH이므로 HP=AP-AH는?","식":["$\\overline{BQ}=\\overline{AH}=4,\\ \\overline{HP}=5-4=1$"],"설명":"직사각형의 성질로 AH를 구해 HP를 계산한다.","확인":"1","스킬":"S3"},{"제목":"tan x 구하기","힌트":"직각삼각형 HPQ에서 tan x는?","식":["$\\tan x=\\frac{\\overline{HQ}}{\\overline{HP}}=3$"],"설명":"HQ=DC=3이므로 tan x=3이다.","확인":"3","스킬":"S6"}],"fb":"fig/ns/"},"ns-9217b5f58700":{"길":"점 A를 변수로 두고 정사각형 조건 AD=DC로 방정식을 세운다","단계":[{"제목":"세 점 A, D, C를 변수로 나타내기","힌트":"A(a,a²)(a>0)이라 하면 D, C는 각각 어느 포물선 위의 점일까?","식":["$A(a,\\ a^{2}),\\ D(a,\\ 9a^{2}),\\ C(3a,\\ 9a^{2})$"],"설명":"AB가 x축에 평행하고 AD는 y축에 평행하므로 D는 A와 x좌표가 같은 y=9x² 위의 점이고, C는 D와 y좌표가 같다.","확인":null,"스킬":"S4"},{"제목":"정사각형 조건 AD=DC로 a 구하기","고비":true,"힌트":"AD의 길이와 DC의 길이가 같다는 조건을 식으로 쓰면?","식":["$8a^{2}=2a$","$8a\\left(a-\\frac{1}{4}\\right)=0\\ \\Rightarrow\\ a=\\frac{1}{4}$"],"설명":"정사각형이므로 AD=DC를 식으로 세워 풀면 a=1/4이다.","확인":null,"스킬":"S4"},{"제목":"정사각형의 넓이 계산하기","힌트":"한 변의 길이 2a를 제곱하면?","식":["$\\left(2\\times\\frac{1}{4}\\right)^{2}=\\frac{1}{4}$"],"설명":"한 변의 길이 1/2을 제곱하면 넓이는 1/4이다.","확인":"1/4","스킬":"S4"}],"fb":"fig/ns/"},"ns-95c7d0f9b065":{"길":"작은 직사각형의 짧은 변과 긴 변 사이 관계를 배치에서 찾고 넓이식으로 이차방정식을 세워 푼다","단계":[{"제목":"작은 직사각형의 변 관계식 세우기","힌트":"AD와 BC가 같다는 조건에서 짧은 변과 긴 변의 관계는?","식":["$4x=3y\\ \\Rightarrow\\ y=\\frac43x$"],"설명":"작은 직사각형의 짧은 변을 x, 긴 변을 y라 하면 배치에서 4x=3y이므로 y=(4/3)x이다.","확인":null,"스킬":"C7"},{"제목":"직사각형 ABCD의 넓이식 세우기","고비":true,"힌트":"AB=4x, AD=x+y인데 넓이가 189라면?","식":["$4x\\times(x+y)=189$"],"설명":"가로 AB=4x, 세로 AD=x+y이므로 넓이를 곱으로 나타내 189와 같다고 둔다.","확인":null,"스킬":"C7"},{"제목":"y를 대입해 이차방정식 풀기","힌트":"y=(4/3)x를 대입하면?","식":["$4x\\times\\frac73x=189$","$x^2=\\frac{81}{4}$","$x=\\frac92$"],"설명":"대입해 정리하면 x²=81/4이고 x>0이므로 x=9/2이다.","확인":null,"스킬":"A6"},{"제목":"둘레 계산하기","힌트":"y=4x/3에 x=9/2를 넣으면?","식":["$y=6$","$2\\times\\left(\\frac92+6\\right)=21$"],"설명":"y=6이므로 작은 직사각형의 둘레는 2×(9/2+6)=21이다.","확인":"21","스킬":"C7"}],"fb":"fig/ns/"},"ns-9b86128a0d47":{"길":"교점 B와 중점 C를 구한 뒤 C를 지나는 조건으로 a를 구한다","단계":[{"제목":"점 B 구하기","힌트":"y=4와 y=x²의 교점(1사분면)은?","식":["$x^{2}=4\\Rightarrow B(2,4)$"],"설명":"y=4와 이차함수의 교점 중 1사분면 점을 구한다.","확인":null,"스킬":"G1"},{"제목":"중점 C 구하기","힌트":"A(0,4)와 B(2,4)의 중점은?","식":["$C(1,4)$"],"설명":"A와 B의 중점을 구한다.","확인":null,"스킬":"S4"},{"제목":"a값 구하기","고비":true,"힌트":"y=ax²가 점 C를 지나므로?","식":["$4=a\\times1^{2}\\Rightarrow a=4$"],"설명":"점 C의 좌표를 대입해 a를 구한다.","확인":"4","스킬":"A6"}],"fb":"fig/ns/"},"ns-9d47b2990d2d":{"길":"1,2,3의 눈이 나온 횟수를 미지수로 두고 개수·평균·분산 세 조건을 연립해 이차방정식을 푼다","단계":[{"제목":"미지수 두고 개수 조건 세우기","힌트":"1,2,3의 눈이 나온 횟수를 a,b,c라 하면 전체 개수 조건은?","식":["$a+b+c+1+2+4=19$","$a+b+c=12$"],"설명":"눈의 수 1,2,3이 나온 횟수를 a,b,c라 하고 전체 개수 조건을 세운다.","확인":null,"스킬":"C7"},{"제목":"평균 조건 세우기","힌트":"평균이 3이라는 식을 세우면?","식":["$\\frac{a+2b+3c+4+10+24}{19}=3$","$a+2b+3c=19$"],"설명":"평균 방정식을 정리한다.","확인":null,"스킬":"A2"},{"제목":"분산 조건 세우기","고비":true,"힌트":"분산이 4라는 식을 세우면?","식":["$\\frac{4a+b+45}{19}=4$","$4a+b=31$"],"설명":"분산 방정식을 정리한다.","확인":null,"스킬":"A2"},{"제목":"세 식을 연립해 정리하기","힌트":"b를 a로 나타내 나머지 두 식에 대입하면?","식":["$b=31-4a$","$-3a+c=-19$","$-7a+3c=-43$"],"설명":"b를 소거해 a, c에 관한 두 식을 얻는다.","확인":null,"스킬":"A10"},{"제목":"연립해 a, b 구하기","힌트":"두 식을 연립하면?","식":["$a=7,\\ b=31-4\\times7=3$"],"설명":"연립하여 풀면 a=7, b=3이다.","확인":"3","스킬":"A10"}],"fb":"fig/ns/"},"ns-9dfc89c2807a":{"길":"대칭으로 A, B를 놓고 C를 구해 AB:BC 비례식으로 a를 구한다","단계":[{"제목":"대칭으로 A, B 좌표 놓기","힌트":"y=x² 위에서 y축 대칭인 두 점은?","식":["$B(a,a^{2}),\\ A(-a,a^{2})\\ (a>0)$"],"설명":"y축에 대칭이므로 x좌표의 부호만 반대로 놓는다.","확인":null,"스킬":"S4"},{"제목":"점 C 좌표 구하기","힌트":"B에서 y축에 평행한 선이 다른 그래프와 만나는 점은?","식":["$C\\left(a,-\\frac{1}{2}a^{2}\\right)$"],"설명":"B와 x좌표가 같은 점을 다른 그래프의 식에 대입한다.","확인":null,"스킬":"S4"},{"제목":"AB, BC 길이 구하기","힌트":"AB는 가로, BC는 세로 거리다","식":["$\\overline{AB}=2a,\\ \\overline{BC}=\\frac{3}{2}a^{2}$"],"설명":"두 점의 좌표 차이로 길이를 구한다.","확인":null,"스킬":"S4"},{"제목":"비례식 세워 a 구하기","고비":true,"힌트":"AB:BC=4:1을 식으로 세우면?","식":["$2a:\\frac{3}{2}a^{2}=4:1\\Rightarrow a=\\frac{1}{3}$"],"설명":"비례식을 세워 풀면 a=1/3이다.","확인":"1/3","스킬":"A8"}],"fb":"fig/ns/"},"ns-9f7c00358b55":{"길":"중간 반원의 반지름을 15-r로 놓고 넓이 조건으로 이차방정식을 세워 판정 조건으로 답을 고른다","단계":[{"제목":"중간 반원의 반지름 나타내기","힌트":"가장 큰 반원의 반지름이 15이면 중간 반원의 반지름은?","식":["$15-r$"],"설명":"가장 작은 반원의 반지름을 r라 하면, 접하는 조건에서 중간 크기 반원의 반지름은 15-r이다.","확인":null,"스킬":"C7"},{"제목":"색칠한 부분의 넓이식 세우기","고비":true,"힌트":"큰 반원에서 작은 두 반원을 빼면?","식":["$\\frac12\\pi\\times15^2-\\frac12\\pi r^2-\\frac12\\pi(15-r)^2=50\\pi$"],"설명":"큰 반원의 넓이에서 반지름 r인 반원과 반지름 15-r인 반원의 넓이를 뺀 것이 색칠한 부분이다.","확인":null,"스킬":"S12"},{"제목":"이차방정식으로 정리해 풀기","힌트":"양변을 π로 나누고 정리하면?","식":["$r^2-15r+50=0$","$(r-10)(r-5)=0$"],"설명":"정리하면 이차방정식이 되어 r=10 또는 r=5이다.","확인":null,"스킬":"A6"},{"제목":"가장 작은 반원인지 확인하기","힌트":"r=10이면 중간 반원의 반지름 15-r은?","식":["$r=10\\Rightarrow15-r=5<r$ (모순)"],"설명":"r=10이면 중간 반원의 반지름이 5로 r보다 작아져 '가장 작은 반원'이라는 조건에 맞지 않으므로 r=5가 답이다.","확인":"5","스킬":"C2"}],"fb":"fig/ns/"},"ns-a0ba8541b273":{"길":"P를 문자로 놓아 두 삼각형 넓이를 각각 구하고 합을 완전제곱으로 만들어 최솟값을 찾는다","단계":[{"제목":"A, B 좌표 구하기","힌트":"직선의 x절편과 y절편은?","식":["$A(0,12),\\ B(6,0)$"],"설명":"직선 y=-2x+12의 절편을 구한다.","확인":null,"스킬":"G1"},{"제목":"점 P로 두 삼각형 넓이 나타내기","힌트":"P(a,-2a+12)로 놓으면 두 삼각형의 넓이는?","식":["$\\triangle ARP=a^{2},\\ \\triangle PQB=(6-a)^{2}$"],"설명":"점 P를 직선 위의 문자로 놓고 두 삼각형의 넓이를 각각 구한다.","확인":null,"스킬":"G10"},{"제목":"넓이의 합을 완전제곱으로 바꾸기","고비":true,"힌트":"두 넓이를 더해 정리하면?","식":["$a^{2}+(6-a)^{2}=2(a-3)^{2}+18$"],"설명":"두 식을 더해 완전제곱 꼴로 정리한다.","확인":null,"스킬":"A6"},{"제목":"최솟값 읽기","힌트":"완전제곱 꼴에서 최솟값은?","식":["$a=3\\ 일\\ 때\\ 최솟값\\ 18$"],"설명":"a=3일 때 넓이의 합이 최솟값 18을 갖는다.","확인":"18","스킬":"A6"}],"fb":"fig/ns/"},"ns-ab914fbe52ca":{"길":"점 B에서 수선을 내려 닮은 삼각형을 만들고 삼각비를 연쇄적으로 적용한다","단계":[{"제목":"AD의 길이 구하기","힌트":"△ACD에서 sin x°=CD/AD 임을 이용하면?","식":["$\\sin x^\\circ=\\dfrac{\\overline{CD}}{\\overline{AD}}=\\dfrac{3}{\\overline{AD}}=\\dfrac13$"],"설명":"직각삼각형 ACD에서 sin x°의 정의로 AD를 구하면 9이다.","확인":"9","스킬":"S6"},{"제목":"보조선 그어 닮은 삼각형 만들기","힌트":"점 B에서 AD의 연장선에 내린 수선의 발을 E라 하면?","식":[],"설명":"BE⊥AD인 점 E를 잡으면 △BDE와 △ADC는 AA닮음이다.","확인":null,"스킬":"S2"},{"제목":"DE 길이 구하기","힌트":"닮음인 △BDE에서도 sin x°는 같은 비율일까?","식":["$\\sin x^\\circ=\\dfrac{\\overline{DE}}{\\overline{BD}}=\\dfrac{\\overline{DE}}{3}=\\dfrac13$"],"설명":"△BDE에서도 각 x°에 대한 sin 비율이 같으므로 DE=1이다.","확인":"1","스킬":"S1"},{"제목":"BE 길이 구하기","고비":true,"힌트":"직각삼각형 BDE에서 피타고라스 정리를 쓰면?","식":["$\\overline{BE}=\\sqrt{3^2-1^2}=2\\sqrt2$"],"설명":"직각삼각형 BDE에서 BD=3, DE=1이므로 BE를 구한다.","확인":null,"스킬":"S3"},{"제목":"tan y° 계산하기","힌트":"AE=AD+DE, tan y°=BE/AE 임을 이용하면?","식":["$\\overline{AE}=9+1=10$","$\\tan y^\\circ=\\dfrac{\\overline{BE}}{\\overline{AE}}=\\dfrac{2\\sqrt2}{10}=\\dfrac{\\sqrt2}{5}$"],"설명":"직각삼각형 ABE에서 AE=10이므로 tan y°=√2/5이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-aebecf38cc82":{"길":"정오각형의 각으로 이등변삼각형 두 개를 찾아 주어진 비를 이용해 방정식을 세운다","단계":[{"제목":"이등변삼각형 찾기","힌트":"정오각형의 밑각들이 같다는 사실로 어떤 삼각형이 이등변삼각형일까?","식":[],"설명":"정오각형에서 ∠BAC=∠BCA=∠ABE이므로 △ABP는 PA=PB, △CBP는 CB=CP인 이등변삼각형이다.","확인":null,"스킬":"S10"},{"제목":"PC의 길이 확정하기","힌트":"CB=CP이고 한 변의 길이가 2이므로 PC는?","식":["$\\overline{PC}=\\overline{CB}=2$"],"설명":"이등변삼각형 CBP에서 PC는 정오각형의 한 변과 같은 2다.","확인":null,"스킬":"S10"},{"제목":"비례식 세워 BP 구하기","고비":true,"힌트":"BP=x라 하고 AP:PC=1:(1+√5)/2에 대입하면?","식":["$x:2=1:\\frac{1+\\sqrt{5}}{2}$","$\\left(\\frac{1+\\sqrt{5}}{2}\\right)x=2$"],"설명":"PA=PB=x이므로 주어진 비례식에 대입해 x에 관한 방정식을 세운다.","확인":null,"스킬":"A8"},{"제목":"분모를 유리화해 x 구하기","힌트":"4/(1+√5)의 분모를 유리화하면?","식":["$x=\\frac{4}{1+\\sqrt{5}}=\\frac{4(\\sqrt{5}-1)}{4}=\\sqrt{5}-1$"],"설명":"분모, 분자에 (√5-1)을 곱해 유리화하면 BP=√5-1을 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-b5387f5cee1e":{"길":"평행사변형 성질로 B의 좌표를 구해 두 y좌표의 절댓값이 같다는 조건을 세운다","단계":[{"제목":"A, D 좌표 놓기","힌트":"AD가 x축에 평행하므로 A, D는 y좌표가 같다","식":["$A(-k,2k^{2}),\\ D(k,2k^{2})$"],"설명":"y=2x² 위에서 y좌표가 같은 대칭인 두 점으로 놓는다.","확인":null,"스킬":"S4"},{"제목":"B 좌표 구하기","힌트":"평행사변형이므로 BC=AD, B는 A를 어떻게 옮긴 점일까?","식":["$\\overline{AD}=2k=\\overline{BC},\\ B(-2k,4ak^{2})$"],"설명":"AD와 같은 길이만큼 A를 옮긴 점이 B이고, y=ax² 위에 있으므로 대입한다.","확인":null,"스킬":"S4"},{"제목":"절댓값 조건 세우기","고비":true,"힌트":"A와 B의 y좌표의 절댓값이 같다는 조건을 식으로 쓰면?","식":["$-2k^{2}=4ak^{2}$"],"설명":"A는 양수, B는 음수 y좌표를 가지므로 부호를 반영해 식을 세운다.","확인":null,"스킬":"C2"},{"제목":"a값 구하기","힌트":"양변을 k²으로 나누면?","식":["$a=-\\frac{1}{2}$"],"설명":"식을 정리하면 a=-1/2이다.","확인":"-1/2","스킬":"A6"}],"fb":"fig/ns/"},"ns-b790d0202772":{"길":"두 점을 각 그래프 위에 놓고 정사각형의 변 조건으로 방정식을 세워 둘레를 구한다","단계":[{"제목":"A, D 좌표 놓기","힌트":"AD가 y축에 평행하므로 x좌표가 같다","식":["$A(a,a^{2}),\\ D(a,9a^{2})\\ (a>0)$"],"설명":"A는 y=x², D는 y=9x² 위에서 x좌표가 같은 점으로 놓는다.","확인":null,"스킬":"S4"},{"제목":"C 좌표 구하기","힌트":"DC가 x축에 평행하고 C도 y=x² 위에 있다면?","식":["$C(3a,9a^{2})$"],"설명":"D와 y좌표가 같으면서 y=x² 위에 있는 점을 구한다.","확인":null,"스킬":"S4"},{"제목":"정사각형 조건으로 방정식 세우기","고비":true,"힌트":"AD=CD를 식으로 쓰면?","식":["$9a^{2}-a^{2}=3a-a$"],"설명":"정사각형이므로 이웃한 두 변의 길이가 같다는 조건을 세운다.","확인":null,"스킬":"A6"},{"제목":"a값 구하고 둘레 계산하기","힌트":"방정식을 풀면 a와 한 변의 길이는?","식":["$a=\\frac{1}{4},\\ 한\\ 변=2a=\\frac{1}{2}$"],"설명":"a=1/4이므로 한 변의 길이는 1/2이고 둘레는 4×1/2=2이다.","확인":"2","스킬":"N6"}],"fb":"fig/ns/"},"ns-ba286031db1e":{"길":"가로세로 비를 4a,3a로 두고 넓이식으로 a를 구한 뒤 모서리 자른 길이를 더해 종이 크기를 구한다","단계":[{"제목":"가로세로를 4a, 3a로 두고 a 구하기","고비":true,"힌트":"4a×3a=432에서 a는?","식":["$4a\\times3a=432$","$a^2=36,\\ a=6$"],"설명":"가로세로의 비가 4:3이므로 4a, 3a로 두고 넓이식을 풀면 a=6이다.","확인":"6","스킬":"A8"},{"제목":"바닥의 가로, 세로 길이 구하기","힌트":"a=6을 대입하면 바닥의 가로, 세로는?","식":["$4a=24,\\ 3a=18$"],"설명":"바닥의 가로는 24cm, 세로는 18cm이다.","확인":null,"스킬":"C7"},{"제목":"종이의 가로, 세로 길이 구하기","힌트":"네 모퉁이에서 5cm씩 잘라내므로 종이는 바닥보다 양쪽으로 얼마나 더 커야 할까?","식":["$24+5\\times2=34$","$18+5\\times2=28$"],"설명":"바닥의 각 변에 접어 올리는 5cm를 양쪽에 더하면 종이의 가로 34cm, 세로 28cm를 얻는다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-bd55ac8eb5c4":{"길":"축 조건으로 b를 구하고 대칭으로 점을 표현해 둘레를 완전제곱으로 만든다","단계":[{"제목":"축 조건으로 b 구하기","힌트":"축이 x=5이므로 -b/(-2)=5에서 b는?","식":["$b=10$"],"설명":"이차함수의 축 공식을 이용해 b를 구한다.","확인":null,"스킬":"A6"},{"제목":"B, A, D 좌표 놓기","고비":true,"힌트":"D는 축에 대해 B와 대칭인 점을 지나는 점이다","식":["$B(k,0),\\ A(k,-k^{2}+10k),\\ D(10-k,-k^{2}+10k)$"],"설명":"축 x=5에 대해 대칭이므로 D의 x좌표는 10-k이다.","확인":null,"스킬":"G11"},{"제목":"둘레 식 세우기","힌트":"BC와 AB의 길이를 이용해 둘레를 쓰면?","식":["$l=2(10-2k-k^{2}+10k)=-2k^{2}+16k+20$"],"설명":"직사각형의 둘레 공식으로 l을 k에 대한 식으로 나타낸다.","확인":null,"스킬":"A6"},{"제목":"완전제곱으로 최댓값 구하기","힌트":"이차식을 완전제곱으로 바꾸면?","식":["$l=-2(k-4)^{2}+52$"],"설명":"완전제곱 꼴로 바꾸면 k=4일 때 최댓값 52를 갖는다.","확인":"52","스킬":"A6"}],"fb":"fig/ns/"},"ns-bfbf9bf84671":{"길":"접은 각의 성질로 이등변삼각형을 확인한 뒤 보조선을 그어 피타고라스 정리를 두 번 적용한다","단계":[{"제목":"접은 각의 성질로 이등변삼각형 찾기","힌트":"∠DPQ와 ∠BPQ, 엇각 ∠PQB는 서로 어떤 관계일까?","식":[],"설명":"접었으므로 ∠DPQ=∠BPQ이고 엇각이므로 ∠DPQ=∠PQB이다. 따라서 ∠BPQ=∠PQB=x로 △BPQ는 이등변삼각형이다.","확인":null,"스킬":"S10"},{"제목":"BP, BQ 길이 구하기","힌트":"이등변삼각형이므로 BP=BQ이고, 접었으므로 PD와도 같을까?","식":["$\\overline{BP}=\\overline{BQ}=\\overline{PD}=10$"],"설명":"이등변삼각형의 성질과 접은 변의 길이가 같다는 사실로 BP=BQ=PD=10을 얻는다.","확인":null,"스킬":"S10"},{"제목":"보조선 그어 BH 구하기","힌트":"점 P에서 BQ에 내린 수선의 발을 H라 하면 PH, BH는?","식":["$\\overline{PH}=\\overline{AB}=6$","$\\overline{BH}=\\sqrt{10^2-6^2}=8$"],"설명":"직사각형의 성질로 PH=AB=6이고, 직각삼각형 PBH에서 피타고라스 정리로 BH를 구한다.","확인":null,"스킬":"S3"},{"제목":"HQ, PQ 길이 구하기","고비":true,"힌트":"BQ=10에서 BH를 빼면 HQ는? 그리고 PQ는?","식":["$\\overline{HQ}=10-8=2$","$\\overline{PQ}=\\sqrt{6^2+2^2}=2\\sqrt{10}$"],"설명":"HQ=BQ-BH로 구하고, 직각삼각형 PHQ에서 PQ를 구한다.","확인":null,"스킬":"S3"},{"제목":"cos x 계산하기","힌트":"직각삼각형 PHQ에서 cos x는?","식":["$\\cos x=\\dfrac{\\overline{QH}}{\\overline{PQ}}=\\dfrac{2}{2\\sqrt{10}}=\\dfrac{\\sqrt{10}}{10}$"],"설명":"직각삼각형 PHQ에서 cos x의 정의로 값을 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-c552d9166cbf":{"길":"꼭짓점과 한 점으로 식을 구한 뒤 PQ의 길이를 완전제곱으로 만들어 최솟값을 찾는다","단계":[{"제목":"이차함수 식 구하기","힌트":"꼭짓점(1,0)과 점(0,-1)을 지나므로?","식":["$y=a(x-1)^{2},\\ -1=a(0-1)^{2}\\Rightarrow a=-1$"],"설명":"꼭짓점과 그래프가 지나는 한 점을 이용해 식을 구한다.","확인":null,"스킬":"A6"},{"제목":"P, Q 좌표 놓기","힌트":"P는 y=x 위, Q는 P와 x좌표가 같은 그래프 위의 점","식":["$P(k,k),\\ Q(k,-(k-1)^{2})$"],"설명":"P의 x좌표 k를 이용해 Q의 좌표도 나타낸다.","확인":null,"스킬":"S4"},{"제목":"PQ 길이를 완전제곱으로","고비":true,"힌트":"PQ=k-(Q의 y좌표)를 정리하면?","식":["$\\overline{PQ}=k^{2}-k+1=\\left(k-\\frac{1}{2}\\right)^{2}+\\frac{3}{4}$"],"설명":"두 점의 y좌표 차이를 완전제곱 꼴로 정리한다.","확인":null,"스킬":"A6"},{"제목":"최솟값 읽기","힌트":"완전제곱 꼴에서 최솟값은?","식":["$\\frac{3}{4}$"],"설명":"완전제곱 꼴에서 최솟값은 3/4이다.","확인":"3/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-c8e77ad29418":{"길":"세로를 20-2x로 놓아 넓이를 완전제곱으로 만들어 최댓값과 x를 더한다","단계":[{"제목":"넓이 식 세우기","힌트":"세로 길이는 20-2x이므로 넓이는?","식":["$S=x(20-2x)=-2x^{2}+20x$"],"설명":"가로 x, 세로 20-2x로 넓이 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"완전제곱으로 최댓값 구하기","고비":true,"힌트":"완전제곱 꼴로 바꾸면?","식":["$S=-2(x-5)^{2}+50$"],"설명":"완전제곱 꼴로 바꾸면 x=5일 때 최댓값 50을 갖는다.","확인":null,"스킬":"A6"},{"제목":"x와 최댓값 더하기","힌트":"x=5와 최댓값 50을 더하면?","식":["$5+50=55$"],"설명":"가로의 길이와 최대 넓이를 더하면 55이다.","확인":"55","스킬":"N6"}],"fb":"fig/ns/"},"ns-cab2be7208fc":{"길":"직사각형의 두 꼭짓점을 지날 때를 각각 구해 a의 범위를 정하고 정수의 합을 구한다","단계":[{"제목":"A를 지날 때 a 구하기","힌트":"포물선이 점 A를 지날 때 a는 얼마가 될까?","식":["$a=4$"],"설명":"포물선 y=ax²이 직사각형의 꼭짓점 A를 지날 때 대입하면 a=4이다.","확인":null,"스킬":"A3"},{"제목":"C를 지날 때 a 구하기","힌트":"점 C를 지날 때는?","식":["$2=16a$","$a=\\frac{1}{8}$"],"설명":"포물선이 점 C를 지날 때 대입하면 16a=2이므로 a=1/8이다.","확인":null,"스킬":"A3"},{"제목":"a의 범위 정하기","고비":true,"힌트":"포물선이 직사각형 둘레의 두 점을 지나려면 a는 두 극단값 사이에 있어야 할까?","식":["$\\frac{1}{8}<a<4$"],"설명":"포물선이 직사각형 둘레 위의 서로 다른 두 점을 지나려면 a는 두 극단값인 1/8과 4 사이에 있어야 한다.","확인":null,"스킬":"C2"},{"제목":"정수 세어 합 구하기","힌트":"1/8과 4 사이의 정수는?","식":["$1,2,3$","$1+2+3=6$"],"설명":"범위 안의 정수는 1, 2, 3이고 합은 6이다.","확인":"6","스킬":"P4"}],"fb":"fig/ns/"},"ns-cbb3c12686ec":{"길":"가로·세로를 x초 후 식으로 나타내 넓이 조건을 이차방정식으로 세운다","단계":[{"제목":"x초 후 가로·세로 나타내기","힌트":"가로는 매초 3cm씩, 세로는 매초 1cm씩 변한다면?","식":["$27+3x,\\ 21-x$"],"설명":"x초 후 가로의 길이는 27+3x, 세로의 길이는 21-x이다.","확인":null,"스킬":"C7"},{"제목":"넓이 조건 이차방정식 세우기","힌트":"처음 넓이보다 39만큼 작다는 조건을 식으로 쓰면?","식":["$(27+3x)(21-x)=27\\times21-39$"],"설명":"변한 후 넓이가 처음 넓이보다 39 작다는 조건을 등식으로 세운다.","확인":null,"스킬":"C7"},{"제목":"전개해 정리하기","고비":true,"힌트":"좌변을 전개하고 이항하면?","식":["$-3x^2+36x+567=528$","$3x^2-36x-39=0$","$x^2-12x-13=0$"],"설명":"전개해 정리하면 x²-12x-13=0의 이차방정식이 된다.","확인":null,"스킬":"A3"},{"제목":"인수분해로 풀어 조건 확인하기","힌트":"(x-13)(x+1)=0에서 x>0인 해는?","식":["$(x-13)(x+1)=0$","$\\therefore x=13$"],"설명":"인수분해하면 x=13 또는 x=-1인데 x>0이므로 x=13이다.","확인":"13","스킬":"N4"}],"fb":"fig/ns/"},"ns-cd376711e8e8":{"길":"B,E의 좌표를 구하고 CD=AE 조건으로 C,D를 구해 오각형을 사다리꼴과 삼각형으로 나눠 더한다","단계":[{"제목":"B,E의 좌표 구하기","힌트":"y좌표가 8일 때 포물선 위의 x좌표는?","식":["$8=\\frac{1}{2}x^2$","$x=\\pm4$"],"설명":"두 점 B,E의 y좌표가 8이므로 대입하면 x=±4이다. B(-4,8), E(4,8)이다.","확인":null,"스킬":"G1"},{"제목":"C,D의 좌표 구하기","고비":true,"힌트":"CD=AE=4라면 C,D의 x좌표는?","식":["$\\overline{CD}=\\overline{AE}=4$","$C(-2,2),\\ D(2,2)$"],"설명":"AE의 길이가 4이므로 CD도 4이다. C,D는 원점에 대해 대칭이며 포물선 위에 있으므로 x좌표는 ±2, y좌표는 2이다.","확인":null,"스킬":"C7"},{"제목":"사다리꼴과 삼각형으로 나눠 넓이 구하기","힌트":"오각형 BCODE를 사다리꼴 BCDE와 삼각형 OCD로 나누면?","식":["$\\square BCDE=\\frac{1}{2}\\times(8+4)\\times6=36$","$\\triangle OCD=\\frac{1}{2}\\times4\\times2=4$"],"설명":"사다리꼴 BCDE의 넓이는 윗변 CD=4, 아랫변 BE=8, 높이 6이므로 36이고, 삼각형 OCD의 넓이는 4이다.","확인":null,"스킬":"S12"},{"제목":"두 넓이 더해 답 구하기","힌트":"두 넓이를 더하면?","식":["$36+4=40$"],"설명":"사다리꼴과 삼각형의 넓이를 더하면 오각형 BCODE의 넓이는 40이다.","확인":"40","스킬":"S12"}],"fb":"fig/ns/"},"ns-d5452ba500eb":{"길":"늘어난 원과 처음 원의 넓이 차를 식으로 세워 완전제곱으로 푼다","단계":[{"제목":"넓이 조건 세우기","힌트":"늘어난 원의 넓이에서 처음 원의 넓이를 빼면 처음 넓이의 3배라면?","식":["$\\pi(2+x)^2-\\pi\\times2^2=3\\times\\pi\\times2^2$"],"설명":"색칠한 부분의 넓이 조건을 식으로 세운다.","확인":null,"스킬":"C7"},{"제목":"정리해 완전제곱식 만들기","고비":true,"힌트":"양변을 π로 나누고 정리하면?","식":["$(x+2)^2=16$"],"설명":"π로 나누고 정리하면 (x+2)²=16이 된다.","확인":null,"스킬":"A6"},{"제목":"x 구하기","힌트":"x+2=±4에서 x>0인 값은?","식":["$x+2=\\pm4$","$\\therefore x=2$"],"설명":"x+2=4를 택하면(x>0) x=2이다.","확인":"2","스킬":"N8"}],"fb":"fig/ns/"},"ns-dc60e88140b0":{"길":"정사면체의 대칭을 이용해 필요한 길이를 구한 뒤, 부피를 두 가지로 표현하는 부피법으로 점과 평면 사이의 거리를 구한다","단계":[{"제목":"밑면에 내린 수선의 발 H' 구하기","힌트":"꼭짓점 O에서 △ABC에 내린 수선의 발 H'은 무게중심이고, OM, MC는?","식":["$\\overline{MC}=\\overline{OM}=\\dfrac{\\sqrt3}{2}\\times\\sqrt3=\\dfrac32$","$\\overline{MH'}=\\dfrac13\\times\\dfrac32=\\dfrac12$"],"설명":"정삼각형의 중선 길이로 OM, MC를 구하고, 무게중심은 중선을 2:1로 나누므로 MH'을 구한다.","확인":null,"스킬":"S11"},{"제목":"높이 OH' 구하기","힌트":"직각삼각형 OH'M에서 OH'은?","식":["$\\overline{OH'}=\\sqrt{\\left(\\dfrac32\\right)^2-\\left(\\dfrac12\\right)^2}=\\sqrt2$"],"설명":"직각삼각형에서 피타고라스 정리로 정사면체의 높이 OH'을 구한다.","확인":null,"스킬":"S3"},{"제목":"삼각뿔 O-MBC의 부피 구하기","고비":true,"힌트":"삼각뿔 O-MBC의 부피는 원래 정사면체 부피의 몇 배일까?","식":["$\\dfrac12\\times\\left(\\dfrac13\\times\\dfrac{\\sqrt3}4\\times(\\sqrt3)^2\\times\\sqrt2\\right)=\\dfrac{\\sqrt6}8$"],"설명":"M이 AB의 중점이므로 O-MBC의 부피는 정사면체 부피의 절반이다.","확인":null,"스킬":"S11"},{"제목":"MH 구하기","힌트":"같은 부피를 M에서 △OBC까지의 거리 MH로도 표현하면?","식":["$\\dfrac13\\times\\dfrac{\\sqrt3}4\\times(\\sqrt3)^2\\times\\overline{MH}=\\dfrac{\\sqrt6}8\\Rightarrow\\overline{MH}=\\dfrac{\\sqrt2}2$"],"설명":"같은 부피를 밑면 △OBC와 높이 MH로 표현한 식을 풀어 MH를 구한다.","확인":null,"스킬":"S11"},{"제목":"cos x 계산하기","힌트":"직각삼각형 OMH에서 cos x는?","식":["$\\cos x=\\dfrac{\\overline{MH}}{\\overline{OM}}=\\dfrac{\\frac{\\sqrt2}2}{\\frac32}=\\dfrac{\\sqrt2}3$"],"설명":"직각삼각형 OMH에서 cos x의 정의로 값을 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-debdff32be23":{"길":"A,B를 대칭점으로 문자로 두고 AB:BC 비율조건으로 방정식을 세워 a를 구한다","단계":[{"제목":"A,B,C를 문자로 나타내기","힌트":"A(-a,a²), B(a,a²)이면 C는?","식":["$A(-a,\\ a^2),\\ B(a,\\ a^2)$","$C\\left(a,\\ -\\frac{1}{4}a^2\\right)$"],"설명":"B의 x좌표가 a이므로 C는 y=-1/4x²의 그래프 위에서 x좌표가 같은 점이다.","확인":null,"스킬":"S4"},{"제목":"비율조건으로 방정식 세우기","고비":true,"힌트":"AB:BC=4:5를 길이로 나타내면?","식":["$\\overline{AB}=2a,\\ \\overline{BC}=\\frac{5}{4}a^2$","$2a:\\frac{5}{4}a^2=4:5$"],"설명":"AB, BC의 길이를 a로 나타내고 비율조건을 식으로 세운다.","확인":null,"스킬":"C7"},{"제목":"방정식을 풀어 좌표 구하기","힌트":"정리한 이차방정식을 풀면?","식":["$5a^2-10a=0$","$a=2\\ (\\because a>0)$"],"설명":"방정식을 풀면 a=2이므로 A의 좌표는 (-2,4)이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-e1b566407fe0":{"길":"점 B를 문자로 두어 변의 길이를 나타내고 둘레조건으로 이차방정식을 세워 넓이를 구한다","단계":[{"제목":"변의 길이를 문자로 나타내기","힌트":"B(a, 3/2a²)이면 A,D는? AB,BD의 길이는?","식":["$A\\left(-a,\\ \\frac{3}{2}a^2\\right),\\ D(a,\\,0)$","$\\overline{AB}=2a,\\ \\overline{BD}=\\frac{3}{2}a^2$"],"설명":"B의 x좌표를 a(a>0)라 하면 A,D의 좌표가 정해지고, AB=2a, BD=3/2a²이다.","확인":null,"스킬":"S4"},{"제목":"둘레조건으로 방정식 세우기","고비":true,"힌트":"둘레가 4라는 조건을 식으로 쓰면?","식":["$2\\left(2a+\\frac{3}{2}a^2\\right)=4$","$3a^2+4a-4=0$"],"설명":"직사각형 둘레 공식을 이용해 이차방정식을 세운다.","확인":null,"스킬":"C7"},{"제목":"방정식을 풀어 넓이 구하기","힌트":"(3a-2)(a+2)=0을 풀면?","식":["$(3a-2)(a+2)=0$","$a=\\frac{2}{3}$"],"설명":"인수분해하면 a=2/3(a>0)이므로 AB=4/3, BD=2/3이고 넓이는 4/3×2/3=8/9이다.","확인":"8/9","스킬":"A6"}],"fb":"fig/ns/"},"ns-e41b10a56584":{"길":"AC=2x로 놓고 세 반원의 넓이 차를 식으로 세워 조건에 맞는 값을 고른다","단계":[{"제목":"변수 설정하기","힌트":"AC=2x, BC=12-2x로 놓으면 AC>BC 조건은?","식":["$\\overline{AC}=2x,\\ \\overline{BC}=12-2x$","$x>3$"],"설명":"AC=2x로 놓으면 BC=12-2x이고, AC>BC에서 x>3이다.","확인":null,"스킬":"C7"},{"제목":"세 반원의 넓이로 식 세우기","고비":true,"힌트":"큰 반원에서 작은 두 반원을 뺀 넓이가 색칠한 부분이라면?","식":["$\\frac{1}{2}\\pi\\times6^2-\\frac{1}{2}\\pi x^2-\\frac{1}{2}\\pi(6-x)^2=\\frac{27}{4}\\pi$"],"설명":"가장 큰 반원의 넓이에서 두 작은 반원의 넓이를 뺀 식을 세운다.","확인":null,"스킬":"S12"},{"제목":"정리해 이차방정식 풀기","힌트":"π를 나누고 정리하면?","식":["$4x^2-24x+27=0$","$(2x-9)(2x-3)=0$"],"설명":"정리해 인수분해하면 x=9/2 또는 x=3/2이다.","확인":null,"스킬":"N4"},{"제목":"조건에 맞는 값 고르고 AC 구하기","힌트":"x>3인 값을 택해 AC=2x를 계산하면?","식":["$x=\\frac{9}{2}\\ (\\because x>3)$","$\\overline{AC}=2x=9$"],"설명":"x>3인 x=9/2를 택하면 AC=9cm이다.","확인":"9","스킬":"C2"}],"fb":"fig/ns/"},"ns-e5107c4d8dab":{"길":"직사각형의 내각을 나눠 얻은 두 직각삼각형에서 변을 구해 sin75°로 합친다","단계":[{"제목":"△ABE에서 AB, BE 구하기","힌트":"AE=2이고 ∠AEB=90°, ∠ABE=45°일 때 AB, BE는?","식":["$\\overline{AB}=\\frac{2}{\\sin45^{\\circ}}=2\\sqrt2$","$\\overline{BE}=\\frac{2}{\\tan45^{\\circ}}=2$"],"설명":"직각삼각형 ABE에서 삼각비로 AB와 BE를 구한다.","확인":null,"스킬":"S6"},{"제목":"∠FEB 구하기","힌트":"직사각형의 한 내각 90°에서 ∠BED를 빼면?","식":["$\\angle FEB=90^{\\circ}-60^{\\circ}=30^{\\circ}$"],"설명":"∠FED=90°(직사각형의 내각)에서 ∠BED=60°를 빼면 ∠FEB를 얻는다.","확인":null,"스킬":"C7"},{"제목":"∠AEF 구하기","고비":true,"힌트":"∠AEB에서 ∠FEB를 빼면?","식":["$\\angle AEF=90^{\\circ}-30^{\\circ}=60^{\\circ}$"],"설명":"∠AEB=90°에서 ∠FEB=30°를 빼면 ∠AEF를 얻는다.","확인":null,"스킬":"C7"},{"제목":"△AEF에서 AF, FE 구하기","힌트":"직각삼각형 AEF에서 AE=2, ∠AEF=60°이면 AF, FE는?","식":["$\\overline{AF}=2\\sin60^{\\circ}=\\sqrt3$","$\\overline{FE}=2\\cos60^{\\circ}=1$"],"설명":"직각삼각형 AEF에서 삼각비로 AF와 FE를 구한다.","확인":null,"스킬":"S6"},{"제목":"△BDE에서 BD, ED 구하기","힌트":"직각삼각형 BDE에서 BE=2, ∠BED=60°이면 BD, ED는?","식":["$\\overline{BD}=2\\sin60^{\\circ}=\\sqrt3$","$\\overline{ED}=2\\cos60^{\\circ}=1$"],"설명":"직각삼각형 BDE에서 삼각비로 BD와 ED를 구한다.","확인":null,"스킬":"S6"},{"제목":"AC 길이로 sin75° 구하기","힌트":"직사각형에서 FC=ED이므로 AC=AF+FC, sin75°=AC/AB는?","식":["$\\overline{AC}=\\overline{AF}+\\overline{ED}=\\sqrt3+1$","$\\sin75^{\\circ}=\\frac{\\overline{AC}}{\\overline{AB}}=\\frac{\\sqrt3+1}{2\\sqrt2}=\\frac{\\sqrt6+\\sqrt2}{4}$"],"설명":"직사각형의 대변 FC=ED=1을 이용해 AC를 구하고, 직각삼각형 ABC에서 sin75°를 계산한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-e5484a89bb8b":{"길":"점 B를 문자로 두어 A,C의 좌표를 구하고 AB:BC 비율조건으로 a를 구해 넓이를 계산한다","단계":[{"제목":"A,B,C를 문자로 나타내기","힌트":"B(a,a²)이면 A,C는?","식":["$A(-a,\\ a^2),\\ C\\left(a,\\ -\\frac{1}{2}a^2\\right)$"],"설명":"B의 x좌표를 a(a>0)라 하면 A는 대칭점, C는 y=-1/2x²의 그래프 위에서 x좌표가 같은 점이다.","확인":null,"스킬":"S4"},{"제목":"AB, BC의 길이 나타내기","힌트":"AB, BC를 a로 나타내면?","식":["$\\overline{AB}=2a,\\ \\overline{BC}=\\frac{3}{2}a^2$"],"설명":"두 점 사이의 거리로 AB, BC를 a에 관한 식으로 쓴다.","확인":null,"스킬":"S4"},{"제목":"비율조건으로 방정식 세우고 풀기","고비":true,"힌트":"AB:BC=4:1을 식으로 세우면?","식":["$2a:\\frac{3}{2}a^2=4:1$","$6a^2-2a=0$","$a=\\frac{1}{3}$"],"설명":"비율조건을 식으로 세워 풀면 a=1/3(a>0)이다.","확인":null,"스킬":"C7"},{"제목":"넓이 계산하기","힌트":"AB, BC 값을 구해 넓이 공식에 넣으면?","식":["$\\overline{AB}=\\frac{2}{3},\\ \\overline{BC}=\\frac{1}{6}$","$\\frac{1}{2}\\times\\frac{2}{3}\\times\\frac{1}{6}=\\frac{1}{18}$"],"설명":"AB=2/3, BC=1/6이므로 삼각형의 넓이는 1/18이다.","확인":"1/18","스킬":"A6"}],"fb":"fig/ns/"},"ns-e868dcd42ea1":{"길":"점 C에서 AD의 연장선에 내린 수선의 발 H를 잡아 닮은 두 삼각형으로 sin x를 구한다","단계":[{"제목":"점 C에서 수선의 발 H 내리기","고비":true,"힌트":"AD의 연장선 위에 점 C에서 내린 수선의 발을 H라 하면?","식":[],"설명":"점 C에서 AD의 연장선 위에 내린 수선의 발을 H라 하자.","확인":null,"스킬":"S2"},{"제목":"AB, BD 구하기","힌트":"직각이등변삼각형 ABD에서 AD=√2일 때 AB, BD는?","식":["$\\sqrt2:\\overline{AB}=\\sqrt2:1\\Rightarrow\\overline{AB}=1$","$\\overline{BD}=1$"],"설명":"직각이등변삼각형 ABD의 변의 비로 AB와 BD를 구한다.","확인":"1","스킬":"S3"},{"제목":"CH 구하기","힌트":"△ABD∽△CHD(AA닮음)이므로 비례식을 세우면?","식":["$1:\\overline{CH}=\\sqrt2:1\\Rightarrow\\overline{CH}=\\frac{\\sqrt2}{2}$"],"설명":"두 삼각형이 닮음이므로 비례식으로 CH를 구한다.","확인":null,"스킬":"S1"},{"제목":"AC 구하기","힌트":"AB=1, BC=BD+DC=2인 직각삼각형 ABC에서 AC는?","식":["$\\overline{AC}=\\sqrt{1^2+2^2}=\\sqrt5$"],"설명":"직각삼각형 ABC에서 피타고라스 정리로 AC를 구한다.","확인":null,"스킬":"S3"},{"제목":"sin x 계산하기","힌트":"직각삼각형 ACH에서 sin x=CH/AC는?","식":["$\\sin x=\\frac{\\frac{\\sqrt2}{2}}{\\sqrt5}=\\frac{\\sqrt{10}}{10}$"],"설명":"직각삼각형 ACH에서 삼각비 정의로 sin x를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-ef797fde7576":{"길":"A,B를 대칭점으로 구하고 CD=2AB 조건으로 C,D를 잡아 사다리꼴 넓이 공식으로 a를 구한다","단계":[{"제목":"A,B의 좌표 구하기","힌트":"y=-3x²와 선분 AB가 x축과 평행하다는 조건으로 A,B는?","식":["$A(-1,\\,-3),\\ B(1,\\,-3)$"],"설명":"A,B는 y축에 대칭이며 y=-3x² 위의 점이고, 선분 AB가 x축과 평행하므로 y좌표가 같다.","확인":null,"스킬":"S4"},{"제목":"C,D의 좌표 구하기","고비":true,"힌트":"CD=2AB=4이고 C,D가 y=ax² 위에 있다면?","식":["$\\overline{AB}=2,\\ \\overline{CD}=4$","$C(2,\\,4a),\\ D(-2,\\,4a)$"],"설명":"AB=2이므로 CD=4이고, C,D는 y=ax² 위에서 x좌표가 ±2인 점이다.","확인":null,"스킬":"C7"},{"제목":"사다리꼴 넓이 공식으로 a 구하기","힌트":"사다리꼴 넓이 공식에 넣으면?","식":["$\\frac{1}{2}\\times(2+4)\\times(4a+3)=21$","$4a+3=7,\\ a=1$"],"설명":"윗변 AB=2, 아랫변 CD=4, 높이 4a+3인 사다리꼴의 넓이 공식을 세워 풀면 a=1이다.","확인":"1","스킬":"S12"}],"fb":"fig/ns/"},"ns-f000aaf76f3c":{"길":"세 변의 길이를 한 문자 x로 나타내고 정사각형에서 두 삼각형을 뺀 넓이를 완전제곱 꼴로 바꾼다","단계":[{"제목":"변의 길이를 x로 나타내기","힌트":"AP=AR, BP=BQ를 이용하면 각 변의 길이는?","식":["$\\overline{BP}=\\overline{BQ}=x$"],"설명":"BP=BQ=x라 하면 AP=AR=CQ=14-x, DR=x이다.","확인":null,"스킬":"C7"},{"제목":"넓이 식 세우기","고비":true,"힌트":"정사각형 전체에서 두 삼각형을 빼면 삼각형 PQR의 넓이는?","식":["$\\triangle PQR=\\frac{1}{2}\\times14\\times14-\\frac{1}{2}(14-x)^2-\\frac{1}{2}x^2$"],"설명":"정사각형 절반 넓이에서 두 직각삼각형 APR, BPQ의 넓이를 뺀다.","확인":null,"스킬":"S12"},{"제목":"완전제곱 꼴로 정리하기","힌트":"전개해서 정리하면?","식":["$=-x^2+14x=-(x-7)^2+49$"],"설명":"전개하고 동류항을 정리해 완전제곱 꼴로 바꾼다.","확인":null,"스킬":"A6"},{"제목":"최댓값 구하기","힌트":"x=7일 때 넓이는?","식":["$x=7$일 때 최댓값 $49$"],"설명":"x=7일 때 삼각형 PQR의 넓이가 최대이며 그 값은 49이다.","확인":"49","스킬":"A6"}],"fb":"fig/ns/"},"ns-f05df75475d6":{"길":"두 점을 매개변수로 놓고 정사각형 조건 AB=BC를 식으로 세워 인수분해한다","단계":[{"제목":"점 B, D의 좌표를 문자로 놓기","힌트":"두 점이 곡선 위에 있으므로 좌표는?","식":["$B\\left(b,\\,\\frac{1}{3}b^2\\right),\\ D\\left(d,\\,\\frac{1}{3}d^2\\right)$"],"설명":"두 점을 매개변수 b, d로 놓는다.","확인":null,"스킬":"G1"},{"제목":"정사각형 조건 AB=BC로 식 세우기","고비":true,"힌트":"정사각형이므로 두 변의 길이가 같다는 조건은?","식":["$\\frac{1}{3}d^2-\\frac{1}{3}b^2=d-b$"],"설명":"정사각형이므로 AB=BC이고 이를 좌표로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"인수분해해 정리하기","힌트":"좌변을 인수분해하면?","식":["$\\frac{1}{3}(d+b)(d-b)=d-b$","$(b\\ne d)$"],"설명":"양변을 (d-b)로 나누면 (1/3)(d+b)=1이 된다.","확인":null,"스킬":"A2"},{"제목":"b+d 구하기","힌트":"최종 값은?","식":["$b+d=3$"],"설명":"점 B와 점 D의 x좌표의 합은 3이며 이는 점 B와 점 C의 x좌표의 합과 같다.","확인":"3","스킬":"N5"}],"fb":"fig/ns/"},"ns-f339a8548c54":{"길":"P의 좌표를 문자로 놓고 두 삼각형의 넓이를 식으로 세워 이차방정식을 푼다","단계":[{"제목":"P의 좌표 설정하기","힌트":"P가 y=2x 위의 점이면 좌표는?","식":["$P(p,\\ 2p)$"],"설명":"P는 직선 y=2x 위의 점이므로 P(p, 2p)로 둔다.","확인":null,"스킬":"G10"},{"제목":"두 삼각형의 넓이 식 세우기","힌트":"△POQ와 △APR의 넓이를 p로 나타내면?","식":["$\\triangle POQ=\\frac{1}{2}\\times p\\times2p=p^2$","$\\triangle APR=\\frac{1}{2}\\times(10-p)\\times(20-2p)=(10-p)^2$"],"설명":"두 삼각형의 넓이를 각각 p에 관한 식으로 나타낸다.","확인":null,"스킬":"G10"},{"제목":"넓이 조건으로 이차방정식 세우기","고비":true,"힌트":"색칠한 부분의 넓이 68은 두 삼각형 넓이의 합과 같다면?","식":["$p^2+(10-p)^2=68$","$p^2-10p+16=0$"],"설명":"두 넓이의 합이 68이라는 조건을 정리해 이차방정식을 세운다.","확인":null,"스킬":"A6"},{"제목":"조건에 맞는 p 고르고 넓이 구하기","힌트":"(p-2)(p-8)=0에서 OQ<PR을 만족하는 p는?","식":["$(p-2)(p-8)=0$","$p=2\\ (\\because\\overline{OQ}<\\overline{PR})$"],"설명":"인수분해해 p=2 또는 8인데 조건에 맞는 p=2를 택한다.","확인":null,"스킬":"C2"},{"제목":"넓이의 비 계산하기","힌트":"p=2일 때 두 넓이는 각각 얼마이고 비는?","식":["$\\triangle POQ=4,\\ \\triangle APR=64$","$4:64=1:16$"],"설명":"p=2를 대입해 넓이를 구하고 비를 정리하면 1:16이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-f64c62da7ab0":{"길":"직사각형에서 삼각형 PBQ의 넓이를 빼는 식으로 오각형의 넓이를 표현해 이차방정식을 세운다","단계":[{"제목":"t초 후 각 변의 길이 나타내기","힌트":"P, Q가 1초에 각각 1/2cm, 1cm씩 움직인다면 AP, BQ, PB는?","식":["$\\overline{AP}=\\frac{1}{2}t,\\ \\overline{BQ}=t,\\ \\overline{PB}=10-\\frac{1}{2}t$"],"설명":"t초 후 P, Q의 위치와 PB의 길이를 t로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"오각형 넓이를 직사각형-삼각형으로 표현하기","고비":true,"힌트":"직사각형 넓이에서 삼각형 PBQ의 넓이를 빼면 오각형의 넓이가 될까?","식":["$15\\times10-\\frac{1}{2}\\times t\\times\\left(10-\\frac{1}{2}t\\right)=134$"],"설명":"직사각형 ABCD의 넓이에서 잘려나간 삼각형 PBQ의 넓이를 뺀 것이 오각형 APQCD의 넓이이다.","확인":null,"스킬":"S12"},{"제목":"정리해 이차방정식 풀기","힌트":"전개해 정리하면?","식":["$t^2-20t+64=0$","$(t-4)(t-16)=0$"],"설명":"정리해 인수분해하면 t=4 또는 t=16이다.","확인":null,"스킬":"N4"},{"제목":"범위 조건으로 답 정하기","힌트":"Q가 변 BC 위에 있으려면 t는 15를 넘을 수 없다면?","식":["$0<t<15$"],"설명":"Q가 변 BC 위에 있어야 하므로 t는 15보다 작아야 하고, 따라서 t=4이다.","확인":"4","스킬":"C2"}],"fb":"fig/ns/"},"ns-f99f49549c4b":{"길":"x초 후 가로세로를 x로 나타내 넓이를 완전제곱 꼴로 바꾼다","단계":[{"제목":"x초 후 가로, 세로 나타내기","힌트":"가로는 매초 2cm씩 줄고 세로는 매초 3cm씩 늘면?","식":["$60-2x,\\ 30+3x$"],"설명":"x초 후 가로와 세로의 길이를 x로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"넓이 식을 전개해 정리하기","고비":true,"힌트":"두 식을 곱해 전개하면?","식":["$y=(60-2x)(30+3x)=-6x^2+120x+1800$"],"설명":"넓이를 x에 관한 이차식으로 전개한다.","확인":null,"스킬":"A3"},{"제목":"완전제곱 꼴로 바꿔 x 구하기","힌트":"완전제곱 꼴로 바꾸면?","식":["$=-6(x-10)^2+2400$"],"설명":"완전제곱 꼴로 정리하면 x=10일 때 넓이가 최대이다.","확인":"10","스킬":"A6"}],"fb":"fig/ns/"},"ns-fab079b94cb7":{"길":"점 P를 매개변수로 놓아 점 Q의 좌표를 구하고 PQ의 길이를 완전제곱 꼴로 바꾼다","단계":[{"제목":"점 P를 매개변수로 놓고 점 Q의 좌표 구하기","힌트":"P(a, 2a²+1)이면 Q의 y좌표는 같고 직선 위에 있으므로?","식":["$P(a,\\,2a^2+1)$","$2a^2+1=2x-1\\ \\Rightarrow\\ x=a^2+1$"],"설명":"점 Q는 점 P와 y좌표가 같고 직선 y=2x-1 위에 있으므로 x좌표를 구한다.","확인":null,"스킬":"G1"},{"제목":"PQ의 길이를 a에 관한 식으로 나타내기","고비":true,"힌트":"두 점의 x좌표의 차는?","식":["$\\overline{PQ}=(a^2+1)-a=a^2-a+1$"],"설명":"두 점의 x좌표의 차가 PQ의 길이이다.","확인":null,"스킬":"A6"},{"제목":"완전제곱 꼴로 바꿔 최솟값 구하기","힌트":"완전제곱 꼴로 바꾸면?","식":["$=\\left(a-\\frac{1}{2}\\right)^2+\\frac{3}{4}$"],"설명":"완전제곱 꼴로 정리하면 PQ의 최솟값은 3/4이다.","확인":"3/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-fc94bf527ad8":{"길":"네 점의 좌표를 문자로 놓고 조건 AB=PQ로 이차방정식을 세워 풀고 사다리꼴 넓이를 구한다","단계":[{"제목":"점 C, D의 좌표 구하기","힌트":"y=-6일 때 x는?","식":["$-6=-\\frac{1}{2}x^2,\\ x^2=12$","$x=\\pm2\\sqrt3$"],"설명":"y좌표가 -6인 두 점의 x좌표를 구하면 D(-2√3,-6), C(2√3,-6)이다.","확인":null,"스킬":"A6"},{"제목":"점 A, B를 문자로 놓기","힌트":"A, B는 곡선 위에서 y좌표가 같으므로?","식":["$A\\left(-a,\\,-\\frac{1}{2}a^2\\right),\\ B\\left(a,\\,-\\frac{1}{2}a^2\\right)\\ (a>0)$"],"설명":"대칭인 두 점을 a로 놓는다.","확인":null,"스킬":"G1"},{"제목":"조건 AB=PQ로 방정식 세우기","고비":true,"힌트":"AB=2a이고 조건 AB=PQ를 식으로 쓰면?","식":["$2a=-\\frac{1}{2}a^2+6$","$a^2+4a-12=0$"],"설명":"주어진 조건을 이차방정식으로 옮긴다.","확인":null,"스킬":"C7"},{"제목":"인수분해해 a 구하기","힌트":"인수분해하면?","식":["$(a+6)(a-2)=0$","$a=2\\ (a>0)$"],"설명":"a>0인 근을 택하면 a=2이다.","확인":"2","스킬":"A6"},{"제목":"사다리꼴 넓이 구하기","힌트":"평행한 두 변의 길이와 높이를 곱하면?","식":["$\\square ABCD=\\frac{1}{2}\\times(4\\sqrt3+4)\\times4=8(\\sqrt3+1)$"],"설명":"두 밑변 AB=4, DC=4√3과 높이로 사다리꼴 넓이 공식을 적용한다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-fcbcd29efc6b":{"길":"그림의 완전제곱 과정을 식으로 옮겨 선지와 대조한다","단계":[{"제목":"그림이 나타내는 식 확인하기","힌트":"그림은 x²+6x=□ 꼴에서 무엇을 더해 완전제곱을 만들까?","식":["$x^2+6x=\\square$","$x^2+6x+9=\\square+9$","$(x+3)^2=\\square+9$"],"설명":"그림은 x²+6x 꼴에 9를 더해 (x+3)²을 만드는 과정을 나타낸다.","확인":null,"스킬":"A6"},{"제목":"선지를 같은 꼴로 바꾸기","고비":true,"힌트":"②의 식을 x² 계수가 1이 되게 양변을 나누면?","식":["$2x^2+12x=54\\ \\Rightarrow\\ x^2+6x=27$"],"설명":"②의 양변을 2로 나누면 x²+6x=27이 되어 그림과 같은 꼴(계수 6)이다.","확인":null,"스킬":"A6"},{"제목":"완전제곱식으로 확인하기","힌트":"x²+6x+9=27+9로 정리하면?","식":["$(x+3)^2=36$"],"설명":"9를 더해 정리하면 (x+3)²=36이 되어 그림을 이용해 풀 수 있다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-084d76427d4e":{"길":"처음 양을 1로 두고 퍼내고 붓는 두 변화를 식 하나로 세운다","단계":[{"제목":"조건을 식으로 세우기","힌트":"처음을 $1$ 로 두고, $x\\%$ 퍼낸 뒤 남은 양의 $x\\%$ 를 부은 결과가 처음의 $75\\%$ 라면?","식":["$\\left(1-\\frac{x}{100}\\right)+\\frac{x}{100}\\left(1-\\frac{x}{100}\\right)=\\frac{75}{100}$"],"설명":"퍼낸 뒤 남는 양은 $1-\\frac{x}{100}$ 이고, 여기에 남은 양의 $x\\%$ 를 더한 것이 $1-\\frac{25}{100}$ 이다.","확인":null,"스킬":"C7"},{"제목":"합차공식으로 정리하기","힌트":"좌변을 $\\left(1-\\frac{x}{100}\\right)$ 로 묶으면?","식":["$\\left(1-\\frac{x}{100}\\right)\\left(1+\\frac{x}{100}\\right)=\\frac{75}{100}$","$1-\\left(\\frac{x}{100}\\right)^2=\\frac{75}{100}$"],"설명":"좌변을 $1-\\frac{x}{100}$ 로 묶으면 합차공식 꼴이 된다.","확인":null,"스킬":"A1","고비":true},{"제목":"x 구하기","힌트":"$\\left(\\frac{x}{100}\\right)^2$ 의 값을 구한 뒤 $x>0$ 이면 $x$ 는?","식":["$x^2=2500$","$x=50$"],"설명":"$x>0$ 이므로 $x=50$ 이다.","확인":"50","스킬":"A2"}]},"ns-14e61c2ceebc":{"길":"중근 조건을 판별식으로 세워 y를 x의 식으로 얻고 완전제곱으로 최솟값을 구한다","단계":[{"제목":"중근 조건을 판별식으로 바꾸기","힌트":"a에 대한 이차방정식이 중근을 가지려면 어떤 식이 0이 되어야 할까?","식":["$(x-2)^2-(-3x+y)=0$"],"설명":"a²+2b'a+c'=0 꼴에서 중근 조건은 b'²-c'=0이므로 이 식이 성립해야 한다.","확인":null,"스킬":"A6"},{"제목":"y를 x의 식으로 정리하기","고비":true,"힌트":"위 식을 전개해 y에 대해 풀면?","식":["$x^2-4x+4+3x=y\\ \\Rightarrow\\ y=x^2-x+4$"],"설명":"전개해서 정리하면 y가 x에 대한 이차식으로 나온다.","확인":null,"스킬":"A3"},{"제목":"완전제곱으로 최솟값 구하기","힌트":"y=x²-x+4를 완전제곱 꼴로 바꾸면?","식":["$y=\\left(x-\\frac{1}{2}\\right)^2+\\frac{15}{4}$"],"설명":"완전제곱으로 바꾸면 최솟값은 15/4이다.","확인":"15/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-290628af0c58":{"길":"가격과 손님 수의 변화를 각각 식으로 세워 총 판매금액 조건의 이차방정식을 만든다","단계":[{"제목":"가격과 손님 수를 식으로 세우기","힌트":"가격을 x% 올리면 가격은 몇 배, 손님은 몇 배가 될까?","식":["$a\\left(1+\\frac{x}{100}\\right),\\ b\\left(1-\\frac{x}{200}\\right)$"],"설명":"가격 인상률과 손님 감소율을 각각 배수로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"총 판매금액 조건으로 방정식 세우기","고비":true,"힌트":"두 배수의 곱이 원래보다 8% 늘어난다는 조건은?","식":["$\\left(1+\\frac{x}{100}\\right)\\left(1-\\frac{x}{200}\\right)=\\frac{108}{100}$","$x^2-100x+1600=0$"],"설명":"총 판매금액이 8% 증가한다는 조건을 정리해 이차방정식을 만든다.","확인":null,"스킬":"C7"},{"제목":"인수분해로 x 구하기","힌트":"인수분해하면 x는 어떤 두 값을 가질까?","식":["$(x-20)(x-80)=0$"],"설명":"인수분해하면 x=20 또는 x=80이다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-2de572925eb8":{"길":"중앙값과 최빈값이 같다는 조건으로 처음 자료를 문자로 세운 뒤, 평균 조건으로 새 학생의 값을 구한다","단계":[{"제목":"처음 자료를 문자로 세우기","힌트":"중앙값과 최빈값이 모두 61이라면 자료를 어떻게 나열할까?","식":["$a,\\ 61,\\ 61,\\ b,\\ 66\\ (a\\ne b)$"],"설명":"중앙값과 최빈값이 모두 61이므로 자료를 a, 61, 61, b, 66으로 둘 수 있다.","확인":null,"스킬":"C7"},{"제목":"평균 조건으로 a+b 구하기","힌트":"평균이 60이라는 식을 세우면?","식":["$\\frac{a+61+61+b+66}{5}=60$","$a+b=112$"],"설명":"평균 조건을 정리하면 a+b=112이다.","확인":"112","스킬":"A10"},{"제목":"새 학생 값 x 구하기","고비":true,"힌트":"평균이 59로 바뀐 조건으로 x를 구하면?","식":["$\\frac{a+61+61+b+x}{5}=59$","$a+b+x=173$","$x=173-112=61$"],"설명":"새로운 평균 조건으로 식을 세워 x=61임을 구한다.","확인":"61","스킬":"A10"},{"제목":"중앙값과 최빈값의 합 구하기","힌트":"a, 61, 61, 61, b의 중앙값과 최빈값은?","식":["$61+61=122$"],"설명":"세 개의 61이 있으므로 중앙값과 최빈값이 모두 61이고, 그 합은 122이다.","확인":"122","스킬":"C7"}],"fb":"fig/ns/"},"ns-3f6aaaf1c77e":{"길":"근의 공식으로 해를 나타내고 판별식이 홀수인 완전제곱수가 되는 조건으로 k를 센다","단계":[{"제목":"근의 공식으로 해 나타내기","힌트":"근의 공식을 적용하면 해는?","식":["$x=\\frac{3\\pm\\sqrt{9+2k}}{2}$"],"설명":"근의 공식을 적용해 해를 나타낸다.","확인":null,"스킬":"N8"},{"제목":"조건을 만족하는 값 나열하기","고비":true,"힌트":"해가 정수이려면 9+2k는 홀수인 제곱수여야 한다","식":["$9+2k=25,49,81,121,169$"],"설명":"9+2k가 홀수인 제곱수가 되는 값을 100 이하 범위에서 나열한다.","확인":null,"스킬":"N8"},{"제목":"자연수 k 개수 세기","힌트":"각 값에서 9를 빼고 2로 나누면 k는?","식":["$k=8,20,36,56,80$"],"설명":"k값을 모두 구하면 자연수 k는 5개이다.","확인":"5","스킬":"P4"}],"fb":"fig/ns/"},"ns-458dc413a6c5":{"길":"친구 수를 x로 놓고 1인당 부담 금액 변화를 분수식으로 세워 이차방정식을 만든다","단계":[{"제목":"1인당 금액을 식으로 세우기","힌트":"친구가 x명일 때와 2명이 빠진 (x-2)명일 때 1인당 금액은?","식":["$\\frac{120000}{x},\\ \\frac{120000}{x-2}$"],"설명":"전체 금액을 인원수로 나눠 1인당 부담 금액을 각각 나타낸다.","확인":null,"스킬":"C7"},{"제목":"차액 조건으로 방정식 세우기","고비":true,"힌트":"1인당 5천 원 더 낸다는 조건을 식으로 옮기면?","식":["$\\frac{120000}{x}+5000=\\frac{120000}{x-2}$","$x^2-2x-48=0$"],"설명":"분모를 통분해 정리하면 이차방정식이 나온다.","확인":null,"스킬":"C7"},{"제목":"인수분해로 인원수 구하기","힌트":"인수분해한 두 값 중 x>0에 맞는 것은?","식":["$(x+6)(x-8)=0\\Rightarrow x=8$"],"설명":"x>0이므로 x=8만 남는다.","확인":"8","스킬":"C2"}],"fb":"fig/ns/"},"ns-47bb1ec5adf0":{"길":"두 근을 k, 2k로 놓고 근과 계수의 관계로 a+b를 k의 식으로 나타내 정수값을 테스트한다","단계":[{"제목":"두 근을 k, 2k로 놓기","힌트":"두 근의 비가 1:2이므로 두 근을 어떻게 나타낼까?","식":["$두\\ 근:\\ k,\\ 2k$"],"설명":"두 근의 비가 1:2이므로 k, 2k로 놓는다.","확인":null,"스킬":"A8"},{"제목":"근과 계수의 관계로 a+b 식 세우기","고비":true,"힌트":"근과 계수의 관계로 -a=3k, b=2k²이므로 a+b는?","식":["$a+b=2k^2-3k$"],"설명":"근과 계수의 관계를 이용해 a+b를 k에 대한 식으로 나타낸다.","확인":null,"스킬":"A2"},{"제목":"정수 k로 선택지 값 만들어보기","힌트":"k=1,2,-1,-3을 대입하면 어떤 값이 나올까?","식":["$k=1:-1,\\ k=2:2,\\ k=-1:5,\\ k=-3:27$"],"설명":"정수 k에 여러 값을 대입해 선택지 -1, 2, 5, 27이 모두 나옴을 확인한다.","확인":null,"스킬":"N4"},{"제목":"될 수 없는 값 찾기","힌트":"2k²-3k=10을 만족하는 정수 k가 있을까?","식":["$2k^2-3k-10=0$의\\ 정수해\\ 없음"],"설명":"2k²-3k=10은 정수 k로 만족되지 않으므로 10은 a+b가 될 수 없다.","확인":null,"스킬":"N4"}],"fb":"fig/ns/"},"ns-4abef50e2479":{"길":"가격 인하 횟수를 x로 놓고 수익 함수를 완전제곱으로 정리한다","단계":[{"제목":"수익 함수 세우기","힌트":"50원씩 x번 내리면 가격과 관중 수는?","식":["$y=(5000-50x)(500+10x)$"],"설명":"가격 인하 횟수 x로 수익 함수를 세운다.","확인":null,"스킬":"C7"},{"제목":"전개해 완전제곱으로 정리하기","고비":true,"힌트":"전개한 뒤 완전제곱으로 바꾸면?","식":["$y=-500x^2+25000x+2500000$","$=-500(x-25)^2+2812500$"],"설명":"완전제곱으로 정리하면 x=25일 때 수익이 최대가 된다.","확인":null,"스킬":"A6"},{"제목":"가격 구하기","힌트":"x=25를 가격식에 대입하면?","식":["$5000-50\\times25=3750$"],"설명":"x=25를 대입하면 입장권 가격은 3750원이다.","확인":"3750","스킬":"C7"}],"fb":"fig/ns/"},"ns-4fb5b24f878d":{"길":"편차를 크기순으로 나열해 a=1,2,3,4일 때 중앙값을 각각 확인해 조건을 만족하는 가장 작은 a를 찾는다","단계":[{"제목":"a=1,2일 때 확인하기","힌트":"편차를 크기순으로 나열해 중앙값을 구하면?","식":["$a=1:\\ -11,1,1,4,5\\to(중앙값)=180+1=181$","$a=2:\\ -11,0,2,4,5\\to(중앙값)=180+2=182$"],"설명":"a=1, 2일 때는 중앙값이 각각 181, 182개로 184가 되지 않는다.","확인":null,"스킬":"C2"},{"제목":"a=3일 때 확인하기","힌트":"a=3이면 편차 순서와 중앙값은?","식":["$a=3:\\ -11,-1,3,4,5\\to(중앙값)=180+3=183$"],"설명":"a=3일 때 중앙값은 183개로 아직 184가 아니다.","확인":null,"스킬":"C2"},{"제목":"a=4일 때 확인해 답 정하기","고비":true,"힌트":"a=4이면?","식":["$a=4:\\ -11,-2,4,4,5\\to(중앙값)=180+4=184$"],"설명":"a=4일 때 중앙값이 184개로 조건을 만족하므로 가장 작은 a는 4이다.","확인":"4","스킬":"C2"}],"fb":"fig/ns/"},"ns-54069c5340da":{"길":"제곱근을 풀어 정수 조건을 홀수 조건으로 바꾸고 가장 작은 값을 찾는다","단계":[{"제목":"제곱근 형태로 풀기","힌트":"양변에 제곱근을 취하면?","식":["$2x+1=\\pm\\sqrt{4k+1}$","$x=\\frac{-1\\pm\\sqrt{4k+1}}{2}$"],"설명":"양변에 제곱근을 취해 x를 √(4k+1)에 대한 식으로 나타낸다.","확인":null,"스킬":"N8"},{"제목":"정수 조건 찾기","고비":true,"힌트":"x가 정수이려면 √(4k+1)은 어떤 수여야 할까?","식":["$\\sqrt{4k+1}$이 홀수"],"설명":"2x+1은 항상 홀수이므로 √(4k+1)도 홀수여야 x가 정수가 된다.","확인":null,"스킬":"N8"},{"제목":"최솟값 k 구하기","힌트":"1보다 큰 가장 작은 홀수는?","식":["$\\sqrt{4k+1}=3$","$4k+1=9$","$k=2$"],"설명":"k가 자연수이므로 √(4k+1)이 될 수 있는 가장 작은 홀수 3을 대입해 k의 최솟값을 구한다.","확인":"2","스킬":"N8"}],"fb":"fig/ns/"},"ns-55b78b139fa6":{"길":"정팔각형과 정육각형을 각각 이등변삼각형으로 나눠 넓이를 구해 더한다","단계":[{"제목":"정팔각형을 삼각형으로 나누기","힌트":"정팔각형을 8개의 이등변삼각형으로 나누면 중심각은?","식":["$\\angle AOB=\\frac18\\times360^{\\circ}=45^{\\circ}$"],"설명":"정팔각형을 중심에서 8개의 이등변삼각형으로 나누면 한 삼각형의 중심각은 45°이다.","확인":"45","스킬":"S13"},{"제목":"정팔각형의 넓이 구하기","고비":true,"힌트":"점 A에서 OB에 내린 수선의 발을 H라 하면 AH는?","식":["$\\overline{AH}=2\\sqrt2$","$\\triangle OAB=\\frac12\\times4\\times2\\sqrt2=4\\sqrt2$","$8\\times4\\sqrt2=32\\sqrt2$"],"설명":"직각삼각형 AOH에서 AH=2√2이므로 한 삼각형의 넓이는 4√2, 정팔각형 전체 넓이는 32√2이다.","확인":null,"스킬":"S6"},{"제목":"정육각형을 삼각형으로 나누기","힌트":"정육각형을 6개의 정삼각형으로 나누면 중심각은?","식":["$\\angle AOB=\\frac16\\times360^{\\circ}=60^{\\circ}$"],"설명":"정육각형을 중심에서 나누면 6개의 정삼각형이 되고 중심각은 60°이다.","확인":"60","스킬":"S13"},{"제목":"정육각형의 한 변 구하기","힌트":"정삼각형의 높이가 반지름 3√3이면 한 변은?","식":["$\\frac{\\sqrt3}{2}\\times\\overline{OA}=3\\sqrt3$","$\\overline{OA}=6$"],"설명":"정삼각형의 높이 공식에서 한 변 OA=6이다.","확인":"6","스킬":"S6"},{"제목":"정육각형의 넓이 구하기","힌트":"정삼각형 넓이 공식으로 한 삼각형의 넓이는?","식":["$\\triangle OAB=\\frac{\\sqrt3}{4}\\times6^2=9\\sqrt3$","$6\\times9\\sqrt3=54\\sqrt3$"],"설명":"한 삼각형의 넓이는 9√3이므로 정육각형 전체 넓이는 54√3이다.","확인":null,"스킬":"S6"},{"제목":"a+b+c+d 구하기","힌트":"두 넓이의 합을 a√2+b√3 꼴로 정리하면?","식":["$32\\sqrt2+54\\sqrt3$","$a=32,\\ b=54,\\ c=d=0$","$a+b+c+d=86$"],"설명":"두 넓이의 합은 32√2+54√3이므로 a=32,b=54,c=d=0이고 a+b+c+d=86이다.","확인":"86","스킬":"A3"}],"fb":"fig/ns/"},"ns-5bd93614770c":{"길":"나머지 세 학생 기록의 편차 제곱합을 구하고 바른 기록으로 바꿔 분산을 다시 계산","단계":[{"제목":"기록된 자료의 분산식 세우기","힌트":"나머지 세 학생의 기록을 a, b, c라 하고 기록된 5개 자료의 분산식을 세우면?","식":["$\\frac{(a-30)^2+(b-30)^2+(c-30)^2+(-3)^2+6^2}{5}=12$"],"설명":"옳게 기록된 세 학생의 값을 a, b, c라 하면 기록된 자료는 a, b, c, 27, 36이다. 27, 36의 편차는 각각 -3, 6이고 이 자료의 분산이 12라는 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"편차 제곱 합만 따로 정리하기","고비":true,"힌트":"양변에 5를 곱해 정리하면?","식":["$(a-30)^2+(b-30)^2+(c-30)^2+45=60$","$(a-30)^2+(b-30)^2+(c-30)^2=15$"],"설명":"a, b, c 각각의 값을 몰라도 세 편차 제곱의 합은 15로 구할 수 있다.","확인":"15","스킬":"A2"},{"제목":"평균이 그대로임을 확인하기","힌트":"27+36과 31+32는 같을까?","식":["$27+36=31+32=63$"],"설명":"잘못 기록된 두 값의 합과 바른 두 값의 합이 같아 전체 합이 그대로이므로 평균은 변함없이 30이다.","확인":null,"스킬":"C7"},{"제목":"실제 분산·표준편차 구하기","힌트":"세 학생의 편차 제곱 합 15에 31, 32의 편차 제곱을 더하면?","식":["$\\frac{15+1+4}{5}=4$","$\\sqrt{4}=2$"],"설명":"실제 턱걸이 횟수의 분산은 4이므로 표준편차는 2이다.","확인":"2","스킬":"A2"}]},"ns-60ba70fa235e":{"길":"가로 길이의 합과 제곱합을 평균·표준편차 조건으로 구한 뒤, 넓이 평균 식에 대입한다","단계":[{"제목":"가로 길이의 합 구하기","힌트":"가로 길이 평균이 5cm라는 조건으로 합을 구하면?","식":["$\\frac{a+b+c+d+e}{5}=5$","$a+b+c+d+e=25$"],"설명":"다섯 직사각형의 가로 길이의 합은 25이다.","확인":"25","스킬":"C7"},{"제목":"제곱합 구하기","고비":true,"힌트":"표준편차 2cm 조건을 전개해 제곱합을 구하면?","식":["$a^2+b^2+c^2+d^2+e^2-10(a+b+c+d+e)+125=20$","$a^2+b^2+c^2+d^2+e^2=145$"],"설명":"분산식을 전개하고 가로 길이의 합을 대입하면 제곱합은 145이다.","확인":"145","스킬":"A2"},{"제목":"넓이의 평균 구하기","힌트":"세로 길이가 10-가로이므로 넓이의 평균은?","식":["$\\frac{-(a^2+b^2+c^2+d^2+e^2)+10(a+b+c+d+e)}{5}=\\frac{-145+250}{5}=21$"],"설명":"넓이 a(10-a) 등의 평균을 구하면 21이다.","확인":"21","스킬":"A2"}],"fb":"fig/ns/"},"ns-61aa6dda9de6":{"길":"두 쌍의 평균·분산 조건으로 각각의 제곱합을 구한 뒤, 네 수를 합쳐 전체 평균과 분산을 구한다","단계":[{"제목":"a,b의 제곱합 구하기","힌트":"a,b의 평균 6, 분산 1 조건을 전개하면?","식":["$a+b=12$","$a^2+b^2-12(a+b)+72=2$","$a^2+b^2=74$"],"설명":"a, b의 평균과 분산 조건을 정리하면 a²+b²=74이다.","확인":"74","스킬":"A2"},{"제목":"c,d의 제곱합 구하기","고비":true,"힌트":"c,d도 같은 방법으로 정리하면?","식":["$c+d=4$","$c^2+d^2-4(c+d)+8=8$","$c^2+d^2=16$"],"설명":"c, d의 평균과 분산 조건을 정리하면 c²+d²=16이다.","확인":"16","스킬":"A2"},{"제목":"네 수 전체의 평균·분산 구하기","힌트":"a+b+c+d와 a²+b²+c²+d²을 이용해 전체 분산을 구하면?","식":["$(전체평균)=\\frac{12+4}{4}=4$","$(전체분산)=\\frac{(74+16)-8(16)+64}{4}=\\frac{26}{4}$"],"설명":"전체 네 수의 평균은 4, 분산은 26/4이다.","확인":null,"스킬":"A2"},{"제목":"표준편차 구하기","힌트":"분산 26/4에 제곱근을 씌우면?","식":["$\\sqrt{\\frac{26}{4}}=\\frac{\\sqrt{26}}{2}$"],"설명":"표준편차는 √26/2이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-63f56a636d57":{"길":"가중평균 방정식으로 B의 평균을 구하고, 전체 편차제곱합에서 A의 몫을 빼 B의 분산을 구한다","단계":[{"제목":"가중평균 방정식 세우기","힌트":"두 자료를 합친 평균 3을 가중평균식으로 쓰면?","식":["$\\frac{5\\times3+4\\times m}{9}=3$"],"설명":"자료 A 5개, B 4개를 합친 평균 방정식을 세운다.","확인":null,"스킬":"A2"},{"제목":"B의 평균 구하기","힌트":"방정식을 풀면 m은?","식":["$15+4m=27$","$m=3$"],"설명":"방정식을 정리하면 자료 B의 평균은 3이다.","확인":"3","스킬":"A2"},{"제목":"전체와 A의 편차제곱합 구하기","고비":true,"힌트":"분산에 개수를 곱하면 편차제곱합이 되는데, A와 전체 각각은?","식":["$5\\times4=20$","$9\\times8=72$"],"설명":"A의 편차제곱합은 20, 전체 9개의 편차제곱합은 72이다.","확인":null,"스킬":"A2"},{"제목":"B의 편차제곱합에서 분산 구하기","힌트":"전체에서 A의 몫을 빼면 B의 편차제곱합은?","식":["$72-20=52$","$v=\\frac{52}{4}=13$"],"설명":"B의 편차제곱합 52를 개수 4로 나누면 분산은 13이다.","확인":null,"스킬":"A2"},{"제목":"평균과 분산의 차 구하기","힌트":"B의 분산 13에서 평균 3을 빼면?","식":["$13-3=10$"],"설명":"자료 B의 평균과 분산의 차는 10이다.","확인":"10","스킬":"A2"}],"fb":"fig/ns/"},"ns-6d8a37903268":{"길":"중앙값으로 b를 정하고 평균·분산 조건을 연립해 이차방정식으로 a,c를 구한다","단계":[{"제목":"중앙값으로 b 정하기","힌트":"a<b<c이고 중앙값이 8이므로 b는?","식":["$b=8$"],"설명":"가운데 오는 값이 중앙값이므로 b=8이다.","확인":null,"스킬":"C7"},{"제목":"평균 조건으로 a+c 구하기","힌트":"세 수의 평균이 9라는 식을 세우면?","식":["$\\frac{a+8+c}{3}=9\\Rightarrow a+c=19$"],"설명":"평균 방정식을 정리하면 a+c=19이다.","확인":null,"스킬":"A2"},{"제목":"분산 조건을 식으로 세우기","고비":true,"힌트":"편차 제곱의 합을 분산식으로 쓰면?","식":["$(a-9)^2+(-1)^2+(c-9)^2=26$","$(a-9)^2+(c-9)^2=25$"],"설명":"분산 조건을 정리해 a, c의 편차 제곱합 식을 얻는다.","확인":null,"스킬":"A2"},{"제목":"c를 a로 치환해 이차방정식 풀기","힌트":"c=19-a를 대입하면?","식":["$(a-9)^2+(10-a)^2=25$","$a^2-19a+78=0$","$(a-6)(a-13)=0$"],"설명":"치환해 정리하면 a=6 또는 a=13이다.","확인":null,"스킬":"N4"},{"제목":"조건에 맞는 값 정하고 답 구하기","힌트":"a<c 조건을 만족하는 값은?","식":["$a=6,\\ c=13$","$a+b-c=6+8-13=1$"],"설명":"a<c이므로 a=6, c=13이며, a+b-c=1이다.","확인":"1","스킬":"A2"}],"fb":"fig/ns/"},"ns-7335d48f848d":{"길":"변을 x로 두고 넓이비를 변의 제곱비로 바꿔 이차방정식을 풀고 범위 조건으로 근을 고른다","단계":[{"제목":"변수 설정하기","힌트":"큰 정삼각형의 변을 x라 하면 작은 정삼각형의 변은?","식":["$\\frac{15-3x}{3}=5-x$"],"설명":"큰 정삼각형의 한 변을 x라 하면 나머지 끈으로 만든 작은 정삼각형의 한 변은 5-x이다.","확인":null,"스킬":"C7"},{"제목":"넓이비를 변의 제곱비로 바꾸기","고비":true,"힌트":"닮은 정삼각형의 넓이비는 변의 비의 무엇과 같을까?","식":["$(5-x)^2:x^2=2:3$"],"설명":"정삼각형은 서로 닮음이므로 넓이비는 변의 길이비의 제곱과 같다.","확인":null,"스킬":"S1"},{"제목":"이차방정식 풀기","힌트":"비례식을 정리해 전개하면?","식":["$3(5-x)^2=2x^2$","$x^2-30x+75=0$"],"설명":"비례식을 정리해 이차방정식으로 바꾼다.","확인":null,"스킬":"A6"},{"제목":"조건에 맞는 근 고르기","힌트":"x는 0과 5 사이여야 하지 않을까?","식":["$x=15-5\\sqrt{6}\\ (\\because 0<x<5)$"],"설명":"근의 공식으로 얻은 두 근 중 0<x<5를 만족하는 값만 답이 된다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-746ff9f7cf60":{"길":"근의 공식으로 정수 조건을 배수 조건으로 바꾸고 자연수가 되는 최솟값을 찾는다","단계":[{"제목":"근의 공식으로 x 표현하기","힌트":"근의 공식을 쓰면 x는?","식":["$x=\\frac{6\\pm\\sqrt{15k}}{3}$"],"설명":"근의 공식으로 x를 √15k에 대한 식으로 나타낸다.","확인":null,"스킬":"N8"},{"제목":"정수 조건을 배수 조건으로 바꾸기","고비":true,"힌트":"x가 정수이려면 √15k는 3의 몇 배여야 할까?","식":["$\\sqrt{15k}=3a$","$15k=9a^2$","$k=\\frac{3}{5}a^2$"],"설명":"분모 3을 없애려면 √15k가 3의 배수여야 하므로 3a로 놓고 k를 a에 관한 식으로 쓴다.","확인":null,"스킬":"N4"},{"제목":"자연수 조건 맞춰 최솟값 찾기","힌트":"k가 자연수이려면 a²이 5의 배수여야 하지 않을까?","식":["$a=5$일 때 $k=\\frac{3}{5}\\times25=15$"],"설명":"k가 자연수가 되려면 a가 5의 배수여야 하므로 가장 작은 a=5를 대입하면 k의 최솟값 15를 얻는다.","확인":"15","스킬":"N1"}],"fb":"fig/ns/"},"ns-7a234b38a01d":{"길":"완전제곱식 조건을 k에 관한 이차방정식으로 보고 근과 계수의 관계로 합을 구한다","단계":[{"제목":"완전제곱식 조건 세우기","힌트":"3x²+bx+c가 완전제곱식이려면 판별식은?","식":["$(-\\sqrt{60})^2-12(k^2-4k+\\sqrt{15})=0$"],"설명":"이차식이 완전제곱식이 되려면 x에 대한 판별식이 0이어야 한다는 조건을 세운다.","확인":null,"스킬":"A6"},{"제목":"k에 관한 이차방정식으로 정리하기","고비":true,"힌트":"정리하면 k에 대한 어떤 방정식이 될까?","식":["$60-12k^2+48k-12\\sqrt{15}=0$","$12k^2-48k-60+12\\sqrt{15}=0$"],"설명":"조건식을 k에 관해 정리하면 k를 미지수로 하는 이차방정식이 된다.","확인":null,"스킬":"A3"},{"제목":"근과 계수의 관계로 합 구하기","힌트":"k값들을 직접 풀지 않고 합을 구하려면?","식":["$k_1+k_2=\\frac{-(-48)}{12}=4$"],"설명":"k에 관한 이차방정식을 직접 풀지 않고 근과 계수의 관계로 두 k값의 합을 구한다.","확인":"4","스킬":"A2"}],"fb":"fig/ns/"},"ns-7bc4e0c3ef50":{"길":"기존 제곱합을 구한 뒤 새 학생 점수를 더해 새 평균·분산을 계산한다","단계":[{"제목":"기존 다섯 명의 합 구하기","힌트":"평균 80이라는 식으로 합을 구하면?","식":["$a+b+c+d+e=400$"],"설명":"평균 방정식을 정리해 다섯 명의 점수 합을 구한다.","확인":null,"스킬":"A2"},{"제목":"기존 제곱합 구하기","고비":true,"힌트":"분산 12를 식으로 펼치면?","식":["$(a^2+b^2+c^2+d^2+e^2)-160\\times400+80^2\\times5=60$","$a^2+b^2+c^2+d^2+e^2=32060$"],"설명":"분산식을 전개해 다섯 명의 제곱합을 구한다.","확인":null,"스킬":"A2"},{"제목":"새 평균 구하기","힌트":"92점이 추가되면 여섯 명의 평균은?","식":["$\\frac{400+92}{6}=82$"],"설명":"새로 들어온 학생을 포함한 평균은 82점이다.","확인":null,"스킬":"A2"},{"제목":"새 분산 구하기","힌트":"새 제곱합을 전개해 정리하면?","식":["$\\frac{32060-65600+33720}{6}=\\frac{180}{6}=30$"],"설명":"새 분산식을 전개해 계산하면 분산은 30이다.","확인":"30","스킬":"A2"}],"fb":"fig/ns/"},"ns-844c19ee645a":{"길":"새 기호의 방정식을 풀어 약수 개수를 정한 뒤 그 조건을 만족하는 수를 30 이하에서 센다","단계":[{"제목":"새 기호의 방정식 풀기","힌트":"<x>를 t로 놓고 이차방정식을 풀면?","식":["$t^2-t-6=0$","$(t+2)(t-3)=0$","$t=3\\ (\\because t>0)$"],"설명":"<x>를 t로 놓고 이차방정식을 풀면, 약수의 개수는 자연수이므로 t=3이다.","확인":"3","스킬":"C6"},{"제목":"약수 3개인 수의 조건 찾기","고비":true,"힌트":"약수가 정확히 3개인 자연수는 어떤 꼴일까?","식":["$p^2\\ (p는\\ 소수)$"],"설명":"양의 약수가 3개인 자연수는 소수의 제곱 꼴이다.","확인":null,"스킬":"N1"},{"제목":"30이하 값 세기","힌트":"30 이하에서 소수의 제곱은?","식":["$2^2=4,\\ 3^2=9,\\ 5^2=25$"],"설명":"30 이하에서 소수의 제곱은 4, 9, 25로 3개이다.","확인":"3","스킬":"N1"}],"fb":"fig/ns/"},"ns-8b34b1103abf":{"길":"큰 삼각형 변을 x로 두고 넓이비를 이차방정식으로 세워 범위에 맞는 근을 고른다","단계":[{"제목":"두 정삼각형의 변 길이 식 세우기","힌트":"큰 삼각형에 쓴 끈이 3x라면 작은 삼각형 변은?","식":["$x,\\ \\frac{18-3x}{3}=6-x$"],"설명":"큰 정삼각형의 한 변을 x라 하면 나머지 끈으로 만든 작은 정삼각형의 한 변은 6-x이다.","확인":null,"스킬":"C7"},{"제목":"넓이비를 식으로 옮기기","고비":true,"힌트":"넓이비 1:3은 변 길이 제곱의 비와 같을까?","식":["$(6-x)^2:x^2=1:3$"],"설명":"닮은 도형의 넓이비는 변 길이 제곱의 비와 같으므로 이 비례식을 세운다.","확인":null,"스킬":"S1"},{"제목":"이차방정식으로 정리하기","힌트":"비례식을 정리하면 어떤 이차방정식이 될까?","식":["$3(6-x)^2=x^2$","$x^2-18x+54=0$"],"설명":"비례식의 내항과 외항을 곱해 정리하면 이차방정식이 된다.","확인":null,"스킬":"A6"},{"제목":"근의 공식으로 풀고 범위에 맞는 값 고르기","힌트":"0<x<6이어야 작은 변도 양수인데?","식":["$x=9\\pm3\\sqrt3$","$9+3\\sqrt3>6$이므로 제외"],"설명":"근의 공식으로 풀면 두 근이 나오는데, 작은 정삼각형의 변도 양수여야 하므로 0<x<6을 만족하는 x=9-3√3만 답이 된다.","확인":null,"스킬":"C2"}],"fb":"fig/ns/"},"ns-9039fc1c0f87":{"길":"a,b,c의 제곱합을 구한 뒤 1,2를 더한 새 자료의 평균과 분산을 계산한다","단계":[{"제목":"a+b+c 구하기","힌트":"평균 4라는 식으로 합을 구하면?","식":["$\\frac{a+b+c}{3}=4$","$a+b+c=12$"],"설명":"평균 방정식을 정리해 세 값의 합을 구한다.","확인":null,"스킬":"A2"},{"제목":"a²+b²+c² 구하기","고비":true,"힌트":"분산 2를 식으로 펼치면?","식":["$(a-4)^2+(b-4)^2+(c-4)^2=6$","$a^2+b^2+c^2-8\\times12+48=6$","$a^2+b^2+c^2=54$"],"설명":"분산식을 전개해 세 값의 제곱합을 구한다.","확인":null,"스킬":"A2"},{"제목":"새 평균 m 구하기","힌트":"1, 2를 더한 다섯 값의 평균은?","식":["$m=\\frac{3+12}{5}=3$"],"설명":"1, 2, a, b, c의 평균은 3이다.","확인":null,"스킬":"A2"},{"제목":"새 분산 S 구하고 m+S 계산하기","힌트":"새 분산식을 전개하면?","식":["$S=\\frac{5+54-6\\times12+27}{5}=\\frac{14}{5}=2.8$","$m+S=3+2.8=5.8$"],"설명":"새 분산은 2.8이고, m+S는 5.8이다.","확인":"5.8","스킬":"A2"}],"fb":"fig/ns/"},"ns-94f5a5b63250":{"길":"가격을 x로 놓아 수익을 이차식으로 세우고 완전제곱으로 최댓값을 구한다","단계":[{"제목":"수익 식 세우기","힌트":"가격 x와 판매량을 곱하면 수익 식은?","식":["$y=x\\left(200-\\frac{1}{4}x\\right)=-\\frac{1}{4}x^{2}+200x$"],"설명":"가격과 판매량을 곱해 수익을 이차식으로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"완전제곱으로 바꾸기","고비":true,"힌트":"이차식을 완전제곱 꼴로 바꾸면?","식":["$y=-\\frac{1}{4}(x-400)^{2}+40000$"],"설명":"완전제곱 꼴로 바꾸면 x=400일 때 최댓값 40000을 갖는다.","확인":null,"스킬":"A6"},{"제목":"가격과 최대 수익 답하기","힌트":"최댓값을 갖는 x와 그때의 y값은?","식":[],"설명":"상품가격 400원일 때 최대 수익 40000원을 얻는다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-98b528900bf6":{"길":"두 근을 이용해 포물선 식을 세우고 꼭짓점 조건으로 a를 구해 값을 계산한다","단계":[{"제목":"포물선 식 세우기","힌트":"땅에서 0, 30에서 떨어지므로 식은?","식":["$y=ax(x-30)$"],"설명":"x=0과 x=30에서 떨어지므로 두 근을 이용해 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"꼭짓점 형태로 바꾸기","힌트":"완전제곱으로 바꾸면 꼭짓점은?","식":["$y=a(x-15)^{2}-225a$"],"설명":"완전제곱 꼴로 바꾸면 꼭짓점의 y좌표는 -225a이다.","확인":null,"스킬":"A6"},{"제목":"a값 구하기","고비":true,"힌트":"최고 높이가 10m이므로?","식":["$-225a=10\\Rightarrow a=-\\frac{2}{45}$"],"설명":"꼭짓점의 y좌표가 최고 높이 10과 같으므로 a를 구한다.","확인":null,"스킬":"A6"},{"제목":"x=24일 때 높이 계산하기","힌트":"완성된 식에 x=24를 대입하면?","식":["$y=-\\frac{2}{45}\\times24^{2}+\\frac{4}{3}\\times24=\\frac{32}{5}$"],"설명":"식에 x=24를 대입해 높이를 구한다.","확인":"32/5","스킬":"A6"}],"fb":"fig/ns/"},"ns-98d75dbaffa2":{"길":"자연수 조건으로 크기 순서를 정하고 중앙값·최빈값 조건을 함께 맞춰 a를 구한다","단계":[{"제목":"크기 순서 정하기","힌트":"a가 자연수이면 a와 3a, a²과 a²+a, a²+2a의 크기는?","식":["$a<3a,\\quad a^2<a^2+a<a^2+2a$"],"설명":"자연수 조건으로 각 쌍의 대소가 정해진다.","확인":null,"스킬":"C2"},{"제목":"중앙값 조건으로 순서 확정하기","고비":true,"힌트":"a²이 중앙값이 되려면 전체 순서는?","식":["$a,\\ 3a,\\ a^2,\\ a^2+a,\\ a^2+2a$"],"설명":"a²이 중앙값이 되려면 이 순서로 나열되어야 한다.","확인":null,"스킬":"C2"},{"제목":"최빈값 조건으로 a 구하기","힌트":"a²이 최빈값도 되려면 어느 두 값이 같아야 할까?","식":["$3a=a^2$","$a(a-3)=0$","$a=3$"],"설명":"3a=a²을 풀면 a=3(자연수)이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-9b68e2e482e6":{"길":"잘못 본 평균으로 세운 분산식을 전개해 제곱합을 구한 뒤 실제 평균으로 다시 분산을 구한다","단계":[{"제목":"다섯 수의 합 구하기","힌트":"평균이 6이라는 식으로 합을 구하면?","식":["$\\frac{a+b+c+d+e}{5}=6$","$a+b+c+d+e=30$"],"설명":"평균 방정식을 정리해 다섯 수의 합을 구한다.","확인":null,"스킬":"A2"},{"제목":"제곱합 구하기","고비":true,"힌트":"잘못 본 평균 5로 구한 분산 4를 식으로 펼치면?","식":["$(a^2+b^2+c^2+d^2+e^2)-10\\times30+125=20$","$a^2+b^2+c^2+d^2+e^2=195$"],"설명":"분산식을 전개해 다섯 수의 제곱합을 구한다.","확인":null,"스킬":"A2"},{"제목":"원래 분산 구하기","힌트":"실제 평균 6으로 분산식을 다시 전개하면?","식":["$\\frac{195-12\\times30+180}{5}=\\frac{15}{5}=3$"],"설명":"실제 평균으로 분산을 구하면 3이다.","확인":"3","스킬":"A2"}],"fb":"fig/ns/"},"ns-9c86fee6e5d8":{"길":"두 번의 덜어내기를 남은 원액 비율 공식으로 옮겨 최종 비율 조건으로 이차방정식을 세운다","단계":[{"제목":"처음 따라낸 양을 x로 두고 두 번째 양 나타내기","힌트":"두 번째로 따라낸 양은 처음보다 4L 많다고 했으니?","식":["$x,\\ x+4$"],"설명":"처음에 따라낸 매실 원액의 양을 x L라 하면 두 번째로 따라낸 양은 x+4 L이다.","확인":null,"스킬":"C7"},{"제목":"남은 원액의 양을 비율식으로 세우기","고비":true,"힌트":"두 번 덜어낸 뒤 남는 원액은 (48-x)(44-x)/48인데, 이게 몇 L여야 할까?","식":["$\\frac{(48-x)(44-x)}{48}=30$"],"설명":"물과 원액의 비가 3:5이므로 전체 48L 중 원액은 30L이 남아야 한다. 두 번 덜어낸 뒤 남는 원액의 비율 공식에 대입한다.","확인":null,"스킬":"C7"},{"제목":"이차방정식 정리해 풀기","힌트":"양변에 48을 곱해 전개하면?","식":["$(48-x)(44-x)=1440$","$x^2-92x+672=0$","$(x-8)(x-84)=0$"],"설명":"전개해 정리하면 이차방정식이 되고 인수분해로 두 근 8, 84를 얻는다.","확인":null,"스킬":"A6"},{"제목":"범위에 맞는 값 고르기","힌트":"x는 48L보다 작아야 하는데?","식":["$0<x<48$이므로 $x=8$"],"설명":"x=84는 전체 양 48L를 넘으므로 조건에 맞지 않고, x=8만 답이 된다.","확인":"8","스킬":"C2"}],"fb":"fig/ns/"},"ns-a464da4a877a":{"길":"둘레의 합에서 반지름 평균을, 표준편차식에서 반지름 제곱합을 구해 넓이 평균을 계산한다","단계":[{"제목":"반지름의 합과 평균 구하기","힌트":"둘레의 합이 20π라는 식으로 반지름 합을 구하면?","식":["$2\\pi(r_1+\\cdots+r_5)=20\\pi$","$r_1+\\cdots+r_5=10$"],"설명":"반지름의 합은 10이고 평균은 2이다.","확인":null,"스킬":"A2"},{"제목":"분산식 세워 제곱합 구하기","고비":true,"힌트":"표준편차 √2를 분산식으로 펼치면?","식":["$(r_1-2)^2+\\cdots+(r_5-2)^2=10$","$r_1^2+\\cdots+r_5^2-4\\times10+20=10$","$r_1^2+\\cdots+r_5^2=30$"],"설명":"분산식을 전개해 반지름의 제곱합을 구한다.","확인":null,"스킬":"A2"},{"제목":"넓이의 평균 구하기","힌트":"원의 넓이는 πr²이므로 넓이의 평균은?","식":["$\\frac{\\pi\\times30}{5}=6\\pi$"],"설명":"넓이의 평균은 6π이다.","확인":null,"스킬":"A2"}],"fb":"fig/ns/"},"ns-a720f04dbf2f":{"길":"직각이등변삼각형에서 각의 이등분선 성질로 CD를 구해 tan22.5°를 구한다","단계":[{"제목":"AB 길이 나타내기","힌트":"직각이등변삼각형 ABC에서 AC=BC=a이면 AB는?","식":["$\\overline{AB}=\\sqrt2\\,a$"],"설명":"AC=BC=a인 직각이등변삼각형이므로 빗변 AB=√2a이다.","확인":null,"스킬":"S3"},{"제목":"각의 이등분선 성질로 CD 구하기","고비":true,"힌트":"AD가 각 A를 이등분하면 BD:CD는 AB:AC와 같을까?","식":["$\\overline{BD}:\\overline{CD}=\\overline{AB}:\\overline{AC}=\\sqrt2:1$","$\\overline{CD}=\\dfrac{1}{\\sqrt2+1}\\overline{BC}=(\\sqrt2-1)a$"],"설명":"각의 이등분선 성질로 BD:CD=√2:1임을 이용해 CD를 구한다.","확인":null,"스킬":"S2"},{"제목":"tan22.5° 계산하기","힌트":"직각삼각형 ADC에서 tan22.5°는?","식":["$\\tan22.5^\\circ=\\dfrac{\\overline{CD}}{\\overline{AC}}=\\dfrac{(\\sqrt2-1)a}{a}=\\sqrt2-1$"],"설명":"직각삼각형 ADC에서 tan22.5°의 정의로 값을 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-a8a2311e2647":{"길":"A의 값이 중앙값과 같음을 이용해 D, E의 편차 순서를 경우로 나눠 x의 범위를 구한다","단계":[{"제목":"A의 실제 값 구하기","힌트":"평균 120에 A의 편차 3을 더하면?","식":["$120+3=123$"],"설명":"A의 실제 기록은 123회로, 이는 문제에서 주어진 중앙값과 같다.","확인":null,"스킬":"C7"},{"제목":"경우 (ⅰ) 순서로 부등식 세우기","힌트":"B, D, A, E, C 순서라면 편차의 크기 관계는?","식":["$3-x\\le3\\le x+1$"],"설명":"D의 편차가 A보다 작거나 같고 E의 편차가 A보다 크거나 같아야 A가 가운데(중앙값)에 온다.","확인":null,"스킬":"C2"},{"제목":"경우 (ⅰ)의 범위 풀기","힌트":"두 부등식을 각각 풀면?","식":["$x\\ge0,\\ x\\ge2$"],"설명":"두 조건을 모두 만족하려면 x는 2 이상이어야 한다.","확인":null,"스킬":"C2"},{"제목":"경우 (ⅱ) 성립 여부 확인하기","힌트":"B, E, A, D, C 순서라면 성립할까?","식":["$x+1\\le3\\le3-x\\Rightarrow x\\le2,\\ x\\le0$"],"설명":"x>0 조건과 x≤0이 동시에 성립할 수 없으므로 이 경우는 불가능하다.","확인":null,"스킬":"C2","고비":true},{"제목":"가장 작은 x 값 정하기","힌트":"가능한 경우에서 x의 최솟값은?","식":["$x=2$"],"설명":"경우 (ⅰ)만 성립하므로 가장 작은 x의 값은 2이다.","확인":"2","스킬":"C7"}],"fb":"fig/ns/"},"ns-ab91fcaa70e9":{"길":"대각선으로 닮음인 직각이등변삼각형을 찾아 변을 x로 놓고 넓이를 완전제곱으로 만든다","단계":[{"제목":"대각선 반씩 나누기","힌트":"정사각형의 대각선은 서로 어떻게 나뉠까?","식":["$\\overline{OA}=\\overline{OD}=6$"],"설명":"두 대각선이 서로를 이등분하므로 반지름 같은 길이 6을 얻는다.","확인":null,"스킬":"S2"},{"제목":"닮음으로 직각이등변삼각형 찾기","힌트":"△APE와 △AOD는 어떤 관계일까?","식":[],"설명":"두 삼각형이 닮음이고 △AOD가 직각이등변삼각형이므로 △APE도 직각이등변삼각형이다.","확인":null,"스킬":"S1"},{"제목":"변의 길이를 x로 나타내기","고비":true,"힌트":"AP=PE=x로 놓으면 나머지 변은?","식":["$\\overline{ES}=6-x,\\ \\overline{EH}=12-2x,\\ \\overline{FE}=2x$"],"설명":"직사각형의 각 변을 x에 대한 식으로 나타낸다.","확인":null,"스킬":"S4"},{"제목":"넓이를 완전제곱으로 바꾸기","힌트":"직사각형의 넓이 y=(12-2x)(2x)를 정리하면?","식":["$y=-4(x-3)^{2}+36$"],"설명":"완전제곱 꼴로 바꾸면 x=3일 때 최댓값 36이다.","확인":null,"스킬":"A6"},{"제목":"둘레 계산하기","힌트":"x=3일 때 가로, 세로의 길이는?","식":["$\\overline{EF}=6,\\ \\overline{EH}=6\\Rightarrow 2(6+6)=24$"],"설명":"가로와 세로가 모두 6이므로 둘레는 24이다.","확인":"24","스킬":"N6"}],"fb":"fig/ns/"},"ns-bd7cebeb85d6":{"길":"표에서 두 거리를 더해 두 식을 세우고 연립해 a, b를 구한다","단계":[{"제목":"표에서 합 구하기","힌트":"정지거리는 공주거리+제동거리, x=20일 때와 x=40일 때는?","식":["$x=20:\\,y=6,\\quad x=40:\\,y=16$"],"설명":"표의 두 거리를 더해 정지거리를 구한다.","확인":null,"스킬":"C7"},{"제목":"두 식 세우기","힌트":"y=ax²+bx에 각각 대입하면?","식":["$200a+10b=3\\ \\cdots①$","$200a+5b=2\\ \\cdots②$"],"설명":"값을 대입해 a, b에 대한 두 방정식을 세운다.","확인":null,"스킬":"C7"},{"제목":"연립방정식 풀기","고비":true,"힌트":"①에서 ②를 빼면?","식":["$5b=1\\Rightarrow b=\\frac{1}{5}$"],"설명":"두 식을 빼서 b를 먼저 구한다.","확인":"1/5","스킬":"A10"},{"제목":"a값 구하기","힌트":"b값을 ②에 대입하면?","식":["$200a=2-1=1\\Rightarrow a=\\frac{1}{200}$"],"설명":"②에 b를 대입해 a를 구한다.","확인":"1/200","스킬":"A10"}],"fb":"fig/ns/"},"ns-c41802b7ca33":{"길":"중앙값과 최빈값이 겹치는 자료 구조를 세우고 두 쿼터의 평균 조건을 식으로 만든다","단계":[{"제목":"자료 구조 설정하기","힌트":"중앙값과 최빈값이 모두 178이면 다섯 명의 키는 어떤 모양일까?","식":["$a,\\ 178,\\ 178,\\ d,\\ x$"],"설명":"중앙값과 최빈값이 178이므로 가운데 두 값이 178이고 나머지는 a, d, x로 둘 수 있다.","확인":null,"스킬":"C7"},{"제목":"1쿼터 평균으로 식 세우기","힌트":"평균이 180이면 다섯 값의 합은?","식":["$a+178+178+d+x=900$","$a+d+x=544$"],"설명":"1쿼터 평균 180을 이용해 세 미지수의 합을 구한다.","확인":null,"스킬":"C7"},{"제목":"3쿼터 평균으로 식 세우기","힌트":"E 대신 F(178cm)가 들어가 평균이 181일 때 식은?","식":["$a+178+178+178+d=905$","$a+d=371$"],"설명":"E가 F로 바뀐 3쿼터의 평균 181을 이용해 a+d를 구한다.","확인":null,"스킬":"C7"},{"제목":"E의 키 x 구하기","힌트":"1쿼터 식에서 a+d를 빼면?","식":["$x=544-371=173$"],"설명":"두 식을 빼서 E의 키 x는 173cm임을 구한다.","확인":null,"스킬":"A10","고비":true},{"제목":"3쿼터 중앙값 y 구하고 x-y 계산하기","힌트":"3쿼터 다섯 명의 키에서 178은 몇 개인가?","식":["$a,178,178,178,d\\to y=178$","$x-y=173-178=-5$"],"설명":"3쿼터 키 중 178이 세 개로 가장 많아 중앙값도 178이므로 y=178이고, x-y는 -5이다.","확인":"-5","스킬":"C7"}],"fb":"fig/ns/"},"ns-ceb41cf8a874":{"길":"12를 두 정수의 곱으로 나누는 경우를 모두 나열해 x의 계수를 구하고 합한다","단계":[{"제목":"정수근 조건을 인수분해로 표현하기","힌트":"두 근이 정수이면 x²+kx+12를 어떻게 인수분해할 수 있을까?","식":["$x^2+kx+12=(x+p)(x+q),\\ pq=12$"],"설명":"두 근이 정수가 되려면 곱이 12인 두 정수 p, q로 인수분해되어야 한다.","확인":null,"스킬":"N4"},{"제목":"곱이 12인 정수 쌍 나열하기","고비":true,"힌트":"곱해서 12가 되는 두 자연수 쌍은 몇 가지일까?","식":["$1\\times12,\\ 2\\times6,\\ 3\\times4$"],"설명":"절댓값 기준으로 곱이 12인 자연수 쌍은 (1,12), (2,6), (3,4) 세 가지이다.","확인":null,"스킬":"N4"},{"제목":"각 쌍에서 k값 구하기","힌트":"p+q=k이므로 두 수가 모두 양수이거나 모두 음수인 경우를 나누면?","식":["$k=\\pm13,\\ \\pm8,\\ \\pm7$"],"설명":"두 정수가 모두 양수거나 모두 음수인 경우로 나누면 k=±13, ±8, ±7이다.","확인":null,"스킬":"C2"},{"제목":"값들의 합 구하기","힌트":"양수와 음수가 쌍으로 있으므로 합은?","식":["$13-13+8-8+7-7=0$"],"설명":"모든 k값이 부호쌍으로 상쇄되어 합은 0이다.","확인":"0","스킬":"N5"}],"fb":"fig/ns/"},"ns-d31d7a0be3a7":{"길":"완전제곱꼴에서 √7의 범위를 잡아 두 근 사이 자연수를 센다","단계":[{"제목":"완전제곱식 풀기","힌트":"(x+3)²=7에서 x+3=±√7이면 x는?","식":["$x=-3\\pm\\sqrt{7}$"],"설명":"양변에 제곱근을 취하면 x=-3±√7이다.","확인":null,"스킬":"N8"},{"제목":"√7의 범위 잡기","힌트":"2², 3² 사이에 7이 있다면?","식":["$2<\\sqrt{7}<3$"],"설명":"4<7<9이므로 2<√7<3이다.","확인":null,"스킬":"N8"},{"제목":"두 근의 범위로 자연수 개수 확인하기","고비":true,"힌트":"두 근이 모두 0보다 작은 범위에 있다면 자연수가 있을까?","식":["$-1<-3+\\sqrt{7}<0$","$-6<-3-\\sqrt{7}<-5$"],"설명":"두 근이 모두 음수 범위에 있으므로 그 사이에 자연수는 없다.","확인":"0","스킬":"N3"}],"fb":"fig/ns/"},"ns-d38f3bef8f8c":{"길":"근호를 정리해 일차방정식으로 만든 뒤 분모를 유리화해 해를 구한다","단계":[{"제목":"근호 정리하기","힌트":"√12, √18/√2, √12/√3을 간단히 하면?","식":["$2\\sqrt{3}x-(3x+1)=2\\sqrt{3}-2x$"],"설명":"각 항의 근호를 간단히 정리해 방정식을 다시 쓴다.","확인":null,"스킬":"N6"},{"제목":"x에 대해 정리하기","고비":true,"힌트":"x가 있는 항끼리, 상수항끼리 모으면?","식":["$(2\\sqrt{3}-1)x=2\\sqrt{3}+1$"],"설명":"x항을 좌변에, 상수항을 우변에 모아 정리한다.","확인":null,"스킬":"A3"},{"제목":"분모를 유리화해 x 구하기","힌트":"분모 2√3-1의 켤레를 곱하면?","식":["$x=\\frac{(2\\sqrt{3}+1)^2}{(2\\sqrt{3}-1)(2\\sqrt{3}+1)}=\\frac{13+4\\sqrt{3}}{11}$"],"설명":"분모, 분자에 켤레 2√3+1을 곱해 유리화하면 해를 얻는다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-d4b8998b440a":{"길":"포장 구조를 식으로 옮겨 이차방정식을 세우고 인수분해로 푼다","단계":[{"제목":"포장 구조를 식으로 나타내기","힌트":"바구니 4개, 상자 3개, 초콜릿 1개가 남았다는 것을 식으로 쓰면?","식":["$4n(3n+1)+3n+1=336$"],"설명":"바구니 4개(각 3n+1상자, 각 n개)와 남은 상자 3개, 낱개 1개를 모두 더해 336이 되는 식을 세운다.","확인":null,"스킬":"C7"},{"제목":"전개해 정리하기","고비":true,"힌트":"좌변을 전개해 이항하면?","식":["$12n^2+4n+3n+1=336$","$12n^2+7n-335=0$"],"설명":"전개하고 정리하면 이차방정식 12n²+7n-335=0을 얻는다.","확인":null,"스킬":"A3"},{"제목":"인수분해해 n 구하기","힌트":"(n-5)(12n+67)=0에서 n>0인 해는?","식":["$(n-5)(12n+67)=0$"],"설명":"인수분해하면 n=5 또는 n=-67/12인데 n>0이므로 n=5이다.","확인":"5","스킬":"N4"}],"fb":"fig/ns/"},"ns-d7315acd59de":{"길":"점 P를 문자로 두고 Q의 좌표를 구해 PQ를 완전제곱식으로 정리해 최솟값을 구한다","단계":[{"제목":"P,Q의 좌표를 문자로 나타내기","힌트":"점 P(p, p²+3)에서 y좌표가 같은 Q의 x좌표는?","식":["$P(p,\\ p^2+3)$","$p^2+3=x-1\\Rightarrow x=p^2+4$","$Q(p^2+4,\\ p^2+3)$"],"설명":"P의 x좌표를 p라 하면 Q는 직선 y=x-1 위에서 y좌표가 같은 점이므로 x좌표는 p²+4이다.","확인":null,"스킬":"A6"},{"제목":"PQ를 p에 관한 식으로 세우기","고비":true,"힌트":"PQ는 두 점의 x좌표의 차이면?","식":["$\\overline{PQ}=(p^2+4)-p=p^2-p+4$"],"설명":"PQ는 x축에 평행한 선분이므로 두 x좌표의 차와 같다.","확인":null,"스킬":"A6"},{"제목":"완전제곱으로 최솟값 구하기","힌트":"p²-p+4를 완전제곱 꼴로 바꾸면?","식":["$\\left(p-\\frac{1}{2}\\right)^2+\\frac{15}{4}$"],"설명":"완전제곱으로 정리하면 최솟값은 15/4이다.","확인":"15/4","스킬":"A6"}],"fb":"fig/ns/"},"ns-df43c0064c42":{"길":"잘못 기록된 세 명의 값을 미지수로 두고, 평균이 그대로임을 이용해 편차제곱합만 바꿔 표준편차를 구한다","단계":[{"제목":"미지수로 두고 합 구하기","힌트":"a,b,c와 39,43의 합이 평균 40×5와 같다면?","식":["$a+b+c+39+43=40\\times5=200$","$a+b+c=118$"],"설명":"잘못 기록된 세 값을 a, b, c로 두고 평균 조건에서 세 값의 합을 구한다.","확인":"118","스킬":"C7"},{"제목":"편차제곱합 구하기","힌트":"표준편차 2에서 편차제곱의 합은?","식":["$\\frac{(a-40)^2+(b-40)^2+(c-40)^2+(-1)^2+3^2}{5}=2^2$","$(a-40)^2+(b-40)^2+(c-40)^2=10$"],"설명":"분산 공식을 세워 a, b, c의 편차제곱의 합이 10임을 구한다.","확인":"10","스킬":"C7"},{"제목":"평균이 그대로임을 확인하기","고비":true,"힌트":"37+45와 39+43은 같은가?","식":["$37+45=39+43=82$"],"설명":"바뀐 두 값의 합이 같으므로 실제 평균도 40으로 그대로다.","확인":null,"스킬":"N5"},{"제목":"실제 분산과 표준편차 구하기","힌트":"바뀐 두 값의 편차제곱만 새로 더하면?","식":["$\\frac{10+(-3)^2+5^2}{5}=\\frac{10+34}{5}=8.8$","$\\sqrt{8.8}$"],"설명":"a,b,c의 편차제곱합 10은 그대로 두고 37, 45의 편차제곱만 새로 더하면 분산은 8.8, 표준편차는 √8.8이다.","확인":"8.8","스킬":"C7"}],"fb":"fig/ns/"},"ns-e3ae21d04f0a":{"길":"원가에 대한 정가·판매가 관계를 식으로 세워 (1+r)(1-r) 꼴로 정리한다","단계":[{"제목":"정가·판매가 관계식 세우기","힌트":"원가를 A라 하면 정가는? 판매가는 정가에서 다시 x% 할인이면?","식":["$A\\left(1+\\frac{x}{100}\\right)\\left(1-\\frac{x}{100}\\right)=A\\times\\frac{21}{25}$"],"설명":"원가 A에 대해 정가와 판매가의 관계를 식으로 세운다.","확인":null,"스킬":"C7"},{"제목":"곱셈공식으로 정리하기","고비":true,"힌트":"좌변을 (1+r)(1-r)=1-r² 꼴로 정리하면?","식":["$1-\\left(\\frac{x}{100}\\right)^2=\\frac{21}{25}$","$x^2=1600$"],"설명":"A를 약분하고 곱셈공식으로 정리하면 x²=1600을 얻는다.","확인":null,"스킬":"A6"},{"제목":"x 구하기","힌트":"x>0이므로 √1600은?","식":["$x=40$"],"설명":"x는 양수이므로 x=40이다.","확인":"40","스킬":"N8"}],"fb":"fig/ns/"},"ns-e403105d8945":{"길":"추가값을 x로 두고 평균과 분산 공식을 세워 x에 대한 이차방정식을 푼다","단계":[{"제목":"평균을 x로 나타내기","힌트":"1,3,5,x 네 값의 평균은?","식":["$\\frac{1+3+5+x}{4}=\\frac{9+x}{4}$"],"설명":"추가된 값을 x라 하면 네 변량의 평균은 (9+x)/4이다.","확인":null,"스킬":"C7"},{"제목":"분산 공식 세우기","고비":true,"힌트":"각 편차의 제곱을 더해 4로 나누면 분산 2와 같다는 식은?","식":["$\\frac{(1-\\frac{9+x}{4})^2+(3-\\frac{9+x}{4})^2+(5-\\frac{9+x}{4})^2+(x-\\frac{9+x}{4})^2}{4}=2$"],"설명":"분산 공식에 대입해 x에 대한 방정식을 세운다.","확인":null,"스킬":"C7"},{"제목":"방정식 정리해 풀기","힌트":"식을 정리하면 완전제곱식이 나올까?","식":["$x^2-6x+9=0$","$(x-3)^2=0$"],"설명":"정리하면 (x-3)²=0이 되어 x=3이다.","확인":"3","스킬":"A6"}],"fb":"fig/ns/"},"ns-eb9fd636ddbc":{"길":"판별식이 완전제곱수가 되는 조건으로 자연수 a를 모두 찾아 더한다","단계":[{"제목":"근의 공식으로 조건 세우기","힌트":"2x²-3x+a-4=0의 근호 안 식은?","식":["$x=\\frac{3\\pm\\sqrt{41-8a}}{4}$"],"설명":"근의 공식을 적용하면 근호 안이 41-8a이다.","확인":null,"스킬":"N8"},{"제목":"완전제곱수 조건 세우기","고비":true,"힌트":"해가 유리수이려면 41-8a는 어떤 수여야 할까?","식":["$41-8a=0,1,4,9,16,25,36,\\ldots$"],"설명":"근이 유리수가 되려면 41-8a가 0 또는 완전제곱수여야 한다.","확인":null,"스킬":"N8"},{"제목":"자연수 a가 되는 경우 걸러내기","힌트":"8a가 41,40,37,32,25,16,5 중 8로 나누어떨어지는 것은?","식":["$8a=40,\\ 32,\\ 16$"],"설명":"8로 나누어떨어지는 경우만 자연수 a가 되며 a=5, 4, 2이다.","확인":null,"스킬":"N3"},{"제목":"a값들의 합 구하기","힌트":"5+4+2는?","식":["$5+4+2=11$"],"설명":"자연수 a의 값을 모두 더하면 11이다.","확인":"11","스킬":"N5"}],"fb":"fig/ns/"},"ns-f5ec0ab7d17b":{"길":"A의 중앙값 조건으로 b를 정하고, 두 자료를 합쳐 순서대로 나열해 전체 중앙값 조건으로 a를 구한다","단계":[{"제목":"A의 중앙값으로 b 정하기","힌트":"a≥b이고 A의 중앙값이 15이면 가운데 값은?","식":["$10,14,b,a,22\\ (b\\le a)$","$b=15$"],"설명":"a≥b이므로 A를 작은 값부터 나열하면 가운데(세 번째) 값이 b이고, 이것이 중앙값 15와 같으므로 b=15이다.","확인":"15","스킬":"C2"},{"제목":"두 자료의 값 정리하기","힌트":"b=15를 대입하면 A, B는 각각 어떤 값들일까?","식":["$A:\\ 10,14,15,a,22$","$B:\\ 11,14,a,21,22$"],"설명":"b=15를 대입해 B의 b-1=14도 함께 정리한다.","확인":null,"스킬":"C7"},{"제목":"열 개를 순서대로 나열하기","고비":true,"힌트":"10개의 값을 작은 값부터 늘어놓으면 a는 어디에 놓일까?","식":["$10,11,14,14,15,a,a,21,22,22$"],"설명":"a가 15보다 크다고 보고 늘어놓으면 다섯째는 15, 여섯째는 a가 된다.","확인":null,"스킬":"C2"},{"제목":"전체 중앙값 조건으로 a 구하기","힌트":"다섯째와 여섯째 값의 평균이 16이라는 식은?","식":["$\\frac{15+a}{2}=16$","$a=17$"],"설명":"전체 중앙값 조건을 식으로 세우면 a=17이다.","확인":"17","스킬":"A3"},{"제목":"a+b 계산하기","힌트":"a=17, b=15를 더하면?","식":["$a+b=17+15=32$"],"설명":"a+b=32이다.","확인":"32","스킬":"C2"}],"fb":"fig/ns/"},"ns-f5f811ac5665":{"길":"평균이 그대로임을 확인하고, 바뀐 두 값의 편차제곱만 새로 더해 분산을 구한다","단계":[{"제목":"평균이 그대로임을 확인하기","힌트":"47+51과 53+45는 같은가?","식":["$47+51=53+45=98$"],"설명":"바뀐 두 값의 합이 같으므로 실제 평균도 50으로 그대로다.","확인":null,"스킬":"N5"},{"제목":"잘못된 자료의 편차제곱합 구하기","힌트":"분산 10에 10을 곱하면 편차제곱의 합은?","식":["$10\\times10=100$"],"설명":"분산 공식을 거꾸로 써서 잘못된 10명 자료의 편차제곱의 합이 100임을 구한다.","확인":"100","스킬":"C7"},{"제목":"바뀐 두 값의 편차제곱만 바꾸기","고비":true,"힌트":"53, 45 대신 47, 51의 편차제곱을 넣으면?","식":["$100-3^2-(-5)^2+(-3)^2+1^2$","$=100-9-25+9+1=76$"],"설명":"잘못 기록된 53, 45의 편차제곱을 빼고 실제 값 47, 51의 편차제곱을 더한다.","확인":"76","스킬":"C7"},{"제목":"실제 분산 계산하기","힌트":"편차제곱합 76을 10으로 나누면?","식":["$\\frac{76}{10}=7.6$"],"설명":"실제 분산은 7.6이다.","확인":"7.6","스킬":"C7"}],"fb":"fig/ns/"},"ns-faf5e79116d0":{"길":"소금의 양은 그대로 두고 두 번의 농도 변화를 차례로 식으로 세운다","단계":[{"제목":"첫 번째 조작 후 농도 A 구하기","힌트":"10% 소금물 100g에서 x g을 퍼내고 물 x g을 부으면 소금의 양은?","식":["$100\\times\\frac{10}{100}-x\\times\\frac{10}{100}=100\\times\\frac{A}{100}$"],"설명":"소금의 양 변화로 식을 세우면 첫 조작 후 농도 A=10-x/10이다.","확인":null,"스킬":"C7"},{"제목":"두 번째 조작 후 농도 조건 세우기","고비":true,"힌트":"농도 A인 소금물에서 다시 2x g을 퍼내고 물 2x g을 부으면 농도는 4.8%가 된다면?","식":["$100\\times\\frac{10-\\frac{x}{10}}{100}-2x\\times\\frac{10-\\frac{x}{10}}{100}=100\\times\\frac{4.8}{100}$"],"설명":"같은 방식으로 두 번째 조작 후 소금의 양을 식으로 세운다.","확인":null,"스킬":"C7"},{"제목":"정리해 이차방정식 세우기","힌트":"전개해 정리하면?","식":["$1000-30x+\\frac{1}{5}x^2=480$","$x^2-150x+2600=0$"],"설명":"전개하고 5를 곱해 정리하면 이차방정식을 얻는다.","확인":null,"스킬":"A3"},{"제목":"인수분해해 x 구하기","힌트":"(x-130)(x-20)=0에서 0<x<100인 해는?","식":["$(x-130)(x-20)=0$"],"설명":"인수분해하면 x=130 또는 x=20인데 0<x<100이므로 x=20이다.","확인":"20","스킬":"N4"}],"fb":"fig/ns/"},"ns-fdfe7c347a4c":{"길":"정가와 판매가를 원가의 배율로 세워 방정식을 완전제곱으로 정리한다","단계":[{"제목":"원가·정가·판매가 세우기","고비":true,"힌트":"정가는 원가의 몇 %이고, 판매가는 정가의 몇 % 할인일까?","식":["$a\\left(1+\\frac{x}{100}\\right)\\left(1-\\frac{x}{200}\\right)=a\\times\\frac{112.5}{100}$"],"설명":"정가는 원가에 x%의 이익을 더한 값, 판매가는 정가에서 x/2%를 할인한 값이므로 두 배율을 곱해 방정식을 세운다.","확인":null,"스킬":"C7"},{"제목":"분수 없애 전개하기","힌트":"양변에 20000을 곱하면 어떤 방정식이 될까?","식":["$(100+x)(200-x)=22500$"],"설명":"분모를 없애기 위해 양변에 20000을 곱하고 정리한다.","확인":null,"스킬":"A3"},{"제목":"완전제곱으로 정리해 풀기","힌트":"전개한 식을 이항해 정리하면?","식":["$x^2-100x+2500=0$","$(x-50)^2=0$"],"설명":"좌변이 완전제곱식이 되어 중근 x=50을 얻는다.","확인":"50","스킬":"A6"}],"fb":"fig/ns/"},"ns-016b4ae2e7cf":{"길":"직각삼각형의 세 변으로 다섯 선지의 삼각비를 각각 계산해 비교한다","단계":[{"제목":"각 선지의 삼각비 값 계산하기","고비":true,"힌트":"변의 길이 9, 12, 15를 이용해 각 비를 구하면?","식":["$\\sin A=\\frac{9}{15}=\\frac{3}{5},\\ \\cos A=\\frac{12}{15}=\\frac{4}{5},\\ \\tan A=\\frac{9}{12}=\\frac{3}{4}$","$\\tan B=\\frac{12}{9}=\\frac{4}{3},\\ \\sin B=\\frac{12}{15}=\\frac{4}{5}$"],"설명":"직각삼각형의 세 변 9, 12, 15를 이용해 각 삼각비를 구한다.","확인":null,"스킬":"S6"},{"제목":"옳은 선지 고르기","힌트":"계산한 값과 선지를 비교하면?","식":[],"설명":"①~④는 값이 다르고 ⑤ sinB=4/5만 옳다.","확인":"4/5","스킬":"S6"}],"fb":"fig/ns/"},"ns-01b8059c3be7":{"길":"호의 비로 원주각의 비를 세운 뒤 외각의 성질로 ∠x를 구한다","단계":[{"제목":"호와 원주각 비례로 ∠ACB 구하기","힌트":"AB가 원 둘레의 1/5이면 ∠ACB는?","식":["$\\angle ACB=\\frac15\\times180^{\\circ}=36^{\\circ}$"],"설명":"호의 길이는 원주각에 비례하므로 원주각으로는 180°의 1/5인 ∠ACB를 구한다.","확인":"36","스킬":"S5"},{"제목":"∠CBD 구하기","힌트":"AB:CD=1:2이면 ∠CBD는 ∠ACB의 몇 배일까?","식":["$\\angle CBD=2\\times36^{\\circ}=72^{\\circ}$"],"설명":"호의 비가 1:2이므로 대응하는 원주각도 1:2이다.","확인":"72","스킬":"S5"},{"제목":"외각 성질로 ∠x 구하기","고비":true,"힌트":"△PBC의 외각 ∠x는 두 내각의 합과 같을까?","식":["$\\angle x=36^{\\circ}+72^{\\circ}=108^{\\circ}$"],"설명":"AC와 BD의 교점 P에서 △PBC의 외각의 성질로 ∠x를 구한다.","확인":"108","스킬":"S10"}],"fb":"fig/ns/"},"ns-0277b04a32bd":{"길":"주어진 산점도의 상관관계를 읽고 같은 유형의 보기를 찾는다","단계":[{"제목":"산점도의 상관관계 읽기","힌트":"그림의 점들은 오른쪽 위로 갈수록 증가하는 모양일까?","식":[],"설명":"주어진 산점도는 x가 커질수록 y도 커지는 양의 상관관계를 보인다.","확인":null,"스킬":"G6"},{"제목":"보기와 비교해 답 찾기","고비":true,"힌트":"자동차의 속력이 빠를수록 정지거리는 어떻게 될까?","식":[],"설명":"속력이 빠를수록 정지거리도 길어지는 양의 상관관계이므로 ①이 답이다.","확인":null,"스킬":"C3"}],"fb":"fig/ns/"},"ns-04a6db696c99":{"길":"두 과목 성적의 합이 160 이상인 영역을 산점도에서 찾아 비율을 계산한다","단계":[{"제목":"조건을 만족하는 영역 찾기","힌트":"두 과목 성적의 합이 160점 이상인 점은 어디에 있을까?","식":[],"설명":"두 과목 평균이 80점 이상이려면 합이 160점 이상이어야 하고, 이에 해당하는 점은 색칠한 부분의 7명이다.","확인":null,"스킬":"G6"},{"제목":"비율 계산하기","고비":true,"힌트":"7명은 전체 20명의 몇 %일까?","식":["$\\frac{7}{20}\\times100=35\\%$"],"설명":"전체 20명 중 7명이 조건을 만족하므로 35%이다.","확인":"35","스킬":"N6"}],"fb":"fig/ns/"},"ns-056416031870":{"길":"반지름 1인 사분원에서 cos50°, tan50°를 각각 선분의 길이로 읽어 더한다","단계":[{"제목":"OB=cos50°의 값 읽기","고비":true,"힌트":"반지름이 1인 사분원에서 cos50°는 어느 선분의 길이일까?","식":["$\\cos50^\\circ=\\frac{\\overline{OB}}{\\overline{AO}}=\\overline{OB}=0.6428$"],"설명":"반지름 AO=1이므로 cos50°는 OB의 길이와 같다.","확인":"0.6428","스킬":"T5"},{"제목":"CD=tan50°의 값 읽기","힌트":"tan50°는 어느 선분의 길이일까?","식":["$\\tan50^\\circ=\\frac{\\overline{CD}}{\\overline{OD}}=\\overline{CD}=1.1918$"],"설명":"OD=1이므로 tan50°는 CD의 길이와 같다.","확인":"1.1918","스킬":"T5"},{"제목":"두 값을 더하기","힌트":"두 값을 더하면?","식":["$\\cos50^\\circ+\\tan50^\\circ=1.8346$"],"설명":"두 값을 더하면 1.8346이다.","확인":"1.8346","스킬":"T5"}],"fb":"fig/ns/"},"ns-05dbfb5ebb07":{"길":"피타고라스 정리로 AB, AD의 길이를 구해 점 P, Q의 좌표를 정하고 뺀다","단계":[{"제목":"AB, AD의 길이 구하기","힌트":"가로 1, 세로 2인 직각삼각형의 빗변은?","식":["$\\overline{AB}=\\overline{AD}=\\sqrt{1^{2}+2^{2}}=\\sqrt{5}$"],"설명":"피타고라스 정리로 두 변의 길이가 모두 √5임을 구한다.","확인":null,"스킬":"S3"},{"제목":"점 P의 좌표 구하기","힌트":"AD=AP이므로 P의 좌표는?","식":["$a=1-\\sqrt{5}$"],"설명":"A(1)에서 왼쪽으로 √5만큼 떨어진 점이 P이다.","확인":null,"스킬":"N7"},{"제목":"점 Q의 좌표 구하기","고비":true,"힌트":"AB=AQ이므로 Q의 좌표는?","식":["$b=1+\\sqrt{5}$"],"설명":"A(1)에서 오른쪽으로 √5만큼 떨어진 점이 Q이다.","확인":null,"스킬":"N7"},{"제목":"a-b 계산하기","힌트":"두 좌표를 빼면?","식":["$a-b=(1-\\sqrt{5})-(1+\\sqrt{5})=-2\\sqrt{5}$"],"설명":"a-b=-2√5이다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-0691bd9edd22":{"길":"산점도에서 학생들의 위치를 비교해 보기의 서술이 맞는지 하나씩 대조한다","단계":[{"제목":"ㄱ 판별하기","힌트":"산점도가 오른쪽 위로 퍼져 있으면 상관관계는?","식":[],"설명":"앉은키와 키 사이에는 양의 상관관계가 있으므로 ㄱ은 옳다.","확인":null,"스킬":"G6"},{"제목":"ㄴ~ㄹ 판별하기","고비":true,"힌트":"C, B, D의 위치를 비교하면 앉은키·키의 대소는 보기와 같을까?","식":[],"설명":"C는 B보다 키는 크지만 앉은키는 작고, D는 키보다 앉은키가 크며, C는 앉은키보다 키가 크므로 ㄴ,ㄷ,ㄹ은 보기 서술과 반대라 옳지 않다.","확인":null,"스킬":"G6"},{"제목":"ㅁ 판별과 개수 세기","힌트":"E가 키도 크고 앉은키도 큰 학생이 맞다면, 옳지 않은 것은 모두 몇 개일까?","식":[],"설명":"ㅁ은 옳고, 옳지 않은 것은 ㄴ,ㄷ,ㄹ로 3개이다.","확인":"3","스킬":"P4"}],"fb":"fig/ns/"},"ns-07a07618d150":{"길":"국어 성적이 영어 성적보다 높은 영역을 산점도에서 찾아 인원을 센다","단계":[{"제목":"조건을 만족하는 영역 찾기","힌트":"국어 성적이 영어 성적보다 높은 점은 대각선의 어느 쪽에 있을까?","식":[],"설명":"국어>영어인 점들은 대각선을 기준으로 색칠한 부분에 있다.","확인":null,"스킬":"G6"},{"제목":"인원 세기","고비":true,"힌트":"색칠한 부분의 점은 몇 개일까?","식":[],"설명":"해당하는 점을 세면 4명이다.","확인":"4","스킬":"P4"}],"fb":"fig/ns/"},"ns-0811788d24b3":{"길":"원에 내접하는 사각형의 대각의 합이 180°임을 이용해 ∠x, ∠y를 구해 뺀다","단계":[{"제목":"내접사각형 성질로 ∠x, ∠y 구하기","힌트":"원에 내접하는 사각형의 대각의 합은?","식":["$\\angle x=180^{\\circ}-80^{\\circ}=100^{\\circ}$","$\\angle y=180^{\\circ}-112^{\\circ}=68^{\\circ}$"],"설명":"원에 내접하는 사각형은 대각의 합이 180°이므로 ∠x와 ∠y를 각각 구한다.","확인":null,"스킬":"S5"},{"제목":"∠x-∠y 계산하기","고비":true,"힌트":"두 값을 빼면?","식":["$\\angle x-\\angle y=100^{\\circ}-68^{\\circ}=32^{\\circ}$"],"설명":"구한 두 각의 차를 계산한다.","확인":"32","스킬":"S5"}],"fb":"fig/ns/"},"ns-0a7477ca86e0":{"길":"두 변과 끼인각으로 넓이 공식을 세워 계산한다","단계":[{"제목":"두 변과 끼인각으로 넓이 공식 쓰기","힌트":"두 변의 길이와 사잇각의 sin값을 곱하면?","식":["$\\triangle ABC=\\frac{1}{2}\\times3\\times5\\times\\sin60^\\circ$"],"설명":"두 변 3, 5와 그 끼인각 60°로 넓이 공식을 쓴다.","확인":null,"스킬":"S6"},{"제목":"계산하기","고비":true,"힌트":"sin60°=√3/2를 대입하면?","식":["$=\\frac{1}{2}\\times3\\times5\\times\\frac{\\sqrt3}{2}=\\frac{15\\sqrt3}{4}$"],"설명":"값을 대입해 정리하면 넓이는 15√3/4이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-0c203fab20dd":{"길":"호의 비와 원주각의 비가 같음을 이용해 ∠x를 비례배분으로 구한다","단계":[{"제목":"호의 비로 원주각의 비 세우기","힌트":"호의 길이와 원주각은 어떤 관계일까?","식":["$\\angle ACB:\\angle BAC:\\angle ABC=4:5:3$"],"설명":"호의 길이와 그에 대한 원주각의 크기는 비례한다.","확인":null,"스킬":"S5"},{"제목":"∠x 계산하기","고비":true,"힌트":"세 각의 합 180°를 4:5:3으로 나누면?","식":["$\\angle x=180^{\\circ}\\times\\frac{5}{4+5+3}=75^{\\circ}$"],"설명":"삼각형의 내각의 합 180°를 비례배분해 ∠x=∠BAC를 구한다.","확인":"75","스킬":"S5"}],"fb":"fig/ns/"},"ns-0d3d996759b9":{"길":"접선과 현이 이루는 각으로 ∠BPA를 구하고 이등변삼각형 성질로 ∠PBA를 구한다","단계":[{"제목":"접선과 현이 이루는 각으로 ∠BPA 구하기","힌트":"접선과 현이 이루는 각은 어느 원주각과 같을까?","식":["$\\angle BPA=\\angle BAT=65^{\\circ}$"],"설명":"접선과 현이 이루는 각은 그 호에 대한 원주각과 같으므로 ∠BPA=∠BAT=65°이다.","확인":null,"스킬":"S5"},{"제목":"이등변삼각형으로 ∠BAP 구하기","힌트":"호 AB=호 PB이면 △PAB는 어떤 삼각형일까?","식":["$\\overset{\\frown}{AB}=\\overset{\\frown}{PB}\\Rightarrow\\overline{AB}=\\overline{PB}\\Rightarrow\\angle BAP=65^{\\circ}$"],"설명":"호의 길이가 같으면 현의 길이도 같으므로 △PAB는 이등변삼각형이고 두 밑각 ∠BPA, ∠BAP가 같다.","확인":null,"스킬":"S5"},{"제목":"∠PBA 계산하기","고비":true,"힌트":"삼각형의 내각의 합에서 나머지 각을 구하면?","식":["$\\angle PBA=180^{\\circ}-2\\times65^{\\circ}=50^{\\circ}$"],"설명":"삼각형의 내각의 합이 180°임을 이용해 ∠PBA를 구한다.","확인":"50","스킬":"S10"}],"fb":"fig/ns/"},"ns-0e18a1a6ee43":{"길":"각 변의 길이를 간단한 근호로 정리한 뒤 사다리꼴 넓이 공식에 대입한다","단계":[{"제목":"각 변을 간단한 근호로 정리하기","힌트":"√20, √45+√5, √18을 간단히 하면?","식":["$\\sqrt{20}=2\\sqrt{5},\\ \\sqrt{45}+\\sqrt{5}=4\\sqrt{5},\\ \\sqrt{18}=3\\sqrt{2}$"],"설명":"세 변의 길이를 각각 간단한 근호로 바꾼다.","확인":null,"스킬":"N1"},{"제목":"사다리꼴 넓이 공식에 대입하기","고비":true,"힌트":"1/2×(윗변+아랫변)×높이를 계산하면?","식":["$\\frac{1}{2}\\times(2\\sqrt{5}+4\\sqrt{5})\\times3\\sqrt{2}=\\frac{1}{2}\\times6\\sqrt{5}\\times3\\sqrt{2}$"],"설명":"공식에 대입해 계산을 준비한다.","확인":null,"스킬":"A9"},{"제목":"근호를 곱해 정리하기","힌트":"√5×√2는?","식":["$9\\sqrt{10}$"],"설명":"√5와 √2를 곱해 넓이 9√10 cm²를 얻는다.","확인":null,"스킬":"N1"}],"fb":"fig/ns/"},"ns-1005d9b70b0b":{"길":"tan62°로 눈높이 위의 높이를 구하고 눈높이를 더한다","단계":[{"제목":"눈높이 위의 높이 구하기","힌트":"tan62°를 이용하면 CB의 길이는?","식":["$\\overline{CB}=7\\tan62^\\circ=7\\times1.88=13.16$"],"설명":"직각삼각형에서 CB를 구한다.","확인":"13.16","스킬":"S6"},{"제목":"눈높이를 더해 전체 높이 구하기","고비":true,"힌트":"눈높이 1.5m를 더하면?","식":["$13.16+1.5=14.66$"],"설명":"독립문의 높이는 눈높이를 더한 14.66m이다.","확인":"14.66","스킬":"S6"}],"fb":"fig/ns/"},"ns-10b9e81c58eb":{"길":"OM=ON에서 두 현이 같음을 얻어 이등변삼각형의 밑각을 구한다","단계":[{"제목":"현의 길이 관계 알아내기","힌트":"원의 중심에서 같은 거리에 있는 두 현은 어떤 관계일까?","식":["$\\overline{OM}=\\overline{ON}\\ \\Rightarrow\\ \\overline{AB}=\\overline{AC}$"],"설명":"중심에서 거리가 같은 두 현의 길이는 같으므로 AB=AC이고, 삼각형 ABC는 이등변삼각형이다.","확인":null,"스킬":"S5"},{"제목":"밑각 계산하기","고비":true,"힌트":"이등변삼각형에서 꼭지각이 50°이면 밑각은 몇 도일까?","식":["$\\angle ACB=\\frac{1}{2}\\times(180^\\circ-50^\\circ)$"],"설명":"이등변삼각형의 두 밑각의 크기는 같으므로 나머지 각의 절반으로 구한다.","확인":"65","스킬":"S10"}],"fb":"fig/ns/"},"ns-10d1f6d17d63":{"길":"수선을 내려 AH를 구하고 직각삼각형 ABH에서 AB를 구한다","단계":[{"제목":"수선을 내려 AH 구하기","힌트":"A에서 BC에 내린 수선의 발을 H라 하면 AH는?","식":["$\\overline{AH}=5\\sin45^\\circ=\\frac{5\\sqrt2}{2}$"],"설명":"직각삼각형 ACH에서 AH를 구한다.","확인":null,"스킬":"S2"},{"제목":"AB의 길이 구하기","고비":true,"힌트":"직각삼각형 ABH에서 AB는?","식":["$\\overline{AB}=\\frac{5\\sqrt2}{2}\\times\\frac{1}{\\sin60^\\circ}=\\frac{5\\sqrt2}{2}\\times\\frac{2}{\\sqrt3}$"],"설명":"직각삼각형 ABH에서 AB=AH÷sin60°이다.","확인":null,"스킬":"S6"},{"제목":"정리하기","힌트":"분모를 유리화하면?","식":["$=\\frac{5\\sqrt6}{3}$"],"설명":"유리화해 정리하면 AB=5√6/3이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-112f79bb583f":{"길":"두 변과 끼인각으로 넓이 공식을 세워 계산한다","단계":[{"제목":"넓이 공식 쓰기","힌트":"두 변과 사잇각으로 넓이를 쓰면?","식":["$\\square ABCD=\\frac{1}{2}\\times9\\times12\\times\\sin60^\\circ$"],"설명":"두 변 9, 12와 그 사잇각 60°로 넓이 공식을 쓴다.","확인":null,"스킬":"S6"},{"제목":"계산하기","고비":true,"힌트":"sin60°=√3/2를 대입하면?","식":["$=\\frac{1}{2}\\times9\\times12\\times\\frac{\\sqrt3}{2}=27\\sqrt3$"],"설명":"값을 대입해 정리하면 넓이는 27√3이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-1131b3c15fa3":{"길":"주어진 각 관계식에 값을 대입해 x를 구한다","단계":[{"제목":"각 사이의 관계식 세우기","힌트":"∠APB=100°일 때 x는 어떤 식으로 나타날까?","식":["$\\angle x=360^\\circ-2\\angle APB$"],"설명":"그림의 각 관계에 의해 x는 360°에서 ∠APB의 두 배를 뺀 값이다.","확인":null,"스킬":"S13"},{"제목":"값을 대입해 계산하기","고비":true,"힌트":"∠APB=100°를 대입하면?","식":["$\\angle x=360^\\circ-2\\times100^\\circ$"],"설명":"수를 대입해 계산하면 x=160°이다.","확인":"160","스킬":"S13"}],"fb":"fig/ns/"},"ns-12a37b088536":{"길":"x절편으로 인수분해 꼴을 세우고 y절편을 대입해 계수를 구한다","단계":[{"제목":"인수분해 꼴 세우기","힌트":"x절편이 -4, 1이면 y=a(x+4)(x-1)로 쓸 수 있다. 남은 조건은?","식":["$y=a(x+4)(x-1)$"],"설명":"x축과 -4, 1에서 만나므로 이 꼴로 놓고 y절편 조건을 대입한다.","확인":null,"스킬":"A3"},{"제목":"a 값 구하기","고비":true,"힌트":"(0,4)를 지나므로 a는?","식":["$4=-4a\\ \\Rightarrow\\ a=-1$"],"설명":"x=0, y=4를 대입해 a=-1을 얻는다.","확인":null,"스킬":"A3"},{"제목":"전개해 a-b+c 계산하기","힌트":"y=-(x+4)(x-1)을 전개하면 b, c는?","식":["$y=-x^2-3x+4$","$a-b+c=-1-(-3)+4=6$"],"설명":"전개해 a=-1, b=-3, c=4를 얻고 계산하면 6이다.","확인":"6","스킬":"A3"}],"fb":"fig/ns/"},"ns-1414fbdfc331":{"길":"다섯 선지를 원의 성질과 하나씩 비교해 중심을 찾는 방법인지 판단한다","단계":[{"제목":"중심을 찾는 성질 확인하기","힌트":"두 현을 그었을 때 그 수직이등분선이 만나는 점은 무엇일까?","식":[],"설명":"원에서 현의 수직이등분선은 그 원의 중심을 지나므로, 두 현의 수직이등분선의 교점이 원의 중심이 된다.","확인":null,"스킬":"S5"},{"제목":"다른 선지와 구별하기","고비":true,"힌트":"나머지 선지들은 길이나 거리의 비교일 뿐, 중심을 직접 작도해 주는가?","식":[],"설명":"나머지 성질들은 이미 중심을 안다는 전제에서 쓰이는 성질이라 중심을 새로 찾는 방법은 아니므로 답은 ①이다.","확인":null,"스킬":"S5"}],"fb":"fig/ns/"},"ns-15f9621d1827":{"길":"꼭짓점으로 p, q를 정하고 지나는 점을 대입해 a를 구해 곱한다","단계":[{"제목":"꼭짓점으로 p, q 정하기","힌트":"그래프의 꼭짓점 좌표가 (4,5)이면 p, q는?","식":["$p=4,\\ q=5$"],"설명":"꼭짓점의 좌표가 그대로 p, q 값이 된다.","확인":null,"스킬":"A6"},{"제목":"지나는 점을 대입해 a 구하기","고비":true,"힌트":"그래프가 (0,-5)를 지나므로 a는?","식":["$-5=16a+5\\ \\Rightarrow\\ a=-\\frac{5}{8}$"],"설명":"x=0, y=-5를 대입해 a를 구한다.","확인":null,"스킬":"A6"},{"제목":"apq 계산하기","힌트":"a, p, q를 모두 곱하면?","식":["$apq=-\\frac{5}{8}\\times4\\times5=-\\frac{25}{2}$"],"설명":"세 값을 곱하면 -25/2이다.","확인":"-25/2","스킬":"N6"}],"fb":"fig/ns/"},"ns-166a7ba07a9b":{"길":"45°에서 기울기를 구하고 점 (-3,0)을 대입해 b를 구한 뒤 더한다","단계":[{"제목":"기울기 a 구하기","힌트":"x축과 이루는 각이 45°이면 기울기는?","식":["$a=\\tan45^\\circ=1$"],"설명":"직선이 x축의 양의 방향과 45°를 이루므로 기울기는 tan45°=1이다.","확인":"1","스킬":"S6"},{"제목":"b 구하고 a+b 계산하기","고비":true,"힌트":"점 (-3,0)을 대입하면?","식":["$0=-3+b\\ \\Rightarrow\\ b=3$","$a+b=1+3=4$"],"설명":"직선이 점 (-3,0)을 지나므로 b=3이고 a+b=4이다.","확인":"4","스킬":"C7"}],"fb":"fig/ns/"},"ns-16e24a5031cc":{"길":"작은 원까지의 거리를 반지름으로 놓고 피타고라스 정리로 AB를 구한다","단계":[{"제목":"수선의 발 H와 OH 길이 확인하기","힌트":"작은 원에 접하는 직선까지 중심 O에서의 거리는 얼마일까?","식":["$\\overline{OH}=3$"],"설명":"직선이 작은 원에 접하므로 중심에서 직선까지 거리는 작은 원의 반지름 3과 같다.","확인":null,"스킬":"S13"},{"제목":"AH 구하고 AB로 확장하기","고비":true,"힌트":"직각삼각형 OAH에서 피타고라스 정리를 쓰면?","식":["$\\overline{AH}=\\sqrt{4^2-3^2}=\\sqrt{7},\\ \\overline{AB}=2\\overline{AH}$"],"설명":"큰 원의 반지름 OA=4이므로 AH=√7이고, H가 AB의 중점이므로 AB=2√7이다.","확인":null,"스킬":"S3"}],"fb":"fig/ns/"},"ns-175830ce7bd6":{"길":"다섯 그림을 마주보는 각의 합과 선분의 곱 성질로 하나씩 판별한다","단계":[{"제목":"① 판별하기","힌트":"네 점이 한 원 위에 있으려면 마주보는 각의 합이 얼마여야 할까?","식":["$\\angle BAD+\\angle BCD\\ne180^\\circ$"],"설명":"두 각의 합이 180°가 아니므로 네 점은 한 원 위에 있지 않다.","확인":null,"스킬":"S15"},{"제목":"② 판별하기","힌트":"두 현이 만날 때 곱이 같으면 네 점이 한 원 위에 있다는 성질은?","식":["$\\overline{PA}\\times\\overline{PD}\\ne\\overline{PB}\\times\\overline{PC}$"],"설명":"할선의 곱이 같지 않으므로 한 원 위에 있지 않다.","확인":null,"스킬":"S15"},{"제목":"③ 판별하기","힌트":"③도 같은 방법으로 곱을 비교하면?","식":["$\\overline{PA}\\times\\overline{PC}\\ne\\overline{PB}\\times\\overline{PD}$"],"설명":"곱이 다르므로 한 원 위에 있지 않다.","확인":null,"스킬":"S15"},{"제목":"④ 판별하기","힌트":"④는 마주보는 각의 합을 다시 확인하면?","식":["$\\angle ABC+\\angle ADC\\ne180^\\circ$"],"설명":"합이 180°가 아니므로 한 원 위에 있지 않다.","확인":null,"스킬":"S15"},{"제목":"⑤ 판별하고 결론 내리기","고비":true,"힌트":"⑤에서 남은 각을 계산해 같은 호에 대한 원주각과 비교하면?","식":["$\\angle ADB=180^\\circ-(32^\\circ+78^\\circ)=70^\\circ$"],"설명":"∠ADB=∠ACB=70°로 같은 호 AB에 대한 원주각이 같으므로 네 점은 한 원 위에 있다. 따라서 답은 ⑤이다.","확인":null,"스킬":"S15"}],"fb":"fig/ns/"},"ns-19a0a8f55827":{"길":"지름의 원주각 90°와 접선-현 각을 삼각형의 외각 관계로 이어 x를 구한다","단계":[{"제목":"지름에 대한 원주각 확인하기","힌트":"AC가 지름이면 ∠ABC는 몇 도일까?","식":["$\\angle ABC=90^\\circ$"],"설명":"지름에 대한 원주각은 90°이므로 ∠ABC=90°이다.","확인":null,"스킬":"S5"},{"제목":"접선과 현이 이루는 각 찾기","힌트":"∠ABP와 ∠ACB는 어떤 관계일까?","식":["$\\angle ABP=\\angle ACB=24^\\circ$"],"설명":"접선과 현이 이루는 각은 그 호에 대한 원주각과 같으므로 ∠ABP=24°이다.","확인":null,"스킬":"S5"},{"제목":"삼각형 CPB에서 ∠APT 구하기","고비":true,"힌트":"삼각형 CPB의 각 관계를 정리하면 ∠APT는?","식":["$\\angle APT=180^\\circ-(24^\\circ+90^\\circ)+24^\\circ$"],"설명":"내각과 외각 관계를 정리하면 ∠APT=42°이다.","확인":"42","스킬":"S10"}],"fb":"fig/ns/"},"ns-1c39ac442c02":{"길":"수선의 발로 반현을 구해 피타고라스 정리를 쓰고, 같은 현 조건으로 x를 확정한다","단계":[{"제목":"AE 길이 구하기","힌트":"O에서 AB에 내린 수선은 AB를 어떻게 나눌까?","식":["$\\overline{AE}=\\frac{1}{2}\\overline{AB}=8$"],"설명":"수선은 현을 이등분하므로 AE=8이다.","확인":null,"스킬":"S2"},{"제목":"OE 구하기","힌트":"직각삼각형 OAE에서 피타고라스 정리를 쓰면?","식":["$\\overline{OE}=\\sqrt{10^2-8^2}=6$"],"설명":"반지름 OA=10이므로 피타고라스 정리로 OE=6을 얻는다.","확인":null,"스킬":"S3"},{"제목":"x 값 확정하기","고비":true,"힌트":"AB=CD이면 두 현까지 중심에서의 거리는 어떤 관계일까?","식":["$x=\\overline{OE}=6$"],"설명":"길이가 같은 두 현은 중심으로부터 같은 거리에 있으므로 x=OE=6이다.","확인":"6","스킬":"S5"}],"fb":"fig/ns/"},"ns-1ce236928c5f":{"길":"반지름을 문자로 두고 피타고라스 정리로 방정식을 세워 넓이를 구한다","단계":[{"제목":"반지름 관계식 세우기","힌트":"OA=OD=r이라 하면 OB는 어떻게 나타낼까?","식":["$\\overline{OB}=r-4$"],"설명":"OD가 반지름이고 BD=4이므로 OB=r-4이다.","확인":null,"스킬":"C7"},{"제목":"피타고라스 정리로 방정식 세우기","고비":true,"힌트":"직각삼각형 OAB에서 피타고라스 정리를 쓰면?","식":["$r^2=8^2+(r-4)^2$"],"설명":"OA=r, AB=8, OB=r-4를 대입해 방정식을 세운다.","확인":null,"스킬":"S3"},{"제목":"방정식 풀어 r 구하기","힌트":"전개해 r에 대해 정리하면?","식":["$8r=80\\ \\Rightarrow\\ r=10$"],"설명":"식을 전개하고 정리하면 반지름 r=10이다.","확인":"10","스킬":"A3"},{"제목":"원의 넓이 구하기","힌트":"반지름 10인 원의 넓이는?","식":["$\\pi\\times10^2=100\\pi$"],"설명":"넓이 공식에 대입하면 100π이다.","확인":null,"스킬":"S13"}],"fb":"fig/ns/"},"ns-1fe72ccdb785":{"길":"산책로 폭을 x로 놓고 잔디밭 넓이 조건으로 이차방정식을 세워 푼다","단계":[{"제목":"산책로 폭 문자로 놓기","힌트":"산책로를 제외한 잔디밭의 가로, 세로는 각각 얼마일까?","식":["$(18-x)(16-x)=195$"],"설명":"산책로의 폭을 x로 놓고 잔디밭의 넓이 조건을 식으로 세운다.","확인":null,"스킬":"C7"},{"제목":"이차방정식 풀기","고비":true,"힌트":"전개해 정리하면 어떤 두 값이 나올까?","식":["$x^2-34x+93=0$","$(x-3)(x-31)=0$"],"설명":"전개하여 인수분해하면 x=3 또는 x=31이 나온다.","확인":null,"스킬":"C7"},{"제목":"조건에 맞는 값 고르기","힌트":"세로 16-x가 양수여야 한다는 조건에 맞는 값은?","식":["$16-x>0\\Rightarrow x<16$","$\\therefore x=3$"],"설명":"x=31은 세로 길이보다 커서 조건에 맞지 않으므로 x=3만 남는다.","확인":"3","스킬":"C2"}],"fb":"fig/ns/"},"ns-21b49b317650":{"길":"꼭짓점 형태로 식을 세우고 지나는 점을 대입해 a를 구한 뒤 전개한다","단계":[{"제목":"꼭짓점 형태로 식 세우기","힌트":"꼭짓점이 (3,4)이면 y=a(x-3)²+4로 쓸 수 있다. 남은 조건은?","식":["$y=a(x-3)^2+4$"],"설명":"꼭짓점의 좌표를 이용해 식을 세우고, 지나는 다른 점을 대입할 준비를 한다.","확인":null,"스킬":"A6"},{"제목":"지나는 점 대입해 a 구하기","고비":true,"힌트":"(0,-5)를 지나므로 a는?","식":["$-5=9a+4\\ \\Rightarrow\\ a=-1$"],"설명":"x=0, y=-5를 대입해 a=-1을 얻는다.","확인":null,"스킬":"A6"},{"제목":"전개해 a+b+c 계산하기","힌트":"y=-(x-3)²+4를 전개하면 b, c는?","식":["$y=-x^2+6x-5$","$a+b+c=-1+6+(-5)=0$"],"설명":"전개해 a=-1, b=6, c=-5를 얻고 더하면 0이다.","확인":"0","스킬":"A3"}],"fb":"fig/ns/"},"ns-240ae615bed6":{"길":"내접원의 접선 길이를 문자로 놓고 AC 길이로 방정식을 세워 BP를 구한다","단계":[{"제목":"접선 길이를 문자로 놓기","힌트":"내접원의 접선 길이는 각 꼭짓점에서 어떻게 같을까?","식":["$\\overline{BP}=\\overline{BQ}=x,\\ \\overline{AP}=\\overline{AR}=12-x,\\ \\overline{CQ}=\\overline{CR}=14-x$"],"설명":"한 점에서 그은 두 접선의 길이는 같으므로 각 변을 x로 나타낸다.","확인":null,"스킬":"S5"},{"제목":"AC 길이로 방정식 풀기","고비":true,"힌트":"AR+CR=AC임을 이용하면?","식":["$(12-x)+(14-x)=10$"],"설명":"AC=10을 이용해 방정식을 세워 풀면 x=8이다.","확인":"8","스킬":"C7"}],"fb":"fig/ns/"},"ns-26b784b947f5":{"길":"접은 점의 성질로 OM을 구하고 피타고라스 정리로 AB를 구한다","단계":[{"제목":"접은 점에서 OM 구하기","힌트":"원 위의 한 점이 중심 O에 겹치도록 접으면 접힌 선까지 거리는 반지름의 얼마일까?","식":["$\\overline{OM}=\\frac{1}{2}\\overline{OC}=3$"],"설명":"종이를 접어 원 위의 점이 중심 O에 겹치므로, 접힌 선까지 중심에서의 거리는 반지름의 절반인 3이다.","확인":null,"스킬":"S13"},{"제목":"AM 구하기","고비":true,"힌트":"직각삼각형 OAM에서 피타고라스 정리를 쓰면?","식":["$\\overline{AM}=\\sqrt{6^2-3^2}=3\\sqrt{3}$"],"설명":"반지름 OA=6, OM=3이므로 피타고라스 정리로 AM을 구한다.","확인":null,"스킬":"S3"},{"제목":"AB 길이 구하기","힌트":"M이 AB의 중점이면 AB는?","식":["$\\overline{AB}=2\\overline{AM}=6\\sqrt{3}$"],"설명":"수선의 발 M은 AB를 이등분하므로 AB=6√3이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-270ac0e645e5":{"길":"x절편·y절편·꼭짓점을 구해 사다리꼴에서 두 삼각형을 빼 넓이를 구한다","단계":[{"제목":"x절편, y절편 구하기","힌트":"y=0, x=0을 각각 대입하면 A, B는?","식":["$x^2-2x-3=0\\ \\Rightarrow\\ x=3,-1$","$y(0)=-6$"],"설명":"x절편에서 A(3,0), y절편에서 B(0,-6)을 얻는다.","확인":null,"스킬":"A6"},{"제목":"꼭짓점 C와 보조점 H 구하기","힌트":"완전제곱으로 꼭짓점을 구하고, C에서 y축에 내린 수선의 발은?","식":["$y=2(x-1)^2-8\\ \\Rightarrow\\ C(1,-8)$","$H(0,-8)$"],"설명":"꼭짓점 C(1,-8)를 구하고, y축 위의 대응점 H(0,-8)을 잡는다.","확인":null,"스킬":"A6"},{"제목":"사다리꼴에서 두 삼각형을 빼기","고비":true,"힌트":"사다리꼴 OHCA에서 삼각형 OAB, BCH를 빼면?","식":["$\\triangle ABC=\\frac{1}{2}(3+1)\\times8-\\frac{1}{2}\\times3\\times6-\\frac{1}{2}\\times1\\times2$"],"설명":"사다리꼴 OHCA의 넓이에서 두 삼각형의 넓이를 뺀다.","확인":null,"스킬":"S12"},{"제목":"계산해 넓이 구하기","힌트":"16-9-1을 계산하면?","식":["$16-9-1=6$"],"설명":"삼각형 ABC의 넓이는 6이다.","확인":"6","스킬":"N6"}],"fb":"fig/ns/"},"ns-28e791f7f679":{"길":"할선정리로 방정식을 세우고 풀어 OC를 구한다","단계":[{"제목":"PB 길이 구하기","힌트":"AB=6, AP=9이면 PB는?","식":["$\\overline{PB}=\\overline{PA}+\\overline{AB}=15$"],"설명":"P, A, B가 한 직선 위에 있으므로 PB=PA+AB=15이다.","확인":null,"스킬":"C7"},{"제목":"할선정리로 방정식 세우기","고비":true,"힌트":"OP의 연장선이 원과 만나는 점 D를 잡으면 PA×PB는 무엇과 같을까?","식":["$\\overline{PA}\\times\\overline{PB}=\\overline{PC}\\times\\overline{PD}$"],"설명":"한 점에서 그은 두 할선의 곱은 서로 같으므로 9×15=(12-x)(12+x)이다.","확인":null,"스킬":"S13"},{"제목":"방정식 풀어 x 구하기","힌트":"135=144-x²을 정리하면?","식":["$135=144-x^2\\ \\Rightarrow\\ x^2=9$"],"설명":"정리하면 x²=9이고 x>0이므로 x=3이다.","확인":"3","스킬":"A3"}],"fb":"fig/ns/"},"ns-29cf1ed4c8b6":{"길":"같은 호에 대한 원주각이 같음을 이용해 삼각형의 외각으로 x를 구한다","단계":[{"제목":"호가 같으면 원주각도 같음을 이용하기","힌트":"호AB=호DC이면 어떤 원주각들이 같을까?","식":["$\\angle ACB=\\angle DBC=43^\\circ$"],"설명":"길이가 같은 호에 대한 원주각은 같으므로 ∠ACB=43°이다.","확인":null,"스킬":"S5"},{"제목":"외각으로 x 구하기","고비":true,"힌트":"삼각형 PBC의 외각 x는 두 내각의 합과 같다","식":["$\\angle x=43^\\circ+43^\\circ=86^\\circ$"],"설명":"삼각형의 외각은 이웃하지 않는 두 내각의 합과 같으므로 x=86°이다.","확인":"86","스킬":"S10"}],"fb":"fig/ns/"},"ns-2c3058aadef2":{"길":"△CDE와 △ABC가 닮음임을 이용해 x°를 옮기고 cos 값을 구한다","단계":[{"제목":"∠BAC=∠EDC=x°임을 확인하기","힌트":"△ABC와 △DEC에서 각 x는 어떻게 대응할까?","식":["$\\angle BAC=\\angle EDC=x^{\\circ}$"],"설명":"두 직각삼각형이 각 C를 공유해 서로 닮음이므로 ∠BAC와 ∠EDC는 같은 x°이다.","확인":null,"스킬":"S1"},{"제목":"△CDE에서 DE 구하기","고비":true,"힌트":"직각삼각형 CDE에서 피타고라스 정리로 DE는?","식":["$\\overline{DE}=\\sqrt{6^2-4^2}=2\\sqrt5$"],"설명":"DC=6, CE=4인 직각삼각형에서 피타고라스 정리로 DE를 구한다.","확인":null,"스킬":"S3"},{"제목":"cos x 값 구하기","힌트":"cos x=DE/DC는?","식":["$\\cos x^{\\circ}=\\dfrac{\\overline{DE}}{\\overline{CD}}=\\dfrac{2\\sqrt5}{6}=\\dfrac{\\sqrt5}{3}$"],"설명":"직각삼각형 CDE에서 각 x에 대한 cos 값을 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-2dc6f46727c1":{"길":"두 원의 중심에서 수선을 내려 직각삼각형을 만들고 피타고라스로 이차방정식을 세워 푼다","단계":[{"제목":"원 O의 반지름 구하기","힌트":"AB=8이 원 O의 지름이라면 반지름은?","식":["$\\frac{1}{2}\\times8=4$"],"설명":"원 O는 직사각형의 세로변에 내접하므로 반지름은 4이다.","확인":null,"스킬":"S2"},{"제목":"직각삼각형 OHO' 세우기","고비":true,"힌트":"원 O'의 반지름을 r라 하고 OH, OO', HO'를 r로 나타내면?","식":["$\\overline{OH}=4-r,\\ \\overline{OO'}=4+r,\\ \\overline{HO'}=9-(4+r)=5-r$"],"설명":"두 원의 중심에서 수선을 내려 직각삼각형 OHO'를 만들고 세 변을 r로 나타낸다.","확인":null,"스킬":"S2"},{"제목":"피타고라스 정리로 방정식 세우기","힌트":"직각삼각형이므로 세 변 사이의 관계식은?","식":["$(4+r)^2=(4-r)^2+(5-r)^2$","$r^2-26r+25=0$"],"설명":"피타고라스 정리를 적용해 정리하면 r에 대한 이차방정식이 나온다.","확인":null,"스킬":"S3"},{"제목":"r 값 구하기","힌트":"인수분해하면 r은?","식":["$(r-1)(r-25)=0$"],"설명":"0<r<4 조건에서 r=1만 가능하다.","확인":"1","스킬":"S3"},{"제목":"둘레의 합 구하기","힌트":"두 원의 둘레를 더하면?","식":["$2\\pi\\times4+2\\pi\\times1=10\\pi$"],"설명":"두 반지름으로 둘레의 합을 계산하면 10π(cm)이다.","확인":null,"스킬":"S2"}],"fb":"fig/ns/"},"ns-2e66604e646c":{"길":"산점도에서 조건에 맞는 점의 개수를 직접 세어 다섯 선지를 확인한다","단계":[{"제목":"①,② 판별하기","힌트":"50점 이하 영역의 점 개수와 상관관계의 부호는?","식":[],"설명":"국어, 영어 모두 50점 이하인 학생은 색칠한 영역에서 6명이므로 ①은 옳지 않다. 국어와 영어 성적 사이에는 양의 상관관계가 있으므로 ②도 옳지 않다.","확인":null,"스킬":"C3"},{"제목":"③,④ 판별하기","고비":true,"힌트":"대각선 위쪽과 대각선 위에 있는 점을 세면?","식":[],"설명":"영어 성적이 국어 성적보다 높은 학생은 5명이므로 ③은 옳고, 국어와 영어 성적이 같은 학생(대각선 위)은 4명이므로 ④도 옳다.","확인":null,"스킬":"C3"},{"제목":"⑤ 판별하기","힌트":"국어 성적이 50점인 학생 4명의 영어 성적 평균은?","식":["$\\frac{30+40+50+60}{4}=45$"],"설명":"국어 성적이 50점인 학생 4명의 영어 성적 평균은 45점이므로 ⑤도 옳다.","확인":"45","스킬":"P4"}],"fb":"fig/ns/"},"ns-2f8ddf7f745e":{"길":"수선의 발과 반지름으로 만든 직각삼각형에서 피타고라스로 반현을 구해 2배 한다","단계":[{"제목":"직각삼각형 AOH에서 AH 구하기","힌트":"원의 중심에서 수선을 내리면 직각삼각형이 되는데, AH는?","식":["$\\overline{AH}=\\sqrt{5^2-4^2}=3$"],"설명":"피타고라스 정리로 AH의 길이를 구한다.","확인":null,"스킬":"S3"},{"제목":"x 값 구하기","고비":true,"힌트":"현은 수선의 발에서 이등분되므로 x=AB는?","식":["$x=\\overline{AB}=2\\overline{AH}=6$"],"설명":"현 AB는 AH의 2배이므로 x=6이다.","확인":"6","스킬":"S2"}],"fb":"fig/ns/"},"ns-2ff8e7477bdf":{"길":"조건에 맞는 점의 개수를 세어 전체에 대한 비율을 구한다","단계":[{"제목":"조건에 맞는 점 세기","힌트":"1차, 2차 점수 모두 8점 이하인 점은 몇 개일까?","식":["$(6,6),(7,7),(7,8),(8,8)$"],"설명":"두 점수 모두 8점 이하인 학생을 나타내는 점은 4개이다.","확인":"4","스킬":"P4"},{"제목":"비율 계산하기","고비":true,"힌트":"4명을 전체 10명으로 나누면?","식":["$\\frac{4}{10}\\times100=40$"],"설명":"전체의 40%이다.","확인":"40","스킬":"P4"}],"fb":"fig/ns/"},"ns-2fff97efa517":{"길":"C에서 AB에 수선을 내려 두 직각삼각형으로 나누어 AB를 구한다","단계":[{"제목":"C에서 AB에 수선의 발 H 내리기","힌트":"△BCH에서 BH, CH를 구하면?","식":["$\\overline{BH}=4\\cos45^{\\circ}=2\\sqrt2,\\ \\overline{CH}=4\\sin45^{\\circ}=2\\sqrt2$"],"설명":"C에서 AB에 내린 수선의 발 H로 직각삼각형 BCH를 만들어 BH, CH를 구한다.","확인":null,"스킬":"S2"},{"제목":"∠ACH의 크기 구하기","고비":true,"힌트":"∠ACB=105°에서 ∠BCH를 빼면 ∠ACH는?","식":["$\\angle ACH=105^{\\circ}-45^{\\circ}=60^{\\circ}$"],"설명":"△BCH가 직각이등변삼각형이므로 ∠BCH=45°이고, 여기서 ∠ACH=60°를 얻는다.","확인":"60","스킬":"S10"},{"제목":"△ACH에서 AH 구하기","힌트":"AH=CH×tan60°는?","식":["$\\overline{AH}=2\\sqrt2\\tan60^{\\circ}=2\\sqrt6$"],"설명":"직각삼각형 ACH에서 CH와 각 60°로 AH를 구한다.","확인":null,"스킬":"S6"},{"제목":"AB의 길이 구하기","힌트":"BH와 AH를 더하면 AB는?","식":["$\\overline{AB}=\\overline{BH}+\\overline{AH}=2\\sqrt2+2\\sqrt6$"],"설명":"BH와 AH를 더해 AB의 길이를 구한다.","확인":null,"스킬":"S12"}],"fb":"fig/ns/"},"ns-306ff507e7eb":{"길":"완전제곱으로 꼭짓점을 구하고 y절편을 확인해 그래프를 고른다","단계":[{"제목":"완전제곱으로 꼭짓점 구하기","힌트":"y=(1/2)x²-2x+3을 완전제곱 꼴로 바꾸면?","식":["$y=\\frac{1}{2}(x-2)^2+1$"],"설명":"꼭짓점은 (2,1)로 제1사분면 위에 있고 아래로 볼록하다.","확인":null,"스킬":"A6"},{"제목":"y절편 확인하고 답 정하기","고비":true,"힌트":"x=0일 때 y값은?","식":["$y=3$"],"설명":"y축과의 교점은 (0,3)이며, 이 조건을 모두 만족하는 그래프는 ③이다.","확인":null,"스킬":"A6"}],"fb":"fig/ns/"},"ns-3250f6fbb56f":{"길":"피타고라스 정리로 남은 변을 구하고 cos A의 정의에 대입한다","단계":[{"제목":"피타고라스 정리로 AC 구하기","힌트":"직각삼각형에서 AC=√(3²-2²)는?","식":["$\\overline{AC}=\\sqrt{3^2-2^2}=\\sqrt5$"],"설명":"빗변과 한 변의 길이로 피타고라스 정리를 이용해 AC를 구한다.","확인":null,"스킬":"S3"},{"제목":"cos A 값 구하기","고비":true,"힌트":"cos A=AC/AB는?","식":["$\\cos A=\\dfrac{\\overline{AC}}{\\overline{AB}}=\\dfrac{\\sqrt5}{3}$"],"설명":"인접변 AC를 빗변 AB로 나누어 cos A를 구한다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-3376685ec19f":{"길":"사각형의 내각의 합으로 중심각을 구하고 우각의 원주각으로 답을 구한다","단계":[{"제목":"사각형 APBO의 각 합으로 ∠AOB 구하기","힌트":"접선은 반지름과 수직이므로 ∠PAO=∠PBO=90°, 사각형의 내각의 합은?","식":["$\\angle AOB=360^\\circ-(30^\\circ+90^\\circ+90^\\circ)=150^\\circ$"],"설명":"접선과 반지름이 이루는 두 직각과 ∠APB를 이용해 사각형의 내각의 합에서 ∠AOB를 구한다.","확인":null,"스킬":"S2"},{"제목":"큰 쪽 호에 대한 중심각 구하기","고비":true,"힌트":"점 C가 있는 쪽 호에 대한 중심각은 360°에서 방금 구한 각을 빼면?","식":["$360^\\circ-150^\\circ=210^\\circ$"],"설명":"점 C를 포함하는 우각(優角) 쪽 호에 대한 중심각은 210°이다.","확인":null,"스킬":"S5"},{"제목":"원주각으로 ∠ACB 구하기","힌트":"원주각은 중심각의 절반이므로?","식":["$\\angle ACB=\\frac{1}{2}\\times210^\\circ=105^\\circ$"],"설명":"원주각은 중심각의 절반이므로 ∠ACB=105°이다.","확인":"105","스킬":"S5"}],"fb":"fig/ns/"},"ns-34cbde8b90f7":{"길":"그래프에서 꼭짓점과 다른 한 점을 읽어 이차함수식에 대입해 a를 구한다","단계":[{"제목":"꼭짓점 좌표 읽기","힌트":"그래프의 꼭짓점은 어디인가?","식":["$p=3,\\ q=4$"],"설명":"그래프에서 꼭짓점이 (3,4)이므로 p=3, q=4이다.","확인":null,"스킬":"A6"},{"제목":"다른 한 점 대입해 a 구하기","고비":true,"힌트":"그래프가 지나는 점 (0,-5)를 대입하면?","식":["$-5=a\\times(-3)^2+4$","$9a=-9$","$a=-1$"],"설명":"그래프가 점 (0,-5)를 지나므로 대입해 a=-1을 얻는다.","확인":null,"스킬":"A6"},{"제목":"a+p+q 계산하기","힌트":"세 값을 더하면?","식":["$a+p+q=-1+3+4=6$"],"설명":"세 값을 더하면 6이다.","확인":"6","스킬":"A6"}],"fb":"fig/ns/"},"ns-35e50e18a92e":{"길":"면의 대각선과 공간대각선을 구해 직각삼각형 DFH의 세 삼각비를 계산한다","단계":[{"제목":"면의 대각선 FH 구하기","힌트":"직육면체 밑면에서 FH=√(4²+3²)는?","식":["$\\overline{FH}=\\sqrt{4^2+3^2}=5$"],"설명":"직사각형 FGH의 대각선 FH를 피타고라스 정리로 구한다.","확인":null,"스킬":"S3"},{"제목":"공간대각선 DF 구하기","힌트":"직육면체의 대각선 DF=√(4²+3²+5²)는?","식":["$\\overline{DF}=\\sqrt{4^2+3^2+5^2}=5\\sqrt2$"],"설명":"직육면체의 세 모서리 길이로 공간대각선 DF를 구한다.","확인":null,"스킬":"S11"},{"제목":"직각삼각형 DFH에서 세 삼각비 구하기","고비":true,"힌트":"cos x, sin x, tan x를 DF, FH, DH로 나타내면?","식":["$\\cos x^{\\circ}=\\dfrac{\\overline{FH}}{\\overline{DF}}=\\dfrac{\\sqrt2}{2},\\ \\sin x^{\\circ}=\\dfrac{\\overline{DH}}{\\overline{DF}}=\\dfrac{\\sqrt2}{2},\\ \\tan x^{\\circ}=\\dfrac{\\overline{DH}}{\\overline{FH}}=1$"],"설명":"직각삼각형 DFH에서 세 변 DF, FH, DH로 세 삼각비를 각각 구한다.","확인":null,"스킬":"S6"},{"제목":"식의 값 계산하기","힌트":"cos x+sin x-tan x를 계산하면?","식":["$\\cos x^{\\circ}+\\sin x^{\\circ}-\\tan x^{\\circ}=\\sqrt2-1$"],"설명":"구한 세 값을 더하고 빼서 최종 값을 구한다.","확인":null,"스킬":"A3"}],"fb":"fig/ns/"},"ns-3b07eb6cda6f":{"길":"성의 높이를 x로 놓고 두 직각삼각형의 밑변 차가 10임을 이용해 방정식을 세운다","단계":[{"제목":"높이를 x로 놓고 각 구하기","힌트":"AH=x라 하면 △ABH, △ACH의 밑각은?","식":["$\\angle BAH=180^{\\circ}-(30^{\\circ}+90^{\\circ})=60^{\\circ}$","$\\angle CAH=180^{\\circ}-(45^{\\circ}+90^{\\circ})=45^{\\circ}$"],"설명":"성의 높이를 AH=x로 놓고 두 직각삼각형의 밑각을 구한다.","확인":null,"스킬":"C7"},{"제목":"BH, CH를 x로 나타내기","힌트":"BH=x tan60°, CH=x tan45°는?","식":["$\\overline{BH}=x\\tan60^{\\circ}=\\sqrt3x$","$\\overline{CH}=x\\tan45^{\\circ}=x$"],"설명":"각 삼각형에서 x에 대한 밑변의 길이를 나타낸다.","확인":null,"스킬":"S6"},{"제목":"BC=10으로 방정식 세워 x 구하기","고비":true,"힌트":"BH-CH=10이라는 조건을 식으로 세우면?","식":["$\\sqrt3x-x=10$","$x=\\dfrac{10}{\\sqrt3-1}=5(\\sqrt3+1)$"],"설명":"BH에서 CH를 뺀 값이 BC=10이라는 조건으로 방정식을 세워 x를 구한다.","확인":null,"스킬":"C7"}],"fb":"fig/ns/"},"ns-3b67d0615c94":{"길":"직육면체와 원기둥의 부피가 같다는 식을 세워 근호를 정리해 x를 구한다","단계":[{"제목":"부피가 같다는 식 세우기","힌트":"직육면체 부피와 원기둥 부피를 각각 쓰면?","식":["$2\\sqrt2\\times\\sqrt6\\times x=\\pi\\times2^2\\times\\sqrt{15}$"],"설명":"직육면체의 부피와 원기둥의 부피가 같다는 조건으로 식을 세운다.","확인":null,"스킬":"N1"},{"제목":"근호를 정리해 좌변 간단히 하기","고비":true,"힌트":"2√2×√6을 하나의 근호로 합치면?","식":["$2\\sqrt2\\times\\sqrt6=2\\sqrt{12}=4\\sqrt3$"],"설명":"좌변의 근호를 합쳐 정리하면 4√3 x=4√15π이다.","확인":null,"스킬":"N6"},{"제목":"x의 값 구하기","힌트":"양변을 4√3으로 나누면?","식":["$x=\\frac{4\\sqrt{15}\\pi}{4\\sqrt3}=\\sqrt5\\pi$"],"설명":"양변을 4√3으로 나누고 근호를 정리하면 x=√5π(cm)이다.","확인":null,"스킬":"N6"}],"fb":"fig/ns/"},"ns-3b9e91c12343":{"길":"내접사각형의 외각 성질로 미지수를 옮기고 두 삼각형의 외각 정리로 방정식을 세운다","단계":[{"제목":"미지수 정하고 외각 성질 쓰기","힌트":"∠B=x라 하면 사각형이 원에 내접할 때 외각 ∠CDF는?","식":["$\\angle B=x\\Rightarrow\\angle CDF=x$"],"설명":"원에 내접하는 사각형의 외각은 그와 마주보는 내각과 같으므로 ∠CDF=x이다.","확인":null,"스킬":"S5"},{"제목":"삼각형 BCE의 외각으로 ∠DCF 구하기","고비":true,"힌트":"△BCE에서 ∠DCF는 어떤 외각일까?","식":["$\\angle DCF=x+44^\\circ$"],"설명":"△BCE의 외각 정리에 의해 ∠DCF=∠B+∠E=x+44°이다.","확인":null,"스킬":"S10"},{"제목":"△CDF에서 방정식 세우기","힌트":"삼각형의 내각의 합은 180°이므로?","식":["$(x+44^\\circ)+x+42^\\circ=180^\\circ$"],"설명":"△CDF의 세 내각의 합이 180°임을 이용해 방정식을 세운다.","확인":null,"스킬":"C7"},{"제목":"x 값 구하기","힌트":"방정식을 풀면 x는?","식":["$2x=94^\\circ\\Rightarrow x=47^\\circ$"],"설명":"방정식을 풀면 ∠B=47°이다.","확인":"47","스킬":"C7"}],"fb":"fig/ns/"},"ns-3d31973695ee":{"길":"같은 호의 원주각을 x로 두고 두 삼각형의 외각 정리를 이어 방정식을 세운다","단계":[{"제목":"같은 호의 원주각 표시하기","힌트":"호 BC에 대한 원주각 ∠BAC와 ∠BDC는?","식":["$\\angle BAC=\\angle BDC=x$"],"설명":"호 BC에 대한 원주각이므로 ∠BAC=∠BDC이다. 이를 x라 하자.","확인":null,"스킬":"S5"},{"제목":"△AQC의 외각으로 ∠ACD 구하기","고비":true,"힌트":"△AQC에서 ∠ACD는 외각이므로?","식":["$\\angle ACD=30^\\circ+x$"],"설명":"△AQC의 외각 정리에 의해 ∠ACD=∠Q+∠A=30°+x이다.","확인":null,"스킬":"S10"},{"제목":"△CPD에서 방정식 세우기","힌트":"∠APD가 △CPD의 두 내각의 합과 같음을 이용하면?","식":["$(30^\\circ+x)+x=78^\\circ$"],"설명":"∠APD는 △CPD의 외각이므로 두 내각의 합과 같다는 관계로 방정식을 세운다.","확인":null,"스킬":"S10"},{"제목":"x 값 구하기","힌트":"방정식을 풀면?","식":["$2x=48^\\circ\\Rightarrow x=24^\\circ$"],"설명":"방정식을 풀면 ∠BDC=24°이다.","확인":"24","스킬":"C7"}],"fb":"fig/ns/"},"ns-3e51099b1e51":{"길":"접선 길이가 같다는 성질로 변을 x로 두고, 직각이 만드는 정사각형으로 나머지 접선 길이를 정해 넓이를 더한다","단계":[{"제목":"접선의 길이 성질로 변수 두기","힌트":"원에 외접하는 삼각형에서 접점까지 거리는 같으므로 BQ=BP=x라 하면 AP, AR은?","식":["$\\overline{BQ}=\\overline{BP}=x,\\ \\overline{AP}=\\overline{AR}=6-x$"],"설명":"접선의 길이가 같은 성질을 이용해 BQ=BP=x, AP=AR=6-x로 둔다.","확인":null,"스킬":"S8"},{"제목":"∠C=90°로 CQ=CR=1 확인하기","고비":true,"힌트":"∠C=90°이고 OQ⊥CA, OR⊥CB이면 사각형 OQCR은 어떤 모양일까?","식":["$\\overline{CQ}=\\overline{CR}=\\overline{OQ}=1$"],"설명":"∠C=90°이므로 사각형 OQCR은 정사각형이 되어 CQ=CR=반지름=1이다.","확인":null,"스킬":"S2"},{"제목":"BC, CA 나타내기","힌트":"BC=BQ+QC, CA=CR+RA를 x로 쓰면?","식":["$\\overline{BC}=x+1,\\ \\overline{CA}=1+(6-x)=7-x$"],"설명":"각 변을 접점까지의 두 선분의 합으로 나타낸다.","확인":null,"스킬":"C7"},{"제목":"세 삼각형으로 넓이 더하기","힌트":"내접원의 중심 O를 꼭짓점으로 하는 세 삼각형으로 나누면?","식":["$\\triangle ABC=\\frac12\\times1\\times(x+1)+\\frac12\\times1\\times(7-x)+\\frac12\\times6\\times1=\\frac12\\times14=7$"],"설명":"내접원의 중심 O를 이용해 세 삼각형으로 나눠 더하면 x가 소거되어 넓이는 7이다.","확인":"7","스킬":"S8"}],"fb":"fig/ns/"},"ns-3edac337f1fd":{"길":"삼각형의 내각의 합으로 ∠y를 구하고 내접사각형의 대각 성질로 ∠x를 구해 차를 낸다","단계":[{"제목":"△ABD에서 ∠y 구하기","힌트":"삼각형의 내각의 합을 이용하면 ∠y는?","식":["$\\angle y=180^\\circ-60^\\circ-70^\\circ=50^\\circ$"],"설명":"△ABD의 세 내각의 합이 180°임을 이용해 ∠y를 구한다.","확인":"50","스킬":"C7"},{"제목":"내접사각형 성질로 ∠x 구하기","고비":true,"힌트":"원에 내접하는 사각형의 대각의 합은?","식":["$\\angle x=180^\\circ-\\angle y=180^\\circ-50^\\circ=130^\\circ$"],"설명":"원에 내접하는 사각형은 대각의 합이 180°이므로 ∠x를 구한다.","확인":null,"스킬":"S5"},{"제목":"차 계산하기","힌트":"∠x-∠y는?","식":["$130^\\circ-50^\\circ=80^\\circ$"],"설명":"두 각의 차를 계산하면 80°이다.","확인":"80","스킬":"C7"}],"fb":"fig/ns/"},"ns-40792413e5f7":{"길":"조건에 맞는 점을 세어 전체에 대한 비율을 구한다","단계":[{"제목":"조건에 맞는 점 세기","힌트":"두 성적의 차가 20점 이상인 점은 몇 개일까?","식":[],"설명":"수학 성적과 전 과목 평균 성적의 차가 20점 이상인 학생은 색칠한 영역에서 3명이다.","확인":"3","스킬":"P4"},{"제목":"비율 계산하기","고비":true,"힌트":"3명을 전체 10명으로 나누면?","식":["$\\frac{3}{10}\\times100=30$"],"설명":"전체의 30%이다.","확인":"30","스킬":"P4"}],"fb":"fig/ns/"},"ns-42a4c092e3e9":{"길":"꼭짓점 B에서 AC에 수선을 내려 두 직각삼각형으로 나눠 삼각비를 두 번 적용한다","단계":[{"제목":"수선 내려 BH 구하기","힌트":"△BCH에서 6×sin45°는?","식":["$\\overline{BH}=6\\sin45^{\\circ}=3\\sqrt2$"],"설명":"꼭짓점 B에서 AC에 내린 수선의 발을 H라 하면 직각삼각형 BCH에서 BH=6sin45°=3√2이다.","확인":null,"스킬":"S2"},{"제목":"∠BAH 구하기","힌트":"삼각형의 세 각의 합에서 나머지 각은?","식":["$\\angle BAH=180^{\\circ}-(75^{\\circ}+45^{\\circ})=60^{\\circ}$"],"설명":"삼각형 ABC의 세 내각의 합이 180°이므로 ∠BAH=∠BAC=60°이다.","확인":null,"스킬":"S10"},{"제목":"AB 구하기","고비":true,"힌트":"직각삼각형 ABH에서 BH를 sin60°로 나누면?","식":["$\\overline{AB}=\\frac{3\\sqrt2}{\\sin60^{\\circ}}=3\\sqrt2\\times\\frac{2}{\\sqrt3}=2\\sqrt6$"],"설명":"직각삼각형 ABH에서 AB=BH÷sin60°=2√6이다.","확인":null,"스킬":"S6"}],"fb":"fig/ns/"},"ns-43276e18d370":{"길":"보조선을 그어 합동으로 각을 구하고, 삼각비로 길이를 구한 뒤 정삼각형임을 알아챈다","단계":[{"제목":"보조선 긋고 합동 찾기","힌트":"PO를 그으면 어떤 두 삼각형이 합동일까?","식":["$\\triangle APO \\equiv \\triangle BPO$"],"설명":"PO를 그으면 RHS합동으로 △APO≡△BPO이므로 ∠APO=∠BPO=30°이다.","확인":null,"스킬":"S2"},{"제목":"PA의 길이 구하기","힌트":"직각삼각형 APO에서 tan30°를 이용하면?","식":["$\\overline{PA}=\\frac{\\sqrt{3}}{\\tan 30^{\\circ}}=3$"],"설명":"직각삼각형 APO에서 tan30°를 써서 PA=3(cm)를 구한다.","확인":null,"스킬":"S6"},{"제목":"정삼각형임을 알아채기","고비":true,"힌트":"PA=PB이고 끼인각이 60°이면 어떤 삼각형일까?","식":[],"설명":"PA=PB이고 ∠APB=60°이므로 △APB는 정삼각형이다.","확인":null,"스킬":"S6"},{"제목":"AB 길이 확정하기","힌트":"정삼각형이므로 AB는?","식":["$\\overline{AB}=\\overline{PA}=3$"],"설명":"정삼각형이므로 AB=PA=3(cm)이다.","확인":"3","스킬":"S6"}],"fb":"fig/ns/"},"ns-059776fd4428":{"길":"모눈의 가로, 세로 칸 수로 $\\overline{\\mathrm{AB}}$ 를 구하고 점 $\\mathrm{B}$ 에서 그 길이만큼 오른쪽으로 옮긴다","단계":[{"제목":"정사각형 한 변의 길이","힌트":"$\\overline{\\mathrm{AB}}$ 를 빗변으로 하는 직각삼각형의 가로, 세로는 각각 몇 칸인가?","식":["가로 $1$ 칸, 세로 $3$ 칸","$\\overline{\\mathrm{AB}}=\\sqrt{1^{2}+3^{2}}=\\sqrt{10}$"],"설명":"모눈 한 칸의 길이가 $1$ 이므로 피타고라스 정리를 쓴다.","확인":null,"스킬":"S3","고비":true},{"제목":"점 E 에 대응하는 수","힌트":"$\\overline{\\mathrm{BE}}=\\overline{\\mathrm{AB}}$ 이고 점 $\\mathrm{E}$ 가 점 $\\mathrm{B}$ 의 오른쪽에 있을 때 $\\mathrm{E}$ 에 대응하는 수는?","식":["점 $\\mathrm{B}$ 에 대응하는 수는 $2$","$\\overline{\\mathrm{BE}}=\\sqrt{10}$ 이므로 점 $\\mathrm{E}$ 에 대응하는 수는 $2+\\sqrt{10}$"],"설명":"점 $\\mathrm{E}$ 는 점 $\\mathrm{B}$ 에서 오른쪽으로 $\\sqrt{10}$ 만큼 떨어진 곳에 있다.","확인":null,"스킬":"S3"}]},"ns-0a1635fed159":{"길":"겉넓이를 $a$ 에 대한 식으로 세운 뒤 분모의 유리화로 $a$ 를 구한다","단계":[{"제목":"겉넓이의 식 세우기","힌트":"겉넓이를 이루는 서로 다른 세 면의 넓이는 각각 얼마인가?","식":["세 면의 넓이: $\\sqrt{3}a$, $\\sqrt{2}a$, $\\sqrt{3}\\times\\sqrt{2}=\\sqrt{6}$","겉넓이 $=2(\\sqrt{3}a+\\sqrt{2}a+\\sqrt{6})$"],"설명":"마주 보는 면은 합동이므로 세 쌍의 넓이를 더해 $2$ 배 한다.","확인":null,"스킬":"C7"},{"제목":"$a$ 에 대한 식으로 정리","힌트":"$2(\\sqrt{3}a+\\sqrt{2}a+\\sqrt{6})=6\\sqrt{6}+10$ 에서 $a$ 가 든 항만 왼쪽에 두면?","식":["$\\sqrt{3}a+\\sqrt{2}a+\\sqrt{6}=3\\sqrt{6}+5$","$(\\sqrt{3}+\\sqrt{2})a=2\\sqrt{6}+5$"],"설명":"양변을 $2$ 로 나눈 뒤 $\\sqrt{6}$ 을 우변으로 옮긴다.","확인":null,"스킬":"C7"},{"제목":"분모의 유리화","힌트":"$\\frac{2\\sqrt{6}+5}{\\sqrt{3}+\\sqrt{2}}$ 의 분모를 유리화하려면 분자와 분모에 무엇을 곱하는가?","식":["분모: $(\\sqrt{3}+\\sqrt{2})(\\sqrt{3}-\\sqrt{2})=3-2=1$","분자: $(2\\sqrt{6}+5)(\\sqrt{3}-\\sqrt{2})=6\\sqrt{2}-4\\sqrt{3}+5\\sqrt{3}-5\\sqrt{2}$","$a=\\sqrt{2}+\\sqrt{3}$"],"설명":"합과 차의 곱 공식으로 분모가 $1$ 이 되므로 분자가 그대로 $a$ 의 값이다.","확인":null,"스킬":"A5","고비":true}]},"ns-0d73766ddaf3":{"길":"부등식의 각 변을 제곱해 $ab$ 의 값을 정하고 가능한 눈의 쌍을 빠짐없이 찾는다","단계":[{"제목":"제곱하여 $ab$ 의 값 정하기","힌트":"$2<\\sqrt{2ab}<3$ 의 각 변을 제곱하면?","식":["$4<2ab<9$","$2<ab<\\frac{9}{2}$","$ab$ 는 자연수이므로 $ab=3$ 또는 $ab=4$"],"설명":"각 변이 양수이므로 제곱해도 부등호의 방향은 바뀌지 않는다.","확인":null,"스킬":"C7"},{"제목":"곱이 $3$ 또는 $4$ 인 눈의 쌍","힌트":"곱이 $3$ 또는 $4$ 가 되는 두 주사위의 눈 $(a,\\ b)$ 를 빠짐없이 나열하면?","식":["$ab=3$: $(1,\\ 3)$, $(3,\\ 1)$","$ab=4$: $(1,\\ 4)$, $(4,\\ 1)$, $(2,\\ 2)$"],"설명":"주사위의 눈은 $1$ 이상 $6$ 이하이므로 $a$ 와 $b$ 를 서로 바꾼 쌍도 모두 센다.","확인":null,"스킬":"P4","고비":true},{"제목":"$a+b$ 의 최댓값","힌트":"각 쌍의 $a+b$ 중 가장 큰 값은?","식":["$1+3=4$, $1+4=5$, $2+2=4$","최댓값은 $5$"],"설명":"쌍마다 합을 구해 가장 큰 값을 고른다.","확인":"5","스킬":"P4"}]},"ns-13a6cb750cad":{"길":"세 정사각형의 한 변으로 $\\overline{\\mathrm{OK}}$ 를 구하고 닮은 삼각형으로 $\\overline{\\mathrm{EB}}$, $\\overline{\\mathrm{HI}}$ 를 구한다","단계":[{"제목":"세 정사각형의 한 변","힌트":"넓이가 $\\frac{1}{4}$ 인 정사각형 $\\mathrm{GIKJ}$ 의 한 변의 길이는?","식":["$\\mathrm{S}_{1}=1$ 이므로 $\\overline{\\mathrm{OB}}=\\overline{\\mathrm{OA}}=1$","$\\mathrm{S}_{2}=\\frac{1}{2}$ 이므로 $\\overline{\\mathrm{BI}}=\\frac{\\sqrt{2}}{2}$","$\\mathrm{S}_{3}=\\frac{1}{4}$ 이므로 $\\overline{\\mathrm{IK}}=\\frac{1}{2}$"],"설명":"정사각형의 한 변의 길이는 넓이의 양의 제곱근이다.","확인":"1/2","스킬":"S1"},{"제목":"$\\overline{\\mathrm{OK}}$ 와 $\\overline{\\mathrm{BK}}$ 의 길이","힌트":"$\\overline{\\mathrm{OK}}$ 를 세 정사각형의 한 변으로 나타내면?","식":["$\\overline{\\mathrm{OK}}=\\overline{\\mathrm{OB}}+\\overline{\\mathrm{BI}}+\\overline{\\mathrm{IK}}=1+\\frac{\\sqrt{2}}{2}+\\frac{1}{2}=\\frac{3+\\sqrt{2}}{2}$","$\\overline{\\mathrm{BK}}=\\overline{\\mathrm{OK}}-\\overline{\\mathrm{OB}}=\\frac{1+\\sqrt{2}}{2}$"],"설명":"세 정사각형이 $x$ 축 위에 차례로 이어 붙어 있다.","확인":null,"스킬":"S1"},{"제목":"$\\overline{\\mathrm{EB}}$ 의 길이","힌트":"$\\triangle\\mathrm{AOK}$ 와 닮은 삼각형은 어느 것인가?","식":["$\\overline{\\mathrm{AO}}\\parallel\\overline{\\mathrm{EB}}$ 이므로 $\\triangle\\mathrm{AOK}\\sim\\triangle\\mathrm{EBK}$","$\\overline{\\mathrm{EB}}:\\overline{\\mathrm{AO}}=\\overline{\\mathrm{BK}}:\\overline{\\mathrm{OK}}$","$\\overline{\\mathrm{EB}}=\\frac{\\frac{1+\\sqrt{2}}{2}}{\\frac{3+\\sqrt{2}}{2}}=\\frac{1+\\sqrt{2}}{3+\\sqrt{2}}$"],"설명":"$\\angle\\mathrm{K}$ 가 공통이고 $\\angle\\mathrm{AOK}=\\angle\\mathrm{EBK}=90^{\\circ}$ 이므로 두 삼각형은 닮음이다.","확인":null,"스킬":"S1","고비":true},{"제목":"$\\overline{\\mathrm{HI}}$ 의 길이","힌트":"$\\triangle\\mathrm{AOK}\\sim\\triangle\\mathrm{HIK}$ 일 때 $\\overline{\\mathrm{HI}}:\\overline{\\mathrm{AO}}$ 와 같은 비는?","식":["$\\overline{\\mathrm{HI}}:\\overline{\\mathrm{AO}}=\\overline{\\mathrm{IK}}:\\overline{\\mathrm{OK}}$","$\\overline{\\mathrm{HI}}=\\frac{\\frac{1}{2}}{\\frac{3+\\sqrt{2}}{2}}=\\frac{1}{3+\\sqrt{2}}$"],"설명":"$\\overline{\\mathrm{HI}}\\parallel\\overline{\\mathrm{AO}}$ 이므로 같은 방법으로 닮음을 쓴다.","확인":null,"스킬":"S1"},{"제목":"두 길이의 합과 유리화","힌트":"$\\overline{\\mathrm{EB}}+\\overline{\\mathrm{HI}}$ 를 분모가 같은 분수로 더한 뒤 유리화하면?","식":["$\\overline{\\mathrm{EB}}+\\overline{\\mathrm{HI}}=\\frac{1+\\sqrt{2}}{3+\\sqrt{2}}+\\frac{1}{3+\\sqrt{2}}=\\frac{2+\\sqrt{2}}{3+\\sqrt{2}}$","$=\\frac{(2+\\sqrt{2})(3-\\sqrt{2})}{(3+\\sqrt{2})(3-\\sqrt{2})}=\\frac{4+\\sqrt{2}}{7}$"],"설명":"분자와 분모에 $3-\\sqrt{2}$ 를 곱하면 분모가 $7$ 이 되어 유리수가 된다.","확인":null,"스킬":"A5"}]},"ns-173153f67590":{"길":"중점을 이은 정사각형의 넓이가 절반이 되는 규칙으로 $A_{5}$ 의 한 변을 구한다","단계":[{"제목":"정사각형 넓이의 변화","힌트":"각 변의 중점을 이어 만든 정사각형의 넓이는 바깥 정사각형 넓이의 몇 분의 몇인가?","식":["정사각형 $A_{2}$ 의 넓이 $=\\frac{1}{2}\\times$ 정사각형 $A_{1}$ 의 넓이","정사각형 $A_{3}$ 의 넓이 $=\\frac{1}{2}\\times$ 정사각형 $A_{2}$ 의 넓이"],"설명":"안쪽 정사각형은 바깥 정사각형에서 합동인 모서리 삼각형 $4$ 개를 뺀 것이고, 그 삼각형들의 넓이의 합이 안쪽 정사각형의 넓이와 같다.","확인":"1/2","스킬":"P1"},{"제목":"$A_{5}$ 의 넓이","힌트":"$A_{1}$ 에서 $A_{5}$ 까지 넓이가 몇 번 절반이 되는가?","식":["$A_{5}$ 의 넓이 $=240\\times\\left(\\frac{1}{2}\\right)^{4}=15$"],"설명":"$A_{1}$ 에서 $A_{5}$ 까지 중점을 $4$ 번 이었다.","확인":"15","스킬":"P1","고비":true},{"제목":"내접원의 반지름","힌트":"정사각형에 내접하는 원의 지름은 정사각형의 무엇과 같은가?","식":["$A_{5}$ 의 한 변은 $\\sqrt{15}$","내접원의 지름 $=\\sqrt{15}$ 이므로 반지름 $=\\frac{\\sqrt{15}}{2}$"],"설명":"내접원은 마주 보는 두 변에 접하므로 지름이 한 변의 길이와 같다.","확인":null,"스킬":"S13"},{"제목":"내접원의 넓이","힌트":"반지름이 $\\frac{\\sqrt{15}}{2}$ 인 원의 넓이는?","식":["$\\pi\\times\\left(\\frac{\\sqrt{15}}{2}\\right)^{2}=\\frac{15}{4}\\pi$"],"설명":"반지름이 $r$ 인 원의 넓이는 $\\pi r^{2}$ 이다.","확인":null,"스킬":"S13"}]},"ns-2417a16fb262":{"길":"$\\overline{\\mathrm{CA}}$ 를 피타고라스 정리로 구해 $a$ 를 정하고 선지를 어림해 비교한다","단계":[{"제목":"$\\overline{\\mathrm{CA}}$ 의 길이","힌트":"$\\overline{\\mathrm{CA}}$ 를 빗변으로 하는 직각삼각형의 가로, 세로는 각각 몇 칸인가?","식":["가로 $3$ 칸, 세로 $1$ 칸","$\\overline{\\mathrm{CA}}=\\sqrt{3^{2}+1^{2}}=\\sqrt{10}$"],"설명":"점 $\\mathrm{C}$ 에서 점 $\\mathrm{A}$ 까지 가로로 $3$ 칸, 세로로 $1$ 칸이다.","확인":null,"스킬":"S3"},{"제목":"$a$ 의 값","힌트":"점 $\\mathrm{P}$ 가 점 $\\mathrm{C}$ 의 왼쪽에 있을 때 $\\mathrm{P}$ 에 대응하는 수는?","식":["$\\overline{\\mathrm{CP}}=\\overline{\\mathrm{CA}}=\\sqrt{10}$ 이므로 $\\mathrm{P}$ 에 대응하는 수는 $4-\\sqrt{10}$","$a=\\overline{\\mathrm{PQ}}=5-(4-\\sqrt{10})=1+\\sqrt{10}$","$a=1+3.162=4.162$"],"설명":"$a$ 가 $4.162$ 이므로 구하는 수는 $4.162$ 보다 크고 $5$ 보다 작은 무리수이다.","확인":null,"스킬":"S3","고비":true},{"제목":"선지 ①, ②, ③ 판정","힌트":"①, ②, ③ 을 $a=4.162$ 와 비교하면?","식":["① $\\sqrt{15}<\\sqrt{16}=4<4.162$ 이므로 $a$ 보다 작다","② $\\frac{9}{5}+\\sqrt{5}=1.8+2.236=4.036<4.162$","③ $4.5$ 는 $a$ 와 $5$ 사이에 있지만 유리수이다"],"설명":"①, ②, ③ 은 조건에 맞지 않는다.","확인":null,"스킬":"S3"},{"제목":"선지 ④, ⑤ 판정","힌트":"④, ⑤ 의 값은 $a$ 와 $5$ 사이에 있는가?","식":["④ $\\frac{a}{2}+2=\\frac{4.162}{2}+2=4.081<a$","⑤ $a+\\frac{1}{2}=4.662$ 이고 $4.162<4.662<5$ 이며 무리수이다"],"설명":"$a$ 가 무리수이므로 $a+\\frac{1}{2}$ 도 무리수이다.","확인":null,"스킬":"S3"}]},"ns-264a908694b4":{"길":"각 변을 제곱해 $n$ 의 범위를 만들고 그 사이의 자연수의 개수를 $x$ 의 식으로 나타낸다","단계":[{"제목":"제곱근 부등식을 $n$ 의 범위로","힌트":"$x<\\sqrt{n}<x+1$ 의 각 변을 제곱하면?","식":["$x^{2}<n<(x+1)^{2}$"],"설명":"$x$ 가 자연수이므로 각 변이 양수여서 제곱해도 부등호의 방향이 바뀌지 않는다.","확인":null,"스킬":"N7"},{"제목":"자연수 $n$ 의 개수","힌트":"$x^{2}$ 과 $(x+1)^{2}$ 사이의 자연수는 몇 개인가?","식":["$(x+1)^{2}-x^{2}-1=2x$","$x=1$ 이면 $2$ 개, $x=2$ 이면 $4$ 개로 문제에서 준 값과 같다"],"설명":"$x^{2}$ 과 $(x+1)^{2}$ 은 범위에 들어가지 않으므로 $1$ 을 뺀다.","확인":null,"스킬":"N7","고비":true},{"제목":"$x$ 의 값","힌트":"$n$ 의 개수 $2x$ 가 $32$ 일 때 $x$ 는?","식":["$2x=32$","$x=16$"],"설명":"개수를 나타낸 식에 $32$ 를 넣어 $x$ 를 구한다.","확인":"16","스킬":"N7"}]},"ns-2cc6d58d3b10":{"길":"정사각형의 한 변은 넓이의 제곱근이므로 세 변을 간단히 한 뒤 더한다","단계":[{"제목":"세 정사각형의 한 변","힌트":"넓이가 $18\\,\\mathrm{cm}^{2}$ 인 정사각형의 한 변의 길이를 $a\\sqrt{b}$ 꼴로 나타내면?","식":["$\\sqrt{18}=3\\sqrt{2}$","$\\sqrt{32}=4\\sqrt{2}$","$\\sqrt{8}=2\\sqrt{2}$"],"설명":"$18=3^{2}\\times2$, $32=4^{2}\\times2$, $8=2^{2}\\times2$ 이므로 제곱인 수를 근호 밖으로 꺼낸다.","확인":null,"스킬":"N1","고비":true},{"제목":"$\\overline{\\mathrm{AB}}$ 의 길이","힌트":"세 정사각형의 한 변의 길이를 모두 더하면?","식":["$\\overline{\\mathrm{AB}}=3\\sqrt{2}+4\\sqrt{2}+2\\sqrt{2}=9\\sqrt{2}\\,(\\mathrm{cm})$"],"설명":"세 정사각형의 한 변이 선분 $\\mathrm{AB}$ 위에 차례로 놓여 있다.","확인":null,"스킬":"N1"}]},"ns-2d3cb0ed9c64":{"길":"겹친 정사각형의 한 변이 앞 정사각형의 절반임을 써서 둘레의 합에서 겹친 부분의 둘레를 뺀다","단계":[{"제목":"네 정사각형의 한 변","힌트":"넓이가 $8$ 인 정사각형의 한 변의 길이를 $a\\sqrt{b}$ 꼴로 나타내면?","식":["$\\sqrt{3}$, $\\sqrt{5}$, $\\sqrt{8}=2\\sqrt{2}$, $\\sqrt{12}=2\\sqrt{3}$"],"설명":"한 변은 넓이의 양의 제곱근이고 $8=2^{2}\\times2$, $12=2^{2}\\times3$ 이다.","확인":null,"스킬":"N1"},{"제목":"겹친 정사각형의 한 변","힌트":"겹친 정사각형의 대각선은 앞 정사각형의 대각선의 몇 분의 몇인가?","식":["겹친 정사각형의 대각선 $=\\frac{1}{2}\\times$ 앞 정사각형의 대각선","한 변도 $\\frac{1}{2}$ 배이므로 $\\frac{\\sqrt{3}}{2}$, $\\frac{\\sqrt{5}}{2}$, $\\sqrt{2}$"],"설명":"다음 정사각형의 꼭짓점이 앞 정사각형의 두 대각선의 교점에 있으므로 겹친 정사각형의 대각선은 앞 정사각형 대각선의 절반이다.","확인":null,"스킬":"S12","고비":true},{"제목":"둘레의 식","힌트":"합친 도형의 둘레는 네 정사각형의 둘레의 합에서 무엇을 빼서 구하는가?","식":["도형의 둘레 $=$ 네 정사각형의 둘레의 합 $-$ 겹친 정사각형 $3$ 개의 둘레의 합","$=4(\\sqrt{3}+\\sqrt{5}+2\\sqrt{2}+2\\sqrt{3})-4\\left(\\frac{\\sqrt{3}}{2}+\\frac{\\sqrt{5}}{2}+\\sqrt{2}\\right)$"],"설명":"겹친 정사각형의 변 $4$ 개는 두 정사각형의 둘레 위에 두 개씩 있고, 그 부분이 서로 안쪽에 들어가므로 바깥 둘레에서 빠진다. 빠지는 길이의 합이 겹친 정사각형의 둘레와 같다.","확인":null,"스킬":"S12"},{"제목":"둘레의 계산","힌트":"$\\sqrt{2}$, $\\sqrt{3}$, $\\sqrt{5}$ 의 계수를 각각 모으면?","식":["$=12\\sqrt{3}+4\\sqrt{5}+8\\sqrt{2}-2\\sqrt{3}-2\\sqrt{5}-4\\sqrt{2}$","$=4\\sqrt{2}+10\\sqrt{3}+2\\sqrt{5}$"],"설명":"근호 안의 수가 같은 항끼리 모아 더하고 뺀다.","확인":null,"스킬":"N1"}]},"ns-2ea318b94868":{"길":"정사각형의 대각선 길이를 구해 점 $\\mathrm{F}$ 에서 거꾸로 점 $\\mathrm{B}$, $\\mathrm{C}$, $\\mathrm{E}$ 의 위치를 차례로 찾는다","단계":[{"제목":"정사각형의 한 변과 대각선","힌트":"넓이가 $4$ 인 정사각형의 한 변과 대각선의 길이는 각각 얼마인가?","식":["한 변 $=\\sqrt{4}=2$","대각선 $\\overline{\\mathrm{CA}}=\\overline{\\mathrm{BD}}=\\sqrt{2^{2}+2^{2}}=2\\sqrt{2}$"],"설명":"정사각형의 대각선은 한 변을 두 변으로 하는 직각이등변삼각형의 빗변이다.","확인":null,"스킬":"S3"},{"제목":"점 B 와 점 C","힌트":"$\\overline{\\mathrm{BF}}=\\overline{\\mathrm{BD}}$ 이고 점 $\\mathrm{F}$ 에 대응하는 수가 $8$ 일 때 점 $\\mathrm{B}$ 에 대응하는 수는?","식":["$\\overline{\\mathrm{BF}}=\\overline{\\mathrm{BD}}=2\\sqrt{2}$ 이므로 점 $\\mathrm{B}$ 에 대응하는 수는 $8-2\\sqrt{2}$","$\\overline{\\mathrm{BC}}=2$ 이므로 점 $\\mathrm{C}$ 에 대응하는 수는 $10-2\\sqrt{2}$"],"설명":"점 $\\mathrm{F}$ 는 점 $\\mathrm{B}$ 의 오른쪽에 있으므로 $\\mathrm{B}$ 는 $8$ 에서 $2\\sqrt{2}$ 를 뺀 수이다.","확인":null,"스킬":"S3","고비":true},{"제목":"점 E 에 대응하는 수","힌트":"$\\overline{\\mathrm{CE}}=\\overline{\\mathrm{CA}}$ 이고 점 $\\mathrm{E}$ 가 점 $\\mathrm{C}$ 의 왼쪽에 있을 때 $\\mathrm{E}$ 에 대응하는 수는?","식":["$10-2\\sqrt{2}-2\\sqrt{2}=10-4\\sqrt{2}$"],"설명":"점 $\\mathrm{E}$ 는 점 $\\mathrm{C}$ 에서 왼쪽으로 $2\\sqrt{2}$ 만큼 떨어져 있다.","확인":null,"스킬":"S3"}]},"ns-3edc820c6e84":{"길":"원이 한 바퀴 구르면 원의 둘레만큼 이동한다는 것을 이용한다","단계":[{"제목":"원이 한 바퀴 구른 거리","힌트":"지름이 $4$ 인 원의 둘레의 길이는?","식":["원의 둘레 $=\\pi\\times4=4\\pi$"],"설명":"원이 미끄러지지 않고 한 바퀴 구르면 원의 둘레와 같은 거리만큼 이동한다.","확인":null,"스킬":"C7","고비":true},{"제목":"점 B 에 대응하는 수","힌트":"두 바퀴 굴러간 거리를 점 $\\mathrm{A}$ 에 대응하는 수 $2$ 에 더하면?","식":["두 바퀴: $2\\times4\\pi=8\\pi$","점 $\\mathrm{B}$ 에 대응하는 수 $=2+8\\pi$"],"설명":"오른쪽으로 굴렸으므로 점 $\\mathrm{B}$ 는 점 $\\mathrm{A}$ 의 오른쪽에 있다.","확인":null,"스킬":"C7"}]},"ns-41a0f79d3d32":{"길":"직사각형에서 정사각형을 차례로 떼어 네 변을 구하고 사분원의 호의 길이를 더한다","단계":[{"제목":"첫째, 둘째 정사각형의 한 변","힌트":"가로 $1+\\sqrt{5}$, 세로 $2$ 인 직사각형에서 한 변이 $2$ 인 정사각형 $A$ 를 떼면 남는 직사각형의 가로는?","식":["$A$ 의 한 변 $=2$","남은 직사각형: 가로 $(1+\\sqrt{5})-2=\\sqrt{5}-1$, 세로 $2$","$B$ 의 한 변 $=\\sqrt{5}-1$"],"설명":"남은 직사각형에서 짧은 변이 다음 정사각형의 한 변이 된다. $\\sqrt{5}-1$ 은 $2$ 보다 작다.","확인":null,"스킬":"S12"},{"제목":"셋째, 넷째 정사각형의 한 변","힌트":"$B$ 를 떼고 남은 직사각형의 세로는 얼마인가?","식":["남은 직사각형: 가로 $\\sqrt{5}-1$, 세로 $2-(\\sqrt{5}-1)=3-\\sqrt{5}$","$C$ 의 한 변 $=3-\\sqrt{5}$","남은 가로 $(\\sqrt{5}-1)-(3-\\sqrt{5})=2\\sqrt{5}-4$ 이므로 $D$ 의 한 변 $=2\\sqrt{5}-4$"],"설명":"남은 직사각형의 짧은 변이 계속 다음 정사각형의 한 변이 된다.","확인":null,"스킬":"S12","고비":true},{"제목":"사분원의 호의 길이","힌트":"반지름이 $r$ 인 사분원의 호의 길이를 $r$ 로 나타내면?","식":["호의 길이 $=\\frac{1}{4}\\times2\\pi r=\\frac{\\pi}{2}r$"],"설명":"사분원은 중심각이 $90^{\\circ}$ 이므로 원의 둘레의 $\\frac{1}{4}$ 이다.","확인":null,"스킬":"S13"},{"제목":"호의 길이의 합","힌트":"네 사분원의 반지름의 합을 구하면?","식":["반지름의 합 $=2+(\\sqrt{5}-1)+(3-\\sqrt{5})+(2\\sqrt{5}-4)=2\\sqrt{5}$","호의 길이의 합 $=\\frac{\\pi}{2}\\times2\\sqrt{5}=\\sqrt{5}\\pi$"],"설명":"네 호의 길이에 모두 $\\frac{\\pi}{2}$ 가 곱해지므로 반지름의 합을 먼저 구한다.","확인":null,"스킬":"S13"}]},"ns-464eeaa50d22":{"길":"정사각형의 대각선 길이를 구해 $1$ 에서 그만큼 오른쪽에 있는 점을 찾는다","단계":[{"제목":"정사각형의 대각선","힌트":"한 변이 $1$ 인 정사각형의 대각선의 길이는?","식":["$\\sqrt{1^{2}+1^{2}}=\\sqrt{2}$"],"설명":"각 호의 반지름은 정사각형의 대각선의 길이이다.","확인":null,"스킬":"S3"},{"제목":"$1+\\sqrt{2}$ 에 대응하는 점","힌트":"$1$ 에서 오른쪽으로 $\\sqrt{2}$ 만큼 떨어진 점은 어느 점인가?","식":["점 $\\mathrm{E}$ 는 $1$ 을 중심으로 반지름 $\\sqrt{2}$ 인 호가 수직선과 만나는 점","따라서 $\\mathrm{E}$ 에 대응하는 수는 $1+\\sqrt{2}$"],"설명":"점 $\\mathrm{D}$ 는 $0$ 을 중심으로 한 호가 닿는 점이므로 $\\sqrt{2}$ 에 대응한다.","확인":null,"스킬":"S3","고비":true}]},"ns-4d9f048e1b88":{"길":"한 칸의 넓이를 구한 뒤 $\\overline{\\mathrm{OA}}$ 를 피타고라스 정리로 구한다","단계":[{"제목":"모눈 칸 수로 센 넓이","힌트":"$\\square\\mathrm{OADE}$ 의 넓이는 모눈 몇 칸인가?","식":["둘러싼 직사각형의 넓이 $=5\\times3=15$ 칸","네 모서리 직각삼각형: $\\frac{1\\times2}{2}+\\frac{4\\times1}{2}+\\frac{1\\times2}{2}+\\frac{4\\times1}{2}=6$ 칸","$\\square\\mathrm{OADE}=15-6=9$ 칸"],"설명":"$\\square\\mathrm{OADE}$ 를 둘러싸는 직사각형에서 네 모서리의 직각삼각형을 뺀다.","확인":"9","스킬":"S12","고비":true},{"제목":"한 칸의 넓이","힌트":"모눈 한 칸의 한 변을 $u$ 라 할 때 $9u^{2}=54$ 에서 $u^{2}$ 은?","식":["$9u^{2}=54$","$u^{2}=6$"],"설명":"모눈 한 칸은 정사각형이므로 한 칸의 넓이는 $u^{2}$ 이다.","확인":"6","스킬":"S8"},{"제목":"$\\overline{\\mathrm{OA}}$ 를 빗변으로 하는 삼각형","힌트":"$\\overline{\\mathrm{OA}}^{2}$ 은 $u^{2}$ 의 몇 배인가?","식":["$\\overline{\\mathrm{OA}}$ 를 빗변으로 하는 직각삼각형은 가로 $1$ 칸, 세로 $2$ 칸","$\\overline{\\mathrm{OA}}^{2}=(1^{2}+2^{2})u^{2}=5u^{2}$"],"설명":"한 칸의 길이가 $u$ 이므로 가로는 $u$, 세로는 $2u$ 이다.","확인":"5","스킬":"S3"},{"제목":"$\\overline{\\mathrm{OA}}$ 의 길이","힌트":"$\\overline{\\mathrm{OA}}^{2}=5u^{2}$ 에 $u^{2}=6$ 을 넣으면 $\\overline{\\mathrm{OA}}$ 는?","식":["$\\overline{\\mathrm{OA}}^{2}=5\\times6=30$","$\\overline{\\mathrm{OA}}=\\sqrt{30}$"],"설명":"길이는 양수이므로 양의 제곱근을 택한다.","확인":null,"스킬":"S3"}]},"ns-6607399ec827":{"길":"한 변을 $s$ 로 두고 둘레를 $s$ 의 식으로 나타내 $s$ 를 구한 뒤 넓이를 구한다","단계":[{"제목":"세 꽃밭의 한 변","힌트":"넓이의 비가 $1:2:4$ 이면 한 변의 길이의 비는?","식":["한 변의 길이의 비 $=\\sqrt{1}:\\sqrt{2}:\\sqrt{4}=1:\\sqrt{2}:2$","꽃밭 $\\mathrm{A}$ 의 한 변을 $s$ 라 하면 $\\mathrm{B}$ 는 $\\sqrt{2}s$, $\\mathrm{C}$ 는 $2s$"],"설명":"넓이의 비는 한 변의 길이의 비의 제곱이므로 한 변의 길이의 비는 넓이의 비의 제곱근의 비이다.","확인":null,"스킬":"S1"},{"제목":"둘레를 $s$ 로 나타내기","힌트":"가로 방향 선분과 세로 방향 선분의 길이의 합을 각각 구하면?","식":["가로 방향: 위쪽 선분의 합과 아래쪽 선분의 합이 같으므로 $2\\times(s+\\sqrt{2}s+2s)=(6+2\\sqrt{2})s$","세로 방향: 계단 모양이 한 번 올라갔다 내려오므로 가장 높은 변 $2s$ 의 $2$ 배 $=4s$","둘레 $=(6+2\\sqrt{2})s+4s=(10+2\\sqrt{2})s$"],"설명":"위쪽에서 보이는 가로 선분을 모으면 아래쪽 변의 길이의 합과 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"$s$ 의 값","힌트":"$(10+2\\sqrt{2})s=46$ 에서 분모를 유리화하여 $s$ 를 구하면?","식":["$s=\\frac{46}{10+2\\sqrt{2}}=\\frac{23}{5+\\sqrt{2}}$","$=\\frac{23(5-\\sqrt{2})}{(5+\\sqrt{2})(5-\\sqrt{2})}=\\frac{23(5-\\sqrt{2})}{23}=5-\\sqrt{2}$"],"설명":"분모와 분자에 $5-\\sqrt{2}$ 를 곱하면 분모가 $23$ 이 된다.","확인":null,"스킬":"A5"},{"제목":"꽃밭 A 의 넓이","힌트":"한 변이 $5-\\sqrt{2}$ 인 정사각형의 넓이는?","식":["$(5-\\sqrt{2})^{2}=25-10\\sqrt{2}+2=27-10\\sqrt{2}$"],"설명":"$(a-b)^{2}=a^{2}-2ab+b^{2}$ 을 쓴다.","확인":null,"스킬":"C7"}]},"ns-6cef4e7c4cac":{"길":"정사각형이 꼭짓점을 중심으로 $90^{\\circ}$ 씩 네 번 회전하는 동안 점 $\\mathrm{A}$ 가 그리는 호를 더한다","단계":[{"제목":"회전 횟수와 회전각","힌트":"정사각형이 한 바퀴 굴러 같은 모양이 되기까지 꼭짓점을 중심으로 몇 번 회전하는가?","식":["네 변이 차례로 바닥에 닿으므로 $90^{\\circ}$ 씩 $4$ 번 회전"],"설명":"한 번 회전할 때마다 한 변이 바닥에 놓이고 회전각은 $90^{\\circ}$ 이다.","확인":"4","스킬":"C2"},{"제목":"회전할 때마다의 반지름","힌트":"각 회전의 중심에서 점 $\\mathrm{A}$ 까지의 거리는 차례로 얼마인가?","식":["첫째: 중심이 $\\mathrm{A}$ 와 이웃한 꼭짓점이므로 반지름 $4$","둘째: 중심이 $\\mathrm{A}$ 의 맞은편 꼭짓점이므로 반지름 $4\\sqrt{2}$","셋째: 반지름 $4$, 넷째: 중심이 $\\mathrm{A}$ 자신이므로 움직이지 않는다"],"설명":"정사각형의 대각선은 한 변이 $4$ 인 직각이등변삼각형의 빗변이므로 $4\\sqrt{2}$ 이다.","확인":null,"스킬":"S3","고비":true},{"제목":"호의 길이의 합","힌트":"중심각이 $90^{\\circ}$ 이고 반지름이 $r$ 인 호의 길이를 $r$ 로 나타내면?","식":["반지름 $4$: $\\frac{1}{4}\\times2\\pi\\times4=2\\pi$","반지름 $4\\sqrt{2}$: $\\frac{1}{4}\\times2\\pi\\times4\\sqrt{2}=2\\sqrt{2}\\pi$","합 $=2\\pi+2\\sqrt{2}\\pi+2\\pi+0=(4+2\\sqrt{2})\\pi$"],"설명":"움직이지 않는 마지막 회전은 호의 길이가 $0$ 이다.","확인":null,"스킬":"S13"}]},"ns-6f78c0d958cc":{"길":"$96n$ 이 제곱수가 되는 $n$ 의 꼴을 소인수분해로 찾고 $60-n$ 도 제곱수인지 확인한다","단계":[{"제목":"$96n$ 이 제곱수가 되는 $n$ 의 꼴","힌트":"$96n=2^{5}\\times3\\times n$ 이 제곱수이려면 $n$ 은 어떤 꼴이어야 하는가?","식":["$96=2^{5}\\times3$","소인수의 지수가 모두 짝수이려면 $n$ 에 $2\\times3=6$ 이 곱해져 있어야 한다","$n=6k^{2}$ ($k$ 는 자연수)"],"설명":"$2^{5}\\times3\\times6k^{2}=2^{6}\\times3^{2}\\times k^{2}$ 이므로 제곱수이다.","확인":null,"스킬":"N1","고비":true},{"제목":"조건에 맞는 $n$","힌트":"$n=6k^{2}$ 중에서 $60-n$ 도 제곱수가 되는 $n$ 은?","식":["$60-n>0$ 이므로 $n=6,\\ 24,\\ 54$","$60-n=54,\\ 36,\\ 6$ 중 제곱수는 $36$","$n=24$"],"설명":"$60-n$ 은 정사각형의 넓이이므로 자연수의 제곱이어야 한다.","확인":"24","스킬":"N8"},{"제목":"정사각형 A, B 의 한 변","힌트":"$n=24$ 일 때 정사각형 $\\mathrm{A}$ 의 한 변의 길이는?","식":["$\\mathrm{A}$ 의 넓이 $=96\\times24=2304=48^{2}$ 이므로 한 변 $48\\,\\mathrm{m}$","$\\mathrm{B}$ 의 넓이 $=60-24=36=6^{2}$ 이므로 한 변 $6\\,\\mathrm{m}$"],"설명":"넓이가 $a^{2}$ 인 정사각형의 한 변은 $a$ 이다.","확인":"48","스킬":"N8"},{"제목":"직사각형 C 의 넓이","힌트":"직사각형 $\\mathrm{C}$ 의 두 변의 길이는 각각 얼마인가?","식":["$\\mathrm{C}$ 의 가로 $=\\mathrm{B}$ 의 한 변 $=6$","$\\mathrm{C}$ 의 세로 $=48-6=42$","$\\mathrm{C}$ 의 넓이 $=6\\times42=252\\,(\\mathrm{m}^{2})$"],"설명":"$\\mathrm{A}$ 의 한 변은 $\\mathrm{B}$ 의 한 변과 $\\mathrm{C}$ 의 세로를 합한 길이와 같다.","확인":"252","스킬":"S12"}]},"ns-73fd30918936":{"길":"$\\overline{\\mathrm{BD}}$ 로 점 $\\mathrm{B}$ 를 정하고 $\\overline{\\mathrm{AF}}$ 로 점 $\\mathrm{Q}$ 를 구한 뒤 역수의 분모를 유리화한다","단계":[{"제목":"점 B 의 위치","힌트":"$\\overline{\\mathrm{BP}}=\\overline{\\mathrm{BD}}$ 일 때 $\\mathrm{P}$ 의 좌표에서 점 $\\mathrm{B}$ 에 대응하는 수는?","식":["$\\overline{\\mathrm{BD}}=\\sqrt{1^{2}+1^{2}}=\\sqrt{2}$","$\\mathrm{P}$ 는 $\\mathrm{B}$ 의 왼쪽이므로 $\\mathrm{B}$ 에 대응하는 수는 $(-1-\\sqrt{2})+\\sqrt{2}=-1$"],"설명":"한 원의 반지름이므로 $\\overline{\\mathrm{BP}}=\\overline{\\mathrm{BD}}=\\sqrt{2}$ 이다.","확인":"-1","스킬":"S3","고비":true},{"제목":"점 A 와 $\\overline{\\mathrm{AF}}$ 의 길이","힌트":"$\\overline{\\mathrm{AF}}$ 를 빗변으로 하는 직각삼각형의 두 변의 길이는?","식":["$\\overline{\\mathrm{AB}}=1$ 이므로 점 $\\mathrm{A}$ 에 대응하는 수는 $-1-1=-2$","$\\overline{\\mathrm{AC}}=2$, $\\overline{\\mathrm{CF}}=1$ 이므로 $\\overline{\\mathrm{AF}}=\\sqrt{2^{2}+1^{2}}=\\sqrt{5}$"],"설명":"점 $\\mathrm{A}$, $\\mathrm{B}$, $\\mathrm{C}$ 는 한 칸씩 떨어져 있다.","확인":null,"스킬":"S3"},{"제목":"점 Q 에 대응하는 수","힌트":"$\\overline{\\mathrm{AQ}}=\\overline{\\mathrm{AF}}$ 이고 점 $\\mathrm{Q}$ 가 점 $\\mathrm{A}$ 의 오른쪽에 있을 때 $\\mathrm{Q}$ 에 대응하는 수는?","식":["$\\mathrm{Q}=-2+\\sqrt{5}$"],"설명":"그림에서 점 $\\mathrm{Q}$ 는 점 $\\mathrm{A}$ 의 오른쪽에 있다.","확인":null,"스킬":"S3"},{"제목":"$\\frac{1}{Q}$ 의 값","힌트":"$\\frac{1}{-2+\\sqrt{5}}$ 의 분모를 유리화하려면 분자와 분모에 무엇을 곱하는가?","식":["$\\frac{1}{-2+\\sqrt{5}}=\\frac{\\sqrt{5}+2}{(\\sqrt{5}-2)(\\sqrt{5}+2)}$","$=\\frac{\\sqrt{5}+2}{5-4}=2+\\sqrt{5}$"],"설명":"$\\sqrt{5}+2$ 를 곱하면 합과 차의 곱 공식으로 분모가 유리수가 된다.","확인":null,"스킬":"A5"}]},"ns-899b59729446":{"길":"정사각형의 한 변을 차례로 구해 색칠한 부분의 둘레를 조각별로 더한다","단계":[{"제목":"정사각형 한 변의 변화","힌트":"각 변의 중점을 이어 만든 정사각형의 한 변은 바깥 정사각형의 한 변의 몇 배인가?","식":["한 변: $2\\rightarrow\\sqrt{2}\\rightarrow1\\rightarrow\\frac{\\sqrt{2}}{2}$","한 변이 $a$ 이면 다음 정사각형의 한 변은 $\\sqrt{\\left(\\frac{a}{2}\\right)^{2}+\\left(\\frac{a}{2}\\right)^{2}}=\\frac{\\sqrt{2}}{2}a$"],"설명":"다음 정사각형의 한 변은 길이가 $\\frac{a}{2}$ 인 두 변을 가진 직각이등변삼각형의 빗변이다.","확인":null,"스킬":"S3"},{"제목":"바깥 삼각형 $4$ 개의 둘레","힌트":"색칠한 바깥 삼각형의 세 변의 길이는 각각 얼마인가?","식":["밑변은 셋째 정사각형의 한 변 $1$, 나머지 두 변은 각각 $\\frac{\\sqrt{2}}{2}$","삼각형 한 개의 둘레 $=1+\\frac{\\sqrt{2}}{2}\\times2=1+\\sqrt{2}$","$4$ 개의 둘레 $=4(1+\\sqrt{2})=4+4\\sqrt{2}$"],"설명":"셋째 정사각형의 꼭짓점은 둘째 정사각형의 변의 중점이므로 둘째 정사각형의 한 변 $\\sqrt{2}$ 가 반으로 나뉜다.","확인":null,"스킬":"S12","고비":true},{"제목":"가운데 정사각형의 둘레","힌트":"가운데 색칠한 정사각형의 한 변의 길이는?","식":["한 변 $=\\frac{\\sqrt{2}}{2}$","둘레 $=4\\times\\frac{\\sqrt{2}}{2}=2\\sqrt{2}$"],"설명":"가운데 색칠한 정사각형은 한 변이 $\\frac{\\sqrt{2}}{2}$ 인 넷째 정사각형이다.","확인":null,"스킬":"S12"},{"제목":"둘레의 합","힌트":"바깥 삼각형 $4$ 개와 가운데 정사각형의 둘레를 더하면?","식":["$(4+4\\sqrt{2})+2\\sqrt{2}=4+6\\sqrt{2}$"],"설명":"색칠한 부분은 조각이 떨어져 있으므로 둘레를 각각 구해 더한다.","확인":null,"스킬":"S12"}]},"ns-8ce162532927":{"길":"한 변을 $s$ 로 두고 둘레의 식에서 $s$ 를 구해 두 정사각형의 넓이의 합을 구한다","단계":[{"제목":"두 정사각형의 한 변","힌트":"넓이의 비가 $1:3$ 이면 한 변의 길이의 비는?","식":["한 변의 길이의 비 $=1:\\sqrt{3}$","작은 정사각형의 한 변을 $s$ 라 하면 큰 정사각형의 한 변은 $\\sqrt{3}s$"],"설명":"넓이의 비는 한 변의 길이의 비의 제곱이다.","확인":null,"스킬":"S1"},{"제목":"둘레를 $s$ 의 식으로","힌트":"가로 방향 선분과 세로 방향 선분의 길이의 합을 각각 구하면?","식":["가로 방향: $2\\times(s+\\sqrt{3}s)=(2+2\\sqrt{3})s$","세로 방향: 계단 모양이 한 번 올라갔다 내려오므로 큰 정사각형의 한 변의 $2$ 배 $=2\\sqrt{3}s$","둘레 $=(2+4\\sqrt{3})s$"],"설명":"위쪽에서 보이는 가로 선분의 합은 아래쪽 변의 길이의 합과 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"$s$ 의 값","힌트":"$(2+4\\sqrt{3})s=44$ 에서 분모를 유리화하여 $s$ 를 구하면?","식":["$s=\\frac{44}{2+4\\sqrt{3}}=\\frac{22}{1+2\\sqrt{3}}$","$=\\frac{22(2\\sqrt{3}-1)}{(2\\sqrt{3}+1)(2\\sqrt{3}-1)}=\\frac{22(2\\sqrt{3}-1)}{11}=4\\sqrt{3}-2$"],"설명":"분모와 분자에 $2\\sqrt{3}-1$ 을 곱하면 분모가 $11$ 이 된다.","확인":null,"스킬":"A5"},{"제목":"도형의 넓이","힌트":"두 정사각형의 넓이의 합은 $s^{2}$ 의 몇 배인가?","식":["넓이 $=s^{2}+3s^{2}=4s^{2}$","$4(4\\sqrt{3}-2)^{2}=4(52-16\\sqrt{3})=208-64\\sqrt{3}$"],"설명":"$(4\\sqrt{3}-2)^{2}=48-16\\sqrt{3}+4=52-16\\sqrt{3}$ 이다.","확인":null,"스킬":"C7"}]},"ns-8f34eee26866":{"길":"$54n$ 이 제곱수가 되는 $n$ 의 꼴을 찾고 $12+n$ 도 제곱수가 되는 가장 작은 $n$ 을 구한다","단계":[{"제목":"$54n$ 이 제곱수가 되는 $n$ 의 꼴","힌트":"$54n=2\\times3^{3}\\times n$ 이 제곱수이려면 $n$ 은 어떤 꼴이어야 하는가?","식":["$54=2\\times3^{3}$","소인수의 지수가 모두 짝수이려면 $n$ 에 $2\\times3=6$ 이 곱해져 있어야 한다","$n=6k^{2}$ ($k$ 는 자연수)"],"설명":"$2\\times3^{3}\\times6k^{2}=2^{2}\\times3^{4}\\times k^{2}$ 이므로 제곱수이다.","확인":null,"스킬":"N1","고비":true},{"제목":"$12+n$ 도 제곱수인 가장 작은 $n$","힌트":"$n=6,\\ 24,\\ 54,\\ \\cdots$ 중에서 $12+n$ 이 제곱수가 되는 가장 작은 값은?","식":["$n=6$ 이면 $12+6=18$ (제곱수가 아니다)","$n=24$ 이면 $12+24=36=6^{2}$ (제곱수이다)"],"설명":"$k$ 를 $1$ 부터 차례로 넣어 처음으로 조건이 맞는 $n$ 을 찾는다.","확인":"24","스킬":"N8"},{"제목":"두 정사각형의 한 변","힌트":"$n=24$ 일 때 과수원의 한 변의 길이는?","식":["과수원의 넓이 $=54\\times24=1296=36^{2}$ 이므로 한 변 $36$","배추밭의 넓이 $=12+24=36=6^{2}$ 이므로 한 변 $6$"],"설명":"넓이가 $a^{2}$ 인 정사각형의 한 변은 $a$ 이다.","확인":"36","스킬":"N8"},{"제목":"무밭의 둘레","힌트":"무밭의 가로, 세로의 길이는 각각 얼마인가?","식":["무밭의 가로 $=$ 배추밭의 한 변 $=6$","무밭의 세로 $=36-6=30$","둘레 $=2\\times(6+30)=72$"],"설명":"과수원의 한 변은 무밭의 세로와 배추밭의 한 변을 합한 길이와 같다.","확인":"72","스킬":"S12"}]},"ns-8f933cfcb6c9":{"길":"겹친 정사각형의 한 변이 앞 정사각형의 절반임을 써서 둘레의 합에서 겹친 부분의 둘레를 뺀다","단계":[{"제목":"네 정사각형의 한 변","힌트":"넓이가 $18$ 인 정사각형의 한 변의 길이를 $a\\sqrt{b}$ 꼴로 나타내면?","식":["$\\sqrt{4}=2$, $\\sqrt{8}=2\\sqrt{2}$, $\\sqrt{16}=4$, $\\sqrt{18}=3\\sqrt{2}$"],"설명":"한 변은 넓이의 양의 제곱근이고 $8=2^{2}\\times2$, $18=3^{2}\\times2$ 이다.","확인":null,"스킬":"N1"},{"제목":"겹친 정사각형의 한 변","힌트":"겹친 정사각형의 대각선은 앞 정사각형의 대각선의 몇 분의 몇인가?","식":["겹친 정사각형의 대각선 $=\\frac{1}{2}\\times$ 앞 정사각형의 대각선","한 변도 $\\frac{1}{2}$ 배이므로 $1$, $\\sqrt{2}$, $2$"],"설명":"다음 정사각형의 꼭짓점이 앞 정사각형의 두 대각선의 교점에 있으므로 겹친 정사각형의 대각선은 앞 정사각형 대각선의 절반이다.","확인":null,"스킬":"S12","고비":true},{"제목":"둘레의 식","힌트":"합친 도형의 둘레는 네 정사각형의 둘레의 합에서 무엇을 빼서 구하는가?","식":["도형의 둘레 $=$ 네 정사각형의 둘레의 합 $-$ 겹친 정사각형 $3$ 개의 둘레의 합","$=4(2+2\\sqrt{2}+4+3\\sqrt{2})-4(1+\\sqrt{2}+2)$"],"설명":"겹친 정사각형의 변 $4$ 개는 두 정사각형의 둘레 위에 두 개씩 있고, 그 부분이 서로 안쪽에 들어가므로 바깥 둘레에서 빠진다. 빠지는 길이의 합이 겹친 정사각형의 둘레와 같다.","확인":null,"스킬":"S12"},{"제목":"둘레의 계산","힌트":"상수항과 $\\sqrt{2}$ 의 계수를 각각 모으면?","식":["$=4(6+5\\sqrt{2})-4(3+\\sqrt{2})$","$=24+20\\sqrt{2}-12-4\\sqrt{2}=12+16\\sqrt{2}$"],"설명":"근호가 없는 항끼리, $\\sqrt{2}$ 가 든 항끼리 모아 계산한다.","확인":null,"스킬":"N1"}]},"ns-921ac8d8dfac":{"길":"A2 와 B6 의 넓이를 A0 의 넓이로 나타내고 넓이비의 제곱근으로 닮음비를 구한다","단계":[{"제목":"A2 용지의 넓이","힌트":"A0 을 두 번 반으로 자른 A2 의 넓이는 A0 넓이의 몇 배인가?","식":["반으로 자를 때마다 넓이는 $\\frac{1}{2}$ 배","A2 의 넓이 $=\\left(\\frac{1}{2}\\right)^{2}\\times$ A0 의 넓이 $=\\frac{1}{4}\\times$ A0 의 넓이"],"설명":"A2 는 A0 을 두 번 반으로 자른 용지이다.","확인":"1/4","스킬":"S1"},{"제목":"B6 용지의 넓이","힌트":"B6 의 넓이는 A0 넓이의 몇 배인가?","식":["B6 의 넓이 $=\\left(\\frac{1}{2}\\right)^{6}\\times$ B0 의 넓이 $=\\frac{1}{64}\\times$ B0 의 넓이","B0 의 넓이 $=1.5\\times$ A0 의 넓이이므로 B6 의 넓이 $=\\frac{1.5}{64}\\times$ A0 의 넓이 $=\\frac{3}{128}\\times$ A0 의 넓이"],"설명":"B6 은 B0 을 여섯 번 반으로 자른 용지이다.","확인":"3/128","스킬":"S1"},{"제목":"넓이비와 닮음비","힌트":"B6 의 넓이는 A2 넓이의 몇 배인가?","식":["$\\frac{3}{128}\\div\\frac{1}{4}=\\frac{3}{32}$","닮음비가 $1:b$ 이면 넓이비는 $1:b^{2}$ 이므로 $b^{2}=\\frac{3}{32}$"],"설명":"닮은 도형의 넓이의 비는 닮음비의 제곱이다.","확인":"3/32","스킬":"S1","고비":true},{"제목":"$b$ 의 값","힌트":"$b^{2}=\\frac{3}{32}$ 이고 $b>0$ 일 때 $b$ 를 분모를 유리화하여 나타내면?","식":["$b=\\sqrt{\\frac{3}{32}}=\\frac{\\sqrt{3}}{4\\sqrt{2}}=\\frac{\\sqrt{6}}{8}$"],"설명":"$\\sqrt{32}=4\\sqrt{2}$ 이고 분자와 분모에 $\\sqrt{2}$ 를 곱하면 분모가 유리수가 된다.","확인":null,"스킬":"S1"}]},"ns-9e1fc758b1c3":{"길":"기울어진 정사각형의 한 변을 모눈과 피타고라스 정리로 구해 네 점의 값을 정하고 선지를 가린다","단계":[{"제목":"작은 정사각형과 점 A, B","힌트":"작은 정사각형의 한 변을 모눈 위 직각삼각형으로 구하면?","식":["한 변 $=\\sqrt{1^{2}+1^{2}}=\\sqrt{2}$","중심 $-1$ 에서 왼쪽, 오른쪽으로 $\\sqrt{2}$ 만큼: $a=-1-\\sqrt{2}$, $b=-1+\\sqrt{2}$"],"설명":"반원의 중심은 수직선 위의 꼭짓점이고 반지름은 정사각형의 한 변이다.","확인":null,"스킬":"S3"},{"제목":"큰 정사각형과 점 C, D","힌트":"큰 정사각형의 한 변을 모눈 위 직각삼각형으로 구하면?","식":["한 변 $=\\sqrt{2^{2}+2^{2}}=2\\sqrt{2}$","중심 $5$ 에서 왼쪽, 오른쪽으로 $2\\sqrt{2}$ 만큼: $c=5-2\\sqrt{2}$, $d=5+2\\sqrt{2}$"],"설명":"큰 정사각형은 가로, 세로로 $2$ 칸씩 기울어져 있다.","확인":null,"스킬":"S3","고비":true},{"제목":"선지 ①, ②, ③ 판정","힌트":"①, ②, ③ 의 식에 $a$, $b$, $c$ 의 값을 넣으면?","식":["① $a=-1-\\sqrt{2}\\ne-\\sqrt{2}$","② $c=5-2\\sqrt{2}\\ne1+\\sqrt{8}$","③ $\\overline{\\mathrm{BC}}=c-b=6-3\\sqrt{2}\\ne6+3\\sqrt{2}$"],"설명":"①, ②, ③ 은 모두 옳지 않다.","확인":null,"스킬":"S3"},{"제목":"선지 ④, ⑤ 판정","힌트":"④, ⑤ 의 식에 값을 넣으면?","식":["④ $a+d=(-1-\\sqrt{2})+(5+2\\sqrt{2})=4+\\sqrt{2}$ 이므로 옳다","⑤ $b+c=(-1+\\sqrt{2})+(5-2\\sqrt{2})=4-\\sqrt{2}\\ne-4-\\sqrt{2}$"],"설명":"④ 만 옳으므로 정답은 ④ 이다.","확인":null,"스킬":"S3"}]},"ns-99c03cec8480":{"길":"두 지름 $\\overline{\\mathrm{AD}}$, $\\overline{\\mathrm{DB}}$ 를 $a$, $b$ 로 나타낸 뒤 넓이의 차를 합차 공식으로 정리한다","단계":[{"제목":"$\\overline{\\mathrm{AD}}$, $\\overline{\\mathrm{DB}}$ 의 길이 구하기","힌트":"$\\mathrm{D}$ 가 $\\overline{\\mathrm{AC}}$ 의 중점일 때 $\\overline{\\mathrm{AD}}$ 는 $a$, $b$ 로 얼마인가?","식":["$\\overline{\\mathrm{AC}}=a+b$","$\\overline{\\mathrm{AD}}=\\frac{a+b}{2}$","$\\overline{\\mathrm{DB}}=a-\\frac{a+b}{2}=\\frac{a-b}{2}$"],"설명":"두 원이 점 $\\mathrm{B}$ 에서 만나므로 $\\overline{\\mathrm{AC}}$ 는 두 지름의 합이다. $\\overline{\\mathrm{DB}}$ 는 $\\overline{\\mathrm{AB}}$ 에서 $\\overline{\\mathrm{AD}}$ 를 뺀 길이이다.","확인":null,"스킬":"C7","고비":true},{"제목":"두 원의 넓이의 차 세우기","힌트":"지름이 $\\overline{\\mathrm{AD}}$ 인 원의 넓이 $S_{1}$ 을 $a$, $b$ 로 나타내면?","식":["$S_{1}=\\pi\\left(\\frac{a+b}{4}\\right)^{2}$, $S_{2}=\\pi\\left(\\frac{a-b}{4}\\right)^{2}$","$S_{1}-S_{2}=\\frac{\\pi}{16}\\{(a+b)^{2}-(a-b)^{2}\\}$"],"설명":"반지름은 지름의 절반이므로 각각 $\\frac{a+b}{4}$, $\\frac{a-b}{4}$ 이다.","확인":null,"스킬":"C7"},{"제목":"합차 공식으로 정리","힌트":"$(a+b)^{2}-(a-b)^{2}$ 을 정리하면?","식":["$(a+b)^{2}-(a-b)^{2}=4ab$","$S_{1}-S_{2}=\\frac{\\pi}{16}\\times4ab=\\frac{ab}{4}\\pi$"],"설명":"$X^{2}-Y^{2}=(X+Y)(X-Y)$ 에서 $X=a+b$, $Y=a-b$ 이면 $2a\\times2b=4ab$ 이다.","확인":null,"스킬":"A2"}]},"ns-a16e18231d62":{"길":"$(x-c)^{2}$ 을 전개해 계수를 비교한 뒤 조건에 맞는 $c$ 를 모두 찾는다","단계":[{"제목":"계수 비교로 $a$, $b$ 를 $c$ 로 나타내기","힌트":"$(x-c)^{2}$ 을 전개하면?","식":["$(x-c)^{2}=x^{2}-2cx+c^{2}$","$x^{2}-ax+b=x^{2}-2cx+c^{2}$ 에서 $a=2c,\\ b=c^{2}$"],"설명":"$x$ 에 관한 항등식이므로 같은 차수의 계수끼리 비교한다.","확인":null,"스킬":"A3"},{"제목":"조건에 맞는 $c$ 찾기","힌트":"$b=c^{2}$ 이 $10$ 이하의 홀수가 되는 자연수 $c$ 는?","식":["$c=1$: $b=1$, $a=2$","$c=3$: $b=9$, $a=6$","$c=2$ 는 $b=4$ 로 짝수이고, $c\\ge4$ 는 $b\\ge16$ 이므로 제외"],"설명":"$a$ 는 $10$ 이하의 짝수, $b$ 는 $10$ 이하의 홀수이어야 한다.","확인":null,"스킬":"N5","고비":true},{"제목":"$c=1$ 일 때의 합","힌트":"$(a,\\ b,\\ c)=(2,\\ 1,\\ 1)$ 일 때 $a+b+c$ 는?","식":["$a+b+c=2+1+1=4$"],"설명":"세 값을 더한다.","확인":"4","스킬":"A3"},{"제목":"$c=3$ 일 때의 합","힌트":"$(a,\\ b,\\ c)=(6,\\ 9,\\ 3)$ 일 때 $a+b+c$ 는?","식":["$a+b+c=6+9+3=18$","따라서 $a+b+c$ 의 값은 $4$ 또는 $18$"],"설명":"두 경우의 값을 모두 쓴다.","확인":null,"스킬":"A3"}]},"ns-a5e0f7f4c1f6":{"길":"접힌 변의 길이가 같음을 이용해 $\\overline{\\mathrm{EG}}$, $\\overline{\\mathrm{FJ}}$ 를 $a$, $b$ 로 나타낸 뒤 합차 공식으로 인수분해한다","단계":[{"제목":"$\\overline{\\mathrm{EG}}$ 의 길이 구하기","힌트":"$\\overline{\\mathrm{AB}}$ 가 $\\overline{\\mathrm{BF}}$ 에 겹치도록 접으면 $\\overline{\\mathrm{AE}}$ 의 길이는?","식":["$\\mathrm{ABFE}$ 는 정사각형이므로 $\\overline{\\mathrm{AE}}=\\overline{\\mathrm{AB}}=2b$","$\\overline{\\mathrm{ED}}=3a-2b$","$\\overline{\\mathrm{EG}}=\\overline{\\mathrm{ED}}=3a-2b$"],"설명":"$\\mathrm{ABFE}$ 는 직사각형이고 $\\overline{\\mathrm{AB}}=\\overline{\\mathrm{BF}}$ 이므로 정사각형이다. 접은 변 $\\overline{\\mathrm{ED}}$ 와 $\\overline{\\mathrm{EG}}$ 는 길이가 같다.","확인":null,"스킬":"C7"},{"제목":"$\\overline{\\mathrm{HC}}$ 의 길이 구하기","힌트":"$\\overline{\\mathrm{ED}}$ 가 $\\overline{\\mathrm{EG}}$ 에 겹치도록 접으면 $\\overline{\\mathrm{DH}}$ 의 길이는?","식":["$\\mathrm{EDHG}$ 는 정사각형이므로 $\\overline{\\mathrm{DH}}=\\overline{\\mathrm{GH}}=\\overline{\\mathrm{ED}}=3a-2b$","$\\overline{\\mathrm{HC}}=\\overline{\\mathrm{DC}}-\\overline{\\mathrm{DH}}=2b-(3a-2b)=4b-3a$"],"설명":"$\\mathrm{EDHG}$ 는 직사각형이고 $\\overline{\\mathrm{ED}}=\\overline{\\mathrm{EG}}$ 이므로 정사각형이다. $3a<4b$ 이므로 $4b-3a>0$ 이다.","확인":null,"스킬":"C7"},{"제목":"$\\overline{\\mathrm{FJ}}$ 의 길이 구하기","힌트":"$\\overline{\\mathrm{HC}}$ 가 $\\overline{\\mathrm{HI}}$ 에 겹치도록 접으면 $\\overline{\\mathrm{GI}}$ 의 길이는?","식":["$\\overline{\\mathrm{HI}}=\\overline{\\mathrm{HC}}=4b-3a$","$\\overline{\\mathrm{GI}}=\\overline{\\mathrm{GH}}-\\overline{\\mathrm{HI}}=(3a-2b)-(4b-3a)=6a-6b$","$\\mathrm{GFJI}$ 는 직사각형이므로 $\\overline{\\mathrm{FJ}}=\\overline{\\mathrm{GI}}=6a-6b$"],"설명":"$\\overline{\\mathrm{GI}}$ 와 $\\overline{\\mathrm{FJ}}$ 는 직사각형 $\\mathrm{GFJI}$ 의 마주 보는 변이므로 길이가 같다.","확인":null,"스킬":"C7","고비":true},{"제목":"합차 공식으로 인수분해","힌트":"$(3a-2b)^{2}-(6a-6b)^{2}$ 을 합차 공식으로 인수분해하면?","식":["$\\{(3a-2b)+(6a-6b)\\}\\{(3a-2b)-(6a-6b)\\}$","$=(9a-8b)(-3a+4b)$"],"설명":"$X^{2}-Y^{2}=(X+Y)(X-Y)$ 에서 $X=3a-2b$, $Y=6a-6b$ 이다.","확인":null,"스킬":"A2"}]},"ns-ba9a59a01171":{"길":"두 원의 반지름의 차와 넓이식에 합차 공식을 써서 $R+r$ 를 구한 뒤 점선의 반지름으로 둘레를 구한다","단계":[{"제목":"산책로의 넓이식 세우기","힌트":"바깥 원의 반지름을 $R$, 안쪽 원의 반지름을 $r$ 라 할 때 산책로의 넓이는 어떻게 나타내는가?","식":["$R-r=3$","$\\pi R^{2}-\\pi r^{2}=198\\pi$"],"설명":"산책로는 두 원 사이의 부분이므로 바깥 원의 넓이에서 안쪽 원의 넓이를 뺀다.","확인":null,"스킬":"C7"},{"제목":"$R+r$ 의 값 구하기","힌트":"$\\pi(R^{2}-r^{2})=198\\pi$ 를 합차 공식으로 바꾸면?","식":["$R^{2}-r^{2}=(R+r)(R-r)=198$","$3(R+r)=198$","$R+r=66$"],"설명":"$R-r=3$ 을 합차 공식에 넣으면 $R$, $r$ 를 따로 구하지 않아도 $R+r$ 가 나온다.","확인":"66","스킬":"A2","고비":true},{"제목":"점선의 반지름 구하기","힌트":"점선은 폭의 한가운데를 지나므로 점선의 반지름은 $R$, $r$ 로 얼마인가?","식":["점선의 반지름 $=\\frac{R+r}{2}=33$"],"설명":"폭이 일정하므로 점선의 반지름은 두 반지름의 평균이다.","확인":"33","스킬":"C7"},{"제목":"점선의 길이 구하기","힌트":"반지름이 $33$ 인 원의 둘레는 얼마인가?","식":["$l=2\\pi\\times33=66\\pi$"],"설명":"반지름이 $r$ 인 원의 둘레는 $2\\pi r$ 이다.","확인":null,"스킬":"C7"}]}});
